function validate(_input) {
  return { valid: true };
}

function parseStdin() {
  return new Promise(resolve => {
    let input = '';
    let hasData = false;

    process.stdin.setEncoding('utf8');

    process.stdin.on('data', chunk => {
      hasData = true;
      input += chunk;
    });

    process.stdin.on('end', () => {
      if (!hasData || !input.trim()) {
        resolve(null);
        return;
      }

      try {
        resolve(JSON.parse(input));
      } catch (_e) {
        // Not JSON, treat as plain text summary
        resolve({ summary: input.trim() });
      }
    });

    process.stdin.on('error', () => {
      resolve(null);
    });

    // Timeout for stdin read
    setTimeout(() => {
      if (!hasData) {
        resolve(null);
      }
    }, 100);

    process.stdin.resume();
  });
}

async function gatherSessionInsights() {
  // Try to read from stdin first
  const stdinData = await parseStdin();
  if (stdinData) {
    return stdinData;
  }

  // Fallback: read from active_context.md if it exists
  const activeContextPath = path.join(
    PROJECT_ROOT,
    '.claude',
    'context',
    'memory',
    'active_context.md'
  );
  if (fs.existsSync(activeContextPath)) {
    try {
      const content = fs.readFileSync(activeContextPath, 'utf8');

      // Extract structured data from markdown if possible
      const insights = {
        summary: 'Session ended',
        tasks_completed: [],
        discoveries: [],
        files_modified: [],
      };

      // Simple extraction - look for lists
      const lines = content.split('\n');
      let currentSection = null;

      for (const line of lines) {
        const trimmed = line.trim();

        if (trimmed.match(/^##?\s+(tasks?|completed)/i)) {
          currentSection = 'tasks';
        } else if (trimmed.match(/^##?\s+(discover|found)/i)) {
          currentSection = 'discoveries';
        } else if (trimmed.match(/^##?\s+(files?|modified|changed)/i)) {
          currentSection = 'files';
        } else if (trimmed.startsWith('-') || trimmed.match(/^\d+\./)) {
          const item = trimmed
            .replace(/^[-*]\s*/, '')
            .replace(/^\d+\.\s*/, '')
            .trim();
          if (item && currentSection === 'tasks') {
            insights.tasks_completed.push(item);
          } else if (item && currentSection === 'discoveries') {
            insights.discoveries.push(item);
          } else if (item && currentSection === 'files') {
            insights.files_modified.push(item);
          }
        }
      }

      return insights;
    } catch (_err) {
      // Fall through to default
    }
  }

  // Default empty insights
  return {
    summary: 'Session ended',
    tasks_completed: [],
    discoveries: [],
    files_modified: [],
  };
}

async function main() {
  try {
    // Gather session insights
    const insights = await gatherSessionInsights();

    // Build session data structure matching saveSession() expectations
    const sessionData = {
      session_id: `session-${Date.now()}`,
      summary: insights.summary || 'Session ended',
      tasks_completed: insights.tasks_completed || [],
      files_modified: insights.files_modified || insights.filesModified || [],
      discoveries: insights.discoveries || [],
      patterns_found: insights.patterns_found || insights.patterns || [],
      gotchas_encountered: insights.gotchas_encountered || insights.gotchas || [],
      decisions_made: insights.decisions_made || insights.decisions || [],
      next_steps: insights.next_steps || insights.nextSteps || [],
      timestamp: new Date().toISOString(),
    };

    // Phase 2: Use memory tiers if available
    if (memoryTiers) {
      // Write to STM first
      memoryTiers.writeSTMEntry(sessionData, PROJECT_ROOT);

      // Consolidate STM -> MTM
      const consolidateResult = memoryTiers.consolidateSession(
        sessionData.session_id,
        PROJECT_ROOT
      );

      debugLog('session-end-recorder', `Consolidated session to MTM: ${consolidateResult.mtmPath}`);
    }

    // Legacy saveSession has been removed; memory-tiers is the canonical path.

    process.exit(0);
  } catch (err) {
    // Fail gracefully - session ends regardless
    debugLog('session-end-recorder', 'Session recording error', err);
    process.exit(0); // Non-blocking - session ends regardless
  }
}

function runTest(testFile) {
  return new Promise((resolve, reject) => {
    console.log(`\n▶ Running: ${path.basename(testFile)}`);
    console.log('─'.repeat(70));

    const proc = spawn('node', [testFile], {
      stdio: ['inherit', 'pipe', 'pipe'],
    });

    let output = '';
    let errorOutput = '';

    proc.stdout.on('data', data => {
      output += data.toString();
    });

    proc.stderr.on('data', data => {
      errorOutput += data.toString();
    });

    proc.on('close', code => {
      // Parse TAP output to get test counts
      const testMatch = output.match(/# tests (\d+)/);
      const passMatch = output.match(/# pass (\d+)/);
      const failMatch = output.match(/# fail (\d+)/);

      const tests = testMatch ? parseInt(testMatch[1]) : 0;
      const pass = passMatch ? parseInt(passMatch[1]) : 0;
      const fail = failMatch ? parseInt(failMatch[1]) : 0;

      totalTests += tests;
      totalPassed += pass;
      totalFailed += fail;

      if (code === 0) {
        console.log(`✓ PASSED: ${pass}/${tests} tests`);
      } else {
        console.log(`✗ FAILED: ${fail}/${tests} tests failed`);
        if (errorOutput) {
          console.log('\nError Output:');
          console.log(errorOutput);
        }
      }

      resolve(code === 0);
    });

    proc.on('error', err => {
      console.error(`✗ ERROR running test: ${err.message}`);
      reject(err);
    });
  });
}

async function runAllTests() {
  const startTime = Date.now();

  for (const testFile of testFiles) {
    try {
      await runTest(testFile);
      currentFile++;
    } catch (err) {
      console.error(`Failed to run ${testFile}:`, err);
      totalFailed++;
    }
  }

  const duration = ((Date.now() - startTime) / 1000).toFixed(2);

  console.log('\n' + '═'.repeat(70));
  console.log('                       FINAL RESULTS');
  console.log('═'.repeat(70));
  console.log(`Total Tests:    ${totalTests}`);
  console.log(`Passed:         ${totalPassed} ✓`);
  console.log(`Failed:         ${totalFailed} ✗`);
  console.log(`Duration:       ${duration}s`);
  console.log(`Success Rate:   ${((totalPassed / totalTests) * 100).toFixed(1)}%`);
  console.log('═'.repeat(70));

  if (totalFailed > 0) {
    console.log('\n⚠ Some tests failed. Review output above for details.\n');
    process.exit(1);
  } else {
    console.log('\n✓ All tests passed!\n');
    process.exit(0);
  }
}

class TaskToolMock {
  constructor() {
    this.spawnedAgents = [];
    this.taskList = new Map();
    this.taskIdCounter = 1;
    this.spawnDelay = 0; // Simulate spawn time
    this.failureMode = null; // { agentIndex: 0, error: "message" }
  }

  /**
   * Mock Task tool - spawn an agent
   */
  async spawn(config) {
    // Validate required fields
    if (!config.subagent_type) {
      throw new Error('subagent_type is required');
    }
    if (!config.description) {
      throw new Error('description is required');
    }
    if (!config.prompt) {
      throw new Error('prompt is required');
    }

    const taskId = `task-${this.taskIdCounter++}`;

    const agent = {
      id: taskId,
      type: config.subagent_type,
      model: config.model || 'sonnet',
      description: config.description,
      prompt: config.prompt,
      allowed_tools: config.allowed_tools || [],
      status: 'pending',
      spawnedAt: new Date().toISOString(),
      completedAt: null,
      result: null,
      error: null,
    };

    this.spawnedAgents.push(agent);
    this.taskList.set(taskId, agent);

    // Simulate spawn delay
    if (this.spawnDelay > 0) {
      await new Promise(resolve => setTimeout(resolve, this.spawnDelay));
    }

    // Simulate failure if configured
    const agentIndex = this.spawnedAgents.length - 1;
    if (this.failureMode && this.failureMode.agentIndex === agentIndex) {
      agent.status = 'failed';
      agent.error = this.failureMode.error;
      throw new Error(this.failureMode.error);
    }

    // Auto-complete agent (simulate successful execution)
    agent.status = 'running';

    return { taskId, agent };
  }

  /**
   * Mock TaskList
   */
  list() {
    return Array.from(this.taskList.values()).map(task => ({
      id: task.id,
      subject: task.description,
      status: task.status,
      owner: task.type,
      blockedBy: [],
    }));
  }

  /**
   * Mock TaskUpdate
   */
  update(taskId, updates) {
    const task = this.taskList.get(taskId);
    if (!task) {
      throw new Error(`Task ${taskId} not found`);
    }

    if (updates.status) {
      task.status = updates.status;
    }
    if (updates.metadata) {
      task.metadata = { ...task.metadata, ...updates.metadata };
    }

    if (updates.status === 'completed') {
      task.completedAt = new Date().toISOString();
    }

    return { success: true, taskId };
  }

  /**
   * Mock TaskGet
   */
  get(taskId) {
    const task = this.taskList.get(taskId);
    if (!task) {
      throw new Error(`Task ${taskId} not found`);
    }
    return task;
  }

  /**
   * Configure failure mode for testing error handling
   */
  setFailureMode(agentIndex, error) {
    this.failureMode = { agentIndex, error };
  }

  /**
   * Clear failure mode
   */
  clearFailureMode() {
    this.failureMode = null;
  }

  /**
   * Set spawn delay (ms) for timeout testing
   */
  setSpawnDelay(ms) {
    this.spawnDelay = ms;
  }

  /**
   * Reset mock state
   */
  reset() {
    this.spawnedAgents = [];
    this.taskList.clear();
    this.taskIdCounter = 1;
    this.spawnDelay = 0;
    this.failureMode = null;
  }

  /**
   * Get spawn history for assertions
   */
  getSpawnHistory() {
    return this.spawnedAgents;
  }

  /**
   * Get specific spawned agent
   */
  getSpawnedAgent(index) {
    return this.spawnedAgents[index];
  }

  /**
   * Count spawned agents by type
   */
  countByType(type) {
    return this.spawnedAgents.filter(a => a.type === type).length;
  }

  /**
   * Get all failed agents
   */
  getFailedAgents() {
    return this.spawnedAgents.filter(a => a.status === 'failed');
  }

