function isWorkflowComplete(text) {
  if (!text || typeof text !== 'string') return false;
  const lower = text.toLowerCase();
  return WORKFLOW_COMPLETE_MARKERS.some(marker => lower.includes(marker));
}

function extractLearnings(text) {
  if (!text || typeof text !== 'string') return [];

  const learnings = [];

  for (const pattern of LEARNING_PATTERNS) {
    let match;
    // Reset lastIndex for global patterns before starting
    pattern.lastIndex = 0;
    while ((match = pattern.exec(text)) !== null) {
      if (match[1] && match[1].length > 10 && match[1].length < 500) {
        learnings.push(match[1].trim());
      }
    }
    // Reset lastIndex for global patterns after finishing
    pattern.lastIndex = 0;
  }

  return [...new Set(learnings)]; // Remove duplicates
}

function appendLearnings(learnings, workflowName = 'Unknown Workflow') {
  if (!learnings || learnings.length === 0) return false;

  const timestamp = new Date().toISOString().split('T')[0];
  const entry = `\n## [${timestamp}] Auto-Extracted: ${workflowName}\n\n${learnings.map(l => `- ${l}`).join('\n')}\n`;

  try {
    // Ensure directory exists
    const dir = path.dirname(LEARNINGS_PATH);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    fs.appendFileSync(LEARNINGS_PATH, entry);
    return true;
  } catch (err) {
    debugLog('extract-workflow-learnings', 'Failed to append learnings', err);
    return false;
  }
}

function validate(context) {
  const { tool, result, parameters } = context || {};

  // Only process Task tool completions
  if (tool !== 'Task') {
    return { valid: true, error: '' };
  }

  const output = result?.output || '';

  // Check if workflow completed
  if (!isWorkflowComplete(output)) {
    return { valid: true, error: '' };
  }

  // Extract and save learnings
  const learnings = extractLearnings(output);
  if (learnings.length > 0) {
    const workflowName = parameters?.description || 'Workflow';
    appendLearnings(learnings, workflowName);
  }

  return { valid: true, error: '' };
}

function main() {
  try {
    // HOOK-001: Use shared hook-input utility instead of inline argv parsing
    const input = parseHookInputSync();

    if (!input) {
      process.exit(0);
    }

    // Validate and process
    const result = validate(input);

    // Output result for hook framework
    console.log(JSON.stringify(result));
    process.exit(0);
  } catch (err) {
    // For PostToolUse hooks, we fail open since the tool has already executed.
    // However, we still audit log the error for observability.
    auditLog('extract-workflow-learnings', 'error_post_tool', { error: err.message });

    // PostToolUse hooks should not block (tool already ran), so exit 0
    process.exit(0);
  }
}

 * @class BackgroundSyncWorker
 * @extends EventEmitter
 *
 * await worker.start();
 * // ... worker runs in background ...
 * await worker.stop();
 */
/**
 * @deprecated SyncLayer is deprecated; BackgroundSyncWorker is not used.
 * See .claude/lib/memory/sync-layer.cjs and .claude/hooks/memory/sync-memory-index.cjs.
 */
class BackgroundSyncWorker extends EventEmitter {
  /**
   * Create BackgroundSyncWorker instance
   *
   * @param {Object} config - Configuration options
   * @param {string} config.memoryDir - Directory containing memory files
   * @param {string} config.dbPath - Path to SQLite database
   * @param {number} config.intervalMs - Sync interval in milliseconds (default: 60000)
   */
  constructor(config = {}) {
    super();

    // Read interval from environment variable or config or default
    const envIntervalMs = process.env.MEMORY_SYNC_INTERVAL_MS
      ? parseInt(process.env.MEMORY_SYNC_INTERVAL_MS, 10)
      : null;

    // Config parameter takes precedence over env var
    const intervalMs = config.intervalMs !== undefined ? config.intervalMs : envIntervalMs || 60000;

    // Configuration
    this.config = {
      memoryDir: config.memoryDir,
      dbPath: config.dbPath,
      intervalMs,
    };

    // State
    this.running = false;
    this.intervalHandle = null;
    this.syncLayer = null;

    // Signal handlers for cleanup
    this.signalHandlers = {
      SIGINT: this._handleShutdown.bind(this),
      SIGTERM: this._handleShutdown.bind(this),
    };
  }

  /**
   * Start background worker
   *
   * Initializes SyncLayer, registers signal handlers, and starts periodic sync.
   *
   * @returns {Promise<void>}
   */
  async start() {
    if (this.running) {
      // Already running - idempotent
      return;
    }

    // Initialize SyncLayer
    this.syncLayer = new SyncLayer({
      memoryDir: this.config.memoryDir,
      dbPath: this.config.dbPath,
      debounceMs: 2000, // Use SyncLayer's default debounce
    });

    // Start watching files
    await this.syncLayer.start();

    // Register signal handlers for graceful shutdown
    process.on('SIGINT', this.signalHandlers.SIGINT);
    process.on('SIGTERM', this.signalHandlers.SIGTERM);

    // Start periodic sync
    this.intervalHandle = setInterval(() => {
      this._performSync();
    }, this.config.intervalMs);

    this.running = true;
  }

  /**
   * Stop background worker
   *
   * Cleans up interval timer, unregisters signal handlers, and stops SyncLayer.
   *
   * @returns {Promise<void>}
   */
  async stop() {
    if (!this.running) {
      // Not running - idempotent
      return;
    }

    // Stop interval timer
    if (this.intervalHandle) {
      clearInterval(this.intervalHandle);
      this.intervalHandle = null;
    }

    // Unregister signal handlers
    process.removeListener('SIGINT', this.signalHandlers.SIGINT);
    process.removeListener('SIGTERM', this.signalHandlers.SIGTERM);

    // Stop SyncLayer
    if (this.syncLayer) {
      await this.syncLayer.stop();
      this.syncLayer = null;
    }

    this.running = false;
  }

  /**
   * Check if worker is running
   *
   * @returns {boolean} True if running, false otherwise
   */
  isRunning() {
    return this.running;
  }

  /**
   * Perform periodic sync (internal)
   *
   * Emits 'periodic-sync' event with timestamp.
   *
   * @private
   */
  _performSync() {
    // Emit periodic-sync event
    this.emit('periodic-sync', {
      timestamp: Date.now(),
    });

    // NOTE: SyncLayer already watches files and syncs automatically.
    // This periodic sync is a heartbeat to ensure the system is alive.
    // Actual syncing happens in SyncLayer via file watchers.
  }

  /**
   * Handle shutdown signals (SIGINT, SIGTERM)
   *
   * Gracefully stops the worker on process termination.
   *
   * @private
   */
  async _handleShutdown() {
    console.log('[BackgroundSyncWorker] Received shutdown signal, stopping gracefully...');
    await this.stop();
    process.exit(0);
  }

class SyncLayer extends EventEmitter {
  /**
   * Create SyncLayer instance
   *
   * @param {Object} config - Configuration options
   * @param {string} config.memoryDir - Directory containing memory files (default: .claude/context/memory)
   * @param {string} config.dbPath - Path to SQLite database (default: .claude/data/memory.db)
   * @param {number} config.debounceMs - Debounce delay in milliseconds (default: 2000)
   */
  constructor(config = {}) {
    super();

    // Default configuration
    const projectRoot = path.resolve(__dirname, '../../../');
    this.config = {
      memoryDir: config.memoryDir || path.join(projectRoot, '.claude/context/memory'),
      dbPath: config.dbPath || path.join(projectRoot, '.claude/data/memory.db'),
      debounceMs: config.debounceMs !== undefined ? config.debounceMs : 2000,
    };

    // State
    this.watchers = new Map(); // filePath -> FSWatcher
    this.debounceTimers = new Map(); // filePath -> Timer
    this.watching = false;

    // Entity extractor
    this.extractor = null;
  }

  /**
   * Start watching memory files
   *
   * Monitors learnings.md, decisions.md, and issues.md for changes.
   * On change, debounces and triggers entity extraction + database sync.
   *
   * @returns {Promise<void>}
   */
  start() {
    if (this.watching) {
      // Already watching - idempotent
      return;
    }

    // Initialize entity extractor
    try {
      this.extractor = new EntityExtractor(this.config.dbPath);
    } catch (error) {
      console.error('[SyncLayer] Failed to initialize EntityExtractor:', error.message);
      // Continue without extractor (file watching still works)
    }

    // Ensure memory directory exists
    if (!fs.existsSync(this.config.memoryDir)) {
      fs.mkdirSync(this.config.memoryDir, { recursive: true });
    }

    // Files to watch
    const filesToWatch = ['learnings.md', 'decisions.md', 'issues.md'];

    // Start watching each file
    for (const filename of filesToWatch) {
      const filePath = path.join(this.config.memoryDir, filename);

      // Create file if it doesn't exist
      if (!fs.existsSync(filePath)) {
        fs.writeFileSync(filePath, `# ${filename}\n\nInitialized by SyncLayer\n`);
      }

      // Start watching
      const watcher = fs.watch(filePath, eventType => {
        if (eventType === 'change') {
          this._handleFileChange(filePath);
        }
      });

      this.watchers.set(filePath, watcher);
    }

    this.watching = true;
  }

  /**
   * Stop watching memory files
   *
   * Cleans up all file watchers and pending timers.
   *
   * @returns {Promise<void>}
   */
  stop() {
    // Stop all watchers
    for (const [_filePath, watcher] of this.watchers.entries()) {
      watcher.close();
    }
    this.watchers.clear();

    // Clear all debounce timers
    for (const [_filePath, timer] of this.debounceTimers.entries()) {
      clearTimeout(timer);
    }
    this.debounceTimers.clear();

    this.watching = false;

    // Close entity extractor
    if (this.extractor) {
      this.extractor.close();
      this.extractor = null;
    }
  }

  /**
   * Check if currently watching files
   *
   * @returns {boolean} True if watching, false otherwise
   */
  isWatching() {
    return this.watching;
  }

  /**
   * Handle file change event (debounced)
   *
   * @private
   * @param {string} filePath - Path to changed file
   */
  _handleFileChange(filePath) {
    // Emit sync event
    this.emit('sync', { filePath, timestamp: Date.now() });

    // Clear existing timer
    if (this.debounceTimers.has(filePath)) {
      clearTimeout(this.debounceTimers.get(filePath));
    }

    // Set new timer (debounce)
    const timer = setTimeout(async () => {
      await this._syncFile(filePath);
      this.debounceTimers.delete(filePath);
    }, this.config.debounceMs);

    this.debounceTimers.set(filePath, timer);
  }

  /**
   * Sync file changes to databases with retry logic
   *
   * Uses exponential backoff: 1s, 2s, 4s, 8s, 16s (max 5 retries)
   * Only retries transient errors (EBUSY, EAGAIN, ETIMEDOUT)
   * Does NOT retry permanent errors (ENOENT, syntax errors, etc.)
   *
   * @param {string} filePath - Path to changed file
   * @returns {Promise<void>}
   */
  async syncChanges(filePath) {
    try {
      // Wrap sync operation with retry logic
      await retryWithBackoff(
        async () => {
          // Step 1: Extract entities from file
          if (!this.extractor) {
            throw new Error('EntityExtractor not initialized');
          }

          const { entities, relationships } = await this.extractor.extractFromFile(filePath);

          this.emit('entities-extracted', { filePath, entities, relationships });

          // Step 2: Store entities in SQLite
          await this.extractor.storeEntities(entities);
          await this.extractor.storeRelationships(relationships);

          // Step 3: Update ChromaDB vectors (TODO: Implement in Task #27)
          // For now, just emit event
          this.emit('vectors-updated', { filePath, count: entities.length });

          // Step 4: Emit sync-complete event (MOVED inside retry for proper emission)
          this.emit('sync-complete', {
            filePath,
            entitiesCount: entities.length,
            relationshipsCount: relationships.length,
          });

          // Step 5: Return completion metadata
          return {
            entitiesCount: entities.length,
            relationshipsCount: relationships.length,
          };
        },
        {
          maxRetries: 5,
          baseDelay: 1000,
          onRetry: (error, attempt) => {
            console.warn(
              `[SyncLayer] Retry attempt ${attempt}/5 for ${filePath}: ${error.message}`
            );
          },
        }
      );
    } catch (error) {
      // Max retries exceeded or permanent error
      console.error('[SyncLayer] Sync failed:', error.message);
      this.emit('sync-error', {
        filePath,
        error: error.message,
        stack: error.stack,
      });
    }
  }

  /**
   * Sync file changes to databases (legacy method - no retry)
   *
   * @deprecated Use syncChanges() instead for retry logic
   * @private
   * @param {string} filePath - Path to changed file
   */
  async _syncFile(filePath) {
    try {
      // Step 1: Extract entities from file
      if (!this.extractor) {
        throw new Error('EntityExtractor not initialized');
      }

      const { entities, relationships } = await this.extractor.extractFromFile(filePath);

      this.emit('entities-extracted', { filePath, entities, relationships });

      // Step 2: Store entities in SQLite
      await this.extractor.storeEntities(entities);
      await this.extractor.storeRelationships(relationships);

      // Step 3: Update ChromaDB vectors (TODO: Implement in Task #27)
      // For now, just emit event
      this.emit('vectors-updated', { filePath, count: entities.length });

      // Step 4: Emit completion event
      this.emit('sync-complete', {
        filePath,
        entitiesCount: entities.length,
        relationshipsCount: relationships.length,
      });
    } catch (error) {
      // Emit error event
      this.emit('sync-error', {
        filePath,
        error: error.message,
        stack: error.stack,
      });
    }
  }

function getEnforcementMode() {
  return getEnfMode('CONFLICT_DETECTOR', 'block');
}

function extractArtifactName(filePath) {
  if (!filePath || typeof filePath !== 'string') {
    return null;
  }

  // Normalize path separators
  const normalizedPath = filePath.replace(/\\/g, '/');

  // Agent: .claude/agents/<category>/<name>.md
  const agentMatch = normalizedPath.match(/\.claude\/agents\/[^/]+\/([^/]+)\.md$/);
  if (agentMatch) {
    return agentMatch[1];
  }

  // Skill: .claude/skills/<name>/SKILL.md
  const skillMatch = normalizedPath.match(/\.claude\/skills\/([^/]+)\/SKILL\.md$/);
  if (skillMatch) {
    return skillMatch[1];
  }

  // Workflow: .claude/workflows/<category>/<name>.md
  const workflowMatch = normalizedPath.match(/\.claude\/workflows\/[^/]+\/([^/]+)\.md$/);
  if (workflowMatch) {
    return workflowMatch[1];
  }

  return null;
}

function extractArtifactCategory(filePath) {
  if (!filePath || typeof filePath !== 'string') {
    return null;
  }

  const normalizedPath = filePath.replace(/\\/g, '/');

  if (normalizedPath.includes('.claude/agents/')) {
    return 'agents';
  }
  if (normalizedPath.includes('.claude/skills/')) {
    return 'skills';
  }
  if (normalizedPath.includes('.claude/workflows/')) {
    return 'workflows';
  }

  return null;
}

function isValidArtifactName(name) {
  if (!name || typeof name !== 'string') {
    return false;
  }
  return NAME_PATTERN.test(name);
}

function collectArtifactNames(dir, names) {
  try {
    if (!fs.existsSync(dir)) {
      return;
    }

    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        // For skills, the directory name is the skill name
        if (dir.includes('skills') && fs.existsSync(path.join(fullPath, 'SKILL.md'))) {
          names.push(entry.name);
        }
        // Recurse into subdirectories
        collectArtifactNames(fullPath, names);
      } else if (entry.isFile() && entry.name.endsWith('.md')) {
        // For agents and workflows, extract name from filename
        const name = entry.name.replace(/\.md$/, '');
        if (name !== 'SKILL' && name !== 'README') {
          names.push(name);
        }
      }
    }
  } catch (_e) {
    // Ignore errors (permissions, etc.)
  }
}

function checkNameConflict(name, category) {
  if (!name || !category) {
    return { hasConflict: false, category: null, existingPath: null };
  }

  const categoryDir = path.join(PROJECT_ROOT, '.claude', category);

  // Collect all existing names in this category
  const existingNames = [];
  collectArtifactNames(categoryDir, existingNames);

  // Check for conflict
  if (existingNames.includes(name)) {
    return {
      hasConflict: true,
      category,
      existingPath: `${categoryDir}/**/${name}*`,
    };
  }

  return { hasConflict: false, category: null, existingPath: null };
}

function formatViolationMessage(name, category) {
  return `[NAMING CONFLICT] Artifact "${name}" already exists in ${category}.
Choose a unique name or enhance the existing artifact.
Run: Grep("${name}", ".claude/${category}/") to see existing artifact.`;
}

function formatNamingViolationMessage(name) {
  return `[NAMING CONVENTION VIOLATION] Invalid artifact name: "${name}"
Names must be kebab-case, lowercase, start with a letter: ^[a-z][a-z0-9-]*$
Examples: python-pro, mobile-ux-reviewer, c4-context`;
}

async function main() {
  try {
    // Check enforcement mode
    const enforcement = getEnforcementMode();
    if (enforcement === 'off') {
      process.exit(0);
    }

    // Parse the hook input using shared utility
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      // No input provided - fail open
      process.exit(0);
    }

    // PERF-006: Get the tool input using shared utilities
    const toolInput = getToolInput(hookInput);
    const filePath = extractFilePath(toolInput) || '';

    // Extract artifact name and category
    const name = extractArtifactName(filePath);
    const category = extractArtifactCategory(filePath);

    if (!name || !category) {
      // Not an artifact creation - allow
      process.exit(0);
    }

    // Check naming conventions
    if (!isValidArtifactName(name)) {
      const message = formatNamingViolationMessage(name);

      if (enforcement === 'block') {
        try {
          await eventBus.emit(EventTypes.TOOL_BLOCKED, {
            type: EventTypes.TOOL_BLOCKED,
            timestamp: new Date().toISOString(),
            toolName: 'Write',
            reason: 'artifact_name_invalid',
          });
        } catch (_err) {
          // Best-effort
        }
        console.log(JSON.stringify({ result: 'block', message }));
        process.exit(2);
      } else {
        console.log(JSON.stringify({ result: 'warn', message }));
        process.exit(0);
      }
    }

    // Check for naming conflicts
    const conflict = checkNameConflict(name, category);

    if (conflict.hasConflict) {
      const message = formatViolationMessage(name, category);

      if (enforcement === 'block') {
        try {
          await eventBus.emit(EventTypes.TOOL_BLOCKED, {
            type: EventTypes.TOOL_BLOCKED,
            timestamp: new Date().toISOString(),
            toolName: 'Write',
            reason: 'artifact_name_conflict',
          });
        } catch (_err) {
          // Best-effort
        }
        console.log(JSON.stringify({ result: 'block', message }));
        process.exit(2);
      } else {
        console.log(JSON.stringify({ result: 'warn', message }));
        process.exit(0);
      }
    }

    // No conflicts - allow
    process.exit(0);
  } catch (err) {
    // Fail open on errors to avoid blocking legitimate work
    if (process.env.DEBUG_HOOKS) {
      console.error('conflict-detector error:', err.message);
      console.error('Stack trace:', err.stack);
    }
    process.exit(0);
  }
}

function extractPatterns(output) {
  const patterns = [];

  // Look for pattern indicators
  const patternIndicators = [
    /(?:pattern|approach|solution|technique|best practice):\s*(.+)/gi,
    /(?:always|should|must|prefer)\s+(.{20,100})/gi,
    /(?:use|using)\s+(\w+)\s+(?:for|to|when)\s+(.{10,50})/gi,
  ];

  for (const regex of patternIndicators) {
    let match;
    while ((match = regex.exec(output)) !== null) {
      const patternText = match[1]?.trim();
      if (patternText && patternText.length > 10 && patternText.length < 200) {
        patterns.push(patternText);
      }
    }
  }

  return patterns.slice(0, 3); // Max 3 patterns per task
}

function extractGotchas(output) {
  const gotchas = [];

  // Look for gotcha indicators
  const gotchaIndicators = [
    /(?:gotcha|pitfall|warning|caution|watch out|careful):\s*(.+)/gi,
    /(?:don't|do not|never|avoid)\s+(.{20,100})/gi,
    /(?:bug|issue|problem):\s*(.{20,150})/gi,
    /(?:fixed|resolved)\s+(?:by|with)\s+(.{20,100})/gi,
  ];

  for (const regex of gotchaIndicators) {
    let match;
    while ((match = regex.exec(output)) !== null) {
      const gotchaText = match[1]?.trim();
      if (gotchaText && gotchaText.length > 10 && gotchaText.length < 200) {
        gotchas.push(gotchaText);
      }
    }
  }

  return gotchas.slice(0, 3); // Max 3 gotchas per task
}

function extractDiscoveries(output) {
  const discoveries = [];

  // Look for file path mentions with descriptions
  const filePatterns = [
    /`([^`]+\.[a-z]{2,4})`[:\s-]+(.{10,100})/gi,
    /(?:file|module|component)\s+`?([^\s`]+\.[a-z]{2,4})`?\s+(?:is|handles|contains|manages)\s+(.{10,80})/gi,
  ];

  for (const regex of filePatterns) {
    let match;
    while ((match = regex.exec(output)) !== null) {
      const filePath = match[1]?.trim();
      const description = match[2]?.trim();
      if (filePath && description && !filePath.includes(' ')) {
        discoveries.push({ path: filePath, description });
      }
    }
  }

  return discoveries.slice(0, 5); // Max 5 discoveries per task
}

async function main() {
  try {
    // Deprecated hook: do nothing unless explicitly enabled.
    // This prevents accidental re-wiring from causing double-counting or extra IO.
    const enabled =
      process.env.SESSION_MEMORY_EXTRACTOR_ENABLE === 'true' ||
      process.env.SESSION_MEMORY_EXTRACTOR_ENABLE === '1';
    if (!enabled) {
      if (process.env.DEBUG_HOOKS) {
        debugLog('session-memory-extractor', 'Deprecated hook skipped (not enabled)');
      }
      process.exit(0);
    }

    // PERF-006: Use shared utility
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      process.exit(0);
    }

    // PERF-006: Only process Task tool results using shared helper
    const toolName = getToolName(hookInput);
    if (toolName !== 'Task') {
      process.exit(0);
    }

    // PERF-006: Get the tool output/result using shared helper
    const toolOutput = getToolOutput(hookInput) || '';

    if (!toolOutput || typeof toolOutput !== 'string' || toolOutput.length < 50) {
      process.exit(0);
    }

    // Extract learnings
    const patterns = extractPatterns(toolOutput);
    const gotchas = extractGotchas(toolOutput);
    const discoveries = extractDiscoveries(toolOutput);

    // Record extracted items
    let recorded = 0;

    for (const pattern of patterns) {
      if (memoryManager.recordPattern(pattern, PROJECT_ROOT)) {
        recorded++;
      }
    }

    for (const gotcha of gotchas) {
      if (memoryManager.recordGotcha(gotcha, PROJECT_ROOT)) {
        recorded++;
      }
    }

    for (const discovery of discoveries) {
      if (
        memoryManager.recordDiscovery(
          discovery.path,
          discovery.description,
          'general',
          PROJECT_ROOT
        )
      ) {
        recorded++;
      }
    }

    // Log if we recorded anything (for debugging)
    if (recorded > 0) {
      debugLog('session-memory-extractor', `Recorded ${recorded} items from Task output`);
    }

    process.exit(0);
  } catch (err) {
    // Fail silently - memory extraction is non-critical
    debugLog('session-memory-extractor', 'Memory extraction error', err);
    process.exit(0);
  }
}

