function checkEvolutionStateTransition(currentState, hookInput) {
  const toolInput = getToolInput(hookInput);
  const filePath = extractFilePath(toolInput) || '';
  const normalizedPath = filePath.replace(/\\/g, '/');

  // Only check writes to evolution-state.json
  if (!normalizedPath.includes('evolution-state.json')) {
    return { block: false, warn: false, message: '' };
  }

  // Extract target state from content
  const content = toolInput.content || toolInput.new_string || '';
  const stateMatch = content.match(/"state"\s*:\s*"([^"]+)"/);
  if (!stateMatch) {
    return { block: false, warn: false, message: '' };
  }

  const targetState = stateMatch[1];
  const fromState = currentState?.state || 'idle';
  const validTargets = STATE_TRANSITIONS[fromState] || [];

  if (validTargets.includes(targetState)) {
    return { block: false, warn: false, message: '' };
  }

  return {
    block: true,
    warn: false,
    message: `[EVOLUTION STATE VIOLATION] Invalid state transition: ${fromState} -> ${targetState}
Valid transitions from ${fromState}: ${validTargets.join(', ') || 'none'}
Follow the EVOLVE workflow: E -> V -> O -> L -> V -> E`,
  };
}

function extractArtifactName(filePath) {
  if (!filePath) return null;
  const normalized = filePath.replace(/\\/g, '/');

  const agentMatch = normalized.match(/\.claude\/agents\/[^/]+\/([^/]+)\.md$/);
  if (agentMatch) return agentMatch[1];

  const skillMatch = normalized.match(/\.claude\/skills\/([^/]+)\/SKILL\.md$/);
  if (skillMatch) return skillMatch[1];

  const workflowMatch = normalized.match(/\.claude\/workflows\/[^/]+\/([^/]+)\.md$/);
  if (workflowMatch) return workflowMatch[1];

  return null;
}

function extractArtifactCategory(filePath) {
  if (!filePath) return null;
  const normalized = filePath.replace(/\\/g, '/');

  if (normalized.includes('.claude/agents/')) return 'agents';
  if (normalized.includes('.claude/skills/')) return 'skills';
  if (normalized.includes('.claude/workflows/')) return 'workflows';

  return null;
}

function collectArtifactNames(dir, names) {
  try {
    if (!fs.existsSync(dir)) return;
    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (dir.includes('skills') && fs.existsSync(path.join(fullPath, 'SKILL.md'))) {
          names.push(entry.name);
        }
        collectArtifactNames(fullPath, names);
      } else if (entry.isFile() && entry.name.endsWith('.md')) {
        const name = entry.name.replace(/\.md$/, '');
        if (name !== 'SKILL' && name !== 'README') {
          names.push(name);
        }
      }
    }
  } catch (_e) {
    // Ignore errors
  }
}

function checkConflicts(hookInput) {
  const toolInput = getToolInput(hookInput);
  const filePath = extractFilePath(toolInput) || '';

  const name = extractArtifactName(filePath);
  const category = extractArtifactCategory(filePath);

  if (!name || !category) {
    return { block: false, warn: false, message: '' };
  }

  // Check naming convention
  if (!NAME_PATTERN.test(name)) {
    return {
      block: true,
      warn: false,
      message: `[NAMING CONVENTION VIOLATION] Invalid artifact name: "${name}"
Names must be kebab-case, lowercase, start with a letter: ^[a-z][a-z0-9-]*$
Examples: python-pro, mobile-ux-reviewer, c4-context`,
    };
  }

  // Check for existing names
  const categoryDir = path.join(PROJECT_ROOT, '.claude', category);
  const existingNames = [];
  collectArtifactNames(categoryDir, existingNames);

  if (existingNames.includes(name)) {
    return {
      block: true,
      warn: false,
      message: `[NAMING CONFLICT] Artifact "${name}" already exists in ${category}.
Choose a unique name or enhance the existing artifact.
Run: Grep("${name}", ".claude/${category}/") to see existing artifact.`,
    };
  }

  return { block: false, warn: false, message: '' };
}

function detectArtifactType(filePath) {
  if (!filePath) return null;
  const normalized = filePath.replace(/\\/g, '/');

  if (/\.claude\/agents\//.test(normalized)) return 'agent';
  if (/\.claude\/skills\//.test(normalized)) return 'skill';
  if (/\.claude\/workflows\//.test(normalized)) return 'workflow';
  if (/\.claude\/hooks\//.test(normalized)) return 'hook';
  if (/\.claude\/schemas\//.test(normalized)) return 'schema';

  return null;
}

function isInVerifyPhase(state) {
  if (!state || !state.currentEvolution) return false;
  return state.state === 'verifying' || state.currentEvolution.phase === 'verify';
}

function findPlaceholders(content) {
  const issues = [];
  const lines = content.split('\n');

  lines.forEach((line, index) => {
    PLACEHOLDER_PATTERNS.forEach(pattern => {
      if (pattern.test(line)) {
        issues.push({
          pattern: pattern.source,
          line: index + 1,
          text: line.trim().substring(0, 80),
        });
      }
    });
  });

  return issues;
}

function findMissingSections(content, artifactType) {
  const missing = [];

  if (artifactType === 'agent') {
    REQUIRED_AGENT_SECTIONS.forEach(({ pattern, name }) => {
      if (!pattern.test(content)) missing.push(name);
    });
  } else if (artifactType === 'skill') {
    REQUIRED_SKILL_SECTIONS.forEach(({ pattern, name }) => {
      if (!pattern.test(content)) missing.push(name);
    });
  }

  return missing;
}

function checkQualityGates(currentState, hookInput) {
  const toolInput = getToolInput(hookInput);
  const filePath = extractFilePath(toolInput) || '';
  const content = toolInput.content || toolInput.new_string || '';

  const artifactType = detectArtifactType(filePath);
  if (!artifactType) {
    return { block: false, warn: false, message: '' };
  }

  // Only enforce during VERIFY phase
  if (!isInVerifyPhase(currentState)) {
    return { block: false, warn: false, message: '' };
  }

  const issues = [];

  // Check for placeholders
  const placeholders = findPlaceholders(content);
  if (placeholders.length > 0) {
    issues.push({
      type: 'placeholder',
      message: `Found ${placeholders.length} placeholder(s)`,
      details: placeholders.slice(0, 5),
    });
  }

  // Check for required sections
  const missingSections = findMissingSections(content, artifactType);
  if (missingSections.length > 0) {
    issues.push({
      type: 'missing_section',
      message: `Missing required section(s): ${missingSections.join(', ')}`,
      details: missingSections,
    });
  }

  // Check minimum content length
  if (content.length < 500) {
    issues.push({
      type: 'too_short',
      message: `Content too short (${content.length} chars, minimum 500)`,
    });
  }

  if (issues.length === 0) {
    return { block: false, warn: false, message: '' };
  }

  const issueDetails = issues.map(i => `  - ${i.message}`).join('\n');
  return {
    block: true,
    warn: false,
    message: `[EVOLUTION WORKFLOW VIOLATION] Artifact failed quality gate (VERIFY phase).
Quality issues found:
${issueDetails}

Fix these issues before proceeding to ENABLE phase.
Refer to: .claude/workflows/core/evolution-workflow.md Phase 5 (VERIFY)`,
  };
}

function isArtifactPath(filePath) {
  if (!filePath) return false;
  const normalized = filePath.replace(/\\/g, '/');
  return ARTIFACT_PATH_PATTERNS.some(pattern => pattern.test(normalized));
}

function checkResearchEnforcement(currentState, hookInput) {
  const toolInput = getToolInput(hookInput);
  const filePath = extractFilePath(toolInput) || '';

  if (!isArtifactPath(filePath)) {
    return { block: false, warn: false, message: '' };
  }

  const research = currentState?.currentEvolution?.research || [];
  const count = research.length;

  if (count >= MIN_RESEARCH_ENTRIES) {
    return { block: false, warn: false, message: '' };
  }

  return {
    block: true,
    warn: false,
    message: `[EVOLUTION WORKFLOW VIOLATION] Cannot create artifact without completing research.
Phase O (OBTAIN) requires minimum ${MIN_RESEARCH_ENTRIES} research entries. Current: ${count}.
Complete research phase first by invoking: Skill({ skill: "research-synthesis" })`,
  };
}

function runAllChecks(evolutionState, hookInput) {
  const results = [];
  const mainMode = getEnforcementMode();

  // Check 1: State transitions
  const stateMode = getCheckEnforcementMode('stateTransition', mainMode);
  if (stateMode !== 'off') {
    const result = checkEvolutionStateTransition(evolutionState, hookInput);
    if (result.block || result.warn) {
      results.push({ check: 'stateTransition', ...result });
    }
  }

  // Check 2: Naming conflicts
  const conflictMode = getCheckEnforcementMode('conflict', mainMode);
  if (conflictMode !== 'off') {
    const result = checkConflicts(hookInput);
    if (result.block || result.warn) {
      results.push({ check: 'conflict', ...result });
    }
  }

  // Check 3: Quality gates
  const qualityMode = getCheckEnforcementMode('qualityGate', mainMode);
  if (qualityMode !== 'off') {
    const result = checkQualityGates(evolutionState, hookInput);
    if (result.block || result.warn) {
      results.push({ check: 'qualityGate', ...result });
    }
  }

  // Check 4: Research enforcement
  const researchMode = getCheckEnforcementMode('research', mainMode);
  if (researchMode !== 'off') {
    const result = checkResearchEnforcement(evolutionState, hookInput);
    if (result.block || result.warn) {
      results.push({ check: 'research', ...result });
    }
  }

  return results;
}

async function main() {
  try {
    // Check main enforcement mode
    const enforcement = getEnforcementMode();
    if (enforcement === 'off') {
      process.exit(0);
    }

    // Parse hook input
    const hookInput = await parseHookInputAsync();
    if (!hookInput) {
      process.exit(0);
    }

    // Load evolution state once (PERF-002: single read instead of 4)
    const evolutionState = getEvolutionState();

    // Run all checks
    const results = runAllChecks(evolutionState, hookInput);

    // Find first blocking result
    const blockingResult = results.find(r => r.block);

    if (blockingResult) {
      if (enforcement === 'block') {
        try {
          await eventBus.emit(EventTypes.TOOL_BLOCKED, {
            type: EventTypes.TOOL_BLOCKED,
            timestamp: new Date().toISOString(),
            toolName: 'Write',
            reason: 'unified_evolution_blocked',
          });
        } catch (_err) {
          // Best-effort
        }
        console.log(JSON.stringify({ result: 'block', message: blockingResult.message }));
        process.exit(2);
      } else {
        console.log(JSON.stringify({ result: 'warn', message: blockingResult.message }));
        process.exit(0);
      }
    }

    // All checks passed
    process.exit(0);
  } catch (err) {
    // SEC-008: Fail closed on errors
    if (process.env.HOOK_FAIL_OPEN === 'true') {
      console.error(
        JSON.stringify({
          hook: 'unified-evolution-guard',
          event: 'fail_open_override',
          error: err.message,
        })
      );
      process.exit(0);
    }

    console.error(
      JSON.stringify({
        hook: 'unified-evolution-guard',
        event: 'error_fail_closed',
        error: err.message,
        timestamp: new Date().toISOString(),
      })
    );

    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'unified-evolution-guard',
        error: err.message,
      });
    } catch (_err) {
      // Best-effort
    }
    process.exit(2);
  }
}

function isMemoryFile(filePath) {
  if (!filePath) return false;

  const normalizedPath = path.normalize(filePath).replace(/\\/g, '/');

  return MEMORY_PATHS.some(memPath => {
    const fullMemPath = path.join(PROJECT_ROOT, memPath).replace(/\\/g, '/');
    return normalizedPath.startsWith(fullMemPath) || normalizedPath.includes(memPath);
  });
}

function isMarkdownFile(filePath) {
  return filePath && filePath.endsWith('.md');
}

function isPathSafe(filePath) {
  // Reject paths with dangerous characters that could enable injection
  // Allow: alphanumeric, hyphens, underscores, dots, colons (drive letters), slashes
  const safePattern = /^[a-zA-Z0-9_\-.\\/:\s]+$/;
  if (!safePattern.test(filePath)) {
    return false;
  }

  // Reject paths with shell metacharacters
  const dangerousChars = [
    '$',
    '`',
    '|',
    '&',
    ';',
    '(',
    ')',
    '<',
    '>',
    '!',
    '*',
    '?',
    '[',
    ']',
    '{',
    '}',
    '"',
    "'",
    '\n',
    '\r',
  ];
  return !dangerousChars.some(char => filePath.includes(char));
}

function formatFile(filePath) {
  // SEC-009 FIX: Validate file path before use
  if (!isPathSafe(filePath)) {
    debugLog('format-memory', 'Rejected unsafe file path', new Error(filePath));
    return false;
  }

  try {
    // SEC-009 FIX: Use spawnSync with array args instead of string interpolation
    // This prevents command injection via shell metacharacters
    const pnpmResult = spawnSync('pnpm', ['format', filePath], {
      cwd: PROJECT_ROOT,
      stdio: 'pipe',
      timeout: 10000,
      shell: false, // CRITICAL: Disable shell to prevent injection
    });

    if (pnpmResult.status === 0) {
      return true;
    }

    // pnpm format failed, try prettier directly
    const prettierResult = spawnSync('npx', ['prettier', '--write', filePath], {
      cwd: PROJECT_ROOT,
      stdio: 'pipe',
      timeout: 10000,
      shell: false, // CRITICAL: Disable shell to prevent injection
    });

    if (prettierResult.status === 0) {
      return true;
    }

    // Prettier also failed, skip formatting
    return false;
  } catch (_e) {
    return false;
  }
}

function main() {
  const startTime = Date.now();
  let output = null;
  // PERF-006: Use shared utility for parsing
  const input = parseHookInputSync();
  if (!input) {
    process.exit(0);
  }

  // PERF-006: Get tool info using shared utilities
  const toolName = getToolName(input);
  const toolInput = getToolInput(input);

  // Only process Edit/Write tools
  if (toolName !== 'Edit' && toolName !== 'Write') {
    process.exit(0);
  }

  // PERF-006: Get file path using shared utility
  const filePath = extractFilePath(toolInput);
  if (!filePath) {
    process.exit(0);
  }

  // Check if it's a memory markdown file
  if (!isMemoryFile(filePath) || !isMarkdownFile(filePath)) {
    process.exit(0);
  }

  // Format the file
  const formatted = formatFile(filePath);
  if (formatted) {
    const fileName = path.basename(filePath);
    auditLog('format-memory', 'formatted', { file: fileName });
  }
  output = {
    file: filePath,
    formatted,
    toolName,
  };

  try {
    // Best-effort: no await to avoid blocking hook execution
    eventBus.emit(EventTypes.TOOL_COMPLETED, {
      type: EventTypes.TOOL_COMPLETED,
      timestamp: new Date().toISOString(),
      toolName: 'format-memory',
      output,
      duration: Date.now() - startTime,
    });
  } catch (_e) {
    // Best-effort
  }

  if (!formatted) {
    try {
      eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'format-memory',
        error: 'formatting_failed',
      });
    } catch (_e) {
      // Best-effort
    }
  }

  process.exit(0);
}

function modelToTier(model) {
  if (!model) return 'sonnet';
  const m = model.toLowerCase();
  if (m.includes('haiku')) return 'haiku';
  if (m.includes('opus')) return 'opus';
  return 'sonnet';
}

function calculateCost(tier, inputTokens, outputTokens) {
  const pricing = PRICING[tier] || PRICING.sonnet;
  const inputCost = (inputTokens / 1000) * pricing.input;
  const outputCost = (outputTokens / 1000) * pricing.output;
  return inputCost + outputCost;
}

function validateCostEntry(entry) {
  const REQUIRED_FIELDS = ['timestamp', 'tier', 'inputTokens', 'outputTokens', 'cost'];

  // Check required fields
  for (const field of REQUIRED_FIELDS) {
    if (entry[field] === undefined) {
      return { valid: false, error: `SEC-CT-001: Missing required field: ${field}` };
    }
  }

  // Validate tier
  if (!['haiku', 'sonnet', 'opus'].includes(entry.tier)) {
    return { valid: false, error: 'SEC-CT-001: Invalid tier value' };
  }

  // Validate token counts
  if (typeof entry.inputTokens !== 'number' || entry.inputTokens < 0) {
    return { valid: false, error: 'SEC-CT-001: Invalid inputTokens' };
  }

  if (typeof entry.outputTokens !== 'number' || entry.outputTokens < 0) {
    return { valid: false, error: 'SEC-CT-001: Invalid outputTokens' };
  }

  // Validate cost is numeric
  const costNum = parseFloat(entry.cost);
  if (isNaN(costNum) || costNum < 0) {
    return { valid: false, error: 'SEC-CT-001: Invalid cost value' };
  }

  return { valid: true, error: null };
}

function calculateEntryHash(entry, previousHash) {
  const entryString = JSON.stringify(entry, Object.keys(entry).sort());
  const hashInput = previousHash + entryString;
  return crypto.createHash('sha256').update(hashInput).digest('hex').slice(0, 32);
}

function appendWithIntegrity(logPath, entry) {
  let previousHash = '0';

  // Get hash of last entry
  if (fs.existsSync(logPath)) {
    const content = fs.readFileSync(logPath, 'utf-8').trim();
    if (content) {
      const lines = content.split('\n');
      const lastLine = lines[lines.length - 1];
      try {
        const lastEntry = JSON.parse(lastLine);
        previousHash = lastEntry._hash || '0';
      } catch {
        previousHash = 'BROKEN_' + Date.now();
        console.warn('[SEC-CT-002] Log chain broken, starting new chain');
      }
    }
  }

  // Add integrity hash
  entry._hash = calculateEntryHash(entry, previousHash);
  entry._prevHash = previousHash;

  // Append to file
  fs.appendFileSync(logPath, JSON.stringify(entry) + '\n');

  return entry;
}

function verifyLogIntegrity(logPath) {
  if (!fs.existsSync(logPath)) {
    return { valid: true, brokenAt: null, reason: 'Log file does not exist' };
  }

  const content = fs.readFileSync(logPath, 'utf-8').trim();
  if (!content) {
    return { valid: true, brokenAt: null, reason: 'Log file is empty' };
  }

  const lines = content.split('\n');
  let previousHash = '0';

  for (let i = 0; i < lines.length; i++) {
    try {
      const entry = JSON.parse(lines[i]);

      // Verify previous hash reference
      if (entry._prevHash !== previousHash) {
        return {
          valid: false,
          brokenAt: i + 1,
          reason: `SEC-CT-002: Hash chain broken at line ${i + 1}`,
        };
      }

      // Verify entry hash
      const entryWithoutHash = { ...entry };
      delete entryWithoutHash._hash;
      delete entryWithoutHash._prevHash;

      const calculatedHash = calculateEntryHash(entryWithoutHash, previousHash);
      if (calculatedHash !== entry._hash) {
        return {
          valid: false,
          brokenAt: i + 1,
          reason: `SEC-CT-002: Entry hash mismatch at line ${i + 1}. Possible tampering detected.`,
        };
      }

      previousHash = entry._hash;
    } catch (e) {
      return {
        valid: false,
        brokenAt: i + 1,
        reason: `SEC-CT-002: Invalid JSON at line ${i + 1}: ${e.message}`,
      };
    }
  }

  return { valid: true, brokenAt: null, reason: 'Log integrity verified' };
}

function checkRateLimit() {
  const currentHour = Math.floor(Date.now() / (60 * 60 * 1000));

  // Reset counter if hour changed
  if (currentHour !== rateLimitState.hour) {
    rateLimitState.hour = currentHour;
    rateLimitState.entries = 0;
  }

  if (rateLimitState.entries >= RATE_LIMIT_PER_HOUR) {
    return false;
  }

  rateLimitState.entries++;
  return true;
}

function trackCall(params) {
  const tier = modelToTier(params.model);
  const cost = calculateCost(tier, params.inputTokens, params.outputTokens);

  // Update session state
  sessionCosts[tier].input += params.inputTokens;
  sessionCosts[tier].output += params.outputTokens;
  sessionCosts[tier].cost += cost;
  sessionCosts[tier].calls += 1;

  sessionCosts.total.input += params.inputTokens;
  sessionCosts.total.output += params.outputTokens;
  sessionCosts.total.cost += cost;
  sessionCosts.total.calls += 1;

  // Create log entry
  const entry = {
    timestamp: new Date().toISOString(),
    tier,
    inputTokens: params.inputTokens,
    outputTokens: params.outputTokens,
    cost: cost.toFixed(6),
    taskId: params.taskId || null,
    agent: params.agent || null,
  };

  // Validate entry (SEC-CT-001)
  const validation = validateCostEntry(entry);
  if (!validation.valid) {
    console.error(`[SEC-CT-001] ${validation.error}`);
    return;
  }

  // Check rate limit (SEC-CT-004)
  if (!checkRateLimit()) {
    console.warn('[SEC-CT-004] Rate limit exceeded: 1000 entries per hour');
    return;
  }

  // Ensure directory exists
  const dir = path.dirname(COST_LOG);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  // Append with integrity (SEC-CT-002)
  try {
    appendWithIntegrity(COST_LOG, entry);
  } catch (e) {
    console.error(`[SEC-CT-002] Failed to append cost log: ${e.message}`);
  }
}

function getSessionSummary() {
  const duration = (Date.now() - sessionStart) / 1000; // seconds

  return {
    duration: `${Math.floor(duration / 60)}m ${Math.floor(duration % 60)}s`,
    byTier: {
      haiku: {
        calls: sessionCosts.haiku.calls,
        tokens: sessionCosts.haiku.input + sessionCosts.haiku.output,
        cost: `$${sessionCosts.haiku.cost.toFixed(4)}`,
      },
      sonnet: {
        calls: sessionCosts.sonnet.calls,
        tokens: sessionCosts.sonnet.input + sessionCosts.sonnet.output,
        cost: `$${sessionCosts.sonnet.cost.toFixed(4)}`,
      },
      opus: {
        calls: sessionCosts.opus.calls,
        tokens: sessionCosts.opus.input + sessionCosts.opus.output,
        cost: `$${sessionCosts.opus.cost.toFixed(4)}`,
      },
    },
    total: {
      calls: sessionCosts.total.calls,
      inputTokens: sessionCosts.total.input,
      outputTokens: sessionCosts.total.output,
      totalTokens: sessionCosts.total.input + sessionCosts.total.output,
      cost: `$${sessionCosts.total.cost.toFixed(4)}`,
    },
  };
}

function formatSummary() {
  const summary = getSessionSummary();

  return `
## Session Cost Summary

**Duration**: ${summary.duration}

| Tier | Calls | Tokens | Cost |
|------|-------|--------|------|
| Haiku | ${summary.byTier.haiku.calls} | ${summary.byTier.haiku.tokens.toLocaleString()} | ${summary.byTier.haiku.cost} |
| Sonnet | ${summary.byTier.sonnet.calls} | ${summary.byTier.sonnet.tokens.toLocaleString()} | ${summary.byTier.sonnet.cost} |
| Opus | ${summary.byTier.opus.calls} | ${summary.byTier.opus.tokens.toLocaleString()} | ${summary.byTier.opus.cost} |
| **Total** | **${summary.total.calls}** | **${summary.total.totalTokens.toLocaleString()}** | **${summary.total.cost}** |
`;
}

function checkBudget(budget) {
  return sessionCosts.total.cost > budget;
}

function loadRunningTotals() {
  try {
    return JSON.parse(fs.readFileSync(COST_SUMMARY, 'utf-8'));
  } catch {
    return {
      allTime: { cost: 0, tokens: 0, sessions: 0 },
      lastSession: null,
    };
  }
}

function saveSummary() {
  const existing = loadRunningTotals();

  existing.lastSession = {
    timestamp: new Date().toISOString(),
    cost: sessionCosts.total.cost,
    tokens: sessionCosts.total.input + sessionCosts.total.output,
  };

  existing.allTime.cost += sessionCosts.total.cost;
  existing.allTime.tokens += sessionCosts.total.input + sessionCosts.total.output;
  existing.allTime.sessions += 1;

  // Ensure directory exists
  const dir = path.dirname(COST_SUMMARY);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  fs.writeFileSync(COST_SUMMARY, JSON.stringify(existing, null, 2));
}

function resetSession() {
  sessionCosts = {
    haiku: { input: 0, output: 0, cost: 0, calls: 0 },
    sonnet: { input: 0, output: 0, cost: 0, calls: 0 },
    opus: { input: 0, output: 0, cost: 0, calls: 0 },
    total: { input: 0, output: 0, cost: 0, calls: 0 },
  };
  sessionStart = Date.now();
}

function onSessionStart() {
  resetSession();
  console.log('[cost-tracking] Session started');
  return { exit: 0 };
}

function onSessionEnd() {
  if (sessionCosts.total.calls === 0) {
    console.log('[cost-tracking] No LLM calls in this session');
    return { exit: 0 };
  }

  console.log(formatSummary());
  saveSummary();

  return { exit: 0 };
}

function main(hookInput) {
  const { event } = hookInput;

  if (event === 'session-start') {
    return onSessionStart();
  } else if (event === 'session-end') {
    return onSessionEnd();
  }

  return { exit: 0 };
}

function isDetectionEnabled() {
  const mode = process.env.EVOLUTION_TRIGGER_DETECTION || 'on';
  return mode !== 'off';
}

function detectTriggers(text) {
  if (!text || typeof text !== 'string') {
    return [];
  }

  const triggers = [];

  EVOLUTION_TRIGGERS.forEach(({ pattern, type, priority }) => {
    const match = text.match(pattern);
    if (match) {
      triggers.push({
        pattern: pattern.source,
        type,
        priority,
        match: match[0],
        context: extractContext(text, match.index, 100),
      });
    }
  });

  return triggers;
}

function extractContext(text, index, radius) {
  const start = Math.max(0, index - radius);
  const end = Math.min(text.length, index + radius);
  let context = text.substring(start, end);

  if (start > 0) context = '...' + context;
  if (end < text.length) context = context + '...';

  return context.replace(/\n/g, ' ').trim();
}

function getEvolutionState() {
  // Default state if not found
  const defaultState = {
    version: '1.0.0',
    state: 'idle',
    currentEvolution: null,
    evolutions: [],
    patterns: [],
    suggestions: [],
    lastUpdated: new Date().toISOString(),
  };

  // PERF-004: Use cached state with 1s TTL
  return getCachedState(EVOLUTION_STATE_PATH, defaultState);
}

function addSuggestion(state, triggers) {
  // Don't add suggestions if evolution is in progress
  if (state.state !== 'idle') {
    return state;
  }

  const suggestion = {
    id: `sug-${Date.now()}`,
    detectedAt: new Date().toISOString(),
    triggers: triggers.map(t => ({
      type: t.type,
      priority: t.priority,
      match: t.match,
    })),
    status: 'pending',
  };

  // Avoid duplicate suggestions (same trigger types within 5 minutes)
  const recentSuggestions = state.suggestions.filter(s => {
    const age = Date.now() - new Date(s.detectedAt).getTime();
    return age < 5 * 60 * 1000; // 5 minutes
  });

  const isDuplicate = recentSuggestions.some(s => {
    const existingTypes = new Set(s.triggers.map(t => t.type));
    const newTypes = new Set(triggers.map(t => t.type));
    return [...newTypes].every(t => existingTypes.has(t));
  });

  if (isDuplicate) {
    return state;
  }

  // Add suggestion (keep last 10)
  state.suggestions = [...recentSuggestions, suggestion].slice(-10);
  state.lastUpdated = new Date().toISOString();

  return state;
}

function saveEvolutionState(state) {
  try {
    const dir = path.dirname(EVOLUTION_STATE_PATH);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    atomicWriteJSONSync(EVOLUTION_STATE_PATH, state);
    // PERF-004: Invalidate cache after writing to ensure consistency
    invalidateCache(EVOLUTION_STATE_PATH);
  } catch (e) {
    if (process.env.DEBUG_HOOKS) {
      console.error('Failed to save evolution state:', e.message);
    }
  }
}

async function main() {
  try {
    // Check if detection is enabled
    if (!isDetectionEnabled()) {
      process.exit(0);
    }

    // Parse the hook input using shared utility
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      // No input provided
      process.exit(0);
    }

    // Extract text to analyze from tool output or user message
    const toolOutput = hookInput.tool_output || hookInput.output || '';
    const userMessage = hookInput.user_message || hookInput.prompt || '';
    const textToAnalyze = `${userMessage} ${toolOutput}`.trim();

    if (!textToAnalyze) {
      process.exit(0);
    }

    // Detect evolution triggers
    const triggers = detectTriggers(textToAnalyze);

    if (triggers.length === 0) {
      // No triggers detected
      process.exit(0);
    }

    // Get current state and add suggestion
    const state = getEvolutionState();
    const updatedState = addSuggestion(state, triggers);

    // Save updated state
    if (updatedState !== state) {
      saveEvolutionState(updatedState);

      // Log detection for visibility (advisory)
      if (process.env.DEBUG_HOOKS) {
        console.log(
          JSON.stringify({
            result: 'detected',
            message: `Evolution trigger detected: ${triggers[0].match}`,
            triggers: triggers.length,
            suggestion_id: updatedState.suggestions[updatedState.suggestions.length - 1]?.id,
          })
        );
      }
    }

    // Always exit successfully (advisory hook)
    process.exit(0);
  } catch (err) {
    // Fail silently on errors (advisory hook)
    if (process.env.DEBUG_HOOKS) {
      console.error('evolution-trigger-detector error:', err.message);
      console.error('Stack trace:', err.stack);
    }
    process.exit(0);
  }
}

function getEnforcementMode() {
  return getEnfMode('QUALITY_GATE_ENFORCEMENT', 'block');
}

function detectArtifactType(filePath) {
  if (!filePath || typeof filePath !== 'string') {
    return null;
  }
  const normalized = filePath.replace(/\\/g, '/');

  if (/\.claude\/agents\//.test(normalized)) return 'agent';
  if (/\.claude\/skills\//.test(normalized)) return 'skill';
  if (/\.claude\/workflows\//.test(normalized)) return 'workflow';
  if (/\.claude\/hooks\//.test(normalized)) return 'hook';
  if (/\.claude\/schemas\//.test(normalized)) return 'schema';

  return null;
}

function getEvolutionState() {
  // PERF-004: Use cached state with 1s TTL
  return getCachedState(EVOLUTION_STATE_PATH, null);
}

function isInVerifyPhase(state) {
  if (!state || !state.currentEvolution) {
    return false;
  }
  return state.state === 'verifying' || state.currentEvolution.phase === 'verify';
}

function findPlaceholders(content) {
  const issues = [];
  const lines = content.split('\n');

  lines.forEach((line, index) => {
    PLACEHOLDER_PATTERNS.forEach(pattern => {
      if (pattern.test(line)) {
        issues.push({
          pattern: pattern.source,
          line: index + 1,
          text: line.trim().substring(0, 80),
        });
      }
    });
  });

  return issues;
}

function findMissingSections(content, artifactType) {
  const missing = [];

  if (artifactType === 'agent') {
    REQUIRED_AGENT_SECTIONS.forEach(({ pattern, name }) => {
      if (!pattern.test(content)) {
        missing.push(name);
      }
    });
  } else if (artifactType === 'skill') {
    REQUIRED_SKILL_SECTIONS.forEach(({ pattern, name }) => {
      if (!pattern.test(content)) {
        missing.push(name);
      }
    });
  }

  return missing;
}

function validateQuality(content, artifactType) {
  const issues = [];

  // Check for placeholders
  const placeholders = findPlaceholders(content);
  if (placeholders.length > 0) {
    issues.push({
      type: 'placeholder',
      message: `Found ${placeholders.length} placeholder(s)`,
      details: placeholders.slice(0, 5), // Limit to first 5
    });
  }

  // Check for required sections
  const missingSections = findMissingSections(content, artifactType);
  if (missingSections.length > 0) {
    issues.push({
      type: 'missing_section',
      message: `Missing required section(s): ${missingSections.join(', ')}`,
      details: missingSections,
    });
  }

  // Check minimum content length (avoid empty/stub artifacts)
  if (content.length < 500) {
    issues.push({
      type: 'too_short',
      message: `Content too short (${content.length} chars, minimum 500)`,
    });
  }

  return {
    valid: issues.length === 0,
    issues,
  };
}

function formatViolationMessage(issues) {
  const issueDetails = issues.map(i => `  - ${i.message}`).join('\n');
  return `[EVOLUTION WORKFLOW VIOLATION] Artifact failed quality gate (VERIFY phase).
Quality issues found:
${issueDetails}

Fix these issues before proceeding to ENABLE phase.
Refer to: .claude/workflows/core/evolution-workflow.md Phase 5 (VERIFY)`;
}

async function main() {
  try {
    // Check enforcement mode
    const enforcement = getEnforcementMode();
    if (enforcement === 'off') {
      process.exit(0);
    }

    // Parse the hook input using shared utility
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      // No input provided - fail open
      process.exit(0);
    }

    // PERF-006: Get the file path and content using shared utilities
    const toolInput = getToolInput(hookInput);
    const filePath = extractFilePath(toolInput) || '';
    const content = toolInput.content || toolInput.new_string || '';

    // Detect artifact type
    const artifactType = detectArtifactType(filePath);
    if (!artifactType) {
      // Not an artifact path - allow
      process.exit(0);
    }

    // Check if we're in VERIFY phase (only enforce during verification)
    const state = getEvolutionState();
    if (!isInVerifyPhase(state)) {
      // Not in verify phase - allow (LOCK phase creates initial content)
      process.exit(0);
    }

    // Validate quality
    const validation = validateQuality(content, artifactType);

    // If quality is good, allow
    if (validation.valid) {
      process.exit(0);
    }

    // Quality issues found - violation
    const message = formatViolationMessage(validation.issues);

    if (enforcement === 'block') {
      try {
        await eventBus.emit(EventTypes.TOOL_BLOCKED, {
          type: EventTypes.TOOL_BLOCKED,
          timestamp: new Date().toISOString(),
          toolName: 'Write',
          reason: 'quality_gate_failed',
        });
      } catch (_err) {
        // Best-effort
      }
      console.log(JSON.stringify({ result: 'block', message }));
      process.exit(2);
    } else {
      // Default to warn
      console.log(JSON.stringify({ result: 'warn', message }));
      process.exit(0);
    }
  } catch (err) {
    // Fail open on errors to avoid blocking legitimate work
    if (process.env.DEBUG_HOOKS) {
      console.error('quality-gate-validator error:', err.message);
      console.error('Stack trace:', err.stack);
    }
    process.exit(0);
  }
}

function shouldRunHealthCheck() {
  if (!Number.isFinite(HEALTH_CHECK_INTERVAL_MS) || HEALTH_CHECK_INTERVAL_MS <= 0) {
    return true;
  }
  try {
    if (!fs.existsSync(LAST_CHECK_PATH)) return true;
    const lastCheck = Number(fs.readFileSync(LAST_CHECK_PATH, 'utf8'));
    if (!Number.isFinite(lastCheck)) return true;
    return Date.now() - lastCheck > HEALTH_CHECK_INTERVAL_MS;
  } catch (_e) {
    return true;
  }
}

function recordHealthCheckTimestamp() {
  try {
    if (!fs.existsSync(RUNTIME_DIR)) {
      fs.mkdirSync(RUNTIME_DIR, { recursive: true });
    }
    fs.writeFileSync(LAST_CHECK_PATH, String(Date.now()));
  } catch (_e) {
    // best-effort; ignore
  }
}

