function buildOutput(health) {
  return {
    status: health.status,
    warnings: [...health.warnings],
    metrics: {
      learningsSizeKB: health.learningsSizeKB,
      decisionsSizeKB: health.decisionsSizeKB,
      codebaseMapEntries: health.codebaseMapEntries,
      sessionsCount: health.sessionsCount,
    },
    semanticStatus: null,
  };
}

async function attachSemanticStatus(output, memoryDashboard, projectRoot) {
  if (!memoryDashboard || typeof memoryDashboard.getLanceDBStatus !== 'function') {
    return;
  }
  try {
    const semanticStatus = await memoryDashboard.getLanceDBStatus(projectRoot);
    output.semanticStatus = semanticStatus;
    if (
      process.env.MEMORY_SEMANTIC_SEARCH !== 'off' &&
      semanticStatus &&
      semanticStatus.status === 'unavailable'
    ) {
      output.warnings.push(
        `Semantic search disabled: ${semanticStatus.reason || semanticStatus.status}`
      );
      if (output.status === 'healthy') {
        output.status = 'warning';
      }
    }
  } catch (_e) {
    // best-effort; don't fail hook
  }
}

function applyTierHealth(output, memoryTiers, projectRoot) {
  if (!memoryTiers) return;
  const tierHealth = memoryTiers.getTierHealth(projectRoot);
  output.tiers = {
    stm: tierHealth.stm,
    mtm: tierHealth.mtm,
    ltm: tierHealth.ltm,
  };

  if (tierHealth.mtm.warnings && tierHealth.mtm.warnings.length > 0) {
    output.warnings.push(...tierHealth.mtm.warnings);
    if (output.status === 'healthy') {
      output.status = 'warning';
    }
  }
}

function applyAutoRemediation(
  health,
  output,
  memoryTiers,
  smartPruner,
  projectRoot,
  memoryManager
) {
  const { checkAndArchiveLearnings, pruneCodebaseMap, getMemoryDir, CONFIG } = memoryManager;
  const autoActions = [];

  if (health.learningsSizeKB > CONFIG.LEARNINGS_ARCHIVE_THRESHOLD_KB) {
    const archiveResult = checkAndArchiveLearnings(projectRoot);
    if (archiveResult.archived) {
      autoActions.push(
        `Archived ${Math.round(archiveResult.archivedBytes / 1024)}KB of learnings.md`
      );
    }
  }

  if (health.codebaseMapEntries > CONFIG.CODEBASE_MAP_MAX_ENTRIES) {
    const pruneResult = pruneCodebaseMap(projectRoot);
    if (pruneResult.totalPruned > 0) {
      autoActions.push(`Pruned ${pruneResult.totalPruned} stale codebase_map entries`);
    }
  }

  if (
    memoryTiers &&
    output.tiers &&
    output.tiers.mtm.sessionCount >= memoryTiers.CONFIG.MTM_MAX_SESSIONS
  ) {
    const summarizeResult = memoryTiers.summarizeOldSessions(projectRoot);
    if (summarizeResult.summarized > 0) {
      autoActions.push(`Summarized ${summarizeResult.summarized} old MTM sessions to LTM`);
    }
  }

  if (smartPruner) {
    const memoryDir = getMemoryDir(projectRoot);

    const patternsPath = path.join(memoryDir, 'patterns.json');
    if (fs.existsSync(patternsPath)) {
      try {
        const patterns = JSON.parse(fs.readFileSync(patternsPath, 'utf8'));
        output.metrics.patternsCount = patterns.length;

        if (patterns.length > SMART_PRUNE_CONFIG.PATTERNS_WARN_COUNT) {
          output.warnings.push(
            `patterns.json has ${patterns.length} entries (threshold: ${SMART_PRUNE_CONFIG.PATTERNS_WARN_COUNT})`
          );
          output.status = 'warning';
        }

        if (patterns.length > SMART_PRUNE_CONFIG.PATTERNS_MAX_COUNT) {
          const result = smartPruner.deduplicateAndPrune(patterns, {
            targetCount: SMART_PRUNE_CONFIG.PATTERNS_MAX_COUNT,
            similarityThreshold: 0.4,
          });
          atomicWriteJSONSync(patternsPath, result.kept);
          if (result.deduplicated > 0 || result.removed.length > 0) {
            autoActions.push(
              `Smart-pruned patterns.json: ${result.deduplicated} deduped, ${result.removed.length} pruned`
            );
          }
        }
      } catch (e) {
        console.error(
          JSON.stringify({
            hook: 'memory-health-check',
            event: 'patterns_prune_error',
            error: e.message,
            timestamp: new Date().toISOString(),
          })
        );
      }
    }

    const gotchasPath = path.join(memoryDir, 'gotchas.json');
    if (fs.existsSync(gotchasPath)) {
      try {
        const gotchas = JSON.parse(fs.readFileSync(gotchasPath, 'utf8'));
        output.metrics.gotchasCount = gotchas.length;

        if (gotchas.length > SMART_PRUNE_CONFIG.GOTCHAS_WARN_COUNT) {
          output.warnings.push(
            `gotchas.json has ${gotchas.length} entries (threshold: ${SMART_PRUNE_CONFIG.GOTCHAS_WARN_COUNT})`
          );
          output.status = 'warning';
        }

        if (gotchas.length > SMART_PRUNE_CONFIG.GOTCHAS_MAX_COUNT) {
          const result = smartPruner.deduplicateAndPrune(gotchas, {
            targetCount: SMART_PRUNE_CONFIG.GOTCHAS_MAX_COUNT,
            similarityThreshold: 0.4,
          });
          atomicWriteJSONSync(gotchasPath, result.kept);
          if (result.deduplicated > 0 || result.removed.length > 0) {
            autoActions.push(
              `Smart-pruned gotchas.json: ${result.deduplicated} deduped, ${result.removed.length} pruned`
            );
          }
        }
      } catch (e) {
        console.error(
          JSON.stringify({
            hook: 'memory-health-check',
            event: 'gotchas_prune_error',
            error: e.message,
            timestamp: new Date().toISOString(),
          })
        );
      }
    }
  }

  return autoActions;
}

async function main() {
  const startTime = Date.now();
  stderrLog('hook_start');
  const memoryManagerPath = getMemoryManagerPath();
  const memoryTiersPath = getMemoryTiersPath();
  const smartPrunerPath = getSmartPrunerPath();

  if (!fs.existsSync(memoryManagerPath)) {
    // Memory manager not available - skip silently
    stderrLog('hook_end', { status: 'skipped', reason: 'memory_manager_missing' });
    process.exit(0);
  }

  if (!shouldRunHealthCheck()) {
    try {
      await eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'memory-health-check',
        output: { status: 'skipped', reason: 'rate-limit' },
        duration: Date.now() - startTime,
      });
    } catch (_e) {
      // Best-effort
    }
    stderrLog('hook_end', { status: 'skipped', reason: 'rate-limit' });
    process.exit(0);
  }

  const {
    getMemoryHealth,
    checkAndArchiveLearnings,
    pruneCodebaseMap,
    getMemoryDir,
    CONFIG,
  } = require(memoryManagerPath);

  const memoryTiers = loadOptionalModule(memoryTiersPath);
  const smartPruner = loadOptionalModule(smartPrunerPath);

  const memoryDashboardPath = getMemoryDashboardPath();
  const memoryDashboard = loadOptionalModule(memoryDashboardPath, 'memory dashboard');

  let output;
  let autoActions = [];
  try {
    const health = getMemoryHealth(PROJECT_ROOT);
    output = buildOutput(health);
    await attachSemanticStatus(output, memoryDashboard, PROJECT_ROOT);
    applyTierHealth(output, memoryTiers, PROJECT_ROOT);
    autoActions = applyAutoRemediation(health, output, memoryTiers, smartPruner, PROJECT_ROOT, {
      checkAndArchiveLearnings,
      pruneCodebaseMap,
      getMemoryDir,
      CONFIG,
    });
    output.autoActions = autoActions;
  } catch (err) {
    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'memory-health-check',
        error: err.message,
      });
    } catch (_e) {
      // Best-effort
    }
    stderrLog('hook_failed', { error: err?.message });
    throw err;
  }

  // Pending reflection requests (Router must perform Step 0 to process them)
  const reflectionSpawnPath = path.join(
    PROJECT_ROOT,
    '.claude',
    'context',
    'runtime',
    'reflection-spawn-request.json'
  );
  if (fs.existsSync(reflectionSpawnPath)) {
    try {
      const raw = fs.readFileSync(reflectionSpawnPath, 'utf8').trim();
      const arr = raw ? JSON.parse(raw) : [];
      if (Array.isArray(arr) && arr.length > 0) {
        output.pendingReflectionRequests = arr.length;
      }
    } catch (_e) {
      // ignore parse errors
    }
  }

  // Phase 4: Save metrics to history (resilient: try/catch, fallback JSONL)
  output.metricsLogged = false;
  const writeFallbackMetrics = errMsg => {
    try {
      const metricsDir = path.join(PROJECT_ROOT, '.claude', 'context', 'memory', 'metrics');
      if (!fs.existsSync(metricsDir)) {
        fs.mkdirSync(metricsDir, { recursive: true });
      }
      const fallbackPath = path.join(metricsDir, 'fallback.jsonl');
      const line =
        JSON.stringify({
          timestamp: new Date().toISOString(),
          event: 'health_check',
          status: output.status,
          warningsCount: (output.warnings && output.warnings.length) || 0,
          ...(errMsg ? { metricsError: errMsg } : {}),
        }) + '\n';
      fs.appendFileSync(fallbackPath, line);
    } catch (_e) {
      // ignore fallback write failure
    }
  };

  if (memoryDashboard) {
    try {
      const metrics = memoryDashboard.collectMetrics(PROJECT_ROOT);
      const metricsPath = memoryDashboard.saveMetrics(metrics, PROJECT_ROOT);
      memoryDashboard.cleanupOldMetrics(PROJECT_ROOT);
      output.metricsLogged = true;
      output.metricsPath = metricsPath;

      if (process.env.METRICS_DEBUG === 'true') {
        console.error(
          JSON.stringify({
            hook: 'memory-health-check',
            event: 'metrics_saved',
            metricsPath,
            timestamp: new Date().toISOString(),
          })
        );
      }
    } catch (e) {
      output.metricsError = e.message;
      console.error(
        JSON.stringify({
          hook: 'memory-health-check',
          event: 'metrics_logging_error',
          error: e.message,
          timestamp: new Date().toISOString(),
        })
      );
      writeFallbackMetrics(e.message);
    }
  } else {
    output.metricsError = 'dashboard not loaded';
    writeFallbackMetrics('dashboard not loaded');
  }

  // Format user-friendly message (stderr so host hook stdout stays empty)
  if (output.status === 'warning' || autoActions.length > 0) {
    console.error('[MEMORY HEALTH CHECK]');

    if (output.warnings.length > 0) {
      console.error('Warnings:');
      for (const warning of output.warnings) {
        console.error(`  - ${warning}`);
      }
    }

    if (autoActions.length > 0) {
      console.error('Auto-actions taken:');
      for (const action of autoActions) {
        console.error(`  - ${action}`);
      }
    }

    // Phase 2: Show tier metrics
    if (output.tiers && memoryTiers) {
      console.error('Memory Tiers:');
      console.error(`  - STM: ${output.tiers.stm.sessionCount} session(s)`);
      console.error(
        `  - MTM: ${output.tiers.mtm.sessionCount}/${memoryTiers.CONFIG.MTM_MAX_SESSIONS} sessions`
      );
      console.error(`  - LTM: ${output.tiers.ltm.summaryCount} summaries`);
    }

    console.error('');
  }

  // JSON result for programmatic access (stderr so host hook stdout stays empty)
  if (process.env.MEMORY_HEALTH_JSON) {
    console.error(JSON.stringify(output, null, 2));
  }

  recordHealthCheckTimestamp();

  try {
    await eventBus.emit(EventTypes.TOOL_COMPLETED, {
      type: EventTypes.TOOL_COMPLETED,
      timestamp: new Date().toISOString(),
      toolName: 'memory-health-check',
      output,
      duration: Date.now() - startTime,
    });
  } catch (_e) {
    // Best-effort
  }
  stderrLog('hook_end', {
    status: output.status,
    duration_ms: Date.now() - startTime,
  });

  process.exit(0);
}

function isTrackedPlanFile(filePath) {
  if (!filePath) return false;
  const normalized = path.normalize(filePath);
  const planDirNormalized = path.normalize(PLAN_DIR);
  if (!normalized.startsWith(planDirNormalized)) return false;
  const base = path.basename(normalized);
  return TRACKED_FILES.has(base);
}

function appendStamp(filePath) {
  try {
    if (!fs.existsSync(PLAN_DIR)) {
      fs.mkdirSync(PLAN_DIR, { recursive: true });
    }
    const base = path.basename(filePath);
    const line = `${new Date().toISOString()} ${base}\n`;
    fs.appendFileSync(STAMP_FILE, line, 'utf8');
  } catch (err) {
    debugLog('planning-progress-tracker', 'Failed to append update stamp', err);
  }
}

function handleHookInput(input) {
  if (!input) return;
  const toolName = getToolName(input);
  if (toolName !== 'Edit' && toolName !== 'Write' && toolName !== 'NotebookEdit') return;
  const toolInput = getToolInput(input);
  const filePath = extractFilePath(toolInput);
  if (!isTrackedPlanFile(filePath)) return;
  appendStamp(filePath);
}

function main() {
  const input = parseHookInputSync();
  if (!input) process.exit(0);
  handleHookInput(input);
  process.exit(0);
}

function checkLimits(agentId, state) {
  const elapsed = Date.now() - state.startTime;

  // Check turn limit
  if (state.limits.max_turns !== Infinity) {
    checkLimit(
      agentId,
      'max_turns',
      state.turns,
      state.limits.max_turns,
      state.limits.timeout_action,
      state.warnings
    );
  }

  // Check duration limit
  if (state.limits.max_duration_ms !== Infinity) {
    checkLimit(
      agentId,
      'max_duration_ms',
      elapsed,
      state.limits.max_duration_ms,
      state.limits.timeout_action,
      state.warnings
    );
  }

  // Check cost limit
  if (state.limits.max_cost_usd !== Infinity) {
    checkLimit(
      agentId,
      'max_cost_usd',
      state.cost,
      state.limits.max_cost_usd,
      state.limits.timeout_action,
      state.warnings
    );
  }
}

function checkLimit(agentId, limitType, current, max, timeoutAction, warnings) {
  const percentage = (current / max) * 100;

  // Emit warning at 80% threshold (once per limit type)
  if (percentage >= 80 && percentage < 100 && !warnings.has(`${limitType}_warning`)) {
    warnings.add(`${limitType}_warning`);
    emitWarning(agentId, limitType, current, max);
  }

  // Emit exceeded at 100% threshold (once per limit type)
  if (percentage >= 100 && !warnings.has(`${limitType}_exceeded`)) {
    warnings.add(`${limitType}_exceeded`);
    emitExceeded(agentId, limitType, current, max, timeoutAction);

    // Execute timeout action
    executeTimeoutAction(agentId, limitType, timeoutAction);
  }
}

function emitWarning(agentId, limitType, current, max) {
  if (!eventBus) return;

  const payload = {
    type: 'AGENT_LIMIT_WARNING',
    agentId,
    limitType,
    current,
    max,
    percentage: ((current / max) * 100).toFixed(1),
    timestamp: new Date().toISOString(),
  };

  eventBus.emit('AGENT_LIMIT_WARNING', payload);
}

function emitExceeded(agentId, limitType, current, max, action) {
  if (!eventBus) return;

  const payload = {
    type: 'AGENT_LIMIT_EXCEEDED',
    agentId,
    limitType,
    current,
    max,
    action,
    timestamp: new Date().toISOString(),
  };

  eventBus.emit('AGENT_LIMIT_EXCEEDED', payload);
}

function executeTimeoutAction(agentId, limitType, action) {
  switch (action) {
    case 'warn':
      // Log warning but continue execution
      console.warn(
        `[execution-limit-monitor] Agent ${agentId} exceeded ${limitType} (action: warn)`
      );
      break;

    case 'terminate':
      // Log error (actual termination would be handled by caller)
      console.error(`[execution-limit-monitor] Agent ${agentId} terminated: ${limitType} exceeded`);
      break;

    case 'pause':
      // Log pause (actual pause would be handled by caller)
      console.warn(
        `[execution-limit-monitor] Agent ${agentId} paused: ${limitType} exceeded (manual resume required)`
      );
      break;

    default:
      console.warn(`[execution-limit-monitor] Unknown timeout action: ${action}`);
  }
}

function getStatus(agentId) {
  const state = agents.get(agentId);
  if (!state) {
    return { turns: 0, elapsed: 0, cost: 0 };
  }

  return {
    turns: state.turns,
    elapsed: Date.now() - state.startTime,
    cost: state.cost,
    limits: state.limits,
  };
}

function stopMonitoring(agentId) {
  agents.delete(agentId);
}

function getActiveAgents() {
  return Array.from(agents.keys());
}

function clearAll() {
  agents.clear();
}

function getCoreMemoryFileType(absPath) {
  if (!absPath) return false;
  const normalized = path.normalize(absPath);
  const memDir = path.join(PROJECT_ROOT, '.claude', 'context', 'memory');
  if (!normalized.startsWith(memDir)) return false;
  const base = path.basename(normalized);
  if (CORE_MEMORY_MARKDOWN_FILES.has(base)) return 'markdown';
  if (CORE_MEMORY_JSON_FILES.has(base)) return 'json';
  return false;
}

function ensureEntityDbInitialized(dbPath) {
  try {
    const dbDir = path.dirname(dbPath);
    if (!fs.existsSync(dbDir)) {
      fs.mkdirSync(dbDir, { recursive: true });
    }

    // Lazily initialize schema if missing (idempotent).
    // This avoids the "EntityExtractor assumes schema exists" failure mode.
    const { DatabaseSync } = require('node:sqlite');
    const db = new DatabaseSync(dbPath);
    try {
      const row = db
        .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='schema_version'")
        .get();
      if (row) return;

      const init = require('../../tools/cli/init-memory-db.cjs');
      init.initializeDatabase(db);
    } finally {
      db.close();
    }
  } catch (err) {
    debugLog('sync-memory-index', 'Failed to initialize entity DB schema', err);
  }
}

function buildEntityId(prefix, text) {
  const hash = crypto.createHash('sha256').update(String(text)).digest('hex').slice(0, 16);
  return `${prefix}-${hash}`;
}

function clamp01(value) {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(1, value));
}

function qualityFromAccess(accessCount) {
  const count = Number.isFinite(accessCount) ? accessCount : 0;
  const max = 20;
  const ratio = Math.min(Math.log1p(count) / Math.log1p(max), 1);
  return clamp01(0.5 + ratio * 0.5);
}

function syncJsonMemory(absPath, dbPath) {
  const base = path.basename(absPath);
  const type = base === 'patterns.json' ? 'pattern' : 'issue';
  const raw = fs.readFileSync(absPath, 'utf8');
  let items = [];
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) items = parsed;
  } catch (_e) {
    return;
  }

  const { DatabaseSync } = require('node:sqlite');
  const db = new DatabaseSync(dbPath);
  db.exec('PRAGMA foreign_keys = ON');

  const insert = db.prepare(`
    INSERT OR REPLACE INTO entities (
      id, type, name, content, source_file, line_number,
      created_at, updated_at, last_accessed, access_count, quality_score
    )
    VALUES (?, ?, ?, ?, ?, ?, COALESCE(
      (SELECT created_at FROM entities WHERE id = ?),
      strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
    ), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), ?, ?, ?)
  `);

  const seenIds = new Set();
  for (const item of items) {
    const text = typeof item === 'string' ? item : item?.text;
    if (!text) continue;
    const content = typeof item === 'object' ? item?.content || null : null;
    const ts = item?.timestamp || null;
    const accessCount = Number.isFinite(item?.accessCount) ? item.accessCount : 0;
    const lastAccessed = item?.lastAccessed || null;
    const id = buildEntityId(type, text);
    seenIds.add(id);
    insert.run(
      id,
      type,
      text,
      content,
      absPath,
      null,
      id,
      lastAccessed,
      accessCount,
      qualityFromAccess(accessCount)
    );
    if (ts) {
      try {
        db.prepare('UPDATE entities SET created_at = ? WHERE id = ?').run(ts, id);
      } catch (_e) {
        // best-effort
      }
    }
  }

  if (seenIds.size > 0) {
    try {
      const placeholders = Array.from({ length: seenIds.size }).fill('?').join(', ');
      const params = Array.from(seenIds);
      db.prepare(
        `DELETE FROM entities WHERE source_file = ? AND type = ? AND id NOT IN (${placeholders})`
      ).run(absPath, type, ...params);
    } catch (_e) {
      // best-effort
    }
  }

  db.close();
}

function maybeGenerateEmbeddingsForFile(absPath) {
  if (process.env.MEMORY_EMBED_ON_EDIT !== 'on') return;
  if (!absPath) return;
  const basename = path.basename(absPath);
  if (!EMBEDDING_MEMORY_FILES.has(basename)) return;

  const generatorPath = path.join(
    PROJECT_ROOT,
    '.claude',
    'tools',
    'cli',
    'generate-embeddings.cjs'
  );
  if (!fs.existsSync(generatorPath)) return;

  const timeoutMs = Number(process.env.MEMORY_EMBED_ON_EDIT_TIMEOUT_MS || 60000);
  // REMEDIATION-FIX: Use non-blocking spawn to avoid hanging the hook
  const { spawn } = require('child_process');
  const child = spawn(process.execPath, [generatorPath, '--file', absPath], {
    cwd: PROJECT_ROOT,
    stdio: 'ignore',
    detached: true, // Allow child to run after parent exits
    timeout: timeoutMs,
  });
  child.unref(); // Don't wait for child

  if (process.env.DEBUG_HOOKS) {
    console.warn('[sync-memory-index] Embedding generation triggered in background for', basename);
  }
}

async function main() {
  const startTime = Date.now();
  let output = null;
  let toolName = null;
  let absPath = null;
  const hookInput = parseHookInputSync();
  if (!hookInput) process.exit(0);

  toolName = getToolName(hookInput);

  if (toolName === 'MemoryRecord') {
    const dbPath = path.join(PROJECT_ROOT, '.claude', 'data', 'memory.db');
    ensureEntityDbInitialized(dbPath);
    const memoryDir = path.join(PROJECT_ROOT, '.claude', 'context', 'memory');
    for (const fileName of CORE_MEMORY_JSON_FILES) {
      const targetPath = path.join(memoryDir, fileName);
      if (!fs.existsSync(targetPath)) continue;
      try {
        syncJsonMemory(targetPath, dbPath);
        maybeGenerateEmbeddingsForFile(targetPath);
      } catch (err) {
        debugLog('sync-memory-index', `Sync failed for ${fileName}`, err);
      }
    }

    try {
      await eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'sync-memory-index',
        output: {
          file: 'memory-record',
          fileType: 'json',
          toolName,
        },
        duration: Date.now() - startTime,
      });
    } catch (_e) {
      // Best-effort
    }

    process.exit(0);
  }

  const toolInput = getToolInput(hookInput);
  const filePath = extractFilePath(toolInput);

  if (!filePath) process.exit(0);

  const validated = validatePathWithinProject(filePath, PROJECT_ROOT);
  if (!validated.safe) {
    debugLog('sync-memory-index', `Blocked unsafe path: ${validated.reason}`, new Error(filePath));
    process.exit(0);
  }

  absPath = path.isAbsolute(filePath) ? filePath : path.join(PROJECT_ROOT, filePath);
  const fileType = getCoreMemoryFileType(absPath);
  if (!fileType) process.exit(0);
  // REMEDIATION-FIX: Allow JSON sync for all tools (e.g. manual edits by agents)
  // if (fileType === 'json' && toolName !== 'MemoryRecord' && !allowJsonHookSync) { ... }

  const dbPath = path.join(PROJECT_ROOT, '.claude', 'data', 'memory.db');
  ensureEntityDbInitialized(dbPath);

  try {
    if (fileType === 'json') {
      syncJsonMemory(absPath, dbPath);
      maybeGenerateEmbeddingsForFile(absPath);
    } else {
      const extractor = new EntityExtractor(dbPath);
      try {
        const { entities, relationships } = await extractor.extractFromFile(absPath);
        await extractor.storeEntities(entities || []);
        await extractor.storeRelationships(relationships || []);
        extractor.close();
      } catch (err) {
        extractor.close();
        debugLog('sync-memory-index', `Sync failed for ${path.basename(absPath)}`, err);
      }
      maybeGenerateEmbeddingsForFile(absPath);
    }
    output = {
      file: absPath,
      fileType,
      toolName,
    };
  } catch (err) {
    debugLog('sync-memory-index', `Failed to initialize extractor for ${toolName || 'tool'}`, err);
    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'sync-memory-index',
        error: err.message,
      });
    } catch (_e) {
      // Best-effort
    }
  }

  try {
    if (output) {
      await eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'sync-memory-index',
        output,
        duration: Date.now() - startTime,
      });
    }
  } catch (_e) {
    // Best-effort
  }
  // Best-effort / non-blocking.
  process.exit(0);
}

function coerceError(toolOutput) {
  if (!toolOutput) return null;

  // Structured output: { error: { message, name, stack? } }
  if (toolOutput && typeof toolOutput === 'object' && toolOutput.error) {
    const e = toolOutput.error;
    const message =
      (e && typeof e === 'object' && typeof e.message === 'string' && e.message) ||
      (typeof e === 'string' && e) ||
      'Unknown error';
    const err = new Error(message);
    if (e && typeof e === 'object') {
      if (typeof e.name === 'string') err.name = e.name;
      if (typeof e.stack === 'string') err.stack = e.stack;
    }
    return err;
  }

  // String output: heuristic (avoid spamming logs)
  if (typeof toolOutput === 'string') {
    const firstLine = toolOutput.split('\n')[0] || '';
    const looksLikeError =
      firstLine.startsWith('Error:') ||
      firstLine.startsWith('[ERROR]') ||
      firstLine.startsWith('ERROR:') ||
      firstLine.includes('Unhandled error') ||
      firstLine.includes('Unhandled exception');
    if (!looksLikeError) return null;
    return new Error(firstLine.slice(0, 500));
  }

  return null;
}

function main() {
  try {
    const hookInput = parseHookInputSync();
    if (!hookInput) process.exit(0);

    const tool = getToolName(hookInput) || 'unknown';
    const params = getToolInput(hookInput) || {};
    const toolOutput = getToolOutput(hookInput);

    const err = coerceError(toolOutput);
    errorTracker.postToolUse(tool, params, { error: err }, { sessionId: hookInput.session_id });
  } catch (_e) {
    // Monitoring must never block tool use
  } finally {
    process.exit(0);
  }
}

function ensureMetricsDir() {
  if (!fs.existsSync(METRICS_DIR)) {
    fs.mkdirSync(METRICS_DIR, { recursive: true });
  }
}

function checkRateLimit() {
  const currentHour = new Date().getHours();

  if (currentHour !== rateLimitState.hour) {
    rateLimitState.hour = currentHour;
    rateLimitState.count = 0;
  }

  if (rateLimitState.count >= RATE_LIMIT_PER_HOUR) {
    return false;
  }

  rateLimitState.count++;
  return true;
}

function determineSeverity(error, source) {
  // CRITICAL: Security violations
  if (source.includes('security') || error.message?.includes('SEC-')) {
    return 'CRITICAL';
  }

  // HIGH: Validation failures, routing errors
  if (source.includes('validation') || source.includes('routing')) {
    return 'HIGH';
  }

  // MEDIUM: Hook failures
  if (source.includes('hook')) {
    return 'MEDIUM';
  }

  // LOW: Other errors
  return 'LOW';
}

function classifyErrorType(error, source) {
  if (source.includes('security')) {
    return 'SecurityViolation';
  }

  if (source.includes('validation')) {
    return 'ValidationError';
  }

  if (source.includes('routing')) {
    return 'RoutingError';
  }

  if (error.name === 'TypeError' || error.name === 'ReferenceError') {
    return 'SystemError';
  }

  return 'UnknownError';
}

function logError(errorEntry) {
  try {
    if (!checkRateLimit()) {
      return;
    }

    ensureMetricsDir();

    appendJsonl(ERROR_METRICS_FILE, errorEntry, { maxLines: ERROR_METRICS_MAX_LINES });
  } catch (err) {
    console.error('[error-tracker] Failed to log error:', err.message);
  }
}

function postToolUse(tool, params, result, _context) {
  try {
    // Only track if there's an error
    if (!result.error) {
      return { tool, params, result };
    }

    // Get source from stack trace
    const stack = result.error.stack || new Error().stack || '';
    const sourceMatch = stack.match(/at\s+.*\/([\w-]+\.cjs)/);
    const source = sourceMatch ? sourceMatch[1] : 'unknown';

    // Create error entry
    const errorEntry = {
      timestamp: new Date().toISOString(),
      errorType: classifyErrorType(result.error, source),
      source,
      message: result.error.message || 'Unknown error',
      severity: determineSeverity(result.error, source),
      tool,
      metadata: {
        errorName: result.error.name,
        stack: result.error.stack?.split('\n').slice(0, 3).join('\n'), // First 3 lines only
        params: Object.keys(params || {}),
      },
    };

    // Log error
    logError(errorEntry);
  } catch (err) {
    console.error('[error-tracker] Error in postToolUse:', err.message);
  }

  return { tool, params, result };
}

function preToolUse(tool, params, _context) {
  // No errors to track yet in preToolUse
  // Errors caught by validation hooks will be tracked in postToolUse
  return { tool, params };
}

function main() {
  // Pass through stdin
  const input = fs.readFileSync(0, 'utf-8');

  for (const hook of HOOKS) {
    // Run hook synchronously
    const proc = spawnSync(process.execPath, [hook], {
      input,
      cwd: PROJECT_ROOT,
      env: process.env,
      stdio: ['pipe', 'inherit', 'inherit'], // pipe stdin, inherit stdout/stderr
    });

    if (proc.status !== 0) {
      console.error(`[PreToolUse] Hook failed: ${hook}`);
      process.exit(proc.status);
    }
  }
}

function readSpawnRequests(filePath) {
  try {
    if (!fs.existsSync(filePath)) return [];
    const content = fs.readFileSync(filePath, 'utf8');
    if (!content.trim()) return [];
    const parsed = JSON.parse(content);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    stderrLog('warn', 'Failed to read spawn requests', { error: err.message });
    return [];
  }
}

function hasPendingReflections() {
  // Check for reminder file
  if (fs.existsSync(REMINDER_PATH)) {
    stderrLog('info', 'Pending reflections detected: reminder file exists');
    return true;
  }

  // Check for spawn requests
  const requests = readSpawnRequests(SPAWN_REQUEST_PATH);
  if (requests.length > 0) {
    stderrLog('info', `Pending reflections detected: ${requests.length} spawn requests`);
    return true;
  }

  return false;
}

function logToSpawnLog(event) {
  try {
    const entry = JSON.stringify(event);
    fs.appendFileSync(SPAWN_LOG_PATH, entry + '\n', 'utf8');
  } catch (err) {
    stderrLog('warn', 'Failed to log to spawn-log.jsonl', { error: err.message });
  }
}

function main() {
  // Skip if reflection system is disabled
  if (process.env.REFLECTION_ENABLED === 'false') {
    stderrLog('info', 'Reflection system disabled, skipping Step 0 check');
    process.exit(0);
  }

  stderrLog('info', 'Checking for pending reflections (Step 0)');

  if (!hasPendingReflections()) {
    stderrLog('info', 'No pending reflections, proceeding with normal flow');
    process.exit(0);
  }

  // BLOCK: Pending reflections must be processed first
  const requestCount = readSpawnRequests(SPAWN_REQUEST_PATH).length;

  stderrLog('error', 'BLOCKING: Pending reflections must be processed before proceeding', {
    reminderFileExists: fs.existsSync(REMINDER_PATH),
    spawnRequestCount: requestCount,
  });

  logToSpawnLog({
    event: 'step0_block',
    timestamp: new Date().toISOString(),
    reason: 'pending_reflections',
    reminder_file_exists: fs.existsSync(REMINDER_PATH),
    spawn_request_count: requestCount,
    action: 'blocking_all_router_operations_until_reflections_processed',
  });

  // Exit with error to block the tool call
  console.log(
    JSON.stringify({
      block: true,
      message:
        `STEP 0 REQUIRED: ${requestCount} pending reflection request(s) detected. ` +
        'Read .claude/context/runtime/reflection-reminder.txt and ' +
        '.claude/context/runtime/reflection-spawn-request.json, spawn reflection-agent ' +
        'for each request (or first batch), then delete reminder file and clear spawn request file. ' +
        'See CLAUDE.md Section 0 for Step 0 protocol.',
    })
  );

  process.exit(1);
}

function syncSleep(ms) {
  if (typeof SharedArrayBuffer !== 'undefined' && typeof Atomics !== 'undefined') {
    try {
      const sharedBuffer = new SharedArrayBuffer(4);
      const int32 = new Int32Array(sharedBuffer);
      Atomics.wait(int32, 0, 0, ms);
      return;
    } catch (_e) {
      // fall back
    }
  }
  const start = Date.now();
  while (Date.now() - start < ms) {
    // busy wait
  }
}

function isProcessAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch (_err) {
    return false;
  }
}

function tryClaimStaleLock(lockFile) {
  const claimingFile = `${lockFile}.claiming.${process.pid}.${Date.now()}`;

  try {
    fs.renameSync(lockFile, claimingFile);
    try {
      const lockData = JSON.parse(fs.readFileSync(claimingFile, 'utf8'));
      if (lockData.pid && !isProcessAlive(lockData.pid)) {
        fs.unlinkSync(claimingFile);
        return true;
      }

      try {
        fs.renameSync(claimingFile, lockFile);
      } catch (_restoreErr) {
        try {
          fs.unlinkSync(claimingFile);
        } catch {
          // best effort
        }
      }
      return false;
    } catch (_readErr) {
      try {
        fs.unlinkSync(claimingFile);
      } catch {
        // best effort
      }
      return true;
    }
  } catch (_renameErr) {
    return false;
  }
}

function acquireLock(filePath) {
  const lockFile = filePath + LOCK_SUFFIX;
  const startTime = Date.now();

  while (Date.now() - startTime < MAX_LOCK_WAIT_MS) {
    try {
      fs.writeFileSync(lockFile, JSON.stringify({ pid: process.pid, time: Date.now() }), {
        flag: 'wx',
      });
      return true;
    } catch (e) {
      if (e.code === 'EEXIST') {
        if (tryClaimStaleLock(lockFile)) continue;
        syncSleep(LOCK_RETRY_MS);
        continue;
      }
      return false;
    }
  }
  return false;
}

function releaseLock(filePath) {
  const lockFile = filePath + LOCK_SUFFIX;
  try {
    fs.unlinkSync(lockFile);
  } catch {
    // ignore
  }
}

function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function readState() {
  const defaults = { updatedAt: new Date().toISOString(), sessions: {} };
  try {
    if (!fs.existsSync(STATE_FILE)) return defaults;
    const content = fs.readFileSync(STATE_FILE, 'utf8');
    const parsed = safeParseJSON(content, null);
    if (!parsed || typeof parsed !== 'object') return defaults;
    const sessions = parsed.sessions && typeof parsed.sessions === 'object' ? parsed.sessions : {};
    return { ...defaults, ...parsed, sessions };
  } catch {
    return defaults;
  }
}

function writeState(state) {
  const lockAcquired = acquireLock(STATE_FILE);
  try {
    ensureDir(path.dirname(STATE_FILE));
    atomicWriteJSONSync(STATE_FILE, { ...state, updatedAt: new Date().toISOString() });
  } finally {
    if (lockAcquired) releaseLock(STATE_FILE);
  }
}

function appendEvent(event) {
  try {
    ensureDir(METRICS_DIR);
    appendJsonl(EVENTS_FILE, event, { maxLines: EXECUTION_LIMIT_EVENTS_MAX_LINES });
  } catch {
    // best effort
  }
}

function normalizeLimits(raw) {
  if (!raw || typeof raw !== 'object') return null;

  const maxTurns =
    typeof raw.max_turns === 'number' && Number.isFinite(raw.max_turns) && raw.max_turns > 0
      ? Math.floor(raw.max_turns)
      : null;
  const maxDurationMs =
    typeof raw.max_duration_ms === 'number' &&
    Number.isFinite(raw.max_duration_ms) &&
    raw.max_duration_ms > 0
      ? Math.floor(raw.max_duration_ms)
      : null;
  const maxCostUsd =
    typeof raw.max_cost_usd === 'number' &&
    Number.isFinite(raw.max_cost_usd) &&
    raw.max_cost_usd > 0
      ? raw.max_cost_usd
      : null;

  const timeoutAction =
    raw.timeout_action === 'warn' ||
    raw.timeout_action === 'pause' ||
    raw.timeout_action === 'terminate'
      ? raw.timeout_action
      : 'terminate';

  return {
    max_turns: maxTurns ?? Infinity,
    max_duration_ms: maxDurationMs ?? Infinity,
    max_cost_usd: maxCostUsd ?? Infinity,
    timeout_action: timeoutAction,
  };
}

function getSessionId(hookInput) {
  const sid = hookInput && typeof hookInput.session_id === 'string' ? hookInput.session_id : null;
  return sid || process.env.CLAUDE_SESSION_ID || 'unknown-session';
}

function ensureSessionConfigured(state, sessionId, maybeLimits) {
  const existing = state.sessions[sessionId];

  if (maybeLimits) {
    const normalized = normalizeLimits(maybeLimits);
    if (!normalized) return;

    const nowIso = new Date().toISOString();
    state.sessions[sessionId] = {
      ...(existing && typeof existing === 'object' ? existing : {}),
      configuredAt: existing?.configuredAt || nowIso,
      startedAt: existing?.startedAt || nowIso,
      lastSeenAt: nowIso,
      turns: typeof existing?.turns === 'number' ? existing.turns : 0,
      costUsd: typeof existing?.costUsd === 'number' ? existing.costUsd : 0,
      limits: normalized,
      warningsEmitted: existing?.warningsEmitted || {},
      exceeded: existing?.exceeded || {},
    };

    appendEvent({
      timestamp: nowIso,
      type: 'EXECUTION_LIMITS_CONFIGURED',
      sessionId,
      limits: normalized,
    });
    return;
  }

  // Ensure minimal structure exists
  if (!existing) {
    const nowIso = new Date().toISOString();
    state.sessions[sessionId] = {
      configuredAt: null,
      startedAt: nowIso,
      lastSeenAt: nowIso,
      turns: 0,
      costUsd: 0,
      limits: null,
      warningsEmitted: {},
      exceeded: {},
    };
  }
}

function main() {
  try {
    const hookInput = parseHookInputSync();
    if (!hookInput) process.exit(0);

    const toolName = getToolName(hookInput);
    const toolInput = getToolInput(hookInput) || {};
    const sessionId = getSessionId(hookInput);

    const state = readState();

    // If this is a Task spawn and it provides execution_limits, store them.
    if (toolName === 'Task' && toolInput && toolInput.execution_limits) {
      ensureSessionConfigured(state, sessionId, toolInput.execution_limits);
      writeState(state);
      process.exit(0);
    }

    const session = state.sessions[sessionId];
    if (!session || !session.limits) {
      process.exit(0);
    }

    // Update per-call accounting
    const now = Date.now();
    const startedAtMs = session.startedAt ? new Date(session.startedAt).getTime() : now;
    const elapsedMs = now - startedAtMs;
    session.turns = typeof session.turns === 'number' ? session.turns + 1 : 1;
    session.lastSeenAt = new Date().toISOString();
    session.warningsEmitted = session.warningsEmitted || {};
    session.exceeded = session.exceeded || {};

    const {
      max_turns: maxTurns,
      max_duration_ms: maxDurationMs,
      timeout_action: timeoutAction,
    } = session.limits;

    // Warn at 80%
    if (maxTurns !== Infinity) {
      const pct = (session.turns / maxTurns) * 100;
      if (pct >= 80 && !session.warningsEmitted.max_turns) {
        session.warningsEmitted.max_turns = new Date().toISOString();
        appendEvent({
          timestamp: new Date().toISOString(),
          type: 'AGENT_LIMIT_WARNING',
          sessionId,
          limitType: 'max_turns',
          current: session.turns,
          max: maxTurns,
          percentage: pct.toFixed(1),
        });
      }
    }

    if (maxDurationMs !== Infinity) {
      const pct = (elapsedMs / maxDurationMs) * 100;
      if (pct >= 80 && !session.warningsEmitted.max_duration_ms) {
        session.warningsEmitted.max_duration_ms = new Date().toISOString();
        appendEvent({
          timestamp: new Date().toISOString(),
          type: 'AGENT_LIMIT_WARNING',
          sessionId,
          limitType: 'max_duration_ms',
          current: elapsedMs,
          max: maxDurationMs,
          percentage: pct.toFixed(1),
        });
      }
    }

    // Exceeded checks
    let exceeded = null;
    if (maxTurns !== Infinity && session.turns >= maxTurns) {
      exceeded = { limitType: 'max_turns', current: session.turns, max: maxTurns };
    } else if (maxDurationMs !== Infinity && elapsedMs >= maxDurationMs) {
      exceeded = { limitType: 'max_duration_ms', current: elapsedMs, max: maxDurationMs };
    }

    if (exceeded && !session.exceeded[exceeded.limitType]) {
      session.exceeded[exceeded.limitType] = new Date().toISOString();
      appendEvent({
        timestamp: new Date().toISOString(),
        type: 'AGENT_LIMIT_EXCEEDED',
        sessionId,
        action: timeoutAction,
        ...exceeded,
      });
    }

    state.sessions[sessionId] = session;
    writeState(state);

    if (!exceeded) {
      process.exit(0);
    }

    if (timeoutAction === 'warn') {
      process.exit(0);
    }

    const message = `[EXECUTION LIMIT] ${exceeded.limitType} exceeded (${exceeded.current}/${exceeded.max}). Action: ${timeoutAction}.

If this is expected, increase Task({ execution_limits: { ... } }) for this session.`;
    process.stdout.write(formatResult('block', message));
    try {
      eventBus.emit(EventTypes.TOOL_BLOCKED, {
        type: EventTypes.TOOL_BLOCKED,
        timestamp: new Date().toISOString(),
        toolName,
        reason: 'execution_limit_exceeded',
      });
    } catch (_err) {
      // Best-effort
    }
    process.exit(2);
  } catch (_e) {
    // Fail open: monitoring must not break tool usage
    process.exit(0);
  }
}

async function main() {
  const startedAt = Date.now();

  try {
    // FIX-RS-003: Use async parsing to read from stdin (where Claude Code sends hook input)
    const hookInput = await parseHookInputAsync();
    if (!hookInput) process.exit(0);

    const tool = getToolName(hookInput) || 'unknown';
    const params = getToolInput(hookInput) || {};
    const output = getToolOutput(hookInput);

    const result =
      output && typeof output === 'object' && !Array.isArray(output) ? output : { output };

    const context = {
      sessionId: hookInput.session_id,
      _metricsStartTime: startedAt,
    };

    metricsCollector.postToolUse(tool, params, result, context);
  } catch (_e) {
    // Monitoring must never block tool use
  } finally {
    process.exit(0);
  }
}

function ensureMetricsDir() {
  if (!fs.existsSync(METRICS_DIR)) {
    fs.mkdirSync(METRICS_DIR, { recursive: true });
  }
}

function checkRateLimit() {
  const currentHour = new Date().getHours();

  // Reset counter if hour changed
  if (currentHour !== rateLimitState.hour) {
    rateLimitState.hour = currentHour;
    rateLimitState.count = 0;
  }

  // Check limit
  if (rateLimitState.count >= RATE_LIMIT_PER_HOUR) {
    logger.warn(`Rate limit exceeded (${RATE_LIMIT_PER_HOUR}/hour)`);
    return false;
  }

  rateLimitState.count++;
  return true;
}

function validateMetric(metric) {
  if (!metric.timestamp || typeof metric.timestamp !== 'string') {
    throw new Error('Invalid metric: timestamp must be ISO 8601 string');
  }

  if (!metric.hook || typeof metric.hook !== 'string') {
    throw new Error('Invalid metric: hook must be string');
  }

  if (!metric.event || typeof metric.event !== 'string') {
    throw new Error('Invalid metric: event must be string');
  }

  if (typeof metric.executionTimeMs !== 'number' || metric.executionTimeMs < 0) {
    throw new Error('Invalid metric: executionTimeMs must be non-negative number');
  }

  if (!['success', 'failure'].includes(metric.status)) {
    throw new Error('Invalid metric: status must be "success" or "failure"');
  }

  return true;
}

function logMetric(metric) {
  try {
    // Check rate limit
    if (!checkRateLimit()) {
      return;
    }

    // Validate metric
    validateMetric(metric);

    // Ensure directory exists
    ensureMetricsDir();

    appendJsonl(HOOKS_METRICS_FILE, metric, { maxLines: HOOK_METRICS_MAX_LINES });
  } catch (error) {
    // Log error but don't throw (monitoring shouldn't break the system)
    const err = /** @type {Error} */ (error);
    logger.error('Failed to log metric', { error: err.message });
  }
}

function preToolUse(tool, params, context) {
  // Store start time
  context._metricsStartTime = Date.now();

  return { tool, params };
}

function postToolUse(tool, params, result, context) {
  try {
    // Calculate duration
    const startTime = context._metricsStartTime || Date.now();
    const executionTimeMs = Date.now() - startTime;

    // Determine status
    /** @type {'success'|'failure'} */
    const status = result.error ? 'failure' : 'success';

    // Get hook name from stack trace (if available)
    const stack = new Error().stack || '';
    const hookMatch = stack.match(/at\s+(\w+\.cjs)/);
    const hook = hookMatch ? hookMatch[1] : 'unknown';

    // Create metric entry
    const metric = {
      timestamp: new Date().toISOString(),
      hook,
      event: 'PostToolUse',
      tool,
      executionTimeMs: Math.round(executionTimeMs * 100) / 100, // Round to 2 decimals
      status,
      error: result.error
        ? result.error instanceof Error
          ? result.error.message
          : String(result.error)
        : undefined,
      metadata: {
        paramsSize: JSON.stringify(params).length,
        resultSize: JSON.stringify(result).length,
      },
    };

    // Log metric
    logMetric(metric);
  } catch (error) {
    // Silently fail - monitoring shouldn't break execution
    logger.error('Error in postToolUse', { error: error.message });
  }

  return { tool, params, result };
}

function sessionStart(context) {
  /** @type {Metric} */
  const metric = {
    timestamp: new Date().toISOString(),
    hook: 'metrics-collector.cjs',
    event: 'SessionStart',
    tool: 'N/A',
    executionTimeMs: 0,
    status: 'success',
    metadata: {
      sessionId: context.sessionId || 'unknown',
    },
  };

  logMetric(metric);

  return context;
}

function sessionEnd(context) {
  /** @type {Metric} */
  const metric = {
    timestamp: new Date().toISOString(),
    hook: 'metrics-collector.cjs',
    event: 'SessionEnd',
    tool: 'N/A',
    executionTimeMs: 0,
    status: 'success',
    metadata: {
      sessionId: context.sessionId || 'unknown',
      duration: context.sessionDuration || 'unknown',
    },
  };

  logMetric(metric);

  return context;
}

function setErrorReportsDir(dir) {
  ERROR_REPORTS_DIR = dir;
}

function setErrorSummariesDir(dir) {
  ERROR_SUMMARIES_DIR = dir;
}

function readErrorLogs(errorReportsDir = ERROR_REPORTS_DIR) {
  const errorsFile = path.join(errorReportsDir, 'errors.jsonl');

  if (!fs.existsSync(errorsFile)) {
    return [];
  }

  try {
    const content = fs.readFileSync(errorsFile, 'utf8');
    if (!content.trim()) {
      return [];
    }

    const lines = content.split('\n').filter(line => line.trim());
    const errors = [];

    for (const line of lines) {
      try {
        const error = JSON.parse(line);
        errors.push(error);
      } catch (_parseErr) {
        // Skip malformed JSON lines
        debugLog('error-summary-extractor', `Skipping malformed line: ${line.substring(0, 50)}`);
      }
    }

    return errors;
  } catch (err) {
    debugLog('error-summary-extractor', 'Error reading error logs', err);
    return [];
  }
}

function filterErrorsByTimeRange(errors, timeRangeMs = DEFAULT_TIME_RANGE_MS) {
  const cutoff = Date.now() - timeRangeMs;

  return errors.filter(error => {
    if (!error.timestamp) return false;
    const errorTime = new Date(error.timestamp).getTime();
    return errorTime >= cutoff;
  });
}

function aggregateByAgent(errors) {
  const counts = {};

  for (const error of errors) {
    const agentName = error.context?.agentName || 'unknown';
    counts[agentName] = (counts[agentName] || 0) + 1;
  }

  return counts;
}

function aggregateByCategory(errors) {
  const counts = {};

  for (const error of errors) {
    const category = error.category || 'UNKNOWN';
    counts[category] = (counts[category] || 0) + 1;
  }

  return counts;
}

function aggregateBySeverity(errors) {
  const counts = {};

  for (const error of errors) {
    const severity = error.severity || 'UNKNOWN';
    counts[severity] = (counts[severity] || 0) + 1;
  }

  return counts;
}

function generateSummary(errors) {
  const now = new Date();
  const dateStr = now.toISOString().split('T')[0];

  // Get critical errors
  const criticalErrors = errors.filter(e => e.severity === 'CRITICAL');

  // Detect patterns using pattern detector
  const patterns = patternDetector.detectPatterns(errors);
  const recommendations = patternDetector.generateRecommendations(patterns);

  return {
    date: dateStr,
    generatedAt: now.toISOString(),
    totalErrors: errors.length,
    bySeverity: aggregateBySeverity(errors),
    byCategory: aggregateByCategory(errors),
    byAgent: aggregateByAgent(errors),
    criticalErrors: criticalErrors.map(e => ({
      errorId: e.errorId,
      message: e.message,
      timestamp: e.timestamp,
      context: e.context,
    })),
    patterns,
    recommendations,
  };
}

function generateSummaryMarkdown(summary) {
  const lines = [];

  lines.push(`# Error Summary - ${summary.date}`);
  lines.push('');
  lines.push(`Generated: ${summary.generatedAt}`);
  lines.push(`Total Errors: ${summary.totalErrors}`);
  lines.push('');

  // Critical Issues
  if (summary.criticalErrors && summary.criticalErrors.length > 0) {
    lines.push(`## Critical Issues (${summary.criticalErrors.length})`);
    lines.push('');
    for (const error of summary.criticalErrors) {
      const context = error.context?.agentName ? `Agent: ${error.context.agentName}` : '';
      lines.push(`- **${error.errorId}**: ${error.message} ${context ? `(${context})` : ''}`);
    }
    lines.push('');
  }

  // Patterns Detected
  if (summary.patterns) {
    const { repeatedErrors, cascades } = summary.patterns;

    if (repeatedErrors && repeatedErrors.length > 0) {
      lines.push('## Pattern Detected: Repeated Errors');
      lines.push('');
      for (const pattern of repeatedErrors) {
        lines.push(`- **${pattern.count}x**: ${pattern.message?.substring(0, 60) || 'Unknown'}...`);
        if (pattern.lastSeen) {
          lines.push(`  - Last occurrence: ${pattern.lastSeen}`);
        }
      }
      lines.push('');
    }

    if (cascades && cascades.length > 0) {
      lines.push('## Pattern Detected: Error Cascades');
      lines.push('');
      for (const cascade of cascades) {
        lines.push(
          `- Root: ${cascade.rootErrorId} -> ${cascade.childErrorIds.length} child errors`
        );
      }
      lines.push('');
    }
  }

  // By Severity
  lines.push('## By Severity');
  lines.push('');
  for (const [severity, count] of Object.entries(summary.bySeverity || {})) {
    lines.push(`- ${severity}: ${count}`);
  }
  lines.push('');

  // By Category
  lines.push('## By Category');
  lines.push('');
  for (const [category, count] of Object.entries(summary.byCategory || {})) {
    lines.push(`- ${category}: ${count}`);
  }
  lines.push('');

  // By Agent
  lines.push('## By Agent');
  lines.push('');
  for (const [agent, count] of Object.entries(summary.byAgent || {})) {
    lines.push(`- ${agent}: ${count} errors`);
  }
  lines.push('');

  // Recommendations
  if (summary.recommendations && summary.recommendations.length > 0) {
    lines.push('## Recommendations');
    lines.push('');
    for (const rec of summary.recommendations) {
      lines.push(`### [${rec.priority}] ${rec.issue}`);
      lines.push(`- Suggestion: ${rec.suggestion}`);
      lines.push('');
    }
  }

  return lines.join('\n');
}

function saveSummary(summary, errorSummariesDir = ERROR_SUMMARIES_DIR) {
  // Ensure directory exists
  if (!fs.existsSync(errorSummariesDir)) {
    fs.mkdirSync(errorSummariesDir, { recursive: true });
  }

  const markdown = generateSummaryMarkdown(summary);
  const filePath = path.join(errorSummariesDir, `summary-${summary.date}.md`);

  fs.writeFileSync(filePath, markdown, 'utf8');

  return filePath;
}

function calculateReflectionWeight(summary) {
  let weight = 0;

  // Base weight from error count (max 0.4)
  const errorCountWeight = Math.min(summary.totalErrors / 50, 0.4);
  weight += errorCountWeight;

  // Severity weight (max 0.4)
  const severityCounts = summary.bySeverity || {};
  const criticalWeight = (severityCounts.CRITICAL || 0) * 0.15;
  const highWeight = (severityCounts.HIGH || 0) * 0.05;
  const mediumWeight = (severityCounts.MEDIUM || 0) * 0.02;
  weight += Math.min(criticalWeight + highWeight + mediumWeight, 0.4);

  // Pattern weight (max 0.2)
  const patterns = summary.patterns || {};
  const hasRepeated = (patterns.repeatedErrors || []).length > 0;
  const hasCascades = (patterns.cascades || []).length > 0;
  if (hasRepeated) weight += 0.1;
  if (hasCascades) weight += 0.1;

  return Math.min(weight, 1.0);
}

function generateActionItems(summary) {
  const items = [];

  // Critical errors need immediate attention
  if (summary.criticalErrors && summary.criticalErrors.length > 0) {
    items.push(`Review ${summary.criticalErrors.length} CRITICAL errors immediately`);
  }

  // Repeated errors suggest systemic issues
  const repeatedErrors = summary.patterns?.repeatedErrors || [];
  for (const repeated of repeatedErrors.slice(0, 3)) {
    items.push(
      `Investigate repeated error: "${repeated.message?.substring(0, 40)}..." (${repeated.count}x)`
    );
  }

  // Agent-specific issues
  const agentErrors = Object.entries(summary.byAgent || {})
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3);

  for (const [agent, count] of agentErrors) {
    if (count >= 5) {
      items.push(`Review agent "${agent}" for error patterns (${count} errors)`);
    }
  }

  // Hook failures
  const hookFailures = summary.patterns?.hookFailures || [];
  for (const hookFailure of hookFailures.slice(0, 2)) {
    items.push(`Fix hook "${hookFailure.hookName}" (${hookFailure.count} failures)`);
  }

  return items;
}

function getContextDir(queueFile = QUEUE_FILE) {
  return path.dirname(queueFile);
}

function getRuntimeDir(queueFile = QUEUE_FILE) {
  return path.join(getContextDir(queueFile), 'runtime');
}

function getSpawnRequestFile(queueFile = QUEUE_FILE) {
  return path.join(getRuntimeDir(queueFile), 'reflection-spawn-request.json');
}

function isEnabled() {
  // Check REFLECTION_ENABLED (default: true)
  if (process.env.REFLECTION_ENABLED === 'false') {
    return false;
  }

  // Check REFLECTION_HOOK_MODE (default: block, which means enabled)
  const mode = process.env.REFLECTION_HOOK_MODE || 'block';
  if (mode === 'off') {
    return false;
  }

  return true;
}

function readQueueEntries(queueFile) {
  try {
    if (!fs.existsSync(queueFile)) {
      return [];
    }

    const content = fs.readFileSync(queueFile, 'utf8');
    if (!content.trim()) {
      return [];
    }

    const lines = content.split('\n').filter(line => line.trim());
    const entries = [];

    for (const line of lines) {
      try {
        const entry = JSON.parse(line);
        // Skip entries already marked as processed
        if (!entry.processed) {
          entries.push(entry);
        }
      } catch (parseErr) {
        // Skip malformed JSON lines, log if debug enabled
        debugLog('reflection-queue-processor', 'Skipping malformed line in queue', parseErr);
      }
    }

    return entries;
  } catch (err) {
    debugLog('reflection-queue-processor', 'Error reading queue file', err);
    return [];
  }
}

function getPendingEntries(entries) {
  return entries.filter(entry => !entry.processed);
}

function generateSpawnInstruction(entry) {
  const _trigger = entry.trigger || 'unknown';
  const reason = buildReason(entry);
  const taskPrompt = buildTaskPrompt(entry);

  return `[REFLECTION-TRIGGER] Spawn reflection-agent for: ${reason}
Task({
  subagent_type: "reflection-agent",
  description: "Reflection: ${reason}",
  prompt: \`${taskPrompt}\`
})`;
}

function generateSpawnRequest(entry) {
  const reason = buildReason(entry);
  const taskPrompt = buildTaskPrompt(entry);
  const id = `${entry.trigger}:${entry.timestamp}:${entry.taskId || entry.context || ''}`;

  return {
    id,
    subagent_type: 'reflection-agent',
    description: `Reflection: ${reason}`,
    prompt: taskPrompt,
    source: {
      trigger: entry.trigger || 'unknown',
      timestamp: entry.timestamp || null,
      taskId: entry.taskId || null,
      context: entry.context || null,
      priority: entry.priority || 'medium',
    },
  };
}

function readExistingSpawnRequests(spawnRequestFile) {
  try {
    if (!fs.existsSync(spawnRequestFile)) {
      return [];
    }
    const content = fs.readFileSync(spawnRequestFile, 'utf8');
    if (!content.trim()) return [];
    const parsed = JSON.parse(content);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    debugLog('reflection-queue-processor', 'Error reading existing spawn requests', err);
    return [];
  }
}

function writeSpawnRequests(newRequests, queueFile = QUEUE_FILE) {
  if (!Array.isArray(newRequests) || newRequests.length === 0) {
    return { written: 0 };
  }

  try {
    const runtimeDir = getRuntimeDir(queueFile);
    if (!fs.existsSync(runtimeDir)) {
      fs.mkdirSync(runtimeDir, { recursive: true });
    }

    const spawnRequestFile = getSpawnRequestFile(queueFile);
    const existing = readExistingSpawnRequests(spawnRequestFile);
    const existingById = new Map(
      existing
        .filter(r => r && typeof r === 'object' && typeof r.id === 'string')
        .map(r => [r.id, r])
    );

    for (const req of newRequests) {
      if (!req || typeof req !== 'object' || typeof req.id !== 'string') continue;
      if (!existingById.has(req.id)) {
        existingById.set(req.id, req);
      }
    }

    const merged = Array.from(existingById.values());
    atomicWriteSync(spawnRequestFile, JSON.stringify(merged, null, 2));

    return { written: newRequests.length, total: merged.length, file: spawnRequestFile };
  } catch (err) {
    debugLog('reflection-queue-processor', 'Error writing spawn request file', err);
    return { written: 0 };
  }
}

function buildReason(entry) {
  switch (entry.trigger) {
    case 'task_completion':
      return `task ${entry.taskId || 'unknown'} completed`;
    case 'session_end':
      return 'session ended - batch reflection for unreflected tasks';
    case 'error':
      return `error in ${entry.tool || 'unknown tool'}: ${entry.error || 'unknown error'}`;
    default:
      return `${entry.trigger || 'unknown trigger'}`;
  }
}

function buildTaskPrompt(entry) {
  const trigger = entry.trigger || 'unknown';
  const timestamp = entry.timestamp || new Date().toISOString();
  const priority = entry.priority || 'medium';

  let context = '';
  switch (trigger) {
    case 'task_completion':
      context = `Analyze completed task ${entry.taskId || 'unknown'}.
${entry.summary ? `Summary: ${entry.summary}` : ''}`;
      break;
    case 'session_end':
      context = `Session ended. Perform batch reflection for all unreflected tasks.
${entry.stats ? `Stats: ${JSON.stringify(entry.stats)}` : ''}`;
      break;
    case 'error':
      context = `Error occurred during ${entry.tool || 'unknown'} execution.
Error: ${entry.error || 'unknown'}`;
      break;
    default:
      context = `Reflection triggered: ${trigger}`;
  }

  return `You are the REFLECTION-AGENT.

Trigger: ${trigger}
Timestamp: ${timestamp}
Priority: ${priority}

${context}

Instructions:
1. Read your agent definition: .claude/agents/core/reflection-agent.md
2. Analyze the context and extract learnings
3. Update memory files as appropriate
4. Document any patterns or issues discovered`;
}

function markEntriesProcessed(processedEntries, queueFile) {
  if (!processedEntries || processedEntries.length === 0) {
    return;
  }

  try {
    if (!fs.existsSync(queueFile)) {
      return;
    }

    const content = fs.readFileSync(queueFile, 'utf8');
    if (!content.trim()) {
      return;
    }

    const lines = content.split('\n').filter(line => line.trim());
    const updatedLines = [];

    // Create a set of processed entry identifiers for fast lookup
    const processedSet = new Set(
      processedEntries.map(e => `${e.trigger}:${e.timestamp}:${e.taskId || e.context || ''}`)
    );

    for (const line of lines) {
      try {
        const entry = JSON.parse(line);
        const identifier = `${entry.trigger}:${entry.timestamp}:${entry.taskId || entry.context || ''}`;

        if (processedSet.has(identifier)) {
          entry.processed = true;
        }

        updatedLines.push(JSON.stringify(entry));
      } catch (_parseErr) {
        // Keep malformed lines as-is
        updatedLines.push(line);
      }
    }

    // ATOMIC-001 FIX: Use atomicWriteSync utility for safe atomic writes
    // This handles temp file creation, writing, and atomic rename internally
    atomicWriteSync(queueFile, updatedLines.join('\n') + '\n');
  } catch (err) {
    debugLog('reflection-queue-processor', 'Error marking entries as processed', err);
  }
}

function processQueue(queueFile = QUEUE_FILE) {
  const result = {
    processed: 0,
    instructions: [],
    spawnRequests: [],
  };

  if (!isEnabled()) {
    return result;
  }

  const entries = readQueueEntries(queueFile);
  const pending = getPendingEntries(entries);

  if (pending.length === 0) {
    return result;
  }

  for (const entry of pending) {
    const instruction = generateSpawnInstruction(entry);
    result.instructions.push(instruction);
    result.spawnRequests.push(generateSpawnRequest(entry));
    result.processed++;
  }

  // Mark entries as processed
  markEntriesProcessed(pending, queueFile);
  trimJsonlFile(queueFile, REFLECTION_QUEUE_MAX_LINES);

  return result;
}

async function main() {
  const startTime = Date.now();
  try {
    // Check if enabled
    if (!isEnabled()) {
      process.exit(0);
    }

    // Process the queue
    const result = processQueue(QUEUE_FILE);

    // Write a machine-readable spawn request file so a follow-up Router turn can
    // actually call Task() for each request.
    const writeResult = writeSpawnRequests(result.spawnRequests);

    // Output spawn instructions to stderr for visibility
    if (result.instructions.length > 0) {
      for (const instruction of result.instructions) {
        console.error(instruction);
        console.error(''); // Blank line between instructions
      }

      const mode = process.env.REFLECTION_HOOK_MODE || 'block';
      if (mode === 'warn') {
        auditLog('reflection-queue-processor', 'processed', {
          count: result.processed,
          spawnRequestsWritten: writeResult.written || 0,
        });
      }
    }

    try {
      await eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'reflection-queue-processor',
        output: {
          processed: result.processed,
          spawnRequestsWritten: writeResult.written || 0,
          spawnRequestFile: writeResult.file || null,
        },
        duration: Date.now() - startTime,
      });
    } catch (_e) {
      // Best-effort
    }
    // Informational hook - always exit 0
    process.exit(0);
  } catch (err) {
    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'reflection-queue-processor',
        error: err.message,
      });
    } catch (_e) {
      // Best-effort
    }
    // Fail open - log error but don't block
    debugLog('reflection-queue-processor', 'Hook error during processing', err);
    process.exit(0);
  }
}

function readSpawnRequests(filePath) {
  try {
    if (!fs.existsSync(filePath)) return [];
    const content = fs.readFileSync(filePath, 'utf8');
    if (!content.trim()) return [];
    const parsed = JSON.parse(content);
    return Array.isArray(parsed) ? parsed : [];
  } catch (_err) {
    return [];
  }
}

function hasPendingReflections() {
  if (fs.existsSync(REMINDER_PATH)) {
    return true;
  }
  const requests = readSpawnRequests(SPAWN_REQUEST_PATH);
  return Array.isArray(requests) && requests.length > 0;
}

async function main() {
  const startTime = Date.now();
  try {
    if (process.env.REFLECTION_ENABLED === 'false') {
      process.exit(0);
    }

    const mode = getEnforcementMode('REFLECTION_STEP0_ENFORCEMENT', 'block');
    if (mode === 'off') {
      process.exit(0);
    }

    const hookInput = await parseHookInputAsync();
    if (!hookInput) {
      process.exit(0);
    }

    const toolName = getToolName(hookInput);
    if (toolName !== 'TaskList') {
      process.exit(0);
    }

    stderrLog('hook_start');

    if (!hasPendingReflections()) {
      stderrLog('hook_end', { status: 'no_pending' });
      process.exit(0);
    }

    const message =
      'Pending reflection requests exist. Perform Step 0 before TaskList: read ' +
      'reflection-reminder.txt, review reflection-spawn-request.json, spawn reflection-agent, then clear files. ' +
      'Set REFLECTION_STEP0_ENFORCEMENT=warn to soften enforcement.';

    auditLog('reflection-step0-guard', {
      level: mode === 'block' ? 'error' : 'warn',
      message: 'Reflection Step 0 pending before TaskList.',
      enforcement: mode,
    });

    if (mode === 'block') {
      stderrLog('hook_blocked', { reason: 'reflection_step0_pending' });
      try {
        await eventBus.emit(EventTypes.TOOL_BLOCKED, {
          type: EventTypes.TOOL_BLOCKED,
          timestamp: new Date().toISOString(),
          toolName: 'TaskList',
          duration: Date.now() - startTime,
          reason: 'reflection_step0_pending',
        });
      } catch (_e) {
        // Best-effort
      }
      console.log(formatResult('block', message));
      process.exit(2);
    }

    try {
      await eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'TaskList',
        output: {
          status: 'warn',
          reason: 'reflection_step0_pending',
        },
        duration: Date.now() - startTime,
      });
    } catch (_e) {
      // Best-effort
    }
    stderrLog('hook_end', { status: 'warn', reason: 'reflection_step0_pending' });
    console.log(formatResult('warn', message));
    process.exit(0);
  } catch (err) {
    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'reflection-step0-guard',
        error: err.message,
      });
    } catch (_e) {
      // Best-effort
    }
    stderrLog('hook_failed', { error: err?.message });
    if (process.env.DEBUG_HOOKS) {
      console.error('[reflection-step0-guard] Error:', err.message);
    }
    // Fail open: do not block TaskList if the guard itself fails.
    process.exit(0);
  }
}

function extractTaskDescription(toolInput) {
  if (!toolInput) return 'agent task';

  // Try to get description from various possible fields
  if (toolInput.description) return toolInput.description;
  if (toolInput.prompt) {
    // Extract first line or truncate
    const firstLine = toolInput.prompt.split('\n')[0];
    return firstLine.length > 100 ? firstLine.slice(0, 100) + '...' : firstLine;
  }
  if (toolInput.subagent_type) return `${toolInput.subagent_type} agent`;

  return 'agent task';
}

async function main() {
  try {
    const input = await parseHookInput();

    // PERF-006: Extract tool input using shared helper
    const toolInput = getToolInput(input);

    // Extract task description
    const taskDescription = extractTaskDescription(toolInput);

    // Set mode to agent BEFORE task starts
