      );
    }
  }
  // No queue entry for non-completion updates - just tracking
}

function handleErrorRecovery(input) {
  const toolName = getToolName(input);
  const toolInput = getToolInput(input);
  const toolResult = getToolOutput(input) || {};

  // Determine severity based on error type
  let severity = 'MEDIUM';
  if (toolResult.error?.includes('CRITICAL') || toolResult.error?.includes('SECURITY')) {
    severity = 'CRITICAL';
  } else if (
    toolResult.error?.includes('permission denied') ||
    toolResult.error?.includes('not found')
  ) {
    severity = 'HIGH';
  }

  // Determine priority based on severity
  const priority = severity === 'CRITICAL' ? 'high' : severity === 'HIGH' ? 'medium' : 'low';

  const entry = {
    context: 'error_recovery',
    trigger: 'error',
    tool: toolName,
    timestamp: new Date().toISOString(),
    priority,
    // Phase 4: Enhanced error context
    severity,
    category: toolName === 'Bash' ? 'TOOL_FAILURE' : 'EXECUTION_ERROR',
  };

  // Add Bash-specific fields
  if (toolName === 'Bash') {
    entry.command = toolInput.command;
    if (toolResult.stderr) {
      entry.error = toolResult.stderr;
    }
    if (typeof toolResult.exit_code === 'number') {
      entry.exitCode = toolResult.exit_code;
    }
  }

  // Add error from tool result
  if (toolResult.error) {
    entry.error =
      typeof toolResult.error === 'string' ? toolResult.error : JSON.stringify(toolResult.error);
  }

  // Include relevant tool input for context
  if (toolInput.file_path) {
    entry.filePath = toolInput.file_path;
  }

  // Add correlation IDs if available
  entry.correlation = {
    sessionId: process.env.CLAUDE_SESSION_ID,
    traceId: process.env.TRACE_ID,
  };

  return entry;
}

function getErrorSummaryForReflection() {
  if (!errorSummaryExtractor) {
    return null;
  }

  try {
    const result = errorSummaryExtractor.extractSummaryForReflection({ hours: 24 });

    // Only include if there are errors to review
    if (result.errorCount === 0) {
      return null;
    }

    return {
      errorCount: result.errorCount,
      summaryPath: result.summaryPath,
      reflectionWeight: result.reflectionWeight,
      actionItems: result.actionItems,
      criticalIssues: result.summary?.criticalErrors?.length || 0,
      patterns: {
        repeated: result.summary?.patterns?.repeatedErrors?.length || 0,
        cascades: result.summary?.patterns?.cascades?.length || 0,
      },
    };
  } catch (err) {
    debugLog('unified-reflection', 'Error getting error summary for reflection', err);
    return null;
  }
}

function handleSessionEnd(input) {
  const sessionId = input.session_id || input.sessionId || process.env.CLAUDE_SESSION_ID;
  const stats = getSessionStats(input);
  const insights = gatherSessionInsights(input);
  const toolsUsed = Array.isArray(input?.tools_used)
    ? input.tools_used
    : Array.isArray(input?.stats?.tool_names)
      ? input.stats.tool_names
      : [];

  // Phase 4 Integration: Get error summary for reflection
  const errorSummary = getErrorSummaryForReflection();

  // Determine reflection priority based on error summary
  let reflectionPriority = 'low';
  if (errorSummary) {
    if (errorSummary.criticalIssues > 0 || errorSummary.reflectionWeight >= 0.7) {
      reflectionPriority = 'high';
    } else if (errorSummary.reflectionWeight >= 0.4) {
      reflectionPriority = 'medium';
    }
  }

  // Create reflection entry
  const reflection = {
    context: 'session_end',
    trigger: 'session_end',
    sessionId: sessionId,
    scope: 'all_unreflected_tasks',
    timestamp: new Date().toISOString(),
    priority: reflectionPriority,
    stats: stats,
    // Phase 4: Include error review context
    errorReview: errorSummary,
  };

  // Create session data for memory recording (formerly from session-end-recorder.cjs)
  const sessionData = {
    session_id: sessionId || `session-${Date.now()}`,
    summary: insights.summary || 'Session ended',
    tasks_completed: insights.tasks_completed || [],
    files_modified: insights.files_modified || insights.filesModified || [],
    discoveries: insights.discoveries || [],
    patterns_found: insights.patterns_found || insights.patterns || [],
    gotchas_encountered: insights.gotchas_encountered || insights.gotchas || [],
    decisions_made: insights.decisions_made || insights.decisions || [],
    next_steps: insights.next_steps || insights.nextSteps || [],
    tools_used: toolsUsed,
    timestamp: new Date().toISOString(),
  };

  return {
    reflection,
    sessionData,
  };
}

function getSessionStats(input) {
  const stats = input.stats || {};

  return {
    toolCalls: stats.tool_calls || 0,
    errors: stats.errors || 0,
    tasksCompleted: stats.tasks_completed || 0,
  };
}

function handleMemoryExtraction(input) {
  const toolResult = getToolOutput(input) || '';
  const output = typeof toolResult === 'string' ? toolResult : '';

  return {
    patterns: extractPatterns(output),
    gotchas: extractGotchas(output),
    discoveries: extractDiscoveries(output),
  };
}

function extractPatterns(output) {
  const patterns = [];

  // Look for pattern indicators
  const patternIndicators = [
    /(?:pattern|approach|solution|technique|best practice):\s*(.+)/gi,
    /(?:always|should|must|prefer)\s+(.{20,100})/gi,
    /(?:use|using)\s+(\w+)\s+(?:for|to|when)\s+(.{10,50})/gi,
  ];

  for (const regex of patternIndicators) {
    let match;
    while ((match = regex.exec(output)) !== null) {
      const patternText = match[1]?.trim();
      if (patternText && patternText.length > 10 && patternText.length < 200) {
        patterns.push(patternText);
      }
    }
  }

  return patterns.slice(0, 3); // Max 3 patterns per task
}

function extractGotchas(output) {
  const gotchas = [];

  // Look for gotcha indicators
  const gotchaIndicators = [
    /(?:gotcha|pitfall|warning|caution|watch out|careful):\s*(.+)/gi,
    /(?:don't|do not|never|avoid)\s+(.{20,100})/gi,
    /(?:bug|issue|problem):\s*(.{20,150})/gi,
    /(?:fixed|resolved)\s+(?:by|with)\s+(.{20,100})/gi,
  ];

  for (const regex of gotchaIndicators) {
    let match;
    while ((match = regex.exec(output)) !== null) {
      const gotchaText = match[1]?.trim();
      if (gotchaText && gotchaText.length > 10 && gotchaText.length < 200) {
        gotchas.push(gotchaText);
      }
    }
  }

  return gotchas.slice(0, 3); // Max 3 gotchas per task
}

function extractDiscoveries(output) {
  const discoveries = [];

  // Look for file path mentions with descriptions
  const filePatterns = [
    /`([^`]+\.[a-z]{2,4})`[:\s-]+(.{10,100})/gi,
    /(?:file|module|component)\s+`?([^\s`]+\.[a-z]{2,4})`?\s+(?:is|handles|contains|manages)\s+(.{10,80})/gi,
  ];

  for (const regex of filePatterns) {
    let match;
    while ((match = regex.exec(output)) !== null) {
      const filePath = match[1]?.trim();
      const description = match[2]?.trim();
      if (filePath && description && !filePath.includes(' ')) {
        discoveries.push({ path: filePath, description });
      }
    }
  }

  return discoveries.slice(0, 5); // Max 5 discoveries per task
}

function queueReflection(entry, queueFile = QUEUE_FILE) {
  // Check if enabled
  if (!isEnabled()) {
    return;
  }

  try {
    // Ensure directory exists
    const queueDir = path.dirname(queueFile);
    if (!fs.existsSync(queueDir)) {
      fs.mkdirSync(queueDir, { recursive: true });
    }

    appendJsonl(queueFile, entry, { maxLines: REFLECTION_QUEUE_MAX_LINES });

    // Log in warn mode
    const mode = process.env.REFLECTION_HOOK_MODE || 'block';
    if (mode === 'warn') {
      const trigger = entry.trigger || 'unknown';
      const id = entry.taskId || entry.sessionId || entry.tool || 'unknown';
      auditLog('unified-reflection', 'queued', { trigger, id });
    }
  } catch (err) {
    // Log error but don't fail the hook
    debugLog('unified-reflection', 'Error queueing reflection', err);
  }
}

function recordSession(sessionData) {
  if (!isEnabled()) {
    return;
  }

  try {
    // Try to load memory-tiers (may not exist in older installations)
    let memoryTiers = null;
    try {
      memoryTiers = require(
        path.join(PROJECT_ROOT, '.claude', 'lib', 'memory', 'memory-tiers.cjs')
      );
    } catch (_e) {
      // Memory tiers not available - session recording skipped (saveSession is deprecated no-op)
      debugLog(
        'unified-reflection',
        'memory-tiers not available; session recording skipped (memory-tiers required for session persistence)'
      );
      return;
    }

    // Use memory tiers (canonical path): STM → MTM
    // Write to STM first
    memoryTiers.writeSTMEntry(sessionData, PROJECT_ROOT);

    // Consolidate STM -> MTM
    memoryTiers.consolidateSession(sessionData.session_id, PROJECT_ROOT);

    // NOTE: We no longer call memory-manager.saveSession() here.
    // This avoids duplicate session storage in both sessions/ and mtm/ directories.
    // memory-manager.saveSession() is now deprecated for session recording.
    // Use memory-tiers for sessions; memory-manager for gotchas, patterns, codebase_map, learnings.

    if (process.env.DEBUG_HOOKS) {
      debugLog(
        'unified-reflection',
        `Session recorded via memory-tiers: ${sessionData.session_id}`
      );
    }
  } catch (err) {
    debugLog('unified-reflection', 'Error recording session', err);
  }
}

async function triggerEmbeddingGeneration(sessionData) {
  if (!isEnabled()) {
    return;
  }

  const filesModified = Array.isArray(sessionData?.files_modified)
    ? sessionData.files_modified
    : [];
  if (filesModified.length === 0) {
    return;
  }

  const memoryDir = path.resolve(PROJECT_ROOT, '.claude', 'context', 'memory');
  const memoryFiles = filesModified
    .filter(f => typeof f === 'string' && f.toLowerCase().endsWith('.md'))
    .map(f => (path.isAbsolute(f) ? path.resolve(f) : path.resolve(PROJECT_ROOT, f)))
    .filter(fullPath => {
      const resolved = path.resolve(fullPath);
      if (resolved === memoryDir) return false;
      return resolved.startsWith(memoryDir + path.sep);
    })
    .filter(fullPath => fs.existsSync(fullPath));

  if (memoryFiles.length === 0) {
    return;
  }

  try {
    const { MemoryVectorStore } = require('../../lib/memory/lancedb-client.cjs');
    const embeddings = require('../../tools/cli/generate-embeddings.cjs');

    const vectorStore = new MemoryVectorStore({
      persistDirectory:
        process.env.LANCEDB_URI || path.join(PROJECT_ROOT, '.claude', 'data', 'lancedb'),
      collectionName: process.env.LANCEDB_TABLE || 'agent_memory',
    });

    const available = await vectorStore.isAvailable();
    if (!available) {
      debugLog('unified-reflection', 'LanceDB not available, skipping embedding generation');
      return;
    }

    // Process files
    for (const fullPath of memoryFiles) {
      try {
        const content = fs.readFileSync(fullPath, 'utf8');
        const chunks = embeddings.chunkByHeaders(content, fullPath);
        if (chunks.length === 0) continue;

        const docs = chunks.map(chunk => {
          const metadata = embeddings.extractMetadata(fullPath, chunk.section, chunk.line);
          return {
            id: `${metadata.filePath}-${chunk.line}`,
            text: `${chunk.section}\n\n${chunk.content}`,
            metadata,
          };
        });

        await vectorStore.upsertDocuments(docs);
      } catch (err) {
        debugLog('unified-reflection', `Error processing file ${fullPath}`, err);
      }
    }

    if (process.env.DEBUG_HOOKS) {
      debugLog('unified-reflection', `Generated embeddings for ${memoryFiles.length} files`);
    }
  } catch (err) {
    debugLog('unified-reflection', 'Error in embedding generation workflow', err);
  }
} // End triggerEmbeddingGeneration

function triggerMLSessionEnd(result) {
  if (!mlIndex || !mlIndex.isMLEnabled()) return;

  try {
    const toSafeInt = (value, fallback = 0) => {
      const n = Number(value);
      return Number.isFinite(n) ? Math.trunc(n) : fallback;
    };

    const bucketize = (value, thresholds, labels) => {
      const v = Math.max(0, toSafeInt(value, 0));
      for (let i = 0; i < thresholds.length; i++) {
        if (v < thresholds[i]) return labels[i];
      }
      return labels[labels.length - 1];
    };

    const stats = result.reflection?.stats || {};
    const errorReview = result.reflection?.errorReview || {};
    const sessionData = result.sessionData || {};

    const tasksCompleted = Array.isArray(sessionData.tasks_completed)
      ? sessionData.tasks_completed
      : [];
    const filesModified = Array.isArray(sessionData.files_modified)
      ? sessionData.files_modified
      : [];

    // Use real signals we have today: reflection stats + sessionData lists.
    // If duration/tokens/memory are available later from the host payload, they can flow through
    // sessionData.* and will be picked up below.
    const tasksCount = Math.max(tasksCompleted.length, toSafeInt(stats.tasksCompleted, 0), 0);
    const historyLen = Math.min(Math.max(tasksCount, 1), 200);

    const toolCalls = toSafeInt(stats.toolCalls, 0);
    const toolCallsBucket = bucketize(toolCalls, [1, 10, 50], ['none', 'low', 'med', 'high']);

    const filesModifiedCount = filesModified.length;
    const filesModifiedBucket = bucketize(
      filesModifiedCount,
      [1, 5, 20],
      ['none', 'low', 'med', 'high']
    );

    const history = Array.from({ length: historyLen }, () => {
      const tools = ['Task', `toolCalls:${toolCallsBucket}`];
      if (filesModifiedCount > 0) {
        tools.push(`filesModified:${filesModifiedBucket}`);
      }
      return { agent: 'session', tools };
    });

    // Prefer real metrics if present. Otherwise, use consistent proxies:
    // - tokenUsage: toolCalls * 500 (roughly correlates with "work done"; keeps scale stable)
    const totalDuration =
      toSafeInt(sessionData.totalDuration, null) ??
      toSafeInt(sessionData.duration_ms, null) ??
      toSafeInt(sessionData.durationMs, null) ??
      0;
    const tokenUsage =
      toSafeInt(sessionData.tokenUsage, null) ??
      toSafeInt(sessionData.token_usage, null) ??
      (toolCalls > 0 ? toolCalls * 500 : 0);
    const peakMemoryMB =
      toSafeInt(sessionData.peakMemoryMB, null) ??
      toSafeInt(sessionData.peak_memory_mb, null) ??
      toSafeInt(sessionData.peakMemoryMb, null) ??
      0;

    // Minimal session shape for ML: { history, metrics, trace }
    const sessionForML = {
      history,
      metrics: {
        totalDuration,
        errorCount: toSafeInt(stats.errors, 0),
        tokenUsage,
        peakMemoryMB,
        criticalErrors: toSafeInt(errorReview.criticalIssues, 0),
      },
      trace: {
        tasksCount,
        filesModifiedCount,
        toolCalls,
      },
    };

    const mlContextDir = path.join(PROJECT_ROOT, '.claude', 'context', 'ml');
    const persistence = {
      modelPath: process.env.ML_MODEL_PATH || path.join(mlContextDir, 'pattern-model.json'),
      policyPath:
        process.env.ML_POLICY_PATH || path.join(mlContextDir, 'optimization-policies.json'),
      statePath:
        process.env.ML_FEEDBACK_STATE_PATH || path.join(mlContextDir, 'feedback-loop-state.json'),
      sessionsPath: process.env.ML_SESSIONS_LOG_PATH || path.join(mlContextDir, 'sessions.jsonl'),
    };

    const feedback = mlIndex.getFeedbackLoop(persistence);
    if (feedback) {
      feedback.process(sessionForML);
    }

    const engine = feedback?.optimizationEngine || mlIndex.getOptimizationEngine(persistence);
    if (engine && engine.isReady().ready) {
      const recommendation = engine.optimize(sessionForML);
      const mode = mlIndex.getMLAutomationMode();
      if (recommendation && (mode === 'log' || mode === 'enforce')) {
        debugLog(
          'unified-reflection',
          'ML optimization recommendation (advice-only)',
          recommendation
        );
      }
    }
  } catch (err) {
    debugLog('unified-reflection', 'ML session-end failed', err);
  }
}

function triggerMaintenance() {
  if (!isEnabled()) {
    return;
  }

  try {
    const scheduler = require('../../lib/memory/memory-scheduler.cjs');

    scheduler.runDailyMaintenance(PROJECT_ROOT);

    const status = scheduler.getMaintenanceStatus(PROJECT_ROOT);
    const lastWeekly = status?.lastWeekly ? new Date(status.lastWeekly) : null;
    const daysSinceWeekly = lastWeekly
      ? (Date.now() - lastWeekly.getTime()) / (1000 * 60 * 60 * 24)
      : Infinity;

    if (daysSinceWeekly >= 7) {
      scheduler.runWeeklyMaintenance(PROJECT_ROOT);
      debugLog('unified-reflection', 'Weekly maintenance completed');
    } else {
      debugLog(
        'unified-reflection',
        `Weekly maintenance not due (${Math.round(daysSinceWeekly * 10) / 10} days since last run)`
      );
    }
  } catch (err) {
    debugLog('unified-reflection', 'Error running maintenance', err);
  }
}

function recordMemoryItems(extracted) {
  if (!isEnabled()) {
    return;
  }

  try {
    // Import memory manager
    let memoryManager;
    try {
      memoryManager = require('../../lib/memory/memory-manager.cjs');
    } catch (_e) {
      const libPath = path.join(__dirname, '..', '..', 'lib', 'memory', 'memory-manager.cjs');
      memoryManager = require(libPath);
    }

    let recorded = 0;

    for (const pattern of extracted.patterns || []) {
      if (memoryManager.recordPattern(pattern, PROJECT_ROOT)) {
        recorded++;
      }
    }

    for (const gotcha of extracted.gotchas || []) {
      if (memoryManager.recordGotcha(gotcha, PROJECT_ROOT)) {
        recorded++;
      }
    }

    for (const discovery of extracted.discoveries || []) {
      if (
        memoryManager.recordDiscovery(
          discovery.path,
          discovery.description,
          'general',
          PROJECT_ROOT
        )
      ) {
        recorded++;
      }
    }

    if (recorded > 0 && process.env.DEBUG_HOOKS) {
      debugLog('unified-reflection', `Recorded ${recorded} memory items`);
    }
  } catch (err) {
    debugLog('unified-reflection', 'Error recording memory items', err);
  }
}

async function main() {
  const startTime = Date.now();
  const outcome = {
    eventType: null,
    queued: false,
    sessionRecorded: false,
    memoryItemsRecorded: false,
    taskUpdateTracked: false,
    embeddingTriggered: false,
    maintenanceTriggered: false,
  };
  try {
    // Check if enabled
    if (!isEnabled()) {
      process.exit(0);
    }

    // Parse input
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      process.exit(0);
    }

    // Detect event type
    const eventType = detectEventType(hookInput);

    if (!eventType) {
      process.exit(0);
    }

    outcome.eventType = eventType;

    // Route to appropriate handler
    switch (eventType) {
      case 'task_completion': {
        const entry = handleTaskCompletion(hookInput);
        queueReflection(entry);
        outcome.queued = true;
        break;
      }

      // PERF-003 #2: Handle non-completion TaskUpdate (was task-update-tracker.cjs)
      case 'task_update': {
        handleTaskUpdate(hookInput);
        // No queue entry for non-completion updates
        outcome.taskUpdateTracked = true;
        break;
      }

      case 'error_recovery': {
        const entry = handleErrorRecovery(hookInput);
        queueReflection(entry);
        outcome.queued = true;
        break;
      }

      case 'session_end': {
        const result = handleSessionEnd(hookInput);
        // Queue reflection entry
        queueReflection(result.reflection);
        outcome.queued = true;
        // Record session to memory
        recordSession(result.sessionData);
        outcome.sessionRecorded = true;
        // Best-effort activations
        // Note: Embedding generation is awaited to ensure the process doesn't exit before work completes.
        outcome.embeddingTriggered = true;
        await triggerEmbeddingGeneration(result.sessionData).catch(err => {
          debugLog('unified-reflection', 'Embedding generation failed', err);
        });
        triggerMLSessionEnd(result);
        triggerMaintenance();
        outcome.maintenanceTriggered = true;
        break;
      }

      case 'memory_extraction': {
        const extracted = handleMemoryExtraction(hookInput);
        // Record to memory system
        recordMemoryItems(extracted);
        outcome.memoryItemsRecorded = true;
        break;
      }
    }

    try {
      await eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'unified-reflection-handler',
        output: outcome,
        duration: Date.now() - startTime,
      });
    } catch (_e) {
      // Best-effort
    }
    // PostToolUse/SessionEnd hooks always exit 0 (don't block)
    process.exit(0);
  } catch (err) {
    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'unified-reflection-handler',
        error: err.message,
      });
    } catch (_e) {
      // Best-effort
    }
    // Fail open
    debugLog('unified-reflection', 'Hook error during processing', err);
    process.exit(0);
  }
}

function extractTaskDescription(toolInput) {
  if (!toolInput) return null;

  // Try to get description from various possible fields
  if (toolInput.description) return toolInput.description;
  if (toolInput.prompt) {
    // Extract first line or truncate
    const firstLine = toolInput.prompt.split('\n')[0];
    return firstLine.length > 100 ? firstLine.slice(0, 100) + '...' : firstLine;
  }
  if (toolInput.subagent_type) return `${toolInput.subagent_type} agent`;

  return 'Task spawned';
}

function isPlannerSpawn(toolInput) {
  if (!toolInput) return false;

  const subagentType = (toolInput.subagent_type || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();
  const prompt = toolInput.prompt || '';

  // Check subagent_type for 'plan'
  if (subagentType.includes('plan')) return true;

  // Check description for 'planner' (case-insensitive)
  if (description.includes('planner')) return true;

  // Check prompt for 'You are PLANNER' or 'You are the PLANNER'
  if (prompt.includes('You are PLANNER') || prompt.includes('You are the PLANNER')) return true;

  return false;
}

function isSecuritySpawn(toolInput) {
  if (!toolInput) return false;

  const subagentType = (toolInput.subagent_type || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();
  const prompt = toolInput.prompt || '';

  // Check subagent_type for 'security'
  if (subagentType.includes('security')) return true;

  // Check description for 'security' (case-insensitive)
  if (description.includes('security')) return true;

  // Check prompt for 'SECURITY-ARCHITECT'
  if (prompt.includes('SECURITY-ARCHITECT')) return true;

  return false;
}

function main() {
  const hookInput = parseHookInput();

  // PERF-006: Validate this is a Task tool call using shared helper
  const toolName = getToolName(hookInput);
  if (toolName !== 'Task') {
    // Not a Task tool, skip
    process.exit(0);
  }

  // PERF-006: Get tool input to extract description using shared helper
  const toolInput = getToolInput(hookInput);
  const description = extractTaskDescription(toolInput);

  // Enter agent mode
  const state = routerState.enterAgentMode(description);

  // Detect and mark special agent spawns
  if (isPlannerSpawn(toolInput)) {
    routerState.markPlannerSpawned();
    if (process.env.ROUTER_DEBUG === 'true') {
      console.log('[agent-context-tracker] PLANNER agent detected and marked');
    }
  }

  if (isSecuritySpawn(toolInput)) {
    routerState.markSecuritySpawned();
    if (process.env.ROUTER_DEBUG === 'true') {
      console.log('[agent-context-tracker] SECURITY-ARCHITECT agent detected and marked');
    }
  }

  // Show state change in verbose mode
  if (process.env.ROUTER_DEBUG === 'true') {
    console.log('[agent-context-tracker] Entered agent mode');
    console.log(`[agent-context-tracker] Task: ${description}`);
    console.log(`[agent-context-tracker] Spawned at: ${state.taskSpawnedAt}`);
  }

  // Always allow - this hook only manages state
  process.exit(0);
}

function extractAgentTypeFromPrompt(prompt) {
  if (!prompt || typeof prompt !== 'string') {
    return null;
  }

  const promptLower = prompt.toLowerCase();

  // Pattern 1: "You are PLANNER" or "You are the PLANNER"
  // Matches: "You are PLANNER", "You are the developer", "you are security-architect"
  const youAreMatch = promptLower.match(/you are (?:the )?([a-z][-a-z0-9]*)/i);
  if (youAreMatch) {
    return youAreMatch[1].toLowerCase();
  }

  // Pattern 2: Agent file path reference
  // Matches: ".claude/agents/core/planner.md", ".claude/agents/specialized/security-architect.md"
  const pathMatch = prompt.match(
    /\.claude\/agents\/(?:core|specialized|domain|orchestrators)\/([^/.]+)\.md/i
  );
  if (pathMatch) {
    return pathMatch[1].toLowerCase();
  }

  // Pattern 3: subagent_type hint (used in Task() calls)
  // Matches: "[subagent_type: developer]", "subagent_type: planner"
  const subagentMatch = prompt.match(/\[?subagent_type:\s*([a-z][-a-z0-9]*)\]?/i);
  if (subagentMatch) {
    return subagentMatch[1].toLowerCase();
  }

  return null;
}

function extractModelFromToolInput(toolInput) {
  if (!toolInput || typeof toolInput !== 'object') {
    return null;
  }

  const model = toolInput.model;
  if (!model || typeof model !== 'string') {
    return null;
  }

  return model.trim();
}

function validateModelConfig(toolInput, projectRoot = PROJECT_ROOT) {
  const mode = getEnforcementMode('CONFIG_MODEL_VALIDATOR', 'warn');

  // Skip validation when disabled
  if (mode === 'off') {
    auditSecurityOverride(
      'config-model-validator',
      'CONFIG_MODEL_VALIDATOR',
      'off',
      'Model configuration validation disabled'
    );
    return {
      decision: 'allow',
      mismatch: false,
      skipped: true,
      reason: 'Validation disabled (CONFIG_MODEL_VALIDATOR=off)',
    };
  }

  // Extract agent type from prompt
  const prompt = toolInput?.prompt || '';
  const agentType = extractAgentTypeFromPrompt(prompt);

  if (!agentType) {
    // Cannot determine agent type - allow (no validation possible)
    return {
      decision: 'allow',
      mismatch: false,
      agentType: null,
      reason: 'Cannot determine agent type from prompt',
    };
  }

  // Extract spawn model
  const spawnModel = extractModelFromToolInput(toolInput);

  if (!spawnModel) {
    // No model specified in spawn - allow (Router should use config)
    return {
      decision: 'allow',
      mismatch: false,
      agentType,
      spawnModel: null,
      reason: 'No model specified in spawn (will use config or default)',
    };
  }

  // Resolve configured model
  const configResult = resolveAgentModel(agentType, projectRoot);
  const configuredModel = configResult.shorthand;
  const configSource = configResult.source;

  // Normalize spawn model for comparison
  const spawnShorthand = getShorthand(spawnModel);

  // Check for mismatch
  const mismatch = spawnShorthand !== configuredModel;

  if (mismatch) {
    const decision = mode === 'block' ? 'block' : 'warn';
    return {
      decision,
      mismatch: true,
      agentType,
      spawnModel: spawnShorthand,
      configuredModel,
      source: configSource,
      message: `Model mismatch for ${agentType}: spawn uses '${spawnShorthand}' but config specifies '${configuredModel}' (source: ${configSource})`,
    };
  }

  // Models match
  return {
    decision: 'allow',
    mismatch: false,
    agentType,
    spawnModel: spawnShorthand,
    configuredModel,
    source: configSource,
  };
}

function formatAuditEntry(validation) {
  return {
    hook: 'config-model-validator',
    event: validation.mismatch ? 'model_mismatch' : 'model_validated',
    timestamp: new Date().toISOString(),
    agentType: validation.agentType,
    spawnModel: validation.spawnModel,
    configuredModel: validation.configuredModel,
    source: validation.source,
    decision: validation.decision,
    mismatch: validation.mismatch,
  };
}

async function main() {
  try {
    // Parse hook input
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      // No input - allow
      process.exit(0);
    }

    // Only validate Task tool
    const toolName = getToolName(hookInput);
    if (toolName !== 'Task') {
      process.exit(0);
    }

    // Get tool input
    const toolInput = getToolInput(hookInput);

    // Validate model configuration
    const result = validateModelConfig(toolInput, PROJECT_ROOT);

    // Log audit entry
    const auditEntry = formatAuditEntry(result);
    auditLog('config-model-validator', auditEntry.event, auditEntry);

    // Handle result
    if (result.mismatch) {
      const message = `
+======================================================================+
|  CONFIG MODEL VALIDATOR - MODEL MISMATCH DETECTED                    |
+======================================================================+
|  Agent Type:       ${(result.agentType || 'unknown').padEnd(45)}|
|  Spawn Model:      ${(result.spawnModel || 'none').padEnd(45)}|
|  Configured Model: ${(result.configuredModel || 'none').padEnd(45)}|
|  Config Source:    ${(result.source || 'unknown').padEnd(45)}|
|                                                                      |
|  The spawn model does not match the configured model.                |
|  To fix: Use resolveAgentModel() before spawning to get the correct  |
|  model from config.yaml.                                             |
|                                                                      |
|  Mode: ${getEnforcementMode('CONFIG_MODEL_VALIDATOR', 'warn').padEnd(58)}|
+======================================================================+
`;

      console.error(message);

      if (result.decision === 'block') {
        try {
          await eventBus.emit(EventTypes.TOOL_BLOCKED, {
            type: EventTypes.TOOL_BLOCKED,
            timestamp: new Date().toISOString(),
            toolName: 'Task',
            reason: 'config_model_mismatch',
          });
        } catch (_err) {
          // Best-effort
        }
        console.log(formatResult('block', result.message));
        process.exit(2);
      } else {
        // Warn mode - allow but log
        console.log(formatResult('allow', result.message));
        process.exit(0);
      }
    }

    // No mismatch - allow
    process.exit(0);
  } catch (err) {
    // Fail open on error (don't break spawning)
    auditLog('config-model-validator', 'error', { error: err.message });
    process.exit(0);
  }
}

function getRegistryPath() {
  return (
    process.env.AGENT_REGISTRY_PATH ||
    path.join(PROJECT_ROOT, '.claude/context/agent-registry.json')
  );
}

function extractAgentId(prompt) {
  if (!prompt || typeof prompt !== 'string') {
    return null;
  }

  // Pattern 1: "You are DEVELOPER agent" or "You are the PLANNER agent"
  const pattern1 = /You are (?:the )?([A-Z][A-Z0-9_-]+)(?: agent)?/i;
  const match1 = prompt.match(pattern1);
  if (match1) {
    return match1[1].toLowerCase().replace(/_/g, '-');
  }

  // Pattern 2: "Read: .claude/agents/core/developer.md"
  const pattern2 = /\.claude\/agents\/(?:core|specialized|domain|orchestrators)\/([a-z0-9-]+)\.md/i;
  const match2 = prompt.match(pattern2);
  if (match2) {
    return match2[1].toLowerCase();
  }

  return null;
}

function extractAgentFromInput(toolInput) {
  if (!toolInput) {
    return null;
  }

  // Check prompt first
  if (toolInput.prompt) {
    const fromPrompt = extractAgentId(toolInput.prompt);
    if (fromPrompt) return fromPrompt;
  }

  // Check description field
  if (toolInput.description) {
    const descLower = toolInput.description.toLowerCase();

    // Common patterns in description
    const agentPatterns = [
      /^(developer|planner|architect|qa|security-architect|security|devops|code-reviewer|frontend-pro|frontend|researcher)\b/,
      /(developer|planner|architect|qa|security|devops|reviewer|frontend)\s+(implementing|designing|reviewing|testing|deploying|researching)/i,
    ];

    for (const pattern of agentPatterns) {
      const match = descLower.match(pattern);
      if (match) return match[1].toLowerCase().replace(/_/g, '-');
    }
  }

  return null;
}

async function postToolUse(context) {
  // Skip if disabled
  if (hookConfig.mode === 'off' || hookConfig.mode === 'disabled') {
    return { decision: 'allow' };
  }

  const { toolName, toolInput, toolResult } = context;

  // Only process Task tool
  if (toolName !== 'Task') {
    return { decision: 'allow' };
  }

  // Handle missing input or result
  if (!toolInput || !toolResult) {
    return { decision: 'allow' };
  }

  // Extract agent ID
  const agentId = extractAgentFromInput(toolInput);
  if (!agentId) {
    // Can't track if we don't know the agent
    return { decision: 'allow' };
  }

  try {
    const tracker = new AgentHealthTracker({ registryPath: getRegistryPath() });
    const startTime = context.startTime || Date.now();
    const executionMs = Date.now() - startTime;

    // Determine success/failure from result
    const isError = toolResult.error || toolResult.status === 'error';
    if (isError) {
      const reason = toolResult.error?.message || toolResult.message || 'Task spawn failed';
      tracker.recordFailure(agentId, reason);
    } else {
      tracker.recordSuccess(agentId, executionMs);
    }
  } catch (err) {
    // Don't fail the hook if health tracking fails
    if (process.env.DEBUG_HEALTH_HOOK) {
      console.error(`[agent-health-hook] Error: ${err.message}`);
    }
  }

  return { decision: 'allow' };
}

async function preToolUse(context) {
  const { toolName, toolInput } = context;

  // Only process Task tool
  if (toolName !== 'Task') {
    return { decision: 'allow' };
  }

  // Handle missing input
  if (!toolInput) {
    return { decision: 'allow' };
  }

  // Extract agent ID
  const agentId = extractAgentFromInput(toolInput);
  if (!agentId) {
    return { decision: 'allow' };
  }

  try {
    const tracker = new AgentHealthTracker({ registryPath: getRegistryPath() });
    const registry = tracker.loadRegistry();
    const agent = registry.agents[agentId];

    if (!agent) {
      // Unknown agent - allow spawn (may be new agent)
      return { decision: 'allow' };
    }

    // Block unavailable agents (unless recovery possible)
    if (agent.health.status === 'unavailable') {
      const recovery = tracker.attemptRecovery(agentId);

      if (!recovery.success) {
        return {
          decision: 'block',
          message: `Agent ${agentId} is currently unavailable: ${agent.health.isolationReason}. ${recovery.reason}`,
          suggestion: `Try alternative agents with similar capabilities.`,
        };
      }
      // Recovery succeeded - agent is now degraded, allow spawn
    }

    // Warn for degraded agents but allow spawn
    if (agent.health.status === 'degraded') {
      if (process.env.DEBUG_HEALTH_HOOK) {
        console.warn(
          `[agent-health] Agent ${agentId} is degraded (success rate: ${(agent.health.successRate * 100).toFixed(1)}%)`
        );
      }
    }

    return { decision: 'allow' };
  } catch (err) {
    // Don't fail the hook if health check fails
    if (process.env.DEBUG_HEALTH_HOOK) {
      console.error(`[agent-health-hook] Error: ${err.message}`);
    }
    return { decision: 'allow' };
  }
}

function getToolNameFromInput(input) {
  if (!input || typeof input !== 'object') return null;
  if (input.tool_name) return String(input.tool_name);
  if (input.tool) return String(input.tool);
  if (input.toolName) return String(input.toolName);
  if (input.tool_input && input.tool_input.tool_name) return String(input.tool_input.tool_name);
  if (input.parameters && input.parameters.tool_name) return String(input.parameters.tool_name);
  return null;
}

function evaluateToolGuard(toolName, activeToolNames, enforcementMode) {
  if (!toolName || !Array.isArray(activeToolNames)) {
    return { action: 'allow', message: null };
  }
  if (activeToolNames.includes(toolName)) {
    return { action: 'allow', message: null };
  }
  if (enforcementMode === 'block') {
    return {
      action: 'block',
      message: `Tool '${toolName}' is not allowed in the current context/mode.`,
    };
  }
  if (enforcementMode === 'warn') {
    return {
      action: 'warn',
      message: `Tool '${toolName}' is not allowed in the current context/mode (warn-only).`,
    };
  }
  return { action: 'allow', message: null };
}

function getRoleFromInput(input) {
  if (!input || typeof input !== 'object') return 'developer';
  if (input.subagent_type) return String(input.subagent_type);
  if (input.agent_type) return String(input.agent_type);
  return 'developer';
}

function main() {
  const input = parseHookInputSync();
  const toolName = getToolNameFromInput(input);
  const enforcementMode = getEnforcementMode(ENFORCEMENT_ENV, 'warn');

  if (enforcementMode === 'off') {
    process.exit(0);
  }

  const role = getRoleFromInput(input);
  const contextMode = buildContextModePrompt({ role });

  if (!contextMode || !contextMode.hasContextOrMode) {
    process.exit(0);
  }

  const decision = evaluateToolGuard(toolName, contextMode.activeToolNames || [], enforcementMode);

  if (decision.action === 'block') {
    auditLog('context-mode-tool-guard', 'block', {
      tool: toolName,
      context: contextMode.contextName,
      modes: contextMode.modeNames,
    });
    process.stderr.write(`${decision.message}\n`);
    process.exit(2);
  }

  if (decision.action === 'warn') {
    auditLog('context-mode-tool-guard', 'warn', {
      tool: toolName,
      context: contextMode.contextName,
      modes: contextMode.modeNames,
    });
    process.stderr.write(`${decision.message}\n`);
  }

  process.exit(0);
}

function isDisabled() {
  return process.env.CODE_INDEX_AUTO_UPDATE === 'off';
}

function shouldIndexFile(filePath) {
  if (!filePath || typeof filePath !== 'string') return false;

  // Check extension
  const ext = path.extname(filePath).toLowerCase();
  if (!INDEXABLE_EXTENSIONS.has(ext)) return false;

  // Check exclude patterns
  const normalizedPath = filePath.replace(/\\/g, '/');
  for (const pattern of EXCLUDE_PATTERNS) {
    if (pattern.test(normalizedPath)) return false;
  }

  return true;
}

async function canProceed() {
  try {
    // Check if lock exists and is stale
    const lockStats = await fs.stat(LOCK_FILE);
    const lockAge = Date.now() - lockStats.mtimeMs;

    if (lockAge > LOCK_TIMEOUT_MS) {
      // Stale lock - remove it
      await fs.unlink(LOCK_FILE).catch(() => {});
      return true;
    }

    // Lock is active - another process is indexing
    return false;
  } catch (_err) {
    // Lock file doesn't exist or stat failed - allow proceed (fail-open)
    return true;
  }
}

async function createLock() {
  try {
    await fs.writeFile(
      LOCK_FILE,
      JSON.stringify({
        pid: process.pid,
        timestamp: Date.now(),
      }),
      { flag: 'wx' } // fail if exists (atomic)
    );
    return true;
  } catch (_err) {
    return false;
  }
}

async function removeLock() {
  await fs.unlink(LOCK_FILE).catch(() => {});
}

async function triggerIndexUpdate(filePath) {
  if (isDisabled()) {
    return;
  }

  // Best-effort: refresh codebase_map.json so it doesn't go stale.
  // Only record safe, in-project paths (fail-open if anything is weird).
  try {
    const projectRoot = process.cwd();
    const validation = validatePathWithinProject(filePath, projectRoot);
    if (validation.safe) {
      const abs = path.isAbsolute(filePath) ? filePath : path.join(projectRoot, filePath);
      const rel = path.relative(projectRoot, abs).replace(/\\/g, '/');
      if (!rel.startsWith('.claude/context/')) {
        const memoryManager = require('../../lib/memory/memory-manager.cjs');
        memoryManager.recordDiscovery(
          rel,
          'Auto-discovered (code-index-updater)',
          'code-indexing',
          projectRoot
        );
      }
    }
  } catch (_err) {
    // best-effort only
  }

  // Quick check - if another process is indexing, skip (they'll handle it)
  const proceed = await canProceed();
  if (!proceed) {
    return; // Another process is handling indexing
  }

  // Try to acquire lock (best-effort, non-blocking)
  const hasLock = await createLock();
  if (!hasLock) {
    return; // Another process got the lock first
  }

  try {
    const { IndexManager } = require('../../lib/code-indexing/index-manager.cjs');
    const projectRoot = process.cwd();

    // Create index manager
    const manager = new IndexManager({ projectRoot });

    // Check if index exists
    const indexMetadataPath = path.join(projectRoot, '.claude/context/code-index/metadata.json');
    const indexExists = await fs
      .access(indexMetadataPath)
      .then(() => true)
      .catch(() => false);

    if (!indexExists) {
      await removeLock();
      return;
    }

    // Use incremental update (Merkle tree) if available, otherwise fall back to directory indexing
    // Run indexing in background (non-blocking)
    setImmediate(async () => {
      const startTime = Date.now();
      try {
        // Try incremental update first (uses Merkle tree for O(log n) change detection)
        const result = await manager.incrementalUpdate({
          onProgress: () => {}, // Silent progress
        });

        const output = {
          filePath,
          updateType: result.updateType,
          filesAdded: result.filesAdded,
          filesModified: result.filesModified,
          filesDeleted: result.filesDeleted,
        };

        if (
          result.updateType === 'incremental' &&
          result.filesAdded === 0 &&
          result.filesModified === 0 &&
          result.filesDeleted === 0
        ) {
          // No changes detected - nothing to do
          debugLog('code-index-updater', 'No changes detected (Merkle tree)');
          output.noChanges = true;
        } else {
          debugLog(
            'code-index-updater',
            `Incremental update: ${result.filesModified} modified, ${result.filesAdded} added, ${result.filesDeleted} deleted`
          );
        }

        try {
          await eventBus.emit(EventTypes.TOOL_COMPLETED, {
            type: EventTypes.TOOL_COMPLETED,
            timestamp: new Date().toISOString(),
            toolName: 'code-index-updater',
            duration: Date.now() - startTime,
            output,
          });
        } catch (_e) {
          // Best-effort
        }
      } catch (err) {
        // Fallback: if incremental fails, index the directory containing the file
        debugLog(
          'code-index-updater',
          'Incremental update failed, falling back to directory index',
          err
        );
        try {
          const fileDir = path.dirname(filePath);
          await manager.indexDirectory(fileDir, {
            onProgress: () => {},
          });
          try {
            await eventBus.emit(EventTypes.TOOL_COMPLETED, {
              type: EventTypes.TOOL_COMPLETED,
              timestamp: new Date().toISOString(),
              toolName: 'code-index-updater',
              duration: Date.now() - startTime,
              output: {
                filePath,
                updateType: 'fallback',
                indexedDirectory: fileDir,
              },
            });
          } catch (_e) {
            // Best-effort
          }
        } catch (fallbackErr) {
          debugLog('code-index-updater', `Fallback indexing failed (non-blocking)`, fallbackErr);
          try {
            await eventBus.emit(EventTypes.TOOL_FAILED, {
              type: EventTypes.TOOL_FAILED,
              timestamp: new Date().toISOString(),
              toolName: 'code-index-updater',
              duration: Date.now() - startTime,
              error: fallbackErr.message,
            });
          } catch (_e) {
            // Best-effort
          }
        }
      } finally {
        await removeLock();
      }
    });
  } catch (err) {
    debugLog('code-index-updater', 'Index update error (ignored)', err);
    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'code-index-updater',
        error: err.message,
      });
    } catch (_e) {
      // Best-effort
    }
    await removeLock();
  }
}

function scheduleDebouncedUpdate(filePath) {
  // Clear existing timer
  if (debounceTimer) {
    clearTimeout(debounceTimer);
  }

  // Schedule update after debounce period
  debounceTimer = setTimeout(() => {
    debounceTimer = null;
    triggerIndexUpdate(filePath).catch(() => {
      // Non-blocking - errors are logged but don't affect file operations
    });
  }, DEFAULT_DEBOUNCE_MS);
}

async function main() {
  try {
    if (isDisabled()) {
      process.exit(0);
    }

    const hookInput = await parseHookInputAsync();
    if (!hookInput) process.exit(0);

    const toolName = getToolName(hookInput);
    if (toolName !== 'Write' && toolName !== 'Edit') {
      process.exit(0);
    }

    const toolInput = getToolInput(hookInput);
    if (!toolInput || typeof toolInput !== 'object') process.exit(0);

    const filePath = toolInput.file_path || toolInput.target_file;
    if (!filePath || typeof filePath !== 'string') process.exit(0);

    // Check if this file should be indexed
    if (!shouldIndexFile(filePath)) {
      process.exit(0);
    }

    // Schedule debounced update
    scheduleDebouncedUpdate(filePath);

    // Exit successfully (don't block the tool)
    process.exit(0);
  } catch (err) {
    // Fail open - don't block file operations if hook fails
    debugLog('code-index-updater', 'Hook error (fail open)', err);
    process.exit(0);
  }
}

function extractTaskId(prompt) {
  if (!prompt || typeof prompt !== 'string') return null;

  const patterns = [
    /Task\s+#(\d+)/i,
    /Your\s+Task\s+ID:\s*(\d+)/i,
    /task\s+#(\d+)/i,
    /taskId[:\s]+["']?(\d+)/i,
  ];

  for (const pattern of patterns) {
    const match = prompt.match(pattern);
    if (match && match[1]) {
      return match[1];
    }
  }

  return null;
}

function loadTasks(projectRoot) {
  const tasksFile = path.join(projectRoot, '.claude/context/tasks.json');

  if (!fs.existsSync(tasksFile)) {
    return [];
  }

  try {
    const content = fs.readFileSync(tasksFile, 'utf8');
    const data = JSON.parse(content);
    return data.tasks || [];
  } catch (error) {
    console.error('[POST-SPAWN-UPDATER] Failed to load tasks.json:', error.message);
    return [];
  }
}

function logPostSpawnCheck(projectRoot, entry) {
  const auditLog = path.join(projectRoot, '.claude/context/metrics/spawn-audit.jsonl');
  const dir = path.dirname(auditLog);

  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  const line = JSON.stringify({
    timestamp: new Date().toISOString(),
    hook: 'post-spawn-task-updater',
    ...entry,
  });

  fs.appendFileSync(auditLog, line + '\n', 'utf8');
}

function logEscalation(projectRoot, escalation) {
  const escalationLog = path.join(projectRoot, '.claude/context/metrics/task-escalations.jsonl');
  const dir = path.dirname(escalationLog);

  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  const line = JSON.stringify({
    timestamp: new Date().toISOString(),
    ...escalation,
  });

  fs.appendFileSync(escalationLog, line + '\n', 'utf8');
}

async function PostToolUse(input) {
  const { tool, parameters = {}, context = {} } = input;

  // Only check Task tool
  if (tool !== 'Task') {
    return { allowed: true };
  }

  // Check for override flag
  if (process.env.NO_TRACK_ENFORCEMENT === 'true') {
    return { allowed: true };
  }

  const projectRoot = context.PROJECT_ROOT || process.cwd();
  const { prompt = '' } = parameters;

  // Extract task ID from prompt
  const taskId = extractTaskId(prompt);
  if (!taskId) {
    // No task ID in prompt - can't verify
    logPostSpawnCheck(projectRoot, {
      event: 'no-task-id',
      prompt: prompt.substring(0, 100),
      warning: 'Spawn completed without task ID in prompt',
    });
    return { allowed: true, warnings: ['Spawn without task ID'] };
  }

  // Load tasks
  const tasks = loadTasks(projectRoot);
  if (tasks.length === 0) {
    // No tasks file - can't verify
    return { allowed: true };
  }

  // Find the task
  const task = tasks.find(t => String(t.id) === String(taskId));
  if (!task) {
    logPostSpawnCheck(projectRoot, {
      event: 'task-not-found',
      taskId,
      warning: `Task #${taskId} not found after spawn`,
    });
    return { allowed: true, warnings: [`Task #${taskId} not found`] };
  }

  // Check if task is still in_progress
  if (task.status === 'in_progress') {
    const warnings = [];

    // Calculate how long task has been in progress
    const startedAt = task.startedAt ? new Date(task.startedAt) : null;
    const duration = startedAt ? Date.now() - startedAt.getTime() : 0;
    const durationMinutes = Math.floor(duration / 60000);

    const warning = `Task #${taskId} still in_progress after spawn completed (${durationMinutes}m)`;
    warnings.push(warning);

    // Escalate if >1 hour
    if (duration > 60 * 60 * 1000) {
      logEscalation(projectRoot, {
        taskId: task.id,
        subject: task.subject,
        status: task.status,
        durationMs: duration,
        durationMinutes,
        reason: 'Task in_progress for >1 hour without completion',
      });
      warnings.push(`ESCALATED: Task #${taskId} >1 hour without completion`);
    }

    logPostSpawnCheck(projectRoot, {
      event: 'incomplete-task',
      taskId: task.id,
      subject: task.subject,
      status: task.status,
      durationMinutes,
      warning,
    });

    return { allowed: true, warnings };
  }

  // Task is completed or failed - good!
  logPostSpawnCheck(projectRoot, {
    event: 'task-completed',
    taskId: task.id,
    status: task.status,
    result: 'Task properly updated',
  });

  return { allowed: true };
}

function loadManifest() {
  if (_manifestCache) {
    return _manifestCache;
  }

  try {
    if (fs.existsSync(MANIFEST_PATH)) {
      const content = fs.readFileSync(MANIFEST_PATH, 'utf-8');
      _manifestCache = JSON.parse(content);
      return _manifestCache;
    }
  } catch (e) {
    // Fallback to minimal manifest if load fails
    auditLog('pre-spawn-tool-validator', 'warn', {
      reason: 'Failed to load manifest, using fallback',
      error: e.message,
    });
  }

  // Fallback manifest with core tools
  _manifestCache = {
    tools: {
      core: [
        { name: 'Read', status: 'available' },
        { name: 'Write', status: 'available' },
        { name: 'Edit', status: 'available' },
        { name: 'Bash', status: 'available' },
        { name: 'Glob', status: 'available' },
        { name: 'Grep', status: 'available' },
        { name: 'Task', status: 'available' },
        { name: 'TaskCreate', status: 'available' },
        { name: 'TaskUpdate', status: 'available' },
        { name: 'TaskList', status: 'available' },
        { name: 'TaskGet', status: 'available' },
        { name: 'TaskOutput', status: 'available' },
        { name: 'TaskStop', status: 'available' },
        { name: 'Skill', status: 'available' },
        { name: 'AskUserQuestion', status: 'available' },
        { name: 'EnterPlanMode', status: 'available' },
        { name: 'ExitPlanMode', status: 'available' },
        { name: 'WebSearch', status: 'available' },
        { name: 'WebFetch', status: 'available' },
        { name: 'NotebookEdit', status: 'available' },
      ],
      mcp: [],
    },
    constraints: {
      maxToolsPerAgent: 15,
      maxToolsPerOrchestrator: 18,
    },
    validation: {
      reservedTools: {
        Task: [
          'router',
          'master-orchestrator',
          'evolution-orchestrator',
          'swarm-coordinator',
          'party-orchestrator',
        ],
        AskUserQuestion: ['router'],
      },
      mandatoryTools: ['TaskUpdate', 'Skill'],
    },
  };

  return _manifestCache;
}

function getKnownTools(manifest) {
  const known = new Set();

  // Add core tools
  for (const tool of manifest.tools?.core || []) {
    known.add(tool.name);
  }

  // Add MCP tools
  for (const tool of manifest.tools?.mcp || []) {
    known.add(tool.name);
  }

  return known;
}

function getMcpToolInfo(toolName, manifest) {
  for (const tool of manifest.tools?.mcp || []) {
    if (tool.name === toolName) {
      return tool;
    }
  }
  return null;
}

function isOrchestrator(agentType) {
  if (!agentType) return false;
  const lowerType = agentType.toLowerCase();
  return ORCHESTRATOR_TYPES.some(t => lowerType.includes(t) || lowerType.includes('orchestrator'));
}

const agentLower = (agentType || '').toLowerCase();

// Check if this agent is allowed to use the reserved tool
const isAllowed = allowedAgents.some(
  allowed =>
    agentLower.includes(allowed.toLowerCase()) || allowed.toLowerCase() === agentLower
);

if (!isAllowed) {
  result.valid = false;
  result.errors.push(
    `Tool '${tool}' is reserved for: ${allowedAgents.join(', ')}. ` +
      `Agent type '${agentType}' cannot use this tool.`
  );
}

function extractAgentConfig(prompt) {
  if (!prompt) {
    return { agentType: null, tools: null };
  }

  // If prompt is an object (Task params), extract directly
  if (typeof prompt === 'object') {
    return {
      agentType: prompt.subagent_type || prompt.agent_type || null,
      tools: prompt.allowed_tools || null,
    };
  }

  // If prompt is a string, try to extract from text
  const config = { agentType: null, tools: null };

  // Extract subagent_type
  const typeMatch = prompt.match(/subagent_type:\s*['"]?([a-zA-Z_-]+)['"]?/);
  if (typeMatch) {
    config.agentType = typeMatch[1];
  }

  // Try to extract from "You are DEVELOPER" pattern
  const roleMatch = prompt.match(/You are (?:the )?([A-Z_-]+)/);
  if (roleMatch && !config.agentType) {
    config.agentType = roleMatch[1].toLowerCase();
  }

  // Extract allowed_tools (basic parsing)
  const toolsMatch = prompt.match(/allowed_tools:\s*\[([^\]]+)\]/);
  if (toolsMatch) {
    try {
      // Try to parse as JSON-like array
      const toolsStr = '[' + toolsMatch[1].replace(/'/g, '"') + ']';
      config.tools = JSON.parse(toolsStr);
    } catch {
      // Fallback: split by comma
      config.tools = toolsMatch[1]
        .split(',')
        .map(t => t.trim().replace(/['"]/g, ''))
        .filter(t => t);
    }
  }

  return config;
}

function generateSuggestions(errors) {
  const manifest = loadManifest();
  const suggestions = [];

  for (const error of errors) {
    // MCP tool unavailable - suggest fallback
    if (error.includes('mcp__') && error.includes('unavailable')) {
      const toolMatch = error.match(/mcp__([^']+)/);
      if (toolMatch) {
        const mcpTool = 'mcp__' + toolMatch[1];
        const mcpInfo = getMcpToolInfo(mcpTool, manifest);

        if (mcpInfo?.fallback) {
          suggestions.push(mcpInfo.fallback);
        } else if (mcpTool.includes('sequential-thinking')) {
          suggestions.push("Use Skill({ skill: 'sequential-thinking' }) instead");
        } else if (mcpTool.includes('Exa')) {
          suggestions.push('Use WebSearch as fallback for Exa tools');
        }
      }
    }

    // Reserved tool - suggest using appropriate agent
    if (error.includes('reserved for')) {
      if (error.includes('Task')) {
        suggestions.push('Developers cannot spawn subagents. Use orchestrators instead.');
      }
      if (error.includes('AskUserQuestion')) {
        suggestions.push('Only the router can ask user questions.');
      }
    }

    // Too many tools - suggest removing optional tools
    if (error.includes('maximum')) {
      suggestions.push(
        'Remove optional tools like EnterPlanMode, ExitPlanMode, or WebSearch/WebFetch ' +
          'if not needed for this agent.'
      );
    }

    // Unknown tool - suggest checking spelling
    if (error.includes('not found')) {
      suggestions.push('Check tool name spelling. See CLAUDE.md section 1.4 for available tools.');
    }
  }

  return suggestions;
}

async function main() {
  try {
    const mode = getEnforcementMode(ENFORCEMENT_ENV, DEFAULT_MODE);

    // If hook is disabled, allow all
    if (mode === 'off') {
      process.exit(0);
    }

    const hookInput = await parseHookInputAsync();

    // Only validate Task tool (agent spawning)
    const toolName = getToolName(hookInput);
    if (toolName !== 'Task') {
      process.exit(0); // Allow (not spawning agent)
    }

    const toolInput = getToolInput(hookInput);

    // Extract agent configuration from Task parameters
    const allowedTools = toolInput.allowed_tools || null;
    const agentType = toolInput.subagent_type || toolInput.description || 'unknown';

    // If no tools specified, allow (backward compatible)
    if (!allowedTools) {
      process.exit(0);
    }

    // Validate tools
    const validation = validateToolConfig({
      tools: allowedTools,
      agentType: agentType,
    });

    // Handle validation result
    if (!validation.valid) {
      const suggestions = generateSuggestions(validation.errors);
      const message =
        `[PRE-SPAWN-VALIDATOR] Tool validation failed:\n` +
        `  Errors: ${validation.errors.join('; ')}\n` +
        `  Suggestions: ${suggestions.join('; ')}`;

      auditLog('pre-spawn-tool-validator', 'block', {
        tool: toolName,
        agentType,
        errors: validation.errors,
        suggestions,
      });

      if (mode === 'block') {
        try {
          await eventBus.emit(EventTypes.TOOL_BLOCKED, {
            type: EventTypes.TOOL_BLOCKED,
            timestamp: new Date().toISOString(),
            toolName: 'Task',
            reason: 'pre_spawn_tool_validation_failed',
          });
        } catch (_err) {
          // Best-effort
        }
        console.log(formatResult('block', message));
        process.exit(2);
      } else {
        // warn mode
        console.warn(message);
      }
    }

    // Log warnings
    if (validation.warnings.length > 0) {
      auditLog('pre-spawn-tool-validator', 'warn', {
        tool: toolName,
        agentType,
        warnings: validation.warnings,
      });

      for (const warning of validation.warnings) {
        console.warn(`[PRE-SPAWN-VALIDATOR] Warning: ${warning}`);
      }
    }

    process.exit(0); // Allow
  } catch (err) {
    auditLog('pre-spawn-tool-validator', 'error', { error: err.message });
    // Fail open on error (don't block legitimate spawns due to hook errors)
    process.exit(0);
  }
}

function getMemoryManager() {
  if (memoryManager === null) {
    try {
      memoryManager = require('../../lib/memory/memory-manager.cjs');
    } catch (_e) {
      memoryManager = false; // Mark as unavailable
    }
  }
  return memoryManager || null;
}

function extractTaskDescription(toolInput) {
  if (!toolInput) return 'Task spawned';

  // Try to get description from various possible fields
  if (toolInput.description) return toolInput.description;
  if (toolInput.prompt) {
    // Extract first line or truncate
    const firstLine = toolInput.prompt.split('\n')[0];
    return firstLine.length > 100 ? firstLine.slice(0, 100) + '...' : firstLine;
  }
  if (toolInput.subagent_type) return `${toolInput.subagent_type} agent`;

  return 'Task spawned';
}

function isPlannerSpawn(toolInput) {
  if (!toolInput) return false;

  const subagentType = (toolInput.subagent_type || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();
  const prompt = toolInput.prompt || '';

  if (subagentType.includes('plan')) return true;
  if (description.includes('planner')) return true;
  if (prompt.includes('You are PLANNER') || prompt.includes('You are the PLANNER')) return true;

  return false;
}

function isSecuritySpawn(toolInput) {
  if (!toolInput) return false;

  const subagentType = (toolInput.subagent_type || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();
  const prompt = toolInput.prompt || '';

  if (subagentType.includes('security')) return true;
  if (description.includes('security')) return true;
  if (prompt.includes('SECURITY-ARCHITECT')) return true;

  return false;
}

function runAgentContextTracker(toolInput) {
  const description = extractTaskDescription(toolInput);

  // FIX-ROUTER-MONITORING-001 (2026-01-31):
  // DO NOT exit agent mode here. Task() spawns subagent asynchronously.
  // Router must remain in agent mode until:
  //   1. Subagent completes work
  //   2. SessionEnd hook fires to clean up agent mode
  //
  // Previous code caused immediate exit, losing monitoring of spawned agents.
  // Subagents were running invisible to router, causing:
  //   - Tasks stuck in in_progress forever
  //   - Duplicate agent spawning
  //   - Projects appearing abandoned mid-stream
  //
  // const _state = routerState.exitAgentMode(); // ❌ REMOVED - was breaking monitoring

  // Detect and mark special agent spawns
  if (isPlannerSpawn(toolInput)) {
    routerState.markPlannerSpawned();
    if (process.env.ROUTER_DEBUG === 'true') {
      console.error('[post-task-unified] PLANNER agent detected and marked');
    }
  }

  if (isSecuritySpawn(toolInput)) {
    routerState.markSecuritySpawned();
    if (process.env.ROUTER_DEBUG === 'true') {
      console.error('[post-task-unified] SECURITY-ARCHITECT agent detected and marked');
    }
  }

  if (process.env.ROUTER_DEBUG === 'true') {
    console.error(
      '[post-task-unified] Agent mode KEPT ACTIVE (router waiting for subagent completion)'
    );
    console.error(`[post-task-unified] Task description: ${description}`);
  }
}

function isWorkflowComplete(text) {
  if (!text || typeof text !== 'string') return false;
  const lower = text.toLowerCase();
  return WORKFLOW_COMPLETE_MARKERS.some(marker => lower.includes(marker));
}

function extractLearnings(text) {
  if (!text || typeof text !== 'string') return [];

  const learnings = [];

  for (const pattern of LEARNING_PATTERNS) {
    let match;
    pattern.lastIndex = 0;
    while ((match = pattern.exec(text)) !== null) {
      if (match[1] && match[1].length > 10 && match[1].length < 500) {
        learnings.push(match[1].trim());
      }
    }
    pattern.lastIndex = 0;
  }

  return [...new Set(learnings)]; // Remove duplicates
}

function appendLearnings(learnings, workflowName = 'Unknown Workflow') {
  if (!learnings || learnings.length === 0) return false;

  const timestamp = new Date().toISOString().split('T')[0];
  const entry = `\n## [${timestamp}] Auto-Extracted: ${workflowName}\n\n${learnings.map(l => `- ${l}`).join('\n')}\n`;

  try {
    const dir = path.dirname(LEARNINGS_PATH);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.appendFileSync(LEARNINGS_PATH, entry);
    return true;
  } catch (err) {
    if (process.env.DEBUG_HOOKS) {
      console.error('Failed to append learnings:', err.message);
    }
    return false;
  }
}

function runWorkflowLearningExtraction(toolOutput, toolInput) {
  if (!isWorkflowComplete(toolOutput)) {
    return;
  }

  const learnings = extractLearnings(toolOutput);
  if (learnings.length > 0) {
    const workflowName = toolInput?.description || 'Workflow';
    appendLearnings(learnings, workflowName);
  }
}

function extractPatterns(output) {
  if (!output || typeof output !== 'string') return [];

  const patterns = [];
  const patternIndicators = [
    /(?:pattern|approach|solution|technique|best practice):\s*(.+)/gi,
    /(?:always|should|must|prefer)\s+(.{20,100})/gi,
    /(?:use|using)\s+(\w+)\s+(?:for|to|when)\s+(.{10,50})/gi,
  ];

  for (const regex of patternIndicators) {
    let match;
    regex.lastIndex = 0;
    while ((match = regex.exec(output)) !== null) {
      const patternText = match[1]?.trim();
      if (patternText && patternText.length > 10 && patternText.length < 200) {
        patterns.push(patternText);
      }
    }
  }

  return patterns.slice(0, 3); // Max 3 patterns per task
}

function extractGotchas(output) {
  if (!output || typeof output !== 'string') return [];

  const gotchas = [];
  const gotchaIndicators = [
    /(?:gotcha|pitfall|warning|caution|watch out|careful):\s*(.+)/gi,
    /(?:don't|do not|never|avoid)\s+(.{20,100})/gi,
    /(?:bug|issue|problem):\s*(.{20,150})/gi,
    /(?:fixed|resolved)\s+(?:by|with)\s+(.{20,100})/gi,
  ];

  for (const regex of gotchaIndicators) {
    let match;
    regex.lastIndex = 0;
    while ((match = regex.exec(output)) !== null) {
      const gotchaText = match[1]?.trim();
      if (gotchaText && gotchaText.length > 10 && gotchaText.length < 200) {
        gotchas.push(gotchaText);
      }
    }
  }

  return gotchas.slice(0, 3); // Max 3 gotchas per task
}

function extractDiscoveries(output) {
  if (!output || typeof output !== 'string') return [];

  const discoveries = [];
  const filePatterns = [
    /`([^`]+\.[a-z]{2,4})`[:\s-]+(.{10,100})/gi,
    /(?:file|module|component)\s+`?([^\s`]+\.[a-z]{2,4})`?\s+(?:is|handles|contains|manages)\s+(.{10,80})/gi,
  ];

  for (const regex of filePatterns) {
    let match;
    regex.lastIndex = 0;
    while ((match = regex.exec(output)) !== null) {
      const filePath = match[1]?.trim();
      const description = match[2]?.trim();
      if (filePath && description && !filePath.includes(' ')) {
        discoveries.push({ path: filePath, description });
      }
    }
  }

  return discoveries.slice(0, 5); // Max 5 discoveries per task
}

function runSessionMemoryExtraction(toolOutput) {
  if (!toolOutput || typeof toolOutput !== 'string' || toolOutput.length < 50) {
    return;
  }

  const mm = getMemoryManager();
  if (!mm) return;

  const patterns = extractPatterns(toolOutput);
  const gotchas = extractGotchas(toolOutput);
  const discoveries = extractDiscoveries(toolOutput);

  let recorded = 0;

  for (const pattern of patterns) {
    if (mm.recordPattern && mm.recordPattern(pattern, PROJECT_ROOT)) {
      recorded++;
    }
  }

  for (const gotcha of gotchas) {
    if (mm.recordGotcha && mm.recordGotcha(gotcha, PROJECT_ROOT)) {
      recorded++;
    }
  }

  for (const discovery of discoveries) {
    if (
      mm.recordDiscovery &&
      mm.recordDiscovery(discovery.path, discovery.description, 'general', PROJECT_ROOT)
    ) {
      recorded++;
    }
  }

  if (recorded > 0 && process.env.DEBUG_HOOKS) {
    console.error(`[post-task-unified] Recorded ${recorded} items from Task output`);
  }
}

function detectsCompletion(output) {
  if (!output || typeof output !== 'string') return false;
  return COMPLETION_INDICATORS.some(pattern => pattern.test(output));
}

function runTaskCompletionGuard(toolOutput) {
  const enforcement = process.env.TASK_COMPLETION_GUARD || 'warn';
  if (enforcement === 'off') return;

  if (!toolOutput || !detectsCompletion(toolOutput)) return;

  // Check if TaskUpdate was called recently
  const wasUpdated = routerState.wasTaskUpdateCalledRecently();

  if (wasUpdated) {
    if (process.env.DEBUG_HOOKS) {
      console.error('[post-task-unified] Agent properly called TaskUpdate');
    }
    return;
  }

  // Warning - completion detected but no TaskUpdate
  console.error(formatTaskCompletionWarning(toolOutput));
}

function getEvolutionState() {
  return getCachedState(EVOLUTION_STATE_PATH, null);
}

function isEvolutionCompletion(state) {
  if (!state) return false;

  // Check if currentEvolution is in the final 'enable' phase
  if (state.currentEvolution && state.currentEvolution.phase === 'enable') {
    return true;
  }

  // Check for newly completed evolutions in array using createdAt timestamps
  if (state.evolutions && Array.isArray(state.evolutions) && state.evolutions.length > 0) {
    const lastEvolution = state.evolutions[state.evolutions.length - 1];
    const completedTime = lastEvolution.createdAt
      ? new Date(lastEvolution.createdAt).getTime()
      : lastEvolution.completedAt
        ? new Date(lastEvolution.completedAt).getTime()
        : 0;

    if (completedTime > 0) {
      // Check if completed recently (within last 5 minutes)
      const now = Date.now();
      if (now - completedTime < 5 * 60 * 1000) {
        return true;
      }
    }
  }

  return false;
}

function getLatestEvolution(state) {
  if (!state) return null;

  if (state.evolutions && Array.isArray(state.evolutions) && state.evolutions.length > 0) {
    return state.evolutions[state.evolutions.length - 1];
  }

  if (state.currentEvolution) {
    return state.currentEvolution;
  }

  return null;
}

function formatAuditEntry(evolution) {
  if (!evolution) {
    return (
      '[EVOLUTION] ' +
      new Date().toISOString() +
      ' | type=unknown | name=unknown | status=completed'
    );
  }

  const timestamp = evolution.completedAt || new Date().toISOString();
  const type = evolution.type || 'unknown';
  const name = evolution.name || 'unknown';
  const artifactPath = evolution.path || evolution.artifactPath || 'unknown';
  const researchReport = evolution.researchReport || 'none';

  const parts = [
    '[EVOLUTION]',
    timestamp,
    '| type=' + type,
    '| name=' + name,
    '| path=' + artifactPath,
    '| research=' + researchReport,
    '| status=completed',
  ];

  return parts.join(' ');
}

function appendToAuditLog(entry) {
  try {
    const dir = path.dirname(AUDIT_LOG_PATH);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.appendFileSync(AUDIT_LOG_PATH, entry + '\n');
  } catch (e) {
    if (process.env.DEBUG_HOOKS) {
      console.error('Failed to write audit log:', e.message);
    }
  }
}

function runEvolutionAudit() {
  const enforcement = process.env.EVOLUTION_AUDIT || 'on';
  if (enforcement === 'off') return;

  const state = getEvolutionState();
  if (!isEvolutionCompletion(state)) return;

  const evolution = getLatestEvolution(state);
  const entry = formatAuditEntry(evolution);
  appendToAuditLog(entry);

  if (process.env.DEBUG_HOOKS) {
    console.error('[post-task-unified] Audit entry written:', entry);
  }
}

async function main() {
  const startTime = Date.now();
  try {
    // Parse hook input
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      process.exit(0);
      return;
    }

    // Validate this is a Task tool call
    const toolName = getToolName(hookInput);
    if (toolName !== 'Task') {
      process.exit(0);
      return;
    }

    // Get tool input and output
    const toolInput = getToolInput(hookInput);
    const toolOutput = getToolOutput(hookInput) || '';
    const toolOutputStr = typeof toolOutput === 'string' ? toolOutput : '';

    try {
      // Try to get task_id from toolInput first, then fallback to router state
      let taskId = toolInput?.task_id || toolInput?.id || null;

      // If task_id is null, retrieve from router state (generated by spawn_start)
      if (!taskId) {
        const { getCurrentSpawnTaskId, clearCurrentSpawnTaskId } = require('./router-state.cjs');
        taskId = getCurrentSpawnTaskId();
        // Clear the stored task_id after retrieving it
        if (taskId) {
          clearCurrentSpawnTaskId();
        }
      }

      const sessionId = hookInput.session_id || hookInput.sessionId || null;
      let success = true;
      let errorSnippet = null;
      if (toolOutput && typeof toolOutput === 'object' && toolOutput.error) {
        success = false;
        errorSnippet = toolOutput.error.message || String(toolOutput.error);
      }
      logSpawnEnd({ taskId, success, errorSnippet, sessionId });
    } catch (_e) {
      // best-effort
    }

    // Run all consolidated hooks
    // 1. Agent context tracking (always runs)
    runAgentContextTracker(toolInput);

    // 2. Workflow learning extraction
    runWorkflowLearningExtraction(toolOutputStr, toolInput);

    // 3. Session memory extraction
    runSessionMemoryExtraction(toolOutputStr);

    // 4. Task completion guard
    runTaskCompletionGuard(toolOutputStr);

    // 5. Evolution audit
    runEvolutionAudit();

    // Best-effort: decrement spawn depth after Task tool returns.
    // This keeps spawnDepth from monotonically increasing across a session.
    try {
      loopStateManager.decrementSpawnDepth();
    } catch (_e) {
      // Monitoring-only; never block
    }

    // Always exit 0 - post-tool hooks should never block
    try {
      await eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'Task',
        duration: Date.now() - startTime,
        output: {
          status: 'ok',
        },
      });
    } catch (_err) {
      // Best-effort
    }
    process.exit(0);
  } catch (err) {
    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'post-task-unified',
        error: err.message,
      });
    } catch (_err) {
      // Best-effort
    }
    // Fail open - post-tool hooks should never block
    if (process.env.DEBUG_HOOKS) {
      console.error('[post-task-unified] Error:', err.message);
    }
    process.exit(0);
  }
}

function loadAgents() {
  // Check cache first
  const now = Date.now();
  if (agentCache && now - agentCacheTime < AGENT_CACHE_TTL) {
    return agentCache;
  }

  const agents = [];

  function scanDir(dir) {
    if (!fs.existsSync(dir)) return;

    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        scanDir(fullPath);
      } else if (entry.name.endsWith('.md')) {
        try {
          const content = fs.readFileSync(fullPath, 'utf-8');
          const frontmatter = parseFrontmatter(content);
          if (frontmatter && frontmatter.name) {
            agents.push({
              name: frontmatter.name,
              description: frontmatter.description || '',
              skills: frontmatter.skills || [],
              priority: frontmatter.priority || 'medium',
              path: path.relative(PROJECT_ROOT, fullPath),
            });
          }
        } catch (_e) {
          // Skip invalid files
        }
      }
    }
  }

  scanDir(AGENTS_DIR);

  // Update cache
  agentCache = agents;
  agentCacheTime = now;

  return agents;
}

function parseFrontmatter(content) {
  // BUG-NEW-007 FIX: Size limit to prevent regex DoS on large files
  if (!content || content.length > 50000) return null;

  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return null;

  const yaml = match[1];
  const result = {};

  const lines = yaml.split('\n');
  let currentKey = null;
  let inArray = false;

  for (const line of lines) {
    if (line.match(/^[a-z_]+:/i)) {
      const colonIndex = line.indexOf(':');
      currentKey = line.slice(0, colonIndex).trim();
      const value = line.slice(colonIndex + 1).trim();

      if (value === '') {
        result[currentKey] = [];
        inArray = true;
      } else if (value.startsWith('[')) {
        result[currentKey] = value
          .slice(1, -1)
          .split(',')
          .map(s => s.trim());
        inArray = false;
      } else {
        result[currentKey] = value;
        inArray = false;
      }
    } else if (inArray && line.match(/^\s+-\s/)) {
      result[currentKey].push(line.replace(/^\s+-\s/, '').trim());
    }
  }

  return result;
}

function detectPlanningRequirement(prompt) {
