  ];

  // Keywords that indicate security review is mandatory
  const securityMandatoryKeywords = [
    'auth',
    'authentication',
    'authorization',
    'login',
    'password',
    'token',
    'jwt',
    'oauth',
    'security',
    'permission',
    'role',
    'encrypt',
    'credential',
    'secret',
