    'financial',
  ];

  // Keywords that indicate architect review is needed
  const architectKeywords = [
    'integrate',
    'integration',
    'api',
    'database',
    'schema',
    'refactor',
    'architecture',
    'pattern',
    'structure',
    'scale',
    'migrate',
    'migration',
    'external',
    'codebase',
  ];

  // Keywords for epic complexity (major undertakings)
  const epicKeywords = [
    'rewrite',
    'rebuild',
    'major refactor',
    'new system',
    'microservice',
    'monolith',
    'platform',
    'framework',
    'multi-tenant',
    'multi-region',
    'distributed',
    'audit',
    'comprehensive review',
    'all hooks',
    'all agents',
    'all workflows',
    'all skills',
    'framework',
    'system-wide',
    'entire codebase',
    'everything',
  ];

  // Multi-scope patterns that MUST trigger EPIC complexity
  // These patterns indicate requests spanning multiple framework domains
  const multiScopePatterns = [
    /\ball\b.*\b(review|audit|check|validate)/i,
    /\b(review|audit|check)\b.*\ball\b/i,
    /multiple.*(agent|review|audit)/i,
    /(agents|workflows|hooks|skills|schemas).*and.*(agents|workflows|hooks|skills|schemas)/i,
    /etc\./i, // Enumeration indicator (e.g., "hooks, commands, etc.")
    /deep dive.*everything/i,
    /\ball\s+other\s+items/i, // "all other items"
    /\beverything\b.*\b(review|audit|check)/i,
    /\b(review|audit|check)\b.*\beverything\b/i,
  ];

  // Domain keywords for multi-domain detection
  const domainKeywords = [
    'router',
    'workflow',
    'hook',
    'skill',
    'agent',
    'schema',
    'memory',
    'command',
    'template',
    'config',
    'context',
  ];

  // Count matches
  const trivialMatches = trivialKeywords.filter(k => promptLower.includes(k)).length;
  const lowMatches = lowKeywords.filter(k => promptLower.includes(k)).length;
  const complexMatches = complexPlanningKeywords.filter(k => promptLower.includes(k)).length;
  const securityMatches = securityMandatoryKeywords.filter(k => promptLower.includes(k)).length;
  const architectMatches = architectKeywords.filter(k => promptLower.includes(k)).length;
  const epicMatches = epicKeywords.filter(k => promptLower.includes(k)).length;

  // Check multi-scope patterns (any match = EPIC)
  const multiScopeMatch = multiScopePatterns.some(pattern => pattern.test(prompt));

  // Count domain keyword matches for multi-domain detection
  const domainMatches = domainKeywords.filter(k => promptLower.includes(k)).length;

  // Word count analysis for verbose multi-scope requests
  const wordCount = prompt.split(/\s+/).length;

  // Determine complexity level
  let complexity = 'trivial'; // Default to trivial
  let requiresArchitectReview = false;
  let requiresSecurityReview = false;

  // EPIC complexity triggers (checked first, highest priority)
  // 1. Explicit multi-scope pattern match
  // 2. Multiple domains mentioned (4+)
  // 3. High word count combined with complex keywords
  // 4. Original epic keywords
  if (
    multiScopeMatch ||
    domainMatches >= 4 ||
    (wordCount > 30 && complexMatches >= 1) ||
    epicMatches >= 1 ||
    (architectMatches >= 2 && complexMatches >= 3)
  ) {
    complexity = 'epic';
    requiresArchitectReview = true;
  }
  // High complexity: architecture, security, multi-agent
  else if (complexMatches >= 2 || securityMatches >= 1 || architectMatches >= 2) {
    complexity = 'high';
    requiresArchitectReview = architectMatches >= 1 || complexMatches >= 2;
  }
  // Medium complexity: multi-file changes, features
  else if (complexMatches >= 1 || architectMatches >= 1) {
    complexity = 'medium';
  }
  // Low complexity: single-file fixes, minor changes
  else if (lowMatches >= 1 || (prompt.length > 20 && trivialMatches === 0)) {
    complexity = 'low';
  }
  // Trivial: greetings, questions (default, or explicit match)
  // Already set to 'trivial' by default

  // Security flag
  if (securityMatches >= 1) {
    requiresSecurityReview = true;
  }

  // Investigation patterns always require PLANNER
  const investigationPatterns = [
    /investigat.*why/i,
    /why.*not.*working/i,
    /debug.*enforcement/i,
    /fix.*hook/i,
    /router.*broken/i,
    /enforcement.*fail/i,
  ];
  if (investigationPatterns.some(p => p.test(prompt))) {
    complexity = 'high';
  }

  // Save complexity to router-state
  routerState.setComplexity(complexity);
  if (requiresSecurityReview) {
    routerState.setSecurityRequired(true);
  }

  return {
    complexity,
    requiresArchitectReview,
    requiresSecurityReview,
    multiAgentRequired: requiresArchitectReview || requiresSecurityReview,
  };
}

function applyDisambiguation(promptLower, candidates) {
  // Find which disambiguation keywords are in the prompt
  for (const [keyword, rules] of Object.entries(DISAMBIGUATION_RULES)) {
    if (!promptLower.includes(keyword)) continue;

    // Check each rule for this keyword
    for (const rule of rules) {
      const hasCondition = rule.condition.some(c => promptLower.includes(c));
      if (!hasCondition) continue;

      // Apply score adjustments
      for (const candidate of candidates) {
        if (candidate.agent.name === rule.prefer) {
          candidate.score += 3; // Boost preferred agent
          candidate.disambiguated = true;
        } else if (candidate.agent.name === rule.deprioritize) {
          candidate.score -= 1; // Slight penalty for deprioritized
          candidate.disambiguated = true;
        }
      }
    }
  }

  // Re-sort after disambiguation
  candidates.sort((a, b) => b.score - a.score);
  return candidates;
}

function main() {
  // PERF-006/PERF-007: Use shared hook-input.cjs utility
  const hookInput = parseHookInputSync();

  // Get the user prompt
  let userPrompt = '';
  if (hookInput && hookInput.prompt) {
    userPrompt = hookInput.prompt;
  } else if (hookInput && hookInput.message) {
    userPrompt = hookInput.message;
  }

  // Skip routing suggestions for very short prompts or meta commands
  if (!userPrompt || userPrompt.length < 10) {
    process.exit(0);
  }

  // Skip for slash commands (handled by skill system)
  if (userPrompt.trim().startsWith('/')) {
    process.exit(0);
  }

  // Load agents and score
  const agents = loadAgents();
  if (agents.length === 0) {
    // No agents found, skip routing
    process.exit(0);
  }

  const classification = classifyIntent(userPrompt);
  const { candidates, intent } = scoreAgents(userPrompt, agents, classification);
  const planningReq = detectPlanningRequirement(userPrompt);

  // Only show routing info if we have a clear recommendation
  if (candidates.length > 0 && candidates[0].score > 2) {
    console.log('\n┌─────────────────────────────────────────────────┐');
    console.log('│ 🔀 ROUTER ANALYSIS                              │');
    console.log('├─────────────────────────────────────────────────┤');
    const displayIntent = classification.intent || intent;
    console.log(`│ Intent: ${displayIntent.padEnd(39)} │`);
    console.log(`│ Complexity: ${planningReq.complexity.padEnd(36)} │`);
    console.log('│ Recommended agents:                             │');
    for (let i = 0; i < Math.min(3, candidates.length); i++) {
      const c = candidates[i];
      if (c.score > 0) {
        const line = `│  ${i + 1}. ${c.agent.name} (score: ${c.score})`.padEnd(50) + '│';
        console.log(line);
      }
    }

    // Show multi-agent planning requirements
    if (planningReq.multiAgentRequired) {
      console.log('├─────────────────────────────────────────────────┤');
      console.log('│ ⚠️  MULTI-AGENT PLANNING REQUIRED               │');
      if (planningReq.requiresArchitectReview) {
        console.log('│  → Architect review: REQUIRED                   │');
      }
      if (planningReq.requiresSecurityReview) {
        console.log('│  → Security review: REQUIRED                    │');
      }
      console.log('│                                                 │');
      console.log('│ Phases: Explore → Plan → Review → Consolidate  │');
    }

    console.log('│                                                 │');
    console.log('│ Use Task tool to spawn: ' + candidates[0].agent.name.padEnd(24) + '│');
    console.log('└─────────────────────────────────────────────────┘\n');
  }

  // Always allow (advisory mode)
  process.exit(0);
}

function detectDocumentationIntent(text) {
  const textLower = text.toLowerCase();
  const matchedKeywords = [];

  // Check high-confidence keywords
  for (const keyword of DOC_KEYWORDS_HIGH) {
    if (textLower.includes(keyword)) {
      matchedKeywords.push(keyword);
    }
  }

  if (matchedKeywords.length > 0) {
    return {
      isDocTask: true,
      confidence: 'high',
      matchedKeywords,
    };
  }

  // Check medium-confidence keywords
  for (const keyword of DOC_KEYWORDS_MEDIUM) {
    if (textLower.includes(keyword)) {
      matchedKeywords.push(keyword);
    }
  }

  // For medium keywords, require at least 2 matches or presence of "write" or "create"
  if (
    matchedKeywords.length >= 2 ||
    (matchedKeywords.length >= 1 && (textLower.includes('write') || textLower.includes('create')))
  ) {
    return {
      isDocTask: true,
      confidence: 'medium',
      matchedKeywords,
    };
  }

  return {
    isDocTask: false,
    confidence: 'low',
    matchedKeywords,
  };
}

function isTechWriterSpawn(toolInput) {
  const prompt = (toolInput.prompt || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();

  // Check prompt patterns
  for (const pattern of TECH_WRITER_PATTERNS.prompt) {
    if (prompt.includes(pattern)) {
      return true;
    }
  }

  // Check description patterns
  for (const pattern of TECH_WRITER_PATTERNS.description) {
    if (description.includes(pattern)) {
      return true;
    }
  }

  return false;
}

function formatViolationMessage(matchedKeywords, confidence) {
  return `[DOCUMENTATION ROUTING VIOLATION] Documentation task detected (${confidence} confidence).
Keywords matched: ${matchedKeywords.join(', ')}

Documentation tasks should be routed to technical-writer agent:
  Task({ subagent_type: 'general-purpose', description: 'Technical writer creating docs...',
         prompt: 'You are TECHNICAL-WRITER...' })

Set DOCUMENTATION_ROUTING_GUARD=off to disable (not recommended).`;
}

function validate(toolInput) {
  // Check enforcement mode
  const enforcement = process.env.DOCUMENTATION_ROUTING_GUARD || 'block';
  if (enforcement === 'off') {
    return { valid: true };
  }

  // Get the prompt being sent to the spawned agent
  const prompt = toolInput.prompt || '';
  const description = toolInput.description || '';
  const combinedText = `${prompt} ${description}`;

  // Detect if this is a documentation task
  const detection = detectDocumentationIntent(combinedText);

  if (!detection.isDocTask) {
    // Not a documentation task, allow
    return { valid: true };
  }

  // This is a documentation task - check if technical-writer is being spawned
  const isTechWriter = isTechWriterSpawn(toolInput);

  if (isTechWriter) {
    // Technical-writer is being spawned - allow
    return { valid: true };
  }

  // Documentation task but NOT spawning technical-writer
  const message = formatViolationMessage(detection.matchedKeywords, detection.confidence);

  return {
    valid: enforcement !== 'block',
    error: message,
  };
}

async function main() {
  try {
    // Check enforcement mode early
    const enforcement = process.env.DOCUMENTATION_ROUTING_GUARD || 'block';
    if (enforcement === 'off') {
      console.log(JSON.stringify({ result: 'allow', message: 'DOCUMENTATION_ROUTING_GUARD=off' }));
      process.exit(0);
    }

    // Parse the hook input
    const hookInput = await parseHookInput();

    if (!hookInput) {
      // No input provided - fail open
      console.log(JSON.stringify({ result: 'allow', message: 'No input provided' }));
      process.exit(0);
    }

    // PERF-006: Verify this is a Task tool call using shared helper
    const toolName = getToolName(hookInput);
    if (toolName !== 'Task') {
      // Not a Task tool - should not happen but fail open
      console.log(JSON.stringify({ result: 'allow', message: 'Not a Task tool call' }));
      process.exit(0);
    }

    // PERF-006: Get tool input using shared helper
    const toolInput = getToolInput(hookInput);

    // Validate
    const result = validate(toolInput);

    if (!result.valid) {
      // Block mode - output error and exit with code 2
      try {
        await eventBus.emit(EventTypes.TOOL_BLOCKED, {
          type: EventTypes.TOOL_BLOCKED,
          timestamp: new Date().toISOString(),
          toolName: 'Task',
          reason: 'documentation_routing_violation',
        });
      } catch (_err) {
        // Best-effort
      }
      console.log(JSON.stringify({ result: 'block', message: result.error }));
      process.exit(2);
    }

    // Warn mode or allowed
    if (result.error) {
      // Warn mode - show warning but allow
      console.log(JSON.stringify({ result: 'warn', message: result.error }));
    } else {
      console.log(
        JSON.stringify({ result: 'allow', message: 'Documentation routing check passed' })
      );
    }

    process.exit(0);
  } catch (err) {
    // Fail open on errors to avoid blocking legitimate work
    if (process.env.DEBUG_HOOKS) {
      console.error('Documentation routing guard error:', err.message);
      console.error('Stack trace:', err.stack);
    }
    console.log(JSON.stringify({ result: 'allow', message: 'Error - failing open' }));
    process.exit(0);
  }
}

function extractTaskId(prompt) {
  if (!prompt || typeof prompt !== 'string') return null;

  for (const pattern of TASK_ID_PATTERNS) {
    const match = prompt.match(pattern);
    if (match && match[1]) {
      return match[1];
    }
  }

  return null;
}

function loadTasks(projectRoot) {
  const tasksFile = path.join(projectRoot, '.claude/context/tasks.json');

  if (!fs.existsSync(tasksFile)) {
    return [];
  }

  try {
    const content = fs.readFileSync(tasksFile, 'utf8');
    const data = JSON.parse(content);
    return data.tasks || [];
  } catch (error) {
    console.error('[PRE-SPAWN-VALIDATOR] Failed to load tasks.json:', error.message);
    return [];
  }
}

function findTaskById(tasks, taskId) {
  return tasks.find(t => String(t.id) === String(taskId)) || null;
}

function matchTaskByDescription(tasks, description) {
  if (!description || typeof description !== 'string') return null;

  const descLower = description.toLowerCase();
  const keywords = descLower.split(/\s+/).filter(w => w.length > 3);

  // Score each pending task by keyword matches
  let bestMatch = null;
  let bestScore = 0;

  for (const task of tasks) {
    if (task.status !== 'pending') continue;

    const taskText = `${task.subject || ''} ${task.description || ''}`.toLowerCase();
    let score = 0;

    for (const keyword of keywords) {
      if (taskText.includes(keyword)) {
        score++;
      }
    }

    if (score > bestScore && score >= 2) {
      // Require at least 2 keyword matches
      bestScore = score;
      bestMatch = task;
    }
  }

  return bestMatch;
}

function logSpawnAttempt(projectRoot, entry) {
  const auditLog = path.join(projectRoot, '.claude/context/metrics/spawn-audit.jsonl');
  const dir = path.dirname(auditLog);

  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  const line = JSON.stringify({
    timestamp: new Date().toISOString(),
    ...entry,
  });

  fs.appendFileSync(auditLog, line + '\n', 'utf8');
}

async function PreToolUse(input) {
  const { tool, parameters = {}, context = {} } = input;

  // Only validate Task tool
  if (tool !== 'Task') {
    return { allowed: true };
  }

  // Check for override flag
  if (process.env.NO_TRACK_ENFORCEMENT === 'true') {
    return { allowed: true, reason: 'NO_TRACK_ENFORCEMENT override' };
  }

  const projectRoot = context.PROJECT_ROOT || process.cwd();
  const { prompt = '', description = '', subagent_type = 'unknown' } = parameters;

  // Extract task ID from prompt
  const taskId = extractTaskId(prompt);

  // Load existing tasks
  const tasks = loadTasks(projectRoot);

  if (tasks.length === 0) {
    const reason = 'No tasks file found. Cannot spawn agent without TaskCreate first.';
    logSpawnAttempt(projectRoot, {
      tool,
      taskId: taskId || 'none',
      allowed: false,
      reason,
      agentType: subagent_type,
    });
    return { allowed: false, reason };
  }

  // Try to find task by ID
  let matchedTask = null;
  if (taskId) {
    matchedTask = findTaskById(tasks, taskId);
  }

  // Fallback: Try keyword matching
  if (!matchedTask) {
    matchedTask = matchTaskByDescription(tasks, description || prompt);
  }

  if (!matchedTask) {
    const reason = taskId
      ? `Task #${taskId} not found in tasks.json. Create task with TaskCreate before spawning.`
      : 'Cannot spawn agent without TaskCreate first. Expected task ID in prompt (e.g., "Task #72").';

    logSpawnAttempt(projectRoot, {
      tool,
      taskId: taskId || 'none',
      allowed: false,
      reason,
      agentType: subagent_type,
      attemptedMatch: description.substring(0, 100),
    });

    return { allowed: false, reason };
  }

  // Task found - allow spawn
  logSpawnAttempt(projectRoot, {
    tool,
    taskId: matchedTask.id,
    allowed: true,
    reason: `Matched task #${matchedTask.id}: ${matchedTask.subject}`,
    agentType: subagent_type,
  });

  return { allowed: true };
}

function invalidateCachedState() {
  // Also invalidate router-state's internal cache
  routerState.invalidateStateCache();
}

function getLoopState() {
  // Backward-compatible helper kept for tests/exports.
  return loopStateManager.getState();
}

function isPlannerSpawn(toolInput) {
  const prompt = (toolInput.prompt || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();

  for (const pattern of PLANNER_PATTERNS.prompt) {
    if (prompt.includes(pattern)) return true;
  }
  for (const pattern of PLANNER_PATTERNS.description) {
    if (description.includes(pattern)) return true;
  }
  return false;
}

function isSecuritySpawn(toolInput) {
  const prompt = (toolInput.prompt || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();

  for (const pattern of SECURITY_PATTERNS.prompt) {
    if (prompt.includes(pattern)) return true;
  }
  for (const pattern of SECURITY_PATTERNS.description) {
    if (description.includes(pattern)) return true;
  }
  return false;
}

function isImplementationAgentSpawn(toolInput) {
  const prompt = (toolInput.prompt || '').toLowerCase();
  return IMPLEMENTATION_AGENTS.some(
    agent => prompt.includes(`you are ${agent}`) || prompt.includes(`you are the ${agent}`)
  );
}

function extractTaskDescription(toolInput) {
  if (!toolInput) return 'agent task';

  if (toolInput.description) return toolInput.description;
  if (toolInput.prompt) {
    const firstLine = toolInput.prompt.split('\n')[0];
    return firstLine.length > 100 ? firstLine.slice(0, 100) + '...' : firstLine;
  }
  if (toolInput.subagent_type) return `${toolInput.subagent_type} agent`;

  return 'agent task';
}

function extractAgentType(prompt, description) {
  const combined = `${prompt} ${description}`.toLowerCase();

  const agentTypes = [
    'developer',
    'planner',
    'architect',
    'qa',
    'security-architect',
    'devops',
    'technical-writer',
    'evolution-orchestrator',
    'reflection-agent',
  ];

  for (const type of agentTypes) {
    if (combined.includes(type)) {
      return type;
    }
  }

  const youAreMatch = combined.match(/you are (?:the )?(\w+(?:-\w+)*)/i);
  if (youAreMatch) {
    return youAreMatch[1].toLowerCase();
  }

  return 'unknown';
}

function isEvolutionTrigger(prompt) {
  if (!prompt) return false;
  const lower = prompt.toLowerCase();
  return EVOLUTION_TRIGGERS.some(t => lower.includes(t.toLowerCase()));
}

function detectEvolutionType(prompt) {
  if (!prompt) return null;
  const lower = prompt.toLowerCase();

  for (const [type, patterns] of Object.entries(EVOLUTION_TYPES)) {
    if (patterns.some(p => lower.includes(p))) {
      return type;
    }
  }
  return null;
}

function getDepthLimit() {
  const envDepth = process.env.LOOP_DEPTH_LIMIT;
  if (envDepth) {
    const parsed = parseInt(envDepth, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return DEFAULT_DEPTH_LIMIT;
}

function getPatternThreshold() {
  const envThreshold = process.env.LOOP_PATTERN_THRESHOLD;
  if (envThreshold) {
    const parsed = parseInt(envThreshold, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return DEFAULT_PATTERN_THRESHOLD;
}

function getEvolutionBudget() {
  const envBudget = process.env.LOOP_EVOLUTION_BUDGET;
  if (envBudget) {
    const parsed = parseInt(envBudget, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return DEFAULT_EVOLUTION_BUDGET;
}

function getCooldownMs() {
  const envCooldown = process.env.LOOP_COOLDOWN_MS;
  if (envCooldown) {
    const parsed = parseInt(envCooldown, 10);
    if (!isNaN(parsed) && parsed >= 0) return parsed;
  }
  return DEFAULT_COOLDOWN_MS;
}

function checkTaskListFirst(toolName) {
  if (toolName !== 'Task') {
    return { pass: true };
  }
  const mode = (process.env.TASKLIST_FIRST_ENFORCEMENT || 'block').toLowerCase();
  if (mode === 'off') {
    return { pass: true };
  }
  if (routerState.isTaskListCalledSincePrompt()) {
    return { pass: true };
  }
  const message =
    'TaskList() must be called before Task(). Call TaskList() first, then spawn with Task().';
  if (mode === 'warn') {
    return { pass: true, result: 'warn', message };
  }
  return { pass: false, result: 'block', message };
}

function checkAgentContextPreTracker(hookInput) {
  const toolInput = getToolInput(hookInput);
  const taskDescription = extractTaskDescription(toolInput);

  // Set mode to agent BEFORE task starts
  routerState.enterAgentMode(taskDescription);

  if (process.env.ROUTER_DEBUG === 'true') {
    console.error(`[pre-task-unified:context] Pre-set mode=agent for: ${taskDescription}`);
  }

  // Always pass (tracking only)
  return { pass: true };
}

function checkRoutingGuard(toolName, toolInput) {
  // Only applies to Task tool
  if (toolName !== 'Task') {
    return { pass: true };
  }

  const state = routerState.getState();

  // Check 2a: Planner-First Guard
  const plannerEnforcement = getEnforcementMode('PLANNER_FIRST_ENFORCEMENT', 'block');
  if (plannerEnforcement !== 'off') {
    const isPlannerRequired = state.requiresPlannerFirst;
    const plannerAlreadySpawned = state.plannerSpawned;

    if (isPlannerRequired && !plannerAlreadySpawned) {
      // Check if THIS spawn is a PLANNER spawn
      if (isPlannerSpawn(toolInput)) {
        return { pass: true, markPlanner: true };
      }

      // Not a PLANNER spawn, but PLANNER is required
      const complexity = state.complexity || 'unknown';
      const message = `[PLANNER-FIRST VIOLATION] High/Epic complexity (${complexity}) requires PLANNER agent first.
Spawn PLANNER first: Task({ description: 'Planner designing...', prompt: 'You are PLANNER...' })`;

      if (plannerEnforcement === 'block') {
        return { pass: false, result: 'block', message };
      } else {
        console.warn(message);
      }
    }
  }

  // Check 2b: Security Review Guard
  const securityEnforcement = getEnforcementMode('SECURITY_REVIEW_ENFORCEMENT', 'block');
  if (securityEnforcement !== 'off') {
    if (state.requiresSecurityReview && !state.securitySpawned) {
      // Check if this is a SECURITY-ARCHITECT spawn
      if (isSecuritySpawn(toolInput)) {
        return { pass: true, markSecurity: true };
      }

      // Check if spawning an implementation agent
      if (isImplementationAgentSpawn(toolInput)) {
        const message = `[SEC-004] Security review required before implementation.
Spawn SECURITY-ARCHITECT first to review security implications.`;

        if (securityEnforcement === 'block') {
          return { pass: false, result: 'block', message };
        } else {
          console.warn(message);
        }
      }
    }
  }

  return { pass: true };
}

function checkLoopPrevention(hookInput) {
  const toolName = getToolName(hookInput);

  // Only check Task tool
  if (toolName !== 'Task') {
    return { pass: true };
  }

  const enforcement = getEnforcementMode('LOOP_PREVENTION_MODE', 'block');
  if (enforcement === 'off') {
    auditLog('pre-task-unified', 'security_override_used', {
      check: 'loop-prevention',
      override: 'LOOP_PREVENTION_MODE=off',
    });
    return { pass: true };
  }

  const toolInput = getToolInput(hookInput);
  const prompt = toolInput.prompt || '';
  const description = toolInput.description || '';
  const loopState = loopStateManager.getState();

  // Check 4a: Spawn Depth
  const depthLimit = getDepthLimit();
  if (loopState.spawnDepth >= depthLimit) {
    const message = `[LOOP PREVENTION] Spawn depth limit exceeded (${loopState.spawnDepth}/${depthLimit}). Too many nested agent spawns.

This is a safety mechanism to prevent infinite loops.`;

    if (enforcement === 'block') {
      return { pass: false, result: 'block', message };
    } else {
      console.warn(message);
    }
  }

  // Check 4b: Pattern Detection
  const agentType = extractAgentType(prompt, description);
  const spawnAction = `spawn:${agentType}`;
  const threshold = getPatternThreshold();

  const entry = loopState.actionHistory?.find(a => a.action === spawnAction);
  const count = entry ? entry.count : 0;

  if (count >= threshold) {
    const message = `[LOOP PREVENTION] Pattern detected: "${spawnAction}" repeated ${count} times. Threshold is ${threshold}.

This is a safety mechanism to prevent infinite loops.`;

    if (enforcement === 'block') {
      return { pass: false, result: 'block', message };
    } else {
      console.warn(message);
    }
  }

  // Check 4c: Evolution triggers
  if (isEvolutionTrigger(prompt)) {
    const budget = getEvolutionBudget();
    if (loopState.evolutionCount >= budget) {
      const message = `[LOOP PREVENTION] Evolution budget exhausted (${loopState.evolutionCount}/${budget}). Session limit reached.

This is a safety mechanism to prevent infinite loops.`;

      if (enforcement === 'block') {
        return { pass: false, result: 'block', message };
      } else {
        console.warn(message);
      }
    }

    // Check cooldown for specific evolution type
    const evolutionType = detectEvolutionType(prompt);
    if (evolutionType && loopState.lastEvolutions?.[evolutionType]) {
      const cooldownMs = getCooldownMs();
      const lastTime = new Date(loopState.lastEvolutions[evolutionType]).getTime();
      const elapsed = Date.now() - lastTime;
      const remainingMs = cooldownMs - elapsed;

      if (remainingMs > 0) {
        const remainingMin = Math.ceil(remainingMs / 60000);
        const message = `[LOOP PREVENTION] Cooldown period active for ${evolutionType} evolution. Wait ${remainingMin} minute(s).

This is a safety mechanism to prevent infinite loops.`;

        if (enforcement === 'block') {
          return { pass: false, result: 'block', message };
        } else {
          console.warn(message);
        }
      }
    }
  }

  return { pass: true };
}

function updateLoopStateAfterAllow(hookInput) {
  try {
    const toolInput = getToolInput(hookInput);
    const prompt = toolInput.prompt || '';
    const description = toolInput.description || '';

    const agentType = extractAgentType(prompt, description);
    loopStateManager.recordSpawn(agentType);

    if (isEvolutionTrigger(prompt)) {
      const evolutionType = detectEvolutionType(prompt) || 'unknown';
      loopStateManager.recordEvolution(evolutionType);
    }
  } catch (err) {
    auditLog('pre-task-unified', 'loop_state_update_failed', { error: err.message });
  }
}

function runAllChecks(hookInput) {
  const toolName = getToolName(hookInput);

  // Skip if not a Task tool
  if (toolName !== 'Task') {
    return { pass: true, exitCode: 0 };
  }

  // Invalidate cache for fresh state
  invalidateCachedState();

  const toolInput = getToolInput(hookInput);

  // Check 0: TaskList-first (TASKLIST_FIRST_ENFORCEMENT=block|warn|off, default block)
  const taskListFirstResult = checkTaskListFirst(toolName);
  if (!taskListFirstResult.pass) {
    return {
      pass: false,
      exitCode: taskListFirstResult.result === 'block' ? 2 : 0,
      message: taskListFirstResult.message,
    };
  }
  if (taskListFirstResult.result === 'warn') {
    console.warn(taskListFirstResult.message);
  }

  // Check 1: Agent Context Pre-Tracker (always passes, sets state)
  const _contextResult = checkAgentContextPreTracker(hookInput);
  // Note: This always passes, just sets mode

  // Check 2: Routing Guard
  const routingResult = checkRoutingGuard(toolName, toolInput);
  if (!routingResult.pass) {
    return {
      pass: false,
      exitCode: routingResult.result === 'block' ? 2 : 0,
      message: routingResult.message,
    };
  }
  // Handle planner/security markers
  if (routingResult.markPlanner) {
    routerState.markPlannerSpawned();
  }
  if (routingResult.markSecurity) {
    routerState.markSecuritySpawned();
  }

  // Check 3: Loop Prevention
  const loopResult = checkLoopPrevention(hookInput);
  if (!loopResult.pass) {
    return {
      pass: false,
      exitCode: loopResult.result === 'block' ? 2 : 0,
      message: loopResult.message,
    };
  }

  // All checks passed
  updateLoopStateAfterAllow(hookInput);
  return { pass: true, exitCode: 0 };
}

async function main() {
  const startTime = Date.now();
  try {
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      // No input - allow (fail open for missing input)
      process.exit(0);
    }

    const toolName = getToolName(hookInput);

    // Skip if not a Task tool
    if (toolName !== 'Task') {
      process.exit(0);
    }

    const result = runAllChecks(hookInput);

    if (!result.pass) {
      try {
        if (result.exitCode === 2) {
          await eventBus.emit(EventTypes.TOOL_BLOCKED, {
            type: EventTypes.TOOL_BLOCKED,
            timestamp: new Date().toISOString(),
            toolName: 'Task',
            duration: Date.now() - startTime,
            reason: result.message,
          });
        } else {
          await eventBus.emit(EventTypes.TOOL_COMPLETED, {
            type: EventTypes.TOOL_COMPLETED,
            timestamp: new Date().toISOString(),
            toolName: 'Task',
            duration: Date.now() - startTime,
            output: {
              status: 'warn',
              reason: result.message,
            },
          });
        }
      } catch (_err) {
        // Best-effort
      }
      console.log(formatResult(result.exitCode === 2 ? 'block' : 'warn', result.message));
      process.exit(result.exitCode);
    }

    // All checks passed
    try {
      await eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'Task',
        duration: Date.now() - startTime,
        output: {
          status: 'ok',
        },
      });
    } catch (_err) {
      // Best-effort
    }
    process.exit(0);
  } catch (err) {
    try {
      await eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'pre-task-unified',
        error: err.message,
      });
    } catch (_err) {
      // Best-effort
    }
    // SEC-008: Allow debug override for troubleshooting
    if (process.env.HOOK_FAIL_OPEN === 'true') {
      auditLog('pre-task-unified', 'fail_open_override', { error: err.message });
      process.exit(0);
    }

    // Audit log the error
    auditLog('pre-task-unified', 'error_fail_closed', { error: err.message });

    // SEC-008: Fail closed - deny when security state unknown
    process.exit(2);
  }
}

function main() {
  // PERF-006/PERF-007: Use shared hook-input.cjs utility
  const hookInput = parseHookInputSync();

  // Get the user prompt for logging
  let userPrompt = '';
  if (hookInput) {
    userPrompt = hookInput.prompt || hookInput.message || '';
  }

  // Skip for very short prompts or slash commands (handled elsewhere)
  if (userPrompt && userPrompt.trim().startsWith('/')) {
    process.exit(0);
  }

  // Bug fix: Check if we're in an active agent context before resetting
  // Subagents also trigger UserPromptSubmit, so we need to skip reset
  // if a task was spawned recently (within 30 minutes)
  const currentState = routerState.getState();
  if (currentState.mode === 'agent' && currentState.taskSpawned) {
    const taskSpawnedAt = currentState.taskSpawnedAt
      ? new Date(currentState.taskSpawnedAt).getTime()
      : 0;
    const isRecentTask = Date.now() - taskSpawnedAt < 30 * 60 * 1000; // 30 minutes
    if (isRecentTask) {
      // Skip reset - we're in an active agent context
      if (process.env.ROUTER_DEBUG === 'true') {
        console.log('[router-mode-reset] Skipping reset - active agent context detected');
        console.log('[router-mode-reset] Task spawned at: ' + currentState.taskSpawnedAt);
      }
      process.exit(0);
    }
  }

  // Reset state to router mode
  const state = routerState.resetToRouterMode();

  // Optional: Show state reset message in verbose mode
  if (process.env.ROUTER_DEBUG === 'true') {
    console.log('[router-mode-reset] State reset to router mode');
    console.log('[router-mode-reset] Session: ' + (state.sessionId || 'unknown'));
  }

  // Always allow - this hook only manages state
  process.exit(0);
}

function markCreatorActive(creatorName) {
  try {
    const statePath = path.join(PROJECT_ROOT, ACTIVE_CREATORS_STATE_FILE);
    const stateDir = path.dirname(statePath);

    // Ensure runtime directory exists
    if (!fs.existsSync(stateDir)) {
      fs.mkdirSync(stateDir, { recursive: true });
    }

    // Load existing state or create new
    let state = {};
    if (fs.existsSync(statePath)) {
      try {
        state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
      } catch (_e) {
        // Invalid state file, start fresh
        state = {};
      }
    }

    // Update the specific creator's state
    state[creatorName] = {
      active: true,
      invokedAt: new Date().toISOString(),
      artifactName: null, // Will be set during workflow when artifact name is determined
      ttl: DEFAULT_TTL_MS,
    };

    fs.writeFileSync(statePath, JSON.stringify(state, null, 2));

    auditLog('skill-invocation-tracker', 'creator_activated', {
      creator: creatorName,
      statePath: statePath,
    });

    return true;
  } catch (err) {
    auditLog('skill-invocation-tracker', 'state_file_error', {
      creator: creatorName,
      error: err.message,
    });
    return false;
  }
}

function extractSkillName(toolInput) {
  if (!toolInput) return null;
  // Skill tool uses 'skill' parameter
  return toolInput.skill || toolInput.name || null;
}

async function main() {
  try {
    // Parse the hook input
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      // No input - allow
      process.exit(0);
    }

    // Get tool name and input
    const toolName = getToolName(hookInput);
    const toolInput = getToolInput(hookInput);

    // Only process Skill tool invocations
    if (toolName !== 'Skill') {
      process.exit(0);
    }

    // Extract the skill name being invoked
    const skillName = extractSkillName(toolInput);

    if (!skillName) {
      // No skill name found - allow but log
      auditLog('skill-invocation-tracker', 'no_skill_name', { input: toolInput });
      process.exit(0);
    }

    // Check if this is a tracked creator skill
    if (TRACKED_CREATOR_SKILLS.includes(skillName)) {
      markCreatorActive(skillName);
    }

    // Always allow - this is a tracking hook, not a guard
    process.exit(0);
  } catch (err) {
    // Log error but don't block - this is a tracking hook
    auditLog('skill-invocation-tracker', 'error', { error: err.message });
    process.exit(0);
  }
}

function getMemoryMonitor() {
  if (memoryMonitor === null && MemoryMonitor === null) {
    try {
      MemoryMonitor = require('../../lib/utils/memory-monitor.cjs');
      memoryMonitor = MemoryMonitor.getGlobalMonitor();
      // Don't auto-start - just use for spot checks
    } catch (_err) {
      // Memory monitor not available - graceful degradation
      MemoryMonitor = false; // Mark as unavailable
      memoryMonitor = false;
    }
  }
  return memoryMonitor || null;
}

function getCachedRouterState() {
  if (_cachedRouterState === null) {
    _cachedRouterState = routerState.getState();
  }
  return _cachedRouterState;
}

function invalidateCachedState() {
  _cachedRouterState = null;
  routerState.invalidateStateCache();
}

function isAlwaysAllowedWrite(filePath) {
  if (!filePath) return false;
  const normalizedPath = path.normalize(filePath);
  return ALWAYS_ALLOWED_WRITE_PATTERNS.some(pattern => pattern.test(normalizedPath));
}

function isPlannerSpawn(toolInput) {
  const prompt = (toolInput.prompt || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();

  for (const pattern of PLANNER_PATTERNS.prompt) {
    if (prompt.includes(pattern)) return true;
  }
  for (const pattern of PLANNER_PATTERNS.description) {
    if (description.includes(pattern)) return true;
  }
  return false;
}

function isSecuritySpawn(toolInput) {
  const prompt = (toolInput.prompt || '').toLowerCase();
  const description = (toolInput.description || '').toLowerCase();

  for (const pattern of SECURITY_PATTERNS.prompt) {
    if (prompt.includes(pattern)) return true;
  }
  for (const pattern of SECURITY_PATTERNS.description) {
    if (description.includes(pattern)) return true;
  }
  return false;
}

function isImplementationAgentSpawn(toolInput) {
  const prompt = (toolInput.prompt || '').toLowerCase();
  return IMPLEMENTATION_AGENTS.some(
    agent => prompt.includes(`you are ${agent}`) || prompt.includes(`you are the ${agent}`)
  );
}

function isWhitelistedBashCommand(command) {
  if (!command || typeof command !== 'string') {
    return false;
  }
  const trimmed = command.trim();
  return ROUTER_BASH_WHITELIST.some(pattern => pattern.test(trimmed));
}

function extractTaskIdFromPrompt(prompt) {
  if (!prompt || typeof prompt !== 'string') {
    return null;
  }
  // Pattern: "Task ID: task-123" or "Your Task ID: task-456"
  const match = prompt.match(/Task ID:\s*([a-zA-Z0-9-]+)/i);
  return match ? match[1] : null;
}

function debugLog(message, data = null) {
  if (!DEBUG) return;
  const timestamp = new Date().toISOString();
  const prefix = `[${timestamp}] [routing-guard]`;
  if (data) {
    console.error(`${prefix} ${message}`, JSON.stringify(data, null, 2));
  } else {
    console.error(`${prefix} ${message}`);
  }
}

function checkPlannerFirst(toolName, toolInput) {
  // Only applies to Task tool
  if (toolName !== 'Task') {
    return { pass: true };
  }

  const enforcement = getEnforcementMode('PLANNER_FIRST_ENFORCEMENT', 'block');
  if (enforcement === 'off') {
    // SEC-AUDIT-016 FIX: Use centralized auditSecurityOverride for consistent logging
    auditSecurityOverride(
      'routing-guard',
      'PLANNER_FIRST_ENFORCEMENT',
      'off',
      'Planner-first requirement bypassed'
    );
    return { pass: true };
  }

  // PERF-001: Use cached state for planner checks
  const state = getCachedRouterState();
  const isPlannerRequired = state.requiresPlannerFirst;
  const plannerAlreadySpawned = state.plannerSpawned;

  // If planner not required or already spawned, allow
  if (!isPlannerRequired || plannerAlreadySpawned) {
    return { pass: true };
  }

  // Check if THIS spawn is a PLANNER spawn (breaks the cycle)
  if (isPlannerSpawn(toolInput)) {
    return { pass: true, markPlanner: true };
  }

  // Not a PLANNER spawn, but PLANNER is required - violation
  const complexity = state.complexity || 'unknown';
  const message = `[PLANNER-FIRST VIOLATION] High/Epic complexity (${complexity}) requires PLANNER agent first.
Spawn PLANNER first: Task({ description: 'Planner designing...', prompt: 'You are PLANNER...' })`;

  if (enforcement === 'block') {
    return { pass: false, result: 'block', message };
  } else {
    return { pass: true, result: 'warn', message };
  }
}

function checkTaskCreate(toolName) {
  // Only applies to TaskCreate tool
  if (toolName !== 'TaskCreate') {
    return { pass: true };
  }

  const enforcement = getEnforcementMode('PLANNER_FIRST_ENFORCEMENT', 'block');
  if (enforcement === 'off') {
    // SEC-AUDIT-016 FIX: Use centralized auditSecurityOverride for consistent logging
    auditSecurityOverride(
      'routing-guard',
      'PLANNER_FIRST_ENFORCEMENT',
      'off',
      'TaskCreate without planner allowed'
    );
    return { pass: true };
  }

  // PERF-001: Use cached state for task-create checks
  const state = getCachedRouterState();
  const isPlannerRequired = state.requiresPlannerFirst;
  const isPlannerSpawned = state.plannerSpawned;

  // If planner not required or already spawned, allow
  if (!isPlannerRequired || isPlannerSpawned) {
    return { pass: true };
  }

  // Violation: trying to create tasks without planner
  const complexity = state.complexity || 'unknown';
  const message = `[TASK-CREATE VIOLATION] Complex task (${complexity}) requires PLANNER agent.
Spawn PLANNER first, then PLANNER will create the tasks.`;

  if (enforcement === 'block') {
    return { pass: false, result: 'block', message };
  } else {
    return { pass: true, result: 'warn', message };
  }
}

function checkSecurityReview(toolName, toolInput) {
  // Only applies to Task tool
  if (toolName !== 'Task') {
    return { pass: true };
  }

  const enforcement = getEnforcementMode('SECURITY_REVIEW_ENFORCEMENT', 'block');
  if (enforcement === 'off') {
    return { pass: true };
  }

  // PERF-001: Use cached state for security review checks
  // Note: getCachedRouterState() handles errors internally via state-cache.cjs
  const state = getCachedRouterState();

  // Check if security review required but not done
  if (!state.requiresSecurityReview || state.securitySpawned) {
    return { pass: true };
  }

  // Check if this is a SECURITY-ARCHITECT spawn (breaks the cycle)
  if (isSecuritySpawn(toolInput)) {
    return { pass: true, markSecurity: true };
  }

  // Check if spawning an implementation agent
  if (!isImplementationAgentSpawn(toolInput)) {
    return { pass: true };
  }

  // Violation: implementation agent without security review
  const message = `[SEC-004] Security review required before implementation.
Spawn SECURITY-ARCHITECT first to review security implications.`;

  if (enforcement === 'block') {
    return { pass: false, result: 'block', message };
  } else {
    return { pass: true, result: 'warn', message };
  }
}

function checkRouterWrite(toolName, toolInput) {
  // Only applies to write tools
  if (!WRITE_TOOLS.includes(toolName)) {
    return { pass: true };
  }

  const enforcement = getEnforcementMode('ROUTER_WRITE_GUARD', 'block');
  if (enforcement === 'off') {
    // SEC-AUDIT-016 FIX: Use centralized auditSecurityOverride for consistent logging
    auditSecurityOverride(
      'routing-guard',
      'ROUTER_WRITE_GUARD',
      'off',
      'Router can write without agent context'
    );
    return { pass: true };
  }

  // Get file path
  const filePath = extractFilePath(toolInput);

  // Check if file is always allowed (framework internal)
  if (isAlwaysAllowedWrite(filePath)) {
    return { pass: true };
  }

  // Check if write is allowed (agent context)
  const { allowed, _reason } = routerState.checkWriteAllowed();
  if (allowed) {
    return { pass: true };
  }

  // Violation: write without agent context
  const fileName = filePath ? path.basename(filePath) : 'unknown';
  const message = `[ROUTER WRITE BLOCKED] Tool: ${toolName}, File: ${fileName}
The Router cannot directly edit files. Spawn an agent using the Task tool.`;

  if (enforcement === 'block') {
    return { pass: false, result: 'block', message };
  } else {
    return { pass: true, result: 'warn', message };
  }
}

function checkMemoryPressure(toolName) {
  // Only applies to Task tool (agent spawning)
  if (toolName !== 'Task') {
    return { pass: true };
  }

  // Check if memory spawn throttling is enabled
  const throttlingEnabled = process.env.MEMORY_SPAWN_THROTTLING !== 'false';
  if (!throttlingEnabled) {
    return { pass: true };
  }

  // Get memory monitor (lazy-loaded)
  const monitor = getMemoryMonitor();
  if (!monitor) {
    // Memory monitor unavailable - allow (fail-open for this optional check)
    return { pass: true };
  }

  // Perform a heap check
  monitor.checkHeap();

  // Check if we should pause spawning
  const { shouldPause, reason, stats } = monitor.shouldPauseSpawning();

  if (shouldPause) {
    const heapUsedMB = stats?.current?.heapUsedMB?.toFixed(1) || 'unknown';
    const heapLimitMB = stats?.current?.heapLimitMB?.toFixed(1) || 'unknown';
    const percentStr = stats?.current?.percent
      ? (stats.current.percent * 100).toFixed(1)
      : 'unknown';

    const message = `
+======================================================================+
|  MEMORY PRESSURE - AGENT SPAWNING PAUSED                             |
+======================================================================+
|  Heap Usage: ${heapUsedMB}MB / ${heapLimitMB}MB (${percentStr}%)
|
|  Reason: ${reason}
|
|  Actions to recover:
|    1. Wait for existing agents to complete
|    2. Reduce concurrent agent spawns
|    3. Increase NODE_OPTIONS --max-old-space-size
|    4. Set MEMORY_SPAWN_THROTTLING=false to override (not recommended)
|
|  Memory Stats:
|    - Min: ${(stats?.min * 100)?.toFixed(1) || 'N/A'}%
|    - Max: ${(stats?.max * 100)?.toFixed(1) || 'N/A'}%
|    - Avg: ${(stats?.avg * 100)?.toFixed(1) || 'N/A'}%
|    - Trend: ${stats?.trend > 0 ? '+' : ''}${(stats?.trend * 100)?.toFixed(2) || 'N/A'}%
|
+======================================================================+
`;

    // Log to audit
    auditLog('routing-guard', 'memory_pressure_block', {
      heapUsedMB,
      heapLimitMB,
      percent: percentStr,
      reason,
    });

    // Block the spawn
    return { pass: false, result: 'block', message };
  }

  // Memory is OK - emit stats for monitoring if in debug mode
  if (process.env.DEBUG_HOOKS === 'true' && stats) {
    console.error(
      `[routing-guard] Memory check passed: ${(stats.current.percent * 100).toFixed(1)}%`
    );
  }

  return { pass: true };
}

function runAllChecks(toolName, toolInput) {
  // Check 0: Router Bash Check (ADR-030 - must come first for Bash commands)
  const bashCheck = checkRouterBash(toolName, toolInput);
  if (!bashCheck.pass) {
    return { pass: false, result: bashCheck.result, message: bashCheck.message };
  }
  if (bashCheck.result === 'warn') {
    console.warn(bashCheck.message);
  }

  // Check 1: Router Self-Check (now receives toolInput for file path checking)
  const selfCheck = checkRouterSelfCheck(toolName, toolInput);
  if (!selfCheck.pass) {
    return { pass: false, result: selfCheck.result, message: selfCheck.message };
  }
  if (selfCheck.result === 'warn') {
    // Log warning but continue checks
    console.warn(selfCheck.message);
  }

  // Check 2: Planner-First Guard
  const plannerCheck = checkPlannerFirst(toolName, toolInput);
  if (!plannerCheck.pass) {
    return { pass: false, result: plannerCheck.result, message: plannerCheck.message };
  }
  if (plannerCheck.markPlanner) {
    // Mark planner as spawned in state
    routerState.markPlannerSpawned();
  }
  if (plannerCheck.result === 'warn') {
    console.warn(plannerCheck.message);
  }

  // Check 3: TaskCreate Guard
  const taskCreateCheck = checkTaskCreate(toolName);
  if (!taskCreateCheck.pass) {
    return { pass: false, result: taskCreateCheck.result, message: taskCreateCheck.message };
  }
  if (taskCreateCheck.result === 'warn') {
    console.warn(taskCreateCheck.message);
  }

  // Check 4: Security Review Guard
  const securityCheck = checkSecurityReview(toolName, toolInput);
  if (!securityCheck.pass) {
    return { pass: false, result: securityCheck.result, message: securityCheck.message };
  }
  if (securityCheck.markSecurity) {
    // Mark security as spawned in state
    routerState.markSecuritySpawned();
  }
  if (securityCheck.result === 'warn') {
    console.warn(securityCheck.message);
  }

  // Check 5: Router Write Guard
  const writeCheck = checkRouterWrite(toolName, toolInput);
  if (!writeCheck.pass) {
    return { pass: false, result: writeCheck.result, message: writeCheck.message };
  }
  if (writeCheck.result === 'warn') {
    console.warn(writeCheck.message);
  }

  // Check 6: Memory Pressure Check (for Task tool only)
  const memoryCheck = checkMemoryPressure(toolName);
  if (!memoryCheck.pass) {
    return { pass: false, result: memoryCheck.result, message: memoryCheck.message };
  }

  // All checks passed
  return { pass: true, result: 'allow', message: '' };
}

async function main() {
  const startTime = Date.now();
  try {
    // PERF-001: Invalidate cache at start of each invocation
    invalidateCachedState();

    // Parse the hook input
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      // No input - allow (fail open for missing input)
      process.exit(0);
    }

    // Get tool name and input
    const toolName = getToolName(hookInput);
    const toolInput = getToolInput(hookInput);

    // Skip if not a watched tool
    if (!toolName || !ALL_WATCHED_TOOLS.includes(toolName)) {
      process.exit(0);
    }

    // Emit TOOL_INVOKED event (P1-6.4 - async, non-blocking)
    if (eventBus) {
      try {
        eventBus.emit('TOOL_INVOKED', {
          type: 'TOOL_INVOKED',
          toolName,
          input: toolInput,
          agentId: process.env.CLAUDE_AGENT_ID || 'router',
          taskId: process.env.CLAUDE_TASK_ID || 'unknown',
          timestamp: new Date().toISOString(),
        });
      } catch (err) {
        // Graceful degradation: event emission failed, continue
        console.error('[routing-guard] Event emission failed:', err.message);
      }
    }

    // Emit AGENT_STARTED event if spawning agent (P1-6.4)
    if (toolName === 'Task' && eventBus) {
      try {
        // Extract agent type from toolInput
        const agentType = toolInput?.subagent_type || 'general-purpose';
        const taskId = extractTaskIdFromPrompt(toolInput?.prompt) || 'unknown';
        const agentId = `${agentType}-${Date.now()}`;

        eventBus.emit('AGENT_STARTED', {
          type: 'AGENT_STARTED',
          agentId,
          agentType,
          taskId,
          timestamp: new Date().toISOString(),
        });
      } catch (err) {
        // Graceful degradation
        console.error('[routing-guard] AGENT_STARTED event emission failed:', err.message);
      }
    }

    // Run all checks
    const result = runAllChecks(toolName, toolInput);

    if (!result.pass) {
      if (eventBus) {
        try {
          if (result.result === 'block') {
            await eventBus.emit(EventTypes.TOOL_BLOCKED, {
              type: EventTypes.TOOL_BLOCKED,
              timestamp: new Date().toISOString(),
              toolName,
              duration: Date.now() - startTime,
              reason: result.message,
            });
          } else {
            await eventBus.emit(EventTypes.TOOL_COMPLETED, {
              type: EventTypes.TOOL_COMPLETED,
              timestamp: new Date().toISOString(),
              toolName,
              duration: Date.now() - startTime,
              output: {
                status: result.result,
                reason: result.message,
              },
            });
          }
        } catch (_err) {
          // Best-effort
        }
      }
      // HOOK-009: Security audit log for blocked/warned actions
      auditLog('routing-guard', `security_${result.result}`, {
        tool: toolName,
        reason: result.message,
        mode: routerState.getState().mode,
      });

      // Output block/warn result
      console.log(formatResult(result.result, result.message));
      process.exit(result.result === 'block' ? 2 : 0);
    }

    // All checks passed
    if (eventBus) {
      try {
        await eventBus.emit(EventTypes.TOOL_COMPLETED, {
          type: EventTypes.TOOL_COMPLETED,
          timestamp: new Date().toISOString(),
          toolName,
          duration: Date.now() - startTime,
          output: {
            status: 'ok',
          },
        });
      } catch (_err) {
        // Best-effort
      }
    }
    process.exit(0);
  } catch (err) {
    if (eventBus) {
      try {
        await eventBus.emit(EventTypes.TOOL_FAILED, {
          type: EventTypes.TOOL_FAILED,
          timestamp: new Date().toISOString(),
          toolName: 'routing-guard',
          error: err.message,
        });
      } catch (_err) {
        // Best-effort
      }
    }
    // SEC-008: Allow debug override for troubleshooting
    if (process.env.HOOK_FAIL_OPEN === 'true') {
      auditLog('routing-guard', 'fail_open_override', { error: err.message });
      process.exit(0);
    }

    // Audit log the error
    auditLog('routing-guard', 'error_fail_closed', { error: err.message });

    // SEC-008: Fail closed - deny when security state unknown
    process.exit(2);
  }
}

function safeJSONParse(content) {
  try {
    const parsed = JSON.parse(content);

    // Only process objects (not arrays, primitives)
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
      // Create clean object without prototype
      const clean = Object.create(null);

      // Copy only own enumerable properties, excluding dangerous keys
      const dangerousKeys = ['__proto__', 'constructor', 'prototype'];
      for (const key of Object.keys(parsed)) {
        if (!dangerousKeys.includes(key)) {
          clean[key] = parsed[key];
        }
      }

      // Return as regular object
      return Object.assign({}, clean);
    }

    return parsed;
  } catch (_e) {
    return null;
  }
}

function ensureRuntimeDir() {
  const dir = path.dirname(STATE_FILE);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function getDefaultState() {
  return {
    mode: 'router',
    lastReset: null,
    taskSpawned: false,
    taskSpawnedAt: null,
    taskDescription: null,
    sessionId: process.env.CLAUDE_SESSION_ID || null,
    // TaskList-first: must call TaskList() before Task() in same session
    taskListCalledSincePrompt: false,
    // Complexity tracking fields
    complexity: 'trivial',
    requiresPlannerFirst: false,
    plannerSpawned: false,
    requiresSecurityReview: false,
    securitySpawned: false,
    // TaskUpdate tracking fields
    lastTaskUpdateCall: null,
    lastTaskUpdateTaskId: null,
    lastTaskUpdateStatus: null,
    taskUpdatesThisSession: 0,
    // Spawn task_id tracking (for spawn_end event logging)
    currentSpawnTaskId: null,
    // Optimistic concurrency version field
    version: 0,
  };
}

function getState() {
  // Read directly from disk for correctness.
  // Hooks run in separate Node processes, so cross-hook in-memory caching is ineffective.
  return loadStateFromFile();
}

function saveState(state) {
  try {
    ensureRuntimeDir();
    // Atomic write: write to temp file, then rename
    // Prevents data corruption if process crashes mid-write
    atomicWriteJSONSync(STATE_FILE, state);
    // Invalidate cache so subsequent getState() calls see the new data
    invalidateCache(STATE_FILE);
  } catch (e) {
    // Best effort - don't fail the hook if state can't be saved
    console.error('[router-state] Warning: Could not save state:', e.message);
  }
}

function validateVersion(version) {
  // Handle non-numbers
  if (typeof version !== 'number') {
    return 0;
  }
  // Handle special numeric values
  if (!Number.isFinite(version)) {
    return 0;
  }
  // Handle negative values
  if (version < 0) {
    return 0;
  }
  // Floor to handle floats
  return Math.floor(version);
}

function loadStateFromFile() {
  try {
    ensureRuntimeDir();
    if (!fs.existsSync(STATE_FILE)) {
      return getDefaultState();
    }
    const content = fs.readFileSync(STATE_FILE, 'utf-8');
    const parsed = safeJSONParse(content);
    if (parsed) {
      return { ...getDefaultState(), ...parsed };
    }
  } catch (_e) {
    // On any error, return default
  }
  return getDefaultState();
}

function syncSleep(ms) {
  // Use Atomics.wait for proper blocking (Node.js v16+)
  if (typeof SharedArrayBuffer !== 'undefined' && typeof Atomics !== 'undefined') {
    try {
      // Create a shared buffer that will never be signaled (timeout-only)
      const sharedBuffer = new SharedArrayBuffer(4);
      const int32 = new Int32Array(sharedBuffer);
      // Atomics.wait blocks the thread without CPU spin
      Atomics.wait(int32, 0, 0, ms);
      return;
    } catch (_e) {
      // Fall through to busy-wait if Atomics.wait fails
    }
  }
  // Fallback to busy-wait for older Node.js versions
  const start = Date.now();
  while (Date.now() - start < ms) {
    // Busy wait - only used when Atomics.wait unavailable
  }
}

function saveStateWithRetry(updates, retries = MAX_RETRIES) {
  for (let i = 0; i < retries; i++) {
    // Apply exponential backoff on retries (skip first attempt)
    if (i > 0) {
      const backoffMs = BASE_BACKOFF * Math.pow(2, i - 1);
      syncSleep(backoffMs);
    }

    // Step 1: Read current state directly from file
    const current = loadStateFromFile();

    // Step 2: Validate and normalize version
    const currentVersion = validateVersion(current.version);

    // Step 3: Merge updates with current state
    const merged = {
      ...current,
      ...updates,
      // Step 4: Increment version
      version: currentVersion + 1,
    };

    // Step 5: Re-read to check for conflicts
    const recheck = loadStateFromFile();
    const recheckVersion = validateVersion(recheck.version);

    // If version changed since we read, someone else wrote - retry
    if (recheckVersion !== currentVersion) {
      continue; // Conflict detected, retry
    }

    // Step 6: Write atomically
    try {
      ensureRuntimeDir();
      atomicWriteJSONSync(STATE_FILE, merged);
      invalidateCache(STATE_FILE);
      return merged;
    } catch (_e) {
      // Write failed, retry
      continue;
    }
  }

  // All retries exhausted
  throw new Error(`Save failed after ${retries} retries - concurrent modification conflict`);
}

function resetToRouterMode() {
  // Get current version to preserve it
  const current = loadStateFromFile();
  const currentVersion = validateVersion(current.version);

  const state = {
    mode: 'router',
    lastReset: new Date().toISOString(),
    taskSpawned: false,
    taskSpawnedAt: null,
    taskDescription: null,
    sessionId: process.env.CLAUDE_SESSION_ID || null,
    taskListCalledSincePrompt: false,
    // Reset complexity tracking fields
    complexity: 'trivial',
    requiresPlannerFirst: false,
    plannerSpawned: false,
    requiresSecurityReview: false,
    securitySpawned: false,
    // Reset TaskUpdate tracking fields
    lastTaskUpdateCall: null,
    lastTaskUpdateTaskId: null,
    lastTaskUpdateStatus: null,
    taskUpdatesThisSession: 0,
    // Increment version
    version: currentVersion + 1,
  };
  saveState(state);
  return state;
}

function enterAgentMode(taskDescription = null) {
