function findRequiredCreator(filePath) {
  if (!filePath) return null;

  // Normalize path separators for consistent matching
  const normalizedPath = filePath.replace(/\\/g, '/');

  for (const config of CREATOR_CONFIGS) {
    // Check exclude patterns first
    if (config.excludePatterns) {
      const excluded = config.excludePatterns.some(pattern => pattern.test(normalizedPath));
      if (excluded) continue;
    }

    // Check include patterns
    const matched = config.patterns.some(pattern => pattern.test(normalizedPath));

    if (matched) {
      return {
        creator: config.creator,
        artifactType: config.artifactType,
      };
    }
  }

  return null;
}

function isCreatorActive(creatorName) {
  try {
    const statePath = path.join(PROJECT_ROOT, STATE_FILE);
    if (!fs.existsSync(statePath)) {
      return { active: false };
    }

    const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
    const creatorState = state[creatorName];

    if (!creatorState || !creatorState.active || !creatorState.invokedAt) {
      return { active: false };
    }

    const invokedAt = new Date(creatorState.invokedAt).getTime();
    const ttl = creatorState.ttl || DEFAULT_TTL_MS;
    const elapsedMs = Date.now() - invokedAt;

    if (elapsedMs <= ttl) {
      return {
        active: true,
        invokedAt: creatorState.invokedAt,
        elapsedMs,
        artifactName: creatorState.artifactName,
      };
    }

    return { active: false, elapsedMs };
  } catch (_err) {
    return { active: false };
  }
}

function markCreatorActive(creatorName, artifactName = null) {
  try {
    const statePath = path.join(PROJECT_ROOT, STATE_FILE);
    const stateDir = path.dirname(statePath);

    // Ensure directory exists
    if (!fs.existsSync(stateDir)) {
      fs.mkdirSync(stateDir, { recursive: true });
    }

    // Load existing state or create new
    let state = {};
    if (fs.existsSync(statePath)) {
      try {
        state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
      } catch (_e) {
        // Invalid state file, start fresh
        state = {};
      }
    }

    // Update specific creator
    state[creatorName] = {
      active: true,
      invokedAt: new Date().toISOString(),
      artifactName: artifactName,
      ttl: DEFAULT_TTL_MS,
    };

    fs.writeFileSync(statePath, JSON.stringify(state, null, 2));
    return true;
  } catch (err) {
    if (process.env.DEBUG_HOOKS) {
      console.error('Failed to mark creator active:', err.message);
    }
    return false;
  }
}

function clearCreatorActive(creatorName) {
  try {
    const statePath = path.join(PROJECT_ROOT, STATE_FILE);
    if (!fs.existsSync(statePath)) return true;

    const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
    if (state[creatorName]) {
      state[creatorName].active = false;
    }

    fs.writeFileSync(statePath, JSON.stringify(state, null, 2));
    return true;
  } catch (_err) {
    return false;
  }
}

function validateCreatorWorkflow(toolName, toolInput) {
  // Only check Edit/Write tools
  if (!WATCHED_TOOLS.includes(toolName)) {
    return { pass: true };
  }

  // Check enforcement mode
  const enforcement = getEnforcementMode('CREATOR_GUARD', 'block');
  if (enforcement === 'off') {
    // SEC-AUDIT-016 FIX: Use centralized auditSecurityOverride for consistent logging
    auditSecurityOverride(
      'unified-creator-guard',
      'CREATOR_GUARD',
      'off',
      'Creator workflow requirement bypassed'
    );
    return { pass: true };
  }

  // Extract file path
  const filePath = extractFilePath(toolInput);
  if (!filePath) {
    return { pass: true };
  }

  // Check if this file requires a creator
  const required = findRequiredCreator(filePath);
  if (!required) {
    return { pass: true }; // Not a protected artifact
  }

  // Check if the required creator is active
  const creatorState = isCreatorActive(required.creator);

  if (creatorState.active) {
    return { pass: true }; // Creator workflow is active - allow
  }

  // VIOLATION: Direct write without creator workflow
  const message = generateViolationMessage(filePath, required.creator, required.artifactType);

  if (enforcement === 'block') {
    return { pass: false, result: 'block', message };
  } else {
    return { pass: true, result: 'warn', message };
  }
}

async function main() {
  try {
    // Parse the hook input
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      // No input - allow (fail open for missing input)
      process.exit(0);
    }

    // Get tool name and input
    const toolName = getToolName(hookInput);
    const toolInput = getToolInput(hookInput);

    // Skip if not a watched tool
    if (!toolName || !WATCHED_TOOLS.includes(toolName)) {
      process.exit(0);
    }

    // Emit TOOL_INVOKED event (P1-6.4 - async, non-blocking)
    if (eventBus) {
      try {
        const filePath = extractFilePath(toolInput);
        const required = findRequiredCreator(filePath);

        eventBus.emit('TOOL_INVOKED', {
          type: 'TOOL_INVOKED',
          toolName,
          input: toolInput,
          agentId: process.env.CLAUDE_AGENT_ID || 'router',
          taskId: process.env.CLAUDE_TASK_ID || 'unknown',
          timestamp: new Date().toISOString(),
          metadata: {
            hook: 'unified-creator-guard',
            artifactType: required?.artifactType || 'unknown',
            requiredCreator: required?.creator || null,
          },
        });
      } catch (err) {
        // Graceful degradation: event emission failed, continue
        console.error('[unified-creator-guard] Event emission failed:', err.message);
      }
    }

    // Validate creator workflow
    const result = validateCreatorWorkflow(toolName, toolInput);

    if (!result.pass) {
      // Log the violation
      const filePath = extractFilePath(toolInput);
      const required = findRequiredCreator(filePath);
      auditLog('unified-creator-guard', `security_${result.result}`, {
        tool: toolName,
        file: filePath,
        requiredCreator: required?.creator,
        artifactType: required?.artifactType,
        reason: 'Direct artifact write without creator workflow',
      });

      // Output block/warn result
      console.log(formatResult(result.result, result.message));
      process.exit(result.result === 'block' ? 2 : 0);
    }

    if (result.result === 'warn') {
      console.warn(result.message);
    }

    // All checks passed
    process.exit(0);
  } catch (err) {
    // SEC-008: Allow debug override for troubleshooting
    if (process.env.HOOK_FAIL_OPEN === 'true') {
      auditLog('unified-creator-guard', 'fail_open_override', { error: err.message });
      process.exit(0);
    }

    // Audit log the error
    auditLog('unified-creator-guard', 'error_fail_closed', { error: err.message });

    // SEC-008: Fail closed - deny when security state unknown
    process.exit(2);
  }
}

function validateCommandAllowlist(input) {
  const { command } = input;
  const mode = process.env.COMMAND_ALLOWLIST || 'warn';

  // Skip if disabled
  if (mode === 'off') {
    return { allowed: true };
  }

  // Check against allowlist
  const result = isCommandAllowed(command);

  if (result.allowed) {
    return { allowed: true };
  }

  // Format error message
  const message = `[COMMAND-ALLOWLIST] ${result.reason}\n\nCommand: ${result.command}\nFull: ${command}\n\nTo bypass: Set COMMAND_ALLOWLIST=off`;

  // Block or warn based on mode
  if (mode === 'block') {
    return {
      allowed: false,
      reason: message,
    };
  }

  // Warn mode
  return {
    allowed: true,
    warning: message,
  };
}

function requiresClaudeMdUpdate(filePath) {
  const normalized = filePath.replace(/\\/g, '/');
  return MONITORED_PATHS.some(p => normalized.includes(p));
}

function getClaudeMdTimestamp() {
  try {
    const stats = fs.statSync(CLAUDE_MD_PATH);
    return stats.mtimeMs;
  } catch {
    return 0;
  }
}

function getSectionToUpdate(filePath) {
  const normalized = filePath.replace(/\\/g, '/');

  if (normalized.includes('.claude/agents/')) {
    return 'Section 3 (Agent Routing Table)';
  }
  if (normalized.includes('.claude/skills/')) {
    return 'Section 8.5+ (Workflow Enhancement Skills or Section 8.7 for new skills)';
  }
  if (normalized.includes('.claude/workflows/')) {
    return 'Section 8.6 (Enterprise Workflows)';
  }
  return 'appropriate section';
}

function getArtifactType(filePath) {
  const normalized = filePath.replace(/\\/g, '/');

  if (normalized.includes('.claude/agents/')) return 'agent';
  if (normalized.includes('.claude/skills/')) return 'skill';
  if (normalized.includes('.claude/workflows/')) return 'workflow';
  return 'artifact';
}

function validate(context) {
  const { tool, parameters } = context;

  // Only check Write/Edit operations
  if (tool !== 'Write' && tool !== 'Edit') {
    return { valid: true, error: '' };
  }

  const filePath = parameters?.file_path || parameters?.filePath || '';

  // Check if this write requires CLAUDE.md update
  if (!requiresClaudeMdUpdate(filePath)) {
    return { valid: true, error: '' };
  }

  // Check if CLAUDE.md was modified this session
  const currentTimestamp = getClaudeMdTimestamp();

  if (currentTimestamp <= sessionStartTimestamp) {
    const artifactType = getArtifactType(filePath);
    const section = getSectionToUpdate(filePath);

    // CLAUDE.md not updated - return warning (not blocking by default)
    return {
      valid: true,
      error: '',
      warning: `REMINDER: You created/modified a ${artifactType} at ${filePath}. Don't forget to update CLAUDE.md ${section}.`,
    };
  }

  // CLAUDE.md was updated this session
  return { valid: true, error: '' };
}

function resetSession() {
  sessionStartTimestamp = getClaudeMdTimestamp();
}

function main() {
  // Skip if enforcement is off
  if (ENFORCEMENT_MODE === 'off') {
    process.exit(0);
  }

  // PERF-006/PERF-007: Use shared hook-input.cjs utilities
  const hookInput = parseHookInputSync();
  if (!hookInput) {
    process.exit(0);
  }

  // Get tool name and input using shared helpers
  const toolName = getToolName(hookInput);
  const toolInput = getToolInput(hookInput);

  // Only check write tools
  if (!WRITE_TOOLS.includes(toolName)) {
    process.exit(0);
  }

  // Get the file being modified using shared helper
  const filePath = extractFilePath(toolInput);
  if (!filePath) {
    process.exit(0);
  }

  // Check if this file requires CLAUDE.md update
  if (!requiresClaudeMdUpdate(filePath)) {
    process.exit(0);
  }

  // Normalize path for display
  const normalizedPath = path.normalize(filePath);
  const fileName = path.basename(normalizedPath);
  const artifactType = getArtifactType(filePath);
  const section = getSectionToUpdate(filePath);

  // Check if CLAUDE.md was modified this session
  const currentTimestamp = getClaudeMdTimestamp();

  if (currentTimestamp <= sessionStartTimestamp) {
    if (ENFORCEMENT_MODE === 'block') {
      try {
        eventBus.emit(EventTypes.TOOL_BLOCKED, {
          type: EventTypes.TOOL_BLOCKED,
          timestamp: new Date().toISOString(),
          toolName: 'Write',
          reason: 'claude_md_update_required',
        });
      } catch (_err) {
        // Best-effort
      }
      console.log('\n' + '='.repeat(55));
      console.log(' CLAUDE.MD UPDATE REQUIRED - OPERATION BLOCKED');
      console.log('='.repeat(55));
      console.log(`\n  File: ${fileName}`);
      console.log(`  Type: ${artifactType}`);
      console.log(`\n  You created/modified a ${artifactType} but CLAUDE.md was not updated.`);
      console.log(`  The router won't know about this ${artifactType} without updating CLAUDE.md.`);
      console.log(`\n  Please update CLAUDE.md ${section} first.`);
      console.log(`\n  Set CLAUDE_MD_ENFORCEMENT=warn to allow anyway.`);
      console.log('='.repeat(55) + '\n');
      process.exit(2); // Exit 2 = block operation (convention: 0=allow, 2=block)
    } else {
      console.log('\n' + '-'.repeat(55));
      console.log(' REMINDER: Update CLAUDE.md');
      console.log('-'.repeat(55));
      console.log(`\n  You created/modified: ${fileName}`);
      console.log(`  Type: ${artifactType}`);
      console.log(`\n  Don't forget to update CLAUDE.md ${section}`);
      console.log(`  so the router can discover this ${artifactType}.`);
      console.log('-'.repeat(55) + '\n');
      process.exit(0);
    }
  }

  // CLAUDE.md was updated this session - all good
  process.exit(0);
}

function debugLog(source, message, err) {
  if (!process.env.DEBUG_HOOKS) return;
  const details = err ? ` ${err.message || err}` : '';
  console.warn(`[${source}] ${message}${details}`);
}

function checkRouterModeReset(hookInput) {
  const result = {
    skipped: false,
    reason: null,
    stateReset: false,
    sessionBoundaryDetected: false,
  };

  // Get prompt
  const userPrompt = hookInput?.prompt || hookInput?.message || '';

  // Skip for slash commands (they are handled separately)
  if (userPrompt && userPrompt.trim().startsWith('/')) {
    result.skipped = true;
    result.reason = 'slash_command';
    return result;
  }

  // ROUTING-003 FIX: Detect session boundary before any state checks
  // Get current session ID from environment (or generate a fallback)
  const currentSessionId = process.env.CLAUDE_SESSION_ID || null;
  const currentState = routerState.getState();

  // Check if session has changed (stale state from previous session)
  // Session boundary is detected when:
  // 1. Current state has a sessionId AND it doesn't match current session
  // 2. Current state has no sessionId but current session has one (null -> defined)
  const stateSessionId = currentState.sessionId;
  const sessionChanged =
    (stateSessionId !== null && stateSessionId !== currentSessionId) ||
    (stateSessionId === null && currentSessionId !== null);

  if (sessionChanged) {
    result.sessionBoundaryDetected = true;
    if (process.env.ROUTER_DEBUG === 'true') {
      console.log(
        `[user-prompt-unified:reset] Session boundary detected: ${stateSessionId} -> ${currentSessionId}`
      );
    }
  }

  // ROUTING-002 FIX: ALWAYS reset to router mode on new user prompt
  // Removed the "active agent context" check that preserved agent mode
  // for 30 minutes. This was causing Router to use blacklisted tools
  // because state.taskSpawned remained true from previous prompts.
  //
  // Design rationale:
  // - Each new user prompt is a NEW routing decision
  // - Router must evaluate whether to spawn agents
  // - Agent mode is for SUBAGENTS, not for Router handling new prompts
  // - Subagent context is tracked by subagent_id in hook input, not state file

  // Reset to router mode
  routerState.resetToRouterMode();
  result.stateReset = true;

  // ROUTING-003 FIX: Update sessionId in state after reset
  // This ensures the new session ID is persisted for future boundary detection
  if (currentSessionId !== null) {
    routerState.saveStateWithRetry({ sessionId: currentSessionId });
  }

  if (process.env.ROUTER_DEBUG === 'true') {
    console.log('[user-prompt-unified:reset] State reset to router mode (ROUTING-002 fix)');
    if (result.sessionBoundaryDetected) {
      console.log('[user-prompt-unified:reset] Session ID updated for ROUTING-003 fix');
    }
  }

  return result;
}

function getConfig() {
  if (cachedConfig) return cachedConfig;
  try {
    cachedConfig = loadConfig();
  } catch (err) {
    if (process.env.DEBUG_HOOKS) {
      console.warn('[user-prompt-unified] Failed to load config.yaml:', err.message);
    }
    cachedConfig = null;
  }
  return cachedConfig;
}

function readCompressionState() {
  try {
    if (!fs.existsSync(AUTO_COMPRESSION_STATE_PATH)) {
      return { sessions: {} };
    }
    return JSON.parse(fs.readFileSync(AUTO_COMPRESSION_STATE_PATH, 'utf8'));
  } catch (_err) {
    return { sessions: {} };
  }
}

function writeCompressionState(state) {
  try {
    const dir = path.dirname(AUTO_COMPRESSION_STATE_PATH);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    atomicWriteJSONSync(AUTO_COMPRESSION_STATE_PATH, state);
