function extractHostname(url) {
  try {
    // Handle URLs without protocol
    let urlToParse = url;
    if (!url.includes('://')) {
      urlToParse = 'https://' + url;
    }
    const parsed = new URL(urlToParse);
    return parsed.hostname;
  } catch (_e) {
