function getCurrentTask(sessionId) {
  const todosDir = getTodosDir();
  if (sessionId && fs.existsSync(todosDir)) {
    try {
      const files = fs
        .readdirSync(todosDir)
        .filter(
          file => file.startsWith(sessionId) && file.includes('-agent-') && file.endsWith('.json')
        )
        .map(file => ({
          name: file,
          mtime: fs.statSync(path.join(todosDir, file)).mtime,
        }))
        .sort((a, b) => b.mtime - a.mtime);

      if (files.length > 0) {
        const todos = readJsonIfExists(path.join(todosDir, files[0].name));
        if (Array.isArray(todos)) {
          const inProgress = todos.find(item => item.status === 'in_progress');
          if (inProgress) {
            const raw = inProgress.activeForm || inProgress.content || '';
            return String(raw);
          }
        }
      }
    } catch (_err) {
      // ignore
    }
  }

  const stateFile = path.join(getStateDir(), 'current-task.json');
  const state = readJsonIfExists(stateFile);
  if (state && state.currentTask) {
    return String(state.currentTask);
  }
  return '';
}

function truncate(text, maxLength = 40) {
  if (!text) return '';
  const trimmed = String(text);
  if (trimmed.length <= maxLength) return trimmed;
  return `${trimmed.slice(0, maxLength - 3)}...`;
}

function getMemoryHealthIndicator() {
  const healthFile = path.join(getStateDir(), 'memory-health.json');
  const health = readJsonIfExists(healthFile);
  if (health && (health.status === 'warning' || health.status === 'error')) {
    return process.env.NO_COLOR ? ' ⚠' : ' \x1b[33m⚠\x1b[0m';
  }
  return '';
}

function formatStatusline(payload) {
  if (!payload || typeof payload !== 'object') return '';
  const model = payload.model?.display_name || 'Claude';
  const dir = payload.workspace?.current_dir || process.cwd();
  const sessionId = payload.session_id || '';
  const remaining = payload.context_window?.remaining_percentage;
  const contextBar = buildContextBar(remaining);
  const task = truncate(getCurrentTask(sessionId));
  const memoryHealth = getMemoryHealthIndicator();
  const dirname = path.basename(dir);

  if (task) {
    return `${memoryHealth}\x1b[2m${model}\x1b[0m │ \x1b[1m${task}\x1b[0m │ \x1b[2m${dirname}\x1b[0m${contextBar}`;
  }
  return `${memoryHealth}\x1b[2m${model}\x1b[0m │ \x1b[2m${dirname}\x1b[0m${contextBar}`;
}

function main() {
  let input = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', chunk => {
    input += chunk;
  });
  process.stdin.on('end', () => {
    const payload = safeParseJson(input);
    const line = formatStatusline(payload);
    if (line) {
      process.stdout.write(line);
    }
    process.exit(0);
  });
}

function extractFrontmatter(content) {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) {
    return null;
  }

  try {
    return yaml.parse(match[1]);
  } catch (_error) {
    return null;
  }
}

function isApprovedTool(tool) {
  // Check core tools
  if (CORE_TOOLS.has(tool)) {
    return { valid: true, type: 'core' };
  }

  // Check legacy/deprecated tools (allowed but warn)
  if (LEGACY_TOOLS.has(tool)) {
    return { valid: true, type: 'legacy', deprecated: true };
  }

  // Check approved MCP tools (including wildcards)
  if (APPROVED_MCP_TOOLS.has(tool)) {
    return { valid: true, type: 'mcp', configured: false };
  }

  // Check if tool matches wildcard pattern (e.g., mcp__filesystem__*)
  for (const approvedTool of APPROVED_MCP_TOOLS) {
    if (approvedTool.endsWith('__*')) {
      const prefix = approvedTool.slice(0, -1); // Remove trailing *
      if (tool.startsWith(prefix)) {
        return { valid: true, type: 'mcp-wildcard', configured: false };
      }
    }
  }

  // Check MCP pattern
  if (MCP_PATTERN.test(tool)) {
    return { valid: true, type: 'mcp-pattern', configured: false };
  }

  return { valid: false, type: 'unknown' };
}

function validateAgentTools(filePath, content) {
  const frontmatter = extractFrontmatter(content);
  if (!frontmatter) {
    return {
      valid: false,
      errors: ['No frontmatter found in agent file'],
      warnings: [],
    };
  }

  if (!frontmatter.tools || !Array.isArray(frontmatter.tools)) {
    return {
      valid: false,
      errors: ['No tools array found in frontmatter'],
      warnings: [],
    };
  }

  const tools = frontmatter.tools;
  // Extract category from file path if not in frontmatter
  let category = frontmatter.category;
  if (!category) {
    if (filePath.includes('/core/')) category = 'core';
    else if (filePath.includes('/domain/')) category = 'domain';
    else if (filePath.includes('/specialized/')) category = 'specialized';
    else if (filePath.includes('/orchestrators/')) category = 'orchestrator';
    else category = 'unknown';
  }
  const agentName = path.basename(filePath, '.md');

  const errors = [];
  const warnings = [];

  // Validate tool count
  if (tools.length < 3) {
    errors.push(`Minimum 3 tools required (found ${tools.length})`);
  }
  if (tools.length > 30) {
    errors.push(`Maximum 30 tools allowed (found ${tools.length})`);
  }

  // Validate each tool
  const invalidTools = [];
  const mcpTools = [];
  const legacyTools = [];

  for (const tool of tools) {
    const validation = isApprovedTool(tool);

    if (!validation.valid) {
      invalidTools.push(tool);
    } else if (validation.type === 'legacy') {
      legacyTools.push(tool);
      warnings.push(
        `Legacy/deprecated tool "${tool}" should be replaced (Search->Grep, Git->Bash, SequentialThinking->Skill, MCP Tools->specific tools)`
      );
    } else if (validation.type.startsWith('mcp')) {
      mcpTools.push(tool);
      if (!validation.configured) {
        warnings.push(`MCP tool "${tool}" requires server configuration in settings.json`);
      }
    }
  }

  if (invalidTools.length > 0) {
    errors.push(`Invalid tools: ${invalidTools.join(', ')}`);
    errors.push(`Valid core tools: ${Array.from(CORE_TOOLS).join(', ')}`);
  }

  // Check agent-specific rules
  const agentRule = AGENT_RULES[agentName];
  if (agentRule) {
    if (agentRule.requiredTools) {
      const missing = agentRule.requiredTools.filter(t => !tools.includes(t));
      if (missing.length > 0) {
        errors.push(
          `${agentName}: Missing required tools: ${missing.join(', ')} (${agentRule.reason})`
        );
      }
    }

    if (agentRule.forbiddenTools) {
      const forbidden = agentRule.forbiddenTools.filter(t => tools.includes(t));
      if (forbidden.length > 0) {
        errors.push(`${agentName}: Forbidden tools: ${forbidden.join(', ')} (${agentRule.reason})`);
      }
    }

    if (agentRule.allowedTools) {
      const disallowed = tools.filter(t => !agentRule.allowedTools.includes(t));
      if (disallowed.length > 0) {
        errors.push(
          `${agentName}: Disallowed tools: ${disallowed.join(', ')} (${agentRule.reason})`
        );
      }
    }
  }

  // Check category requirements
  const categoryReq = CATEGORY_REQUIREMENTS[category];
  if (categoryReq) {
    const missing = categoryReq.requiredTools.filter(t => !tools.includes(t));
    if (missing.length > 0) {
      errors.push(
        `Category "${category}": Missing required tools: ${missing.join(', ')} (${categoryReq.reason})`
      );
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings,
    metadata: {
      agentName,
      category,
      toolCount: tools.length,
      mcpToolCount: mcpTools.length,
      legacyToolCount: legacyTools.length,
    },
  };
}

async function handler(input) {
  const mode = process.env.AGENT_TOOLS_VALIDATOR || 'warn';

  if (mode === 'off') {
    return { decision: 'allow' };
  }

  const { filePath, content } = input;

  // Only validate agent files (skip README.md)
  if (
    !filePath.includes('.claude/agents/') ||
    !filePath.endsWith('.md') ||
    filePath.endsWith('README.md')
  ) {
    return { decision: 'allow' };
  }

  const result = validateAgentTools(filePath, content);

  if (!result.valid) {
    const errorMsg = [
      `Agent tools validation failed for ${path.basename(filePath)}:`,
      ...result.errors.map(e => `  ❌ ${e}`),
      '',
      'To fix:',
      '  1. Use only approved tools from .claude/schemas/agent-tools.json',
      '  2. Ensure category-specific requirements are met',
      '  3. Check agent-specific rules (orchestrators, reviewers, etc.)',
      '',
      `Enforcement mode: ${mode} (set AGENT_TOOLS_VALIDATOR=warn to allow with warnings)`,
    ].join('\n');

    if (mode === 'block') {
      return {
        decision: 'deny',
        reason: errorMsg,
        metadata: result.metadata,
      };
    } else {
      console.warn(errorMsg);
    }
  }

  // Show warnings even if valid
  if (result.warnings.length > 0) {
    console.warn(
      [
        `Agent tools warnings for ${path.basename(filePath)}:`,
        ...result.warnings.map(w => `  ⚠️  ${w}`),
      ].join('\n')
    );
  }

  return {
    decision: 'allow',
    metadata: result.metadata,
  };
}

function isPlanFile(filePath) {
  if (!filePath) return false;

  // Normalize path for cross-platform support
  const normalized = filePath.replace(/\\/g, '/');

  // Check if it's in the plans directory and is a markdown file
  const inPlansDir =
    normalized.includes('.claude/context/plans/') ||
    normalized.includes('.claude\\context\\plans\\');
  const isMarkdown = normalized.endsWith('.md');

  return inPlansDir && isMarkdown;
}

function hasEvolutionPhase(content) {
  if (!content) return false;

  return EVOLUTION_PATTERNS.some(pattern => pattern.test(content));
}

function extractContent(hookInput) {
  if (!hookInput) return null;

  const toolInput = hookInput.tool_input || hookInput.input || hookInput.parameters || {};

  return toolInput.content || null;
}

async function main() {
  try {
    // Check enforcement mode
    const mode = process.env.PLAN_EVOLUTION_GUARD || 'block';

    // If enforcement is off, allow and audit log
    if (mode === 'off') {
      console.error(
        JSON.stringify({
          hook: 'plan-evolution-guard',
          event: 'security_override_used',
          override: 'PLAN_EVOLUTION_GUARD=off',
          timestamp: new Date().toISOString(),
          warning:
            'Plan Evolution enforcement disabled - plans may be created without Evolution phase',
        })
      );
      process.exit(0);
    }

    // Parse hook input using shared async utility
    const hookInput = await parseHookInputAsync({ timeout: 200 });

    // No input - fail open (not a security hook)
    if (!hookInput) {
      process.exit(0);
    }

    // Check tool name - only validate Write operations
    const toolName = sharedGetToolName(hookInput);
    if (toolName !== 'Write') {
      process.exit(0);
    }

    // Extract file path using shared utility
    const toolInput = getToolInput(hookInput);
    const filePath = sharedExtractFilePath(toolInput);

    // Not a plan file - allow
    if (!isPlanFile(filePath)) {
      process.exit(0);
    }

    // Extract content
    const content = extractContent(hookInput);

    // Check for Evolution phase
    if (hasEvolutionPhase(content)) {
      // Evolution phase found - allow
      process.exit(0);
    }

    // Evolution phase NOT found - block or warn
    if (mode === 'warn') {
      console.error('[WARN] Plan missing Evolution phase - allowing anyway');
      console.error(formatMissingEvolutionError());
      process.exit(0);
    }

    // Block mode (default)
    console.error(formatMissingEvolutionError());
    console.log(
      JSON.stringify({
        result: 'block',
        message: 'Plan missing mandatory Evolution & Reflection phase',
      })
    );
    try {
      await eventBus.emit(EventTypes.TOOL_BLOCKED, {
        type: EventTypes.TOOL_BLOCKED,
        timestamp: new Date().toISOString(),
        toolName: 'Write',
        reason: 'missing_evolution_phase',
      });
    } catch (_err) {
      // Best-effort
    }
    process.exit(2);
  } catch (err) {
    // Fail open for validation hooks (not security-critical)
    // But still log the error for debugging
    console.error(
      JSON.stringify({
        hook: 'plan-evolution-guard',
        event: 'error_fail_open',
        error: err.message,
        timestamp: new Date().toISOString(),
      })
    );

    if (process.env.DEBUG_HOOKS) {
      console.error('Plan evolution guard error:', err.message);
      console.error('Stack trace:', err.stack);
    }

    process.exit(0);
  }
}

async function readInput() {
  return new Promise((resolve, reject) => {
    let data = '';
    process.stdin.on('data', chunk => {
      data += chunk;
    });
    process.stdin.on('end', () => {
      try {
        resolve(JSON.parse(data));
      } catch (err) {
        reject(new Error(`Failed to parse input: ${err.message}`));
      }
    });
    process.stdin.on('error', reject);
  });
}

function validateMetrics(metrics) {
  const errors = [];

  if (!metrics || typeof metrics !== 'object') {
    return errors; // metrics is optional
  }

  // Validate elapsedTimeMs
  if (metrics.elapsedTimeMs !== undefined) {
    if (typeof metrics.elapsedTimeMs !== 'number') {
      errors.push('metrics.elapsedTimeMs must be a number');
    } else if (metrics.elapsedTimeMs < 0) {
      errors.push('metrics.elapsedTimeMs must be >= 0');
    }
  }

  // Validate effortMultiplier
  if (metrics.effortMultiplier !== undefined) {
    if (typeof metrics.effortMultiplier !== 'number') {
      errors.push('metrics.effortMultiplier must be a number');
    } else if (metrics.effortMultiplier < 0.5) {
      errors.push('metrics.effortMultiplier must be >= 0.5');
    } else if (metrics.effortMultiplier > 5) {
      errors.push('metrics.effortMultiplier must be <= 5');
    }
  }

  // Validate riskScore
  if (metrics.riskScore !== undefined) {
    if (typeof metrics.riskScore !== 'number') {
      errors.push('metrics.riskScore must be a number');
    } else if (metrics.riskScore < 0) {
      errors.push('metrics.riskScore must be >= 0');
    } else if (metrics.riskScore > 100) {
      errors.push('metrics.riskScore must be <= 100');
    }
  }

  // Validate completionRate
  if (metrics.completionRate !== undefined) {
    if (typeof metrics.completionRate !== 'number') {
      errors.push('metrics.completionRate must be a number');
    } else if (metrics.completionRate < 0) {
      errors.push('metrics.completionRate must be >= 0');
    } else if (metrics.completionRate > 100) {
      errors.push('metrics.completionRate must be <= 100');
    }
  }

  return errors;
}

function validateReporting(reporting) {
  const errors = [];

  if (!reporting || typeof reporting !== 'object') {
    return errors; // reporting is optional
  }

  // Validate generatedAt (ISO 8601 timestamp)
  if (reporting.generatedAt !== undefined) {
    if (typeof reporting.generatedAt !== 'string') {
      errors.push('reporting.generatedAt must be a string');
    } else {
      const timestamp = new Date(reporting.generatedAt);
      if (isNaN(timestamp.getTime())) {
        errors.push('reporting.generatedAt must be a valid ISO 8601 timestamp');
      }
    }
  }

  // Validate lastReportPath
  if (reporting.lastReportPath !== undefined) {
    if (typeof reporting.lastReportPath !== 'string') {
      errors.push('reporting.lastReportPath must be a string');
    }
  }

  // Validate insights (array of strings)
  if (reporting.insights !== undefined) {
    if (!Array.isArray(reporting.insights)) {
      errors.push('reporting.insights must be an array');
    } else {
      reporting.insights.forEach((insight, index) => {
        if (typeof insight !== 'string') {
          errors.push(`reporting.insights[${index}] must be a string`);
        }
      });
    }
  }

  return errors;
}

async function main() {
  if (MODE === 'off') {
    process.exit(0);
  }

  try {
    const input = await readInput();

    // Only validate Write/Edit to metadata.json files
    if (!input.tool || !['Write', 'Edit'].includes(input.tool)) {
      process.exit(0);
    }

    const filePath = input.parameters?.file_path;
    if (!filePath || !filePath.endsWith('metadata.json')) {
      process.exit(0);
    }

    // Parse content to validate
    let content = input.parameters?.content;
    if (input.tool === 'Edit') {
      // For Edit, new_string might contain JSON
      content = input.parameters?.new_string;
    }

    if (!content) {
      process.exit(0);
    }

    // Try to parse as JSON
    let metadata;
    try {
      metadata = JSON.parse(content);
    } catch (_err) {
      // Not valid JSON, skip validation
      process.exit(0);
    }

    // Validate metrics
    const metricsErrors = validateMetrics(metadata.metrics);

    // Validate reporting
    const reportingErrors = validateReporting(metadata.reporting);

    const allErrors = [...metricsErrors, ...reportingErrors];

    if (allErrors.length > 0) {
      const errorMessage = `Track analytics validation failed:\n${allErrors.map(e => `  - ${e}`).join('\n')}`;

      if (MODE === 'block') {
        console.error(errorMessage);
        process.exit(1);
      } else {
        // warn mode
        console.warn(`[WARN] ${errorMessage}`);
        process.exit(0);
      }
    }

    // Validation passed
    process.exit(0);
  } catch (err) {
    console.error(`[ERROR] Hook execution failed: ${err.message}`);
    process.exit(0); // Fail-open (don't block on hook errors)
  }
}

function load() {
  if (_cache) return _cache;
  try {
    if (fs.existsSync(CONFIG_PATH)) {
      _cache = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
      return _cache;
    }
  } catch (_e) {
    // ignore and fall through to defaults
  }
  _cache = { version: '1.0.0', agents: {}, thinkingBudgetMap: {} };
  return _cache;
}

function normalizeAgentType(agentType) {
  if (!agentType || typeof agentType !== 'string') return '';
  return agentType.trim().toLowerCase();
}

function getAgentConfig(agentType) {
  const key = normalizeAgentType(agentType);
  const config = load();
  const agents = config.agents || {};
  return agents[key] || null;
}

function getDefaultTools(agentType) {
  const entry = getAgentConfig(agentType);
  const tools = entry && Array.isArray(entry.tools) ? entry.tools : null;
  if (tools && tools.length > 0) return tools;
  return ['Read', 'Write', 'Edit', 'Bash', 'Glob', 'Grep'];
}

function getDefaultThinkingLevel(agentType) {
  const entry = getAgentConfig(agentType);
  return (entry && entry.thinkingDefault) || 'medium';
}

function getThinkingBudget(thinkingLevel) {
  const config = load();
  const map = config.thinkingBudgetMap || {};
  if (Object.prototype.hasOwnProperty.call(map, thinkingLevel)) {
    return map[thinkingLevel];
  }
  return map.medium ?? 4096;
}

function getPhaseForAgent(agentType) {
  const entry = getAgentConfig(agentType);
  return (entry && entry.phase) || null;
}

function listAgentTypes() {
  const config = load();
  const agents = config.agents || {};
  return Object.keys(agents);
}

function clearCache() {
  _cache = null;
}

class AgentParser {
  constructor() {
    // Load JSON Schema for agent identity
    const schemaPath = path.join(PROJECT_ROOT, '.claude', 'schemas', 'agent-identity.json');
    this.identitySchema = JSON.parse(fs.readFileSync(schemaPath, 'utf8'));

    // Initialize AJV validator
    this.ajv = new Ajv({
      allErrors: true, // Collect all errors
      verbose: true, // Include schema and data in errors
      strict: false, // Allow non-standard keywords like "version"
    });
    this.validateIdentityFn = this.ajv.compile(this.identitySchema);
  }

  /**
   * Parse agent file and validate identity if present
   *
   * @param {string} filePath - Path to agent markdown file
   * @returns {Object} Parsed agent definition with identity (if present)
   * @throws {Error} If identity validation fails
   */
  parseAgentFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');

    // Extract YAML frontmatter
    const frontmatterMatch = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
    if (!frontmatterMatch) {
      throw new Error(`No YAML frontmatter found in ${filePath}`);
    }

    const frontmatter = yaml.load(frontmatterMatch[1]);

    // Validate identity if present
    if (frontmatter.identity) {
      const validation = this.validateIdentity(frontmatter.identity);
      if (!validation.valid) {
        const errorMessages = validation.errors.map(err => err.message).join(', ');
        throw new Error(`Identity validation failed: ${errorMessages}`);
      }
    }

    return frontmatter;
  }

  /**
   * Validate identity object against JSON Schema
   *
   * @param {Object} identity - Identity object to validate
   * @returns {{ valid: boolean, errors?: Array<{path: string, message: string}> }}
   */
  validateIdentity(identity) {
    const valid = this.validateIdentityFn(identity);

    if (valid) {
      return { valid: true };
    }

    // Format validation errors
    const errors = this.validateIdentityFn.errors.map(err => {
      let message = err.message;

      // Add more context to common errors
      if (err.keyword === 'minLength') {
        message = `${err.instancePath || 'field'} ${err.message}`;
      } else if (err.keyword === 'enum') {
        message = `${err.instancePath} should be equal to one of the allowed values`;
      } else if (err.keyword === 'required') {
        message = `Missing required field: ${err.params.missingProperty}`;
      }

      return {
        path: err.instancePath || err.schemaPath,
        message: message,
      };
    });

    return { valid: false, errors };
  }

class ArchitectAgent extends BaseAgent {
  constructor(config = {}) {
    super(config);
    this.name = 'ArchitectAgent';
  }

  /**
   * Decompose a high-level request into specific tasks.
   * @param {string} userRequest - The complex user request
   * @returns {Promise<Object>} - The decomposition plan
   */
  async resolveTask(userRequest) {
    // Step 1: Analyze context (if tools available)
    let context = 'No file access.';
    if (this.tools.listFiles) {
      try {
        const files = await this._useTool('listFiles', { path: '.' });
        context = `Project Structure: ${JSON.stringify(files)}`;
      } catch (e) {
        context = `Error reading files: ${e.message}`;
      }
    }

    // Step 2: Generate Plan
    const plan = await this._generatePlan(userRequest, context);

    return {
      status: 'success',
      originalRequest: userRequest,
      tasks: plan.tasks,
      summary: plan.summary,
    };
  }

  /**
   * Calls LLM to break down the task.
   */
  async _generatePlan(request, context) {
    const systemPrompt = `You are an expert Software Architect.
Your goal is to break down a complex user request into small, specific implementation tasks for a Developer Agent.
The Developer Agent can only edit code and run tests. It cannot "plan" a whole feature.

Context:
${context}

Output a JSON object with:
- summary: string (high level approach)
- tasks: Array<{ title: string, description: string, expectedFiles: string[] }>
`;

    const response = await this._think(systemPrompt, request);

    try {
      return JSON.parse(response);
    } catch (e) {
      throw new Error(`Failed to parse architect plan: ${e.message}`);
    }
  }

class AgentFactory {
  /**
   * Create a specialized agent.
   *
   * @param {string} type - 'developer', 'architect', or 'qa'
   * @param {Object} config - Agent configuration (tools, model, etc.)
   * @returns {BaseAgent} - Instance of the requested agent
   */
  static createAgent(type, config = {}) {
    // Ensure ModelClient is present
    if (!config.modelClient) {
      config.modelClient = new ModelClient(config.model || {});
    }
    // Ensure Memory is present (optional, can be null)
    if (!config.memory && config.context && config.context.memory) {
      config.memory = config.context.memory;
    }
    switch (type.toLowerCase()) {
      case 'developer':
        return new DeveloperAgent(config);
      case 'architect':
        return new ArchitectAgent(config);
      case 'qa':
        return new QAAgent(config);
      default:
        throw new Error(`Unknown agent type: ${type}. Available types: developer, architect, qa`);
    }
  }

  /**
   * Get list of supported agent types.
   * @returns {string[]}
   */
  static getAvailableAgentTypes() {
    return ['developer', 'architect', 'qa'];
  }

class DeveloperAgent extends BaseAgent {
  constructor(config = {}) {
    super(config);
    this.name = 'DeveloperAgent';
  }

  /**
   * Resolve a coding task.
   * Format:
   * 1. Analyze context (read files).
   * 2. Plan changes.
   * 3. Apply changes.
   * 4. Verify.
   */
  async resolveTask(taskDescription) {
    // Step 1: Plan
    const plan = await this._planModifications(taskDescription);

    // Step 2: Apply
    const results = [];
    for (const action of plan.actions) {
      if (action.type === 'edit') {
        const result = await this._applyChanges(action.file, action.content);
        results.push(result);
      }
    }

    // Step 3: Verify (if test provided)
    let verification = { passed: true, message: 'No verification step in plan.' };
    if (plan.verificationCommand) {
      verification = await this._verify(plan.verificationCommand);
    }

    return {
      status: verification.passed ? 'success' : 'failure',
      plan,
      results,
      verification,
    };
  }

  /**
   * Generates a modification plan using the LLM.
   */
  async _planModifications(task) {
    const systemPrompt = `You are an expert Developer Agent.
Your goal is to modify code to satisfy a requirement.
Output a JSON object with:
- explanation: string
- actions: Array<{ type: 'edit', file: string, content: string }>
- verificationCommand: string (optional command to run tests)
`;

    const response = await this._think(systemPrompt, task);

    try {
      // Basic JSON parsing (in production, use a safe parser or output validation)
      return JSON.parse(response);
    } catch (e) {
      throw new Error(`Failed to parse plan from LLM: ${e.message}`);
    }
  }

  /**
   * Applies changes to a file.
   */
  async _applyChanges(file, content) {
    // Use the 'writeFile' tool inherited from BaseAgent config
    return this._useTool('writeFile', { file, content });
  }

  /**
   * Runs a verification command.
   */
  async _verify(command) {
    try {
      // Use 'exec' tool
      const output = await this._useTool('exec', { command });
      // Naive check: if exit code is 0 (implied by no error throw usually), strictly standard logic depends on tool implementation.
      // Assuming tool returns { stdout, stderr, exitCode }
      if (output.exitCode === 0) {
        return { passed: true, message: output.stdout };
      }
      return { passed: false, message: output.stderr || output.stdout };
    } catch (e) {
      return { passed: false, message: e.message };
    }
  }

class OrchestratorService {
  constructor(config = {}) {
    this.config = config;
    this.tools = config.tools || {};
  }

  /**
   * Process a user request by routing it to the appropriate agent.
   *
   * @param {string} task - The user's request
   * @param {Object} context - Optional context (e.g., changed files)
   * @returns {Promise<Object>} - The result from the agent
   */
  async processTask(task, context = {}) {
    // console.log(`[Orchestrator] Processing task: "${task}"`);

    // 1. Route Task
    const agentType = this._routeTask(task);
    // console.log(`[Orchestrator] Routing to: ${agentType}`);

    // 2. Create Agent
    const agent = AgentFactory.createAgent(agentType, {
      tools: this.tools,
      model: this.config.model,
      memory: context.memory, // Inject Memory
    });

    // 3. Execute
    // Developer and QA might need extra context args
    // For now, we pass task and context.changedFiles if available
    let result;
    if (agentType === 'qa') {
      result = await agent.resolveTask(task, context.changedFiles || []);
    } else {
      result = await agent.resolveTask(task);
    }

    // 4. Recursive Execution (Chain of Thought)
    const subResults = [];
    if (agentType === 'architect' && result.tasks && Array.isArray(result.tasks)) {
      console.log(
        `[Orchestrator] Architect returned ${result.tasks.length} sub-tasks. Executing...`
      );
      for (const subTask of result.tasks) {
        // Construct a sub-task string or object.
        // Architect returns { title, description, expectedFiles }
        const subTaskString = `${subTask.title}: ${subTask.description}`;
        const subResult = await this.processTask(subTaskString, context);
        subResults.push(subResult);
      }
    }

    return {
      task,
      agent: agentType,
      result,
      subResults, // Include sub-results in the output
    };
  }

  /**
   * Determine the best agent for the task.
   * Simple heuristic for Phase 7.
   */
  _routeTask(task) {
    const t = task.toLowerCase();

    if (t.includes('test') || t.includes('verify') || t.includes('qa') || t.includes('check')) {
      return 'qa';
    }

    if (
      t.includes('plan') ||
      t.includes('design') ||
      t.includes('architecture') ||
      t.includes('break down')
    ) {
      return 'architect';
    }

    // Default to Developer for "fix", "create", "update", "implement"
    return 'developer';
  }

class BaseAgent {
