    // For now, let's return a default mock string to avoid breaking existing tests
    // that might rely on the specific mock override in the test file itself.
    // If the test OVERRODE _think, this method won't be called anyway.

    throw new Error(`[${this.name}] No ModelClient injected and _think not mocked.`);
  }

  /**
   * Helper to search agent memory.
   * @param {string} query - The search query
   * @param {Object} options - Search options
   * @returns {Promise<Array>} - Search results
   */
  async searchMemory(query, options) {
    if (!this.memory) {
      return [];
    }
    return this.memory.search(query, options);
  }

  /**
   * Execute a tool by name.
   * @param {string} toolName - Name of the tool
   * @param {Object} args - Arguments for the tool
   * @returns {Promise<any>} - Tool output
   */
  async _useTool(toolName, args) {
    if (!this.tools[toolName]) {
      throw new Error(`Tool "${toolName}" not found.`);
    }
    return this.tools[toolName](args);
  }

function parseFrontmatter(content) {
  const match = content.match(/^---\s*\n([\s\S]*?)\n---/);
  if (!match) return null;

  const frontmatter = {};
  const lines = match[1].split('\n');

  for (const line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex === -1) continue;

    const key = line.substring(0, colonIndex).trim();
    const value = line.substring(colonIndex + 1).trim();

    if (key && value) {
      frontmatter[key] = value;
    }
  }

  return frontmatter;
}

function parseSections(content) {
  const sections = [];
  const headingRegex = /^##\s+(.+)$/gm;
  let match;

  while ((match = headingRegex.exec(content)) !== null) {
    sections.push(match[1].trim());
  }

  return sections;
}

function validateRuleStructure(filePath) {
  const errors = [];

  try {
    const content = fs.readFileSync(filePath, 'utf-8');

    // Check frontmatter
    const frontmatter = parseFrontmatter(content);
    if (!frontmatter) {
      errors.push('Missing frontmatter');
    } else {
      // Required frontmatter fields
      if (!frontmatter.title) errors.push('Missing required frontmatter field: title');
      if (!frontmatter.impact) errors.push('Missing required frontmatter field: impact');
    }

    // Check for title heading that matches frontmatter title
    if (frontmatter && frontmatter.title) {
      const titleHeadingRegex = new RegExp(`^##\\s+${frontmatter.title}`, 'm');
      if (!titleHeadingRegex.test(content)) {
        errors.push(`Missing or mismatched title heading (should be "## ${frontmatter.title}")`);
      }
    } else if (!content.match(/^##\s+.+/m)) {
      errors.push('Missing title heading (## Title)');
    }

    // Extract sections
    const sections = parseSections(content);

    // Check required sections
    for (const requiredSection of REQUIRED_SECTIONS) {
      if (!sections.some(s => s.toLowerCase().includes(requiredSection.toLowerCase()))) {
        errors.push(`Missing required section: ${requiredSection}`);
      }
    }

    // Check for Wrong/Bad example
    const hasWrongExample = sections.some(
      s =>
        s.toLowerCase().includes('wrong') ||
        s.toLowerCase().includes('bad') ||
        s.toLowerCase().includes('incorrect')
    );

    if (!hasWrongExample) {
      errors.push('Missing Wrong/Bad/Incorrect example section');
    }

    // Check for Right/Good example
    const hasRightExample = sections.some(
      s =>
        s.toLowerCase().includes('right') ||
        s.toLowerCase().includes('good') ||
        s.toLowerCase().includes('correct')
    );

    if (!hasRightExample) {
      errors.push('Missing Right/Good/Correct example section');
    }

    // Check for code examples (markdown fences)
    const codeBlocks = content.match(/```[\s\S]*?```/g) || [];
    if (codeBlocks.length < 2) {
      errors.push('Missing code examples (need at least 2 code blocks with ``` fences)');
    }
  } catch (err) {
    errors.push(`Failed to read file: ${err.message}`);
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

function preToolUse(hookInput) {
  const { tool, params } = hookInput;

  // Only validate Write/Edit operations
  if (tool !== 'Write' && tool !== 'Edit') {
    return { allowed: true };
  }

  const filePath = params.file_path;
  if (!filePath) {
    return { allowed: true };
  }

  // Only validate files in skills/*/rules/ directories
  const normalizedPath = path.normalize(filePath);
  if (
    !normalizedPath.includes(path.join('.claude', 'skills')) ||
    !normalizedPath.includes(path.join('rules'))
  ) {
    return { allowed: true };
  }

  // Skip validation for _template.md and _sections.md files
  const basename = path.basename(filePath);
  if (basename.startsWith('_')) {
    return { allowed: true };
  }

  // For Edit operations, we need content
  const contentToValidate = params.content || params.new_string || '';

  if (tool === 'Edit' && !contentToValidate) {
    // Can't validate without content, allow for now
    return { allowed: true };
  }

  // Create temporary file for validation
  const tempFile = path.join(PROJECT_ROOT, '.tmp-rule-structure-validation.md');
  try {
    fs.writeFileSync(tempFile, contentToValidate);
    const result = validateRuleStructure(tempFile);
    fs.unlinkSync(tempFile);

    if (!result.valid) {
      return {
        allowed: false,
        reason: `Rule structure validation failed for ${path.basename(filePath)}:\n${result.errors.map(e => `  - ${e}`).join('\n')}`,
      };
    }
  } catch (err) {
    // Don't block on validation errors, just warn
    console.warn(`[rule-structure-validator] Validation error: ${err.message}`);
  }

  return { allowed: true };
}

class QAAgent extends BaseAgent {
  constructor(config = {}) {
    super(config);
    this.name = 'QAAgent';
  }

  /**
   * Verify a set of changes.
   *
   * Required Tools:
   * - writeFile({ file, content }): Promise<{ success }>
   * - exec({ command }): Promise<{ exitCode, stdout, stderr }>
   *
   * @param {string} taskDescription - What was done
   * @param {Array<string>} changedFiles - List of modified files
   * @returns {Promise<Object>} - Verification report
   */
  async resolveTask(taskDescription, changedFiles = []) {
    // Step 1: Plan Tests
    const testPlan = await this._planTests(taskDescription, changedFiles);

    // Validate Plan
    if (!testPlan || !Array.isArray(testPlan.tests)) {
      return {
        status: 'failure',
        error: 'Invalid test plan generated by LLM',
        testPlan,
      };
    }

    if (testPlan.tests.length === 0) {
      return {
        status: 'skipped',
        message: 'No tests generated for this task.',
        testPlan,
        results: { allPassed: true, logs: [] },
      };
    }

    // Step 2: Write Tests
    const testFiles = [];
    for (const test of testPlan.tests) {
      if (!test.filename || !test.content) continue; // Skip malformed tests

      // Use writeFile tool
      await this._useTool('writeFile', {
        file: test.filename,
        content: test.content,
      });
      testFiles.push(test.filename);
    }

    // Step 3: Run Tests
    const results = await this._runTests(testFiles);

    return {
      status: results.allPassed ? 'success' : 'failure',
      testPlan,
      results,
    };
  }

  /**
   * Generates a test plan.
   */
  async _planTests(task, files) {
    const systemPrompt = `You are an expert QA Automation Engineer.
Your goal is to write a self-contained test file (using 'node:test' and 'assert') to verify a recent change.

Context:
Task: ${task}
Changed Files: ${JSON.stringify(files)}

Output a JSON object with:
- explanation: string
- tests: Array<{ filename: string, content: string }>
  (Content must be valid JavaScript code for a node test)
`;

    const response = await this._think(systemPrompt, task);

    try {
      return JSON.parse(response);
    } catch (e) {
      throw new Error(`Failed to parse test plan: ${e.message}`);
    }
  }

  /**
   * Executes tests.
   */
  async _runTests(testFiles) {
    // In a real env, we'd run 'node --test ...'
    // Here we wrap 'exec'
    const results = { allPassed: true, logs: [] };

    for (const file of testFiles) {
      try {
        const output = await this._useTool('exec', { command: `node --test ${file}` });
        results.logs.push({
          file,
          passed: output.exitCode === 0,
          output: output.stdout || output.stderr,
        });
        if (output.exitCode !== 0) results.allPassed = false;
      } catch (e) {
        results.allPassed = false;
        results.logs.push({ file, passed: false, output: e.message });
      }
    }

    return results;
  }

function extractTaskMetadata(params) {
  try {
    const metadata = params.metadata || {};
    return {
      filesModified: metadata.filesModified || [],
      summary: metadata.summary || '',
      taskId: params.taskId,
    };
  } catch (_err) {
    return { filesModified: [], summary: '', taskId: null };
  }
}

function detectArtifacts(filesModified) {
  const artifacts = [];

  for (const filePath of filesModified) {
    const normalizedPath = filePath.replace(/\\/g, '/');

    // Check if it's an artifact path
    if (
      normalizedPath.includes('/.claude/agents/') ||
      normalizedPath.includes('/.claude/skills/') ||
      normalizedPath.includes('/.claude/workflows/') ||
      normalizedPath.includes('/.claude/hooks/')
    ) {
      // Extract artifact info
      const type = normalizedPath.includes('/agents/')
        ? 'agent'
        : normalizedPath.includes('/skills/')
          ? 'skill'
          : normalizedPath.includes('/workflows/')
            ? 'workflow'
            : 'hook';

      artifacts.push({
        path: filePath,
        type,
      });
    }
  }

  return artifacts;
}

function validateArtifact(artifactPath) {
  try {
    // Run validation script
    execSync(`node "${VALIDATION_SCRIPT}" "${artifactPath}"`, {
      cwd: PROJECT_ROOT,
      stdio: 'pipe',
      encoding: 'utf-8',
    });

    return { passed: true, issues: [] };
  } catch (err) {
    // Validation failed - parse output for issues
    const output = err.stdout || err.stderr || '';
    const issues = [];

    // Extract failed checks from output
    const lines = output.split('\n');
    for (const line of lines) {
      if (line.includes('✗') || line.includes('FAIL')) {
        issues.push(line.trim());
      }
    }

    return {
      passed: false,
      issues: issues.length > 0 ? issues : ['Integration validation failed'],
    };
  }
}

function main(hookInput) {
  try {
    // Parse hook input
    const input = typeof hookInput === 'string' ? JSON.parse(hookInput) : hookInput;
    const { tool, params } = input;

    // Only intercept TaskUpdate calls
    if (tool !== 'TaskUpdate') {
      // Not a TaskUpdate call - allow
      console.log(JSON.stringify({ allow: true }));
      process.exit(0);
    }

    // Only intercept when status is being set to "completed"
    if (params.status !== 'completed') {
      // Not completing a task - allow
      console.log(JSON.stringify({ allow: true }));
      process.exit(0);
    }

    // Extract task metadata
    const metadata = extractTaskMetadata(params);

    // Detect artifacts in modified files
    const artifacts = detectArtifacts(metadata.filesModified);

    // If no artifacts, allow completion
    if (artifacts.length === 0) {
      console.log(JSON.stringify({ allow: true }));
      process.exit(0);
    }

    // Validate each artifact
    const failedArtifacts = [];

    for (const artifact of artifacts) {
      const validation = validateArtifact(artifact.path);
      if (!validation.passed) {
        failedArtifacts.push({
          ...artifact,
          issues: validation.issues,
        });
      }
    }

    // If all artifacts passed, allow completion
    if (failedArtifacts.length === 0) {
      console.log(JSON.stringify({ allow: true }));
      process.exit(0);
    }

    // Block completion - validation failed
    const blockMessage = [
      '',
      '+----------------------------------------------------------+',
      '| PRE-COMPLETION VALIDATION FAILED                         |',
      '+----------------------------------------------------------+',
      '| Cannot complete task - artifact integration incomplete.  |',
      '|                                                          |',
      `| Task ID: ${metadata.taskId || 'unknown'}`,
      `| Artifacts with issues: ${failedArtifacts.length}`,
      '|                                                          |',
    ];

    for (const artifact of failedArtifacts) {
      blockMessage.push(`|  [${artifact.type}] ${path.basename(artifact.path)}`);
      for (const issue of artifact.issues.slice(0, 3)) {
        // Max 3 issues shown
        blockMessage.push(`|    - ${issue.substring(0, 50)}`);
      }
    }

    blockMessage.push('|                                                          |');
    blockMessage.push('| Required action:                                         |');
    blockMessage.push('|  1. Run: node .claude/tools/cli/validate-integration.cjs \\|');
    blockMessage.push('|           <artifact-path>                                |');
    blockMessage.push('|  2. Fix reported issues                                 |');
    blockMessage.push('|  3. Re-run TaskUpdate to complete                       |');
    blockMessage.push('|                                                          |');
    blockMessage.push('| See: .claude/workflows/core/post-creation-validation.md  |');
    blockMessage.push('+----------------------------------------------------------+');
    blockMessage.push('');

    // Block with message
    console.log(
      JSON.stringify({
        allow: false,
        message: blockMessage.join('\n'),
      })
    );
    process.exit(0);
  } catch (err) {
    // Error in hook - allow completion (fail open)
    console.log(
      JSON.stringify({
        allow: true,
        message: `Pre-completion validation error: ${err.message}`,
      })
    );
    process.exit(0);
  }
}

class ModelClient {
  constructor(config = {}) {
    this.config = config;
    this.apiKey = process.env.ANTHROPIC_API_KEY || config.apiKey;
    this.isMock = !this.apiKey;
    const agentType = process.env.MODEL_CLIENT_AGENT_TYPE || 'planner';
    const resolved = resolveAgentModel(agentType, PROJECT_ROOT);
    const defaultModel =
      process.env.MODEL_CLIENT_DEFAULT_MODEL ||
      process.env.ANTHROPIC_MODEL ||
      resolved?.model ||
      'claude-3-5-sonnet-20240620';
    this.modelName = config.modelName || defaultModel;

    if (this.isMock && !ModelClient._warnedNoApiKey) {
      ModelClient._warnedNoApiKey = true;
      logger.warn('model_client_no_api_key_startup', {
        model: this.modelName,
        mode: 'mock',
      });
    }
  }

  /**
   * Generate text from the LLM.
   *
   * @param {Object} params
   * @param {string} params.system - System prompt
   * @param {Array<{role: string, content: string}> | string} params.messages - User message or conversation history
   * @returns {Promise<string>} - The model's response
   */
  async generateText({ system, messages }) {
    // 1. Normalize messages
    let normalizedMessages = messages;
    if (typeof messages === 'string') {
      normalizedMessages = [{ role: 'user', content: messages }];
    }

    // 2. Check for Mock Mode
    if (!this.apiKey) {
      this.isMock = true;
      logger.warn('model_client_no_api_key', { model: this.modelName, mode: 'mock' });
      return this._mockResponse(system, normalizedMessages);
    }

    // 3. Call Real API (Anthropic example)
    const maxRetries = Number(process.env.MODEL_CLIENT_MAX_RETRIES || 2);
    const baseDelayMs = Number(process.env.MODEL_CLIENT_RETRY_BASE_MS || 500);
    let attempt = 0;

    while (attempt <= maxRetries) {
      // In a real implementation, use 'anthropic-sdk' or 'fetch'
      // For this Phase 9 pilot, we will simulate the fetch call to avoid adding heavyweight dependencies
      // unless the user explicitly requested external network calls.
      // But since the goal is "Real Intelligence", let's assume we WANT to call it if the key exists.

      // However, I cannot install new packages easily. I'll use native fetch.
      // NOTE: Node 18+ has native fetch.
      try {
        const response = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: {
            'x-api-key': this.apiKey,
            'anthropic-version': '2023-06-01',
            'content-type': 'application/json',
          },
          body: JSON.stringify({
            model: this.modelName,
            system: system,
            messages: normalizedMessages,
            max_tokens: 4096,
          }),
        });

        if (!response.ok) {
          const errText = await response.text();
          const error = new Error(`Anthropic API Error: ${response.status} - ${errText}`);
          error.status = response.status;
          throw error;
        }

        const data = await response.json();
        return data.content[0].text;
      } catch (error) {
        const status = error?.status || 0;
        const retryable = status === 429 || (status >= 500 && status < 600) || status === 0;
        if (!retryable || attempt >= maxRetries) {
          logger.error('model_client_request_failed', {
            error: error.message,
            status,
            attempt,
          });
          throw error;
        }

        const delayMs = baseDelayMs * Math.pow(2, attempt);
        logger.warn('model_client_retry', { attempt, delayMs, status });
        await new Promise(resolve => setTimeout(resolve, delayMs));
      }
      attempt += 1;
    }

    throw new Error('ModelClient failed after retries');
  }

  _mockResponse(system, messages) {
    const lastUserMessage = messages[messages.length - 1].content.toLowerCase();

    // Simple mock logic for testing
    if (lastUserMessage.includes('plan')) {
      return JSON.stringify({
        summary: 'Mock Plan',
        tasks: [{ title: 'Mock Task', description: 'Generated by MockClient' }],
      });
    }
    if (lastUserMessage.includes('test') || lastUserMessage.includes('verify')) {
      return JSON.stringify({
        tests: [{ filename: 'tests/mock.test.js', content: '// mock test' }],
      });
    }
    if (lastUserMessage.includes('fix') || lastUserMessage.includes('code')) {
      return JSON.stringify({
        actions: [{ type: 'edit', file: 'mock.js', content: '// mock code' }],
      });
    }

    return 'Mock response from ModelClient (No API Key)';
  }

  isMockMode() {
    return !this.apiKey || this.isMock === true;
  }

