async function appendJsonl(filePath, payload) {
  const line = JSON.stringify(payload) + '\n';
  await ensureDir(path.dirname(filePath));
  await fs.appendFile(filePath, line);
  if (Number.isFinite(WORKER_METRICS_MAX_LINES) && WORKER_METRICS_MAX_LINES > 0) {
    try {
      const raw = await fs.readFile(filePath, 'utf8');
      const lines = raw.trim().split('\n');
      if (lines.length > WORKER_METRICS_MAX_LINES) {
        const trimmed = lines.slice(-WORKER_METRICS_MAX_LINES).join('\n') + '\n';
        await fs.writeFile(filePath, trimmed);
      }
    } catch (_err) {
      // Best-effort
    }
  }
}

async function runNode(scriptPath, args = []) {
  return new Promise(resolve => {
    const child = spawn(process.execPath, [scriptPath, ...args], {
      cwd: projectRoot,
      env: process.env,
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', data => {
      stdout += data.toString();
    });
    child.stderr.on('data', data => {
      stderr += data.toString();
    });
    child.on('close', code => {
      resolve({ code, stdout, stderr });
    });
  });
}

async function shouldRunWeekly() {
  try {
    const raw = await fs.readFile(maintenanceStatusPath, 'utf8');
    const status = JSON.parse(raw);
    if (!status.lastWeekly) return true;
    const lastWeekly = new Date(status.lastWeekly).getTime();
    if (Number.isNaN(lastWeekly)) return true;
    return Date.now() - lastWeekly >= WEEK_MS;
  } catch (_err) {
    return true;
  }
}

async function runMaintenanceTask() {
  const start = Date.now();
  const shouldWeekly = await shouldRunWeekly();
  const args = [path.join(projectRoot, '.claude', 'lib', 'memory', 'memory-scheduler.cjs')];
  args.push(shouldWeekly ? 'weekly' : 'daily');
  const result = await runNode(args[0], args.slice(1));
  const durationMs = Date.now() - start;
  const ok = result.code === 0;
  return {
    ok,
    durationMs,
    mode: shouldWeekly ? 'weekly' : 'daily',
    stderr: result.stderr || null,
  };
}

async function canProceedIndexing() {
  try {
    const stats = await fs.stat(lockFile);
    const lockAge = Date.now() - stats.mtimeMs;
    if (lockAge > LOCK_TIMEOUT_MS) {
      await fs.unlink(lockFile).catch(() => {});
      return true;
    }
    return false;
  } catch (_err) {
    return true;
  }
}

async function createLock() {
  try {
    await fs.writeFile(lockFile, JSON.stringify({ pid: process.pid, timestamp: Date.now() }), {
      flag: 'wx',
    });
    return true;
  } catch (_err) {
    return false;
  }
}

async function removeLock() {
  await fs.unlink(lockFile).catch(() => {});
}

async function runIndexTask() {
  const start = Date.now();
  const metadataPath = path.join(projectRoot, '.claude', 'context', 'code-index', 'metadata.json');
  const exists = await fs
    .access(metadataPath)
    .then(() => true)
    .catch(() => false);
  if (!exists) {
    return { ok: true, skipped: true, reason: 'index_missing', durationMs: 0 };
  }

  const proceed = await canProceedIndexing();
  if (!proceed) {
    return { ok: true, skipped: true, reason: 'lock_active', durationMs: 0 };
  }

  const hasLock = await createLock();
  if (!hasLock) {
    return { ok: true, skipped: true, reason: 'lock_failed', durationMs: 0 };
  }

  try {
    const manager = new IndexManager({ projectRoot });
    const result = await manager.incrementalUpdate();
    return {
      ok: true,
      durationMs: Date.now() - start,
      updateType: result.updateType,
      filesAdded: result.filesAdded || 0,
      filesModified: result.filesModified || 0,
      filesDeleted: result.filesDeleted || 0,
    };
  } catch (error) {
    return {
      ok: false,
      durationMs: Date.now() - start,
      error: error.message,
    };
  } finally {
    await removeLock();
  }
}

async function runReflectionTask() {
  const start = Date.now();
  const scriptPath = path.join(
    projectRoot,
    '.claude',
    'hooks',
    'reflection',
    'reflection-queue-processor.cjs'
  );
  const result = await runNode(scriptPath, []);
  return {
    ok: result.code === 0,
    durationMs: Date.now() - start,
    stderr: result.stderr || null,
  };
}

async function runTick() {
  const start = Date.now();
  const tasks = {};
  let status = 'ok';

  if (isTaskEnabled('maintenance')) {
    const maintenance = await runMaintenanceTask();
    tasks.maintenance = maintenance;
    if (!maintenance.ok) status = 'partial-fail';
  }

  if (isTaskEnabled('index')) {
    const index = await runIndexTask();
    tasks.index = index;
    if (!index.ok) status = 'partial-fail';
  }

  if (isTaskEnabled('reflection')) {
    const reflection = await runReflectionTask();
    tasks.reflection = reflection;
    if (!reflection.ok) status = 'partial-fail';
  }

  await writeHeartbeat(status, tasks);

  const durationMs = Date.now() - start;
  const summary = {
    timestamp: nowIso(),
    status,
    durationMs,
    tasks: {
      maintenance: tasks.maintenance
        ? {
            ok: tasks.maintenance.ok,
            durationMs: tasks.maintenance.durationMs,
            skipped: tasks.maintenance.skipped,
            reason: tasks.maintenance.reason,
          }
        : null,
      index: tasks.index
        ? {
            ok: tasks.index.ok,
            durationMs: tasks.index.durationMs,
            skipped: tasks.index.skipped,
            reason: tasks.index.reason,
          }
        : null,
      reflection: tasks.reflection
        ? {
            ok: tasks.reflection.ok,
            durationMs: tasks.reflection.durationMs,
            skipped: tasks.reflection.skipped,
            reason: tasks.reflection.reason,
          }
        : null,
    },
  };

  if (WORKER_METRICS) {
    try {
      await appendJsonl(metricsPath, summary);
    } catch (_err) {
      // best-effort
    }
  }

  if (WORKER_EVENTS) {
    try {
      const eventType = status === 'ok' ? EventTypes.TOOL_COMPLETED : EventTypes.TOOL_FAILED;
      const payload = {
        type: eventType,
        timestamp: summary.timestamp,
        toolName: 'worker-loop',
        output: summary.tasks,
        duration: durationMs,
      };
      if (eventType === EventTypes.TOOL_FAILED) {
        payload.error = 'worker_loop_partial_fail';
      }
      eventBus.emit(eventType, payload);
    } catch (_err) {
      // best-effort
    }
  }

  return { status, tasks };
}

async function stop() {
  logger.info('Stopping worker agent...');
  stopping = true;
  if (timeoutId) {
    clearTimeout(timeoutId);
    timeoutId = null;
  }
  if (running) {
    // Wait for current tick? Or just let it finish.
    // Lock release happens in finally block of runTick wrapper
  } else {
    // If not running, ensure lock is released (safeguard)
    await removeLock();
  }
}

async function start() {
  if (!WORKER_ENABLED) {
    logger.info('WORKER_ENABLED not set; exiting.');
    return;
  }

  logger.info('Starting agent worker loop...');

  let consecutiveFailures = 0;

  const tick = async () => {
    if (running || stopping) return;
    running = true;
    try {
      const result = await runTick();
      if (result.status === 'partial-fail') {
        consecutiveFailures += 1;
        logger.warn('Worker tick partial failure', { tasks: result.tasks });
      } else {
        consecutiveFailures = 0;
        logger.info('Worker tick completed', { durationMs: result.tasks?.durationMs });
      }
    } catch (error) {
      consecutiveFailures += 1;
      logger.error('Worker tick failed', { error: error.message });
      await writeHeartbeat('partial-fail', { error: { ok: false, error: error.message } });
    } finally {
      running = false;
      if (WORKER_ONCE) {
        process.exit(0);
      }
    }
  };

  const computeDelay = () => {
    if (consecutiveFailures === 0) return INTERVAL_MS;
    const backoff = Math.min(
      BACKOFF_MAX_MS,
      BACKOFF_BASE_MS * Math.pow(2, consecutiveFailures - 1)
    );
    return Math.max(INTERVAL_MS, backoff);
  };

  async function tickWithSchedule() {
    await tick();
    scheduleNext();
  }

  const scheduleNext = () => {
    if (WORKER_ONCE || stopping) return;
    timeoutId = setTimeout(tickWithSchedule, computeDelay());
  };

  // Handle signals if this is the main process
  if (require.main === module) {
    process.on('SIGINT', async () => {
      await stop();
      process.exit(0);
    });
    process.on('SIGTERM', async () => {
      await stop();
      process.exit(0);
    });
  }

  await tickWithSchedule();
}

 * @class AstGrepSearch
 */
class AstGrepSearch {
  /**
   * Initialize ast-grep wrapper
   * @param {Object} options - Configuration
   * @param {string} options.binPath - Path to ast-grep binary (default: 'ast-grep')
   * @param {string} options.projectRoot - Project root directory
   * @param {number} options.timeout - Search timeout in ms (default: 30000)
   */
  constructor(options = {}) {
    this.binPath = options.binPath || 'ast-grep';
    this.projectRoot = options.projectRoot || process.cwd();
    this.timeout = options.timeout || 30000;
  }

  /**
   * Check if ast-grep binary is available
   * @returns {Promise<boolean>} True if ast-grep is installed and working
   */
  async isAvailable() {
    return new Promise(resolve => {
      const proc = spawn(this.binPath, ['--version'], {
        stdio: ['ignore', 'pipe', 'pipe'],
      });

      proc.on('error', () => resolve(false));
      proc.on('close', code => resolve(code === 0));

      // Timeout after 5 seconds
      setTimeout(() => {
        proc.kill();
        resolve(false);
      }, 5000);
    });
  }

  /**
   * Get ast-grep version
   * @returns {Promise<string>} Version string (e.g., '0.35.0')
   */
  async getVersion() {
    return new Promise((resolve, reject) => {
      const proc = spawn(this.binPath, ['--version'], {
        stdio: ['ignore', 'pipe', 'pipe'],
      });

      let stdout = '';
      let stderr = '';

      proc.stdout.on('data', data => {
        stdout += data.toString();
      });
      proc.stderr.on('data', data => {
        stderr += data.toString();
      });

      proc.on('error', err => {
        reject(new Error(`ast-grep binary not found: ${err.message}`));
      });

      proc.on('close', code => {
        if (code === 0) {
          // Try to extract version number from output
          const match = stdout.match(/ast-grep (\d+\.\d+\.\d+)/);
          if (match) {
            resolve(match[1]);
          } else {
            // Return full output if no version match
            resolve(stdout.trim());
          }
        } else {
          reject(new Error(`ast-grep version check failed: ${stderr || 'Unknown error'}`));
        }
      });
    });
  }

  /**
   * Search for code matching an AST pattern
   * @param {string} pattern - ast-grep pattern (e.g., 'function $NAME($ARGS) { $BODY }')
   * @param {string} language - Programming language (js, ts, py, go, rs)
   * @param {Object} options - Search options
   * @param {string[]} options.include - Glob patterns to include
   * @param {string[]} options.exclude - Glob patterns to exclude
   * @param {number} options.maxResults - Maximum results (default: 100)
   * @returns {Promise<AstGrepResult[]>} Matching code locations
   */
  async search(pattern, language, options = {}) {
    // Validate inputs
    if (!pattern || typeof pattern !== 'string') {
      throw new Error('Pattern must be a non-empty string');
    }
    if (!language || typeof language !== 'string') {
      throw new Error('Language must be a non-empty string');
    }

    // Check if binary is available
    const available = await this.isAvailable();
    if (!available) {
      throw new Error('ast-grep binary not available. Install with: npm install -g @ast-grep/cli');
    }

    // Map language name
    const mappedLang = this.mapLanguage(language);

    // Build command arguments
    const args = ['-p', pattern, '--lang', mappedLang, '--json'];

    // Add include patterns
    if (options.include && options.include.length > 0) {
      for (const glob of options.include) {
        args.push('--glob', glob);
      }
    }

    // Add exclude patterns
    if (options.exclude && options.exclude.length > 0) {
      for (const glob of options.exclude) {
        args.push('--glob', `!${glob}`);
      }
    }

    // Add project root as the search path
    args.push(this.projectRoot);

    // Execute ast-grep
    return new Promise((resolve, reject) => {
      const proc = spawn(this.binPath, args, {
        stdio: ['ignore', 'pipe', 'pipe'],
      });

      let stdout = '';
      let stderr = '';

      proc.stdout.on('data', data => {
        stdout += data.toString();
      });
      proc.stderr.on('data', data => {
        stderr += data.toString();
      });

      proc.on('error', err => {
        reject(new Error(`ast-grep execution failed: ${err.message}`));
      });

      // Timeout handling
      const timeoutId = setTimeout(() => {
        proc.kill();
        reject(new Error(`ast-grep search timed out after ${this.timeout}ms`));
      }, this.timeout);

      proc.on('close', code => {
        clearTimeout(timeoutId);

        // ast-grep returns 0 if matches found, 1 if no matches (not an error)
        if (code === 0 || code === 1) {
          try {
            const results = JSON.parse(stdout || '[]');
            resolve(this._formatResults(results, options.maxResults));
          } catch (e) {
            reject(new Error(`Failed to parse ast-grep output: ${e.message}`));
          }
        } else {
          reject(new Error(`ast-grep failed with code ${code}: ${stderr}`));
        }
      });
    });
  }

  /**
   * Refine semantic search results with structural patterns
   * @param {SemanticResult[]} semanticResults - Results from Phase 1 search
   * @param {string} pattern - ast-grep pattern to filter by
   * @param {string} language - Programming language
   * @returns {Promise<HybridResult[]>} Results with structural scores
   */
  async refine(semanticResults, pattern, language) {
    // Handle empty input
    if (!semanticResults || semanticResults.length === 0) {
      return [];
    }

    // Extract unique file paths from semantic results
    const filePaths = [...new Set(semanticResults.map(r => r.filePath))];

    // Search with pattern in those files only
    const structuralResults = await this.search(pattern, language, {
      include: filePaths.map(f => {
        // Convert absolute path to relative for glob matching
        return path.relative(this.projectRoot, f);
      }),
    });

    // Create lookup map for structural matches
    const structuralMap = new Map();
    for (const sr of structuralResults) {
      const key = `${sr.filePath}:${sr.lineStart}-${sr.lineEnd}`;
      structuralMap.set(key, sr);
    }

    // Enhance semantic results with structural scores
    return semanticResults.map(semResult => {
      // Check for exact line range match
      const exactKey = `${semResult.filePath}:${semResult.lineRange[0]}-${semResult.lineRange[1]}`;
      const exactMatch = structuralMap.get(exactKey);

      if (exactMatch) {
        return {
          ...semResult,
          structuralScore: 1.0,
          structuralMatch: exactMatch,
        };
      }

      // Check for overlapping line ranges
      let overlaps = false;
      for (const [_, strResult] of structuralMap) {
        if (strResult.filePath === semResult.filePath) {
          if (this._rangesOverlap(semResult.lineRange, [strResult.lineStart, strResult.lineEnd])) {
            overlaps = true;
            break;
          }
        }
      }

      return {
        ...semResult,
        structuralScore: overlaps ? 0.5 : 0.0,
        structuralMatch: null,
      };
    });
  }

  /**
   * Map Phase 1 language names to ast-grep language names
   * @param {string} lang - Language name
   * @returns {string} Mapped language name
   */
  mapLanguage(lang) {
    return LANGUAGE_MAP[lang.toLowerCase()] || lang.toLowerCase();
  }

  /**
   * Detect language from file path
   * @param {string} filePath - File path
   * @returns {string|null} Detected language or null
   */
  detectLanguage(filePath) {
    const ext = path.extname(filePath).toLowerCase();
    return EXTENSION_TO_LANGUAGE[ext] || null;
  }

  /**
   * Format ast-grep results to consistent structure
   * @private
   */
  _formatResults(results, maxResults = 100) {
    return results.slice(0, maxResults).map(r => ({
      filePath: r.file,
      lineStart: r.range.start.line + 1, // ast-grep uses 0-indexed lines
      lineEnd: r.range.end.line + 1,
      colStart: r.range.start.column,
      colEnd: r.range.end.column,
      code: r.text,
      matches: r.metaVariables || {},
      language: r.language || 'unknown',
    }));
  }

  /**
   * Check if two line ranges overlap
   * @private
   */
  _rangesOverlap(range1, range2) {
    return range1[0] <= range2[1] && range1[1] >= range2[0];
  }

async function createTempRoot() {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'agent-studio-worker-'));
  return dir;
}

function spawnWorker(envOverrides) {
  const child = spawn(process.execPath, [WORKER_PATH], {
    env: { ...process.env, ...envOverrides },
    stdio: ['ignore', 'ignore', 'ignore'],
  });

  const exit = new Promise(resolve => {
    child.on('exit', code => resolve(code));
  });

  return { child, exit };
}

async function waitForFile(filePath, timeoutMs = 2000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      await fs.access(filePath);
      return true;
    } catch (_err) {
      await new Promise(resolve => setTimeout(resolve, 25));
    }
  }
  return false;
}

async function readJson(filePath) {
  const raw = await fs.readFile(filePath, 'utf8');
  return JSON.parse(raw);
}

class BM25Indexer {
  /**
   * Create BM25 indexer
   * @param {Object} options - Configuration options
   * @param {number} [options.k1=1.5] - Term frequency saturation parameter
   * @param {number} [options.b=0.75] - Length normalization parameter
   */
  constructor(options = {}) {
    this.k1 = options.k1 ?? 1.5;
    this.b = options.b ?? 0.75;

    // Index state
    this.documents = [];     // Array of { id, text, tokens, length, termFreqs }
    this.idf = {};           // IDF scores: { term: idfScore }
    this.avgDocLength = 0;   // Average document length
    this.N = 0;              // Total document count
  }

  /**
   * Tokenize text into words (lowercase, punctuation removed, stop words filtered)
   * @param {string} text - Text to tokenize
   * @returns {string[]} Array of tokens
   * @private
   */
  _tokenize(text) {
    // Convert to lowercase and split on non-alphanumeric
    const words = text
      .toLowerCase()
      .split(/[^a-z0-9]+/)
      .filter(word => word.length > 0);

    // Filter stop words
    return words.filter(word => !STOP_WORDS.has(word));
  }

  /**
   * Calculate term frequency map for a document
   * @param {string[]} tokens - Document tokens
   * @returns {Object} Map of term to frequency: { term: count }
   * @private
   */
  _calculateTermFreqs(tokens) {
    const freqs = {};
    for (const token of tokens) {
      freqs[token] = (freqs[token] || 0) + 1;
    }
    return freqs;
  }

  /**
   * Calculate IDF scores for all terms in the corpus
   * IDF(term) = log((N - df + 0.5) / (df + 0.5))
   * @private
   */
  _calculateIDF() {
    const df = {}; // Document frequency: { term: count of docs containing term }

    // Count document frequency for each term
    for (const doc of this.documents) {
      const uniqueTerms = new Set(doc.tokens);
      for (const term of uniqueTerms) {
        df[term] = (df[term] || 0) + 1;
      }
    }

    // Calculate IDF for each term
    this.idf = {};
    for (const term in df) {
      const numerator = this.N - df[term] + 0.5;
      const denominator = df[term] + 0.5;
      this.idf[term] = Math.log(numerator / denominator + 1); // +1 to avoid log(0)
    }
  }

  /**
   * Add documents to the index
   * @param {Array<{id: string, text: string}>} docs - Documents to add
   */
  addDocuments(docs) {
    if (!Array.isArray(docs) || docs.length === 0) {
      return;
    }

    // Process each document
    for (const doc of docs) {
      const tokens = this._tokenize(doc.text);
      const termFreqs = this._calculateTermFreqs(tokens);

      this.documents.push({
        id: doc.id,
        text: doc.text,
        tokens,
        length: tokens.length,
        termFreqs,
      });
    }

    // Update corpus statistics
    this.N = this.documents.length;
    const totalLength = this.documents.reduce((sum, doc) => sum + doc.length, 0);
    this.avgDocLength = this.N > 0 ? totalLength / this.N : 0;

    // Calculate IDF scores
    this._calculateIDF();
  }

  /**
   * Calculate BM25 score for a document given a query
   * @param {Object} doc - Document object
   * @param {string[]} queryTokens - Query tokens
   * @returns {number} BM25 score
   * @private
   */
  _calculateBM25Score(doc, queryTokens) {
    let score = 0;

    for (const term of queryTokens) {
      const idf = this.idf[term] || 0;
      if (idf === 0) continue; // Term not in corpus

      const termFreq = doc.termFreqs[term] || 0;
      if (termFreq === 0) continue; // Term not in document

      // BM25 formula
      const numerator = termFreq * (this.k1 + 1);
      const denominator = termFreq + this.k1 * (1 - this.b + this.b * (doc.length / this.avgDocLength));

      score += idf * (numerator / denominator);
    }

    return score;
  }

  /**
   * Search for documents matching query
   * @param {string} query - Search query
   * @param {number} [limit=100] - Maximum number of results to return
   * @returns {Array<{id: string, score: number}>} Results sorted by relevance (descending)
   */
  search(query, limit = 100) {
    if (!query || typeof query !== 'string' || query.trim().length === 0) {
      return [];
    }

    const queryTokens = this._tokenize(query);
    if (queryTokens.length === 0) {
      return [];
    }

    // Score all documents
    const results = [];
    for (const doc of this.documents) {
      const score = this._calculateBM25Score(doc, queryTokens);
      if (score > 0) {
        results.push({ id: doc.id, score });
      }
    }

    // Sort by score (descending) and limit results
    results.sort((a, b) => b.score - a.score);
    return results.slice(0, limit);
  }

  /**
   * Serialize index to JSON
   * @returns {Object} JSON representation
   */
  toJSON() {
    return {
      k1: this.k1,
      b: this.b,
      documents: this.documents,
      idf: this.idf,
      avgDocLength: this.avgDocLength,
      N: this.N,
    };
  }

  /**
   * Deserialize index from JSON
   * @param {Object} json - JSON representation
   * @returns {BM25Indexer} Restored indexer instance
   */
  static fromJSON(json) {
    const indexer = new BM25Indexer({ k1: json.k1, b: json.b });
    indexer.documents = json.documents;
    indexer.idf = json.idf;
    indexer.avgDocLength = json.avgDocLength;
    indexer.N = json.N;
    return indexer;
  }

class CodeParser {
  constructor(options = {}) {
    this.options = options;
    this.grammars = new Map();
    this.parsers = new Map();
    this._Parser = _Parser;
    this._treeSitterLoadError = _TREE_SITTER_LOAD_ERROR;
  }

  /**
   * Detect language from file extension
   * @param {string} filePath - Path to source file
   * @returns {string|null} Language identifier or null if unsupported
   */
  detectLanguage(filePath) {
    const ext = path.extname(filePath).toLowerCase();
    return EXTENSION_MAP[ext] || null;
  }

  /**
   * Check if a language is supported
   * @param {string} language - Language identifier
   * @returns {boolean}
   */
  isSupported(language) {
    return language in LANGUAGE_GRAMMARS;
  }

  /**
   * Get list of supported languages
   * @returns {string[]}
   */
  getSupportedLanguages() {
    return Object.keys(LANGUAGE_GRAMMARS);
  }

  /**
   * Get supported file extensions
   * @returns {string[]}
   */
  getSupportedExtensions() {
    return Object.keys(EXTENSION_MAP);
  }

  _loadGrammar(language) {
    if (this.grammars.has(language)) return this.grammars.get(language);
    const grammarName = LANGUAGE_GRAMMARS[language];
    if (!grammarName) return null;
    try {
      const mod = require(grammarName);
      let grammar = mod;
      if (grammarName === 'tree-sitter-typescript') {
        grammar = mod.typescript;
      }
      if (grammarName === 'tree-sitter-typescript/tsx') {
        grammar = mod.tsx;
      }
      this.grammars.set(language, grammar);
      return grammar;
    } catch (_e) {
      this.grammars.set(language, null);
      return null;
    }
  }

  _getParser(language) {
    if (!this._Parser) return null;
    if (this.parsers.has(language)) return this.parsers.get(language);
    const grammar = this._loadGrammar(language);
    if (!grammar) {
      this.parsers.set(language, null);
      return null;
    }
    const parser = new this._Parser();
    parser.setLanguage(grammar);
    this.parsers.set(language, parser);
    return parser;
  }

  parse(content, language) {
    if (!language || !this.isSupported(language)) return null;
    const parser = this._getParser(language);
    if (!parser) return null;
    const tree = parser.parse(content);
    return { content, language, rootNode: tree.rootNode };
  }

class EmbeddingGenerator {
  /**
   * Create embedding generator
   * @param {Object} options - Configuration options
   * @param {string} options.model - HuggingFace model name
   * @param {number} options.dimensions - Embedding dimensions
   * @param {number} options.batchSize - Batch size for processing
   * @param {boolean} options.cacheEnabled - Enable embedding cache
   * @param {string} options.cachePath - Cache file path
   */
  constructor(options = {}) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
    this.pipeline = null;
    this.cache = new Map();
    this.initialized = false;
    this.device = 'cpu'; // Default to CPU
    this.gpuName = null;
    this.gpuMemoryMB = 0;
    this.batchSize = this.options.batchSize;
  }

  /**
   * Initialize the embedding pipeline with GPU detection
   * Downloads model on first run (~25MB)
   * @returns {Promise<void>}
   */
  async initialize() {
    if (this.initialized) return;

    // Allow tests / constrained environments to run without native deps.
    // This keeps code-indexing fail-open (embeddings become deterministic but not semantic).
    const isTestRun = process.env.NODE_ENV === 'test' || process.argv.includes('--test');

    const forceMock =
      isTestRun ||
      process.env.CODE_INDEX_EMBEDDER === 'mock' ||
      process.env.CODE_INDEX_EMBEDDINGS === 'off';

    // In test/mock mode, avoid loading a potentially huge on-disk cache.
    if (forceMock) {
      this.options.cacheEnabled = false;
    }

    const createMockPipeline = dimensions => {
      return async text => {
        const hash = crypto.createHash('sha256').update(String(text)).digest();
        const out = new Float32Array(dimensions);

        // Fill deterministically from the hash bytes.
        for (let i = 0; i < dimensions; i++) {
          out[i] = (hash[i % hash.length] / 255) * 2 - 1;
        }

        // Normalize to unit length to match typical embedding behavior.
        let sumSq = 0;
        for (const v of out) sumSq += v * v;
        const norm = Math.sqrt(sumSq) || 1;
        for (let i = 0; i < out.length; i++) out[i] = out[i] / norm;

        return { data: out };
      };
    };

    // Step 1: GPU Detection (if enabled)
    if (this.options.gpu?.enabled && !forceMock) {
      await this._initializeGPU();
    }

    if (!forceMock) {
      try {
        const { pipeline } = await import('@xenova/transformers');

        console.log(`Loading embedding model: ${this.options.model}...`);
        this.pipeline = await pipeline('feature-extraction', this.options.model, {
          quantized: true, // Use quantized model for faster inference
          // Note: GPU acceleration not available in Node.js
          // @xenova/transformers WebGPU support is browser-only
          // ONNX Runtime Node.js GPU bindings not yet integrated
        });

        // Keep device set by GPU detection (or default to CPU)
        if (this.device !== 'gpu') {
          this.device = 'cpu';
        }
      } catch (_err) {
        this.pipeline = createMockPipeline(this.options.dimensions);
        if (this.device !== 'gpu') {
          this.device = 'cpu';
        }
      }
    } else {
      this.pipeline = createMockPipeline(this.options.dimensions);
      if (this.device !== 'gpu') {
        this.device = 'cpu';
      }
    }

    this.initialized = true;
    if (!forceMock) {
      console.log('Embedding model loaded successfully');
    }

    // Load cache if enabled
    if (this.options.cacheEnabled) {
      await this.loadCache();
    }
  }

  /**
   * Initialize GPU detection and configuration
   * @returns {Promise<void>}
   * @private
   */
  async _initializeGPU() {
    try {
      // Use mock for testing if provided
      if (this._mockGPUDetection) {
        if (this._mockGPUDetection.available) {
          this.device = 'gpu';
          this.gpuName = this._mockGPUDetection.gpuName;
          this.gpuMemoryMB = this._mockGPUDetection.totalMemoryMB;

          // Auto-tune batch size based on GPU memory
          if (this.options.gpu.autoTuneBatchSize) {
            const { GPUDetector } = require('./gpu-detector.cjs');
            const detector = new GPUDetector();
            this.batchSize = detector.recommendBatchSize(this.gpuMemoryMB);
          }

          console.log(`✅ GPU Detected: ${this.gpuName} (${this.gpuMemoryMB}MB)`);
          console.log(`Using batch size: ${this.batchSize}`);
          return;
        }
      }

      // Real GPU detection
      const { GPUDetector } = require('./gpu-detector.cjs');
      const detector = new GPUDetector();
      const gpuInfo = await detector.detectNVIDIA();

      if (gpuInfo.available && !this._mockGPUFailure) {
        this.device = 'gpu';
        this.gpuName = gpuInfo.gpuName;
        this.gpuMemoryMB = gpuInfo.totalMemoryMB;

        // Auto-tune batch size based on GPU memory
        if (this.options.gpu.autoTuneBatchSize) {
          this.batchSize = detector.recommendBatchSize(this.gpuMemoryMB);
        }

        console.log(`✅ GPU Detected: ${this.gpuName} (${this.gpuMemoryMB}MB)`);
        console.log(`Using batch size: ${this.batchSize}`);
      } else {
        console.log('⚠️ No GPU detected, using CPU');
        this.device = 'cpu';
      }
    } catch (error) {
      console.log(`⚠️ GPU detection failed, falling back to CPU: ${error.message}`);
      this.device = 'cpu';
    }
  }

  /**
   * Check if generator is initialized
   * @returns {boolean}
   */
  isInitialized() {
    return this.initialized;
  }

  /**
   * Get embedding dimensions
   * @returns {number}
   */
  getDimensions() {
    return this.options.dimensions;
  }

  /**
   * Generate embedding for a single text
   * @param {string} text - Text to embed
   * @param {boolean} useCache - Whether to use cache
   * @returns {Promise<number[]>} Embedding vector
   */
  async embed(text, useCache = true) {
    if (!this.initialized) {
      await this.initialize();
    }

    // Check cache
    if (useCache && this.options.cacheEnabled) {
      const cached = this.getFromCache(text);
      if (cached) return cached;
    }

    // Generate embedding
    const output = await this.pipeline(text, {
      pooling: 'mean',
      normalize: true,
    });

    // Convert to array
    const embedding = Array.from(output.data);

    // Cache result
    if (useCache && this.options.cacheEnabled) {
      this.addToCache(text, embedding);
    }

    return embedding;
  }

  /**
   * Batch generate embeddings
   * @param {string[]} texts - Array of texts
   * @param {Function} [onProgress] - Progress callback (index, total)
   * @returns {Promise<number[][]>} Array of embeddings
   */
  async batchEmbed(texts, onProgress = null) {
    if (!this.initialized) {
      await this.initialize();
    }

    const embeddings = [];
    const batchSize = this.options.batchSize;
    const total = texts.length;

    for (let i = 0; i < total; i += batchSize) {
      const batch = texts.slice(i, Math.min(i + batchSize, total));
      const batchEmbeddings = await Promise.all(batch.map(text => this.embed(text)));
      embeddings.push(...batchEmbeddings);

      if (onProgress) {
        onProgress(Math.min(i + batchSize, total), total);
      }
    }

    return embeddings;
  }

  /**
   * Embed code chunks with metadata
   * @param {CodeChunk[]} chunks - Array of code chunks
   * @param {Function} [onProgress] - Progress callback
   * @returns {Promise<{chunk: CodeChunk, embedding: number[]}[]>}
   */
  async embedChunks(chunks, onProgress = null) {
    const texts = chunks.map(chunk => this.prepareForEmbedding(chunk));
    const embeddings = await this.batchEmbed(texts, onProgress);

    return chunks.map((chunk, i) => ({
      chunk,
      embedding: embeddings[i],
    }));
  }

  /**
   * Prepare chunk content for embedding
   * Adds context prefix for better code embeddings
   * @param {CodeChunk} chunk - Code chunk
   * @returns {string} Prepared text
   */
  prepareForEmbedding(chunk) {
    const prefix = `[${chunk.language}] [${chunk.type}]`;
    const signature = chunk.signature ? `Signature: ${chunk.signature}\n` : '';
    const name = chunk.name ? `Name: ${chunk.name}\n` : '';

    return `${prefix}\n${name}${signature}Code:\n${chunk.content}`;
  }

  /**
   * Generate cache key for text
   * @param {string} text - Text to hash
   * @returns {string} Cache key
   */
  getCacheKey(text) {
    return crypto.createHash('md5').update(text).digest('hex');
  }

  /**
   * Get embedding from cache
   * @param {string} text - Original text
   * @returns {number[]|null} Cached embedding or null
   */
  getFromCache(text) {
    const key = this.getCacheKey(text);
    return this.cache.get(key) || null;
  }

  /**
   * Add embedding to cache
   * @param {string} text - Original text
   * @param {number[]} embedding - Embedding vector
   */
  addToCache(text, embedding) {
    const key = this.getCacheKey(text);
    this.cache.set(key, embedding);
  }

  /**
   * Save cache to disk
   * @returns {Promise<void>}
   */
  async saveCache() {
    if (!this.options.cacheEnabled) return;

    const cacheDir = path.dirname(this.options.cachePath);
    await fs.mkdir(cacheDir, { recursive: true });

    const cacheData = Object.fromEntries(this.cache);
    await fs.writeFile(this.options.cachePath, JSON.stringify(cacheData), 'utf-8');
  }

  /**
   * Load cache from disk
   * @returns {Promise<void>}
   */
  async loadCache() {
    if (!this.options.cacheEnabled) return;

    try {
      const data = await fs.readFile(this.options.cachePath, 'utf-8');
      const cacheData = JSON.parse(data);
      this.cache = new Map(Object.entries(cacheData));
      console.log(`Loaded ${this.cache.size} cached embeddings`);
    } catch (_error) {
      // Cache file doesn't exist or is invalid
      this.cache = new Map();
    }
  }

  /**
   * Clear cache
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get cache statistics
   * @returns {Object} Cache stats
   */
  getCacheStats() {
    return {
      size: this.cache.size,
      enabled: this.options.cacheEnabled,
      path: this.options.cachePath,
    };
  }

class GPUDetector {
  constructor() {
    this._gpuInfo = null;
  }

  /**
   * Detect NVIDIA GPU using nvidia-smi
   * @returns {Promise<{available: boolean, gpuName: string|null, totalMemoryMB: number}>}
   */
  async detectNVIDIA() {
    try {
      // Query nvidia-smi for GPU name and memory
      const { stdout } = await this._execCommand(
        'nvidia-smi --query-gpu=name,memory.total --format=csv,noheader,nounits'
      );

      const lines = stdout.trim().split('\n');
      if (lines.length === 0 || !lines[0]) {
        return { available: false, gpuName: null, totalMemoryMB: 0 };
      }

      // Parse first GPU (multi-GPU systems use first one)
      const parts = lines[0].split(',');
      const gpuName = parts[0]?.trim();
      const totalMemoryMB = parseInt(parts[1]?.trim(), 10);

      if (!gpuName || !totalMemoryMB) {
        return { available: false, gpuName: null, totalMemoryMB: 0 };
      }

      this._gpuInfo = { available: true, gpuName, totalMemoryMB };
      return this._gpuInfo;
    } catch (_error) {
      // nvidia-smi not found or execution failed
      this._gpuInfo = { available: false, gpuName: null, totalMemoryMB: 0 };
      return this._gpuInfo;
    }
  }

  /**
   * Execute command (allows mocking in tests)
   * @param {string} command
   * @returns {Promise<{stdout: string, stderr: string}>}
   * @private
   */
  async _execCommand(command) {
    return execAsync(command);
  }

  /**
   * Recommend batch size based on GPU memory
   * @param {number} memoryMB - GPU memory in MB
   * @returns {number} Recommended batch size
   */
  recommendBatchSize(memoryMB) {
    if (memoryMB >= 16384) return 256; // 16GB+
    if (memoryMB >= 8192) return 128;  // 8GB
    if (memoryMB >= 4096) return 64;   // 4GB
    return 32; // 2GB or less (minimum)
  }

  /**
   * Get device information
   * @returns {Promise<{device: string, name: string, memoryMB: number}>}
   */
  async getDeviceInfo() {
    if (!this._gpuInfo) {
      await this.detectNVIDIA();
    }

    if (this._gpuInfo.available) {
      return {
        device: 'gpu',
        name: this._gpuInfo.gpuName,
        memoryMB: this._gpuInfo.totalMemoryMB
      };
    }

    return {
      device: 'cpu',
      name: 'CPU',
      memoryMB: 0
    };
  }

 * @class HybridSearch
 */
class HybridSearch {
  /**
   * Initialize hybrid search engine
   * @param {Object} indexManager - Phase 1 index manager
   * @param {Object} options - Configuration
   * @param {Object} options.astGrep - ast-grep wrapper instance
   * @param {Object} options.queryAnalyzer - Query analyzer instance
   * @param {Object} options.ranker - Result ranker instance
   * @param {number} options.semanticWeight - Semantic weight (default: 0.7)
   * @param {number} options.structuralWeight - Structural weight (default: 0.3)
   * @param {number} options.topK - Max results (default: 10)
   * @param {boolean} options.useRipgrep - Enable ripgrep pre-filter (default: true)
   */
  constructor(indexManager, options = {}) {
    this.indexManager = indexManager;
    this.options = { ...DEFAULT_OPTIONS, ...options };

    // Initialize components (provided or create defaults)
    this.astGrep = options.astGrep || null;
    this.queryAnalyzer = options.queryAnalyzer || new QueryAnalyzer();
    this.ranker =
      options.ranker ||
      new ResultRanker({
        semantic: this.options.semanticWeight,
        structural: this.options.structuralWeight,
      });
  }

  /**
   * Perform hybrid search (three-stage pipeline)
   * @param {string} query - Natural language query
   * @param {Object} options - Search options
   * @param {string} options.pattern - Optional ast-grep pattern
   * @param {string} options.language - Language filter
   * @param {number} options.limit - Max results (default: 10)
   * @returns {Promise<HybridSearchResult>} Search results with scores
   */
  async search(query, options = {}) {
    const timing = {};
    const startTotal = Date.now();

    // Stage 0: Query Analysis
    const analysis = this.queryAnalyzer.analyze(query);

    // Stage 1: Semantic Search (Phase 1)
    const semanticStart = Date.now();
    const limit = options.limit || this.options.topK;
    const language = options.language || analysis.language;
    const semanticResults = await this.semanticStage(query, limit * 2, language);
    timing.semantic = Date.now() - semanticStart;

    // Stage 2: Structural Refinement (ast-grep)
    let structuralResults = [];
    const pattern = options.pattern || analysis.astPattern;
    const astGrepLanguage = language || 'javascript';

    if (pattern && this.astGrep && (await this.astGrep.isAvailable())) {
      const astGrepStart = Date.now();
      structuralResults = await this.structuralStage(semanticResults, pattern, astGrepLanguage);
      timing.astGrep = Date.now() - astGrepStart;
    }

    // Stage 3: Combine and Rank
    const combineStart = Date.now();
    const combinedResults = this.combineResults(semanticResults, structuralResults);
    timing.combine = Date.now() - combineStart;

    timing.total = Date.now() - startTotal;

    return {
      query,
      pattern,
      results: combinedResults.slice(0, limit),
      totalMatches: combinedResults.length,
      timing,
    };
  }

  /**
   * Semantic search stage
   * @param {string} query - Query string
   * @param {number} limit - Max results
   * @param {string} language - Optional language filter
   * @returns {Promise<SemanticResult[]>} Semantic results
   */
  async semanticStage(query, limit = 20, language = null) {
    const searchOptions = { limit };

    // Add language filter if provided
    if (language) {
      searchOptions.filters = { language };
    }

    const results = await this.indexManager.semanticSearch(query, searchOptions);
    return results;
  }

  /**
   * Structural search stage (ast-grep refinement)
   * @param {SemanticResult[]} semanticResults - Results from semantic stage
   * @param {string} pattern - ast-grep pattern
   * @param {string} language - Programming language
   * @returns {Promise<HybridResult[]>} Results with structural scores
   */
  async structuralStage(semanticResults, pattern, language) {
    if (!pattern || !this.astGrep) {
      return [];
    }

    const available = await this.astGrep.isAvailable();
    if (!available) {
      return [];
    }

    return await this.astGrep.refine(semanticResults, pattern, language);
  }

  /**
   * Combine semantic and structural results
   * @param {SemanticResult[]} semanticResults - Results from Phase 1
   * @param {AstGrepResult[]} structuralResults - Results from ast-grep (optional)
   * @returns {HybridMatch[]} Combined, ranked results
   */
  combineResults(semanticResults, structuralResults = []) {
    // Combine using ranker
    let combined = this.ranker.combine(semanticResults, structuralResults);

    // Deduplicate
    combined = this.ranker.deduplicate(combined);

    // Sort by score descending
    combined = this.ranker.sort(combined);

    // Filter by confidence threshold
    combined = this.ranker.filterByConfidence(combined);

    return combined;
  }

function simpleChunk(content, filePath, language) {
  const lines = content.split('\n');
  const chunks = [];
  const chunkSize = 50; // lines per chunk

  for (let i = 0; i < lines.length; i += chunkSize) {
    const chunkLines = lines.slice(i, i + chunkSize);
    const text = chunkLines.join('\n').trim();

    if (text.length === 0) continue;

    chunks.push({
      id: `${filePath}:${i}`,
      text,
      metadata: {
        filePath,
        language,
        type: 'text_block',
        lineStart: i + 1,
        lineEnd: Math.min(i + chunkSize, lines.length),
      },
    });
  }

  return chunks;
}

function shouldUseSimpleChunking(filePath) {
  const ext = filePath.toLowerCase().match(/\.[^.]+$/)?.[0];
  // Non-code file extensions that don't benefit from AST parsing
  const simpleExtensions = [
    '.json', '.yaml', '.yml', '.md', '.txt', '.toml', '.ini',
    '.xml', '.html', '.css', '.svg', '.lock', '.log',
    '.env', '.gitignore', '.dockerignore', '.editorconfig'
  ];
  return ext && simpleExtensions.includes(ext);
}

function buildMockParseResult(content, language) {
  const lines = content.split('\n');
  const mockNodes = [];

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];

    const funcMatch = line.match(/function\s+(\w+)\s*\(/);
    const constFuncMatch = line.match(/const\s+(\w+)\s*=\s*function/);
    const arrowMatch = line.match(/const\s+(\w+)\s*=\s*\(/);

    if (funcMatch || constFuncMatch || arrowMatch) {
      const name = funcMatch?.[1] || constFuncMatch?.[1] || arrowMatch?.[1];
      let braceCount = 0;
      let foundOpen = false;
      let endLine = i;

      for (let j = i; j < lines.length; j++) {
        const chars = lines[j];
        for (const char of chars) {
          if (char === '{') {
            braceCount++;
            foundOpen = true;
          }
          if (char === '}') braceCount--;
          if (foundOpen && braceCount === 0) {
            endLine = j;
            break;
          }
        }
        if (foundOpen && braceCount === 0) break;
      }

      const functionContent = lines.slice(i, endLine + 1).join('\n');
      if (functionContent.trim().length > 0) {
        mockNodes.push({
          type: 'function_declaration',
          text: functionContent,
          startPosition: { row: i },
          endPosition: { row: endLine },
          children: [{ type: 'identifier', text: name || 'anonymous' }],
        });
      }
      i = endLine + 1;
    } else if (line.match(/class\s+(\w+)/)) {
      const className = line.match(/class\s+(\w+)/)?.[1];
      let braceCount = 0;
      let foundOpen = false;
      let endLine = i;

      for (let j = i; j < lines.length; j++) {
        const chars = lines[j];
        for (const char of chars) {
          if (char === '{') {
            braceCount++;
            foundOpen = true;
          }
          if (char === '}') braceCount--;
          if (foundOpen && braceCount === 0) {
            endLine = j;
            break;
          }
        }
        if (foundOpen && braceCount === 0) break;
      }

      const classContent = lines.slice(i, endLine + 1).join('\n');
      if (classContent.trim().length > 0) {
        mockNodes.push({
          type: 'class_declaration',
          text: classContent,
          startPosition: { row: i },
          endPosition: { row: endLine },
          children: [{ type: 'identifier', text: className || 'Unknown' }],
        });
      }
      i = endLine + 1;
    } else {
      i++;
    }
  }

  return {
    content,
    language,
    rootNode: { children: mockNodes },
  };
}

 * @class QueryAnalyzer
 */
class QueryAnalyzer {
  /**
   * Analyze a query to determine search strategy
   * @param {string} query - User query
   * @returns {QueryAnalysis} Analysis result
   */
  analyze(query) {
    if (!query || typeof query !== 'string') {
      return this._emptyAnalysis();
    }

    const normalized = query.toLowerCase().trim();
    const keywords = this.extractKeywords(query);
    const type = this._detectType(normalized, keywords);
    const language = this._detectLanguage(query);
    const concepts = this._expandConcepts(keywords);
    const astPattern = this.generatePattern(query, language || 'javascript');
    const confidence = this._calculateConfidence(type, keywords, astPattern);

    return {
      type,
      keywords,
      astPattern,
      language,
      concepts,
      confidence,
    };
  }

  /**
   * Extract keywords for ripgrep pre-filtering
   * @param {string} query - User query
   * @returns {string[]} Keywords for ripgrep
   */
  extractKeywords(query) {
    if (!query || typeof query !== 'string') {
      return [];
    }

    // Split on whitespace and punctuation, preserving original case
    const words = query.split(/[\s.,;:!?(){}[\]<>]+/).filter(word => word.length > 0);

    // Remove stop words (case-insensitive comparison)
    const filtered = words.filter(word => !STOP_WORDS.has(word.toLowerCase()));

    // Remove duplicates
    return [...new Set(filtered)];
  }

  /**
   * Generate ast-grep pattern from query
   * @param {string} query - User query
   * @param {string} language - Target language
   * @returns {string|null} Generated pattern or null
   */
  generatePattern(query, language) {
    if (!query || typeof query !== 'string') {
      return null;
    }

    const normalized = query.toLowerCase().trim();
    const lang = language || 'javascript';
    const templates = PATTERNS[lang] || PATTERNS.javascript;

    // Check for async function
    if (
      normalized.includes('async') &&
      (normalized.includes('function') || normalized.includes('func'))
    ) {
      return templates.asyncFunction || templates.function;
    }

    // Check for function
    if (FUNCTION_KEYWORDS.some(kw => normalized.includes(kw))) {
      return templates.function;
    }

    // Check for class
    if (CLASS_KEYWORDS.some(kw => normalized.includes(kw))) {
      return templates.class;
    }

    // Check for security patterns
    if (normalized.includes('sql') && normalized.includes('injection')) {
      return templates.sqlInjection || null;
    }

    if (normalized.includes('xss')) {
      return templates.xss || null;
    }

    if (normalized.includes('eval')) {
      return templates.eval || null;
    }

    // No structural pattern found - semantic search only
    return null;
  }

  /**
   * Detect query type
   * @private
   */
  _detectType(normalized, _keywords) {
    // Check for function queries
    if (FUNCTION_KEYWORDS.some(kw => normalized.includes(kw))) {
      return 'function';
    }

    // Check for class queries
    if (CLASS_KEYWORDS.some(kw => normalized.includes(kw))) {
      return 'class';
    }

    // Check for security queries
    if (SECURITY_KEYWORDS.some(kw => normalized.includes(kw))) {
      return 'security';
    }

    // Check for performance queries
    if (PERFORMANCE_KEYWORDS.some(kw => normalized.includes(kw))) {
      return 'performance';
    }

    // Default to semantic
    return 'semantic';
  }

  /**
   * Detect language from query
   * @private
   */
  _detectLanguage(query) {
    for (const [lang, pattern] of Object.entries(LANGUAGE_PATTERNS)) {
      if (pattern.test(query)) {
        return lang;
      }
    }
    return null;
  }

  /**
   * Expand concepts with synonyms
   * @private
   */
  _expandConcepts(keywords) {
    const concepts = new Set(keywords);

    for (const keyword of keywords) {
      const synonyms = SYNONYMS[keyword];
      if (synonyms) {
        synonyms.forEach(syn => concepts.add(syn));
      }
    }

    return Array.from(concepts);
  }

  /**
   * Calculate confidence score
   * @private
   */
  _calculateConfidence(type, keywords, astPattern) {
    let confidence = 0.5; // Base confidence

    // High confidence for specific patterns
    if (astPattern !== null) {
      confidence += 0.3;
    }

    // Boost confidence for specific types
    if (type === 'function' || type === 'class') {
      confidence += 0.1;
    }

    // Reduce confidence for vague queries (very few or too many keywords)
    if (keywords.length === 0) {
      confidence -= 0.5;
    } else if (keywords.length === 1) {
      confidence -= 0.2;
    } else if (keywords.length > 20) {
      confidence -= 0.2;
    } else if (keywords.length >= 2 && keywords.length <= 10) {
      // Boost confidence for moderate number of keywords
      confidence += 0.1;
    }

    return Math.max(0, Math.min(1, confidence));
  }

  /**
   * Return empty analysis for invalid input
   * @private
   */
  _emptyAnalysis() {
    return {
      type: 'semantic',
      keywords: [],
      astPattern: null,
      language: null,
      concepts: [],
      confidence: 0.0,
    };
  }

class IndexManager {
  /**
   * Create index manager
   * @param {Object} options - Configuration options
   */
  constructor(options = {}) {
    this.options = { ...DEFAULT_OPTIONS, ...options };

    // Initialize components (lazy - only when indexing)
    this.parser = null;
    this.chunker = null;
    this.vectorStore = null;
  }

  /**
   * Initialize components (lazy initialization)
   * @private
   */
  async _initializeComponents() {
    if (!this.parser) this.parser = new CodeParser();
    if (!this.chunker) {
      const minTokens = parseInt(process.env.CODE_INDEX_MIN_TOKENS || '5', 10);
      this.chunker = new SemanticChunker({ minTokens });
    }
    if (!this.vectorStore) {
      this.vectorStore = new VectorStore({
        projectRoot: this.options.projectRoot,
        bm25: this.options.bm25 || {
          k1: 1.5,
          b: 0.75,
          k_sparse: 100,
          k_dense: 10,
          rrf_k: 60,
          weights: { sparse: 0.4, dense: 0.6 },
        },
      });
    }
  }

  /**
   * Discover source files in directory (41.2)
   * @param {string} dir - Directory to scan
   * @returns {Promise<string[]>} List of source files
   * @private
   */
  async _discoverFiles(dir) {
    const files = [];
    const entries = await fs.readdir(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      const relativePath = path.relative(this.options.projectRoot, fullPath);

      // Check exclude patterns
      const excluded = this.options.excludePatterns.some(pattern => {
        const regex = new RegExp(pattern.replace(/\*\*/g, '.*').replace(/\*/g, '[^/]*'));
        return regex.test(relativePath);
      });
      if (excluded) continue;

      if (entry.isDirectory()) {
        files.push(...(await this._discoverFiles(fullPath)));
      } else if (entry.isFile()) {
        const language = this.parser.detectLanguage(fullPath);
        if (language) {
          // Check file size
          const stats = await fs.stat(fullPath);
          if (stats.size <= this.options.maxFileSize) {
            files.push(fullPath);
          }
        }
      }
    }

    return files;
  }

  /**
   * Index a directory (discover → parse → chunk → embed → store)
   * @param {string} projectPath - Path to project root
   * @param {Object} options - Indexing options
   * @param {Function} options.onProgress - Progress callback (phase, current, total)
   * @returns {Promise<Object>} Indexing results
   */
  async indexDirectory(projectPath, options = {}) {
    const startTime = Date.now();
    await this._initializeComponents();

    this.options.projectRoot = projectPath;
    const { onProgress } = options;

    // 41.2: Discover files
    const files = await this._discoverFiles(projectPath);
    if (this.options.verbose) {
      console.log(`Discovered ${files.length} source files`);
    }

    // Report scan complete
    if (onProgress) onProgress('scan', files.length, files.length);

    // Full reindex: drop code table once so we can use add-only (no per-chunk deletes)
    await this.vectorStore.dropCodeTable();

    let totalChunks = 0;
    let totalEmbeddings = 0;
    let chunksFlushed = 0;
    const fileHashes = {};
    const concurrency = this.options.concurrency || 12;
    // CRITICAL FIX: Reduce flush size from 500 to 100 to prevent memory accumulation
    // With 12 parallel workers, chunks accumulate faster than they flush
    const flushSize = Math.max(1, this.options.chunkFlushSize || 100);

    // Chunk buffer: accumulate and flush in batches for add-only writes
    const chunkBuffer = [];
    let flushPromise = Promise.resolve();

    const flushBuffer = () => {
      if (chunkBuffer.length === 0) return Promise.resolve();

      // MEMORY SAFETY: Take only flushSize chunks to avoid buffering too much during flush
      const toFlush = chunkBuffer.splice(0, flushSize);
      const embedBatchSize = this.options.embedBatchSize || 64;
      const totalBatches = Math.ceil(toFlush.length / embedBatchSize) || 1;

      // Memory monitoring
      const heapUsedGB = process.memoryUsage().heapUsed / 1024 / 1024 / 1024;
      if (this.options.verbose) {
        console.log(
          `[FLUSH] Flushing ${toFlush.length} chunks (buffer: ${chunkBuffer.length} remaining, heap: ${heapUsedGB.toFixed(2)}GB)`
        );
      }

      if (onProgress) onProgress('embed', 0, totalBatches);
      return this.vectorStore
        .addChunksOnly(toFlush, {
          embedBatchSize,
          onEmbedProgress: onProgress
            ? (batchDone, tot) => onProgress('embed', batchDone, tot)
            : undefined,
        })
        .then(async () => {
          chunksFlushed += toFlush.length;
          if (onProgress) onProgress('index', chunksFlushed, totalChunks);
          // Save BM25 index after each flush (incremental persistence)
          await this.vectorStore.saveBM25Index();

          if (this.options.verbose) {
            const heapAfterGB = process.memoryUsage().heapUsed / 1024 / 1024 / 1024;
            console.log(
              `[FLUSH] Complete - ${chunksFlushed}/${totalChunks} indexed (heap: ${heapAfterGB.toFixed(2)}GB)`
            );
          }
        });
    };

    // Worker pool for parse+chunk (CPU-bound) — true multi-core parallelism
    const workerPath = path.resolve(__dirname, 'parse-chunk-worker.cjs');
    const pool = new Piscina({
      filename: workerPath,
      maxThreads: concurrency,
      minThreads: Math.min(concurrency, 4),
      // CRITICAL FIX: Set memory limits per worker to prevent OOM
      resourceLimits: {
        maxOldGenerationSizeMb: 4096,  // 4GB per worker (was default ~512MB)
        maxYoungGenerationSizeMb: 512, // 512MB for young generation
      },
    });

    const inFlight = new Set();
    let filesProcessed = 0;
    const parseStartTime = Date.now();

    const runOne = async (filePath, index) => {
      // CRITICAL FIX: Skip files >1MB before sending to worker to prevent OOM
      const stats = await fs.stat(filePath);
      if (stats.size > 1 * 1024 * 1024) {
        if (this.options.verbose) {
          console.log(`[SKIP] Large file: ${filePath} (${(stats.size / 1024 / 1024).toFixed(2)}MB)`);
        }
        return { filePath, chunks: [], hash: null, skipped: true, index };
      }

      const content = await fs.readFile(filePath, 'utf-8');
      const language = this.parser.detectLanguage(filePath);
      if (!language) {
        return { filePath, chunks: [], hash: '', index };
      }
      const result = await pool.run({ filePath, content, language });
      return { ...result, index };
    };

    for (let i = 0; i < files.length; i++) {
      const filePath = files[i];
      const index = i + 1;

      // Cap in-flight to concurrency to limit memory (workers + queued content)
      while (inFlight.size >= concurrency) {
        await Promise.race(inFlight);
      }

      const task = runOne.call(this, filePath, index);
      inFlight.add(task);
      task
        .then(async result => {
          filesProcessed++;
          fileHashes[result.filePath] = { hash: result.hash, chunks: result.chunks.length };
          totalChunks += result.chunks.length;
          totalEmbeddings += result.chunks.length;

          // Progress logging every 100 files with memory monitoring
          if (this.options.verbose && filesProcessed % 100 === 0) {
            const elapsedSec = (Date.now() - parseStartTime) / 1000;
            const filesPerSec = filesProcessed / elapsedSec;
            const remainingFiles = files.length - filesProcessed;
            const estimatedMin = (remainingFiles / filesPerSec) / 60;
            const heapGB = process.memoryUsage().heapUsed / 1024 / 1024 / 1024;
            console.log(
              `[PARSE] ${filesProcessed}/${files.length} files (${filesPerSec.toFixed(1)} files/sec, ~${estimatedMin.toFixed(1)} min remaining, buffer: ${chunkBuffer.length} chunks, heap: ${heapGB.toFixed(2)}GB)`
            );
          }

          if (onProgress) {
            onProgress('parse', result.index, files.length);
            onProgress('chunk', result.index, files.length);
          }
          if (result.chunks.length > 0) {
            chunkBuffer.push(...result.chunks);

            // CRITICAL FIX: Non-blocking flush - don't wait for completion
            // This keeps workers flowing while flush happens in background
            const heapUsedGB = process.memoryUsage().heapUsed / 1024 / 1024 / 1024;

            if (chunkBuffer.length >= flushSize) {
              // Non-blocking: trigger flush but don't wait
              flushPromise = flushPromise.then(() => flushBuffer());
            }

            // Emergency: If memory explodes, force wait
            if (heapUsedGB > 16) {
              console.warn('⚠️  MEMORY HIGH, waiting for flush...');
              await flushPromise;
            }
          }
          if (onProgress && result.chunks.length === 0)
            onProgress('index', chunksFlushed, totalChunks);
        })
        .catch(err => console.error(`Error indexing ${filePath}:`, err.message))
        .finally(() => inFlight.delete(task));

      if (this.options.verbose && (i + 1) % 500 === 0) {
        console.log(`Processed ${i + 1}/${files.length} files`);
      }
    }

    await Promise.all(Array.from(inFlight));
    await pool.destroy();

    // Flush remaining chunks and wait for any in-flight flush
    await flushPromise;
    await flushBuffer();

    // 41.8: Save metadata
    const byLanguage = {};
    for (const filePath of files) {
      const lang = this.parser.detectLanguage(filePath);
      if (lang) {
        byLanguage[lang] = (byLanguage[lang] || 0) + 1;
      }
    }

    const metadata = {
      timestamp: new Date().toISOString(),
      stats: {
        files: files.length,
        chunks: totalChunks,
        embeddings: totalEmbeddings,
        byLanguage,
      },
      files: fileHashes,
    };

    // Save metadata (use projectRoot for path)
    const metadataPath = path.join(
      this.options.projectRoot,
      '.claude/context/code-index/metadata.json'
    );
    const metadataDir = path.dirname(metadataPath);
    await fs.mkdir(metadataDir, { recursive: true });
    await fs.writeFile(metadataPath, JSON.stringify(metadata, null, 2));

    // Build and save Merkle tree for future incremental updates
    const merklePath = path.join(
      this.options.projectRoot,
      '.claude/context/code-index/merkle-tree.json'
    );
    const merkleTree = new MerkleTree(this.options.projectRoot, this.options.excludePatterns);
    await merkleTree.build();
    await merkleTree.save(merklePath);

    return {
      filesIndexed: files.length,
      chunksCreated: totalChunks,
      embeddingsGenerated: totalEmbeddings,
      timeMs: Date.now() - startTime,
    };
  }

  /**
   * Perform incremental update using Merkle tree change detection
   * Only re-indexes files that have changed since last index
   * @param {Object} options - Update options
   * @returns {Promise<Object>} Update results
   */
  async incrementalUpdate(options = {}) {
    const startTime = Date.now();
    await this._initializeComponents();

    const merklePath = path.join(
      this.options.projectRoot,
      '.claude/context/code-index/merkle-tree.json'
    );

    // Load old Merkle tree
    const oldTree = await MerkleTree.load(merklePath);

    if (!oldTree) {
      // No previous tree - do full index
      const result = await this.indexDirectory(this.options.projectRoot, options);
      // Save new tree
      const newTree = new MerkleTree(this.options.projectRoot, this.options.excludePatterns);
      await newTree.build();
      await newTree.save(merklePath);
      return {
        ...result,
        updateType: 'full',
        filesChanged: result.filesIndexed,
      };
    }

    // Build new Merkle tree
    const newTree = new MerkleTree(this.options.projectRoot, this.options.excludePatterns);
    await newTree.build();

    // Compare trees to find changes
    const diff = MerkleTree.diff(oldTree, newTree.root, '');

    if (diff.added.length === 0 && diff.modified.length === 0 && diff.deleted.length === 0) {
      // No changes
      return {
        updateType: 'incremental',
        filesAdded: 0,
        filesModified: 0,
        filesDeleted: 0,
        chunksAdded: 0,
        chunksUpdated: 0,
        chunksDeleted: 0,
        timeMs: Date.now() - startTime,
      };
    }

    // Process changed files
    const filesToIndex = [...diff.added, ...diff.modified];
    const filesToDelete = diff.deleted;

    let chunksAdded = 0;
    let chunksUpdated = 0;
    let chunksDeleted = 0;

    // Delete removed files from index
    for (const filePath of filesToDelete) {
      const fullPath = path.isAbsolute(filePath)
        ? filePath
        : path.join(this.options.projectRoot, filePath);
      await this.vectorStore.deleteFile(fullPath);
      chunksDeleted++;
    }

    // Re-index changed/added files
    for (const filePath of filesToIndex) {
      const fullPath = path.isAbsolute(filePath)
        ? filePath
        : path.join(this.options.projectRoot, filePath);

      try {
        // Check if file exists and is readable
        await fs.access(fullPath);
        const stats = await fs.stat(fullPath);
        if (stats.size > this.options.maxFileSize) continue;

        // Parse, chunk, embed, and store
        const content = await fs.readFile(fullPath, 'utf8');
        const language = this.parser.detectLanguage(fullPath);
        if (!language) continue;

        const parseResult = this.parser.parse(content, language);
        const chunks = this.chunker.chunk(parseResult, fullPath);
        if (chunks.length === 0) continue;

        // Delete old chunks for this file first
        await this.vectorStore.deleteFile(fullPath);
        chunksDeleted += chunks.length;

        // Add new chunks
        await this.vectorStore.addChunks(chunks);

        if (diff.added.includes(filePath)) {
          chunksAdded += chunks.length;
        } else {
          chunksUpdated += chunks.length;
        }
      } catch (_error) {
        // File might not exist or be unreadable - skip
        continue;
      }
    }

    // Save new Merkle tree
    await newTree.save(merklePath);

    // Update metadata
    const metadataPath = path.join(
      this.options.projectRoot,
      '.claude/context/code-index/metadata.json'
    );
    let metadata = {};
    try {
      const metadataContent = await fs.readFile(metadataPath, 'utf8');
      metadata = JSON.parse(metadataContent);
    } catch (_err) {
      // Metadata doesn't exist - create new
    }

    metadata.lastIncrementalUpdate = new Date().toISOString();
    metadata.incrementalStats = {
      filesAdded: diff.added.length,
      filesModified: diff.modified.length,
      filesDeleted: diff.deleted.length,
      chunksAdded,
      chunksUpdated,
      chunksDeleted,
    };

    await fs.writeFile(metadataPath, JSON.stringify(metadata, null, 2));

    return {
      updateType: 'incremental',
      filesAdded: diff.added.length,
      filesModified: diff.modified.length,
      filesDeleted: diff.deleted.length,
      chunksAdded,
      chunksUpdated,
      chunksDeleted,
      timeMs: Date.now() - startTime,
    };
  }

  /**
   * Search for code using semantic similarity
   * @param {string} query - Natural language query
   * @param {Object} options - Search options
   * @param {number} options.limit - Max results (default: 10)
   * @param {number} options.minScore - Minimum similarity (default: 0.5)
   * @param {Object} options.filters - Metadata filters
   * @returns {Promise<Array>} Search results
   */
  async semanticSearch(query, options = {}) {
    await this._initializeComponents();

    const limit = options.limit || 10;
    const minScore = options.minScore || 0.5;
    let searchResults = [];
    try {
      searchResults = await this.vectorStore.search(query, {
        limit,
        minScore,
        filters: options.filters || {},
      });
    } catch (error) {
      if (process.env.CODE_INDEX_DEBUG) {
        console.warn('[code-indexing] Semantic search unavailable:', error.message);
      }
      return [];
    }

    const results = [];
    for (const result of searchResults) {
      const metadata = result.metadata || {};

      let code = null;
      try {
        const content = await fs.readFile(metadata.filePath, 'utf-8');
        const lines = content.split('\n');
        code = lines.slice(metadata.lineStart - 1, metadata.lineEnd).join('\n');
      } catch (_error) {
        code = null;
      }

      results.push({
        id: result.id,
        code,
        filePath: metadata.filePath,
        language: metadata.language,
        type: metadata.type,
        lineRange: [metadata.lineStart, metadata.lineEnd],
        similarity: result.similarity,
        metadata,
      });
    }

    return results;
  }

