      .split(',')
      .map(mode => mode.trim())
      .filter(Boolean);
  }

  return [];
}

function detectRepeatedErrors(errors, threshold = DEFAULT_REPEATED_THRESHOLD) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return [];
  }

  // Memory safety: reject overly large inputs
  if (errors.length > MAX_INPUT_ERRORS) {
    console.warn(
      `[detectRepeatedErrors] Input too large (${errors.length} errors). Truncating to ${MAX_INPUT_ERRORS}.`
    );
    errors = errors.slice(0, MAX_INPUT_ERRORS);
  }

  const messageCounts = new Map();

  for (const error of errors) {
    const message = error.message || 'unknown';
    const key = message;

    if (!messageCounts.has(key)) {
      messageCounts.set(key, {
        message,
        category: error.category,
        count: 0,
        errorIds: [],
        firstSeen: error.timestamp,
        lastSeen: error.timestamp,
      });
    }

    const entry = messageCounts.get(key);
    entry.count++;
    entry.errorIds.push(error.errorId);
    entry.lastSeen = error.timestamp;
  }

  const results = Array.from(messageCounts.values()).filter(entry => entry.count >= threshold);

  // Memory safety: limit result size
  if (results.length > MAX_RESULT_SIZE) {
    console.warn(
      `[detectRepeatedErrors] Result too large (${results.length} patterns). Truncating to top ${MAX_RESULT_SIZE}.`
    );
    return results.sort((a, b) => b.count - a.count).slice(0, MAX_RESULT_SIZE);
  }

  return results;
}

function detectCascades(errors) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return [];
  }

  // Memory safety: reject overly large inputs
  if (errors.length > MAX_INPUT_ERRORS) {
    console.warn(
      `[detectCascades] Input too large (${errors.length} errors). Truncating to ${MAX_INPUT_ERRORS}.`
    );
    errors = errors.slice(0, MAX_INPUT_ERRORS);
  }

  const cascades = [];
  const errorMap = new Map(errors.map(e => [e.errorId, e]));

  // Build parent->child relationships for explicit cascades
  const parentToChildren = new Map();
  const childToParent = new Map();

  for (const error of errors) {
    const parentId = error.correlation?.parentErrorId;
    if (parentId && errorMap.has(parentId)) {
      if (!parentToChildren.has(parentId)) {
        parentToChildren.set(parentId, []);
      }
      parentToChildren.get(parentId).push(error.errorId);
      childToParent.set(error.errorId, parentId);
    }
  }

  // Find root errors (parents that are not children of anyone)
  const processedRoots = new Set();
  for (const parentId of parentToChildren.keys()) {
    // Find the ultimate root by traversing up the chain
    let root = parentId;
    while (childToParent.has(root)) {
      root = childToParent.get(root);
    }

    if (processedRoots.has(root)) continue;
    processedRoots.add(root);

    // Collect all descendants from this root
    const allChildren = [];
    const queue = [root];
    const visited = new Set([root]);

    while (queue.length > 0) {
      const current = queue.shift();
      const children = parentToChildren.get(current) || [];
      for (const child of children) {
        if (!visited.has(child)) {
          visited.add(child);
          allChildren.push(child);
          queue.push(child);
        }
      }
    }

    if (allChildren.length > 0) {
      cascades.push({
        rootErrorId: root,
        childErrorIds: allChildren,
        cascadeDepth: Math.max(1, allChildren.length),
      });
    }
  }

  // Detect implicit cascades via temporal proximity within same task
  const taskGroups = new Map();
  for (const error of errors) {
    const taskId = error.context?.taskId;
    if (taskId) {
      if (!taskGroups.has(taskId)) {
        taskGroups.set(taskId, []);
      }
      taskGroups.get(taskId).push(error);
    }
  }

  for (const [_taskId, taskErrors] of taskGroups) {
    if (taskErrors.length < 2) continue;

    // Sort by timestamp
    const sorted = taskErrors.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

    // Find critical/high severity errors that might be root causes
    const potentialRoots = sorted.filter(e => e.severity === 'CRITICAL' || e.severity === 'HIGH');

    for (const root of potentialRoots) {
      const rootTime = new Date(root.timestamp).getTime();
      const children = sorted.filter(e => {
        if (e.errorId === root.errorId) return false;
        const childTime = new Date(e.timestamp).getTime();
        return (
          childTime > rootTime &&
          childTime - rootTime <= DEFAULT_CASCADE_WINDOW_MS &&
          !processedRoots.has(root.errorId) // Don't duplicate with explicit cascades
        );
      });

      if (children.length > 0) {
        cascades.push({
          rootErrorId: root.errorId,
          childErrorIds: children.map(c => c.errorId),
          cascadeDepth: 1,
          implicit: true,
        });
      }
    }
  }

  // Memory safety: limit result size
  if (cascades.length > MAX_RESULT_SIZE) {
    console.warn(
      `[detectCascades] Result too large (${cascades.length} cascades). Truncating to ${MAX_RESULT_SIZE}.`
    );
    cascades.sort((a, b) => b.childErrorIds.length - a.childErrorIds.length);
    return cascades.slice(0, MAX_RESULT_SIZE);
  }

  return cascades;
}

function detectHookFailures(errors, threshold = DEFAULT_HOOK_FAILURE_THRESHOLD) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return [];
  }

  // Memory safety: reject overly large inputs
  if (errors.length > MAX_INPUT_ERRORS) {
    console.warn(
      `[detectHookFailures] Input too large (${errors.length} errors). Truncating to ${MAX_INPUT_ERRORS}.`
    );
    errors = errors.slice(0, MAX_INPUT_ERRORS);
  }

  const hookCounts = new Map();

  for (const error of errors) {
    if (error.category !== 'HOOK_FAILURE') continue;

    const hookName = error.source?.location || 'unknown';

    if (!hookCounts.has(hookName)) {
      hookCounts.set(hookName, {
        hookName,
        count: 0,
        errorIds: [],
        lastOccurrence: null,
      });
    }

    const entry = hookCounts.get(hookName);
    entry.count++;
    entry.errorIds.push(error.errorId);
    entry.lastOccurrence = error.timestamp;
  }

  const results = Array.from(hookCounts.values()).filter(entry => entry.count > threshold);

  // Memory safety: limit result size
  if (results.length > MAX_RESULT_SIZE) {
    console.warn(
      `[detectHookFailures] Result too large (${results.length} patterns). Truncating to top ${MAX_RESULT_SIZE}.`
    );
    return results.sort((a, b) => b.count - a.count).slice(0, MAX_RESULT_SIZE);
  }

  return results;
}

function detectToolFailures(errors, threshold = DEFAULT_TOOL_FAILURE_THRESHOLD) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return [];
  }

  // Memory safety: reject overly large inputs
  if (errors.length > MAX_INPUT_ERRORS) {
    console.warn(
      `[detectToolFailures] Input too large (${errors.length} errors). Truncating to ${MAX_INPUT_ERRORS}.`
    );
    errors = errors.slice(0, MAX_INPUT_ERRORS);
  }

  const toolCounts = new Map();

  for (const error of errors) {
    if (error.category !== 'TOOL_FAILURE') continue;

    const toolName = error.context?.toolName || 'unknown';

    if (!toolCounts.has(toolName)) {
      toolCounts.set(toolName, {
        toolName,
        count: 0,
        errorIds: [],
        lastOccurrence: null,
      });
    }

    const entry = toolCounts.get(toolName);
    entry.count++;
    entry.errorIds.push(error.errorId);
    entry.lastOccurrence = error.timestamp;
  }

  const results = Array.from(toolCounts.values()).filter(entry => entry.count >= threshold);

  // Memory safety: limit result size
  if (results.length > MAX_RESULT_SIZE) {
    console.warn(
      `[detectToolFailures] Result too large (${results.length} patterns). Truncating to top ${MAX_RESULT_SIZE}.`
    );
    return results.sort((a, b) => b.count - a.count).slice(0, MAX_RESULT_SIZE);
  }

  return results;
}

function detectAgentIssues(errors, threshold = DEFAULT_AGENT_ERROR_THRESHOLD) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return [];
  }

  // Memory safety: reject overly large inputs
  if (errors.length > MAX_INPUT_ERRORS) {
    console.warn(
      `[detectAgentIssues] Input too large (${errors.length} errors). Truncating to ${MAX_INPUT_ERRORS}.`
    );
    errors = errors.slice(0, MAX_INPUT_ERRORS);
  }

  const agentCounts = new Map();

  for (const error of errors) {
    const agentName = error.context?.agentName || 'unknown';

    if (!agentCounts.has(agentName)) {
      agentCounts.set(agentName, {
        agentName,
        errorCount: 0,
        errorIds: [],
        bySeverity: { CRITICAL: 0, HIGH: 0, MEDIUM: 0, LOW: 0 },
      });
    }

    const entry = agentCounts.get(agentName);
    entry.errorCount++;
    entry.errorIds.push(error.errorId);
    if (error.severity) {
      entry.bySeverity[error.severity] = (entry.bySeverity[error.severity] || 0) + 1;
    }
  }

  const results = Array.from(agentCounts.values()).filter(entry => entry.errorCount > threshold);

  // Memory safety: limit result size
  if (results.length > MAX_RESULT_SIZE) {
    console.warn(
      `[detectAgentIssues] Result too large (${results.length} patterns). Truncating to top ${MAX_RESULT_SIZE}.`
    );
    return results.sort((a, b) => b.errorCount - a.errorCount).slice(0, MAX_RESULT_SIZE);
  }

  return results;
}

function detectSeverityEscalations(errors) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return [];
  }

  const severityOrder = { LOW: 1, MEDIUM: 2, HIGH: 3, CRITICAL: 4 };
  const messageHistory = new Map();

  for (const error of errors) {
    const message = error.message || 'unknown';

    if (!messageHistory.has(message)) {
      messageHistory.set(message, []);
    }

    messageHistory.get(message).push({
      timestamp: error.timestamp,
      severity: error.severity,
      errorId: error.errorId,
    });
  }

  const escalations = [];

  for (const [message, history] of messageHistory) {
    if (history.length < 2) continue;

    // Sort by timestamp
    const sorted = history.sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

    // Check if severity is increasing
    let escalating = false;
    let previousSeverity = severityOrder[sorted[0].severity] || 0;

    for (let i = 1; i < sorted.length; i++) {
      const currentSeverity = severityOrder[sorted[i].severity] || 0;
      if (currentSeverity > previousSeverity) {
        escalating = true;
      }
      previousSeverity = currentSeverity;
    }

    if (escalating) {
      escalations.push({
        message,
        fromSeverity: sorted[0].severity,
        toSeverity: sorted[sorted.length - 1].severity,
        occurrences: sorted.length,
        errorIds: sorted.map(s => s.errorId),
      });
    }
  }

  return escalations;
}

function detectPatterns(errors) {
  return {
    repeatedErrors: detectRepeatedErrors(errors),
    cascades: detectCascades(errors),
    hookFailures: detectHookFailures(errors),
    toolFailures: detectToolFailures(errors),
    agentIssues: detectAgentIssues(errors),
    severityEscalations: detectSeverityEscalations(errors),
  };
}

function scoreAgentHealth(agentName, errors) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return 100; // No errors = perfect health
  }

  const agentErrors = errors.filter(e => e.context?.agentName === agentName);

  if (agentErrors.length === 0) {
    return 100; // No errors for this agent
  }

  // Base score starts at 100
  let score = 100;

  // Deduct points based on error count and severity
  const severityWeights = { CRITICAL: 20, HIGH: 10, MEDIUM: 5, LOW: 2 };

  for (const error of agentErrors) {
    const weight = severityWeights[error.severity] || 3;
    score -= weight;
  }

  // Ensure score is between 0 and 100
  return Math.max(0, Math.min(100, score));
}

function generateRecommendations(patterns) {
  const recommendations = [];

  // Recommendations for repeated errors
  for (const repeated of patterns.repeatedErrors || []) {
    recommendations.push({
      priority: repeated.count > 5 ? 'HIGH' : 'MEDIUM',
      issue: `${repeated.count} repeated occurrences of: "${repeated.message.substring(0, 50)}..."`,
      suggestion: `Investigate root cause of recurring error. Consider adding retry logic or improving error handling.`,
      errorIds: repeated.errorIds,
    });
  }

  // Recommendations for cascades
  for (const cascade of patterns.cascades || []) {
    recommendations.push({
      priority: 'HIGH',
      issue: `Error cascade detected starting from ${cascade.rootErrorId}, affecting ${cascade.childErrorIds.length} subsequent operations`,
      suggestion: `Fix the root cause error (${cascade.rootErrorId}). Add circuit breaker pattern to prevent cascade failures.`,
      errorIds: [cascade.rootErrorId, ...cascade.childErrorIds],
    });
  }

  // Recommendations for agent issues
  for (const agentIssue of patterns.agentIssues || []) {
    recommendations.push({
      priority: agentIssue.bySeverity?.CRITICAL > 0 ? 'CRITICAL' : 'HIGH',
      issue: `Agent "${agentIssue.agentName}" has ${agentIssue.errorCount} errors`,
      suggestion: `Review agent configuration and training data. Consider adding more explicit error handling.`,
      errorIds: agentIssue.errorIds,
    });
  }

  // Recommendations for hook failures
  for (const hookFailure of patterns.hookFailures || []) {
    recommendations.push({
      priority: 'HIGH',
      issue: `Hook "${hookFailure.hookName}" failed ${hookFailure.count} times`,
      suggestion: `Review hook logic and error handling. Validate inputs and add defensive coding.`,
      errorIds: hookFailure.errorIds,
    });
  }

  // Recommendations for tool failures
  for (const toolFailure of patterns.toolFailures || []) {
    recommendations.push({
      priority: 'MEDIUM',
      issue: `Tool "${toolFailure.toolName}" failed ${toolFailure.count} times`,
      suggestion: `Check tool configuration and dependencies. Consider adding input validation.`,
      errorIds: toolFailure.errorIds,
    });
  }

  // Recommendations for severity escalations
  for (const escalation of patterns.severityEscalations || []) {
    recommendations.push({
      priority: 'HIGH',
      issue: `Error severity escalating: "${escalation.message.substring(0, 30)}..." (${escalation.fromSeverity} -> ${escalation.toSeverity})`,
      suggestion: `Urgent: Address degradation pattern before it becomes critical.`,
      errorIds: escalation.errorIds,
    });
  }

  return recommendations;
}

class MerkleNode {
  constructor(type, name, hash, children = null, metadata = {}) {
    this.type = type; // 'file' | 'directory'
    this.name = name;
    this.hash = hash;
    this.children = children; // Map<string, MerkleNode> for directories
    this.metadata = metadata; // { mtime, size, etc. }
  }

  /**
   * Serialize node to JSON
   */
  toJSON() {
    const result = {
      type: this.type,
      name: this.name,
      hash: this.hash,
      metadata: this.metadata,
    };

    if (this.children) {
      result.children = {};
      for (const [name, child] of Object.entries(this.children)) {
        result.children[name] = child.toJSON();
      }
    }

    return result;
  }

  /**
   * Create node from JSON
   */
  static fromJSON(data) {
    const node = new MerkleNode(data.type, data.name, data.hash, null, data.metadata || {});

    if (data.children) {
      node.children = {};
      for (const [name, childData] of Object.entries(data.children)) {
        node.children[name] = MerkleNode.fromJSON(childData);
      }
    }

    return node;
  }

class MerkleTree {
  constructor(rootPath, excludePatterns = []) {
    this.rootPath = rootPath;
    this.excludePatterns = excludePatterns;
    this.root = null;
  }

  _globToRegExp(pattern) {
    // Minimal glob support for the patterns we use in code-indexing:
    // - `*` matches within a path segment
    // - `**` matches across path segments
    // This is intentionally small and avoids pulling in a glob dependency.
    // Escape regex metacharacters but keep glob tokens `*` intact for replacement.
    const escaped = String(pattern).replace(/[.+?^${}()|[\]\\]/g, '\\$&');

    const regexSource = escaped
      // `**/` should match "foo/" or be empty at the start of a path.
      .replace(/\*\*\//g, '(?:.*\\/)?')
      // `/**` should match "/foo" or be empty at the end of a path.
      .replace(/\/\*\*/g, '(?:\\/.*)?')
      .replace(/\*\*/g, '.*')
      .replace(/\*/g, '[^/]*');

    return new RegExp(`^${regexSource}$`);
  }

  /**
   * Hash file content
   */
  async hashFile(filePath) {
    try {
      const content = await fs.readFile(filePath);
      const stats = await fs.stat(filePath);

      // Include content + metadata in hash
      const hashInput = JSON.stringify({
        content: content.toString('base64').slice(0, 1000), // First 1KB for speed
        size: stats.size,
        mtime: stats.mtimeMs,
      });

      return crypto.createHash('sha256').update(hashInput).digest('hex');
    } catch (_err) {
      // File might not exist or be unreadable
      return null;
    }
  }

  /**
   * Hash directory by combining children hashes
   */
  hashDirectory(children) {
    const childHashes = Object.values(children)
      .map(child => child.hash)
      .sort()
      .join('');

    return crypto.createHash('sha256').update(childHashes).digest('hex');
  }

  /**
   * Check if path should be excluded
   */
  shouldExclude(relativePath) {
    const normalized = relativePath.replace(/\\/g, '/');
    return this.excludePatterns.some(pattern => this._globToRegExp(pattern).test(normalized));
  }

  /**
   * Build Merkle tree for a directory
   */
  async buildTree(dirPath, relativePath = '') {
    try {
      const entries = await fs.readdir(dirPath, { withFileTypes: true });
      const children = {};

      for (const entry of entries) {
        const entryPath = path.join(dirPath, entry.name);
        const entryRelative = path.join(relativePath, entry.name).replace(/\\/g, '/');

        // Check exclusions
        if (this.shouldExclude(entryRelative)) {
          continue;
        }

        if (entry.isDirectory()) {
          // Recursively build subtree
          const subtree = await this.buildTree(entryPath, entryRelative);
          if (subtree) {
            children[entry.name] = subtree;
          }
        } else if (entry.isFile()) {
          // Hash file
          const hash = await this.hashFile(entryPath);
          if (hash) {
            const stats = await fs.stat(entryPath);
            children[entry.name] = new MerkleNode('file', entry.name, hash, null, {
              path: entryRelative,
              size: stats.size,
              mtime: stats.mtimeMs,
            });
          }
        }
      }

      // Hash directory from children
      if (Object.keys(children).length === 0) {
        return null; // Empty directory
      }

      const dirHash = this.hashDirectory(children);
      const dirName = path.basename(dirPath);

      return new MerkleNode('directory', dirName, dirHash, children, {
        path: relativePath,
      });
    } catch (_err) {
      // Directory might not exist or be inaccessible
      return null;
    }
  }

  /**
   * Build tree from root
   */
  async build() {
    this.root = await this.buildTree(this.rootPath, '');
    return this.root;
  }

  /**
   * Compare two trees and return differences
   */
  static diff(oldTree, newTree, basePath = '') {
    const differences = {
      added: [],
      modified: [],
      deleted: [],
    };

    if (!oldTree && newTree) {
      // Entire subtree added
      differences.added.push(basePath);
      return differences;
    }

    if (oldTree && !newTree) {
      // Entire subtree deleted
      differences.deleted.push(basePath);
      return differences;
    }

    if (!oldTree || !newTree) {
      return differences;
    }

    // If hashes match, no changes in this subtree
    if (oldTree.hash === newTree.hash) {
      return differences;
    }

    // Hashes differ - check children
    if (oldTree.type === 'file' && newTree.type === 'file') {
      // File modified
      differences.modified.push(basePath);
    } else if (oldTree.type === 'directory' && newTree.type === 'directory') {
      // Compare children
      const oldChildren = oldTree.children || {};
      const newChildren = newTree.children || {};
      const allNames = new Set([...Object.keys(oldChildren), ...Object.keys(newChildren)]);

      for (const name of allNames) {
        const childPath = path.join(basePath, name).replace(/\\/g, '/');
        const oldChild = oldChildren[name];
        const newChild = newChildren[name];

        const childDiff = MerkleTree.diff(oldChild, newChild, childPath);
        differences.added.push(...childDiff.added);
        differences.modified.push(...childDiff.modified);
        differences.deleted.push(...childDiff.deleted);
      }
    }

    return differences;
  }

  /**
   * Save tree to file
   */
  async save(filePath) {
    if (!this.root) {
      throw new Error('Tree not built. Call build() first.');
    }

    const dir = path.dirname(filePath);
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(filePath, JSON.stringify(this.root.toJSON(), null, 2));
  }

  /**
   * Load tree from file
   */
  static async load(filePath) {
    try {
      const data = await fs.readFile(filePath, 'utf8');
      const json = JSON.parse(data);
      return MerkleNode.fromJSON(json);
    } catch (_err) {
      return null;
    }
  }

 * @class ResultRanker
 */
class ResultRanker {
  /**
   * Initialize ranker with weights
   * @param {Object} weights - Score weights
   * @param {number} weights.semantic - Weight for semantic score (default: 0.7)
   * @param {number} weights.structural - Weight for structural score (default: 0.3)
   * @param {number} weights.recency - Weight for recency boost (default: 0.05)
   * @param {number} weights.keyword - Weight for keyword boost (default: 0.1)
   * @param {number} weights.confidenceThreshold - Minimum score to include (default: 0.3)
   */
  constructor(weights = {}) {
    this.weights = {
      semantic: weights.semantic ?? DEFAULT_WEIGHTS.semantic,
      structural: weights.structural ?? DEFAULT_WEIGHTS.structural,
      recency: weights.recency ?? DEFAULT_WEIGHTS.recency,
      keyword: weights.keyword ?? DEFAULT_WEIGHTS.keyword,
    };

    this.confidenceThreshold = weights.confidenceThreshold ?? 0.3;
  }

  /**
   * Calculate combined score
   * @param {number} semanticScore - Semantic similarity (0-1)
   * @param {number} structuralScore - Structural match (0 or 1)
   * @returns {number} Combined score (0-1)
   */
  calculateScore(semanticScore, structuralScore) {
    const baseScore =
      this.weights.semantic * semanticScore + this.weights.structural * structuralScore;

    // Normalize to 0-1 range
    const maxPossible = this.weights.semantic + this.weights.structural;
    return baseScore / maxPossible;
  }

  /**
   * Combine semantic and structural results
   * @param {SemanticResult[]} semanticResults - Results from Phase 1
   * @param {AstGrepResult[]} structuralResults - Results from ast-grep
   * @returns {HybridMatch[]} Combined, deduplicated results
   */
  combine(semanticResults, structuralResults) {
    // Handle empty inputs
    if (!semanticResults || semanticResults.length === 0) {
      return [];
    }

    // Create lookup map for structural matches
    const structuralMap = new Map();
    for (const sr of structuralResults || []) {
      const key = `${sr.filePath}:${sr.lineStart}-${sr.lineEnd}`;
      structuralMap.set(key, sr);
    }

    // Enhance semantic results with structural data
    const combined = semanticResults.map(semResult => {
      // Check for exact line range match
      const key = `${semResult.filePath}:${semResult.lineStart}-${semResult.lineEnd}`;
      const exactMatch = structuralMap.get(key);

      let structuralScore = 0.0;
      const sources = ['semantic'];
      let matches = null;

      if (exactMatch) {
        structuralScore = 1.0;
        sources.push('structural');
        matches = exactMatch.matches || null;
      }

      const combinedScore = this.calculateScore(semResult.semanticScore, structuralScore);

      return {
        filePath: semResult.filePath,
        lineStart: semResult.lineStart,
        lineEnd: semResult.lineEnd,
        content: semResult.content,
        score: combinedScore,
        semanticScore: semResult.semanticScore,
        structuralScore: structuralScore,
        sources: sources,
        metadata: semResult.metadata || {},
        matches: matches,
      };
    });

    return combined;
  }

  /**
   * Deduplicate results by file:line
   * @param {HybridMatch[]} results - Results to dedupe
   * @returns {HybridMatch[]} Deduplicated results
   */
  deduplicate(results) {
    if (!results || results.length === 0) {
      return [];
    }

    const seen = new Map();

    for (const result of results) {
      const key = `${result.filePath}:${result.lineStart}-${result.lineEnd}`;

      // Keep highest score when duplicates found
      if (!seen.has(key) || seen.get(key).score < result.score) {
        seen.set(key, result);
      }
    }

    return Array.from(seen.values());
  }

  /**
   * Sort results by combined score
   * @param {HybridMatch[]} results - Results to sort
   * @returns {HybridMatch[]} Sorted results (descending)
   */
  sort(results) {
    if (!results || results.length === 0) {
      return [];
    }

    return [...results].sort((a, b) => b.score - a.score);
  }

  /**
   * Return top-K results
   * @param {HybridMatch[]} results - Sorted results
   * @param {number} k - Number of results to return
   * @returns {HybridMatch[]} Top-K results
   */
  topK(results, k) {
    if (!results || results.length === 0) {
      return [];
    }

    return results.slice(0, k);
  }

  /**
   * Apply keyword boost to results
   * @param {HybridMatch[]} results - Results to boost
   * @param {string[]} keywords - Keywords to match
   * @returns {HybridMatch[]} Boosted results
   */
  applyKeywordBoost(results, keywords = []) {
    if (!results || results.length === 0 || !keywords || keywords.length === 0) {
      return results;
    }

    const keywordLower = keywords.map(k => k.toLowerCase());

    return results.map(result => {
      const contentLower = (result.content || '').toLowerCase();

      // Check if any keyword appears in content
      const hasKeyword = keywordLower.some(kw => contentLower.includes(kw));

      if (hasKeyword) {
        return {
          ...result,
          score: Math.min(1.0, result.score + this.weights.keyword),
        };
      }

      return result;
    });
  }

  /**
   * Apply recency boost to newer files
   * @param {HybridMatch[]} results - Results to boost
   * @returns {HybridMatch[]} Boosted results
   */
  applyRecencyBoost(results) {
    if (!results || results.length === 0) {
      return results;
    }

    // Find newest file timestamp
    const timestamps = results.map(r => r.metadata?.mtime || 0).filter(t => t > 0);

    if (timestamps.length === 0) {
      return results;
    }

    const now = Date.now();
    const thirtyDaysMs = 30 * 24 * 60 * 60 * 1000;

    return results.map(result => {
      const mtime = result.metadata?.mtime || 0;

      if (mtime === 0) {
        return result; // No timestamp, no boost
      }

      // Calculate age as fraction of 30 days
      const ageMs = now - mtime;
      const ageFraction = Math.min(1.0, ageMs / thirtyDaysMs);

      // Apply boost (newer files get higher boost)
      const boost = this.weights.recency * (1.0 - ageFraction);

      return {
        ...result,
        score: Math.min(1.0, result.score + boost),
      };
    });
  }

  /**
   * Filter results below confidence threshold
   * @param {HybridMatch[]} results - Results to filter
   * @returns {HybridMatch[]} Filtered results
   */
  filterByConfidence(results) {
    if (!results || results.length === 0) {
      return [];
    }

    return results.filter(r => r.score >= this.confidenceThreshold);
  }

class VectorStore {
  constructor(options = {}) {
    const projectRoot = options.projectRoot || process.cwd();
    const persistDirectory =
      options.persistDirectory ||
      process.env.LANCEDB_URI ||
      path.join(projectRoot, '.claude', 'data', 'lancedb');
    const collectionName = options.collectionName || process.env.LANCEDB_TABLE_CODE || 'code_index';

    const embeddingMode =
      options.embeddingMode ||
      process.env.LANCEDB_EMBEDDING_MODE_CODE ||
      process.env.LANCEDB_EMBEDDING_MODE ||
      'transformers';
    this.store = MemoryVectorStore.getSharedStore({
      persistDirectory,
      collectionName,
      embeddingMode,
      embeddingModel:
        embeddingMode === 'fastembed'
          ? undefined
          : process.env.LANCEDB_EMBEDDING_MODEL || 'Xenova/all-MiniLM-L6-v2',
    });

    // BM25 hybrid search integration (Phase 2)
    this.bm25Index = null; // Lazy-loaded BM25 indexer
    this.bm25Config = options.bm25 || {};
    this.persistDirectory = persistDirectory;
  }

  /**
   * Convert code chunks to document shape for the store.
   * @private
   */
  _chunksToDocs(chunks) {
    return chunks.map(chunk => ({
      id: chunk.id,
      text: chunk.content,
      metadata: {
        filePath: chunk.filePath,
        language: chunk.language,
        type: chunk.type,
        lineStart: chunk.lineStart,
        lineEnd: chunk.lineEnd,
        name: chunk.name,
        signature: chunk.signature,
        tokenCount: chunk.tokenCount,
      },
    }));
  }

  /**
   * Add chunks to the vector store (upsert: delete by id then add).
   * Use for incremental updates where chunk ids may already exist.
   */
  async addChunks(chunks, options = {}) {
    if (!Array.isArray(chunks) || chunks.length === 0) return;
    const docs = this._chunksToDocs(chunks);
    if (options.addOnly) {
      await this.store.addDocuments(docs, options.embedBatchSize, {
        onEmbedProgress: options.onEmbedProgress,
      });
    } else {
      await this.store.upsertDocuments(docs);
    }
  }

  /**
   * Add chunks without deleting existing ids (append-only). Use for full reindex after dropping the table.
   * Also builds BM25 sparse index alongside dense embeddings.
   * @param {Object} [options] - Optional { embedBatchSize, onEmbedProgress(batchDone, totalBatches) }.
   */
  async addChunksOnly(chunks, options = {}) {
    if (!Array.isArray(chunks) || chunks.length === 0) return;

    // Build BM25 index first (fast)
    await this.addChunksToBM25(chunks);

    // Then build dense embeddings (slow)
    return this.addChunks(chunks, { addOnly: true, ...options });
  }

  /**
   * Drop the code index table so a full reindex can use add-only writes (avoids per-chunk deletes).
   */
  async dropCodeTable() {
    await this.store.initialize();
    return this.store.dropTable();
  }

  async search(query, options = {}) {
    const limit = options.limit || options.topK || 10;
    const filters = options.filters || {};
    const minScore = typeof options.minScore === 'number' ? options.minScore : null;
    return await this.store.search(query, { limit, filters, minScore });
  }

  async deleteFile(filePath) {
    return await this.store.deleteByMetadata('filePath', filePath);
  }

  async getStats() {
    const tables = await this.store.listTables();
    return {
      collectionName: this.store.config?.collectionName,
      dbPath: this.store.config?.persistDirectory,
      tables,
    };
  }

  /**
   * Load BM25 index from disk (if exists)
   * @returns {Promise<void>}
   */
  async loadBM25Index() {
    const bm25Path = path.join(this.persistDirectory, 'bm25-index.json');
    if (fs.existsSync(bm25Path)) {
      const data = JSON.parse(fs.readFileSync(bm25Path, 'utf-8'));
      const { BM25Indexer } = require('./bm25-indexer.cjs');
      this.bm25Index = BM25Indexer.fromJSON(data);
    }
  }

  /**
   * Save BM25 index to disk
   * @returns {Promise<void>}
   */
  async saveBM25Index() {
    if (this.bm25Index) {
      const bm25Path = path.join(this.persistDirectory, 'bm25-index.json');
      fs.writeFileSync(bm25Path, JSON.stringify(this.bm25Index.toJSON()), 'utf-8');
    }
  }

  /**
   * Add chunks to BM25 sparse index
   * @param {Array<Object>} chunks - Code chunks to add
   * @returns {Promise<void>}
   */
  async addChunksToBM25(chunks) {
    if (!Array.isArray(chunks) || chunks.length === 0) return;

    // Lazy-initialize BM25 indexer
    if (!this.bm25Index) {
      const { BM25Indexer } = require('./bm25-indexer.cjs');
      this.bm25Index = new BM25Indexer(this.bm25Config);
    }

    // Convert chunks to BM25 document format
    const docs = chunks.map(chunk => ({
      id: chunk.id,
      text: chunk.content || chunk.text,
      filePath: chunk.filePath,
      startLine: chunk.lineStart || chunk.startLine,
      endLine: chunk.lineEnd || chunk.endLine,
    }));

    this.bm25Index.addDocuments(docs);
  }

  /**
   * Hybrid search combining BM25 (sparse) + dense embeddings with RRF fusion
   * @param {string} query - Search query
   * @param {Object} options - Search options
   * @param {string} [options.mode='hybrid'] - Search mode: 'hybrid', 'sparse', 'dense'
   * @param {number} [options.k_sparse=100] - Number of sparse results
   * @param {number} [options.k_dense=10] - Number of dense results
   * @param {number} [options.rrf_k=60] - RRF k constant
   * @param {number} [options.sparse_weight=0.4] - Sparse result weight
   * @param {number} [options.dense_weight=0.6] - Dense result weight
   * @returns {Promise<Array>} Hybrid search results
   */
  async hybridSearch(query, options = {}) {
    const opts = {
      k_sparse: options.k_sparse || this.bm25Config.k_sparse || 100,
      k_dense: options.k_dense || this.bm25Config.k_dense || 10,
      rrf_k: options.rrf_k || this.bm25Config.rrf_k || 60,
      sparse_weight: options.sparse_weight || this.bm25Config.weights?.sparse || 0.4,
      dense_weight: options.dense_weight || this.bm25Config.weights?.dense || 0.6,
      mode: options.mode || 'hybrid',
    };

    // Fallback to dense-only if BM25 not available
    if (!this.bm25Index) {
      return this.search(query, { limit: opts.k_dense });
    }

    // Sparse-only mode
    if (opts.mode === 'sparse') {
      return this.bm25Index.search(query, opts.k_sparse);
    }

    // Dense-only mode
    if (opts.mode === 'dense') {
      return this.search(query, { limit: opts.k_dense });
    }

    // Hybrid mode: RRF fusion
    const sparseResults = this.bm25Index.search(query, opts.k_sparse);
    const denseResults = await this.search(query, { limit: opts.k_dense });

    // Fuse results using Reciprocal Rank Fusion
    const fused = this._fuseResultsRRF(
      sparseResults,
      denseResults,
      opts.rrf_k,
      opts.sparse_weight,
      opts.dense_weight
    );

    return fused.slice(0, Math.max(opts.k_sparse, opts.k_dense));
  }

  /**
   * Reciprocal Rank Fusion (RRF) - Fuse sparse + dense results
   * @param {Array} sparseResults - BM25 results
   * @param {Array} denseResults - Dense embedding results
   * @param {number} k - RRF constant (default: 60)
   * @param {number} sparseWeight - Weight for sparse results (default: 0.4)
   * @param {number} denseWeight - Weight for dense results (default: 0.6)
   * @returns {Array} Fused results sorted by RRF score
   * @private
   */
  _fuseResultsRRF(sparseResults, denseResults, k = 60, sparseWeight = 0.4, denseWeight = 0.6) {
    const scoreMap = new Map();

    // Add sparse results with weighted RRF scores
    sparseResults.forEach((result, rank) => {
      const score = sparseWeight * (1 / (k + rank));
      if (!scoreMap.has(result.id)) {
        scoreMap.set(result.id, { ...result, rrf_score: 0 });
      }
      scoreMap.get(result.id).rrf_score += score;
    });

    // Add dense results with weighted RRF scores
    denseResults.forEach((result, rank) => {
      const id = result.id || result.metadata?.id;
      const score = denseWeight * (1 / (k + rank));
      if (!scoreMap.has(id)) {
        scoreMap.set(id, { ...result, id, rrf_score: 0 });
      }
      scoreMap.get(id).rrf_score += score;
    });

    // Sort by RRF score (descending)
    return Array.from(scoreMap.values()).sort((a, b) => b.rrf_score - a.rrf_score);
  }

  async close() {
    return this.store.close();
  }

function load() {
