class EvolutionStateSync {
  /**
   * Create a new EvolutionStateSync instance
   *
   * @param {Object} options - Configuration options
   * @param {string} options.statePath - Path to evolution-state.json
   * @param {number} options.lockTimeout - Lock timeout in ms
   */
  constructor(options = {}) {
    const basePath = options.basePath || process.cwd();

    this.options = {
      statePath: options.statePath || path.join(basePath, DEFAULT_STATE_PATH),
      lockTimeout: options.lockTimeout || DEFAULT_LOCK_TIMEOUT,
    };

    // State cache
    this._stateCache = null;
    this._cacheTime = 0;
    this._cacheMaxAge = 1000; // 1 second cache
  }

  /**
   * Load state from file
   *
   * @returns {Promise<Object>} Evolution state
   */
  async loadState() {
    // Check cache
    if (this._stateCache && Date.now() - this._cacheTime < this._cacheMaxAge) {
      return { ...this._stateCache };
    }

    try {
      if (!fs.existsSync(this.options.statePath)) {
        // Create default state
        const defaultState = { ...DEFAULT_STATE, lastUpdated: new Date().toISOString() };
        await this.saveState(defaultState);
        return defaultState;
      }

      const content = await fs.promises.readFile(this.options.statePath, 'utf-8');
      const state = JSON.parse(content);

      // Update cache
      this._stateCache = state;
      this._cacheTime = Date.now();

      return { ...state };
    } catch (_e) {
      // Return default state on error
      const defaultState = { ...DEFAULT_STATE, lastUpdated: new Date().toISOString() };
      return defaultState;
    }
  }

  /**
   * Save state to file
   *
   * @param {Object} state - State to save
   */
  async saveState(state) {
    // Ensure directory exists
    const dir = path.dirname(this.options.statePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    // Update timestamp
    state.lastUpdated = new Date().toISOString();

    // Write atomically (write to temp, then rename)
    const tempPath = `${this.options.statePath}.tmp`;
    await fs.promises.writeFile(tempPath, JSON.stringify(state, null, 2));
    await fs.promises.rename(tempPath, this.options.statePath);

    // Invalidate cache
    this._stateCache = state;
    this._cacheTime = Date.now();
  }

  /**
   * Acquire a lock for a workflow
   *
   * @param {string} workflowId - Workflow ID
   * @param {number} timeout - Lock timeout in ms
   * @returns {Promise<boolean>} True if lock acquired
   */
  async lock(workflowId, timeout = this.options.lockTimeout) {
    const state = await this.loadState();

    // Ensure locks object exists
    if (!state.locks) {
      state.locks = {};
    }

    // Check if lock exists and hasn't expired
    if (state.locks[workflowId]) {
      const lockTime = new Date(state.locks[workflowId]).getTime();
      const now = Date.now();

      if (now - lockTime < timeout) {
        // Lock is still valid
        return false;
      }
      // Lock expired, allow acquisition
    }

    // Acquire lock
    state.locks[workflowId] = new Date().toISOString();
    await this.saveState(state);

    return true;
  }

  /**
   * Release a lock
   *
   * @param {string} workflowId - Workflow ID
   */
  async unlock(workflowId) {
    const state = await this.loadState();

    if (state.locks && state.locks[workflowId]) {
      delete state.locks[workflowId];
      await this.saveState(state);
    }
  }

  /**
   * Get active evolutions
   *
   * @returns {Promise<Array>} List of active evolutions
   */
  async getActiveEvolutions() {
    const state = await this.loadState();

    if (state.currentEvolution) {
      return [state.currentEvolution];
    }

    return [];
  }

  /**
   * Add a suggestion to the queue
   *
   * @param {Object} suggestion - Suggestion object
   * @param {string} suggestion.type - Artifact type
   * @param {string} suggestion.name - Suggested name
   * @param {string} suggestion.reason - Reason for suggestion
   */
  async addSuggestion(suggestion) {
    const state = await this.loadState();

    if (!state.suggestions) {
      state.suggestions = [];
    }

    // Add timestamp
    const enrichedSuggestion = {
      ...suggestion,
      suggestedAt: new Date().toISOString(),
    };

    state.suggestions.push(enrichedSuggestion);
    await this.saveState(state);
  }

  /**
   * Pop (remove and return) the first suggestion
   *
   * @returns {Promise<Object|null>} First suggestion or null
   */
  async popSuggestion() {
    const state = await this.loadState();

    if (!state.suggestions || state.suggestions.length === 0) {
      return null;
    }

    const suggestion = state.suggestions.shift();
    await this.saveState(state);

    return suggestion;
  }

  /**
   * Record an entry in the evolution history
   *
   * @param {Object} entry - History entry
   * @param {string} entry.type - Artifact type
   * @param {string} entry.name - Artifact name
   * @param {string} entry.path - Artifact path
   */
  async recordHistory(entry) {
    const state = await this.loadState();

    if (!state.evolutions) {
      state.evolutions = [];
    }

    // Add completion timestamp if not present
    const historyEntry = {
      ...entry,
      completedAt: entry.completedAt || new Date().toISOString(),
    };

    state.evolutions.push(historyEntry);
    await this.saveState(state);
  }

  /**
   * Update the current evolution
   *
   * @param {Object} evolution - Evolution data
   * @param {string} evolution.type - Artifact type
   * @param {string} evolution.name - Artifact name
   * @param {string} evolution.phase - Current phase
   */
  async updateCurrentEvolution(evolution) {
    const state = await this.loadState();

    state.currentEvolution = {
      ...evolution,
      updatedAt: new Date().toISOString(),
    };

    // Update state field to match phase
    if (evolution.phase && EVOLUTION_STATES.includes(evolution.phase)) {
      state.state = evolution.phase;
    }

    await this.saveState(state);
  }

  /**
   * Clear the current evolution
   */
  async clearCurrentEvolution() {
    const state = await this.loadState();

    state.currentEvolution = null;
    state.state = 'idle';

    await this.saveState(state);
  }

  /**
   * Get pending suggestions
   *
   * @returns {Promise<Array>} List of pending suggestions
   */
  async getPendingSuggestions() {
    const state = await this.loadState();
    return state.suggestions || [];
  }

  /**
   * Get evolution history
   *
   * @param {number} limit - Max entries to return
   * @returns {Promise<Array>} Evolution history
   */
  async getHistory(limit = 50) {
    const state = await this.loadState();
    const history = state.evolutions || [];

    // Return most recent entries
    return history.slice(-limit);
  }

  /**
   * Add a detected pattern
   *
   * @param {Object} pattern - Pattern object
   */
  async addPattern(pattern) {
    const state = await this.loadState();

    if (!state.patterns) {
      state.patterns = [];
    }

    state.patterns.push({
      ...pattern,
      detectedAt: new Date().toISOString(),
    });

    await this.saveState(state);
  }

  /**
   * Check if a specific artifact is currently being evolved
   *
   * @param {string} type - Artifact type
   * @param {string} name - Artifact name
   * @returns {Promise<boolean>}
   */
  async isBeingEvolved(type, name) {
    const state = await this.loadState();

    if (!state.currentEvolution) {
      return false;
    }

    return state.currentEvolution.type === type && state.currentEvolution.name === name;
  }

  /**
   * Get the current state phase
   *
   * @returns {Promise<string>} Current phase
   */
  async getCurrentPhase() {
    const state = await this.loadState();
    return state.state || 'idle';
  }

  /**
   * Invalidate cache (force reload on next access)
   */
  invalidateCache() {
    this._stateCache = null;
    this._cacheTime = 0;
  }

function getAuditLogPath(projectRoot = process.cwd()) {
  return path.join(projectRoot, LOG_PATHS.modelSelection);
}

function ensureLogDirectory(logPath) {
  const dir = path.dirname(logPath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function getModelCost(model) {
  // Direct lookup by full ID
  if (MODEL_COSTS[model]) {
    return MODEL_COSTS[model];
  }

  // Lookup by shorthand
  for (const [id, cost] of Object.entries(MODEL_COSTS)) {
    if (cost.shorthand === model) {
      return { ...cost, fullId: id };
    }
  }

  return null;
}

function calculateCostDifference(configuredModel, actualModel, tokens = DEFAULT_TOKENS_PER_SPAWN) {
  const configuredCost = getModelCost(configuredModel);
  const actualCost = getModelCost(actualModel);

  if (!configuredCost || !actualCost) {
    return null;
  }

  const configuredTotal =
    configuredCost.input * tokens.input + configuredCost.output * tokens.output;
  const actualTotal = actualCost.input * tokens.input + actualCost.output * tokens.output;

  return actualTotal - configuredTotal;
}

function getComplexity(agentType) {
  const highComplexity = [
    'planner',
    'architect',
    'qa',
    'security-architect',
    'evolution-orchestrator',
    'master-orchestrator',
    'party-orchestrator',
    'swarm-coordinator',
    'reverse-engineer',
    'ai-ml-specialist',
    'web3-blockchain-expert',
  ];

  const lowComplexity = ['context-compressor'];

  if (highComplexity.includes(agentType)) return 'high';
  if (lowComplexity.includes(agentType)) return 'low';
  return 'medium';
}

function getTaskUpdateMetadata(resolution, actualModel = null) {
  const actual = actualModel || resolution.model;

  return {
    modelResolutionSource: resolution.source,
    configuredModel: resolution.model,
    actualModel: actual,
    modelMismatch: resolution.model !== actual,
    modelShorthand: resolution.shorthand,
  };
}

function parseAuditLog(projectRoot) {
  const logPath = getAuditLogPath(projectRoot);

  if (!fs.existsSync(logPath)) {
    return [];
  }

  const content = fs.readFileSync(logPath, 'utf-8');
  const lines = content.trim().split('\n').filter(Boolean);

  const events = [];
  for (const line of lines) {
    try {
      const event = JSON.parse(line);
      if (event.event === 'ConfigModelSelection') {
        events.push(event);
      }
    } catch (_e) {
      // Skip malformed lines
    }
  }

  return events;
}

function filterToday(events) {
  const today = new Date().toISOString().split('T')[0];
  return events.filter(e => e.timestamp && e.timestamp.startsWith(today));
}

function calculateTotalCostImpact(events) {
  return events
    .filter(e => e.mismatch && e.cost_difference !== null)
    .reduce((sum, e) => sum + (e.cost_difference || 0), 0);
}

function validateProjectRoot(projectRoot) {
  if (projectRoot !== PROJECT_ROOT) {
    const validation = validatePathWithinProject(projectRoot, PROJECT_ROOT);
    if (!validation.safe) {
      throw new Error(`Invalid projectRoot: ${validation.reason}`);
    }
  }
}

function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function getLtmDir(projectRoot = PROJECT_ROOT) {
  return path.join(projectRoot, '.claude', 'context', 'memory', 'ltm');
}

function toIsoDate(date) {
  return date.toISOString().slice(0, 10);
}

function listLTMSummaries(projectRoot = PROJECT_ROOT) {
  validateProjectRoot(projectRoot);
  const ltmDir = getLtmDir(projectRoot);
  if (!fs.existsSync(ltmDir)) return [];

  const entries = [];
  for (const name of fs.readdirSync(ltmDir)) {
    if (!name.endsWith('.json')) continue;
    if (!name.startsWith('summary_')) continue;
    const absPath = path.join(ltmDir, name);
    try {
      const stat = fs.statSync(absPath);
      if (!stat.isFile()) continue;
      entries.push({ absPath, name, mtimeMs: stat.mtimeMs });
    } catch {
      // skip unreadable entry
    }
  }

  entries.sort((a, b) => a.mtimeMs - b.mtimeMs || a.name.localeCompare(b.name));
  return entries;
}

function buildColdArchivePath(coldDir) {
  const now = new Date();
  const date = toIsoDate(now);
  const stamp = now.toISOString().replace(/[:.]/g, '-');
  return path.join(coldDir, `ltm-${date}-${stamp}.jsonl.gz`);
}

function buildIndexDocument(summaryObj, sourcePath, coldPath) {
  const createdAt = summaryObj?.created_at || null;
  const dateRange = summaryObj?.date_range || null;
  const keyLearnings = Array.isArray(summaryObj?.key_learnings) ? summaryObj.key_learnings : [];
  const patterns = Array.isArray(summaryObj?.important_patterns)
    ? summaryObj.important_patterns
    : [];
  const decisions = Array.isArray(summaryObj?.major_decisions) ? summaryObj.major_decisions : [];
  const touched = Array.isArray(summaryObj?.files_frequently_touched)
    ? summaryObj.files_frequently_touched
    : [];

  const header = [
    'LTM Session Summary (Archived)',
    createdAt ? `created_at: ${createdAt}` : null,
    dateRange?.start || dateRange?.end
      ? `date_range: ${dateRange?.start || 'unknown'} → ${dateRange?.end || 'unknown'}`
      : null,
    typeof summaryObj?.session_count === 'number'
      ? `session_count: ${summaryObj.session_count}`
      : null,
    '',
  ]
    .filter(Boolean)
    .join('\n');

  const bodyParts = [];
  if (keyLearnings.length) bodyParts.push(`Key learnings:\n- ${keyLearnings.join('\n- ')}`);
  if (patterns.length) bodyParts.push(`Important patterns:\n- ${patterns.join('\n- ')}`);
  if (decisions.length) bodyParts.push(`Major decisions:\n- ${decisions.join('\n- ')}`);
  if (touched.length) bodyParts.push(`Files frequently touched:\n- ${touched.join('\n- ')}`);

  let text = `${header}\n${bodyParts.join('\n\n')}`.trim();
  const truncated = Number.isFinite(COLD_INDEX_MAX_CHARS) && text.length > COLD_INDEX_MAX_CHARS;
  if (truncated) {
    text = `${text.slice(0, COLD_INDEX_MAX_CHARS)}…`;
  }

  const idBase = path.basename(sourcePath, '.json');
  return {
    id: `ltm-archive-${idBase}`,
    text,
    metadata: {
      source: 'ltm_archive',
      tier: 'cold',
      coldPath: path.relative(PROJECT_ROOT, coldPath).replace(/\\/g, '/'),
      ltmFile: path.relative(PROJECT_ROOT, sourcePath).replace(/\\/g, '/'),
      created_at: createdAt,
      date_range: dateRange,
      truncated,
    },
  };
}

class ConductorGapAnalyzer {
  constructor(conductorPath, agentStudioPath) {
    this.conductorPath = conductorPath;
    this.agentStudioPath = agentStudioPath;
  }

  /**
   * Analyze feature gaps between conductor-main and agent-studio
   * @returns {Promise<{missing: Array, redundant: Array, incompatible: Array, trackCount: number}>}
   */
  async analyzeFeatureGaps() {
    // Validate paths
    if (!fs.existsSync(this.conductorPath)) {
      throw new Error(`Conductor path does not exist: ${this.conductorPath}`);
    }

    if (!fs.existsSync(this.agentStudioPath)) {
      throw new Error(`Agent-studio path does not exist: ${this.agentStudioPath}`);
    }

    const missing = await this._findMissingFeatures();
    const redundant = await this._findRedundantFeatures();
    const incompatible = await this._findIncompatibleFeatures();
    const trackCount = await this._countTracks();

    return {
      missing,
      redundant,
      incompatible,
      trackCount,
    };
  }

  /**
   * Compare codebases for size and complexity
   * @returns {Promise<{lineCount: {conductor: number, agentStudio: number}, complexity: {conductor: number, agentStudio: number}, commitCount: number}>}
   */
  async compareCodebases() {
    const conductorLines = await this._countLines(this.conductorPath);
    const agentStudioLines = await this._countLines(this.agentStudioPath);

    const conductorComplexity = await this._calculateComplexity(this.conductorPath);
    const agentStudioComplexity = await this._calculateComplexity(this.agentStudioPath);

    const commitCount = await this._countCommits(this.conductorPath);

    return {
      lineCount: {
        conductor: conductorLines,
        agentStudio: agentStudioLines,
      },
      complexity: {
        conductor: conductorComplexity,
        agentStudio: agentStudioComplexity,
      },
      commitCount,
    };
  }

  /**
   * Identify patterns conductor-main has that agent-studio is missing
   * @returns {Promise<Array<{name: string, description: string, effort: string}>>}
   */
  async identifyMissingPatterns() {
    const patterns = [];

    // Check for git notes
    if (!(await this._hasGitNotesHook(this.conductorPath))) {
      patterns.push({
        name: 'git-notes-audit hook',
        description: 'Automatic git notes attachment for commit metadata',
        effort: '2 hours',
      });
    }

    // Check for track metadata schema
    if (!(await this._hasTrackMetadataSchema(this.conductorPath))) {
      patterns.push({
        name: 'track metadata schema',
        description: 'Validated metadata structure for tracks',
        effort: '1 hour',
      });
    }

    // Check for workflow checkpointing
    if (!(await this._hasWorkflowCheckpointing(this.conductorPath))) {
      patterns.push({
        name: 'workflow checkpointing',
        description: 'State persistence and crash recovery',
        effort: '3 hours',
      });
    }

    // Check for brownfield detection
    if (!(await this._hasBrownfieldDetection(this.conductorPath))) {
      patterns.push({
        name: 'brownfield detection',
        description: 'Automatic tech stack detection',
        effort: '4 hours',
      });
    }

    // Check conductor-specific patterns
    const conductorUnique = await this._findConductorUniquePatterns();
    if (conductorUnique.length > 0) {
      patterns.conductorUnique = conductorUnique;
    }

    return patterns;
  }

  /**
   * Generate markdown gap report
   * @returns {Promise<string>}
   */
  async generateGapReport() {
    const gaps = await this.analyzeFeatureGaps();
    const comparison = await this.compareCodebases();
    const patterns = await this.identifyMissingPatterns();

    let report = '# Gap Analysis Report\n\n';
    report += `**Conductor-Main**: ${this.conductorPath}\n`;
    report += `**Agent-Studio**: ${this.agentStudioPath}\n\n`;

    // Missing features
    report += '## Missing Features\n\n';
    report += 'Features agent-studio has that conductor-main is missing:\n\n';
    for (const feature of gaps.missing) {
      const featureName = typeof feature === 'string' ? feature : feature.name;
      const effort = typeof feature === 'string' ? 'Unknown' : feature.effort;
      const priority = this._assessPriority(featureName);
      report += `- **[${priority}]** ${featureName} (Effort: ${effort})\n`;
    }

    // Redundant features
    report += '\n## Redundant Features\n\n';
    report += 'Features conductor-main has that agent-studio deprecated:\n\n';
    for (const feature of gaps.redundant) {
      report += `- ${feature}\n`;
    }

    // Incompatible features
    report += '\n## Incompatible Features\n\n';
    report += 'Features with schema/format differences:\n\n';
    for (const feature of gaps.incompatible) {
      report += `- ${feature}\n`;
    }

    // Statistics
    report += '\n## Statistics\n\n';
    report += `- **Tracks**: ${gaps.trackCount}\n`;
    report += `- **Lines of Code**: Conductor ${comparison.lineCount.conductor}, Agent-Studio ${comparison.lineCount.agentStudio}\n`;
    report += `- **Complexity**: Conductor ${comparison.complexity.conductor}, Agent-Studio ${comparison.complexity.agentStudio}\n`;
    report += `- **Commits**: ${comparison.commitCount}\n`;

    // Recommendations
    report += '\n## Recommendations\n\n';
    report += this._generateRecommendations(gaps, patterns);

    return report;
  }

  // Private helpers

  async _findMissingFeatures() {
    const missing = [];

    // Tech stack auto-generation
    if (!(await this._fileExists(this.conductorPath, 'tech-stack.md'))) {
      missing.push({
        name: 'tech-stack.md auto-generation (SPEC-005)',
        effort: '1 hour',
        estimatedHours: 1,
      });
    }

    // Git notes audit
    if (!(await this._hasGitNotesHook(this.conductorPath))) {
      missing.push({
        name: 'git-notes-audit hook (SPEC-002)',
        effort: '2 hours',
        estimatedHours: 2,
      });
    }

    // Track analytics
    if (!(await this._fileExists(this.conductorPath, '.claude/lib/utils/track-analytics.cjs'))) {
      missing.push({
        name: 'track-analytics module (SPEC-008)',
        effort: '2 hours',
        estimatedHours: 2,
      });
    }

    // Brownfield detection
    if (
      !(await this._fileExists(this.conductorPath, '.claude/lib/utils/brownfield-detector.cjs'))
    ) {
      missing.push({
        name: 'brownfield-detection module (SPEC-005)',
        effort: '4 hours',
        estimatedHours: 4,
      });
    }

    return missing;
  }

  async _findRedundantFeatures() {
    const redundant = [];

    // Check for deprecated patterns (example)
    if (await this._fileExists(this.conductorPath, 'legacy-config.xml')) {
      redundant.push('legacy-config.xml (deprecated in favor of config.json)');
    }

    return redundant;
  }

  async _findIncompatibleFeatures() {
    const incompatible = [];

    // Workflow state format
    if (await this._fileExists(this.conductorPath, 'setup_state.json')) {
      incompatible.push('workflow-state format (setup_state.json vs workflow-state.schema.json)');
    }

    return incompatible;
  }

  async _countTracks() {
    const tracksDir = path.join(this.conductorPath, 'tracks');
    if (!fs.existsSync(tracksDir)) {
      return 0;
    }

    const entries = fs.readdirSync(tracksDir, { withFileTypes: true });
    const trackDirs = entries.filter(e => e.isDirectory());

    return trackDirs.length;
  }

  async _countLines(dirPath) {
    let total = 0;

    const walk = dir => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);

        if (entry.isDirectory()) {
          // Skip node_modules, .git
          if (entry.name === 'node_modules' || entry.name === '.git') continue;
          walk(fullPath);
        } else if (entry.isFile()) {
          // Count lines in code files
          if (/\.(js|cjs|mjs|ts|md|json)$/.test(entry.name)) {
            const content = fs.readFileSync(fullPath, 'utf8');
            total += content.split('\n').length;
          }
        }
      }
    };

    walk(dirPath);
    return total;
  }

  async _calculateComplexity(dirPath) {
    // Simple complexity metric: average cyclomatic complexity
    // For this implementation, use line count / files as proxy
    const lines = await this._countLines(dirPath);
    const fileCount = await this._countFiles(dirPath);

    return fileCount > 0 ? Math.round(lines / fileCount) : 0;
  }

  async _countFiles(dirPath) {
    let count = 0;

    const walk = dir => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);

        if (entry.isDirectory()) {
          if (entry.name === 'node_modules' || entry.name === '.git') continue;
          walk(fullPath);
        } else if (entry.isFile()) {
          if (/\.(js|cjs|mjs|ts|md|json)$/.test(entry.name)) {
            count++;
          }
        }
      }
    };

    walk(dirPath);
    return count;
  }

  async _countCommits(_dirPath) {
    // Mock: Return 0 (git operations require real git repo)
    return 0;
  }

  async _hasGitNotesHook(dirPath) {
    return await this._fileExists(dirPath, '.claude/hooks/audit/git-notes-audit.cjs');
  }

  async _hasTrackMetadataSchema(dirPath) {
    return await this._fileExists(dirPath, '.claude/schemas/track-metadata.schema.json');
  }

  async _hasWorkflowCheckpointing(dirPath) {
    return await this._fileExists(dirPath, '.claude/lib/workflow/workflow-state-manager.cjs');
  }

  async _hasBrownfieldDetection(dirPath) {
    return await this._fileExists(dirPath, '.claude/lib/utils/brownfield-detector.cjs');
  }

  async _findConductorUniquePatterns() {
    const unique = [];

    // Check for custom tools
    const toolsDir = path.join(this.conductorPath, 'tools');
    if (fs.existsSync(toolsDir)) {
      const tools = fs.readdirSync(toolsDir);
      for (const tool of tools) {
        if (!(await this._fileExists(this.agentStudioPath, `tools/${tool}`))) {
          unique.push({
            name: `custom-tool: ${tool}`,
            description: `Conductor-specific tool not in agent-studio`,
          });
        }
      }
    }

    return unique;
  }

  async _fileExists(basePath, relativePath) {
    return fs.existsSync(path.join(basePath, relativePath));
  }

  _assessPriority(feature) {
    const highPriority = ['git-notes', 'track-analytics', 'workflow-state'];
    const mediumPriority = ['brownfield-detection', 'tech-stack'];

    for (const pattern of highPriority) {
      if (feature.toLowerCase().includes(pattern)) return 'HIGH';
    }

    for (const pattern of mediumPriority) {
      if (feature.toLowerCase().includes(pattern)) return 'MEDIUM';
    }

    return 'LOW';
  }

  _generateRecommendations(gaps, _patterns) {
    let recommendations = '';

    // Helper to check feature name
    const hasFeature = (arr, keyword) =>
      arr.some(f => {
        const name = typeof f === 'string' ? f : f.name || '';
        return name.toLowerCase().includes(keyword.toLowerCase());
      });

    // High-priority recommendations
    if (hasFeature(gaps.missing, 'git-notes')) {
      recommendations += '1. Enable git-notes-audit hook for commit traceability\n';
    }

    if (hasFeature(gaps.incompatible, 'workflow-state')) {
      recommendations += '2. Migrate setup_state.json to workflow-state.schema.json format\n';
    }

    if (hasFeature(gaps.missing, 'track-analytics')) {
      recommendations += '3. Install track-analytics module for project metrics\n';
    }

    return recommendations;
  }

function assessFeatureCompatibility(conductorFeature, agentStudioFeature) {
  if (!conductorFeature || !agentStudioFeature) {
    throw new Error('Both conductor and agent-studio features are required');
  }

  // Check format compatibility
  if (conductorFeature.format && agentStudioFeature.format) {
    if (conductorFeature.format !== agentStudioFeature.format) {
      return {
        level: 'incompatible',
        breakingChanges: [
          {
            field: 'format',
            description: `Format mismatch: ${conductorFeature.format} vs ${agentStudioFeature.format}`,
            type: 'format-change',
          },
        ],
        confidence: 1.0,
      };
    }
  }

  // Check schema compatibility
  if (conductorFeature.schema && agentStudioFeature.schema) {
    return assessSchemaCompatibility(conductorFeature.schema, agentStudioFeature.schema);
  }

  // Default: compatible
  return {
    level: 'compatible',
    confidence: 0.8,
  };
}

function assessSchemaCompatibility(conductorSchema, agentStudioSchema) {
  const transformationRules = [];
  const breakingChanges = [];

  // Check required fields
  const conductorRequired = conductorSchema.required || [];
  const agentStudioRequired = agentStudioSchema.required || [];

  // Field name mapping (detect renames)
  const conductorProps = conductorSchema.properties || {};
  const agentStudioProps = agentStudioSchema.properties || {};

  // Detect field renames
  for (const condField of conductorRequired) {
    if (!agentStudioRequired.includes(condField)) {
      // Field not in agent-studio - check for rename
      const renamed = findRenamedField(condField, agentStudioRequired);
      if (renamed) {
        transformationRules.push({
          type: 'rename',
          from: condField,
          to: renamed,
          description: `Rename field: ${condField} → ${renamed}`,
        });
      }
    }
  }

  // Detect type coercions
  for (const field in conductorProps) {
    if (agentStudioProps[field]) {
      const condType = conductorProps[field].type;
      const agentType = agentStudioProps[field].type;

      if (condType !== agentType) {
        transformationRules.push({
          type: 'coerce',
          field,
          from: condType,
          to: agentType,
          description: `Convert ${field} from ${condType} to ${agentType}`,
        });
      }
    }
  }

  // Detect new required fields (need defaults)
  for (const agentField of agentStudioRequired) {
    if (
      !conductorRequired.includes(agentField) &&
      !transformationRules.some(r => r.to === agentField)
    ) {
      const defaultValue = agentStudioProps[agentField]?.default;

      transformationRules.push({
        type: 'add-default',
        field: agentField,
        value: defaultValue || null,
        description: `Add missing required field: ${agentField}`,
      });
    }
  }

  // Detect removed fields (breaking change)
  for (const condField of conductorRequired) {
    if (
      !agentStudioRequired.includes(condField) &&
      !transformationRules.some(r => r.from === condField)
    ) {
      breakingChanges.push({
        field: condField,
        description: `Field ${condField} removed in agent-studio`,
        type: 'field-removed',
      });
    }
  }

  // Determine compatibility level
  let level;
  if (breakingChanges.length > 0) {
    level = 'incompatible';
  } else if (transformationRules.length > 0) {
    level = 'requires-adaptation';
  } else {
    level = 'compatible';
  }

  // Calculate confidence
  const totalDifferences = transformationRules.length + breakingChanges.length;
  const confidence = totalDifferences === 0 ? 1.0 : Math.max(0.5, 1.0 - totalDifferences * 0.1);

  return {
    level,
    transformationRules: transformationRules.length > 0 ? transformationRules : undefined,
    breakingChanges: breakingChanges.length > 0 ? breakingChanges : undefined,
    confidence,
    version: {
      conductor: conductorSchema.version || '1.0.0',
      agentStudio: agentStudioSchema.version || '2.0.0',
    },
  };
}

function findRenamedField(original, candidates) {
  // Simple heuristic: snake_case <--> camelCase
  const camelCase = original.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
  const snakeCase = original.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);

  if (candidates.includes(camelCase)) return camelCase;
  if (candidates.includes(snakeCase)) return snakeCase;

  // Check common renames
  const renames = {
    workflow_name: 'workflowId',
    current_phase: 'currentPhase',
  };

  return renames[original] || null;
}

function buildCompatibilityMatrix() {
  const features = [
    'spec.md',
    'plan.md',
    'metadata.json',
    'workflow-state',
    'git-notes',
    'analytics',
  ];

  const pairs = {};

  // For each feature pair, assess compatibility
  for (let i = 0; i < features.length; i++) {
    for (let j = i + 1; j < features.length; j++) {
      const key = `${features[i]} <-> ${features[j]}`;
      pairs[key] = {
        compatible: true, // Placeholder
        notes: 'No known conflicts',
      };
    }
  }

  return {
    features,
    pairs,
  };
}

