async function getLanceDb() {
  if (!lancedbModule) {
    // @lancedb/lancedb may be ESM depending on version; use dynamic import for CJS compatibility.
    lancedbModule = await import('@lancedb/lancedb');
  }
  return lancedbModule;
}

function stableTestEmbedding(text, dims = 384) {
  const vec = new Array(dims).fill(0);
  const str = String(text || '');
  for (let i = 0; i < str.length; i++) {
    vec[i % dims] += (str.charCodeAt(i) % 31) / 31;
  }
  // L2 normalize
  let sumSq = 0;
  for (const v of vec) sumSq += v * v;
  const norm = Math.sqrt(sumSq) || 1;
  for (let i = 0; i < vec.length; i++) vec[i] /= norm;
  return vec;
}

class MemoryVectorStore {
  /**
   * Create a new MemoryVectorStore instance
   *
   * @param {Object} config - Configuration options
   * @param {string} [config.persistDirectory] - Directory for persistent storage
   * @param {string} [config.collectionName] - Name of the table (default: agent_memory)
   */
  constructor(config = {}) {
    this.config = {
      persistDirectory:
        config.persistDirectory || process.env.LANCEDB_URI || '.claude/data/lancedb',
      collectionName: config.collectionName || process.env.LANCEDB_TABLE || 'agent_memory',
      embeddingMode: config.embeddingMode || process.env.LANCEDB_EMBEDDING_MODE || 'transformers',
      embeddingModel:
        config.embeddingModel || process.env.LANCEDB_EMBEDDING_MODEL || 'Xenova/all-MiniLM-L6-v2',
      embedBatchSize: config.embedBatchSize,
      gpu: config.gpu !== undefined ? config.gpu : { enabled: true, autoTuneBatchSize: true },
    };

    this.db = null;
    this.table = null;
    this.embedder = null;
    this._fastembedModel = null;
    this.isInitialized = false;
    this._mockMode = false;
    this._tableVectorDim = null;
    this._shared = false;
    this._embeddingStatus = {
      status: 'unknown',
      mode: this.config.embeddingMode,
      reason: null,
    };
    // GPU detection state
    this.device = 'cpu'; // Default to CPU
    this.gpuDetected = false;
    this.gpuName = null;
    this.gpuMemoryMB = 0;
  }

  static _sharedStores = new Map();

  static _makeKey(config) {
    const persistDirectory =
      config.persistDirectory || process.env.LANCEDB_URI || '.claude/data/lancedb';
    const collectionName = config.collectionName || process.env.LANCEDB_TABLE || 'agent_memory';
    const embeddingMode =
      config.embeddingMode || process.env.LANCEDB_EMBEDDING_MODE || 'transformers';
    const embeddingModel =
      config.embeddingModel || process.env.LANCEDB_EMBEDDING_MODEL || 'Xenova/all-MiniLM-L6-v2';
    return [persistDirectory, collectionName, embeddingMode, embeddingModel].join('|');
  }

  static getSharedStore(config = {}) {
    const key = MemoryVectorStore._makeKey(config);
    if (MemoryVectorStore._sharedStores.has(key)) {
      return MemoryVectorStore._sharedStores.get(key);
    }
    const store = new MemoryVectorStore(config);
    store._shared = true;
    MemoryVectorStore._sharedStores.set(key, store);
    return store;
  }

  /**
   * Initialize GPU detection and configuration
   * @returns {Promise<void>}
   * @private
   */
  async _initializeGPU() {
    try {
      const { GPUDetector } = require('../code-indexing/gpu-detector.cjs');
      const detector = new GPUDetector();
      const gpuInfo = await detector.detectNVIDIA();

      if (gpuInfo.available) {
        this.device = 'gpu';
        this.gpuDetected = true;
        this.gpuName = gpuInfo.gpuName;
        this.gpuMemoryMB = gpuInfo.totalMemoryMB;

        // Auto-tune batch size based on GPU memory
        if (this.config.gpu.autoTuneBatchSize && !this.config.embedBatchSize) {
          this.config.embedBatchSize = detector.recommendBatchSize(this.gpuMemoryMB);
        }

        logger.info(`GPU detected: ${this.gpuName} (${this.gpuMemoryMB}MB)`, {
          batchSize: this.config.embedBatchSize,
        });
      } else {
        logger.info('No GPU detected, using CPU for embeddings');
        this.device = 'cpu';
      }
    } catch (error) {
      logger.warn(`GPU detection failed, falling back to CPU: ${error.message}`);
      this.device = 'cpu';
    }
  }

  /**
   * Initialize the LanceDB connection and embedding model
   */
  async initialize() {
    if (this.isInitialized) return;

    try {
      // 1. Initialize DB Connection
      const dbPath = path.resolve(this.config.persistDirectory);
      if (!fs.existsSync(dbPath)) {
        fs.mkdirSync(dbPath, { recursive: true });
      }

      const lancedb = await getLanceDb();
      this.db = await lancedb.connect(dbPath);

      // 2. GPU Detection (if enabled)
      if (
        this.config.gpu?.enabled &&
        (this.config.embeddingMode === 'transformers' || this.config.embeddingMode === 'fastembed')
      ) {
        await this._initializeGPU();
      }

      // 3. Initialize Embedding Model (Local)
      if (this.config.embeddingMode === 'transformers') {
        if (!pipeline) {
          // @xenova/transformers is an ESM module in recent versions.
          // We use dynamic import and property access to get the pipeline function safely.
          try {
            // @xenova/transformers is an ESM module in recent versions.
            // We use dynamic import and property access to get the pipeline function safely.
            const transformerModule = await import('@xenova/transformers');
            pipeline = transformerModule.pipeline;

            // Use efficient MiniLM model (384 dimensions)
            // 'feature-extraction' allows raw vector output
            this.embedder = await pipeline('feature-extraction', this.config.embeddingModel);
            this._embeddingStatus = { status: 'ready', mode: 'transformers', reason: null };
            this._mockMode = false;
          } catch (e) {
            logger.warn(
              'Failed to load local embedding model (likely missing dependencies like "sharp"). Disabling semantic embeddings.',
              { error: e.message }
            );

            // Fail-closed: no mock embeddings
            this.embedder = null;
            this._mockMode = true;
            this._embeddingStatus = {
              status: 'unavailable',
              mode: 'transformers',
              reason: e.message,
            };
          }
        } else {
          // Already loaded pipeline, just ensure embedder is ready
          try {
            this.embedder = await pipeline('feature-extraction', this.config.embeddingModel);
            this._embeddingStatus = { status: 'ready', mode: 'transformers', reason: null };
            this._mockMode = false;
          } catch (e) {
            logger.warn(
              'Failed to initialize embedding model on reuse. Disabling semantic embeddings.',
              { error: e.message }
            );
            this.embedder = null;
            this._mockMode = true;
            this._embeddingStatus = {
              status: 'unavailable',
              mode: 'transformers',
              reason: e.message,
            };
          }
        }
      } else if (this.config.embeddingMode === 'test') {
        // Deterministic, fast embedding for tests (no network/model download)
        this.embedder = null;
        this._embeddingStatus = { status: 'ready', mode: 'test', reason: null };
        this._mockMode = false;
      } else if (this.config.embeddingMode === 'fastembed') {
        this.embedder = null;
        try {
          const fastembed = require('fastembed');

          // Initialize with GPU support if available
          const initOptions = {
            model: fastembed.EmbeddingModel.BGESmallENV15,
            // FastEmbed handles execution providers automatically
            // GPU will be used if CUDA is available, otherwise falls back to CPU
          };

          if (this.device === 'gpu' && this.gpuDetected) {
            logger.info('FastEmbed initializing with GPU (CUDA) support');
          } else {
            logger.info('FastEmbed initializing with CPU');
          }

          this._fastembedModel = await fastembed.FlagEmbedding.init(initOptions);
          this._embeddingStatus = { status: 'ready', mode: 'fastembed', reason: null };
          this._mockMode = false;
          logger.info(
            `FastEmbed initialized successfully (${this.device === 'gpu' ? 'GPU' : 'CPU'} mode)`
          );
        } catch (e) {
          // Try CPU fallback if GPU initialization fails
          logger.warn(`FastEmbed initialization failed: ${e.message}`);

          if (this.device === 'gpu') {
            logger.info('Retrying FastEmbed initialization with CPU fallback...');
            try {
              const fastembed = require('fastembed');
              this._fastembedModel = await fastembed.FlagEmbedding.init({
                model: fastembed.EmbeddingModel.BGESmallENV15,
              });
              this._embeddingStatus = { status: 'ready', mode: 'fastembed', reason: null };
              this._mockMode = false;
              this.device = 'cpu'; // Update device after fallback
              logger.info('FastEmbed initialized with CPU fallback');
            } catch (cpuErr) {
              logger.warn('FastEmbed CPU fallback also failed', { error: cpuErr.message });
              this._fastembedModel = null;
              this._embeddingStatus = {
                status: 'unavailable',
                mode: 'fastembed',
                reason: cpuErr.message || 'Install optional dependency: pnpm add fastembed',
              };
            }
          } else {
            this._fastembedModel = null;
            this._embeddingStatus = {
              status: 'unavailable',
              mode: 'fastembed',
              reason: e.message || 'Install optional dependency: pnpm add fastembed',
            };
          }
        }
      } else if (this.config.embeddingMode === 'off') {
        this.embedder = null;
        this._embeddingStatus = {
          status: 'disabled',
          mode: 'off',
          reason: 'LANCEDB_EMBEDDING_MODE=off',
        };
        this._mockMode = false;
      } else {
        throw new Error(`Unknown embeddingMode: ${this.config.embeddingMode}`);
      }

      // 3. Open Table if exists
      const tableNames = await this.db.tableNames();
      if (tableNames.includes(this.config.collectionName)) {
        this.table = await this.db.openTable(this.config.collectionName);
      }
      // If table doesn't exist, we wait for first add() to create it with schema inference

      this.isInitialized = true;
    } catch (error) {
      throw new Error(`Failed to initialize LanceDB: ${error.message}`);
    }
  }

  /**
   * Generate embedding for text
   * @param {string} text
   * @returns {Promise<Array<number>>} Vector
   */
  async generateEmbedding(text) {
    if (this.config.embeddingMode === 'off') {
      throw new Error('Embeddings disabled (LANCEDB_EMBEDDING_MODE=off)');
    }

    if (this.config.embeddingMode === 'test') {
      return stableTestEmbedding(text, 384);
    }

    if (this._embeddingStatus?.status === 'unavailable') {
      throw new Error(
        `Embeddings unavailable${this._embeddingStatus.reason ? `: ${this._embeddingStatus.reason}` : ''}`
      );
    }

    if (this.config.embeddingMode === 'fastembed' && this._fastembedModel) {
      const gen = this._fastembedModel.embed([text], 1);
      for await (const batch of gen) {
        return Array.from(batch[0] || []);
      }
      return [];
    }

    if (!this.embedder) throw new Error('Embedder not initialized');

    // Real Transformers pipeline
    const output = await this.embedder(text, { pooling: 'mean', normalize: true });
    return Array.from(output.data);
  }

  /**
   * Generate embeddings for multiple texts in batches.
   * Tries pipeline batch input (one forward pass per batch) when texts.length > 1;
   * falls back to parallel single-text calls if batch API is unsupported.
   * @param {string[]} texts
   * @param {number} [batchSize=32]
   * @returns {Promise<Array<number[]>>} Array of vectors in same order as texts
   */
  /**
   * @param {string[]} texts
   * @param {number} [batchSize=32]
   * @param {{ onBatchComplete?: (batchDone: number, totalBatches: number) => void }} [progressOptions]
   */
  async generateEmbeddingsBatch(texts, batchSize = 32, progressOptions) {
    if (!texts || texts.length === 0) return [];
    if (this.config.embeddingMode === 'test') {
      return texts.map(t => stableTestEmbedding(t, 384));
    }
    if (this.config.embeddingMode === 'off' || this._embeddingStatus?.status === 'unavailable') {
      throw new Error('Embedder not available for batch');
    }
    const totalBatches = Math.ceil(texts.length / batchSize) || 1;
    if (this.config.embeddingMode === 'fastembed' && this._fastembedModel) {
      return this._fastembedBatch(texts, batchSize, progressOptions, totalBatches);
    }
    if (!this.embedder) throw new Error('Embedder not initialized');
    const results = [];
    for (let i = 0; i < texts.length; i += batchSize) {
      const batch = texts.slice(i, Math.min(i + batchSize, texts.length));
      const batchVectors = await this._embedBatch(batch);
      results.push(...batchVectors);
      if (progressOptions?.onBatchComplete) {
        const batchDone = Math.min(totalBatches, Math.floor((i + batch.length) / batchSize));
        progressOptions.onBatchComplete(batchDone, totalBatches);
      }
    }
    return results;
  }

  /**
   * FastEmbed batch: collect all batches from async generator.
   * @param {string[]} texts
   * @param {number} batchSize
   * @param {{ onBatchComplete?: (batchDone: number, totalBatches: number) => void }} [progressOptions]
   * @param {number} [totalBatches]
   * @returns {Promise<Array<number[]>>}
   * @private
   */
  async _fastembedBatch(texts, batchSize, progressOptions, totalBatches = 1) {
    const results = [];
    let batchDone = 0;
    const gen = this._fastembedModel.embed(texts, batchSize);
    for await (const batch of gen) {
      for (const row of batch) {
        // Handle both regular arrays and typed arrays (Float32Array, etc.)
        if (row && typeof row === 'object' && (Array.isArray(row) || row.length !== undefined)) {
          results.push(Array.from(row));
        } else {
          // Log unexpected types for debugging
          logger.warn(`Unexpected embedding type: ${typeof row}, value:`, row);
          results.push([]);
        }
      }
      batchDone += 1;
      if (progressOptions?.onBatchComplete)
        progressOptions.onBatchComplete(batchDone, totalBatches);
    }
    return results;
  }

  /**
   * One batch: try pipeline array input (single forward pass), else fall back to parallel single-text calls.
   * @param {string[]} batch - Non-empty array of texts
   * @returns {Promise<Array<number[]>>} Vectors in same order as batch
   * @private
   */
  async _embedBatch(batch) {
    if (batch.length === 1) {
      const vec = await this.generateEmbedding(batch[0]);
      return [vec];
    }
    try {
      const output = await this.embedder(batch, { pooling: 'mean', normalize: true });
      if (!output || typeof output.data === 'undefined')
        throw new Error('Unexpected pipeline output');
      const data = output.data;
      const dims = output.dims;
      if (!Array.isArray(dims) || dims.length < 2) throw new Error('Expected [batchSize, dim]');
      const [rows, dim] = dims;
      if (rows !== batch.length) throw new Error('Batch size mismatch');
      const vecSize = dim;
      const vectors = [];
      for (let r = 0; r < rows; r++) {
        const start = r * vecSize;
        vectors.push(Array.from(data.slice(start, start + vecSize)));
      }
      return vectors;
    } catch (err) {
      logger.debug(
        'Pipeline batch input failed, using parallel single-text fallback:',
        err?.message
      );
      return Promise.all(batch.map(t => this.generateEmbedding(t)));
    }
  }

  async getTableVectorDimension() {
    if (!this.isInitialized) await this.initialize();
    if (!this.table) return null;
    if (Number.isFinite(this._tableVectorDim)) {
      return this._tableVectorDim;
    }
    try {
      const schema = await this.table.schema();
      const field = schema?.fields?.find(f => f.name === 'vector');
      const listSize = field?.type?.listSize;
      if (Number.isFinite(listSize)) {
        this._tableVectorDim = listSize;
        return listSize;
      }
    } catch (_e) {
      // best-effort
    }
    return null;
  }

  async getEmbeddingDimension() {
    if (this.config.embeddingMode === 'off') return null;
    if (this.config.embeddingMode === 'test') return 384;
    if (this.config.embeddingMode === 'fastembed') return this._fastembedModel ? 384 : null;
    if (this._embeddingStatus?.status === 'unavailable') return null;
    if (!this.embedder) return null;
    const vec = await this.generateEmbedding('dimension_check');
    return Array.isArray(vec) ? vec.length : null;
  }

  async listTables() {
    if (!this.isInitialized) await this.initialize();
    if (!this.db) return [];
    return await this.db.tableNames();
  }

  async dropTable() {
    if (!this.isInitialized) await this.initialize();
    if (!this.db) return false;
    const tableNames = await this.db.tableNames();
    if (!tableNames.includes(this.config.collectionName)) return false;

    if (typeof this.db.dropTable === 'function') {
      await this.db.dropTable(this.config.collectionName);
      this.table = null;
      this._tableVectorDim = null;
      return true;
    }

    // FIXED (Issue #1 - CRITICAL): Remove destructive fs.rmSync that deletes entire directory
    // When this is the only table, just mark it as dropped without deleting the DB directory.
    // This allows multi-table usage and prevents catastrophic data loss.
    this.table = null;
    this._tableVectorDim = null;
    logger.info(`Table "${this.config.collectionName}" marked as dropped (metadata cleared)`);
    return true;
  }

  /**
   * Add documents to the store (batch embedding: one forward pass per batch when pipeline supports it).
   * @param {Array<{id: string, text: string, metadata: Object}>} documents
   * @param {number} [embedBatchSize] - Default from config or 64
   * @param {{ onEmbedProgress?: (batchDone: number, totalBatches: number) => void }} [options]
   */
  async addDocuments(documents, embedBatchSize, options) {
    const batchSize = Number.isFinite(embedBatchSize)
      ? embedBatchSize
      : this.config.embedBatchSize || 64;
    if (!documents || documents.length === 0) return;
    if (!this.isInitialized) await this.initialize();

    const toEmbed = documents.filter(d => (d.text || d.content || '').trim());
    if (toEmbed.length === 0) return;

    const texts = toEmbed.map(d => d.text || d.content || '');
    const progressOptions = options?.onEmbedProgress
      ? { onBatchComplete: options.onEmbedProgress }
      : undefined;
    const vectors = await this.generateEmbeddingsBatch(texts, batchSize, progressOptions);

    const tableDim = await this.getTableVectorDimension();
    const data = toEmbed.map((doc, i) => {
      const vector = vectors[i];
      if (Number.isFinite(tableDim) && vector.length !== tableDim) {
        const reason = `embedding dimension mismatch (table ${tableDim} vs vector ${vector.length}). Re-index or rebuild the LanceDB table (pnpm run memory:reindex).`;
        this._embeddingStatus = {
          status: 'unavailable',
          mode: this._embeddingStatus?.mode || this.config.embeddingMode,
          reason,
        };
        throw new Error(reason);
      }
      const text = doc.text || doc.content || '';
      const metadataObj = typeof doc.metadata === 'object' && doc.metadata ? doc.metadata : {};
      return {
        id: doc.id || `doc-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        vector,
        text,
        metadata: JSON.stringify(metadataObj),
        timestamp: Date.now(),
      };
    });

    if (!this.table) {
      this.table = await this.db.createTable(this.config.collectionName, data);
      const firstVector = data[0]?.vector;
      if (Array.isArray(firstVector)) {
        this._tableVectorDim = firstVector.length;
      }
    } else {
      await this.table.add(data);
    }
  }

  /**
   * Upsert documents by deleting matching ids then adding.
   *
   * @param {Array<{id: string, text: string, metadata: Object}>} documents
   */
  async upsertDocuments(documents) {
    if (!documents || documents.length === 0) return;
    if (!this.isInitialized) await this.initialize();

    if (this.table) {
      for (const doc of documents) {
        if (!doc?.id) continue;
        const escaped = String(doc.id).replace(/'/g, "''");
        try {
          await this.table.delete(`id = '${escaped}'`);
        } catch {
          // Ignore delete failures (e.g. table doesn't support delete yet)
        }
      }
    }

    await this.addDocuments(documents);
  }

  /**
   * Search for similar documents
   * @param {string} query
   * @param {Object} options
   * @returns {Promise<Array<{id: string, content: string, metadata: Object, similarity: number}>>}
   */
  async search(query, options = {}) {
    if (!this.isInitialized) await this.initialize();
    if (!this.table) return []; // No table = no results yet

    const limit = options.limit || 10;
    const minScore =
      typeof options.minScore === 'number'
        ? options.minScore
        : typeof options.threshold === 'number'
          ? options.threshold
          : null;
    const queryVector = await this.generateEmbedding(query);
    const tableDim = await this.getTableVectorDimension();
    if (Number.isFinite(tableDim) && queryVector.length !== tableDim) {
      const reason = `embedding dimension mismatch (table ${tableDim} vs query ${queryVector.length}). Re-index or rebuild the LanceDB table (pnpm run memory:reindex).`;
      this._embeddingStatus = {
        status: 'unavailable',
        mode: this._embeddingStatus?.mode || this.config.embeddingMode,
        reason,
      };
      throw new Error(reason);
    }

    let searchBuilder = this.table.vectorSearch(queryVector).limit(limit);

    // Apply filters if present.
    // LanceDB supports SQL filtering string in .where().
    if (options.filters) {
      if (typeof options.filters === 'string') {
        searchBuilder = searchBuilder.where(options.filters);
      } else if (typeof options.filters === 'object') {
        // Minimal adapter for common Chroma-style filters (metadata stored as JSON string).
        // Example: { type: 'learning' } -> metadata LIKE '%"type":"learning"%'
        const clauses = [];
        for (const [key, value] of Object.entries(options.filters)) {
          // metadata is stored as a JSON string; quote characters are safe inside a single-quoted SQL string.
          // Escape only the SQL string delimiter.
          const k = String(key).replace(/'/g, "''");
          const v = String(value).replace(/'/g, "''");
          clauses.push(`metadata LIKE '%"${k}":"${v}"%'`);
        }
        if (clauses.length > 0) {
          searchBuilder = searchBuilder.where(clauses.join(' AND '));
        }
      }
    }

    const results = await searchBuilder.toArray();

    // detailed results map matching standard MemoryVectorStore interface
    const mapped = results.map(r => {
      let metadata = {};
      try {
        metadata = JSON.parse(r.metadata);
      } catch (_e) {
        metadata = { raw: r.metadata };
      }

      return {
        id: r.id,
        content: r.text,
        metadata: metadata,
        similarity: 1 - (r._distance || 0), // Distance->similarity adapter
      };
    });

    if (minScore === null) return mapped;
    return mapped.filter(r => typeof r.similarity === 'number' && r.similarity >= minScore);
  }

  /**
   * Delete documents by metadata match.
   * Uses a LIKE filter on the JSON-encoded metadata column.
   *
   * @param {string} field
   * @param {string|number|boolean} value
   * @returns {Promise<boolean>}
   */
  async deleteByMetadata(field, value) {
    if (!this.isInitialized) await this.initialize();
    if (!this.table) return false;

    const k = String(field).replace(/'/g, "''");
    const v = String(value).replace(/'/g, "''");
    const clause = `metadata LIKE '%"${k}":"${v}"%'`;

    try {
      await this.table.delete(clause);
      return true;
    } catch (_e) {
      return false;
    }
  }

  /**
   * Check availability (always true if init logic passes)
   */
  async isAvailable() {
    try {
      if (!this.isInitialized) await this.initialize();
      return true;
    } catch (_e) {
      return false;
    }
  }

  /**
   * Check if running in mock mode
   */
  isMockMode() {
    return this._mockMode;
  }

  getEmbeddingStatus() {
    return { ...this._embeddingStatus };
  }

  async close() {
    if (this._shared) return;
    // Best-effort (LanceDB doesn't require explicit close in typical usage)
    this.db = null;
    this.table = null;
    this.embedder = null;
    this.isInitialized = false;
  }

  isShared() {
    return this._shared;
  }

function parseEntries(content) {
  if (!content || typeof content !== 'string' || content.trim().length === 0) {
    return [];
  }

  // Split by entry separator
  const rawEntries = content.split(ENTRY_SEPARATOR).filter(e => e.trim().length > 0);

  const entries = [];

  for (const raw of rawEntries) {
    const entry = parseEntry(raw);
    if (entry) {
      entries.push(entry);
    }
  }

  return entries;
}

function parseEntry(raw) {
  if (!raw || raw.trim().length === 0) {
    return null;
  }

  const trimmed = raw.trim();

  // Try standard header format: ## [CATEGORY] Title
  const headerMatch = trimmed.match(HEADER_PATTERN);
  let category = 'UNKNOWN';
  let title = 'Untitled';
  let date = null;

  if (headerMatch) {
    category = headerMatch[1].trim();
    title = headerMatch[2].trim();
  } else {
    // Try alternative header format: ### Title (YYYY-MM-DD)
    const altHeaderMatch = trimmed.match(ALT_HEADER_PATTERN);
    if (altHeaderMatch) {
      title = altHeaderMatch[1].trim();
      // Remove date from title if present
      title = title.replace(/\s*\(\d{4}-\d{2}-\d{2}\)\s*$/, '').trim();

      // Extract date from header
      if (altHeaderMatch[2]) {
        date = altHeaderMatch[2];
      }

      // Infer category from title keywords
      category = inferCategory(title);
    }
  }

  // Extract date from **Date**: line if not already found
  if (!date) {
    const dateMatch = trimmed.match(DATE_PATTERN);
    date = dateMatch ? dateMatch[1] : null;
  }

  // Try alternative date pattern in header if still no date
  if (!date) {
    const altDateMatch = trimmed.match(ALT_DATE_PATTERN);
    date = altDateMatch ? altDateMatch[1] : null;
  }

  // Extract importance (explicit or inferred)
  const importance = extractImportance(trimmed);

  // Extract content (everything after the metadata lines)
  const content = extractContent(trimmed);

  return {
    category,
    title,
    date,
    importance,
    content,
    rawText: trimmed,
  };
}

function inferCategory(title) {
  if (!title) return 'UNKNOWN';

  const lowerTitle = title.toLowerCase();

  if (lowerTitle.includes('security') || lowerTitle.includes('sec-')) {
    return 'SECURITY';
  }
  if (lowerTitle.includes('pattern')) {
    return 'PATTERN';
  }
  if (lowerTitle.includes('bug') || lowerTitle.includes('fix')) {
    return 'BUG-FIX';
  }
  if (lowerTitle.includes('performance') || lowerTitle.includes('optimization')) {
    return 'PERFORMANCE';
  }
  if (lowerTitle.includes('documentation') || lowerTitle.includes('doc')) {
    return 'DOCUMENTATION';
  }
  if (lowerTitle.includes('test')) {
    return 'TESTING';
  }
  if (lowerTitle.includes('insight') || lowerTitle.includes('analysis')) {
    return 'ANALYSIS';
  }
  if (lowerTitle.includes('implementation') || lowerTitle.includes('implemented')) {
    return 'IMPLEMENTATION';
  }

  return 'NOTE';
}

function extractImportance(text, title = null) {
  if (!text) return DEFAULT_IMPORTANCE;

  // First, check for explicit importance marker
  const match = text.match(IMPORTANCE_PATTERN);
  if (match) {
    return match[1].toUpperCase();
  }

  // Extract title from text if not provided
  let titleToCheck = title;
  if (!titleToCheck) {
    const headerMatch = text.match(HEADER_PATTERN);
    if (headerMatch) {
      titleToCheck = headerMatch[2];
    } else {
      const altHeaderMatch = text.match(ALT_HEADER_PATTERN);
      if (altHeaderMatch) {
        titleToCheck = altHeaderMatch[1];
      }
    }
  }

  // Check title keywords first (strong indicators)
  if (titleToCheck) {
    for (const level of ['CRITICAL', 'HIGH', 'MEDIUM']) {
      const patterns = TITLE_KEYWORDS[level];
      if (patterns) {
        for (const pattern of patterns) {
          if (pattern.test(titleToCheck)) {
            return level;
          }
        }
      }
    }
  }

  // Check body keywords (weak indicators - one level lower)
  for (const level of ['HIGH', 'MEDIUM']) {
    const patterns = BODY_KEYWORDS[level];
    if (patterns) {
      for (const pattern of patterns) {
        if (pattern.test(text)) {
          return level;
        }
      }
    }
  }

  return DEFAULT_IMPORTANCE;
}

function extractContent(text) {
  if (!text) return '';

  const lines = text.split('\n');
  const contentLines = [];
  let inMetadata = true;

  for (const line of lines) {
    // Skip header lines (both ## and ### formats)
    if (HEADER_PATTERN.test(line) || ALT_HEADER_PATTERN.test(line)) {
      continue;
    }

    // Skip date line
    if (DATE_PATTERN.test(line)) {
      continue;
    }

    // Skip importance line
    if (IMPORTANCE_PATTERN.test(line)) {
      continue;
    }

    // Skip empty lines at the beginning
    if (inMetadata && line.trim().length === 0) {
      continue;
    }

    // We've hit content
    inMetadata = false;
    contentLines.push(line);
  }

  return contentLines.join('\n').trim();
}

function groupByImportance(entries) {
  const groups = {
    CRITICAL: [],
    HIGH: [],
    MEDIUM: [],
    LOW: [],
  };

  for (const entry of entries) {
    const level = entry.importance || DEFAULT_IMPORTANCE;
    if (groups[level]) {
      groups[level].push(entry);
    } else {
      groups.LOW.push(entry);
    }
  }

  return groups;
}

function filterByImportance(entries, levels) {
  if (!levels || levels.length === 0) {
    return entries;
  }

  const normalizedLevels = levels.map(l => l.toUpperCase());
  return entries.filter(e => normalizedLevels.includes(e.importance));
}

function filterByAge(entries, maxAgeDays, referenceDate = new Date()) {
  if (!maxAgeDays || maxAgeDays <= 0) {
    return entries;
  }

  const cutoffDate = new Date(referenceDate);
  cutoffDate.setDate(cutoffDate.getDate() - maxAgeDays);

  return entries.filter(entry => {
    if (!entry.date) {
      // Keep entries without dates (they're recent enough to not have been archived)
      return true;
    }

    const entryDate = new Date(entry.date);
    return entryDate >= cutoffDate;
  });
}

function getEntrySize(entry) {
  if (!entry) return 0;

  // Use rawText if available, otherwise reconstruct
  if (entry.rawText) {
    return entry.rawText.length;
  }

  // Estimate from components
  return (
    (entry.category || '').length +
    (entry.title || '').length +
    (entry.date || '').length +
    (entry.importance || '').length +
    (entry.content || '').length +
    50 // Overhead for markdown formatting
  );
}

function getTotalSize(entries) {
  if (!entries || entries.length === 0) return 0;

  return entries.reduce((total, entry) => total + getEntrySize(entry), 0);
}

function serializeEntry(entry) {
  if (!entry) return '';

  const lines = [];

  // Header
  lines.push(`## [${entry.category || 'UNKNOWN'}] ${entry.title || 'Untitled'}`);

  // Date
  if (entry.date) {
    lines.push(`**Date**: ${entry.date}`);
  }

  // Importance
  lines.push(`**Importance**: ${entry.importance || DEFAULT_IMPORTANCE}`);

  // Content (with blank line before)
  if (entry.content) {
    lines.push('');
    lines.push(entry.content);
  }

  return lines.join('\n');
}

function serializeEntries(entries) {
  if (!entries || entries.length === 0) return '';

  return entries.map(serializeEntry).join('

---

') + '
';
}

function parseEntriesFromFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      return [];
    }

    const content = fs.readFileSync(filePath, 'utf8');
    return parseEntries(content);
  } catch (_err) {
    // Return empty array on any read error
    return [];
  }
}

function writeEntriesToFile(filePath, entries) {
  const content = serializeEntries(entries);
  fs.writeFileSync(filePath, content, 'utf8');
}

function buildUserPrompt(newMemory, similarMemories) {
  const similar = Array.isArray(similarMemories) ? similarMemories : [];
  return CONSOLIDATION_USER_PROMPT.replace('{{newMemory}}', String(newMemory || ''))
    .replace(
      '{{similarMemories}}',
      similar.length > 0 ? similar.map(m => `- ${m}`).join('\n') : '(none)'
    )
    .trim();
}

function getMemoryDir(projectRoot = PROJECT_ROOT) {
  return path.join(projectRoot, '.claude', 'context', 'memory');
}

function getMetricsDir(projectRoot = PROJECT_ROOT) {
  const metricsDir = path.join(getMemoryDir(projectRoot), 'metrics');
  if (!fs.existsSync(metricsDir)) {
    fs.mkdirSync(metricsDir, { recursive: true });
  }
  return metricsDir;
}

function getFileSizeKB(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      return Math.round(fs.statSync(filePath).size / 1024);
    }
  } catch (e) {
    logger.debug('getFileSizeKB error', {
      function: 'getFileSizeKB',
      error: e.message,
    });
  }
  return 0;
}

function getJsonEntryCount(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
      if (Array.isArray(data)) {
        return data.length;
      }
      if (data.discovered_files) {
        return Object.keys(data.discovered_files).length;
      }
    }
  } catch (e) {
    logger.debug('getJsonEntryCount error', {
      function: 'getJsonEntryCount',
      error: e.message,
    });
  }
  return 0;
}

function countDirFiles(dirPath, pattern = /\.json$/) {
  try {
    if (fs.existsSync(dirPath)) {
      return fs.readdirSync(dirPath).filter(f => pattern.test(f)).length;
    }
  } catch (e) {
    logger.debug('countDirFiles error', {
      function: 'countDirFiles',
      error: e.message,
    });
  }
  return 0;
}

function getDirSizeKB(dirPath, pattern = null) {
  try {
    if (!fs.existsSync(dirPath)) return 0;
    const files = fs.readdirSync(dirPath);
    let total = 0;
    for (const f of files) {
      if (pattern && !pattern.test(f)) continue;
      const fp = path.join(dirPath, f);
      try {
        total += fs.statSync(fp).size;
      } catch (_e) {
        // ignore
      }
    }
    return Math.round(total / 1024);
  } catch (_e) {
    return 0;
  }
}

function calculateMetricScore(value, threshold) {
  if (value <= threshold.warn * 0.7) {
    return 1.0; // Well under warn threshold
  }
  if (value <= threshold.warn) {
    // Approaching warn threshold: 0.8 - 1.0
    const ratio = value / threshold.warn;
    return 1.0 - (ratio - 0.7) * (0.2 / 0.3);
  }
  if (value <= threshold.critical) {
    // In warning zone: 0.5 - 0.8
    const ratio = (value - threshold.warn) / (threshold.critical - threshold.warn);
    return 0.8 - ratio * 0.3;
  }
  // Over critical: 0 - 0.5
  const overRatio = Math.min((value - threshold.critical) / threshold.critical, 1);
  return 0.5 - overRatio * 0.5;
}

function calculateHealthScore(metrics) {
  const {
    learningsSizeKB = 0,
    patternsCount = 0,
    gotchasCount = 0,
    codebaseMapEntries = 0,
    mtmSessionCount = 0,
  } = metrics;

  const scores = {
    learnings: calculateMetricScore(learningsSizeKB, CONFIG.THRESHOLDS.learningsKB),
    patterns: calculateMetricScore(patternsCount, CONFIG.THRESHOLDS.patterns),
    gotchas: calculateMetricScore(gotchasCount, CONFIG.THRESHOLDS.gotchas),
    codebaseMap: calculateMetricScore(codebaseMapEntries, CONFIG.THRESHOLDS.codebaseMapEntries),
    mtm: calculateMetricScore(mtmSessionCount, CONFIG.THRESHOLDS.mtmSessions),
  };

  // Weighted average
  let totalScore = 0;
  let totalWeight = 0;
  for (const [key, weight] of Object.entries(CONFIG.HEALTH_WEIGHTS)) {
    totalScore += scores[key] * weight;
    totalWeight += weight;
  }

  return Math.round((totalScore / totalWeight) * 100) / 100;
}

function generateRecommendations(metrics) {
  const {
    learningsSizeKB = 0,
    patternsCount = 0,
    gotchasCount = 0,
    codebaseMapEntries = 0,
    mtmSessionCount = 0,
    legacySessionsCount = 0,
  } = metrics;

  const recommendations = [];

  // Learnings.md recommendations
  if (learningsSizeKB >= CONFIG.THRESHOLDS.learningsKB.critical) {
    recommendations.push(
      `CRITICAL: learnings.md is ${learningsSizeKB}KB - run archival immediately`
    );
  } else if (learningsSizeKB >= CONFIG.THRESHOLDS.learningsKB.warn) {
    recommendations.push(
      `Consider archiving learnings.md (${learningsSizeKB}KB approaching ${CONFIG.THRESHOLDS.learningsKB.critical}KB threshold)`
    );
  }

  // Patterns recommendations
  if (patternsCount >= CONFIG.THRESHOLDS.patterns.critical) {
    recommendations.push(
      `CRITICAL: patterns.json has ${patternsCount} entries - run deduplication and pruning`
    );
  } else if (patternsCount >= CONFIG.THRESHOLDS.patterns.warn) {
    recommendations.push(
      `Consider pruning patterns.json (${patternsCount} entries approaching ${CONFIG.THRESHOLDS.patterns.critical} threshold)`
    );
  }

  // Gotchas recommendations
  if (gotchasCount >= CONFIG.THRESHOLDS.gotchas.critical) {
    recommendations.push(
      `CRITICAL: gotchas.json has ${gotchasCount} entries - run deduplication and pruning`
    );
  } else if (gotchasCount >= CONFIG.THRESHOLDS.gotchas.warn) {
    recommendations.push(
      `Consider pruning gotchas.json (${gotchasCount} entries approaching ${CONFIG.THRESHOLDS.gotchas.critical} threshold)`
    );
  }

  // Codebase map recommendations
  if (codebaseMapEntries >= CONFIG.THRESHOLDS.codebaseMapEntries.critical) {
    recommendations.push(
      `CRITICAL: codebase_map.json has ${codebaseMapEntries} entries - run TTL pruning`
    );
  } else if (codebaseMapEntries >= CONFIG.THRESHOLDS.codebaseMapEntries.warn) {
    recommendations.push(
      `Consider pruning codebase_map.json (${codebaseMapEntries} entries approaching ${CONFIG.THRESHOLDS.codebaseMapEntries.critical} threshold)`
    );
  }

  // MTM recommendations
  if (mtmSessionCount >= CONFIG.THRESHOLDS.mtmSessions.critical) {
    recommendations.push(
      `CRITICAL: MTM has ${mtmSessionCount} sessions - run summarization to LTM immediately`
    );
  } else if (mtmSessionCount >= CONFIG.THRESHOLDS.mtmSessions.warn) {
    recommendations.push(
      `Consider summarizing MTM sessions to LTM (${mtmSessionCount} sessions approaching ${CONFIG.THRESHOLDS.mtmSessions.critical} limit)`
    );
  }

  if (legacySessionsCount > 0) {
    recommendations.push(
      `Legacy sessions/ has ${legacySessionsCount} files - run migration and delete legacy data`
    );
  }

  return recommendations;
}

function collectMetrics(projectRoot = PROJECT_ROOT) {
  const memoryDir = getMemoryDir(projectRoot);

  // File metrics
  const learningsSizeKB = getFileSizeKB(path.join(memoryDir, 'learnings.md'));
  const patternsCount = getJsonEntryCount(path.join(memoryDir, 'patterns.json'));
  const gotchasCount = getJsonEntryCount(path.join(memoryDir, 'gotchas.json'));
  const codebaseMapEntries = getJsonEntryCount(path.join(memoryDir, 'codebase_map.json'));
  const sessionsCount = countDirFiles(path.join(memoryDir, 'sessions'), /^session_\d{3}\.json$/);

  // Tier metrics
  const stmSessions = countDirFiles(path.join(memoryDir, 'stm'), /\.json$/);
  const mtmSessions = countDirFiles(path.join(memoryDir, 'mtm'), /\.json$/);
  const ltmSummaries = countDirFiles(path.join(memoryDir, 'ltm'), /\.json$/);

  // Cold storage and maintenance status
  let lastColdArchive = null;
  let lastWeekly = null;
  try {
    const statusPath = path.join(memoryDir, 'maintenance-status.json');
    if (fs.existsSync(statusPath)) {
      const status = JSON.parse(fs.readFileSync(statusPath, 'utf8'));
      lastColdArchive = status.lastColdArchive ?? null;
      lastWeekly = status.lastWeekly ?? null;
    }
  } catch (_e) {
    // ignore
  }
  const coldDir = path.join(memoryDir, 'cold');
  const coldFileCount = fs.existsSync(coldDir)
    ? fs.readdirSync(coldDir).filter(f => /\.jsonl\.gz$/.test(f)).length
    : 0;
  const coldSizeKB = getDirSizeKB(coldDir, /\.jsonl\.gz$/);

  let entityCount = 0;
  let relationshipCount = 0;
  const dbPath = path.join(projectRoot, '.claude', 'data', 'memory.db');
  if (fs.existsSync(dbPath)) {
    try {
      const { DatabaseSync } = require('node:sqlite');
      const db = new DatabaseSync(dbPath);
      try {
        entityCount = db.prepare('SELECT COUNT(*) AS c FROM entities').get()?.c || 0;
        relationshipCount =
          db.prepare('SELECT COUNT(*) AS c FROM entity_relationships').get()?.c || 0;
      } finally {
        db.close();
      }
    } catch (_e) {
      // best-effort
    }
  }

  // Calculate totals
  const totalEntries = patternsCount + gotchasCount + codebaseMapEntries;

  // Calculate total size
  let totalSizeKB = learningsSizeKB;
  totalSizeKB += getFileSizeKB(path.join(memoryDir, 'patterns.json'));
  totalSizeKB += getFileSizeKB(path.join(memoryDir, 'gotchas.json'));
  totalSizeKB += getFileSizeKB(path.join(memoryDir, 'codebase_map.json'));
  totalSizeKB += getFileSizeKB(path.join(memoryDir, 'decisions.md'));
  totalSizeKB += getFileSizeKB(path.join(memoryDir, 'issues.md'));

  // Calculate health score
  const healthScore = calculateHealthScore({
    learningsSizeKB,
    patternsCount,
    gotchasCount,
    codebaseMapEntries,
    mtmSessionCount: mtmSessions,
  });

  // Generate recommendations
  const recommendations = generateRecommendations({
    learningsSizeKB,
    patternsCount,
    gotchasCount,
    codebaseMapEntries,
    mtmSessionCount: mtmSessions,
    legacySessionsCount: sessionsCount,
  });

  return {
    timestamp: new Date().toISOString(),
    summary: {
      totalEntries,
      totalSizeKB,
      healthScore,
      entityCount,
      relationshipCount,
    },
    tiers: {
      stm: { sessions: stmSessions, sizeKB: 0 },
      mtm: { sessions: mtmSessions, sizeKB: 0 },
      ltm: { summaries: ltmSummaries, sizeKB: 0 },
    },
    cold: {
      lastColdArchive,
      lastWeekly,
      fileCount: coldFileCount,
      sizeKB: coldSizeKB,
    },
    files: {
      'learnings.md': {
        sizeKB: learningsSizeKB,
        lines: getFileLineCount(path.join(memoryDir, 'learnings.md')),
        status: getFileStatus(learningsSizeKB, CONFIG.THRESHOLDS.learningsKB),
      },
      'patterns.json': {
        entries: patternsCount,
        status: getFileStatus(patternsCount, CONFIG.THRESHOLDS.patterns),
      },
      'gotchas.json': {
        entries: gotchasCount,
        status: getFileStatus(gotchasCount, CONFIG.THRESHOLDS.gotchas),
      },
      'codebase_map.json': {
        entries: codebaseMapEntries,
        status: getFileStatus(codebaseMapEntries, CONFIG.THRESHOLDS.codebaseMapEntries),
      },
      'sessions/ (legacy)': {
        count: sessionsCount,
        status: 'healthy',
      },
    },
    recommendations,
  };
}

function getFileLineCount(filePath) {
  try {
    if (fs.existsSync(filePath)) {
      const content = fs.readFileSync(filePath, 'utf8');
      return content.split('\n').length;
    }
  } catch (e) {
    logger.debug('getFileLineCount error', {
      function: 'getFileLineCount',
      error: e.message,
    });
  }
  return 0;
}

function getFileStatus(value, threshold) {
  if (value >= threshold.critical) return 'critical';
  if (value >= threshold.warn) return 'warning';
  return 'healthy';
}

function saveMetrics(metrics, projectRoot = PROJECT_ROOT) {
  const metricsDir = getMetricsDir(projectRoot);
  const today = new Date().toISOString().split('T')[0];
  const metricsPath = path.join(metricsDir, `${today}.json`);

  fs.writeFileSync(metricsPath, JSON.stringify(metrics, null, 2) + '\n');
  return metricsPath;
}

function getMetricsHistory(days = 7, projectRoot = PROJECT_ROOT) {
  const metricsDir = getMetricsDir(projectRoot);
  const history = [];

  try {
    const files = fs
      .readdirSync(metricsDir)
      .filter(f => f.match(/^\d{4}-\d{2}-\d{2}\.json$/))
      .sort()
      .reverse()
      .slice(0, days);

    for (const file of files) {
      try {
        const data = JSON.parse(fs.readFileSync(path.join(metricsDir, file), 'utf8'));
        history.push({
          date: file.replace('.json', ''),
          ...data,
        });
      } catch (e) {
        logger.debug('getMetricsHistory parsing error', {
          function: 'getMetricsHistory',
          context: 'parsing file',
          file: file,
          error: e.message,
        });
      }
    }
  } catch (e) {
    logger.debug('getMetricsHistory reading directory error', {
      function: 'getMetricsHistory',
      context: 'reading directory',
      error: e.message,
    });
  }

  return history;
}

function cleanupOldMetrics(projectRoot = PROJECT_ROOT) {
  const metricsDir = getMetricsDir(projectRoot);
  const cutoffDate = new Date();
  cutoffDate.setDate(cutoffDate.getDate() - CONFIG.METRICS_RETENTION_DAYS);

  let removedCount = 0;

  try {
    const files = fs.readdirSync(metricsDir).filter(f => f.match(/^\d{4}-\d{2}-\d{2}\.json$/));

    for (const file of files) {
      const dateStr = file.replace('.json', '');
      const fileDate = new Date(dateStr);

      if (fileDate < cutoffDate) {
        fs.unlinkSync(path.join(metricsDir, file));
        removedCount++;
      }
    }
  } catch (e) {
    logger.debug('cleanupOldMetrics error', {
      function: 'cleanupOldMetrics',
      error: e.message,
    });
  }

  return removedCount;
}

async function getLanceDBStatus(projectRoot = PROJECT_ROOT) {
  if (process.env.MEMORY_SEMANTIC_SEARCH === 'off') {
    return { status: 'disabled', reason: 'MEMORY_SEMANTIC_SEARCH=off' };
  }
  try {
    const { MemoryVectorStore } = require('./lancedb-client.cjs');
    const store = new MemoryVectorStore({
      persistDirectory: path.join(projectRoot, '.claude', 'data', 'lancedb'),
    });
    await store.initialize();
    if (typeof store.getEmbeddingStatus === 'function') {
      const status = store.getEmbeddingStatus();
      if (status && status.status !== 'ready') return status;
      if (typeof store.getTableVectorDimension === 'function') {
        const tableDim = await store.getTableVectorDimension();
        const embedDim = await store.getEmbeddingDimension();
        if (Number.isFinite(tableDim) && Number.isFinite(embedDim) && tableDim !== embedDim) {
          return {
            status: 'unavailable',
            reason: `embedding dimension mismatch (table ${tableDim} vs model ${embedDim})`,
          };
        }
      }
      return status;
    }
    return null;
  } catch (e) {
    return { status: 'unavailable', reason: e.message };
  }
}

function getDashboard(projectRoot = PROJECT_ROOT) {
  const metrics = collectMetrics(projectRoot);

  // Save metrics for history tracking
  saveMetrics(metrics, projectRoot);

  // Cleanup old metrics
  cleanupOldMetrics(projectRoot);

  return metrics;
}

function formatDashboard(dashboard) {
  const lines = [];

  lines.push('='.repeat(60));
  lines.push('MEMORY SYSTEM DASHBOARD');
  lines.push('='.repeat(60));
  lines.push(`Timestamp: ${dashboard.timestamp}`);
  lines.push('');

  // Summary
  lines.push('SUMMARY');
  lines.push('-'.repeat(40));
  lines.push(`  Total Entries: ${dashboard.summary.totalEntries}`);
  lines.push(`  Total Size: ${dashboard.summary.totalSizeKB} KB`);
  lines.push(`  Health Score: ${(dashboard.summary.healthScore * 100).toFixed(0)}%`);
  if (dashboard.summary.entityCount !== undefined) {
    lines.push(`  Entities: ${dashboard.summary.entityCount}`);
  }
  if (dashboard.summary.relationshipCount !== undefined) {
    lines.push(`  Relationships: ${dashboard.summary.relationshipCount}`);
  }
  lines.push('');

  // LanceDB / semantic search
  if (dashboard.semanticStatus) {
    const status = dashboard.semanticStatus;
    if (status.status === 'ready') {
      lines.push(`Semantic search: enabled (${status.mode || 'transformers'})`);
      lines.push('');
    } else if (status.status === 'disabled') {
      lines.push(`Semantic search: disabled (${status.reason || 'disabled'})`);
      lines.push('');
    } else if (status.status === 'unavailable') {
      const reason = status.reason ? `: ${status.reason}` : '';
      lines.push(`Semantic search: disabled (embeddings unavailable${reason})`);
      lines.push('');
    }
  }

  // Tiers
  lines.push('MEMORY TIERS');
  lines.push('-'.repeat(40));
  lines.push(`  STM (Short-Term): ${dashboard.tiers.stm.sessions} session(s)`);
  lines.push(`  MTM (Mid-Term): ${dashboard.tiers.mtm.sessions} sessions`);
  lines.push(`  LTM (Long-Term): ${dashboard.tiers.ltm.summaries} summaries`);
  if (dashboard.cold) {
    lines.push(
      `  Cold: ${dashboard.cold.fileCount} archive(s), ${dashboard.cold.sizeKB || 0} KB, last: ${dashboard.cold.lastColdArchive || 'never'}`
    );
  }
  lines.push('');

  // Files
  lines.push('MEMORY FILES');
  lines.push('-'.repeat(40));
  for (const [file, info] of Object.entries(dashboard.files)) {
    const status = info.status || 'healthy';
    const statusIcon = status === 'critical' ? '[!]' : status === 'warning' ? '[~]' : '[ok]';
    if (info.sizeKB !== undefined) {
      lines.push(`  ${statusIcon} ${file}: ${info.sizeKB} KB`);
    } else if (info.entries !== undefined) {
      lines.push(`  ${statusIcon} ${file}: ${info.entries} entries`);
    } else if (info.count !== undefined) {
      lines.push(`  ${statusIcon} ${file}: ${info.count} files`);
    }
  }
  lines.push('');

  // Recommendations
  if (dashboard.recommendations.length > 0) {
    lines.push('RECOMMENDATIONS');
    lines.push('-'.repeat(40));
    for (const rec of dashboard.recommendations) {
      lines.push(`  - ${rec}`);
    }
    lines.push('');
  } else {
    lines.push('STATUS: All systems healthy');
    lines.push('');
  }

  lines.push('='.repeat(60));

  return lines.join('\n');
}

 * @class EntityExtractor
 */
class EntityExtractor {
  /**
   * Create EntityExtractor instance
   * @param {string} dbPath - Path to SQLite database (default: .claude/data/memory.db)
   */
  constructor(dbPath) {
    // Default database path
    if (!dbPath) {
      const projectRoot = path.resolve(__dirname, '../../../');
      dbPath = path.join(projectRoot, '.claude/data/memory.db');
    }

    // Open database connection
    this.db = new DatabaseSync(dbPath);
    this.db.exec('PRAGMA foreign_keys = ON');
    this.db.exec('PRAGMA busy_timeout = 5000');

    // Validate schema exists
    try {
      const tableCheck = this.db
        .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='entities'")
        .get();
      if (!tableCheck) {
        console.log('[EntityExtractor] Database not initialized. Auto-initializing...');
        try {
          const initScript = require('../../tools/cli/init-memory-db.cjs');
          initScript.initializeDatabase(this.db);
        } catch (initError) {
          throw new Error(
            `Auto-initialization failed: ${initError.message}. Run \`pnpm run memory:init\`.`
          );
        }
      }
    } catch (error) {
      // Re-throw specific errors, wrap others
      if (error.message.includes('memory:init')) throw error;
      throw new Error(
        `Database validation failed: ${error.message}. Try running \`pnpm run memory:init\`.`
      );
    }
  }

  /**
   * Extract entities from markdown content
   *
   * @param {string} content - Markdown content
   * @param {string} filePath - Source file path (for metadata)
   * @returns {Promise<Array>} Extracted entities
   */
  async extract(content, filePath) {
    const entities = [];
    const lines = content.split('\n');

    // Determine file type from path
    const fileType = this._detectFileType(filePath);

    // Extract entities based on file type (primary extraction)
    if (fileType === 'learnings') {
      entities.push(...this._extractLearningEntities(lines, filePath));
    } else if (fileType === 'decisions') {
      entities.push(...this._extractDecisionEntities(lines, filePath));
    } else if (fileType === 'issues') {
      entities.push(...this._extractIssueEntities(lines, filePath));
    }

    // Always try to extract other entity types (embedded content)
    // This handles cases where ADRs are referenced in learnings, etc.
    if (fileType !== 'decisions') {
      entities.push(...this._extractDecisionEntities(lines, filePath));
    }
    if (fileType !== 'issues') {
      entities.push(...this._extractIssueEntities(lines, filePath));
    }

    // Extract task references across all file types
    entities.push(...this._extractTaskEntities(lines, filePath));

    return entities;
  }

  /**
   * Extract relationships from markdown content
   *
   * Patterns:
   * - "Task X blocks Task Y"
   * - "Task X depends on Task Y"
   * - "Pattern X implements Decision Y"
   * - "Related Specifications: file.md"
   *
   * @param {string} content - Markdown content
   * @param {string} filePath - Source file path (for metadata)
   * @returns {Promise<Array>} Extracted relationships
   */
  async extractRelationships(content, filePath) {
    const relationships = [];

    // Pattern: Task X blocks Task Y
    const blocksPattern = /Task #?(\d+) blocks Task #?(\d+)/gi;
    let match;

    while ((match = blocksPattern.exec(content)) !== null) {
      relationships.push({
        from: `task-${match[1]}`,
        to: `task-${match[2]}`,
        type: 'blocks',
        weight: 1.0,
      });
    }

    // Pattern: Task X depends on Task Y
    const dependsPattern = /Task #?(\d+) depends on Task #?(\d+)/gi;

    while ((match = dependsPattern.exec(content)) !== null) {
      relationships.push({
        from: `task-${match[1]}`,
        to: `task-${match[2]}`,
        type: 'depends_on',
        weight: 1.0,
      });
    }

    // Pattern: Pattern X implements ADR-Y
    const implementsPattern = /Pattern (\S+) implements (?:Decision )?ADR-(\d+)/gi;

    while ((match = implementsPattern.exec(content)) !== null) {
      relationships.push({
        from: `pattern-${match[1].toLowerCase()}`,
        to: `adr-${match[2]}`,
        type: 'implements',
        weight: 1.0,
      });
    }

    // Pattern: Related Specifications: file.md
    const referencesPattern = /Related Specifications?:(.*?)(?:\n|$)/gi;

    while ((match = referencesPattern.exec(content)) !== null) {
      const files = match[1].match(/[\w-]+\.md/g) || [];
      for (const file of files) {
        relationships.push({
          from: path.basename(filePath, '.md'),
          to: file.replace('.md', ''),
          type: 'references',
          weight: 0.5,
        });
      }
    }

    return relationships;
  }

  /**
   * Store entities in SQLite database
   *
   * Uses UPSERT (INSERT OR REPLACE) to handle duplicates gracefully
   *
   * @param {Array} entities - Entities to store
   * @returns {Promise<void>}
   */
  async storeEntities(entities) {
    const stmt = this.db.prepare(`
      INSERT OR REPLACE INTO entities (
        id, type, name, content, source_file, line_number,
        created_at, updated_at
      )
      VALUES (?, ?, ?, ?, ?, ?, COALESCE(
        (SELECT created_at FROM entities WHERE id = ?),
        strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
      ), strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
    `);

    for (const entity of entities) {
      stmt.run(
        entity.id,
        entity.type,
        entity.name,
        entity.content || null,
        entity.source_file,
        entity.line_number || null,
        entity.id // For COALESCE to preserve created_at
      );
    }
  }

  /**
   * Store relationships in SQLite database
   *
   * @param {Array} relationships - Relationships to store
   * @returns {Promise<void>}
   */
  async storeRelationships(relationships) {
    const stmt = this.db.prepare(`
      INSERT OR IGNORE INTO entity_relationships (
        from_entity_id, to_entity_id, relationship_type, weight
      )
      VALUES (?, ?, ?, ?)
    `);

    for (const rel of relationships) {
      stmt.run(rel.from, rel.to, rel.type, rel.weight || 1.0);
    }
  }

  /**
   * Extract entities from file
   *
   * @param {string} filePath - Path to markdown file
   * @returns {Promise<Object>} { entities, relationships }
   */
  async extractFromFile(filePath) {
    const content = fs.readFileSync(filePath, 'utf8');
    const entities = await this.extract(content, filePath);
    const relationships = await this.extractRelationships(content, filePath);

    return { entities, relationships };
  }

  // Private helper methods

  /**
   * Detect file type from path
   * @private
   */
  _detectFileType(filePath) {
    const basename = path.basename(filePath, '.md').toLowerCase();
    if (basename.includes('learning')) return 'learnings';
    if (basename.includes('decision')) return 'decisions';
    if (basename.includes('issue')) return 'issues';

    // Also check for pattern/concept indicators (treat as learnings)
    if (basename.includes('pattern') || basename.includes('concept')) return 'learnings';

    return 'unknown';
  }

  /**
   * Extract learning entities (patterns, concepts)
   * @private
   */
  _extractLearningEntities(lines, filePath) {
    const entities = [];
    let currentEntity = null;
    let currentContent = [];
    const patternHeader = /^(?:#{1,4}\s+|\s*[-*]\s+)(?:\*\*)?Pattern:?\*?\*?\s*:?\s*(.+)/i;
    const conceptHeader = /^(?:#{1,4}\s+|\s*[-*]\s+)(?:\*\*)?Concept:?\*?\*?\s*:?\s*(.+)/i;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      let conceptMatch;

      // Pattern: ### Pattern: Name or ## Pattern: Name
      const patternMatch = line.match(patternHeader);
      if (patternMatch) {
        // Save previous entity if exists
        if (currentEntity) {
          currentEntity.content = currentContent.join('\n').trim();
          entities.push(currentEntity);
        }

        const name = patternMatch[1].trim();
        currentEntity = {
          id: `pattern-${this._slugify(name)}`,
          type: 'pattern',
          name: name,
          source_file: filePath,
          line_number: i + 1,
        };
        currentContent = [];
      }
      // Concept: ### Concept: Name or ## Concept: Name
      else if ((conceptMatch = line.match(conceptHeader))) {
        if (currentEntity) {
          currentEntity.content = currentContent.join('\n').trim();
          entities.push(currentEntity);
        }

        const name = conceptMatch[1].trim();
        currentEntity = {
          id: `concept-${this._slugify(name)}`,
          type: 'concept',
          name: name,
          source_file: filePath,
          line_number: i + 1,
        };
        currentContent = [];
      }
      // New section header ends current entity
      else if (line.match(/^#{1,4}\s+/)) {
        if (currentEntity) {
          currentEntity.content = currentContent.join('\n').trim();
          entities.push(currentEntity);
          currentEntity = null;
          currentContent = [];
        }
      }
      // Accumulate content
      else if (currentEntity) {
        currentContent.push(line);
      }
    }

    // Save last entity
    if (currentEntity) {
      currentEntity.content = currentContent.join('\n').trim();
      entities.push(currentEntity);
    }

    return entities;
  }

  /**
   * Extract decision entities (ADRs)
   * @private
   */
  _extractDecisionEntities(lines, filePath) {
    const entities = [];
    let currentEntity = null;
    let currentContent = [];
    const adrHeader = /^(?:#{1,4}\s+|\s*[-*]\s+)\[?(?:ADR|Decision)[- #]?(\d+)\]?\s*:?\s*(.+)/i;
    const decisionHeader = /^(?:#{1,4}\s+|\s*[-*]\s+)(?:\*\*)?Decision:?\*?\*?\s*:?\s*(.+)/i;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];

      // Pattern: ## [ADR-NNN] Title, ## ADR-NNN: Title, or ## Decision: Title
      const adrMatch = line.match(adrHeader);
      const decisionMatch = !adrMatch && line.match(decisionHeader);
      if (adrMatch) {
        // Save previous entity
        if (currentEntity) {
          currentEntity.content = currentContent.join('\n').trim();
          entities.push(currentEntity);
        }

        const adrNumber = adrMatch[1];
        const title = adrMatch[2].trim();

        currentEntity = {
          id: `adr-${adrNumber}`,
          type: 'decision',
          name: `ADR-${adrNumber}: ${title}`,
          source_file: filePath,
          line_number: i + 1,
        };
        currentContent = [];
      } else if (decisionMatch) {
        if (currentEntity) {
          currentEntity.content = currentContent.join('\n').trim();
          entities.push(currentEntity);
        }
        const title = decisionMatch[1].trim();
        currentEntity = {
          id: `decision-${this._slugify(title)}`,
          type: 'decision',
          name: title,
          source_file: filePath,
          line_number: i + 1,
        };
        currentContent = [];
      }
      // New section header ends current entity
      else if (line.match(/^#{1,4}\s+/)) {
        if (currentEntity) {
          currentEntity.content = currentContent.join('\n').trim();
          entities.push(currentEntity);
          currentEntity = null;
          currentContent = [];
        }
      }
      // Accumulate content
      else if (currentEntity) {
        currentContent.push(line);
      }
    }

    // Save last entity
    if (currentEntity) {
      currentEntity.content = currentContent.join('\n').trim();
      entities.push(currentEntity);
    }

    return entities;
  }

  /**
   * Extract issue entities
   * @private
   */
  _extractIssueEntities(lines, filePath) {
    const entities = [];
    let currentEntity = null;
    let currentContent = [];
    const issueHeader = /^(?:#{1,4}\s+|\s*[-*]\s+)(?:\*\*)?Issue:?\*?\*?\s*:?\s*(.+)/i;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];

      // Pattern: ### Issue: Title or ## Issue: Title
      const issueMatch = line.match(issueHeader);
      if (issueMatch) {
        // Save previous entity
        if (currentEntity) {
          currentEntity.content = currentContent.join('\n').trim();
          entities.push(currentEntity);
        }

        const title = issueMatch[1].trim();

        currentEntity = {
          id: `issue-${this._slugify(title)}`,
          type: 'issue',
          name: title,
          source_file: filePath,
          line_number: i + 1,
        };
        currentContent = [];
      }
      // New section header ends current entity
      else if (line.match(/^#{1,4}\s+/)) {
        if (currentEntity) {
          currentEntity.content = currentContent.join('\n').trim();
          entities.push(currentEntity);
          currentEntity = null;
          currentContent = [];
        }
      }
      // Accumulate content
      else if (currentEntity) {
        currentContent.push(line);
      }
    }

    // Save last entity
    if (currentEntity) {
      currentEntity.content = currentContent.join('\n').trim();
      entities.push(currentEntity);
    }

    return entities;
  }

  /**
   * Extract task references from content
   * @private
   */
  _extractTaskEntities(lines, filePath) {
    const entities = [];
    const taskReferences = new Set(); // Avoid duplicates

    // Combine all lines for global pattern matching
    const fullContent = lines.join('\n');

    // Pattern: Task #NNN or Task NNN (anywhere in content)
    // Captures all task references including those in relationships
    const taskPattern = /Task #?(\d+)(?:\s+\(([^)]+)\))?/g;
    let match;

    while ((match = taskPattern.exec(fullContent)) !== null) {
      const taskNumber = match[1];
      const taskId = `task-${taskNumber}`;

      // Skip if already added
      if (taskReferences.has(taskId)) continue;
      taskReferences.add(taskId);

      const taskCode = match[2] || ''; // e.g., "P1-2.1"

      // Try to find description by looking for patterns like:
      // "Task #25 - Description" or "Task #25: Description"
      let taskDesc = '';
      const descPattern = new RegExp(
        `Task #?${taskNumber}(?:\\s+\\([^)]+\\))?[:\\s-]+([^\\n]+?)(?:\\n|$)`,
        'i'
      );
      const descMatch = fullContent.match(descPattern);
      if (descMatch) {
        taskDesc = descMatch[1].trim();
      }

      entities.push({
        id: taskId,
        type: 'task',
        name: `Task #${taskNumber}${taskCode ? ` (${taskCode})` : ''}`,
        content: taskDesc,
        source_file: filePath,
        line_number: 0, // Will need to find actual line if needed
      });
    }

    return entities;
  }

  /**
   * Convert string to slug (lowercase, hyphens)
   * @private
   */
  _slugify(text) {
    return text
      .toLowerCase()
      .replace(/[^\w\s-]/g, '') // Remove special chars
      .replace(/\s+/g, '-') // Replace spaces with hyphens
      .replace(/-+/g, '-') // Collapse multiple hyphens
      .substring(0, 50); // Limit length
  }

  /**
   * Close database connection
   */
  close() {
    if (this.db) {
      this.db.close();
    }
  }

class SafetyRollbackManager {
  constructor() {
    this.backupDir = path.join(os.tmpdir(), 'conductor-backups');
    this.componentStates = new Map();
    this.auditLog = [];

    // Ensure backup directory exists
    if (!fs.existsSync(this.backupDir)) {
      fs.mkdirSync(this.backupDir, { recursive: true });
    }
  }

  /**
   * Create backup of component state
   * @param {string} componentName
   * @param {Object} [state] - State to backup (if not provided, current state is used)
   * @param {Object} [options] - Backup options
   * @returns {Promise<string>} Backup ID
   */
  async createBackup(componentName, state = null, options = {}) {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const backupId = `${componentName}_${timestamp}`;

    // Get current state if not provided
    const stateToBackup = state || (await this.getCurrentState(componentName));

    const backup = {
      id: backupId,
      componentName,
      timestamp: new Date().toISOString(),
      state: stateToBackup,
      compressed: options.compress || false,
    };

    // Calculate checksum
    const checksum = this._calculateChecksum(JSON.stringify(stateToBackup));
    backup.checksum = checksum;

    // Save backup
    const backupPath = path.join(this.backupDir, `${backupId}.json`);
    fs.writeFileSync(backupPath, JSON.stringify(backup, null, 2));

    // Log
    this._logAction('backup', componentName, backupId);

    return backupId;
  }

  /**
   * List backups for a component
   * @param {string} componentName
   * @returns {Promise<Array<string>>} Backup IDs
   */
  async listBackups(componentName) {
    const files = fs.readdirSync(this.backupDir);
    const backupFiles = files.filter(f => f.startsWith(componentName) && f.endsWith('.json'));

    return backupFiles.map(f => f.replace('.json', ''));
  }

  /**
   * Validate state integrity
   * @param {Object} beforeState
   * @param {Object} afterState
   * @returns {Promise<{valid: boolean, dataLoss: boolean, missingFields?: Array}>}
   */
  async validateState(beforeState, afterState) {
    const missingFields = [];

    // Check for data loss (fields present in before but missing in after)
    const checkFields = (before, after, prefix = '') => {
      for (const key in before) {
        const fullKey = prefix ? `${prefix}.${key}` : key;

        if (!(key in after)) {
          missingFields.push(fullKey);
        } else if (
          typeof before[key] === 'object' &&
          before[key] !== null &&
          !Array.isArray(before[key])
        ) {
          checkFields(before[key], after[key], fullKey);
        }
      }
    };

    checkFields(beforeState, afterState);

    return {
      valid: missingFields.length === 0,
      dataLoss: missingFields.length > 0,
      missingFields: missingFields.length > 0 ? missingFields : undefined,
    };
  }

  /**
   * Rollback component to backup
   * @param {string} componentName
   * @param {string} backupId
   * @param {Object} [options] - Rollback options
   * @returns {Promise<void>}
   */
  async rollback(componentName, backupId, options = {}) {
    const backup = await this.getBackup(backupId);

    if (!backup) {
      throw new Error(`Backup not found: ${backupId}`);
    }

    // Dry-run mode
    if (options.dryRun) {
      return this.previewRollback(componentName, backupId);
    }

    // Verify integrity
    const integrity = await this.verifyBackupIntegrity(backupId);
    if (!integrity.valid) {
      throw new Error(`Backup corrupted: ${backupId}`);
    }

    // Partial rollback (selected fields only)
    if (options.fields && options.fields.length > 0) {
      const currentState = await this.getCurrentState(componentName);
      const newState = { ...currentState };

      for (const field of options.fields) {
        newState[field] = backup.state[field];
      }

      await this.setState(componentName, newState);
    } else {
      // Full rollback
      await this.setState(componentName, backup.state);
    }

    // Log
    this._logAction('rollback', componentName, backupId);

    // Report progress if callback provided
    if (options.onProgress) {
      options.onProgress({ percent: 100 });
    }
  }

  /**
   * Get backup by ID
   * @param {string} backupId
   * @returns {Promise<Object|null>}
   */
  async getBackup(backupId) {
    const backupPath = path.join(this.backupDir, `${backupId}.json`);

    if (!fs.existsSync(backupPath)) {
      return null;
    }

    const content = fs.readFileSync(backupPath, 'utf8');
    return JSON.parse(content);
  }

  /**
   * Verify backup integrity
   * @param {string} backupId
   * @returns {Promise<{valid: boolean, checksum: string}>}
   */
  async verifyBackupIntegrity(backupId) {
    const backup = await this.getBackup(backupId);

    if (!backup) {
      return { valid: false, checksum: null };
    }

    const calculatedChecksum = this._calculateChecksum(JSON.stringify(backup.state));
    const valid = calculatedChecksum === backup.checksum;

    return {
      valid,
      checksum: calculatedChecksum,
    };
  }

  /**
   * Get current state of component
   * @param {string} componentName
   * @returns {Promise<Object>}
   */
  async getCurrentState(componentName) {
    return this.componentStates.get(componentName) || {};
  }

  /**
   * Set component state
   * @param {string} componentName
   * @param {Object} state
   * @returns {Promise<void>}
   */
  async setState(componentName, state) {
    this.componentStates.set(componentName, state);
  }

  /**
   * Get audit trail for component
   * @param {string} componentName
   * @returns {Promise<Array>}
   */
  async getAuditTrail(componentName) {
    return this.auditLog.filter(entry => entry.component === componentName);
  }

  /**
   * Validate rollback safety
   * @param {string} scenario
   * @returns {Promise<{safe: boolean, reasons?: Array}>}
   */
  async validateRollbackSafety(scenario) {
    // Mock implementation - would check actual safety conditions
    if (scenario === 'incompatible-rollback') {
      return {
        safe: false,
        reasons: ['Incompatible rollback scenario'],
      };
    }

    return {
      safe: true,
    };
  }

  /**
   * Apply retention policy to backups
   * @param {string} componentName
   * @param {Object} policy
   * @returns {Promise<void>}
   */
  async applyRetentionPolicy(componentName, policy) {
    const backups = await this.listBackups(componentName);

    if (policy.maxBackups && backups.length > policy.maxBackups) {
      // Sort by timestamp (oldest first)
      backups.sort();

      // Delete oldest backups beyond limit
      const toDelete = backups.slice(0, backups.length - policy.maxBackups);

      for (const backupId of toDelete) {
        const backupPath = path.join(this.backupDir, `${backupId}.json`);
        if (fs.existsSync(backupPath)) {
          fs.unlinkSync(backupPath);
        }
      }
    }
  }

  /**
   * Export backup to external file
   * @param {string} backupId
   * @param {string} exportPath
   * @returns {Promise<void>}
   */
  async exportBackup(backupId, exportPath) {
    const backup = await this.getBackup(backupId);
    if (!backup) {
      throw new Error(`Backup not found: ${backupId}`);
    }

    fs.writeFileSync(exportPath, JSON.stringify(backup, null, 2));
  }

  /**
   * Import backup from external file
   * @param {string} importPath
   * @returns {Promise<string>} Imported backup ID
   */
  async importBackup(importPath) {
    const content = fs.readFileSync(importPath, 'utf8');
    const backup = JSON.parse(content);

    const backupPath = path.join(this.backupDir, `${backup.id}.json`);
    fs.writeFileSync(backupPath, content);

    return backup.id;
  }

  /**
   * Clear all backups for component
   * @param {string} componentName
   * @returns {Promise<void>}
   */
  async clearBackups(componentName) {
    const backups = await this.listBackups(componentName);

    for (const backupId of backups) {
      const backupPath = path.join(this.backupDir, `${backupId}.json`);
      if (fs.existsSync(backupPath)) {
        fs.unlinkSync(backupPath);
      }
    }
  }

  /**
   * Preview rollback changes
   * @param {string} componentName
   * @param {string} backupId
   * @returns {Promise<{changes: Array}>}
   */
  async previewRollback(componentName, backupId) {
    const backup = await this.getBackup(backupId);
    const currentState = await this.getCurrentState(componentName);

    const changes = [];

    // Find differences
    const findDiffs = (before, after, prefix = '') => {
      for (const key in after) {
        const fullKey = prefix ? `${prefix}.${key}` : key;

        if (!(key in before)) {
          changes.push({
            type: 'restore',
            field: fullKey,
            value: after[key],
          });
        } else if (JSON.stringify(before[key]) !== JSON.stringify(after[key])) {
          changes.push({
            type: 'modify',
            field: fullKey,
            from: before[key],
            to: after[key],
          });
        }
      }
    };

    findDiffs(currentState, backup.state);

    return { changes };
  }

  /**
   * Validate completeness after rollback
   * @param {string} componentName
   * @param {Array<string>} requiredFields
   * @returns {Promise<{complete: boolean}>}
   */
  async validateCompleteness(componentName, requiredFields) {
    const state = await this.getCurrentState(componentName);

    for (const field of requiredFields) {
      if (!(field in state.data)) {
        return { complete: false };
      }
    }

    return { complete: true };
  }

  /**
   * Estimate rollback time
   * @param {string} componentName
   * @param {string} backupId
   * @returns {Promise<{seconds: number}>}
   */
  async estimateRollbackTime(componentName, backupId) {
    const backup = await this.getBackup(backupId);

    // Simple estimate: 0.1ms per KB
    const size = JSON.stringify(backup.state).length;
    const seconds = Math.max(1, Math.round(size / 10000));

    return { seconds };
  }

  // Private helpers

  _calculateChecksum(data) {
    return crypto.createHash('sha256').update(data).digest('hex');
  }

  _logAction(action, component, backupId = null) {
    this.auditLog.push({
      action,
      component,
      backupId,
      timestamp: new Date().toISOString(),
    });
  }

  // Test helpers
  async corruptBackup(backupId) {
    const backupPath = path.join(this.backupDir, `${backupId}.json`);
    if (fs.existsSync(backupPath)) {
      const backup = JSON.parse(fs.readFileSync(backupPath, 'utf8'));
      backup.checksum = 'corrupted';
      fs.writeFileSync(backupPath, JSON.stringify(backup));
    }
  }

  async simulateRollbackFailure(componentName, backupId) {
    // Mark for failure simulation
    this._failureSimulation = { componentName, backupId };
  }

function toSafeInt(val, fallback = 0) {
  const n = Number.parseInt(String(val), 10);
  return Number.isFinite(n) ? n : fallback;
}

function computeQualityScore(accessCount) {
  const count = Number.isFinite(accessCount) ? accessCount : 0;
  const max = 20;
  const ratio = Math.min(Math.log1p(count) / Math.log1p(max), 1);
  return Math.round((0.5 + ratio * 0.5) * 1000) / 1000;
}

function getAccessStatsPath(memoryDir) {
  return path.join(memoryDir, 'access-stats.json');
}

function loadAccessStats(memoryDir) {
  const statsPath = getAccessStatsPath(memoryDir);
  try {
    if (fs.existsSync(statsPath)) {
      const parsed = JSON.parse(fs.readFileSync(statsPath, 'utf8'));
      if (parsed && typeof parsed === 'object') {
        return {
          version: parsed.version || '1.0',
          entries: parsed.entries && typeof parsed.entries === 'object' ? parsed.entries : {},
        };
      }
    }
  } catch (_e) {
    // Best-effort; fall through to default
  }
  return { version: '1.0', entries: {} };
}

function buildAccessKey(entry) {
  if (!entry || typeof entry !== 'object') return null;
  if (entry.id) return `id:${entry.id}`;
  if (typeof entry.text === 'string') {
    return `text:${entry.text}\n${entry.timestamp || ''}`;
  }
  return null;
}

function applyAccessStats(entries, stats) {
  if (!Array.isArray(entries) || entries.length === 0) return;
  if (!stats || typeof stats !== 'object' || !stats.entries) return;
  for (const entry of entries) {
    const key = buildAccessKey(entry);
    if (!key) continue;
    const stat = stats.entries[key];
    if (!stat) continue;
    entry.accessCount = toSafeInt(stat.accessCount, 0);
    entry.lastAccessed = stat.lastAccessed || null;
  }
}

function updateAccessStatsInPlace(stats, returnedEntries, nowIso) {
  if (!ACCESS_TRACKING_ENABLED) return false;
  if (!stats || typeof stats !== 'object') return false;
  if (!Array.isArray(returnedEntries) || returnedEntries.length === 0) return false;

  const entries = stats.entries || {};
  const nowMs = Date.parse(nowIso);
  const minInterval = Number.isFinite(ACCESS_TRACKING_MIN_INTERVAL_MS)
    ? ACCESS_TRACKING_MIN_INTERVAL_MS
    : 0;

  let changed = false;
  for (const entry of returnedEntries) {
    const key = buildAccessKey(entry);
    if (!key) continue;

    const current = entries[key] || { accessCount: 0, lastAccessed: null };
    const lastAccessedMs = current.lastAccessed ? Date.parse(current.lastAccessed) : 0;

    if (!current.lastAccessed || nowMs - lastAccessedMs >= minInterval) {
      entries[key] = {
        accessCount: toSafeInt(current.accessCount, 0) + 1,
        lastAccessed: nowIso,
      };
      changed = true;
    }
  }

  stats.entries = entries;
  return changed;
}

class ContextualMemory {
  /**
   * Create ContextualMemory instance
   *
   * @param {Object} config - Configuration options
   * @param {string} config.memoryDir - Directory containing memory files (default: .claude/context/memory)
   * @param {string} config.dbPath - Path to SQLite database (default: .claude/data/memory.db)
   * @param {Object} config.lancedbConfig - LanceDB configuration (optional)
   * @param {string} config.lancedbConfig.persistDirectory - LanceDB persist directory
   * @param {string} config.lancedbConfig.collectionName - LanceDB table name
   */
  constructor(config = {}) {
    const projectRoot = config.projectRoot || PROJECT_ROOT;

    this.config = {
      projectRoot,
      memoryDir: config.memoryDir || path.join(projectRoot, '.claude/context/memory'),
      dbPath: config.dbPath || path.join(projectRoot, '.claude/data/memory.db'),
      lancedbConfig: config.lancedbConfig || {
        persistDirectory: path.join(projectRoot, '.claude/data/lancedb'),
        collectionName: process.env.LANCEDB_TABLE || 'agent_memory',
      },
    };

    // Initialize components (undefined = not yet tried; null = tried and unavailable)
    this.vectorStore = null; // Lazy initialization
    this.entityQuery = undefined; // Lazy initialization
    this._mockModeWarned = false;
    this._semanticFallbackWarned = false;
  }

  /**
   * Log LanceDB/embedding event to metrics JSONL for observability in headless environments.
   * @private
   * @param {string} event - Event name (e.g. 'mock_mode_detected')
   * @param {Object} [payload] - Optional extra fields
   */
  _logLancedbEvent(event, payload = {}) {
    try {
      const metricsDir = path.join(this.config.memoryDir, 'metrics');
      if (!fs.existsSync(metricsDir)) {
        fs.mkdirSync(metricsDir, { recursive: true });
      }
      const eventsPath = path.join(metricsDir, 'lancedb-events.jsonl');
      const line =
        JSON.stringify({
          timestamp: new Date().toISOString(),
          event,
          ...payload,
        }) + '\n';
      fs.appendFileSync(eventsPath, line);
    } catch (_e) {
      // Best-effort; do not throw
    }
  }

  /**
   * Initialize LanceDB vector store (lazy)
   *
   * @private
   * @returns {Promise<MemoryVectorStore>}
   */
  async _getVectorStore() {
    if (process.env.MEMORY_SEMANTIC_SEARCH === 'off') {
      return null;
    }

    if (!this.vectorStore) {
      this.vectorStore = MemoryVectorStore.getSharedStore(this.config.lancedbConfig);
      try {
        await this.vectorStore.initialize();
        if (this.vectorStore && typeof this.vectorStore.getEmbeddingStatus === 'function') {
          const status = this.vectorStore.getEmbeddingStatus();
          if (status && status.status !== 'ready') {
            if (status.status === 'unavailable' && !this._mockModeWarned) {
              logger.warn(`Semantic search disabled: ${status.reason || status.status}`);
              this._mockModeWarned = true;
            }
            this._logLancedbEvent('semantic_disabled', {
              status: status.status,
              reason: status.reason || null,
              mode: status.mode || null,
            });
            return null;
          }
        }
      } catch (error) {
        logger.warn('LanceDB initialization failed', { error: error.message });
        this.vectorStore = null; // Mark as unavailable
        this._logLancedbEvent('lancedb_init_failed', {
          message: error?.message || String(error),
        });
      }
    }
    return this.vectorStore;
  }

  /**
   * Initialize entity query API (lazy).
   * Ensures entity DB and schema exist before creating EntityQuery (avoids "Required table 'entities' not found").
   *
   * @private
   * @returns {EntityQuery|null}
   */
  _getEntityQuery() {
    if (this.entityQuery !== undefined) {
      return this.entityQuery;
    }
    const dbDir = path.dirname(this.config.dbPath);
    if (!fs.existsSync(dbDir)) {
      fs.mkdirSync(dbDir, { recursive: true });
    }
    try {
      const init = require('../../tools/cli/init-memory-db.cjs');
      const db = init.initializeDatabase(this.config.dbPath);
      if (db && typeof db.close === 'function') {
        db.close();
      }
    } catch (_e) {
      this.entityQuery = null;
      return null;
    }
    try {
      this.entityQuery = new EntityQuery(this.config.dbPath);
    } catch (_e) {
      this.entityQuery = null;
    }
    return this.entityQuery;
  }

  _loadEntitiesFromDb(db, type, limit) {
    const rows = db
      .prepare(
        'SELECT id, name, content, created_at, access_count, last_accessed FROM entities WHERE type = ? ORDER BY quality_score DESC, created_at DESC LIMIT ?'
      )
      .all(type, limit);

    if (rows.length === 0) return [];

    const mapped = rows.map(r => ({
      text: r.name + (r.content ? '\n' + r.content : ''),
      timestamp: r.created_at,
    }));

    try {
      const nowIso = new Date().toISOString();
      const update = db.prepare(
        'UPDATE entities SET access_count = ?, last_accessed = ?, quality_score = ? WHERE id = ?'
      );
      for (const r of rows) {
        const nextCount = toSafeInt(r.access_count, 0) + 1;
        update.run(nextCount, nowIso, computeQualityScore(nextCount), r.id);
      }
    } catch (_e) {
      // best-effort
    }

    return mapped;
  }

  _truncateItems(items, maxChars) {
    let totalChars = 0;
    const result = [];

    for (const item of items) {
      const itemStr = JSON.stringify(item);
      if (totalChars + itemStr.length > maxChars) {
        break;
      }
      totalChars += itemStr.length;
      result.push(item);
    }

    return result;
  }

  /**
   * Load memory context using the unified ContextualMemory read path.
   *
   * @param {Object} options
   * @param {Object} options.maxItems - Limits for each memory section
   * @param {Object} options.maxChars - Character caps for each memory section
   * @returns {Object} Memory context object
   */
  loadContextSync(options = {}) {
    const maxItems = options.maxItems || {};
    const maxChars = options.maxChars || {};
    const result = {
      gotchas: [],
      patterns: [],
      decisions: [],
      discoveries: [],
      recent_sessions: [],
      legacy_summary: '',
    };

    const memoryDir = this.config.memoryDir;
    const dbPath = this.config.dbPath;
    let dbPatternsLoaded = false;
    let dbGotchasLoaded = false;

    if (dbPath && fs.existsSync(dbPath)) {
      try {
        const db = new DatabaseSync(dbPath);
        const patterns = this._loadEntitiesFromDb(db, 'pattern', maxItems.patterns);
        if (patterns.length > 0) {
          result.patterns = patterns;
          dbPatternsLoaded = true;
        }

        const issues = this._loadEntitiesFromDb(db, 'issue', maxItems.gotchas);
        if (issues.length > 0) {
          result.gotchas = issues;
          dbGotchasLoaded = true;
        }

        const decisions = this._loadEntitiesFromDb(db, 'decision', maxItems.decisions);
        if (decisions.length > 0) {
          result.decisions = decisions;
        }

        db.close();
      } catch (e) {
        logger.debug('DB load failed', { error: e.message });
      }
    }

    const accessStats = loadAccessStats(memoryDir);
    const nowIso = new Date().toISOString();

    const gotchasFile = path.join(memoryDir, 'gotchas.json');
    if (!dbGotchasLoaded && fs.existsSync(gotchasFile)) {
      try {
        const allGotchas = JSON.parse(fs.readFileSync(gotchasFile, 'utf8'));
        const selectedGotchas = allGotchas.slice(-maxItems.gotchas);
        result.gotchas = this._truncateItems(selectedGotchas, maxChars.gotchas);
        applyAccessStats(result.gotchas, accessStats);
      } catch (e) {
        logger.debug('Gotchas load failed', { error: e.message });
      }
    }

    const patternsFile = path.join(memoryDir, 'patterns.json');
    if (!dbPatternsLoaded && fs.existsSync(patternsFile)) {
      try {
        const allPatterns = JSON.parse(fs.readFileSync(patternsFile, 'utf8'));
        const selectedPatterns = allPatterns.slice(-maxItems.patterns);
        result.patterns = this._truncateItems(selectedPatterns, maxChars.patterns);
        applyAccessStats(result.patterns, accessStats);
      } catch (e) {
        logger.debug('Patterns load failed', { error: e.message });
      }
    }

    const gotchasAccessChanged = updateAccessStatsInPlace(accessStats, result.gotchas, nowIso);
    const patternsAccessChanged = updateAccessStatsInPlace(accessStats, result.patterns, nowIso);
    const accessChanged = gotchasAccessChanged || patternsAccessChanged;

    // FIXED (Issue #2 - HIGH): Make access stats write non-blocking (fire-and-forget)
    // Using setImmediate to avoid blocking the read operation
    if (accessChanged) {
      setImmediate(() => {
        try {
          atomicWriteJSONSync(getAccessStatsPath(memoryDir), {
            version: '1.0',
            entries: accessStats.entries || {},
          });
          applyAccessStats(result.gotchas, accessStats);
          applyAccessStats(result.patterns, accessStats);
        } catch (_e) {
          // Best-effort; do not block context load
        }
      });
    }

    const mapFile = path.join(memoryDir, 'codebase_map.json');
    if (fs.existsSync(mapFile)) {
      try {
        const map = JSON.parse(fs.readFileSync(mapFile, 'utf8'));
        const discoveries = Object.entries(map.discovered_files || {})
          .slice(-maxItems.discoveries)
          .map(([filePath, info]) => ({ path: filePath, ...info }));
        result.discoveries = this._truncateItems(discoveries, maxChars.discoveries);
      } catch (e) {
        logger.debug('Discoveries load failed', { error: e.message });
      }
    }

    try {
      const memoryTiers = require('./memory-tiers.cjs');
      const projectRoot = this.config.projectRoot || PROJECT_ROOT;
      const mtmSessions = memoryTiers.getMTMSessions(projectRoot);
      if (mtmSessions && mtmSessions.length > 0) {
        const sorted = mtmSessions
          .sort(
            (a, b) =>
              new Date(a.timestamp || a.consolidated_at || 0) -
              new Date(b.timestamp || b.consolidated_at || 0)
          )
          .slice(-maxItems.sessions);

        const sessionNumberBase = mtmSessions.length - sorted.length;
        for (let i = 0; i < sorted.length; i++) {
          const session = sorted[i];
          result.recent_sessions.push({
            session_number: sessionNumberBase + i + 1,
            timestamp: session.timestamp || session.consolidated_at,
            summary: session.summary || '',
            tasks_completed: (session.tasks_completed || []).slice(0, 5),
            source: 'mtm',
          });
        }

        const ltmDir = memoryTiers.getTierPath('LTM', projectRoot);
        if (fs.existsSync(ltmDir)) {
          try {
            const ltmFiles = fs
              .readdirSync(ltmDir)
              .filter(f => f.endsWith('.json') && f.startsWith('summary_'))
              .sort()
              .slice(-2);
            for (const file of ltmFiles) {
              try {
                const summary = JSON.parse(fs.readFileSync(path.join(ltmDir, file), 'utf8'));
                if (summary.type === 'session_summary') {
                  result.recent_sessions.unshift({
                    session_number: 0,
                    timestamp: summary.created_at,
                    summary: `[LTM Summary] ${summary.session_count} sessions from ${summary.date_range?.start || 'unknown'} to ${summary.date_range?.end || 'unknown'}`,
                    tasks_completed: [],
                    source: 'ltm',
                    key_learnings: (summary.key_learnings || []).slice(0, 3),
                  });
                }
              } catch (_e) {
                // ignore malformed LTM
              }
            }
          } catch (_e) {
            // ignore LTM read errors
          }
        }
      }
    } catch (e) {
      logger.debug('loadContextSync (mtm) error', { error: e.message });
    }

    const legacyPath = path.join(memoryDir, 'learnings.md');
    if (fs.existsSync(legacyPath)) {
      try {
        const legacyContent = fs.readFileSync(legacyPath, 'utf8');
        const limit = maxChars.legacy;
        result.legacy_summary =
          typeof limit === 'number' && legacyContent.length > limit
            ? '...' + legacyContent.slice(-limit)
            : legacyContent;
      } catch (_e) {
        // ignore legacy read errors
      }
    }

    return result;
  }

  async loadContext(options = {}) {
    return this.loadContextSync(options);
  }

  /**
   * Semantic search across all memory sources
   *
   * Routes to LanceDB for vector similarity search.
   * Falls back to keyword search if LanceDB unavailable.
   *
   * @param {string} query - Natural language query
   * @param {Object} options - Search options
   * @param {number} [options.limit=5] - Maximum results
   * @param {number} [options.threshold] - Similarity threshold (0-1); default from memory-constants
   * @returns {Promise<Array>} Ranked results with sources
   */
  async search(query, options = {}) {
    const { SEMANTIC_SEARCH_DEFAULT_THRESHOLD } = require('./memory-constants.cjs');
    const { limit = 5, threshold = SEMANTIC_SEARCH_DEFAULT_THRESHOLD, filters } = options;
    const metadataFilters = {};
    if (options.contextType) {
      metadataFilters.type = options.contextType;
    }
    if (options.category) {
      metadataFilters.category = options.category;
    }
    if (options.area) {
      metadataFilters.area = options.area;
    }
    const hasMetadataFilters = Object.keys(metadataFilters).length > 0;
    let effectiveFilters = filters;
    if (hasMetadataFilters) {
      if (!filters) {
        effectiveFilters = metadataFilters;
      } else if (typeof filters === 'string') {
        const clauses = [];
        for (const [key, value] of Object.entries(metadataFilters)) {
          const k = String(key).replace(/'/g, "''");
          const v = String(value).replace(/'/g, "''");
          clauses.push(`metadata LIKE '%"${k}":"${v}"%'`);
        }
        if (clauses.length > 0) {
          effectiveFilters = `${filters} AND ${clauses.join(' AND ')}`;
        }
      } else if (typeof filters === 'object') {
        effectiveFilters = { ...filters, ...metadataFilters };
      }
    }

    try {
      // Try LanceDB semantic search
      const vectorStore = await this._getVectorStore();

      if (!vectorStore) {
        throw new Error('LanceDB unavailable - falling back to keyword search');
      }

      const results = await vectorStore.search(query, {
        limit,
        filters: effectiveFilters,
      });

      // Filter by threshold logic if needed (LanceDB returns similarity 0-1 from our client wrapper)
      const validResults = results.filter(r => r.similarity >= threshold);

      // Format results with source metadata
      return validResults.map(result => ({
        content: result.content,
        metadata: result.metadata,
        similarity: result.similarity,
        source: 'lancedb',
      }));
    } catch (error) {
      this._logLancedbEvent('semantic_fallback', {
        message: error?.message || String(error),
      });
      if (!this._semanticFallbackWarned) {
        logger.warn('Semantic search unavailable; falling back to keyword search', {
          error: error?.message || String(error),
        });
        this._semanticFallbackWarned = true;
      }
      // Fallback: lightweight keyword search over key memory artifacts.
      return await this._keywordSearch(query, { limit });
    }
  }

  /**
   * Get ripgrep binary path from @vscode/ripgrep npm package.
   * @private
   * @returns {string|null} Path to ripgrep binary or null if unavailable
   */
  _getRipgrepPath() {
    try {
      const { rgPath } = require('@vscode/ripgrep');
      return rgPath;
    } catch {
      // Fallback to bundled binary if npm package not available
      const bundledPath = path.join(
        process.cwd(),
        'bin',
        process.platform === 'win32' ? 'rg.exe' : 'rg'
      );
      if (fs.existsSync(bundledPath)) {
        return bundledPath;
      }
      return null;
    }
  }

  /**
   * Get ast-grep binary path from @ast-grep/cli npm package.
   * @private
   * @returns {string|null} Path to ast-grep binary or null if unavailable
   */
  _getAstGrepPath() {
    try {
      const astGrepPkgPath = require.resolve('@ast-grep/cli');
      const binDir = path.join(path.dirname(astGrepPkgPath), '../.bin');
      const binName = process.platform === 'win32' ? 'ast-grep.cmd' : 'ast-grep';
      const binPath = path.join(binDir, binName);
      if (fs.existsSync(binPath)) {
        return binPath;
      }
      // Try without .cmd extension on Windows
      if (process.platform === 'win32') {
        const altPath = path.join(binDir, 'ast-grep');
        if (fs.existsSync(altPath)) {
          return altPath;
        }
      }
    } catch {
      // Package not installed, try global or bundled
    }
    // Fallback to global installation check
    return 'ast-grep';
  }

  /**
   * Check if a binary is available by running --version.
   * @private
   * @param {string} binPath - Path to binary
   * @returns {Promise<boolean>}
   */
  async _checkBinaryAvailable(binPath) {
    return new Promise(resolve => {
      const proc = spawn(binPath, ['--version'], {
        stdio: ['ignore', 'pipe', 'pipe'],
      });
      proc.on('error', () => resolve(false));
      proc.on('close', code => resolve(code === 0));
      setTimeout(() => {
        proc.kill();
        resolve(false);
      }, 5000);
    });
  }

  /**
   * Use ripgrep to search memory files.
   * @private
   * @param {string} query - Search query
   * @param {string[]} files - Relative file paths to search
   * @param {number} limit - Max results
   * @returns {Promise<Array>}
   */
  async _searchWithRipgrep(query, files, limit) {
    const rgPath = this._getRipgrepPath();
    if (!rgPath) return [];

    const available = await this._checkBinaryAvailable(rgPath);
    if (!available) return [];

    const memoryDir = this.config.memoryDir;
    const candidates = [];

    // Build ripgrep command: search query in specific files
    const args = [
      '-i', // case-insensitive
      '-n', // line numbers
      '-C',
      '2', // context lines
      '--', // end of options
      query,
    ];

    // Add file paths (absolute)
    for (const rel of files) {
      const abs = path.join(memoryDir, rel);
      if (fs.existsSync(abs)) {
        args.push(abs);
      }
    }

    if (args.length === 5) return []; // No files to search

    return new Promise(resolve => {
      const proc = spawn(rgPath, args, {
        cwd: memoryDir,
        stdio: ['ignore', 'pipe', 'pipe'],
      });

      let stdout = '';
      proc.stdout.on('data', data => {
        stdout += data.toString();
      });

      proc.on('close', code => {
        // ripgrep returns 1 when no matches found (not an error)
        if (code !== 0 && code !== 1) {
          resolve([]);
          return;
        }

        // Parse ripgrep output: "file:line:context"
        const lines = stdout.split('\n').filter(l => l.trim());
        for (const line of lines.slice(0, limit * 3)) {
          // Format: "path/to/file:123:  context line"
          const match = line.match(/^([^:]+):(\d+):(.*)$/);
          if (match) {
            const [, filePath, , content] = match;
            const rel = path.relative(memoryDir, filePath).replace(/\\/g, '/');
            candidates.push({
              content: content.trim(),
              metadata: { path: rel },
              similarity: null,
              source: 'ripgrep',
            });
          }
        }

        resolve(candidates.slice(0, limit));
      });

      proc.on('error', () => resolve([]));
    });
  }

  /**
   * Keyword search fallback for when semantic search is unavailable.
   *
   * Enhanced to use ripgrep and ast-grep when available for faster searches.
   * Falls back to bounded file reads if tools unavailable.
   *
   * @private
   * @param {string} query
   * @param {object} options
   * @param {number} options.limit
   * @returns {Promise<Array>}
   */
  async _keywordSearch(query, options = {}) {
    const limit = typeof options.limit === 'number' ? options.limit : 5;
    const q = String(query || '')
      .trim()
      .toLowerCase();
    if (!q) return [];

    // Keep file set explicit to avoid scanning large directories.
    const files = [
      'learnings.md',
      'decisions.md',
      'issues.md',
      'active_context.md',
      'gotchas.json',
      'patterns.json',
      'codebase_map.json',
    ];

    // Include some recent sessions and MTM entries (bounded).
    for (const dir of ['mtm']) {
      const absDir = path.join(this.config.memoryDir, dir);
      try {
        if (!fs.existsSync(absDir)) continue;
        const names = fs
          .readdirSync(absDir)
          .filter(n => n.endsWith('.json'))
          .sort()
          .slice(-10);
        for (const n of names) files.push(path.join(dir, n));
      } catch {
        // ignore
      }
    }

    // Try ripgrep first (fastest for text search)
    const ripgrepResults = await this._searchWithRipgrep(q, files, limit);
    if (ripgrepResults.length > 0) {
      return ripgrepResults;
    }

    // Fallback to file-read approach (original implementation)
    const candidates = [];
    const MAX_BYTES = 80_000;

    for (const rel of files) {
      const abs = path.join(this.config.memoryDir, rel);
      try {
        if (!fs.existsSync(abs)) continue;
        const stat = fs.statSync(abs);
        const start = stat.size > MAX_BYTES ? stat.size - MAX_BYTES : 0;
        const fd = fs.openSync(abs, 'r');
        try {
          const buf = Buffer.alloc(stat.size - start);
          fs.readSync(fd, buf, 0, buf.length, start);
          const text = buf.toString('utf8');
          const lower = text.toLowerCase();
          const idx = lower.indexOf(q);
          if (idx === -1) continue;

          const snippetStart = Math.max(0, idx - 100);
          const snippetEnd = Math.min(text.length, idx + q.length + 300);
          const snippet = text.slice(snippetStart, snippetEnd).trim();

          candidates.push({
            content: snippet,
            metadata: { path: rel },
            similarity: null,
            source: 'keyword',
          });
        } finally {
          fs.closeSync(fd);
        }
      } catch {
        // ignore unreadable file
      }
    }

    return candidates.slice(0, limit);
  }

  /**
   * Find entities by type with optional filters
   *
   * Routes to SQLite for structured entity queries.
   *
   * @param {string} type - Entity type (agent, task, skill, concept, file, pattern, decision, issue)
   * @param {Object} filters - Query filters
   * @param {number} filters.limit - Maximum results
   * @param {number} filters.quality_score - Minimum quality score (0-1)
   * @param {string} filters.source_file - Source file filter
   * @param {string} filters.created_after - ISO 8601 timestamp
   * @returns {Promise<Array>} Array of entities matching criteria
   *
   * @example
   * const concepts = await memory.findEntities('concept', {
   *   quality_score: 0.8,
   *   limit: 10
   * });
   */
  async findEntities(type, filters = {}) {
    const entityQuery = this._getEntityQuery();
    if (!entityQuery) return [];
    return await entityQuery.findByType(type, filters);
  }

  /**
   * Find related entities with graph traversal
   *
   * Routes to SQLite for relationship queries.
   *
   * @param {string} id - Entity ID
   * @param {Object} options - Query options
   * @param {string} options.relationshipType - Filter by relationship type
   * @param {number} options.depth - Traversal depth (default: 1)
   * @returns {Promise<Array>} Array of {entity, relationship_type, weight}
   *
   * @example
   * const related = await memory.getRelated('task-123', {
   *   relationshipType: 'blocks',
   *   depth: 2
   * });
   */
  async getRelated(id, options = {}) {
    const entityQuery = this._getEntityQuery();
    if (!entityQuery) return [];
    return await entityQuery.findRelated(id, options);
  }

  /**
   * Read file contents (backward compatibility)
   *
   * Routes to file system for direct file access.
   * Preserves existing file-based memory reads.
   *
   * @param {string} relativePath - File path relative to memoryDir
   * @returns {Promise<string>} File contents
   *
   * @example
   * const content = await memory.readFile('learnings.md');
   */
  async readFile(relativePath) {
    const filePath = path.join(this.config.memoryDir, relativePath);
    return await fsPromises.readFile(filePath, 'utf8');
  }

  /**
   * Close connections (cleanup)
   */
  close() {
    if (this.entityQuery) {
      this.entityQuery.close();
      this.entityQuery = null;
    }
    if (this.vectorStore && typeof this.vectorStore.close === 'function') {
      if (typeof this.vectorStore.isShared === 'function' && this.vectorStore.isShared()) {
        this.vectorStore = null;
        return;
      }
      try {
        const result = this.vectorStore.close();
        if (result && typeof result.then === 'function') {
          result.catch(() => {});
        }
      } catch (_e) {
        // best-effort
      }
    }
    this.vectorStore = null;
  }

 * @class EntityQuery
 */
class EntityQuery {
  /**
   * Create EntityQuery instance
   * @param {DatabaseSync|string} dbOrPath - Database instance or path to SQLite database
   */
  constructor(dbOrPath) {
    if (typeof dbOrPath === 'string') {
      // Open database from path
      const projectRoot = path.resolve(__dirname, '../../../');
      let dbPath;
      if (dbOrPath === ':memory:') {
        dbPath = dbOrPath;
      } else if (path.isAbsolute(dbOrPath)) {
        // Already absolute - use as-is
        dbPath = dbOrPath;
      } else {
        // Relative path - join with project root
        dbPath = path.join(projectRoot, dbOrPath);
      }
      this.db = new DatabaseSync(dbPath);
      this.db.exec('PRAGMA foreign_keys = ON');
      this.db.exec('PRAGMA busy_timeout = 5000');
      this.ownDb = true; // Close on cleanup
    } else {
      // Use provided database instance
      this.db = dbOrPath;
      this.ownDb = false; // Don't close (caller manages)
    }

    // Validate schema early to avoid runtime crashes like "no such table: entities".
    this.validateSchema();
  }

  /**
   * Validate required SQLite tables exist.
   *
   * @throws {Error} If schema is missing
   */
  validateSchema() {
    const requiredTables = ['entities', 'entity_relationships'];
    const placeholders = requiredTables.map(() => '?').join(', ');
    const rows = this.db
      .prepare(`SELECT name FROM sqlite_master WHERE type='table' AND name IN (${placeholders})`)
      .all(...requiredTables);
    const found = new Set(rows.map(r => r.name));
    const missing = requiredTables.filter(t => !found.has(t));

    if (missing.length > 0) {
      const hint =
        'Memory DB not initialized. Run `pnpm run memory:init` (or `node .claude/tools/cli/init-memory-db.cjs`).';
      throw new Error(`${hint} Missing tables: ${missing.join(', ')}`);
    }
  }

  /**
   * Find entity by ID
   *
   * @param {string} id - Entity ID
   * @param {Object} options - Query options
   * @param {boolean} options.includeRelationships - Include relationships in result
   * @returns {Promise<Object|null>} Entity with optional relationships, or null if not found
   */
  async findById(id, options = {}) {
    const { includeRelationships = false } = options;

    // Query entity
    const stmt = this.db.prepare(`
      SELECT * FROM entities WHERE id = ?
    `);
    const entity = stmt.get(id);

    if (!entity) {
      return null;
    }

    // Include relationships if requested
    if (includeRelationships) {
      entity.relationships = await this._getEntityRelationships(id);
    }

    return entity;
  }

  /**
   * Find entities by type with optional filters
   *
   * @param {string} type - Entity type (agent, task, skill, concept, file, pattern, decision, issue)
   * @param {Object} filters - Query filters
   * @param {number} filters.limit - Maximum results
   * @param {number} filters.quality_score - Minimum quality score (0-1)
   * @param {string} filters.source_file - Source file filter
   * @param {string} filters.created_after - ISO 8601 timestamp (find entities created after this date)
   * @returns {Promise<Array>} Array of entities matching criteria
   */
  async findByType(type, filters = {}) {
    const { limit, quality_score, source_file, created_after } = filters;

    // Build WHERE clause dynamically
    const conditions = ['type = ?'];
    const params = [type];

    if (quality_score !== undefined) {
      conditions.push('quality_score >= ?');
      params.push(quality_score);
    }

    if (source_file !== undefined) {
      conditions.push('source_file = ?');
      params.push(source_file);
    }

    if (created_after !== undefined) {
      conditions.push('created_at > ?');
      params.push(created_after);
    }

    // Build query
    let query = `
      SELECT * FROM entities
      WHERE ${conditions.join(' AND ')}
      ORDER BY quality_score DESC, created_at DESC
    `;

    if (limit !== undefined) {
      const limitNum = Number.isFinite(Number(limit)) ? Math.max(0, parseInt(limit, 10)) : 0;
      query += ` LIMIT ${limitNum}`;
    }

    const stmt = this.db.prepare(query);
    const entities = stmt.all(...params);

    return entities;
  }

  /**
   * Find related entities with depth traversal
   *
   * @param {string} id - Entity ID
   * @param {Object} options - Query options
   * @param {string} options.relationshipType - Filter by relationship type (e.g., 'assigned_to')
   * @param {number} options.depth - Traversal depth (default: 1)
   * @returns {Promise<Array>} Array of {entity, relationship_type, weight} objects
   */
  async findRelated(id, options = {}) {
    const { relationshipType, depth: rawDepth = 1 } = options;
    const depthNum = parseInt(rawDepth, 10);
    const depth = Number.isFinite(depthNum) && depthNum >= 1 ? depthNum : 1;

    // Build query based on whether we have a relationship type filter
    // Search BOTH outgoing (from_entity_id = id) AND incoming (to_entity_id = id)
    let query;
    let params;

    if (relationshipType) {
      // Filtered query with type filter
      query = `
        WITH RECURSIVE related AS (
          -- Base case: OUTGOING relationships (from_entity_id = id)
          SELECT
            r.to_entity_id AS entity_id,
            r.relationship_type AS rel_type,
            r.weight AS rel_weight,
            1 AS depth,
            'outgoing' AS direction
          FROM entity_relationships r
          WHERE r.from_entity_id = ?
            AND r.relationship_type = ?

          UNION

          -- Base case: INCOMING relationships (to_entity_id = id)
          SELECT
            r.from_entity_id AS entity_id,
            r.relationship_type AS rel_type,
            r.weight AS rel_weight,
            1 AS depth,
            'incoming' AS direction
          FROM entity_relationships r
          WHERE r.to_entity_id = ?
            AND r.relationship_type = ?

          UNION

          -- Recursive case: traverse from found entities
          SELECT
            r.to_entity_id,
            r.relationship_type,
            r.weight,
            related.depth + 1,
            'outgoing'
          FROM entity_relationships r
          JOIN related ON r.from_entity_id = related.entity_id
          WHERE related.depth < ${depth}
            AND r.relationship_type = ?
        )
        SELECT DISTINCT
          e.*,
          related.rel_type AS relationship_type,
          related.rel_weight AS weight
        FROM related
        JOIN entities e ON e.id = related.entity_id
        ORDER BY related.depth ASC, e.quality_score DESC
      `;
      // Bind parameters: id (outgoing), relationshipType (outgoing), id (incoming), relationshipType (incoming), relationshipType (recursive)
      params = [id, relationshipType, id, relationshipType, relationshipType];
    } else {
      // Unfiltered query
      query = `
        WITH RECURSIVE related AS (
          -- Base case: OUTGOING relationships
          SELECT
            r.to_entity_id AS entity_id,
            r.relationship_type AS rel_type,
            r.weight AS rel_weight,
            1 AS depth
          FROM entity_relationships r
          WHERE r.from_entity_id = ?

          UNION

          -- Base case: INCOMING relationships
          SELECT
            r.from_entity_id AS entity_id,
            r.relationship_type AS rel_type,
            r.weight AS rel_weight,
            1 AS depth
          FROM entity_relationships r
          WHERE r.to_entity_id = ?

          UNION

          -- Recursive case: traverse relationships
          SELECT
            r.to_entity_id,
            r.relationship_type,
            r.weight,
            related.depth + 1
          FROM entity_relationships r
          JOIN related ON r.from_entity_id = related.entity_id
          WHERE related.depth < ${depth}
        )
        SELECT DISTINCT
          e.*,
          related.rel_type AS relationship_type,
          related.rel_weight AS weight
        FROM related
        JOIN entities e ON e.id = related.entity_id
        ORDER BY related.depth ASC, e.quality_score DESC
      `;
      params = [id, id];
    }

    const stmt = this.db.prepare(query);
    const rows = stmt.all(...params);

    // Format results: {entity, relationship_type, weight}
    const results = rows.map(row => {
      const { relationship_type, weight, ...entityFields } = row;
      return {
        entity: entityFields,
        relationship_type,
        weight,
      };
    });

    return results;
  }

  /**
   * Find shortest relationship path between two entities using BFS
   *
   * @param {string} fromId - Starting entity ID
   * @param {string} toId - Target entity ID
   * @param {Object} options - Query options
   * @param {number} options.maxDepth - Maximum path depth (default: 5)
   * @returns {Promise<Array>} Array of {from_entity, to_entity, relationship_type} hops, or empty if no path
   */
  async getRelationshipPath(fromId, toId, options = {}) {
    const { maxDepth = 5 } = options;

    // Early return for same entity
    if (fromId === toId) {
      return [];
    }

    // BFS implementation using queue
    const queue = [{ entityId: fromId, path: [] }];
    const visited = new Set([fromId]);

    while (queue.length > 0) {
      const { entityId, path } = queue.shift();

      // Check if we've reached max depth
      if (path.length >= maxDepth) {
        continue;
      }

      // Get direct relationships from current entity
      const stmt = this.db.prepare(`
        SELECT
          r.from_entity_id,
          r.to_entity_id,
          r.relationship_type,
          r.weight,
          e_from.id AS from_id,
          e_from.type AS from_type,
          e_from.name AS from_name,
          e_to.id AS to_id,
          e_to.type AS to_type,
          e_to.name AS to_name
        FROM entity_relationships r
        JOIN entities e_from ON e_from.id = r.from_entity_id
        JOIN entities e_to ON e_to.id = r.to_entity_id
        WHERE r.from_entity_id = ?
      `);
      const relationships = stmt.all(entityId);

      for (const rel of relationships) {
        const nextId = rel.to_entity_id;

        // Found target - return path
        if (nextId === toId) {
          return [
            ...path,
            {
              from_entity: {
                id: rel.from_id,
                type: rel.from_type,
                name: rel.from_name,
              },
              to_entity: {
                id: rel.to_id,
                type: rel.to_type,
                name: rel.to_name,
              },
              relationship_type: rel.relationship_type,
              weight: rel.weight,
            },
          ];
        }

        // Add to queue if not visited
        if (!visited.has(nextId)) {
          visited.add(nextId);
          queue.push({
            entityId: nextId,
            path: [
              ...path,
              {
                from_entity: {
                  id: rel.from_id,
                  type: rel.from_type,
                  name: rel.from_name,
                },
                to_entity: {
                  id: rel.to_id,
                  type: rel.to_type,
                  name: rel.to_name,
                },
                relationship_type: rel.relationship_type,
                weight: rel.weight,
              },
            ],
          });
        }
      }
    }

    // No path found
    return [];
  }

  /**
   * Get relationships for an entity (internal helper)
   * Includes both OUTGOING (from_entity_id = entityId) and INCOMING (to_entity_id = entityId)
   * @private
   */
  async _getEntityRelationships(entityId) {
    // Query both outgoing and incoming relationships
    const stmt = this.db.prepare(`
      SELECT
        r.relationship_type AS type,
        r.weight,
        e.id AS to_entity_id,
        e.type AS to_entity_type,
        e.name AS to_entity_name
      FROM entity_relationships r
      JOIN entities e ON e.id = r.to_entity_id
      WHERE r.from_entity_id = ?

      UNION

      SELECT
        r.relationship_type AS type,
        r.weight,
        e.id AS to_entity_id,
        e.type AS to_entity_type,
        e.name AS to_entity_name
      FROM entity_relationships r
      JOIN entities e ON e.id = r.from_entity_id
      WHERE r.to_entity_id = ?

      ORDER BY weight DESC
    `);
    const rows = stmt.all(entityId, entityId);

    // Format: {to_entity: {id, type, name}, type, weight}
    const relationships = rows.map(row => ({
      to_entity: {
        id: row.to_entity_id,
        type: row.to_entity_type,
        name: row.to_entity_name,
      },
      type: row.type,
      weight: row.weight,
    }));

    return relationships;
  }

  /**
   * Close database connection (if owned by this instance)
   */
  close() {
    if (this.ownDb && this.db) {
      this.db.close();
    }
  }

function stripCodeFences(text) {
