function isMockClient(modelClient) {
  if (!modelClient) return true;
  if (typeof modelClient.isMockMode === 'function') {
    return modelClient.isMockMode();
  }
  return false;
}

function fallbackDecisionFromSimilarity(results) {
  if (!Array.isArray(results) || results.length === 0) {
    return { decision: 'create', reason: 'No similar memories found' };
  }

  const top = results[0];
  const score = typeof top.similarity === 'number' ? top.similarity : null;

  if (score !== null) {
    if (score >= 0.88) {
      return { decision: 'update', reason: `High similarity (${score.toFixed(2)})` };
    }
    if (score >= 0.78) {
      return { decision: 'merge', reason: `Moderate similarity (${score.toFixed(2)})` };
    }
  }

  return { decision: 'create', reason: 'Similarity below merge threshold' };
}

function formatExistingMemories(results) {
  if (!Array.isArray(results) || results.length === 0) {
    return 'None';
  }

  return results
    .map((result, index) => {
      const content = result && result.content ? String(result.content) : '';
      const snippet = content.length > 400 ? `${content.slice(0, 400)}...` : content;
      const meta = result && result.metadata ? JSON.stringify(result.metadata) : '';
      const metaBlock = meta ? ` (meta: ${meta})` : '';
      return `${index + 1}. ${snippet}${metaBlock}`;
    })
    .join('\n');
}

function toInt(value, fallback) {
  const n = Number.parseInt(String(value), 10);
  return Number.isFinite(n) ? n : fallback;
}

function parseBoolEnv(value, fallback) {
  if (value === undefined || value === null || value === '') return fallback;
  const v = String(value).trim().toLowerCase();
  if (v === 'false' || v === '0' || v === 'off' || v === 'no') return false;
  if (v === 'true' || v === '1' || v === 'on' || v === 'yes') return true;
  return fallback;
}

function resolveColdDir(projectRoot = PROJECT_ROOT) {
  const configured = process.env.MEMORY_COLD_DIR || '.claude/context/memory/cold';
  const abs = path.resolve(projectRoot, configured);

  const validation = validatePathWithinProject(abs, projectRoot);
  if (!validation.safe) {
    throw new Error(`Invalid MEMORY_COLD_DIR: ${validation.reason}`);
  }

  return abs;
}

function getRetentionOptions(projectRoot = PROJECT_ROOT) {
  const maxSummaries = toInt(process.env.MEMORY_LTM_MAX_SUMMARIES, 50);
  const coldEnable = parseBoolEnv(process.env.MEMORY_COLD_ENABLE, true);
  const archiveAfterDays =
    process.env.MEMORY_COLD_ARCHIVE_AFTER_DAYS !== undefined &&
    process.env.MEMORY_COLD_ARCHIVE_AFTER_DAYS !== null &&
    String(process.env.MEMORY_COLD_ARCHIVE_AFTER_DAYS).trim() !== ''
      ? toInt(process.env.MEMORY_COLD_ARCHIVE_AFTER_DAYS, undefined)
      : undefined;

  return {
    maxSummaries,
    coldEnable,
    archiveAfterDays,
    coldDir: resolveColdDir(projectRoot),
  };
}

function normalizeCategory(category) {
  if (!category) return null;
  const key = String(category).trim().toLowerCase();
  return CATEGORY_DIRS[key] ? key : null;
}

function buildMemoryMarkdown(candidate) {
  const abstract = candidate.abstract ? String(candidate.abstract).trim() : '';
  const overview = candidate.overview ? String(candidate.overview).trim() : '';
  const content = candidate.content ? String(candidate.content).trim() : '';

  return [
    `# ${abstract || 'Memory'}`,
    '',
    '## Overview',
    overview || '_No overview provided._',
    '',
    '## Content',
    content || '_No content provided._',
    '',
  ].join('\n');
}

function getProfileFilePath(projectRoot) {
  return path.join(projectRoot, '.claude', 'context', 'memory', 'memories', 'profile.md');
}

function buildMemoryPath(projectRoot, category) {
  const safeCategory = CATEGORY_DIRS[category];
  if (!safeCategory) {
    throw new Error(`Unknown memory category: ${category}`);
  }

  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const id = crypto.randomUUID();
  const fileName = `${timestamp}-${id}.md`;
  const baseDir = path.join(projectRoot, '.claude', 'context', 'memory', 'memories', safeCategory);

  return path.join(baseDir, fileName);
}

function appendToProfileFile(candidate, projectRoot) {
  const profilePath = getProfileFilePath(projectRoot);
  const profileDir = path.dirname(profilePath);
  fs.mkdirSync(profileDir, { recursive: true });

  const existing = fs.existsSync(profilePath) ? fs.readFileSync(profilePath, 'utf8') : '';
  const block = buildMemoryMarkdown(candidate).trimEnd();
  const next = existing ? `${existing.trimEnd()}\n\n---\n\n${block}\n` : `${block}\n`;
  atomicWriteSync(profilePath, next, 'utf8');
  return profilePath;
}

function writeMemoryFile(candidate, projectRoot) {
  const category = normalizeCategory(candidate.category);
  if (!category) {
    throw new Error(`Invalid category: ${candidate.category || 'unknown'}`);
  }

  const filePath = buildMemoryPath(projectRoot, category);
  const content = buildMemoryMarkdown(candidate);
  atomicWriteSync(filePath, content, 'utf8');
  return filePath;
}

function overwriteMemoryFile(candidate, filePath, projectRoot) {
  const validation = validatePathWithinProject(filePath, projectRoot);
  if (!validation.safe) {
    throw new Error(`Invalid memory path: ${validation.reason}`);
  }
  const content = buildMemoryMarkdown(candidate);
  atomicWriteSync(validation.resolvedPath, content, 'utf8');
  return validation.resolvedPath;
}

function resolveTargetFilePath(decisionResult, projectRoot) {
  const similar = Array.isArray(decisionResult?.similarMemories)
    ? decisionResult.similarMemories[0]
    : null;
  const candidatePath = similar?.metadata?.filePath || similar?.id;
  if (!candidatePath) return null;
  const validation = validatePathWithinProject(candidatePath, projectRoot);
  if (!validation.safe) return null;
  return validation.resolvedPath;
}

async function indexMemory(candidate, filePath, projectRoot) {
  const category = normalizeCategory(candidate.category);
  if (!category) return;
  const text = buildMemoryMarkdown(candidate);
  const store = MemoryVectorStore.getSharedStore({
    persistDirectory: path.join(projectRoot, '.claude', 'data', 'lancedb'),
    collectionName: process.env.LANCEDB_TABLE || 'agent_memory',
  });

  let docId = filePath;
  if (category === 'profile') {
    docId = getProfileFilePath(projectRoot);
    try {
      await store.deleteByMetadata('category', 'profile');
    } catch (error) {
      logger.warn('Failed to prune profile metadata before indexing', {
        error: error.message,
      });
    }
  }

  await store.upsertDocuments([
    {
      id: docId,
      text,
      metadata: {
        type: 'memory',
        category,
        source: 'memory_extraction',
        filePath,
        abstract: candidate.abstract ? String(candidate.abstract).trim() : '',
        overview: candidate.overview ? String(candidate.overview).trim().slice(0, 2000) : '',
      },
    },
  ]);
}

function slugify(value) {
  return String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function ensureDb(projectRoot) {
  const root = projectRoot || PROJECT_ROOT;
  const dbPath = path.join(root, '.claude', 'data', 'memory.db');
  const dbDir = path.dirname(dbPath);
  if (!fs.existsSync(dbDir)) {
    fs.mkdirSync(dbDir, { recursive: true });
  }
  return initializeDatabase(new DatabaseSync(dbPath));
}

function insertEntity(db, entity) {
  db.prepare(
    `
      INSERT OR IGNORE INTO entities (
        id,
        type,
        name,
        content,
        source_file
      )
      VALUES (?, ?, ?, ?, ?)
    `
  ).run(entity.id, entity.type, entity.name, entity.content || null, entity.source_file || null);
}

function insertRelationship(db, fromId, toId, metadata) {
  const metaJson = metadata ? JSON.stringify(metadata) : null;
  db.prepare(
    `
      INSERT INTO entity_relationships (
        from_entity_id,
        to_entity_id,
        relationship_type,
        metadata
      )
      SELECT ?, ?, 'references', ?
      WHERE NOT EXISTS (
        SELECT 1 FROM entity_relationships
        WHERE from_entity_id = ? AND to_entity_id = ? AND relationship_type = 'references'
      )
    `
  ).run(fromId, toId, metaJson, fromId, toId);
}

function linkMemoryToTools(memoryId, toolNames, projectRoot) {
  if (!memoryId || !Array.isArray(toolNames) || toolNames.length === 0) {
    return { linked: 0, skipped: 0 };
  }

  const db = ensureDb(projectRoot);
  let linked = 0;
  let skipped = 0;

  try {
    insertEntity(db, {
      id: memoryId,
      type: 'memory',
      name: memoryId,
      source_file: memoryId,
    });

    for (const toolName of toolNames) {
      if (!toolName) {
        skipped += 1;
        continue;
      }
      const slug = slugify(toolName);
      if (!slug) {
        skipped += 1;
        continue;
      }
      const skillId = `skill:${slug}`;
      insertEntity(db, {
        id: skillId,
        type: 'skill',
        name: String(toolName),
      });
      insertRelationship(db, memoryId, skillId, {
        source: 'memory_extraction',
      });
      insertRelationship(db, skillId, memoryId, {
        source: 'memory_extraction',
        direction: 'reverse',
      });
      linked += 1;
    }
  } catch (error) {
    logger.warn('Failed to link memory to tools', {
      error: error.message,
      memoryId,
    });
  } finally {
    db.close();
  }

  return { linked, skipped };
}

function getMemoriesForTool(toolName, projectRoot) {
  if (!toolName) {
    return [];
  }
  const slug = slugify(toolName);
  if (!slug) {
    return [];
  }

  const db = ensureDb(projectRoot);
  try {
    const skillId = `skill:${slug}`;
    const rows = db
      .prepare(
        `
          SELECT to_entity_id AS memory_id
          FROM entity_relationships
          WHERE from_entity_id = ? AND relationship_type = 'references'
        `
      )
      .all(skillId);
    return rows.map(row => row.memory_id).filter(Boolean);
  } finally {
    db.close();
  }
}

function cleanupOrphanedRelationships(projectRoot) {
  const db = ensureDb(projectRoot);
  try {
    const countRow = db
      .prepare(
        `
        SELECT COUNT(*) AS count
        FROM entity_relationships
        WHERE from_entity_id NOT IN (SELECT id FROM entities)
           OR to_entity_id NOT IN (SELECT id FROM entities)
      `
      )
      .get();
    const count = countRow?.count || 0;

    if (count > 0) {
      db.exec(
        `
        DELETE FROM entity_relationships
        WHERE from_entity_id NOT IN (SELECT id FROM entities)
           OR to_entity_id NOT IN (SELECT id FROM entities)
      `
      );
    }

    return { deleted: count };
  } catch (error) {
    logger.warn('Failed to cleanup orphaned relationships', { error: error.message });
    return { deleted: 0, error: error.message };
  } finally {
    db.close();
  }
}

async function main() {
  const query = process.argv.slice(2).join(' ').trim();

  if (!query) {
    console.error('Usage: node .claude/lib/memory/memory-search.cjs "search query"');
    process.exit(1);
  }

  try {
    const results = await memoryManager.searchMemory(query, {
      limit: 10,
      threshold: SEMANTIC_SEARCH_DEFAULT_THRESHOLD,
    });

    console.log(`Found ${results.length} results for: "${query}"\n`);

    for (const result of results) {
      const src = result?.source || 'unknown';
      const sim = typeof result?.similarity === 'number' ? result.similarity : null;
      const prefix = sim === null ? `[${src}]` : `[${src}] Similarity: ${(sim * 100).toFixed(1)}%`;

      console.log(prefix);
      if (result?.content) {
        console.log(String(result.content).slice(0, 200) + '...\n');
      } else {
        console.log('(no content)\n');
      }
    }
  } catch (err) {
    console.error('Search failed:', err.message);
    process.exit(1);
  }
}

function validateProjectRoot(projectRoot) {
  if (projectRoot !== PROJECT_ROOT) {
    const validation = validatePathWithinProject(projectRoot, PROJECT_ROOT);
    if (!validation.safe) {
      throw new Error(`Invalid projectRoot: ${validation.reason}`);
    }
  }
}

function getMemoryDir(projectRoot = PROJECT_ROOT) {
  return path.join(projectRoot, '.claude', 'context', 'memory');
}

function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function buildEntryId(entry) {
  if (entry && typeof entry.id === 'string' && entry.id.trim()) {
    return entry.id;
  }
  const text = entry?.text || '';
  const ts = entry?.timestamp || '';
  const category = entry?.category || '';
  const area = entry?.area || '';
  const base = `${text}\n${ts}\n${category}\n${area}`;
  return crypto.createHash('sha1').update(base).digest('hex');
}

function normalizeArea(area) {
  return isValidArea(area) ? area : DEFAULT_AREA;
}

function maybeSyncMemoryJson(filePath, projectRoot = PROJECT_ROOT) {
  if (process.env.MEMORY_AUTO_SYNC === 'off') return;
  if (!filePath) return;

  try {
    const validated = validatePathWithinProject(filePath, projectRoot);
    if (!validated.safe) return;

    const dbPath = path.join(projectRoot, '.claude', 'data', 'memory.db');
    ensureEntityDbInitialized(dbPath);
    syncJsonMemory(filePath, dbPath);

    if (process.env.MEMORY_EMBED_ON_WRITE === 'on') {
      const generatorPath = path.join(
        projectRoot,
        '.claude',
        'tools',
        'cli',
        'generate-embeddings.cjs'
      );
      if (fs.existsSync(generatorPath)) {
        const timeoutMs = Number(process.env.MEMORY_EMBED_ON_WRITE_TIMEOUT_MS || 30000);
        const spawnResult = spawnSync(process.execPath, [generatorPath, '--file', filePath], {
          cwd: projectRoot,
          stdio: 'ignore',
          timeout: timeoutMs,
        });
        if (spawnResult.signal === 'SIGTERM' || spawnResult.status !== 0) {
          logger.warn('Embedding generation may be partial', {
            file: path.basename(filePath),
            status: spawnResult.status,
            signal: spawnResult.signal,
          });
        }
      }
    }
  } catch (err) {
    logger.warn('Memory sync failed', { file: path.basename(filePath), error: err.message });
  }
}

function normalizeMemoryName(name) {
  return String(name || '')
    .trim()
    .replace(/\.md$/i, '')
    .replace(/\s+/g, '_')
    .replace(/[^a-zA-Z0-9_.-]/g, '_')
    .toLowerCase();
}

function getNamedMemoryDir(projectRoot = PROJECT_ROOT) {
  validateProjectRoot(projectRoot);
  const dir = path.join(getMemoryDir(projectRoot), 'named');
  ensureDir(dir);
  return dir;
}

function readMemory(name, projectRoot = PROJECT_ROOT) {
  validateProjectRoot(projectRoot);
  const baseName = normalizeMemoryName(name);
  const filePath = path.join(getNamedMemoryDir(projectRoot), `${baseName}.md`);
  const validation = validatePathWithinProject(filePath, projectRoot);
  if (!validation.safe) {
    throw new Error(`Invalid memory path: ${validation.reason}`);
  }
  if (!fs.existsSync(filePath)) {
    return `Memory '${name}' not found. Use write_memory to create it.`;
  }
  return fs.readFileSync(filePath, 'utf8');
}

function writeMemory(name, content, projectRoot = PROJECT_ROOT) {
  validateProjectRoot(projectRoot);
  const baseName = normalizeMemoryName(name);
  const filePath = path.join(getNamedMemoryDir(projectRoot), `${baseName}.md`);
  const validation = validatePathWithinProject(filePath, projectRoot);
  if (!validation.safe) {
    throw new Error(`Invalid memory path: ${validation.reason}`);
  }
  atomicWriteSync(filePath, String(content || ''), 'utf8');
  return `Memory '${name}' written.`;
}

function listMemories(projectRoot = PROJECT_ROOT) {
  validateProjectRoot(projectRoot);
  const dir = path.join(getMemoryDir(projectRoot), 'named');
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir)
    .filter(file => file.endsWith('.md'))
    .map(file => file.replace(/\.md$/, ''));
}

function deleteMemory(name, projectRoot = PROJECT_ROOT) {
  validateProjectRoot(projectRoot);
  const baseName = normalizeMemoryName(name);
  const filePath = path.join(getNamedMemoryDir(projectRoot), `${baseName}.md`);
  const validation = validatePathWithinProject(filePath, projectRoot);
  if (!validation.safe) {
    throw new Error(`Invalid memory path: ${validation.reason}`);
  }
  if (!fs.existsSync(filePath)) {
    return `Memory '${name}' not found.`;
  }
  fs.unlinkSync(filePath);
  return `Memory '${name}' deleted.`;
}

function loadMemoryArray(filePath) {
  if (!fs.existsSync(filePath)) return [];
  try {
    const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    return Array.isArray(data) ? data : [];
  } catch (err) {
    logger.warn('memory_json_parse_failed', {
      file: filePath,
      error: err?.message || String(err),
    });
    return [];
  }
}

function writeMemoryArray(filePath, data) {
  atomicWriteJSONSync(filePath, Array.isArray(data) ? data : []);
}

function normalizeEntryIds(entries) {
  let changed = false;
  for (const entry of entries) {
    if (!entry || typeof entry !== 'object') continue;
    if (!entry.id) {
      entry.id = buildEntryId(entry);
      changed = true;
    }
  }
  return changed;
}

function deleteMemoryByIds(ids, projectRoot = PROJECT_ROOT) {
  validateProjectRoot(projectRoot);
  const list = Array.isArray(ids) ? ids.filter(Boolean) : [];
  if (list.length === 0) return { deleted: 0, notFound: [] };

  const memoryDir = getMemoryDir(projectRoot);
  const gotchasFile = path.join(memoryDir, 'gotchas.json');
  const patternsFile = path.join(memoryDir, 'patterns.json');

  let deleted = 0;
  const remainingIds = new Set(list);

  const gotchas = loadMemoryArray(gotchasFile);
  const gotchasChanged = normalizeEntryIds(gotchas);
  const keptGotchas = gotchas.filter(entry => {
    const entryId = buildEntryId(entry);
    if (remainingIds.has(entryId)) {
      remainingIds.delete(entryId);
      deleted += 1;
      return false;
    }
    return true;
  });
  if (gotchasChanged || keptGotchas.length !== gotchas.length) {
    writeMemoryArray(gotchasFile, keptGotchas);
  }

  const patterns = loadMemoryArray(patternsFile);
  const patternsChanged = normalizeEntryIds(patterns);
  const keptPatterns = patterns.filter(entry => {
    const entryId = buildEntryId(entry);
    if (remainingIds.has(entryId)) {
      remainingIds.delete(entryId);
      deleted += 1;
      return false;
    }
    return true;
  });
  if (patternsChanged || keptPatterns.length !== patterns.length) {
    writeMemoryArray(patternsFile, keptPatterns);
  }

  return { deleted, notFound: [...remainingIds] };
}

function getCurrentSessionNumber(memoryDir) {
  const sessionsDir = path.join(memoryDir, 'sessions');
  ensureDir(sessionsDir);

  const files = fs
    .readdirSync(sessionsDir)
    .filter(f => f.match(/^session_\d{3}\.json$/))
    .sort();

  if (files.length === 0) return 1;

  const lastFile = files[files.length - 1];
  const match = lastFile.match(/session_(\d{3})\.json/);
  return match ? parseInt(match[1], 10) + 1 : 1;
}

function checkAndArchiveLearnings(projectRoot = PROJECT_ROOT) {
  const memoryDir = getMemoryDir(projectRoot);
  const learningsPath = path.join(memoryDir, 'learnings.md');
  const archiveDir = path.join(memoryDir, 'archive');

  // Ensure archive directory exists
  ensureDir(archiveDir);

  const result = {
    archived: false,
    archivedBytes: 0,
    archivePath: null,
  };

  // Check if learnings.md exists
  if (!fs.existsSync(learningsPath)) {
    return result;
  }

  // Check file size
  const stats = fs.statSync(learningsPath);
  const thresholdBytes = CONFIG.LEARNINGS_ARCHIVE_THRESHOLD_KB * 1024;

  if (stats.size <= thresholdBytes) {
    return result;
  }

  // Read and split content
  const content = fs.readFileSync(learningsPath, 'utf8');
  const lines = content.split('\n');

  // Determine lines to keep vs archive
  const linesToKeep = CONFIG.LEARNINGS_KEEP_LINES;
  if (lines.length <= linesToKeep) {
    return result; // Not enough lines to archive
  }

  const archiveLines = lines.slice(0, -linesToKeep);
  const keepLines = lines.slice(-linesToKeep);

  const archiveContent = archiveLines.join('\n');
  const keepContent = keepLines.join('\n');

  // Create archive filename with YYYY-MM format
  const now = new Date();
  const archiveFilename = `learnings-${now.toISOString().slice(0, 7)}.md`;
  const archivePath = path.join(archiveDir, archiveFilename);

  // Append to archive (may already have content from previous archives this month)
  fs.appendFileSync(archivePath, archiveContent + '\n\n');

  // Write truncated content back to learnings.md
  atomicWriteSync(learningsPath, keepContent);

  result.archived = true;
  result.archivedBytes = archiveContent.length;
  result.archivePath = archivePath;

  if (process.env.MEMORY_DEBUG || process.env.DEBUG_HOOKS) {
    logger.info(`Archived ${result.archivedBytes} bytes`, { archivePath: result.archivePath });
  }

  return result;
}

function _pruneOldSessions(sessionsDir) {
  const files = fs
    .readdirSync(sessionsDir)
    .filter(f => f.match(/^session_\d{3}\.json$/))
    .sort();

  if (files.length > CONFIG.MAX_SESSIONS) {
    const toDelete = files.slice(0, files.length - CONFIG.MAX_SESSIONS);
    for (const file of toDelete) {
      fs.unlinkSync(path.join(sessionsDir, file));
    }
  }
}

function pruneCodebaseMap(projectRoot = PROJECT_ROOT) {
  const memoryDir = getMemoryDir(projectRoot);
  const mapPath = path.join(memoryDir, 'codebase_map.json');

  const result = {
    prunedByTTL: 0,
    prunedBySize: 0,
    totalPruned: 0,
  };

  // Check if codebase_map.json exists
  if (!fs.existsSync(mapPath)) {
    return result;
  }

  // Load the file
  let codebaseMap;
  try {
    codebaseMap = JSON.parse(fs.readFileSync(mapPath, 'utf8'));
  } catch (_e) {
    return result;
  }

  if (!codebaseMap.discovered_files) {
    return result;
  }

  const now = new Date();
  const ttlMs = CONFIG.CODEBASE_MAP_TTL_DAYS * 24 * 60 * 60 * 1000;
  const maxEntries = CONFIG.CODEBASE_MAP_MAX_ENTRIES;

  // First, add last_accessed to any entries missing it (migration)
  for (const [_key, value] of Object.entries(codebaseMap.discovered_files)) {
    if (!value.last_accessed) {
      // Use discovered_at as fallback, or current time
      value.last_accessed = value.discovered_at || now.toISOString();
    }
  }

  // Convert to array for sorting and filtering
  let entries = Object.entries(codebaseMap.discovered_files).map(([path, info]) => ({
    path,
    ...info,
    accessDate: new Date(info.last_accessed),
  }));

  const initialCount = entries.length;

  // Phase 1: Remove entries older than TTL
  const ttlCutoff = new Date(now - ttlMs);
  entries = entries.filter(entry => {
    const keep = entry.accessDate >= ttlCutoff;
    if (!keep) result.prunedByTTL++;
    return keep;
  });

  // Phase 2: If still over max, remove oldest until under limit
  if (entries.length > maxEntries) {
    // Sort by last_accessed ascending (oldest first)
    entries.sort((a, b) => a.accessDate - b.accessDate);

    const toRemove = entries.length - maxEntries;
    result.prunedBySize = toRemove;
    entries = entries.slice(toRemove);
  }

  result.totalPruned = initialCount - entries.length;

  // Rebuild discovered_files object
  const newDiscoveredFiles = {};
  for (const entry of entries) {
    const { path: entryPath, _accessDate, ...info } = entry;
    newDiscoveredFiles[entryPath] = info;
  }

  codebaseMap.discovered_files = newDiscoveredFiles;
  codebaseMap.last_updated = now.toISOString();

  // Write back
  atomicWriteSync(mapPath, JSON.stringify(codebaseMap, null, 2) + '\n');

  if (result.totalPruned > 0) {
    logger.info(`Pruned ${result.totalPruned} codebase_map entries`, {
      prunedByTTL: result.prunedByTTL,
      prunedBySize: result.prunedBySize,
    });
  }

  return result;
}

function recordGotcha(gotcha, projectRoot = PROJECT_ROOT) {
  // CRITICAL-001-MEMORY FIX: Validate projectRoot
  validateProjectRoot(projectRoot);
  const memoryDir = getMemoryDir(projectRoot);
  ensureDir(memoryDir);

  const gotchasFile = path.join(memoryDir, 'gotchas.json');

  let gotchas = [];
  if (fs.existsSync(gotchasFile)) {
    try {
      gotchas = JSON.parse(fs.readFileSync(gotchasFile, 'utf8'));
    } catch (_e) {
      gotchas = [];
    }
  }

  // Check for duplicates (simple text match)
  const isDuplicate = gotchas.some(
    g =>
      g.text.toLowerCase() === gotcha.text?.toLowerCase() ||
      g.text.toLowerCase() === gotcha.toLowerCase?.()
  );

  if (!isDuplicate) {
    const now = new Date().toISOString();
    const area = typeof gotcha === 'object' && gotcha ? normalizeArea(gotcha.area) : DEFAULT_AREA;
    const entry =
      typeof gotcha === 'string'
