      return { type: taskName, success: false, details: `Unknown task: ${taskName}` };
  }
}

function runDailyMaintenance(projectRoot = PROJECT_ROOT) {
  const startTime = Date.now();
  const timestamp = new Date().toISOString();
  const tasks = [];

  // Run daily tasks
  tasks.push(runConsolidation(projectRoot));
  tasks.push(runHealthCheck(projectRoot));
  tasks.push(runMetricsLog(projectRoot));

  // Update status
  const status = readStatus(projectRoot);
  status.lastDaily = timestamp;
  status.lastRun = timestamp;
  status.history.unshift({
    type: 'daily',
    timestamp,
    tasks: tasks.map(t => ({ type: t.type, success: t.success })),
  });
  // Keep only last 30 history entries
  if (status.history.length > HISTORY_LIMIT) {
    status.history = status.history.slice(0, HISTORY_LIMIT);
  }
  writeStatus(status, projectRoot);

  // Get health check result
  const healthCheckTask = tasks.find(t => t.type === 'healthCheck');

  const result = {
    maintenanceType: 'daily',
    timestamp,
    tasks,
    healthCheck: healthCheckTask
      ? {
          healthScore: healthCheckTask.healthScore,
          recommendations: healthCheckTask.recommendations,
        }
      : null,
  };

  try {
    const taskSummaries = tasks.map(t => ({ type: t.type, success: t.success }));
    const failures = taskSummaries.filter(t => t.success === false);
    if (failures.length > 0) {
      eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'memory-scheduler',
        error: `daily_maintenance_failed:${failures.map(f => f.type).join(',')}`,
      });
    } else {
      eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'memory-scheduler',
        output: {
          maintenanceType: result.maintenanceType,
          tasks: taskSummaries,
        },
        duration: Date.now() - startTime,
      });
    }
  } catch (_e) {
    // Best-effort
  }

  return result;
}

function runWeeklyMaintenance(projectRoot = PROJECT_ROOT) {
  const startTime = Date.now();
  const timestamp = new Date().toISOString();
  const tasks = [];

  // Run daily tasks first
  tasks.push(runConsolidation(projectRoot));
  tasks.push(runHealthCheck(projectRoot));
  tasks.push(runMetricsLog(projectRoot));

  // Run weekly tasks
  tasks.push(runSummarization(projectRoot));
  tasks.push(runDeduplication(projectRoot));
  tasks.push(runPruning(projectRoot));
  tasks.push(runArchiveOldLTM(projectRoot));
  tasks.push(runExtraction(projectRoot));
  const weeklyReportResult = runWeeklyReport(projectRoot);
  tasks.push(weeklyReportResult);

  // Update status
  const status = readStatus(projectRoot);
  status.lastWeekly = timestamp;
  status.lastDaily = timestamp;
  status.lastRun = timestamp;
  status.history.unshift({
    type: 'weekly',
    timestamp,
    tasks: tasks.map(t => ({ type: t.type, success: t.success })),
  });
  // Keep only last 30 history entries
  if (status.history.length > HISTORY_LIMIT) {
    status.history = status.history.slice(0, HISTORY_LIMIT);
  }
  writeStatus(status, projectRoot);

  // Get health check result
  const healthCheckTask = tasks.find(t => t.type === 'healthCheck');

  const result = {
    maintenanceType: 'weekly',
    timestamp,
    tasks,
    healthCheck: healthCheckTask
      ? {
          healthScore: healthCheckTask.healthScore,
          recommendations: healthCheckTask.recommendations,
        }
      : null,
    weeklyReport: weeklyReportResult.report,
  };

  try {
    const taskSummaries = tasks.map(t => ({ type: t.type, success: t.success }));
    const failures = taskSummaries.filter(t => t.success === false);
    if (failures.length > 0) {
      eventBus.emit(EventTypes.TOOL_FAILED, {
        type: EventTypes.TOOL_FAILED,
        timestamp: new Date().toISOString(),
        toolName: 'memory-scheduler',
        error: `weekly_maintenance_failed:${failures.map(f => f.type).join(',')}`,
      });
    } else {
      eventBus.emit(EventTypes.TOOL_COMPLETED, {
        type: EventTypes.TOOL_COMPLETED,
        timestamp: new Date().toISOString(),
        toolName: 'memory-scheduler',
        output: {
          maintenanceType: result.maintenanceType,
          tasks: taskSummaries,
        },
        duration: Date.now() - startTime,
      });
    }
  } catch (_e) {
    // Best-effort
  }

  return result;
}

function runMaintenance(type, projectRoot = PROJECT_ROOT) {
  switch (type) {
    case 'daily':
      return runDailyMaintenance(projectRoot);
    case 'weekly':
      return runWeeklyMaintenance(projectRoot);
    default:
      // Run specific task
      const startTime = Date.now();
      const taskResult = runTask(type, projectRoot);

      // Update status
      const status = readStatus(projectRoot);
      status.lastRun = new Date().toISOString();
      status.history.unshift({
        type: 'task',
        taskName: type,
        timestamp: taskResult.timestamp,
        success: taskResult.success,
      });
      if (status.history.length > HISTORY_LIMIT) {
        status.history = status.history.slice(0, HISTORY_LIMIT);
      }
      writeStatus(status, projectRoot);

      const result = {
        maintenanceType: 'task',
        task: type,
        ...taskResult,
      };

      try {
        if (result.success === false) {
          eventBus.emit(EventTypes.TOOL_FAILED, {
            type: EventTypes.TOOL_FAILED,
            timestamp: new Date().toISOString(),
            toolName: 'memory-scheduler',
            error: `maintenance_task_failed:${result.task}`,
          });
        } else {
          eventBus.emit(EventTypes.TOOL_COMPLETED, {
            type: EventTypes.TOOL_COMPLETED,
            timestamp: new Date().toISOString(),
            toolName: 'memory-scheduler',
            output: {
              maintenanceType: result.maintenanceType,
              task: result.task,
              success: result.success,
            },
            duration: Date.now() - startTime,
          });
        }
      } catch (_e) {
        // Best-effort
      }

      return result;
  }
}

function getMaintenanceStatus(projectRoot = PROJECT_ROOT) {
  return readStatus(projectRoot);
}

function isStructuredSummaryEnabled() {
  const value = String(process.env.MEMORY_STRUCTURED_SUMMARY || '').toLowerCase();
  return value === '1' || value === 'true';
}

function isSessionArchiveEnabled() {
  const value = String(process.env.MEMORY_SESSION_ARCHIVE || '').toLowerCase();
  return value === '1' || value === 'true';
}

function extractAbstractFromSummary(summaryText) {
  const lines = String(summaryText || '')
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);
  if (lines.length === 0) return '';
  const overviewIndex = lines.findIndex(line =>
    line.toLowerCase().includes('one-sentence overview')
  );
  if (overviewIndex !== -1) {
    const nextLine = lines.slice(overviewIndex + 1).find(line => !line.startsWith('#'));
    if (nextLine) return nextLine;
  }
  return lines[0];
}

function getNextArchiveDir(mtmDir) {
  ensureDir(mtmDir);
  const entries = fs.readdirSync(mtmDir, { withFileTypes: true });
  const existing = entries
    .filter(ent => ent.isDirectory() && /^archive_\d+$/.test(ent.name))
    .map(ent => Number(ent.name.replace('archive_', '')))
    .filter(Number.isFinite);
  const nextIndex = existing.length > 0 ? Math.max(...existing) + 1 : 1;
  const dirName = `archive_${String(nextIndex).padStart(3, '0')}`;
  return path.join(mtmDir, dirName);
}

function writeSessionArchive(mtmData, mtmPath, projectRoot) {
  const mtmDir = getTierPath('MTM', projectRoot);
  const archiveDir = getNextArchiveDir(mtmDir);
  ensureDir(archiveDir);

  const sessionPath = path.join(archiveDir, 'session.json');
  atomicWriteSync(sessionPath, JSON.stringify(mtmData, null, 2));

  const summaryPath = mtmPath.replace(/\.json$/i, '.summary.md');
  let overview = '';
  if (fs.existsSync(summaryPath)) {
    try {
      overview = fs.readFileSync(summaryPath, 'utf8').trim();
    } catch (_e) {
      overview = '';
    }
  }
  if (!overview && mtmData.summary) {
    overview = String(mtmData.summary).trim();
  }
  if (!overview) {
    overview = '_No summary available._';
  }

  const overviewPath = path.join(archiveDir, '.overview.md');
  atomicWriteSync(overviewPath, overview);

  const abstract = extractAbstractFromSummary(overview);
  const abstractPath = path.join(archiveDir, '.abstract.md');
  atomicWriteSync(abstractPath, abstract || '_No summary available._');

  return { archiveDir, overviewPath, abstractPath, sessionPath };
}

function getMemoryDir(projectRoot = PROJECT_ROOT) {
  return path.join(projectRoot, '.claude', 'context', 'memory');
}

function ensureDir(dirPath) {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function getTierPath(tier, projectRoot = PROJECT_ROOT) {
  const memoryDir = getMemoryDir(projectRoot);
  switch (tier) {
    case 'STM':
      return path.join(memoryDir, 'stm');
    case 'MTM':
      return path.join(memoryDir, 'mtm');
    case 'LTM':
      return path.join(memoryDir, 'ltm');
    default:
      throw new Error(`Unknown tier: ${tier}`);
  }
}

function writeSTMEntry(sessionData, projectRoot = PROJECT_ROOT) {
  const stmDir = getTierPath('STM', projectRoot);
  ensureDir(stmDir);

  const stmPath = path.join(stmDir, 'session_current.json');
  const entry = {
    ...sessionData,
    tier: 'STM',
    updated_at: new Date().toISOString(),
  };

  atomicWriteSync(stmPath, JSON.stringify(entry, null, 2));
  return { success: true, path: stmPath };
}

function readSTMEntry(projectRoot = PROJECT_ROOT) {
  const stmDir = getTierPath('STM', projectRoot);
  const stmPath = path.join(stmDir, 'session_current.json');

  if (!fs.existsSync(stmPath)) {
    return null;
  }

  try {
    return JSON.parse(fs.readFileSync(stmPath, 'utf8'));
  } catch (e) {
    if (process.env.MEMORY_DEBUG) {
      console.error('[MEMORY_DEBUG]', 'readSTMEntry:', e.message);
    }
    return null;
  }
}

function clearSTM(projectRoot = PROJECT_ROOT) {
  const stmDir = getTierPath('STM', projectRoot);
  const stmPath = path.join(stmDir, 'session_current.json');

  if (fs.existsSync(stmPath)) {
    fs.unlinkSync(stmPath);
  }
}

function getMTMSessions(projectRoot = PROJECT_ROOT) {
  const mtmDir = getTierPath('MTM', projectRoot);
  ensureDir(mtmDir);

  const files = fs
    .readdirSync(mtmDir)
    .filter(f => f.endsWith('.json'))
    .sort();

  return files
    .map(f => {
      try {
        const data = JSON.parse(fs.readFileSync(path.join(mtmDir, f), 'utf8'));
        return { ...data, _filename: f };
      } catch (e) {
        if (process.env.MEMORY_DEBUG) {
          console.error('[MEMORY_DEBUG]', 'getMTMSessions:', e.message);
        }
        return null;
      }
    })
    .filter(Boolean);
}

function consolidateSession(sessionId, projectRoot = PROJECT_ROOT) {
  const stmDir = getTierPath('STM', projectRoot);
  const mtmDir = getTierPath('MTM', projectRoot);
  ensureDir(mtmDir);

  // Find session in STM
  const stmPath = path.join(stmDir, 'session_current.json');
  if (!fs.existsSync(stmPath)) {
    return { success: false, error: 'No STM session found' };
  }

  let sessionData;
  try {
    sessionData = JSON.parse(fs.readFileSync(stmPath, 'utf8'));
  } catch (e) {
    if (process.env.MEMORY_DEBUG) {
      console.error('[MEMORY_DEBUG]', 'consolidateSession:', e.message);
    }
    return { success: false, error: 'Failed to read STM session' };
  }

  // Check if MTM is at capacity
  const mtmSessions = getMTMSessions(projectRoot);
  if (mtmSessions.length >= CONFIG.MTM_MAX_SESSIONS) {
    // Trigger summarization of oldest sessions to make room
    summarizeOldSessions(projectRoot);
  }

  // Generate MTM filename with timestamp
  const now = new Date();
  const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const mtmFilename = `session_${timestamp}.json`;
  const mtmPath = path.join(mtmDir, mtmFilename);

  // Add consolidation metadata
  const mtmData = {
    ...sessionData,
    tier: 'MTM',
    consolidated_at: now.toISOString(),
  };

  // Write to MTM
  atomicWriteSync(mtmPath, JSON.stringify(mtmData, null, 2));

  if (isStructuredSummaryEnabled()) {
    try {
      const { generateStructuredSummaryForSession } = require('./session-summary.cjs');
      const summaryPromise = generateStructuredSummaryForSession(mtmData, {
        projectRoot,
        mtmPath,
      });
      summaryPromise.catch(err => {
        if (process.env.MEMORY_DEBUG) {
          console.error('[MEMORY_DEBUG]', 'structured summary failed:', err.message);
        }
      });
    } catch (e) {
      if (process.env.MEMORY_DEBUG) {
        console.error('[MEMORY_DEBUG]', 'structured summary init failed:', e.message);
      }
    }
  }

  if (isSessionArchiveEnabled()) {
    try {
      writeSessionArchive(mtmData, mtmPath, projectRoot);
    } catch (e) {
      if (process.env.MEMORY_DEBUG) {
        console.error('[MEMORY_DEBUG]', 'session archive failed:', e.message);
      }
    }
  }

  // Clear STM
  clearSTM(projectRoot);

  return {
    success: true,
    mtmPath: mtmPath,
    sessionId: sessionData.session_id || sessionId,
  };
}

function findMTMSession(sessionId, projectRoot = PROJECT_ROOT) {
  const mtmDir = getTierPath('MTM', projectRoot);
  const sessions = getMTMSessions(projectRoot);

  for (const session of sessions) {
    if (session.session_id === sessionId) {
      return {
        data: session,
        path: path.join(mtmDir, session._filename),
      };
    }
  }

  return null;
}

function promoteToLTM(sessionId, projectRoot = PROJECT_ROOT) {
  const _mtmDir = getTierPath('MTM', projectRoot);
  const ltmDir = getTierPath('LTM', projectRoot);
  ensureDir(ltmDir);

  // Find session in MTM
  const found = findMTMSession(sessionId, projectRoot);
  if (!found) {
    return { success: false, error: 'Session not found in MTM' };
  }

  // Generate LTM filename
  const now = new Date();
  const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const ltmFilename = `promoted_${timestamp}.json`;
  const ltmPath = path.join(ltmDir, ltmFilename);

  // Add promotion metadata
  const ltmData = {
    ...found.data,
    tier: 'LTM',
    promoted_at: now.toISOString(),
    promotion_reason: 'manual_promotion',
  };
  delete ltmData._filename;

  // Write to LTM
  atomicWriteSync(ltmPath, JSON.stringify(ltmData, null, 2));

  // Remove from MTM
  if (fs.existsSync(found.path)) {
    fs.unlinkSync(found.path);
  }

  return {
    success: true,
    ltmPath: ltmPath,
    sessionId: sessionId,
  };
}

function generateSessionSummary(sessions) {
  if (!sessions || sessions.length === 0) {
    return null;
  }

  // Sort by timestamp
  const sorted = [...sessions].sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

  const startDate = sorted[0].timestamp.split('T')[0];
  const endDate = sorted[sorted.length - 1].timestamp.split('T')[0];

  // Aggregate data
  const allLearnings = [];
  const allDecisions = [];
  const allPatterns = [];
  const fileFrequency = {};

  for (const session of sessions) {
    // Collect learnings (from summaries)
    if (session.summary) {
      allLearnings.push(session.summary);
    }

    // Collect decisions
    if (session.decisions_made) {
      allDecisions.push(...session.decisions_made);
    }

    // Collect patterns
    if (session.patterns_found) {
      allPatterns.push(...session.patterns_found);
    }

    // Track file frequency
    if (session.files_modified) {
      for (const file of session.files_modified) {
        fileFrequency[file] = (fileFrequency[file] || 0) + 1;
      }
    }
  }

  // Get frequently touched files (touched more than once)
  const frequentFiles = Object.entries(fileFrequency)
    .filter(([_, count]) => count > 1)
    .sort((a, b) => b[1] - a[1])
    .map(([file]) => file);

  return {
    type: 'session_summary',
    date_range: {
      start: startDate,
      end: endDate,
    },
    session_count: sessions.length,
    session_ids: sessions.map(s => s.session_id).filter(Boolean),
    key_learnings: allLearnings,
    major_decisions: allDecisions,
    important_patterns: allPatterns,
    files_frequently_touched: frequentFiles,
    created_at: new Date().toISOString(),
  };
}

function summarizeOldSessions(projectRoot = PROJECT_ROOT) {
  const mtmDir = getTierPath('MTM', projectRoot);
  const ltmDir = getTierPath('LTM', projectRoot);
  ensureDir(ltmDir);

  const sessions = getMTMSessions(projectRoot);

  // Only summarize if we have more than max sessions
  if (sessions.length <= CONFIG.MTM_MAX_SESSIONS) {
    return { summarized: 0, summaryPath: null };
  }

  // Calculate how many to summarize (keep MTM at max)
  const toSummarize = sessions.length - CONFIG.MTM_MAX_SESSIONS + CONFIG.SUMMARY_MIN_SESSIONS;
  const sessionsToSummarize = sessions.slice(
    0,
    Math.min(toSummarize, sessions.length - CONFIG.SUMMARY_MIN_SESSIONS)
  );

  if (sessionsToSummarize.length < CONFIG.SUMMARY_MIN_SESSIONS) {
    return { summarized: 0, summaryPath: null };
  }

  // Generate summary
  const summary = generateSessionSummary(sessionsToSummarize);

  // Write summary to LTM
  const now = new Date();
  const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);
  const summaryFilename = `summary_${timestamp}.json`;
  const summaryPath = path.join(ltmDir, summaryFilename);

  atomicWriteSync(summaryPath, JSON.stringify(summary, null, 2));

  // Remove summarized sessions from MTM
  for (const session of sessionsToSummarize) {
    const sessionPath = path.join(mtmDir, session._filename);
    if (fs.existsSync(sessionPath)) {
      fs.unlinkSync(sessionPath);
    }
  }

  return {
    summarized: sessionsToSummarize.length,
    summaryPath: summaryPath,
    summary: summary,
  };
}

function getTierHealth(projectRoot = PROJECT_ROOT) {
  const result = {
    stm: { sessionCount: 0, warnings: [] },
    mtm: { sessionCount: 0, warnings: [] },
    ltm: { summaryCount: 0, warnings: [] },
    overall: 'healthy',
  };

  // Check STM
  const stmEntry = readSTMEntry(projectRoot);
  result.stm.sessionCount = stmEntry ? 1 : 0;

  // Check MTM
  const mtmSessions = getMTMSessions(projectRoot);
  result.mtm.sessionCount = mtmSessions.length;

  if (mtmSessions.length >= CONFIG.MTM_WARN_THRESHOLD) {
    result.mtm.warnings.push(
      `MTM is approaching limit: ${mtmSessions.length}/${CONFIG.MTM_MAX_SESSIONS} sessions`
    );
    result.overall = 'warning';
  }

  // Check LTM
  const ltmDir = getTierPath('LTM', projectRoot);
  if (fs.existsSync(ltmDir)) {
    const ltmFiles = fs.readdirSync(ltmDir).filter(f => f.endsWith('.json'));
    result.ltm.summaryCount = ltmFiles.length;
  }

  return result;
}

function buildScopeBlock(contextType, targetAbstract) {
  if (!contextType) return '';
  const lines = [];
  lines.push('');
  lines.push('## Search Scope Constraints');
  lines.push('');
  lines.push(`**Restricted Context Type**: ${contextType}`);
  if (targetAbstract) {
    lines.push(`**Target Directory Abstract**: ${targetAbstract}`);
  }
  lines.push('');
  lines.push(
    `**Important**: You can only generate \`${contextType}\` type queries, do not generate other types.`
  );
  lines.push('');
  return lines.join('\n');
}

function applyTemplate(template, replacements) {
  let output = template;
  for (const [key, value] of Object.entries(replacements)) {
    output = output.replace(new RegExp(`{{\\s*${key}\\s*}}`, 'g'), value ?? '');
  }
  return output;
}

function getIntentAnalysisPrompt(
  compressionSummary,
  recentMessages,
  currentMessage,
  contextType = '',
  targetAbstract = ''
) {
  const scopeBlock = buildScopeBlock(contextType, targetAbstract);
  const user = applyTemplate(TEMPLATE, {
    compression_summary: compressionSummary || '',
    recent_messages: recentMessages || '',
    current_message: currentMessage || '',
    scope_block: scopeBlock,
  });

  return {
    system: 'You are a precise query planner that outputs JSON only.',
    user,
  };
}

function formatRecentMessages(sessionData, maxMessages) {
  if (Array.isArray(sessionData?.recent_messages) && sessionData.recent_messages.length > 0) {
    return sessionData.recent_messages
      .map(entry => {
        if (!entry || typeof entry !== 'object') return '';
        const role = entry.role || 'unknown';
        const content = entry.content || '';
        return `[${role}]: ${content}`;
      })
      .filter(Boolean)
      .slice(-maxMessages);
  }

  const parts = [];
  if (sessionData?.summary) {
    parts.push(`Summary: ${sessionData.summary}`);
  }
  if (Array.isArray(sessionData?.decisions_made) && sessionData.decisions_made.length > 0) {
    parts.push(`Decisions: ${sessionData.decisions_made.join('; ')}`);
  }
  if (Array.isArray(sessionData?.patterns_found) && sessionData.patterns_found.length > 0) {
    parts.push(`Patterns: ${sessionData.patterns_found.join('; ')}`);
  }
  if (
    Array.isArray(sessionData?.gotchas_encountered) &&
    sessionData.gotchas_encountered.length > 0
  ) {
    parts.push(`Gotchas: ${sessionData.gotchas_encountered.join('; ')}`);
  }

  return parts.filter(Boolean).slice(-maxMessages);
}

function scoreSummary(text, query) {
  const q = String(query || '')
    .trim()
    .toLowerCase();
  if (!q) return 0;
  const haystack = String(text || '').toLowerCase();
  const tokens = q.split(/\s+/).filter(Boolean);
  let score = 0;
  for (const token of tokens) {
    if (token.length < 3) continue;
    if (haystack.includes(token)) score += 1;
  }
  return score;
}

function readSummaryFiles(projectRoot) {
  const mtmDir = memoryTiers.getTierPath('MTM', projectRoot);
  if (!fs.existsSync(mtmDir)) return [];
  return fs
    .readdirSync(mtmDir)
    .filter(name => name.endsWith('.summary.md'))
    .map(name => {
      const filePath = path.join(mtmDir, name);
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        const stat = fs.statSync(filePath);
        return {
          path: filePath,
          content: content.trim(),
          mtimeMs: stat.mtimeMs || 0,
        };
      } catch (_err) {
        return null;
      }
    })
    .filter(Boolean);
}

function readArchiveSummaries(projectRoot) {
  const mtmDir = memoryTiers.getTierPath('MTM', projectRoot);
  if (!fs.existsSync(mtmDir)) return [];
  const entries = fs.readdirSync(mtmDir, { withFileTypes: true });
  return entries
    .filter(ent => ent.isDirectory() && /^archive_\d+$/.test(ent.name))
    .map(ent => {
      const name = ent.name;
      const overviewPath = path.join(mtmDir, name, '.overview.md');
      if (!fs.existsSync(overviewPath)) return null;
      try {
        const content = fs.readFileSync(overviewPath, 'utf8');
        const stat = fs.statSync(overviewPath);
        return {
          path: overviewPath,
          content: content.trim(),
          mtimeMs: stat.mtimeMs || 0,
        };
      } catch (_err) {
        return null;
      }
    })
    .filter(Boolean);
}

function buildRecentMessages(sessionData) {
  if (!sessionData || typeof sessionData !== 'object') return '';

  if (Array.isArray(sessionData.recent_messages) && sessionData.recent_messages.length > 0) {
    const recent = sessionData.recent_messages.slice(-RECENT_MESSAGES_LIMIT);
    const joined = recent
      .map(entry => {
        if (!entry || typeof entry !== 'object') return '';
        const role = entry.role || 'unknown';
        const content = entry.content || '';
        return `[${role}]: ${content}`;
      })
      .filter(Boolean)
      .join('\n');

    if (joined.length > RECENT_MESSAGES_MAX_CHARS) {
      return joined.slice(-RECENT_MESSAGES_MAX_CHARS);
    }
    return joined;
  }

  const parts = [];
  if (sessionData.summary) {
    parts.push(`Session summary:\n${sessionData.summary}`);
  }
  if (Array.isArray(sessionData.decisions_made) && sessionData.decisions_made.length > 0) {
    const decisions = sessionData.decisions_made.slice(0, LIST_LIMIT);
    parts.push(`Decisions:\n- ${decisions.join('\n- ')}`);
  }
  if (Array.isArray(sessionData.patterns_found) && sessionData.patterns_found.length > 0) {
    const patterns = sessionData.patterns_found.slice(0, LIST_LIMIT);
    parts.push(`Patterns:\n- ${patterns.join('\n- ')}`);
  }
  if (
    Array.isArray(sessionData.gotchas_encountered) &&
    sessionData.gotchas_encountered.length > 0
  ) {
    const gotchas = sessionData.gotchas_encountered.slice(0, LIST_LIMIT);
    parts.push(`Gotchas:\n- ${gotchas.join('\n- ')}`);
  }
  if (Array.isArray(sessionData.tasks_completed) && sessionData.tasks_completed.length > 0) {
    const tasks = sessionData.tasks_completed.slice(0, LIST_LIMIT);
    parts.push(`Tasks completed:\n- ${tasks.join('\n- ')}`);
  }

  const joined = parts.join('\n\n');
  if (joined.length > RECENT_MESSAGES_MAX_CHARS) {
    return joined.slice(-RECENT_MESSAGES_MAX_CHARS);
  }
  return joined;
}

function buildFallbackCandidate(category, text, tag) {
  const clean = String(text || '').trim();
  if (!clean) return null;
  const label = tag ? `${tag}: ${clean}` : clean;
  return {
    category,
    abstract: label.slice(0, 80),
    overview: label,
    content: clean,
  };
}

function fallbackExtractMemories(sessionData) {
  const candidates = [];
  const patterns = Array.isArray(sessionData?.patterns_found) ? sessionData.patterns_found : [];
  const gotchas = Array.isArray(sessionData?.gotchas_encountered)
    ? sessionData.gotchas_encountered
    : [];
  const decisions = Array.isArray(sessionData?.decisions_made) ? sessionData.decisions_made : [];
  const tasks = Array.isArray(sessionData?.tasks_completed) ? sessionData.tasks_completed : [];

  for (const item of patterns) {
    const candidate = buildFallbackCandidate('patterns', item, 'Pattern');
    if (candidate) candidates.push(candidate);
  }
  for (const item of gotchas) {
    const candidate = buildFallbackCandidate('cases', item, 'Gotcha');
    if (candidate) candidates.push(candidate);
  }
  for (const item of decisions) {
    const candidate = buildFallbackCandidate('events', item, 'Decision');
    if (candidate) candidates.push(candidate);
  }
  for (const item of tasks) {
    const candidate = buildFallbackCandidate('events', item, 'Task');
    if (candidate) candidates.push(candidate);
  }

  return candidates;
}

function extractCandidatesFromText(text) {
  const candidates = [];
  if (!text) return candidates;
  const lines = String(text)
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean);

  const add = (category, line, tag) => {
    const candidate = buildFallbackCandidate(category, line, tag);
    if (candidate) candidates.push(candidate);
  };

  for (const line of lines) {
    const lower = line.toLowerCase();
    if (lower.startsWith('pattern:') || lower.includes('pattern -')) {
      add('patterns', line.replace(/^pattern:\s*/i, ''), 'Pattern');
      continue;
    }
    if (lower.startsWith('gotcha:') || lower.includes('gotcha -')) {
      add('cases', line.replace(/^gotcha:\s*/i, ''), 'Gotcha');
      continue;
    }
    if (lower.startsWith('decision:') || lower.includes('decision -')) {
      add('events', line.replace(/^decision:\s*/i, ''), 'Decision');
      continue;
    }
    if (lower.startsWith('lesson:') || lower.startsWith('remember:')) {
      add('patterns', line.replace(/^(lesson|remember):\s*/i, ''), 'Lesson');
    }
  }

  return candidates;
}

function extractJson(text) {
  if (!text) return null;
  const trimmed = String(text).trim();
  const fenced = trimmed.match(/```json\s*([\s\S]*?)```/i) || trimmed.match(/```\s*([\s\S]*?)```/i);
  const payload = fenced ? fenced[1] : trimmed;
  return payload.trim();
}

function buildSessionContext(sessionData) {
  if (!sessionData || typeof sessionData !== 'object') return '';

  if (Array.isArray(sessionData.recent_messages) && sessionData.recent_messages.length > 0) {
    return sessionData.recent_messages
      .map(entry => {
