  }
  if (Array.isArray(sessionData.patterns_found) && sessionData.patterns_found.length > 0) {
    parts.push(`Patterns:\n- ${sessionData.patterns_found.join('\n- ')}`);
  }
  if (
    Array.isArray(sessionData.gotchas_encountered) &&
