class AdaptiveExecutor {
  constructor(config = {}) {
    this.config = {
      defaultTimeout: config.defaultTimeout || 60000,
      maxConcurrency: config.maxConcurrency || 10,
      ...config,
    };

    this.executionHistory = [];
    this.strategyWeights = {
      parallel: 1.0,
      batch: 1.0,
      cache: 1.0,
      none: 1.0,
    };
    this.modelOutcomes = {};
  }

  /**
   * Select optimization strategy based on pattern
   * @param {Object} pattern - Pattern object
   * @returns {Object} Strategy recommendation
   */
  selectStrategy(pattern) {
    if (!pattern) return { type: 'none', reason: 'No pattern provided' };

    // Check for repeated similar tasks first - can be batched
    // (This takes priority over parallelization when tasks are similar)
    if (pattern.type === 'repeated' || this._hasRepeatedOperations(pattern)) {
      return {
        type: 'batch',
        reason: 'Multiple similar operations can be batched',
        expectedSpeedup: 0.3,
      };
    }

    // Check for independent tasks - can be parallelized
    if (pattern.type === 'independent' || this._hasIndependentTasks(pattern)) {
      return {
        type: 'parallel',
        reason: 'Tasks have no dependencies and can run in parallel',
        expectedSpeedup: 0.5,
      };
    }

    // Check for idempotent operations - can be cached
    if (pattern.type === 'idempotent' || this._isIdempotent(pattern)) {
      return {
        type: 'cache',
        reason: 'Operation is idempotent and results can be cached',
        expectedSpeedup: 0.7,
      };
    }

    // Use learned weights to select strategy
    const learnedStrategy = this._selectFromWeights(pattern);
    if (learnedStrategy.type !== 'none') {
      return learnedStrategy;
    }

    return { type: 'none', reason: 'No optimization applicable' };
  }

  _hasIndependentTasks(pattern) {
    if (!pattern.tasks || !Array.isArray(pattern.tasks)) return false;
    return pattern.tasks.every(t => !t.dependencies || t.dependencies.length === 0);
  }

  _hasRepeatedOperations(pattern) {
    if (!pattern.tasks || !Array.isArray(pattern.tasks)) return false;
    const operations = pattern.tasks
      .map(t => t.operation)
      .filter(op => op !== undefined && op !== null);
    if (operations.length === 0) return false;
    const unique = new Set(operations);
    return unique.size < operations.length / 2;
  }

  _isIdempotent(pattern) {
    const idempotentOps = ['Read', 'Grep', 'Glob', 'Search'];
    return pattern.operation && idempotentOps.includes(pattern.operation);
  }

  _selectFromWeights(_pattern) {
    // Select strategy based on historical success weights
    let maxWeight = 0;
    let bestStrategy = 'none';

    for (const [strategy, weight] of Object.entries(this.strategyWeights)) {
      if (weight > maxWeight && strategy !== 'none') {
        maxWeight = weight;
        bestStrategy = strategy;
      }
    }

    if (maxWeight > 1.5) {
      return {
        type: bestStrategy,
        reason: `Learned from historical outcomes (weight: ${maxWeight.toFixed(2)})`,
        expectedSpeedup: 0.2,
      };
    }

    return { type: 'none', reason: 'No strong pattern from history' };
  }

  /**
   * Recommend model based on task characteristics
   * @param {Object} task - Task description
   * @returns {string} Recommended model
   */
  recommendModel(task) {
    // Check historical outcomes for task type
    if (task.taskType && this.modelOutcomes[task.taskType]) {
      const outcomes = this.modelOutcomes[task.taskType];
      let bestModel = null;
      let bestRate = 0;

      for (const [model, stats] of Object.entries(outcomes)) {
        const successRate = stats.total > 0 ? stats.success / stats.total : 0;
        if (successRate > bestRate) {
          bestRate = successRate;
          bestModel = model;
        }
      }

      // If we have clear historical preference, use it
      if (bestModel && bestRate > 0.7) {
        return bestModel;
      }
    }

    // Default recommendations based on task complexity
    if (task.complexity === 'high' || task.criticalPath) {
      return 'claude-opus-4-5-20251101';
    }

    if (task.complexity === 'medium' || task.tokenEstimate > 3000) {
      return 'claude-sonnet-4-20250514';
    }

    return 'claude-haiku-4-20250514';
  }

  /**
   * Record outcome for model selection learning
   * @param {string} model - Model used
   * @param {string} taskType - Type of task
   * @param {boolean} success - Whether task succeeded
   */
  recordOutcome(model, taskType, success) {
    if (!this.modelOutcomes[taskType]) {
      this.modelOutcomes[taskType] = {};
    }
    if (!this.modelOutcomes[taskType][model]) {
      this.modelOutcomes[taskType][model] = { success: 0, total: 0 };
    }

    this.modelOutcomes[taskType][model].total++;
    if (success) {
      this.modelOutcomes[taskType][model].success++;
    }
  }

  /**
   * Adjust timeout based on historical duration
   * @param {Array} history - Array of {duration} records
   * @returns {number} Recommended timeout in ms
   */
  adjustTimeout(history) {
    if (!history || history.length === 0) {
      return this.config.defaultTimeout;
    }

    const durations = history.map(h => h.duration);
    const avg = durations.reduce((sum, d) => sum + d, 0) / durations.length;
    const max = Math.max(...durations);

    // Use 2x average or 1.5x max, whichever is larger (with buffer)
    return Math.max(avg * 2, max * 1.5);
  }

  /**
   * Adjust concurrency based on resource metrics
   * @param {Object} metrics - {cpuUsage, memoryUsage, activeConnections}
   * @returns {number} Recommended concurrency level
   */
  adjustConcurrency(metrics) {
    const baselineConcurrency = this.config.maxConcurrency;

    // Reduce concurrency under high load
    const cpuFactor = 1 - (metrics.cpuUsage || 0);
    const memoryFactor = 1 - (metrics.memoryUsage || 0);
    const loadFactor = Math.min(cpuFactor, memoryFactor);

    const recommended = Math.max(1, Math.floor(baselineConcurrency * loadFactor));
    return recommended;
  }

  /**
   * Record execution for learning
   * @param {Object} execution - {taskId, strategy, success, duration, cost}
   */
  recordExecution(execution) {
    this.executionHistory.push({
      ...execution,
      timestamp: new Date().toISOString(),
    });

    // Update strategy weights based on outcome
    if (execution.strategy) {
      const factor = execution.success ? 1.1 : 0.9;
      this.strategyWeights[execution.strategy] *= factor;

      // Normalize weights
      const total = Object.values(this.strategyWeights).reduce((s, w) => s + w, 0);
      for (const key of Object.keys(this.strategyWeights)) {
        this.strategyWeights[key] /= total / 4; // Keep average at 1.0
      }
    }
  }

  /**
   * Get execution history
   * @returns {Array} Execution history
   */
  getExecutionHistory() {
    return [...this.executionHistory];
  }

  /**
   * Get current strategy weights
   * @returns {Object} Strategy weights
   */
  getStrategyWeights() {
    return { ...this.strategyWeights };
  }

  /**
   * Recommend strategy for pattern based on learned history
   * @param {Object} pattern - Pattern to match
   * @returns {Object} Recommendation
   */
  recommendForPattern(pattern) {
    // Find executions with similar pattern type
    const relevant = this.executionHistory.filter(e => e.patternType === pattern.type);

    if (relevant.length === 0) {
      return this.selectStrategy(pattern);
    }

    // Count successes per strategy
    const strategyStats = {};
    for (const exec of relevant) {
      if (!strategyStats[exec.strategy]) {
        strategyStats[exec.strategy] = { success: 0, total: 0 };
      }
      strategyStats[exec.strategy].total++;
      if (exec.success) {
        strategyStats[exec.strategy].success++;
      }
    }

    // Find best strategy
    let bestStrategy = 'none';
    let bestRate = 0;
    for (const [strategy, stats] of Object.entries(strategyStats)) {
      const rate = stats.total > 0 ? stats.success / stats.total : 0;
      if (rate > bestRate) {
        bestRate = rate;
        bestStrategy = strategy;
      }
    }

    return {
      strategy: bestStrategy,
      confidence: bestRate,
      basedOn: relevant.length,
    };
  }

class CostPredictor {
  constructor(config = {}) {
    this.config = {
      charsPerToken: config.charsPerToken || 4,
      systemOverhead: config.systemOverhead || SYSTEM_OVERHEAD_TOKENS,
      ...config,
    };

    this.sessionRequests = [];
    this.predictionHistory = [];
  }

  /**
   * Estimate token count from text
   * @param {string} text - Text to estimate
   * @param {Object} options - Options (includeSystemOverhead)
   * @returns {number} Estimated token count
   */
  estimateTokens(text, options = {}) {
    if (!text || typeof text !== 'string') return 0;

    // Basic estimation: ~4 characters per token
    let tokens = Math.ceil(text.length / this.config.charsPerToken);

    // Add overhead for system prompts
    if (options.includeSystemOverhead) {
      tokens += this.config.systemOverhead;
    }

    return tokens;
  }

  /**
   * Estimate tokens for a conversation
   * @param {Array} messages - Array of {role, content} messages
   * @returns {number} Total estimated tokens
   */
  estimateConversationTokens(messages) {
    if (!Array.isArray(messages)) return 0;

    let total = 0;
    for (const msg of messages) {
      total += this.estimateTokens(msg.content || '');
      // Add overhead for message structure (~4 tokens per message)
      total += 4;
    }

    return total;
  }

  /**
   * Get pricing for a model
   * @param {string} model - Model identifier
   * @returns {Object} Pricing object {inputPer1k, outputPer1k}
   */
  getModelPricing(model) {
    return MODEL_PRICING[model] || MODEL_PRICING['default'];
  }

  /**
   * List all available model pricings
   * @returns {Array} Array of model names
   */
  listModelPricings() {
    return Object.keys(MODEL_PRICING).filter(k => k !== 'default');
  }

  /**
   * Calculate cost for a single request
   * @param {Object} request - {model, inputTokens, outputTokens}
   * @returns {number} Cost in dollars
   */
  calculateCost(request) {
    const pricing = this.getModelPricing(request.model);
    const inputCost = (request.inputTokens / 1000) * pricing.inputPer1k;
    const outputCost = (request.outputTokens / 1000) * pricing.outputPer1k;
    return inputCost + outputCost;
  }

  /**
   * Reset session tracking
   */
  resetSession() {
    this.sessionRequests = [];
  }

  /**
   * Add a request to session tracking
   * @param {Object} request - {model, inputTokens, outputTokens}
   */
  addRequest(request) {
    const cost = this.calculateCost(request);
    this.sessionRequests.push({
      ...request,
      cost,
      timestamp: new Date().toISOString(),
    });
  }

  /**
   * Get total session cost
   * @returns {number} Total cost in dollars
   */
  getSessionTotal() {
    return this.sessionRequests.reduce((sum, r) => sum + r.cost, 0);
  }

  /**
   * Get cost breakdown by model
   * @returns {Object} Cost by model
   */
  getCostBreakdown() {
    const breakdown = {};
    for (const request of this.sessionRequests) {
      if (!breakdown[request.model]) {
        breakdown[request.model] = {
          requests: 0,
          inputTokens: 0,
          outputTokens: 0,
          cost: 0,
        };
      }
      breakdown[request.model].requests++;
      breakdown[request.model].inputTokens += request.inputTokens;
      breakdown[request.model].outputTokens += request.outputTokens;
      breakdown[request.model].cost += request.cost;
    }
    return breakdown;
  }

  /**
   * Forecast future costs based on historical data
   * @param {Array} history - Array of {date, cost}
   * @param {number} days - Days to forecast
   * @returns {Object} Forecast {predicted, confidence}
   */
  forecastCost(history, days) {
    if (!history || history.length === 0) {
      return { predicted: 0, confidence: 0 };
    }

    // Simple linear regression forecast
    const costs = history.map(h => h.cost);
    const n = costs.length;

    // Calculate average daily cost
    const avgCost = costs.reduce((sum, c) => sum + c, 0) / n;

    // Calculate trend (simple linear)
    let trend = 0;
    if (n > 1) {
      const xMean = (n - 1) / 2;
      const yMean = avgCost;
      let numerator = 0;
      let denominator = 0;
      for (let i = 0; i < n; i++) {
        numerator += (i - xMean) * (costs[i] - yMean);
        denominator += (i - xMean) * (i - xMean);
      }
      trend = denominator !== 0 ? numerator / denominator : 0;
    }

    // Forecast
    const predicted = (avgCost + trend * n) * days;

    // Confidence based on data variance
    const variance = costs.reduce((sum, c) => sum + Math.pow(c - avgCost, 2), 0) / n;
    const stdDev = Math.sqrt(variance);
    const cv = avgCost > 0 ? stdDev / avgCost : 1; // Coefficient of variation
    const confidence = Math.max(0, Math.min(1, 1 - cv));

    return { predicted, confidence };
  }

  /**
   * Calculate prediction accuracy
   * @param {number} predicted - Predicted value
   * @param {number} actual - Actual value
   * @returns {number} Accuracy (0-1)
   */
  calculateAccuracy(predicted, actual) {
    if (actual === 0) return predicted === 0 ? 1 : 0;
    const error = Math.abs(predicted - actual) / actual;
    return Math.max(0, 1 - error);
  }

  /**
   * Record a prediction for accuracy tracking
   * @param {number} predicted - Predicted value
   * @param {number} actual - Actual value
   */
  recordPrediction(predicted, actual) {
    const accuracy = this.calculateAccuracy(predicted, actual);
    this.predictionHistory.push({
      predicted,
      actual,
      accuracy,
      timestamp: new Date().toISOString(),
    });
  }

  /**
   * Reset accuracy tracking
   */
  resetAccuracyTracking() {
    this.predictionHistory = [];
  }

  /**
   * Get average accuracy across all predictions
   * @returns {number} Average accuracy (0-1)
   */
  getAverageAccuracy() {
    if (this.predictionHistory.length === 0) return 1;
    const sum = this.predictionHistory.reduce((s, p) => s + p.accuracy, 0);
    return sum / this.predictionHistory.length;
  }

  /**
   * Get warnings when accuracy drops below threshold
   * @param {number} threshold - Minimum acceptable accuracy
   * @returns {Array} Array of warnings
   */
  getAccuracyWarnings(threshold = 0.8) {
    return this.predictionHistory
      .filter(p => p.accuracy < threshold)
      .map(p => ({
        message: `Prediction accuracy ${(p.accuracy * 100).toFixed(1)}% below threshold ${(threshold * 100).toFixed(1)}%`,
        predicted: p.predicted,
        actual: p.actual,
        timestamp: p.timestamp,
      }));
  }

class FeedbackLoop {
  constructor(patternDetector, optimizationEngine, config = {}) {
    this.patternDetector = patternDetector;
    this.optimizationEngine = optimizationEngine;

    this.ingestCount = 0;
    this.retrainThreshold = config.retrainThreshold || 10;
    this.modelPath = config.modelPath || null;
    this.policyPath = config.policyPath || null;
    this.statePath = config.statePath || null;
    this.sessionsPath = config.sessionsPath || null;
    this.trainingWindow = config.trainingWindow || 200;
    this.maxSessionLogLines = config.maxSessionLogLines || 2000;
    /** off = ingest only; log | enforce = allow retrain and persist */
    this.automationMode = (config.automationMode || 'off').toLowerCase();
  }

  _ensureDirForFile(filePath) {
    if (!filePath) return;
    const dir = path.dirname(filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
  }

  _readState() {
    if (!this.statePath || !fs.existsSync(this.statePath)) {
      return { ingestCount: 0, lastRetrainAt: null };
    }
    try {
      return (
        JSON.parse(fs.readFileSync(this.statePath, 'utf8')) || {
          ingestCount: 0,
          lastRetrainAt: null,
        }
      );
    } catch {
      return { ingestCount: 0, lastRetrainAt: null };
    }
  }

  _writeState(state) {
    if (!this.statePath) return;
    this._ensureDirForFile(this.statePath);
    fs.writeFileSync(this.statePath, JSON.stringify(state, null, 2));
  }

  _appendSession(session) {
    if (!this.sessionsPath) return;
    this._ensureDirForFile(this.sessionsPath);
    fs.appendFileSync(this.sessionsPath, JSON.stringify(session) + '\n', 'utf8');

    // Best-effort trim to keep bounded (simple: keep last N lines).
    try {
      const raw = fs.readFileSync(this.sessionsPath, 'utf8');
      const lines = raw.split(/\r?\n/).filter(Boolean);
      if (lines.length > this.maxSessionLogLines) {
        const kept = lines.slice(-this.maxSessionLogLines).join('\n') + '\n';
        fs.writeFileSync(this.sessionsPath, kept, 'utf8');
      }
    } catch {
      // ignore trim failures
    }
  }

  _readRecentSessions() {
    if (!this.sessionsPath || !fs.existsSync(this.sessionsPath)) return [];
    try {
      const raw = fs.readFileSync(this.sessionsPath, 'utf8');
      const lines = raw.split(/\r?\n/).filter(Boolean);
      const window = Math.max(1, this.trainingWindow);
      const slice = lines.slice(-window);
      const sessions = [];
      for (const line of slice) {
        try {
          sessions.push(JSON.parse(line));
        } catch {
          // skip malformed line
        }
      }
      return sessions;
    } catch {
      return [];
    }
  }

  /**
   * Process a completed session.
   * Always ingests data. Retraining runs only when automationMode is 'log' or 'enforce'.
   * @param {Object} session - { history, metrics, trace } for feature extraction
   * @returns {boolean} - true if retrain was triggered and ran
   */
  process(session) {
    // 0. Persist session (if configured) so training can survive hook process restarts.
    this._appendSession(session);

    // 1. Ingest Data (always, for future training)
    this.patternDetector.ingest(session);

    // 2. Update ingest count (persisted if configured; otherwise in-memory fallback)
    let state = null;
    if (this.statePath) {
      state = this._readState();
      state.ingestCount = (state.ingestCount || 0) + 1;
      this._writeState(state);
    } else {
      this.ingestCount++;
    }

    // 2. Check Threshold; only retrain when automation allows
    const currentCount = this.statePath ? state && state.ingestCount : this.ingestCount;
    if (currentCount >= this.retrainThreshold) {
      const allowed = this.automationMode === 'log' || this.automationMode === 'enforce';
      if (allowed) {
        this.retrain();
        if (this.statePath) {
          state.ingestCount = 0;
          state.lastRetrainAt = new Date().toISOString();
          this._writeState(state);
        } else {
          this.ingestCount = 0;
        }
        return true;
      }
      // When automation is off, do not reset count: if operator flips mode to log/enforce,
      // the next session will trigger retrain immediately using the persisted session log.
      if (!this.statePath) {
        this.ingestCount = Math.min(this.ingestCount, this.retrainThreshold);
      }
      return false;
    }

    return false;
  }

  /**
   * Retrain models and persist state. Called only when automationMode is log/enforce.
   */
  retrain() {
    if (ML_DEBUG) {
      process.stderr.write('[FeedbackLoop] Triggering retraining...\n');
    }

    // Rebuild training set from persisted sessions if available (required for hook processes).
    if (this.sessionsPath) {
      const sessions = this._readRecentSessions();
      if (sessions.length > 0) {
        if (typeof this.patternDetector.resetTraining === 'function') {
          this.patternDetector.resetTraining();
        } else {
          // Backward compat if resetTraining not present
          this.patternDetector.trainingData = [];
          this.patternDetector.isTrained = false;
        }
        for (const s of sessions) {
          this.patternDetector.ingest(s);
        }
      }
    }

    // 1. Train Pattern Detector (K-Means)
    const result = this.patternDetector.train();

    // 2. Persist Models
    if (this.modelPath) {
      this.patternDetector.saveModel(this.modelPath);
    }

    // 3. Persist Policies (Optimization Engine)
    if (this.policyPath) {
      if (this.optimizationEngine.savePolicies) {
        this.optimizationEngine.savePolicies();
      }
    }

    return result;
  }

function toNumber(value, fallback) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

class AnomalyDetector {
  /**
   * @param {{analyze: (session: any) => any, isTrained?: boolean}} patternDetector
   * @param {{threshold?: number, treatUntrainedAsAnomaly?: boolean}} [config]
   */
  constructor(patternDetector, config = {}) {
    if (!patternDetector || typeof patternDetector.analyze !== 'function') {
      throw new TypeError(
        'AnomalyDetector requires a PatternDetector-like dependency with analyze(session)'
      );
    }

    this.patternDetector = patternDetector;
    this.threshold = toNumber(
      config.threshold,
      toNumber(process.env.ANOMALY_DISTANCE_THRESHOLD, 10)
    );
    this.treatUntrainedAsAnomaly = Boolean(config.treatUntrainedAsAnomaly);
  }

  /**
   * Detect anomalies for a session.
   *
   * @param {any} session
   * @returns {{
   *   isAnomaly: boolean,
   *   severity: 'none'|'low'|'medium'|'high',
   *   reason: string,
   *   distance: number|null,
   *   threshold: number,
   *   patternId: number|null
   * }}
   */
  detect(session) {
    // If model is explicitly untrained, fail closed (no anomaly) unless opted in.
    if (this.patternDetector.isTrained === false && !this.treatUntrainedAsAnomaly) {
      return {
        isAnomaly: false,
        severity: 'none',
        reason: 'Anomaly detector not ready: pattern model not trained',
        distance: null,
        threshold: this.threshold,
        patternId: null,
      };
    }

    const analysis = this.patternDetector.analyze(session) || {};

    const patternId = typeof analysis.patternId === 'number' ? analysis.patternId : null;
    const distance =
      typeof analysis.distance === 'number' && Number.isFinite(analysis.distance)
        ? analysis.distance
        : null;

    // Unclassifiable session: treat as anomaly only if the model is actually trained
    // (otherwise it would trivially flag everything).
    if (patternId === -1) {
      if (this.patternDetector.isTrained === false && !this.treatUntrainedAsAnomaly) {
        return {
          isAnomaly: false,
          severity: 'none',
          reason: 'Anomaly detector not ready: pattern model not trained',
          distance,
          threshold: this.threshold,
          patternId,
        };
      }

      return {
        isAnomaly: true,
        severity: 'high',
        reason: 'Unclassifiable session (no matching pattern/cluster)',
        distance,
        threshold: this.threshold,
        patternId,
      };
    }

    if (distance === null) {
      return {
        isAnomaly: false,
        severity: 'none',
        reason: 'No distance available from pattern analysis',
        distance: null,
        threshold: this.threshold,
        patternId,
      };
    }

    if (distance > this.threshold * 2) {
      return {
        isAnomaly: true,
        severity: 'high',
        reason: `Distance ${distance.toFixed(3)} exceeds critical threshold ${(this.threshold * 2).toFixed(3)}`,
        distance,
        threshold: this.threshold,
        patternId,
      };
    }

    if (distance > this.threshold) {
      return {
        isAnomaly: true,
        severity: 'medium',
        reason: `Distance ${distance.toFixed(3)} exceeds threshold ${this.threshold.toFixed(3)}`,
        distance,
        threshold: this.threshold,
        patternId,
      };
    }

    return {
      isAnomaly: false,
      severity: 'none',
      reason: 'Within expected distance',
      distance,
      threshold: this.threshold,
      patternId,
    };
  }

class PatternDetector {
  constructor(config = {}) {
    this.featureEngineer = new FeatureEngineer();
    this.clusteringModel = new KMeans(config.k || 5);
    this.trainingData = [];
    this.isTrained = false;
  }

  /**
   * Reset training state (clears ingested feature vectors and marks untrained).
   * Useful when rebuilding training from persisted session logs.
   */
  resetTraining() {
    this.trainingData = [];
    this.isTrained = false;
  }

  /**
   * Add a completed session to the training set.
   * @param {Object} session - Raw session object
   */
  ingest(session) {
    const features = this.featureEngineer.extractFeatures(session);
    this.trainingData.push(features);
    // In a real system, we might trigger re-training here or periodically
  }

  /**
   * Train the internal models on ingested data.
   */
  train() {
    if (this.trainingData.length < this.clusteringModel.k) {
      console.warn(
        '[PatternDetector] Not enough data to train. Need ' + this.clusteringModel.k + ' samples.'
      );
      return;
    }

    const result = this.clusteringModel.fit(this.trainingData);
    this.isTrained = true;
    return result;
  }

  /**
   * Disable "shadow mode" and return active predictions for a session.
   * @param {Object} session
   */
  analyze(session) {
    if (!this.isTrained) {
      return { patternId: -1, confidence: 0, reason: 'Model not trained' };
    }

    const features = this.featureEngineer.extractFeatures(session);
    const prediction = this.clusteringModel.predict(features);

    return {
      patternId: prediction.clusterId,
      distance: prediction.distance,
      features,
      // In V2, we would calculate distance-to-centroid as confidence
      confidence: Math.max(0, 1.0 - prediction.distance),
    };
  }

  /**
   * Save the current model state to disk.
   * @param {string} filepath
   */
  saveModel(filepath) {
    if (!this.isTrained) return;
    const state = this.clusteringModel.serialize();
    fs.mkdirSync(path.dirname(filepath), { recursive: true });
    fs.writeFileSync(filepath, JSON.stringify(state, null, 2));
  }

  /**
   * Load a model state from disk.
   * @param {string} filepath
   */
  loadModel(filepath) {
    if (!fs.existsSync(filepath)) return false;
    try {
      const data = JSON.parse(fs.readFileSync(filepath, 'utf8'));
      this.clusteringModel = KMeans.deserialize(data);
      this.isTrained = true;
      return true;
    } catch (err) {
      console.error('[PatternDetector] Failed to load model:', err);
      return false;
    }
  }

function calculateHookStats(metrics) {
  // Group by hook
  const byHook = {};

  metrics.forEach(metric => {
    if (!byHook[metric.hook]) {
      byHook[metric.hook] = {
        count: 0,
        totalTime: 0,
        times: [],
        successes: 0,
        failures: 0,
      };
    }

    const stats = byHook[metric.hook];
    stats.count++;
    stats.totalTime += metric.executionTimeMs;
    stats.times.push(metric.executionTimeMs);

    if (metric.status === 'success') {
      stats.successes++;
    } else {
      stats.failures++;
    }
  });

  // Calculate averages and percentiles
  const stats = {};
  for (const [hook, data] of Object.entries(byHook)) {
    data.times.sort((a, b) => a - b);

    const p50Index = Math.floor(data.times.length * 0.5);
    const p95Index = Math.floor(data.times.length * 0.95);
    const p99Index = Math.floor(data.times.length * 0.99);

    stats[hook] = {
      count: data.count,
      avgTime: data.totalTime / data.count,
      p50: data.times[p50Index] || 0,
      p95: data.times[p95Index] || 0,
      p99: data.times[p99Index] || 0,
      successRate: (data.successes / data.count) * 100,
      failures: data.failures,
    };
  }

  return stats;
}

function calculateErrorStats(metrics) {
  // Group by type and severity
  const byType = {};
  const bySeverity = {};
  const bySource = {};

  metrics.forEach(metric => {
    // By type
    byType[metric.errorType] = (byType[metric.errorType] || 0) + 1;

    // By severity
    bySeverity[metric.severity] = (bySeverity[metric.severity] || 0) + 1;

    // By source
    bySource[metric.source] = (bySource[metric.source] || 0) + 1;
  });

  // Top errors
  const topErrors = Object.entries(byType)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([type, count]) => ({ type, count }));

  const topSources = Object.entries(bySource)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([source, count]) => ({ source, count }));

  return {
    total: metrics.length,
    byType,
    bySeverity,
    bySource,
    topErrors,
    topSources,
  };
}

function findSlowHooks(stats, threshold = 10) {
  const slow = [];

  for (const [hook, data] of Object.entries(stats)) {
    if (data.avgTime > threshold) {
      slow.push({
        hook,
        avgTime: data.avgTime,
        p95: data.p95,
        count: data.count,
      });
    }
  }

  return slow.sort((a, b) => b.avgTime - a.avgTime);
}

class FeatureEngineer {
  constructor() {
    this.agentVocabulary = new Map();
    this.toolVocabulary = new Map();
    this.nextAgentId = 1;
    this.nextToolId = 1;
  }

  /**
   * extracting features from a completed workflow session
   * @param {Object} sessionData - The raw session data (metrics, trace, history)
   * @returns {Object} Normalized feature vector
   */
  extractFeatures(sessionData) {
    const { history = [], metrics = {} } = sessionData;
    const rawLength = history.length;
    // Normalize sequenceLength so long history does not dominate Euclidean distance (0-500 -> 0-1)
    const SEQUENCE_LENGTH_CAP = 500;
    const sequenceLength = Math.max(0, Math.min(1, rawLength / SEQUENCE_LENGTH_CAP));

    const totalDuration = metrics.totalDuration ?? 0;
    const historyLen = Math.max(1, rawLength);

    return {
      // Sequence Features (One-Hot / Integer Encoded)
      agentSequence: this._encodeSequence(
        history.map(h => h.agent),
        this.agentVocabulary
      ),
      toolSequence: this._encodeSequence(
        history.flatMap(h => h.tools || []),
        this.toolVocabulary
      ),
      sequenceLength,

      // Timing Features (Normalized)
      totalDuration: this._normalize(totalDuration, 0, 3600000), // Max 1 hour
      avgTaskDuration: this._normalize(totalDuration / historyLen, 0, 300000), // Max 5 mins

      // Error Features
      errorRate: (metrics.errorCount ?? 0) / historyLen,
      hasCriticalError: (metrics.criticalErrors ?? 0) > 0 ? 1 : 0,

      // Resource Features
      totalTokens: this._normalize(metrics.tokenUsage ?? 0, 0, 100000), // Max 100k tokens
      peakMemory: this._normalize(metrics.peakMemoryMB ?? 0, 0, 1024), // Max 1GB
    };
  }

  /**
   * Normalize a value between 0 and 1 based on min/max range.
   */
  _normalize(value, min, max) {
    return Math.max(0, Math.min(1, (value - min) / (max - min)));
  }

  /**
   * Encode a sequence of strings into integer IDs (simplified embedding).
   */
  _encodeSequence(items, vocabulary) {
    return items.map(item => {
      if (!vocabulary.has(item)) {
        vocabulary.set(item, vocabulary.size + 1);
      }
      return vocabulary.get(item);
    });
  }

function getRecencyScore(lastAccessed) {
  if (!lastAccessed) return 0;

  const accessDate = new Date(lastAccessed);
  if (isNaN(accessDate.getTime())) return 0;

  const now = new Date();
  const daysSinceAccess = (now - accessDate) / (1000 * 60 * 60 * 24);

  if (daysSinceAccess < 0) return 1; // Future date = treat as current

  // Exponential decay with half-life
  const decayFactor = Math.log(2) / CONFIG.RECENCY_HALF_LIFE_DAYS;
  const score = Math.exp(-decayFactor * daysSinceAccess);

  // Ensure score stays in [0, 1] range
  return Math.max(0, Math.min(1, score));
}

function getFrequencyScore(accessCount) {
  if (!accessCount || accessCount <= 0) return 0;

  // Logarithmic scaling: log(count+1) / log(maxCount+1)
  const score = Math.log(accessCount + 1) / Math.log(CONFIG.FREQUENCY_MAX_COUNT + 1);

  // Cap at 1.0
  return Math.min(1.0, score);
}

function getImportanceScore(entry) {
  // Handle null/undefined entry gracefully
  if (!entry) return CONFIG.BASE_IMPORTANCE;
  const text = entry.text || entry.content || entry.description || '';

  let maxWeight = CONFIG.BASE_IMPORTANCE;

  // Check all markers and take the highest weight
  for (const marker of IMPORTANCE_MARKERS) {
    if (marker.pattern.test(text)) {
      maxWeight = Math.max(maxWeight, marker.weight);
    }
  }

  return maxWeight;
}

function calculateUtility(entry) {
  const recencyScore = getRecencyScore(entry.lastAccessed || entry.last_accessed);
  const frequencyScore = getFrequencyScore(entry.accessCount || entry.access_count || 1);
  const importanceScore = getImportanceScore(entry);

  return (
    CONFIG.RECENCY_WEIGHT * recencyScore +
    CONFIG.FREQUENCY_WEIGHT * frequencyScore +
    CONFIG.IMPORTANCE_WEIGHT * importanceScore
  );
}

function jaccardSimilarity(str1, str2) {
  if (!str1 || !str2) return 0;

  // Tokenize: lowercase, split by non-word chars, filter empty
  const tokenize = s =>
    new Set(
      s
        .toLowerCase()
        .split(/\W+/)
        .filter(word => word.length > 0)
    );

  const set1 = tokenize(str1);
  const set2 = tokenize(str2);

  if (set1.size === 0 && set2.size === 0) return 1;
  if (set1.size === 0 || set2.size === 0) return 0;

  // Calculate intersection
  const intersection = new Set([...set1].filter(x => set2.has(x)));

  // Calculate union
  const union = new Set([...set1, ...set2]);

  return intersection.size / union.size;
}

function findSimilarEntries(entries, threshold = CONFIG.DEFAULT_SIMILARITY_THRESHOLD) {
  if (!entries || entries.length === 0) return [];

  const groups = [];
  const assigned = new Set();

  for (let i = 0; i < entries.length; i++) {
    if (assigned.has(i)) continue;

    const group = [entries[i]];
    assigned.add(i);

    for (let j = i + 1; j < entries.length; j++) {
      if (assigned.has(j)) continue;

      const text1 = entries[i].text || entries[i].content || '';
      const text2 = entries[j].text || entries[j].content || '';
      const similarity = jaccardSimilarity(text1, text2);

      if (similarity >= threshold) {
        group.push(entries[j]);
        assigned.add(j);
      }
    }

    groups.push(group);
  }

  return groups;
}

function mergeEntries(entries) {
  if (!entries || entries.length === 0) return null;
  if (entries.length === 1) return entries[0];

  // Score entries by: importance first, then length
  const scored = entries.map(entry => ({
    entry,
    importance: getImportanceScore(entry),
    length: (entry.text || entry.content || '').length,
  }));

  // Sort by importance (descending), then by length (descending)
  scored.sort((a, b) => {
    if (b.importance !== a.importance) {
      return b.importance - a.importance; // Higher importance first
    }
    return b.length - a.length; // Then longer text
  });

  const bestEntry = scored[0].entry;

  // Aggregate metadata
  const merged = {
    ...bestEntry,
    // Keep highest access count (or sum)
    accessCount: Math.max(...entries.map(e => e.accessCount || e.access_count || 1)),
    // Keep most recent access time
    lastAccessed: entries.reduce((latest, e) => {
      const current = e.lastAccessed || e.last_accessed;
      if (!latest) return current;
      if (!current) return latest;
      return new Date(current) > new Date(latest) ? current : latest;
    }, null),
    // Keep earliest timestamp (original creation)
    timestamp: entries.reduce((earliest, e) => {
      const current = e.timestamp;
      if (!earliest) return current;
      if (!current) return earliest;
      return new Date(current) < new Date(earliest) ? current : earliest;
    }, null),
    // Mark as merged
    _merged: true,
    _mergedFrom: entries.length,
  };

  return merged;
}

function detectDuplicates(
  newText,
  existingEntries,
  threshold = CONFIG.DEFAULT_SIMILARITY_THRESHOLD
) {
  if (!newText || !existingEntries || existingEntries.length === 0) return null;

  for (const entry of existingEntries) {
    const existingText = entry.text || entry.content || '';
    const similarity = jaccardSimilarity(newText, existingText);

    if (similarity >= threshold) {
      return entry;
    }
  }

  return null;
}

function pruneByUtility(entries, targetCount) {
  if (!entries || entries.length === 0) {
    return { kept: [], removed: [] };
  }

  if (entries.length <= targetCount) {
    return { kept: entries, removed: [] };
  }

  // Calculate utility for each entry
  const withUtility = entries.map(entry => ({
    entry,
    utility: calculateUtility(entry),
  }));

  // Sort by utility descending (highest first)
  withUtility.sort((a, b) => b.utility - a.utility);

  // Split into kept and removed
  const kept = withUtility.slice(0, targetCount).map(x => x.entry);
  const removed = withUtility.slice(targetCount).map(x => x.entry);

  return { kept, removed };
}

function enforceRetention(entries, tier) {
  const limit = RETENTION_LIMITS[tier];

  // LTM has high limit but not unlimited
  if (tier === 'LTM') {
    // For LTM, keep entries but they should be summarized
    // This function just enforces count limits
    if (!limit || entries.length <= limit) {
      return { kept: entries, removed: [], archived: [] };
    }
  }

  if (!limit || entries.length <= limit) {
    return { kept: entries, removed: [], archived: [] };
  }

  const { kept, removed } = pruneByUtility(entries, limit);

  return {
    kept,
    removed,
    archived: [], // Caller can archive if desired
  };
}

function archiveLowValue(entries) {
  if (!entries || entries.length === 0) {
    return {
      type: 'archive',
      entries: [],
      summary: 'No entries to archive',
      created_at: new Date().toISOString(),
    };
  }

  // Extract key themes from entries
  const allText = entries.map(e => e.text || e.content || '').join(' ');
  const words = allText
    .toLowerCase()
    .split(/\W+/)
    .filter(w => w.length > 3);
  const wordCounts = {};
  words.forEach(w => {
    wordCounts[w] = (wordCounts[w] || 0) + 1;
  });

  // Get top keywords
  const topKeywords = Object.entries(wordCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10)
    .map(([word]) => word);

  // Generate summary
  const summary = `Archived ${entries.length} entries. Key topics: ${topKeywords.join(', ')}`;

  return {
    type: 'archive',
    entries: entries.map(e => ({
      text: (e.text || e.content || '').slice(0, 100) + '...',
      timestamp: e.timestamp,
      utility: calculateUtility(e),
    })),
    summary,
    entry_count: entries.length,
    created_at: new Date().toISOString(),
  };
}

async function spawnAgent(sessionId, agentType, role, sharedContext) {
  const spawnTime = Date.now();

  // STEP 1: Generate unique agent ID (SEC-PM-001)
  const agentId = generateAgentId(agentType, spawnTime, sessionId);

  // STEP 2: Isolate context (SEC-PM-004)
  const isolatedContext = isolateContext(sharedContext, agentId, agentType);

  // STEP 3: Create sidecar (SEC-PM-006)
  const { sidecarPath } = await createSidecar(sessionId, agentId, agentType);

  // STEP 4: Track lifecycle state
  lifecycleState.set(agentId, {
    agentId,
    sessionId,
    agentType,
    role,
    status: 'spawned',
    spawnedAt: spawnTime,
    updatedAt: spawnTime,
    sidecarPath,
    statusHistory: [{ status: 'spawned', timestamp: spawnTime }],
  });

  return {
    agentId,
    status: 'spawned',
    timestamp: spawnTime,
    isolatedContext,
  };
}

async function updateAgentStatus(agentId, newStatus) {
  const agent = lifecycleState.get(agentId);

  if (!agent) {
    return {
      updated: false,
      error: `Agent ${agentId} not found in lifecycle state`,
    };
  }

  const previousStatus = agent.status;
  const timestamp = Date.now();

  // Update state
  agent.status = newStatus;
  agent.updatedAt = timestamp;
  agent.statusHistory.push({ status: newStatus, timestamp });

  lifecycleState.set(agentId, agent);

  return {
    updated: true,
    agentId,
    previousStatus,
    newStatus,
  };
}

async function getAgentStatus(agentId) {
  const agent = lifecycleState.get(agentId);

  if (!agent) {
    return null;
  }

  return {
    agentId: agent.agentId,
    agentType: agent.agentType,
    role: agent.role,
    status: agent.status,
    spawnedAt: agent.spawnedAt,
    updatedAt: agent.updatedAt,
  };
}

async function terminateAgent(agentId, reason) {
  const agent = lifecycleState.get(agentId);

  if (!agent) {
    return {
      terminated: false,
      error: `Agent ${agentId} not found`,
    };
  }

  // Update status to terminated
  await updateAgentStatus(agentId, 'terminated');

  // Add termination reason
  agent.terminationReason = reason;
  agent.terminatedAt = Date.now();

  lifecycleState.set(agentId, agent);

  // Note: Sidecar is preserved for audit (not deleted)

  return {
    terminated: true,
    agentId,
  };
}

async function getAllAgents(sessionId) {
  const agents = [];

  for (const [_agentId, agent] of lifecycleState.entries()) {
    if (agent.sessionId === sessionId) {
      agents.push({
        agentId: agent.agentId,
        agentType: agent.agentType,
        role: agent.role,
        status: agent.status,
        timestamp: agent.spawnedAt,
      });
    }
  }

  return agents;
}

class KMeans {
  constructor(k = 5, maxIterations = 100) {
    this.k = k;
    this.maxIterations = maxIterations;
    this.centroids = [];
  }

  /**
   * Train the K-Means model on a dataset of feature vectors.
   * @param {Array<Object>} data - Array of normalized feature objects
   */
  fit(data) {
    if (data.length < this.k) {
      throw new Error(`Insufficient data for clustering. Need at least ${this.k} samples.`);
    }

    // 1. Initialize Centroids (Random Pick)
    this.centroids = this._initializeCentroids(data);

    let iterations = 0;
    let oldCentroids = [];

    // 2. Iterate until convergence
    do {
      oldCentroids = JSON.parse(JSON.stringify(this.centroids));
      const clusters = this._assignClusters(data);
      this._updateCentroids(clusters);
      iterations++;
    } while (!this._hasConverged(oldCentroids, this.centroids) && iterations < this.maxIterations);

    return {
      iterations,
      centroids: this.centroids,
    };
  }

  /**
   * Predict the cluster for a single feature vector
   * @param {Object} features
   * @returns {{clusterId: number, distance: number}} Cluster ID (0 to K-1) and distance-to-centroid
   */
  predict(features) {
    let bestCluster = -1;
    let minDistance = Infinity;

    this.centroids.forEach((centroid, index) => {
      const dist = this._euclideanDistance(features, centroid);
      if (dist < minDistance) {
        minDistance = dist;
        bestCluster = index;
      }
    });

    return { clusterId: bestCluster, distance: minDistance };
  }

  _assignClusters(data) {
    const clusters = Array.from({ length: this.k }, () => []);
    data.forEach(point => {
      const prediction = this.predict(point);
      if (typeof prediction.clusterId === 'number' && clusters[prediction.clusterId]) {
        clusters[prediction.clusterId].push(point);
      }
    });
    return clusters;
  }

  _updateCentroids(clusters) {
    this.centroids = clusters.map(cluster => {
      if (cluster.length === 0) return this._randomPoint(); // Reset empty clusters

      const mean = {};
      const keys = Object.keys(cluster[0]); // Feature keys (agentSequence, totalDuration, etc)

      keys.forEach(key => {
        if (Array.isArray(cluster[0][key])) {
          // For sequence arrays, we just avg length for simplicity in v1
          // True sequence averaging requires DTW or embedding averaging
          mean[key] = cluster.reduce((sum, p) => sum + p[key].length, 0) / cluster.length;
        } else {
          mean[key] = cluster.reduce((sum, p) => sum + p[key], 0) / cluster.length;
        }
      });
      return mean;
    });
  }

  _hasConverged(oldC, newC) {
    return JSON.stringify(oldC) === JSON.stringify(newC);
  }

  _initializeCentroids(data) {
    // MaxMin Initialization (Simple K-Means++ approximation)
    // 1. Pick first centroid randomly
    const centroids = [data[Math.floor(Math.random() * data.length)]];

    // 2. Pick remaining K-1 centroids
    while (centroids.length < this.k) {
      let maxDist = -1;
      let farthestPoint = null;

      for (const point of data) {
        // Find distance to nearest existing centroid
        let minDistToCentroid = Infinity;
        for (const c of centroids) {
          const d = this._euclideanDistance(point, c);
          if (d < minDistToCentroid) minDistToCentroid = d;
        }

        // Keep the point that is farthest from its nearest centroid
        if (minDistToCentroid > maxDist) {
          maxDist = minDistToCentroid;
          farthestPoint = point;
        }
      }

      centroids.push(farthestPoint);
    }

    return centroids;
  }

  _euclideanDistance(a, b) {
    let sum = 0;
    Object.keys(a).forEach(key => {
      // Skip array features (sequences) in distance calc for V1
      if (Array.isArray(a[key]) || Array.isArray(b[key])) return;

      const valA = a[key] || 0;
      const valB = b[key] || 0;
      sum += Math.pow(valA - valB, 2);
    });
    return Math.sqrt(sum);
  }

  _randomPoint() {
    return {};
  }

  /**
   * Export model state
   */
  serialize() {
    return {
      k: this.k,
      centroids: this.centroids,
      maxIterations: this.maxIterations,
    };
  }

  /**
   * Import model state
   */
  static deserialize(data) {
    const kmeans = new KMeans(data.k, data.maxIterations);
    kmeans.centroids = data.centroids;
    return kmeans;
  }

class OptimizationEngine {
  constructor(patternDetector, config = {}) {
    this.patternDetector = patternDetector;
    this.policies = config.policies || this._getDefaultPolicies();
    this.persistencePath = config.persistencePath || null;
  }

  /**
   * Check whether the engine can produce useful recommendations.
   * Requires a trained PatternDetector; otherwise optimize() will return null.
   * @returns {{ ready: boolean, reason?: string }}
   */
  isReady() {
    if (!this.patternDetector) {
      return { ready: false, reason: 'No pattern detector configured' };
    }
    if (!this.patternDetector.isTrained) {
      return {
        ready: false,
        reason:
          'Pattern detector not trained; run FeedbackLoop.process(session) at SessionEnd until retrain triggers',
      };
    }
    return { ready: true };
  }

  /**
   * Analyze a completed session and recommend configuration changes for next time.
   * Returns null if not ready (use isReady() first). Recommendations are advisory-only
   * unless ML_AUTOMATION_MODE=enforce (caller must apply or log).
   * @param {Object} session - The completed workflow session data { history, metrics, trace }
   * @returns {Object|null} Configuration overrides or null if no recommendation
   */
  optimize(session) {
    const readiness = this.isReady();
    if (!readiness.ready) {
      return null;
    }

    const verification = this.patternDetector.analyze(session);

    // logic: If valid pattern found, lookup policy
    if (verification.patternId !== -1 && this.policies[verification.patternId]) {
      // In a real system, we might merge this with existing config
      // For V1, we return the specific policy overrides
      return {
        ...this.policies[verification.patternId],
        _meta: {
          reason: `Matched Pattern ${verification.patternId} (Confidence: ${verification.confidence})`,
          patternId: verification.patternId,
        },
      };
    }

    return null;
  }

  /**
   * Save current policies to disk
   */
  savePolicies() {
    if (!this.persistencePath) return;
    fs.writeFileSync(this.persistencePath, JSON.stringify(this.policies, null, 2));
  }

  /**
   * Load policies from disk
   */
  loadPolicies() {
    if (!this.persistencePath || !fs.existsSync(this.persistencePath)) return;
    try {
      this.policies = JSON.parse(fs.readFileSync(this.persistencePath, 'utf8'));
    } catch (err) {
      console.error('[OptimizationEngine] Failed to load policies:', err);
    }
  }

  _getDefaultPolicies() {
    return {
      // Cluster 0 (e.g., Quick/Small Tasks) -> High Concurrency, Fast Model
      0: {
        maxConcurrency: 50,
        modelPreference: 'fast-v1',
        retryLimit: 1,
      },
      // Cluster 1 (e.g., Heavy/Architectural) -> Low Concurrency, Smart Model
      1: {
        maxConcurrency: 5,
        modelPreference: 'reasoning-v1',
        retryLimit: 5,
      },
    };
  }

function checkHeapUsage(heapUsed) {
  const { heapLimit, warning, critical } = ALERT_THRESHOLDS.memory;
  const percentage = heapUsed / heapLimit;

  if (percentage >= critical) {
    return {
      triggered: true,
      level: 'CRITICAL',
      message: `Heap usage CRITICAL: ${(percentage * 100).toFixed(1)}% (${(heapUsed / 1024 / 1024).toFixed(0)} MB / ${(heapLimit / 1024 / 1024).toFixed(0)} MB)`,
      action: 'Restart service, investigate memory leak',
    };
  }

  if (percentage >= warning) {
    return {
      triggered: true,
      level: 'WARNING',
      message: `Heap usage WARNING: ${(percentage * 100).toFixed(1)}% (${(heapUsed / 1024 / 1024).toFixed(0)} MB / ${(heapLimit / 1024 / 1024).toFixed(0)} MB)`,
      action: 'Monitor closely, prepare for scaling',
    };
  }

  return { triggered: false, level: 'OK', percentage };
}

function checkMLLatency(feature, latency) {
  const thresholds = ALERT_THRESHOLDS.ml[`${feature}Latency`];
  if (!thresholds) {
    throw new Error(`Unknown ML feature: ${feature}`);
  }

  if (latency >= thresholds.critical) {
    return {
      triggered: true,
      level: 'CRITICAL',
      message: `${feature} latency CRITICAL: ${latency}ms (threshold: ${thresholds.critical}ms)`,
      action: 'Disable feature, investigate bottleneck',
    };
  }

  if (latency >= thresholds.warning) {
    return {
      triggered: true,
      level: 'WARNING',
      message: `${feature} latency WARNING: ${latency}ms (threshold: ${thresholds.warning}ms)`,
      action: 'Monitor for sustained high latency',
    };
  }

  return { triggered: false, level: 'OK', latency };
}

function checkErrorRate(errors, total, windowSeconds = 60) {
  const rate = total > 0 ? errors / total : 0;
  const { warningRate, criticalRate, spikeThreshold } = ALERT_THRESHOLDS.errors;

  // Check for error spike (absolute count)
  if (errors >= spikeThreshold && windowSeconds <= 60) {
    return {
      triggered: true,
      level: 'CRITICAL',
      message: `Error SPIKE: ${errors} errors in ${windowSeconds}s (spike threshold: ${spikeThreshold})`,
      action: 'Investigate root cause immediately',
    };
  }

  // Check for sustained high error rate
  if (rate >= criticalRate) {
    return {
      triggered: true,
      level: 'CRITICAL',
      message: `Error rate CRITICAL: ${(rate * 100).toFixed(2)}% (${errors}/${total} in ${windowSeconds}s)`,
      action: 'Rollback deployment, investigate',
    };
  }

  if (rate >= warningRate) {
    return {
      triggered: true,
      level: 'WARNING',
      message: `Error rate WARNING: ${(rate * 100).toFixed(2)}% (${errors}/${total} in ${windowSeconds}s)`,
      action: 'Monitor error logs, prepare rollback',
    };
  }

  return { triggered: false, level: 'OK', rate };
}

function checkConcurrentWorkflows(count) {
  const { warning, critical, max } = ALERT_THRESHOLDS.concurrency;

  if (count >= max) {
    return {
      triggered: true,
      level: 'CRITICAL',
      message: `Concurrent workflows MAX: ${count} (max: ${max}) - Load shedding activated`,
      action: 'Reject new workflows (429), scale horizontally',
    };
  }

  if (count >= critical) {
    return {
      triggered: true,
      level: 'CRITICAL',
      message: `Concurrent workflows CRITICAL: ${count} (threshold: ${critical})`,
      action: 'Scale immediately, prepare load shedding',
    };
  }

  if (count >= warning) {
    return {
      triggered: true,
      level: 'WARNING',
      message: `Concurrent workflows WARNING: ${count} (threshold: ${warning})`,
      action: 'Monitor capacity, prepare scaling',
    };
  }

  return { triggered: false, level: 'OK', count };
}

function checkSystemHealth(metrics) {
  const alerts = [];

  // Memory
  if (metrics.heapUsed) {
    const memAlert = checkHeapUsage(metrics.heapUsed);
    if (memAlert.triggered) alerts.push({ component: 'memory', ...memAlert });
  }

  // ML Features
  if (metrics.ml) {
    if (metrics.ml.patternDetectionLatency) {
      const mlAlert = checkMLLatency('patternDetection', metrics.ml.patternDetectionLatency);
      if (mlAlert.triggered) alerts.push({ component: 'ml-pattern-detection', ...mlAlert });
    }
    if (metrics.ml.costPredictionLatency) {
      const mlAlert = checkMLLatency('costPrediction', metrics.ml.costPredictionLatency);
      if (mlAlert.triggered) alerts.push({ component: 'ml-cost-prediction', ...mlAlert });
    }
    if (metrics.ml.adaptiveExecutorLatency) {
      const mlAlert = checkMLLatency('adaptiveExecutor', metrics.ml.adaptiveExecutorLatency);
      if (mlAlert.triggered) alerts.push({ component: 'ml-adaptive-executor', ...mlAlert });
    }
  }

  // Error Rate
  if (metrics.errors !== undefined && metrics.totalOperations) {
    const errorAlert = checkErrorRate(
      metrics.errors,
      metrics.totalOperations,
      metrics.windowSeconds || 60
    );
    if (errorAlert.triggered) alerts.push({ component: 'error-rate', ...errorAlert });
  }

  // Concurrency
  if (metrics.concurrentWorkflows) {
    const concurrencyAlert = checkConcurrentWorkflows(metrics.concurrentWorkflows);
    if (concurrencyAlert.triggered) alerts.push({ component: 'concurrency', ...concurrencyAlert });
  }

  return {
    healthy: alerts.length === 0,
    alerts,
    criticalCount: alerts.filter(a => a.level === 'CRITICAL').length,
    warningCount: alerts.filter(a => a.level === 'WARNING').length,
  };
}

function ensureDir() {
  if (!fs.existsSync(METRICS_DIR)) {
    fs.mkdirSync(METRICS_DIR, { recursive: true });
  }
}

function trimIfNeeded() {
  if (!Number.isFinite(MAX_LINES) || MAX_LINES <= 0) return;
  try {
    if (!fs.existsSync(SPAWN_LOG_PATH)) return;
    const content = fs.readFileSync(SPAWN_LOG_PATH, 'utf8');
    const lines = content.split('\n').filter(Boolean);
    if (lines.length <= MAX_LINES) return;
    const trimmed = lines.slice(lines.length - MAX_LINES).join('\n') + '\n';
    fs.writeFileSync(SPAWN_LOG_PATH, trimmed, 'utf8');
  } catch (_err) {
    // best-effort
  }
}

function append(entry) {
  try {
    ensureDir();
    const line = JSON.stringify({
      ...entry,
      timestamp: entry.timestamp || new Date().toISOString(),
    });
    fs.appendFileSync(SPAWN_LOG_PATH, `${line}\n`, 'utf8');
    trimIfNeeded();
  } catch (_err) {
    // best-effort
  }
}

function extractKeyPoints(response) {
  // Handle both formats: response.content (direct) and response.response (from aggregateResponses)
  const content = response.content || response.response || '';

  const keyPoints = {
    decisions: [],
    actionItems: [],
    concerns: [],
  };

  // Extract decisions (recommendations, choices)
  const decisionPatterns = [
    /\b(?:recommend|suggest|propose|choose|use)\s+([^.!?]+)/gi,
    /\b(?:should|must|need to)\s+([^.!?]+)/gi,
  ];

  for (const pattern of decisionPatterns) {
    const matches = content.matchAll(pattern);
    for (const match of matches) {
      const decision = match[0].trim();
      if (decision.length > 10 && decision.length < 200) {
        keyPoints.decisions.push(decision);
      }
    }
  }

  // Extract action items (tasks, todos)
  const actionPatterns = [
    /\b(?:we need to|let me|should|must)\s+([^.!?]+)/gi,
    /\b(?:write|update|implement|create|add)\s+([^.!?]+)/gi,
  ];

  for (const pattern of actionPatterns) {
    const matches = content.matchAll(pattern);
    for (const match of matches) {
      const action = match[0].trim();
      if (action.length > 10 && action.length < 200) {
        keyPoints.actionItems.push(action);
      }
    }
  }

  // Extract concerns (risks, issues) - look for complete sentences
  const sentences = content.split(/[.!?]+/);
  for (const sentence of sentences) {
    const lowerSentence = sentence.toLowerCase();
    if (
      lowerSentence.includes('concern') ||
      lowerSentence.includes('risk') ||
      lowerSentence.includes('issue') ||
      lowerSentence.includes('problem') ||
      lowerSentence.includes('worry')
    ) {
      const trimmed = sentence.trim();
      if (trimmed.length > 15 && trimmed.length < 200) {
        keyPoints.concerns.push(trimmed);
      }
    }
  }

  // Deduplicate
  keyPoints.decisions = [...new Set(keyPoints.decisions)];
  keyPoints.actionItems = [...new Set(keyPoints.actionItems)];
  keyPoints.concerns = [...new Set(keyPoints.concerns)];

  return keyPoints;
}

function identifyAgreements(responses) {
  const agreements = [];
  const themes = new Map(); // theme -> Set<agentId>

  // Extract themes from each response
  for (const response of responses) {
    const content = (response.content || response.response || '').toLowerCase();
    const keywords = extractKeywords(content);

    for (const keyword of keywords) {
      if (!themes.has(keyword)) {
        themes.set(keyword, new Set());
      }
      themes.get(keyword).add(response.agentId);
    }
  }

  // Identify themes with 2+ agents agreeing
  for (const [theme, agentIds] of themes.entries()) {
    if (agentIds.size >= 2) {
      const confidence = agentIds.size / responses.length;
      agreements.push({
        theme,
        agentIds: Array.from(agentIds),
        confidence,
      });
    }
  }

  // Sort by confidence (highest first)
  agreements.sort((a, b) => b.confidence - a.confidence);

  return agreements;
}

function extractKeywords(content) {
  const keywords = [];
  const stopWords = new Set([
    'a',
    'an',
    'the',
    'is',
    'are',
    'was',
    'were',
    'be',
    'been',
    'for',
    'to',
    'of',
    'in',
    'on',
    'at',
    'by',
    'with',
    'from',
    'as',
    'and',
    'or',
    'but',
    'if',
    'we',
    'i',
    'you',
    'they',
    'this',
    'that',
    'it',
    'should',
    'will',
    'can',
    'would',
  ]);

  // Extract 2-3 word phrases
  const words = content
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !stopWords.has(w));

  for (let i = 0; i < words.length - 1; i++) {
    const bigram = `${words[i]} ${words[i + 1]}`;
    keywords.push(bigram);

    if (i < words.length - 2) {
      const trigram = `${words[i]} ${words[i + 1]} ${words[i + 2]}`;
      keywords.push(trigram);
    }
  }

  // Also include significant single words
  const significantWords = words.filter(
    w =>
      w.length > 5 ||
      /^(typescript|postgresql|mongodb|jwt|api|database|security|caching|test)$/.test(w)
  );
  keywords.push(...significantWords);

  return keywords;
}

function identifyDisagreements(responses) {
  const disagreements = [];

  // Look for explicit disagreement markers
  const disagreementMarkers = [
    'disagree',
    'however',
    'but',
    'alternatively',
    'instead',
    'prefer',
    'rather than',
  ];

  const responsesWithDisagreement = responses.filter(r => {
    const content = (r.content || r.response || '').toLowerCase();
    return disagreementMarkers.some(marker => content.includes(marker));
  });

  if (responsesWithDisagreement.length === 0) {
    return disagreements;
  }

  // Extract topics and stances
  const topics = new Map(); // topic -> [{ agentId, stance }]

  for (const response of responses) {
    const content = response.content || response.response || '';

    // Extract topic (look for database/framework/approach keywords)
    const topicKeywords = [
      { keyword: 'postgresql', topic: 'database' },
      { keyword: 'mongodb', topic: 'database' },
      { keyword: 'mysql', topic: 'database' },
      { keyword: 'database', topic: 'database' },
      { keyword: 'authentication', topic: 'authentication' },
      { keyword: 'jwt', topic: 'authentication' },
      { keyword: 'session', topic: 'authentication' },
      { keyword: 'cookie', topic: 'authentication' },
      { keyword: 'framework', topic: 'framework' },
      { keyword: 'architecture', topic: 'architecture' },
      { keyword: 'approach', topic: 'approach' },
      { keyword: 'technology', topic: 'technology' },
      { keyword: 'tool', topic: 'tool' },
    ];

    let topic = 'general';
    for (const { keyword, topic: topicName } of topicKeywords) {
      if (content.toLowerCase().includes(keyword)) {
        topic = topicName;
        break;
      }
    }

    // Extract stance (main recommendation)
    const stanceMatch = content.match(
      /\b(?:recommend|prefer|suggest|choose|use)\s+([A-Za-z0-9\s]+?)(?:\s+for|\s+because|\.|,)/i
    );
    const stance = stanceMatch ? stanceMatch[1].trim() : content.substring(0, 100);

    if (!topics.has(topic)) {
      topics.set(topic, []);
    }

    topics.get(topic).push({
      agentId: response.agentId,
      agentType: response.agentType,
      stance,
    });
  }

  // Create disagreement objects for topics with conflicting stances
  for (const [topic, positions] of topics.entries()) {
    if (positions.length >= 2) {
      // Check if stances are different
      const uniqueStances = new Set(positions.map(p => p.stance.toLowerCase().substring(0, 20)));
      if (uniqueStances.size >= 2) {
        disagreements.push({
          topic,
          positions,
        });
      }
    }
  }

  return disagreements;
}

function aggregateResponses(sessionId, round, agentResponses) {
  // Extract key points from all responses
  const allKeyPoints = agentResponses.map(extractKeyPoints);

  // Identify agreements and disagreements
  const agreements = identifyAgreements(agentResponses);
  const disagreements = identifyDisagreements(agentResponses);

  // Generate summary
  let summary = `Round ${round} with ${agentResponses.length} agents:\n`;

  if (agreements.length > 0) {
    const topAgreement = agreements[0];
    summary += `- Consensus: ${topAgreement.theme} (${Math.round(topAgreement.confidence * 100)}% agreement)\n`;
  }

  if (disagreements.length > 0) {
    summary += `- ${disagreements.length} point(s) of disagreement detected\n`;
    for (const disagreement of disagreements) {
      summary += `  * ${disagreement.topic}: ${disagreement.positions.length} different positions\n`;
    }
  }

  // Count total decisions and action items
  const totalDecisions = allKeyPoints.reduce((sum, kp) => sum + kp.decisions.length, 0);
  const totalActions = allKeyPoints.reduce((sum, kp) => sum + kp.actionItems.length, 0);
  const totalConcerns = allKeyPoints.reduce((sum, kp) => sum + kp.concerns.length, 0);

  summary += `- ${totalDecisions} decision(s), ${totalActions} action item(s), ${totalConcerns} concern(s) raised`;

  return {
    sessionId,
    round,
    agreements,
    disagreements,
    summary,
    keyPoints: allKeyPoints,
  };
}

function formatNumber(num) {
  return num.toLocaleString('en-US');
}

function formatTime(ms) {
  if (ms < 1) {
    return `${(ms * 1000).toFixed(0)}µs`;
  }
  if (ms < 1000) {
    return `${ms.toFixed(2)}ms`;
  }
  return `${(ms / 1000).toFixed(2)}s`;
}

function formatPercent(percent) {
  return `${percent.toFixed(1)}%`;
}

function renderTable(headers, rows) {
  // Calculate column widths
  const widths = headers.map((header, i) => {
    const maxRowWidth = Math.max(...rows.map(row => String(row[i] || '').length));
    return Math.max(header.length, maxRowWidth);
  });

  // Render header
  const headerLine = headers.map((h, i) => h.padEnd(widths[i])).join('  ');
  const separator = widths.map(w => '-'.repeat(w)).join('  ');

  const lines = [headerLine, separator];

  // Render rows
  rows.forEach(row => {
    const line = row.map((cell, i) => String(cell || '').padEnd(widths[i])).join('  ');
    lines.push(line);
  });

  return lines.join('\n');
}

function renderBox(title, content, width = 70) {
  const top = '╔' + '═'.repeat(width - 2) + '╗';
  const titleLine = '║ ' + title.padEnd(width - 4) + ' ║';
  const separator = '╠' + '═'.repeat(width - 2) + '╣';
  const bottom = '╚' + '═'.repeat(width - 2) + '╝';

  const contentLines = content.split('\n').map(line => '║ ' + line.padEnd(width - 4) + ' ║');

  return [top, titleLine, separator, ...contentLines, bottom].join('\n');
}

function renderAlert(alert) {
  const icons = {
    CRITICAL: '🔴',
    HIGH: '🟡',
    MEDIUM: '🟠',
    LOW: '🔵',
  };

  const icon = icons[alert.severity] || '⚪';
  return `${icon} [${alert.severity}] ${alert.message}`;
}

function renderHookPerformance(summary) {
  const lines = [];

  lines.push('HOOK PERFORMANCE:');
  lines.push(`  Total calls:      ${formatNumber(summary.hooks.total)}`);
  lines.push(`  Avg execution:    ${formatTime(summary.hooks.avgTime)}`);
  lines.push(`  Failure rate:     ${formatPercent(summary.hooks.failureRate)}`);
  lines.push('');

  // Top hooks by count
  const topHooks = Object.entries(summary.hooks.byHook)
    .sort((a, b) => b[1].count - a[1].count)
    .slice(0, 5);

  if (topHooks.length > 0) {
    lines.push('  Top hooks by frequency:');
    topHooks.forEach(([hook, stats]) => {
      lines.push(
        `    ${hook.padEnd(30)} ${formatTime(stats.avgTime).padStart(8)}  ${formatNumber(stats.count)} calls`
      );
    });
  }

  return lines.join('\n');
}

function renderErrorStats(summary) {
  const lines = [];

  lines.push('ERROR STATISTICS:');
  lines.push(`  Total errors:     ${formatNumber(summary.errors.total)}`);
  lines.push('');

  // By severity
  if (summary.errors.bySeverity && Object.keys(summary.errors.bySeverity).length > 0) {
    lines.push('  By severity:');
    for (const [severity, count] of Object.entries(summary.errors.bySeverity)) {
      lines.push(`    ${severity.padEnd(12)} ${formatNumber(count)}`);
    }
    lines.push('');
  }

  // Top error types
  if (summary.errors.topErrors && summary.errors.topErrors.length > 0) {
    lines.push('  Top error types:');
    summary.errors.topErrors.forEach(error => {
      lines.push(`    ${error.type.padEnd(25)} ${formatNumber(error.count)} occurrences`);
    });
  }

  return lines.join('\n');
}

function renderAlerts(alerts) {
  if (alerts.length === 0) {
    return 'ALERTS:\n  ✓ No alerts';
  }

  const lines = ['ALERTS:'];
  alerts.forEach(alert => {
    lines.push(`  ${renderAlert(alert)}`);
  });

  return lines.join('\n');
}

function renderDashboard(summary, alerts = []) {
  const title = `Agent Studio Monitoring Dashboard - Last ${summary.period.hours}h`;

  const sections = [
    '',
    renderHookPerformance(summary),
    '',
    renderErrorStats(summary),
    '',
    renderAlerts(alerts),
    '',
  ];

  const content = sections.join('\n');

  return renderBox(title, content, 80);
}

