    content: agentContribution.content,
    hash: agentContribution.hash,
    timestamp: agentContribution.timestamp,
    // EXPLICITLY EXCLUDED:
    // - rawThinking
    // - toolCalls
    // - memoryAccess
  };

  // Append to previousResponses
  if (!sharedContext.previousResponses) {
    sharedContext.previousResponses = [];
  }

  sharedContext.previousResponses.push(publicContribution);

  return sharedContext;
}

function initializeChain(sessionId) {
  // Generate genesis hash from session ID and timestamp
  const timestamp = new Date().toISOString();
  const input = `genesis:${sessionId}:${timestamp}`;
  const genesisHash = crypto.createHash('sha256').update(input).digest('hex').slice(0, 16);

  return {
    sessionId,
    genesisHash,
    timestamp,
  };
}

function appendResponse(agentId, response, previousHash) {
  const timestamp = new Date().toISOString();
  const content = response.content || JSON.stringify(response);

  // Build hash input: previousHash + agentId + content + timestamp
  const input = `${previousHash}:${agentId}:${content}:${timestamp}`;
  const responseHash = crypto.createHash('sha256').update(input).digest('hex').slice(0, 16);

  return {
    responseHash,
    agentId,
    timestamp,
    previousHash,
    content,
  };
}

function verifyChain(responseChain) {
  if (!responseChain || responseChain.length === 0) {
    return { valid: true, brokenAtIndex: null };
  }

  let expectedPreviousHash = '0';

  for (let i = 0; i < responseChain.length; i++) {
    const response = responseChain[i];

    // Check previous hash matches expected
    if (response.previousHash !== expectedPreviousHash) {
      return {
        valid: false,
        brokenAtIndex: i,
      };
    }

    // Recalculate hash from response data
    const input = `${response.previousHash}:${response.agentId}:${response.content}:${response.timestamp}`;
    const calculatedHash = crypto.createHash('sha256').update(input).digest('hex').slice(0, 16);

    // Check hash matches stored hash
    if (calculatedHash !== response.responseHash) {
      return {
        valid: false,
        brokenAtIndex: i,
      };
    }

    // Update expected previous hash for next iteration
    expectedPreviousHash = response.responseHash;
  }

  return { valid: true, brokenAtIndex: null };
}

function detectTampering(expectedHash, actualResponse) {
  // For simple comparison, just check if expected matches
  // In practice, we'd need the full chain context
  const content = actualResponse.content || JSON.stringify(actualResponse);

  // If response has all needed fields, recalculate hash
  if (actualResponse.previousHash && actualResponse.agentId && actualResponse.timestamp) {
    const input = `${actualResponse.previousHash}:${actualResponse.agentId}:${content}:${actualResponse.timestamp}`;
    const actualHash = crypto.createHash('sha256').update(input).digest('hex').slice(0, 16);

    return {
      tampered: expectedHash !== actualHash,
      expectedHash,
      actualHash,
    };
  }

  // Without full context, just compare content hash
  const simpleHash = crypto.createHash('sha256').update(content).digest('hex').slice(0, 16);

  return {
    tampered: expectedHash !== simpleHash,
    expectedHash,
    actualHash: simpleHash,
  };
}

async function initializeSession(sessionId, teamName) {
  const timestamp = Date.now();

  const state = {
    sessionId,
    teamName,
    round: 0,
    maxRounds: MAX_ROUNDS_PER_SESSION,
    startedAt: timestamp,
    rounds: [], // History of all rounds
  };

  sessionState.set(sessionId, state);

  return {
    sessionId: state.sessionId,
    teamName: state.teamName,
    round: state.round,
    maxRounds: state.maxRounds,
    startedAt: state.startedAt,
  };
}

async function startRound(sessionId) {
  const session = sessionState.get(sessionId);

  if (!session) {
    throw new Error(`Session ${sessionId} not found`);
  }

  // Check round limit (SEC-PM-005)
  if (session.round >= MAX_ROUNDS_PER_SESSION) {
    throw new Error(
      `Round limit of ${MAX_ROUNDS_PER_SESSION} rounds exceeded for session ${sessionId}`
    );
  }

  // Increment round counter
  session.round += 1;

  // Initialize round state
  const roundState = {
    roundNumber: session.round,
    startedAt: Date.now(),
    agentsActive: 0,
    completed: false,
  };

  session.rounds.push(roundState);
  sessionState.set(sessionId, session);

  return {
    sessionId,
    round: session.round,
    agentsActive: roundState.agentsActive,
  };
}

async function completeRound(sessionId) {
  const session = sessionState.get(sessionId);

  if (!session) {
    throw new Error(`Session ${sessionId} not found`);
  }

  if (session.round === 0) {
    throw new Error(`No active round to complete for session ${sessionId}`);
  }

  // Get current round state
  const currentRoundIndex = session.round - 1;
  const roundState = session.rounds[currentRoundIndex];

  // Mark as completed
  roundState.completed = true;
  roundState.completedAt = Date.now();

  sessionState.set(sessionId, session);

  return {
    sessionId,
    round: session.round,
    completed: true,
    completedAt: roundState.completedAt,
  };
}

async function getRoundStatus(sessionId) {
  const session = sessionState.get(sessionId);

  if (!session) {
    throw new Error(`Session ${sessionId} not found`);
  }

  if (session.round === 0) {
    return {
      sessionId,
      round: 0,
      agentsActive: 0,
      completed: false,
    };
  }

  // Get current round state
  const currentRoundIndex = session.round - 1;
  const roundState = session.rounds[currentRoundIndex];

  return {
    sessionId,
    round: session.round,
    agentsActive: roundState.agentsActive,
    completed: roundState.completed,
  };
}

async function enforceRateLimits(sessionId, agentCount) {
  const session = sessionState.get(sessionId);

  if (!session) {
    return {
      allowed: false,
      reason: `Session ${sessionId} not found`,
    };
  }

  // Check 1: Agent count per round (SEC-PM-005)
  if (agentCount > MAX_AGENTS_PER_ROUND) {
    return {
      allowed: false,
      reason: `Agent limit of ${MAX_AGENTS_PER_ROUND} agents per round exceeded (requested: ${agentCount})`,
    };
  }

  // Check 2: Round count per session (SEC-PM-005)
  if (session.round >= MAX_ROUNDS_PER_SESSION) {
    return {
      allowed: false,
      reason: `Round limit of ${MAX_ROUNDS_PER_SESSION} rounds per session exceeded (current: ${session.round})`,
    };
  }

  // All checks passed
  return {
    allowed: true,
  };
}

function createRouter(sessionId) {
  return {
    sessionId,
    routes: new Map(),
    messageQueue: [],
  };
}

function registerAgent(router, agentId, agentType) {
  // Check if already registered
  if (router.routes.has(agentId)) {
    return {
      success: false,
      error: `Agent ${agentId} is already registered`,
    };
  }

  // Generate route ID
  const routeId = `route_${crypto.randomBytes(8).toString('hex')}`;

  // Register agent
  router.routes.set(agentId, {
    agentId,
    agentType,
    routeId,
    registeredAt: Date.now(),
  });

  return {
    success: true,
    routeId,
  };
}

function routeMessage(router, fromAgentId, toAgentId, message) {
  // Verify sender is registered
  if (!router.routes.has(fromAgentId)) {
    return {
      delivered: false,
      error: `Sender ${fromAgentId} not registered`,
    };
  }

  // Verify recipient is registered
  if (!router.routes.has(toAgentId)) {
    return {
      delivered: false,
      error: `Recipient ${toAgentId} not registered`,
    };
  }

  // Create message entry
  const timestamp = Date.now();
  const messageHash = crypto
    .createHash('sha256')
    .update(JSON.stringify({ fromAgentId, toAgentId, message, timestamp }))
    .digest('hex')
    .slice(0, 16);

  const messageEntry = {
    fromAgentId,
    toAgentId,
    message,
    timestamp,
    messageHash,
    type: 'unicast',
  };

  // Add to message queue
  router.messageQueue.push(messageEntry);

  return {
    delivered: true,
    timestamp,
    messageHash,
  };
}

function broadcastMessage(router, fromAgentId, message) {
  const failedAgents = [];
  let deliveredCount = 0;

  // Get all agents except sender
  const recipients = Array.from(router.routes.keys()).filter(agentId => agentId !== fromAgentId);

  // Send to each recipient
  for (const toAgentId of recipients) {
    const result = routeMessage(router, fromAgentId, toAgentId, message);

    if (result.delivered) {
      deliveredCount++;
    } else {
      failedAgents.push(toAgentId);
    }
  }

  return {
    delivered: deliveredCount,
    failedAgents,
  };
}

function getMessageHistory(router, agentId) {
  return router.messageQueue.filter(
    msg => msg.fromAgentId === agentId || msg.toAgentId === agentId
  );
}

async function loadTeam(teamName) {
  const teamPath = path.join(TEAMS_DIR, `${teamName}.csv`);

  // Check if team file exists
  try {
    await fs.access(teamPath);
  } catch (_err) {
    throw new Error(`Team "${teamName}" not found at ${teamPath}`);
  }

  // Read CSV file
  const csvContent = await fs.readFile(teamPath, 'utf-8');

  // Parse CSV (simple parsing - split by lines and commas)
  const lines = csvContent.trim().split('\n');
  const header = lines[0].split(',').map(h => h.trim());

  // Validate header
  const requiredFields = ['agent_type', 'role', 'priority', 'tools', 'model'];
  const missingFields = requiredFields.filter(field => !header.includes(field));
  if (missingFields.length > 0) {
    throw new Error(`Team CSV missing required fields: ${missingFields.join(', ')}`);
  }

  // Parse agent rows
  const agents = [];
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue; // Skip empty lines

    // Split by comma, handling quoted strings
    const values = parseCSVLine(line);

    // Create agent object
    const agent = {};
    for (let j = 0; j < header.length; j++) {
      const field = header[j];
      const value = values[j];

      if (field === 'priority') {
        agent[field] = parseInt(value, 10);
      } else if (field === 'tools') {
        // Parse tools string "Read,Write,Edit" -> ['Read', 'Write', 'Edit']
        agent[field] = value.split(',').map(t => t.trim());
      } else {
        agent[field] = value;
      }
    }

    agents.push(agent);
  }

  return {
    teamName,
    agents,
  };
}

function parseCSVLine(line) {
  const values = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"') {
      inQuotes = !inQuotes;
    } else if (char === ',' && !inQuotes) {
      values.push(current.trim());
      current = '';
    } else {
      current += char;
    }
  }

  // Push last value
  values.push(current.trim());

  return values;
}

function validateTeamDefinition(team) {
  const errors = [];

  // Check 1: Team has teamName
  if (!team.teamName) {
    errors.push('Team missing required field: teamName');
  }

  // Check 2: Team has agents array
  if (!team.agents || !Array.isArray(team.agents)) {
    errors.push('Team missing required field: agents (must be array)');
    return { valid: false, errors }; // Can't continue without agents
  }

  // Check 3: Max 4 agents
  if (team.agents.length > 4) {
    errors.push(`Team has ${team.agents.length} agents (max 4 agents allowed)`);
  }

  // Check 4: At least 1 agent
  if (team.agents.length === 0) {
    errors.push('Team must have at least 1 agent');
  }

  // Check 5: Validate each agent
  team.agents.forEach((agent, index) => {
    // Required fields
    const requiredFields = ['agent_type', 'role', 'priority', 'tools', 'model'];
    const missingFields = requiredFields.filter(field => agent[field] === undefined);
    if (missingFields.length > 0) {
      errors.push(`Agent ${index + 1} missing required fields: ${missingFields.join(', ')}`);
    }

    // Validate role
    if (agent.role && !VALID_ROLES.includes(agent.role)) {
      errors.push(
        `Agent ${index + 1} has invalid role: ${agent.role} (valid: ${VALID_ROLES.join(', ')})`
      );
    }

    // Validate model
    if (agent.model && !VALID_MODELS.includes(agent.model)) {
      errors.push(
        `Agent ${index + 1} has invalid model: ${agent.model} (valid: ${VALID_MODELS.join(', ')})`
      );
    }

    // Validate tools array
    if (agent.tools && !Array.isArray(agent.tools)) {
      errors.push(`Agent ${index + 1} tools must be array`);
    }

    // Validate priority is number
    if (agent.priority && typeof agent.priority !== 'number') {
      errors.push(`Agent ${index + 1} priority must be number`);
    }
  });

  return {
    valid: errors.length === 0,
    errors,
  };
}

