export function shellQuote(filepath) {
  if (isWindows) {
    // Windows: use double quotes, escape internal quotes
    return `"${filepath.replace(/"/g, '""')}"`;
  }
  // Unix: use single quotes, escape internal single quotes
  return `'${filepath.replace(/'/g, "'\\''")}'`;
}

