function formatRelativeTime(timestamp) {
  const now = Date.now();
  const then = new Date(timestamp).getTime();
  const diffMs = now - then;
  const diffMinutes = Math.floor(diffMs / (1000 * 60));
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (diffDays > 0) {
    return `${diffDays}d ago`;
  } else if (diffHours > 0) {
    return `${diffHours}h ago`;
  } else if (diffMinutes > 0) {
    return `${diffMinutes}m ago`;
  } else {
    return 'just now';
  }
}

function getEvolutionBudget() {
  const envBudget = process.env.LOOP_EVOLUTION_BUDGET;
  if (envBudget) {
    const parsed = parseInt(envBudget, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return DEFAULT_EVOLUTION_BUDGET;
}

function getPatternThreshold() {
  const envThreshold = process.env.LOOP_PATTERN_THRESHOLD;
  if (envThreshold) {
    const parsed = parseInt(envThreshold, 10);
    if (!isNaN(parsed) && parsed > 0) return parsed;
  }
  return DEFAULT_PATTERN_THRESHOLD;
}

function collectMetrics() {
  const now = Date.now();
  const twentyFourHoursAgo = now - 24 * 60 * 60 * 1000;
  const sevenDaysAgo = now - 7 * 24 * 60 * 60 * 1000;

  // Read data sources
  const anomalyEntries = readJSONL(ANOMALY_LOG);
  const rollbackEntries = readJSONL(ROLLBACK_LOG);
  const loopState = readJSON(LOOP_STATE_FILE);

  // -------------------------
  // Anomaly Metrics
  // -------------------------
  const anomalies24h = anomalyEntries.filter(e => {
    const entryTime = new Date(e.timestamp).getTime();
    return entryTime >= twentyFourHoursAgo && e.detected === true;
  });

  const anomalies7d = anomalyEntries.filter(e => {
    const entryTime = new Date(e.timestamp).getTime();
    return entryTime >= sevenDaysAgo && e.detected === true;
  });

  // Recent anomalies (last 5, newest first)
  const recentAnomalies = anomalyEntries
    .filter(e => e.detected === true)
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
    .slice(0, 5)
    .map(e => ({
      type: e.type,
      timestamp: e.timestamp,
      relativeTime: formatRelativeTime(e.timestamp),
      ...e,
    }));

  // -------------------------
  // Recovery Metrics
  // -------------------------
  const rollbackOperations = rollbackEntries.filter(
    e => e.operation === 'rollback_completed' || e.operation === 'selective_rollback'
  );

  const successfulRollbacks = rollbackOperations.filter(e => {
    // For rollback_completed: failedCount === 0 means success
    // For selective_rollback: always considered successful if executed
    if (e.operation === 'rollback_completed') {
      return e.failedCount === 0 || e.success === true;
    }
    return true; // selective_rollback is always partial success
  });

  const totalRollbacks = rollbackOperations.length;
  const successRate =
    totalRollbacks > 0 ? Math.round((successfulRollbacks.length / totalRollbacks) * 100) : 0;

  // Rollback history (last 10, newest first)
  const rollbackHistory = rollbackOperations
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
    .slice(0, 10)
    .map(e => ({
      operation: e.operation,
      checkpointId: e.checkpointId,
      restoredCount: e.restoredCount || 0,
      failedCount: e.failedCount || 0,
      skippedCount: e.skippedCount || 0,
      timestamp: e.timestamp,
      relativeTime: formatRelativeTime(e.timestamp),
    }));

  // -------------------------
  // Evolution Metrics
  // -------------------------
  const evolutionBudget = getEvolutionBudget();
  const evolutionCount = loopState.evolutionCount || 0;
  const lastEvolutions = loopState.lastEvolutions || {};

  // -------------------------
  // Loop Metrics
  // -------------------------
  const actionHistory = loopState.actionHistory || [];
  const patternThreshold = getPatternThreshold();

  // Count interventions (actions that exceeded threshold)
  const interventions = actionHistory.filter(a => a.count > patternThreshold).length;

  const spawnDepth = loopState.spawnDepth || 0;

  return {
    anomalies: {
      last24h: anomalies24h.length,
      last7d: anomalies7d.length,
      recent: recentAnomalies,
    },
    recovery: {
      successRate,
      total: totalRollbacks,
      successful: successfulRollbacks.length,
      history: rollbackHistory,
    },
    evolution: {
      current: evolutionCount,
      budget: evolutionBudget,
      lastEvolutions,
    },
    loops: {
      interventions,
      spawnDepth,
      actionHistory,
    },
    collectedAt: new Date().toISOString(),
  };
}

function formatStatus(metrics) {
  const lines = [];

  lines.push('');
  lines.push('+======================================================+');
  lines.push('|           SELF-HEALING SYSTEM STATUS                 |');
  lines.push('+======================================================+');
  lines.push('|                                                      |');
  lines.push(
    `| Anomalies (24h):  ${String(metrics.anomalies.last24h).padStart(3)}  |  Anomalies (7d):   ${String(metrics.anomalies.last7d).padStart(3)}  |`
  );
  lines.push(
    `| Recovery Rate:   ${String(metrics.recovery.successRate).padStart(3)}%  |  Rollbacks:        ${String(metrics.recovery.total).padStart(3)}  |`
  );
  lines.push(
    `| Evolution Budget: ${metrics.evolution.current}/${metrics.evolution.budget}  |  Loop Blocks:      ${String(metrics.loops.interventions).padStart(3)}  |`
  );
  lines.push('|                                                      |');
  lines.push('+------------------------------------------------------+');
  lines.push('| Recent Anomalies:                                    |');

  if (metrics.anomalies.recent.length === 0) {
    lines.push('|   (none)                                             |');
  } else {
    for (const anomaly of metrics.anomalies.recent.slice(0, 3)) {
      const typeStr = anomaly.type.substring(0, 20).padEnd(20);
      const timeStr = anomaly.relativeTime.padEnd(10);
      lines.push(`|   - ${typeStr} - ${timeStr}        |`);
    }
  }

  lines.push('+======================================================+');
  lines.push('');

  return lines.join('\n');
}

function formatAnomalies(metrics) {
  const lines = [];

  lines.push('');
  lines.push('ANOMALY REPORT');
  lines.push('==============');
  lines.push('');
  lines.push(`Total (24h): ${metrics.anomalies.last24h}`);
  lines.push(`Total (7d):  ${metrics.anomalies.last7d}`);
  lines.push('');
  lines.push('Recent Anomalies:');
  lines.push('-----------------');

  if (metrics.anomalies.recent.length === 0) {
    lines.push('  No anomalies detected.');
  } else {
    for (const anomaly of metrics.anomalies.recent) {
      lines.push(`  - ${anomaly.type} (${anomaly.relativeTime})`);
      if (anomaly.tool) {
        lines.push(`      Tool: ${anomaly.tool}`);
      }
      if (anomaly.current !== undefined && anomaly.average !== undefined) {
        lines.push(`      Current: ${anomaly.current}, Average: ${anomaly.average}`);
      }
      if (anomaly.count !== undefined) {
        lines.push(`      Count: ${anomaly.count}`);
      }
    }
  }

  lines.push('');
  return lines.join('\n');
}

function formatLoops(metrics) {
  const lines = [];

  lines.push('');
  lines.push('LOOP PREVENTION STATUS');
  lines.push('======================');
  lines.push('');
  lines.push(`Evolution Budget: ${metrics.evolution.current}/${metrics.evolution.budget}`);
  lines.push(`Spawn Depth:      ${metrics.loops.spawnDepth}`);
  lines.push(`Interventions:    ${metrics.loops.interventions}`);
  lines.push('');

  // Last evolutions
  const lastEvolutions = metrics.evolution.lastEvolutions;
  if (Object.keys(lastEvolutions).length > 0) {
    lines.push('Last Evolutions:');
    lines.push('----------------');
    for (const [type, timestamp] of Object.entries(lastEvolutions)) {
      lines.push(`  - ${type}: ${formatRelativeTime(timestamp)}`);
    }
    lines.push('');
  }

  // Action history
  if (metrics.loops.actionHistory.length > 0) {
    lines.push('Action History:');
    lines.push('---------------');
    const sortedActions = [...metrics.loops.actionHistory]
      .sort((a, b) => b.count - a.count)
      .slice(0, 10);
    for (const action of sortedActions) {
      const threshold = getPatternThreshold();
      const indicator = action.count > threshold ? ' (!)' : '';
      lines.push(`  - ${action.action}: ${action.count}${indicator}`);
    }
    lines.push('');
  }

  return lines.join('\n');
}

function formatRollbacks(metrics) {
  const lines = [];

  lines.push('');
  lines.push('ROLLBACK HISTORY');
  lines.push('================');
  lines.push('');
  lines.push(`Success Rate: ${metrics.recovery.successRate}%`);
  lines.push(`Total:        ${metrics.recovery.total}`);
  lines.push(`Successful:   ${metrics.recovery.successful}`);
  lines.push('');

  if (metrics.recovery.history.length === 0) {
    lines.push('No rollbacks recorded.');
  } else {
    lines.push('Recent Rollbacks:');
    lines.push('-----------------');
    for (const rollback of metrics.recovery.history) {
      lines.push(`  - ${rollback.checkpointId} (${rollback.relativeTime})`);
      lines.push(`      Operation: ${rollback.operation}`);
      lines.push(`      ${rollback.restoredCount} files restored`);
      if (rollback.failedCount > 0) {
        lines.push(`      ${rollback.failedCount} files failed`);
      }
      if (rollback.skippedCount > 0) {
        lines.push(`      ${rollback.skippedCount} files skipped`);
      }
    }
  }

  lines.push('');
  return lines.join('\n');
}

function run(args = process.argv.slice(2)) {
  const command = args[0] || 'status';
  const jsonFlag = args.includes('--json');

  const metrics = collectMetrics();

  if (jsonFlag) {
    console.log(JSON.stringify(metrics, null, 2));
    return;
  }

  switch (command) {
    case 'status':
      console.log(formatStatus(metrics));
      break;
    case 'anomalies':
      console.log(formatAnomalies(metrics));
      break;
    case 'loops':
      console.log(formatLoops(metrics));
      break;
    case 'rollbacks':
      console.log(formatRollbacks(metrics));
      break;
    case 'help':
    default:
      console.log(`
Self-Healing Dashboard
======================

Usage:
  node dashboard.cjs status           Show status overview
  node dashboard.cjs anomalies        Show anomaly details
  node dashboard.cjs loops            Show loop state details
  node dashboard.cjs rollbacks        Show rollback history
  node dashboard.cjs status --json    JSON output for programmatic use

Options:
  --json    Output metrics as JSON instead of formatted text
`);
  }
}

function runTaskCommand(command, projectRoot) {
  if (!command) return { success: false, error: 'missing_command' };
  const result = spawnSync(command, {
    cwd: projectRoot,
    shell: true,
    stdio: 'inherit',
  });
  if (result.error) {
    return { success: false, error: result.error.message };
  }
  return {
    success: result.status === 0,
    error: result.status === 0 ? null : `exit_${result.status}`,
  };
}

function runTick(projectRoot = PROJECT_ROOT) {
  const store = loadStore(projectRoot);
  const now = Date.now();
  const dueTasks = (store.tasks || []).filter(task => {
    if (!task.nextRunAt) return false;
    const next = Date.parse(task.nextRunAt);
    return Number.isFinite(next) && next <= now;
  });
  if (dueTasks.length === 0) {
    store.meta.lastTickAt = new Date(now).toISOString();
    saveStore(store, projectRoot);
    return { executed: 0, due: 0 };
  }

  const executed = [];
  for (const task of dueTasks) {
    let outcome = { success: true };
    if (task.payload && task.payload.command) {
      outcome = runTaskCommand(task.payload.command, projectRoot);
    }
    executed.push({ id: task.id, success: outcome.success });
    if (task.type !== 'cron') {
      task.nextRunAt = null;
    } else {
      task.nextRunAt = computeNextRunAt(task, now);
    }
    if (!outcome.success) {
      logger.warn('task_failed', { id: task.id, error: outcome.error });
    }
  }

  store.meta.lastTickAt = new Date(now).toISOString();
  saveStore(store, projectRoot);
  return { executed: executed.length, due: dueTasks.length };
}

function getPreferredAgent(intent) {
  return ROUTING_TABLE[intent] ?? INTENT_TO_AGENT[intent] ?? null;
}

function extractTestCases(rule: Rule): TestCase[] {
  const testCases: TestCase[] = []

  rule.examples.forEach((example, index) => {
    const isBad = example.label.toLowerCase().includes('incorrect') ||
                  example.label.toLowerCase().includes('wrong') ||
                  example.label.toLowerCase().includes('bad')
    const isGood = example.label.toLowerCase().includes('correct') ||
                   example.label.toLowerCase().includes('good')

    if (isBad || isGood) {
      testCases.push({
        ruleId: rule.id,
        ruleTitle: rule.title,
        type: isBad ? 'bad' : 'good',
        code: example.code,
        language: example.language || 'typescript',
        description: example.description || `${example.label} example for ${rule.title}`
      })
    }
  })

  return testCases
}

async function extractTests() {
  try {
    console.log('Extracting test cases from rules...')
    console.log(`Rules directory: ${RULES_DIR}`)
    console.log(`Output file: ${TEST_CASES_FILE}`)

    const files = await readdir(RULES_DIR)
    const ruleFiles = files.filter(f => f.endsWith('.md') && !f.startsWith('_') && f !== 'README.md')

    const allTestCases: TestCase[] = []

    for (const file of ruleFiles) {
      const filePath = join(RULES_DIR, file)
      try {
        const { rule } = await parseRuleFile(filePath)
        const testCases = extractTestCases(rule)
        allTestCases.push(...testCases)
      } catch (error) {
        console.error(`Error processing ${file}:`, error)
      }
    }

    // Write test cases as JSON
    await writeFile(TEST_CASES_FILE, JSON.stringify(allTestCases, null, 2), 'utf-8')

    console.log(`✓ Extracted ${allTestCases.length} test cases to ${TEST_CASES_FILE}`)
    console.log(`  - Bad examples: ${allTestCases.filter(tc => tc.type === 'bad').length}`)
    console.log(`  - Good examples: ${allTestCases.filter(tc => tc.type === 'good').length}`)
  } catch (error) {
    console.error('Extraction failed:', error)
    process.exit(1)
  }
}

async function migrate() {
  try {
    console.log('Migrating RPG.md to individual rule files...')

    if (!existsSync(RPG_FILE)) {
      console.error(`RPG.md not found at ${RPG_FILE}`)
      process.exit(1)
    }

    // Ensure rules directory exists
    if (!existsSync(RULES_DIR)) {
      await mkdir(RULES_DIR, { recursive: true })
    }

    const content = await readFile(RPG_FILE, 'utf-8')
    const lines = content.split('\n')

    let currentSection: { number: number; title: string; impact?: string; introduction?: string } | null = null
    let currentRule: { section: number; subsection: number; title: string; content: string[] } | null = null
    let inCodeBlock = false

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]

      // Check for section heading
      const sectionInfo = parseSectionHeading(line)
      if (sectionInfo) {
        // Save previous section if exists
        if (currentSection) {
          const sectionFile = join(RULES_DIR, `section-${currentSection.number}.md`)
          let sectionContent = `# ${currentSection.number}. ${currentSection.title}\n\n`
          if (currentSection.impact) {
            sectionContent += `**Impact: ${currentSection.impact}**\n\n`
          }
          if (currentSection.introduction) {
            sectionContent += `## Introduction\n\n${currentSection.introduction}\n`
          }
          await writeFile(sectionFile, sectionContent, 'utf-8')
        }

        currentSection = sectionInfo
        currentRule = null

        // Look for impact on next few lines
        for (let j = i + 1; j < Math.min(i + 5, lines.length); j++) {
          const impactInfo = extractImpact(lines[j])
          if (impactInfo) {
            currentSection.impact = impactInfo.impact
            break
          }
        }

        // Collect introduction text until first rule
        let introduction: string[] = []
        for (let j = i + 1; j < lines.length; j++) {
          if (parseRuleHeading(lines[j])) {
            break
          }
          if (!lines[j].match(/^###/)) {
            introduction.push(lines[j])
          }
        }
        currentSection.introduction = introduction.join('\n').trim()
        continue
      }

      // Check for rule heading
      const ruleInfo = parseRuleHeading(line)
      if (ruleInfo) {
        // Save previous rule if exists
        if (currentRule && currentSection) {
          const ruleFile = join(RULES_DIR, `section-${currentRule.section}-rule-${currentRule.subsection}.md`)
          const ruleContent = currentRule.content.join('\n')
          await writeFile(ruleFile, ruleContent, 'utf-8')
          console.log(`Created ${ruleFile}`)
        }

        currentRule = {
          ...ruleInfo,
          content: [line]
        }
        continue
      }

      // Accumulate content for current rule
      if (currentRule) {
        currentRule.content.push(line)
      }
    }

    // Save last rule
    if (currentRule && currentSection) {
      const ruleFile = join(RULES_DIR, `section-${currentRule.section}-rule-${currentRule.subsection}.md`)
      const ruleContent = currentRule.content.join('\n')
      await writeFile(ruleFile, ruleContent, 'utf-8')
      console.log(`Created ${ruleFile}`)
    }

    // Save last section
    if (currentSection) {
      const sectionFile = join(RULES_DIR, `section-${currentSection.number}.md`)
      let sectionContent = `# ${currentSection.number}. ${currentSection.title}\n\n`
      if (currentSection.impact) {
        sectionContent += `**Impact: ${currentSection.impact}**\n\n`
      }
      if (currentSection.introduction) {
        sectionContent += `## Introduction\n\n${currentSection.introduction}\n`
      }
      await writeFile(sectionFile, sectionContent, 'utf-8')
      console.log(`Created ${sectionFile}`)
    }

    console.log('\n✓ Migration complete!')
    console.log('Note: You may need to manually add frontmatter to rule files.')
  } catch (error) {
    console.error('Migration failed:', error)
    process.exit(1)
  }
}

export async function parseRuleFile(
  filePath: string,
  sectionMap?: Record<string, number>
): Promise<RuleFile> {
  const rawContent = await readFile(filePath, 'utf-8')
  // Normalize Windows CRLF line endings to LF for consistent parsing
  const content = rawContent.replace(/\r\n/g, '\n')
  const lines = content.split('\n')

  // Extract frontmatter if present
  let frontmatter: Record<string, any> = {}
  let contentStart = 0

  if (content.startsWith('---')) {
    const frontmatterEnd = content.indexOf('---', 3)
    if (frontmatterEnd !== -1) {
      const frontmatterText = content.slice(3, frontmatterEnd).trim()
      frontmatterText.split('\n').forEach((line) => {
        const [key, ...valueParts] = line.split(':')
        if (key && valueParts.length) {
          const value = valueParts.join(':').trim()
          frontmatter[key.trim()] = value.replace(/^["']|["']$/g, '')
        }
      })
      contentStart = frontmatterEnd + 3
    }
  }

  // Parse the rule content
  const ruleContent = content.slice(contentStart).trim()
  const ruleLines = ruleContent.split('\n')

  // Extract title (first # or ## heading)
  let title = ''
  let titleLine = 0
  for (let i = 0; i < ruleLines.length; i++) {
    if (ruleLines[i].startsWith('##')) {
      title = ruleLines[i].replace(/^##+\s*/, '').trim()
      titleLine = i
      break
    }
  }

  // Extract impact
  let impact: Rule['impact'] = 'MEDIUM'
  let impactDescription = ''
  let explanation = ''
  let examples: Rule['examples'] = []
  let references: string[] = []

  // Parse content after title
  let currentExample: {
    label: string
    description?: string
    code: string
    language?: string
    additionalText?: string
  } | null = null
  let inCodeBlock = false
  let codeBlockLanguage = 'typescript'
  let codeBlockContent: string[] = []
  let afterCodeBlock = false
  let additionalText: string[] = []
  let hasCodeBlockForCurrentExample = false

  for (let i = titleLine + 1; i < ruleLines.length; i++) {
    const line = ruleLines[i]

    // Impact line
    if (line.includes('**Impact:')) {
      const match = line.match(
        /\*\*Impact:\s*(\w+(?:-\w+)?)\s*(?:\(([^)]+)\))?/i
      )
      if (match) {
        impact = match[1].toUpperCase().replace(/-/g, '-') as ImpactLevel
        impactDescription = match[2] || ''
      }
      continue
    }

    // Code block start
    if (line.startsWith('```')) {
      if (inCodeBlock) {
        // End of code block
        if (currentExample) {
          currentExample.code = codeBlockContent.join('\n')
          currentExample.language = codeBlockLanguage
        }
        codeBlockContent = []
        inCodeBlock = false
        afterCodeBlock = true
      } else {
        // Start of code block
        inCodeBlock = true
        hasCodeBlockForCurrentExample = true
        codeBlockLanguage = line.slice(3).trim() || 'typescript'
        codeBlockContent = []
        afterCodeBlock = false
      }
      continue
    }

    if (inCodeBlock) {
      codeBlockContent.push(line)
      continue
    }

    // Example label (Incorrect, Correct, Example, Usage, Implementation, etc.)
    // Match pattern: **Label:** or **Label (description):** at end of line
    // This distinguishes example labels from inline bold text like "**Trade-off:** some text"
    const labelMatch = line.match(/^\*\*([^:]+?):\*?\*?$/)
    if (labelMatch) {
      // Save previous example if it exists
      if (currentExample) {
        if (additionalText.length > 0) {
          currentExample.additionalText = additionalText.join('\n\n')
          additionalText = []
        }
        examples.push(currentExample)
      }
      afterCodeBlock = false
      hasCodeBlockForCurrentExample = false

      const fullLabel = labelMatch[1].trim()
      // Try to extract description from parentheses if present (handles simple cases)
      // For nested parentheses like "Incorrect (O(n) per lookup)", we keep the full label
      const descMatch = fullLabel.match(
        /^([A-Za-z]+(?:\s+[A-Za-z]+)*)\s*\(([^()]+)\)$/
      )
      currentExample = {
        label: descMatch ? descMatch[1].trim() : fullLabel,
        description: descMatch ? descMatch[2].trim() : undefined,
        code: '',
        language: codeBlockLanguage,
      }
      continue
    }

    // Reference links
    if (line.startsWith('Reference:') || line.startsWith('References:')) {
      // Save current example before processing references
      if (currentExample) {
        if (additionalText.length > 0) {
          currentExample.additionalText = additionalText.join('\n\n')
          additionalText = []
        }
        examples.push(currentExample)
        currentExample = null
      }

      const refMatch = line.match(/\[([^\]]+)\]\(([^)]+)\)/g)
      if (refMatch) {
        references.push(
          ...refMatch.map((ref) => {
            const m = ref.match(/\[([^\]]+)\]\(([^)]+)\)/)
            return m ? m[2] : ref
          })
        )
      }
      continue
    }

    // Regular text (explanation or additional context after examples)
    if (line.trim() && !line.startsWith('#')) {
      if (!currentExample && !inCodeBlock) {
        // Main explanation before any examples
        explanation += (explanation ? '\n\n' : '') + line
      } else if (
        currentExample &&
        (afterCodeBlock || !hasCodeBlockForCurrentExample)
      ) {
        // Text after a code block, or text in a section without a code block
        // (e.g., "When NOT to use this pattern:" with bullet points instead of code)
        additionalText.push(line)
      }
    }
  }

  // Handle last example if still open
  if (currentExample) {
    if (additionalText.length > 0) {
      currentExample.additionalText = additionalText.join('\n\n')
    }
    examples.push(currentExample)
  }

  // Infer section from filename patterns
  // Pattern: area-description.md where area determines section
  const filename = basename(filePath)

  // Default section map (for backwards compatibility)
  const defaultSectionMap: Record<string, number> = {
    async: 1,
    bundle: 2,
    server: 3,
    client: 4,
    rerender: 5,
    rendering: 6,
    js: 7,
    advanced: 8,
  }

  const effectiveSectionMap = sectionMap || defaultSectionMap

  // Extract area from filename - try longest prefix match first
  // This handles prefixes like "list-performance" vs "list"
  const filenameParts = filename.replace('.md', '').split('-')
  let section = 0

  // Try progressively shorter prefixes to find the best match
  for (let len = filenameParts.length; len > 0; len--) {
    const prefix = filenameParts.slice(0, len).join('-')
    if (effectiveSectionMap[prefix] !== undefined) {
      section = effectiveSectionMap[prefix]
      break
    }
  }

  // Fall back to frontmatter section if specified
  section = frontmatter.section || section || 0

  const rule: Rule = {
    id: '', // Will be assigned by build script based on sorted order
    title: frontmatter.title || title,
    section: section,
    subsection: undefined,
    impact: frontmatter.impact || impact,
    impactDescription: frontmatter.impactDescription || impactDescription,
    explanation: frontmatter.explanation || explanation.trim(),
    examples,
    references: frontmatter.references
      ? frontmatter.references.split(',').map((r: string) => r.trim())
      : references,
    tags: frontmatter.tags
      ? frontmatter.tags.split(',').map((t: string) => t.trim())
      : undefined,
  }

  return {
    section,
    subsection: 0,
    rule,
  }
}

function validateRule(rule: Rule, file: string): ValidationError[] {
  const errors: ValidationError[] = []

  // Note: rule.id is auto-generated during build, not required in source files

  if (!rule.title || rule.title.trim().length === 0) {
    errors.push({ file, ruleId: rule.id, message: 'Missing or empty title' })
  }

  if (!rule.explanation || rule.explanation.trim().length === 0) {
    errors.push({ file, ruleId: rule.id, message: 'Missing or empty explanation' })
  }

  if (!rule.examples || rule.examples.length === 0) {
    errors.push({ file, ruleId: rule.id, message: 'Missing examples (need at least one bad and one good example)' })
  } else {
    // Filter out informational examples (notes, trade-offs, etc.) that don't have code
    const codeExamples = rule.examples.filter(e => e.code && e.code.trim().length > 0)

    const hasBad = codeExamples.some(e =>
      e.label.toLowerCase().includes('incorrect') ||
      e.label.toLowerCase().includes('wrong') ||
      e.label.toLowerCase().includes('bad')
    )
    const hasGood = codeExamples.some(e =>
      e.label.toLowerCase().includes('correct') ||
      e.label.toLowerCase().includes('good') ||
      e.label.toLowerCase().includes('usage') ||
      e.label.toLowerCase().includes('implementation') ||
      e.label.toLowerCase().includes('example')
    )

    if (codeExamples.length === 0) {
      errors.push({ file, ruleId: rule.id, message: 'Missing code examples' })
    } else if (!hasBad && !hasGood) {
      errors.push({ file, ruleId: rule.id, message: 'Missing bad/incorrect or good/correct examples' })
    }
  }

  const validImpacts: Rule['impact'][] = ['CRITICAL', 'HIGH', 'MEDIUM-HIGH', 'MEDIUM', 'LOW-MEDIUM', 'LOW']
  if (!validImpacts.includes(rule.impact)) {
    errors.push({ file, ruleId: rule.id, message: `Invalid impact level: ${rule.impact}. Must be one of: ${validImpacts.join(', ')}` })
  }

  return errors
}

async function validate() {
  try {
    console.log('Validating rule files...')
    console.log(`Rules directory: ${RULES_DIR}`)

    const files = await readdir(RULES_DIR)
    const ruleFiles = files.filter(f => f.endsWith('.md') && !f.startsWith('_'))

    const allErrors: ValidationError[] = []

    for (const file of ruleFiles) {
      const filePath = join(RULES_DIR, file)
      try {
        const { rule } = await parseRuleFile(filePath)
        const errors = validateRule(rule, file)
        allErrors.push(...errors)
      } catch (error) {
        allErrors.push({
          file,
          message: `Failed to parse: ${error instanceof Error ? error.message : String(error)}`
        })
      }
    }

    if (allErrors.length > 0) {
      console.error('\n✗ Validation failed:\n')
      allErrors.forEach(error => {
        console.error(`  ${error.file}${error.ruleId ? ` (${error.ruleId})` : ''}: ${error.message}`)
      })
      process.exit(1)
    } else {
      console.log(`✓ All ${ruleFiles.length} rule files are valid`)
    }
  } catch (error) {
    console.error('Validation failed:', error)
    process.exit(1)
  }
}

function getStorePath(projectRoot = PROJECT_ROOT) {
  return path.join(projectRoot, '.claude', 'context', 'scheduler', 'tasks.json');
}

function loadStore(projectRoot = PROJECT_ROOT) {
  const filePath = getStorePath(projectRoot);
  if (!fs.existsSync(filePath)) return { ...DEFAULT_STORE };
  try {
    const parsed = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    return {
      tasks: Array.isArray(parsed.tasks) ? parsed.tasks : [],
      meta: parsed.meta && typeof parsed.meta === 'object' ? parsed.meta : {},
    };
  } catch (_e) {
    return { ...DEFAULT_STORE };
  }
}

function saveStore(store, projectRoot = PROJECT_ROOT) {
  const filePath = getStorePath(projectRoot);
  const safe = {
    tasks: Array.isArray(store.tasks) ? store.tasks : [],
    meta: store.meta && typeof store.meta === 'object' ? store.meta : {},
  };
  atomicWriteJSONSync(filePath, safe);
  return safe;
}

function listTasks(projectRoot = PROJECT_ROOT) {
  return loadStore(projectRoot).tasks;
}

function addTask(task, projectRoot = PROJECT_ROOT) {
  const store = loadStore(projectRoot);
  const id = task.id || crypto.randomUUID();
  const nextRunAt = task.nextRunAt || task.runAt || null;
  store.tasks.push({
    id,
    name: task.name || 'Unnamed task',
    type: task.type || 'once',
    nextRunAt,
    cronExpr: task.cronExpr || null,
    payload: task.payload || {},
  });
  saveStore(store, projectRoot);
  return id;
}

function removeTask(id, projectRoot = PROJECT_ROOT) {
  const store = loadStore(projectRoot);
  const before = store.tasks.length;
  store.tasks = store.tasks.filter(task => task.id !== id);
  saveStore(store, projectRoot);
  return before !== store.tasks.length;
}

function parseCronIntervalMs(cronExpr) {
  if (!cronExpr || typeof cronExpr !== 'string') return null;
  const match = cronExpr.trim().match(/^\*\/(\d+)\s+\*\s+\*\s+\*\s+\*$/);
  if (!match) return null;
  const minutes = Number(match[1]);
  if (!Number.isFinite(minutes) || minutes <= 0) return null;
  return minutes * 60 * 1000;
}

function computeNextRunAt(task, now = Date.now()) {
  if (task.type === 'once') return null;
  if (task.payload && Number.isFinite(task.payload.intervalMs)) {
    return new Date(now + Number(task.payload.intervalMs)).toISOString();
  }
  if (task.payload && Number.isFinite(task.payload.intervalMinutes)) {
    return new Date(now + Number(task.payload.intervalMinutes) * 60 * 1000).toISOString();
  }
  const intervalMs = parseCronIntervalMs(task.cronExpr);
  if (intervalMs) return new Date(now + intervalMs).toISOString();
  return task.nextRunAt || null;
}

function getDueTasks(projectRoot = PROJECT_ROOT, now = Date.now()) {
  const store = loadStore(projectRoot);
  const due = [];
  for (const task of store.tasks) {
    if (!task.nextRunAt) continue;
    const next = Date.parse(task.nextRunAt);
    if (Number.isFinite(next) && next <= now) {
      due.push(task);
    }
  }
  return due;
}

function normalizeModeNames(modeNames) {
  if (!Array.isArray(modeNames)) return [];
  return modeNames.map(mode => String(mode).trim()).filter(Boolean);
}

class ChaosEngineer {
  constructor() {
    this.injections = {
      hooks: new Map(), // hookName -> failureRate
      tools: new Map(), // toolName -> failureRate
      contextExhausted: false,
      memoryPressure: 0,
    };
    this.testResults = [];
    this.recoveryAttempts = [];
  }

  async cleanup() {
    this.injections.hooks.clear();
    this.injections.tools.clear();
    this.injections.contextExhausted = false;
    this.injections.memoryPressure = 0;
    this.testResults = [];
    this.recoveryAttempts = [];
  }

  /**
   * Inject hook failures
   *
   * @param {string} hookName - Hook to inject failures into ('*' for all)
   * @param {number} failureRate - Probability of failure (0.0 to 1.0)
   */
  async injectHookFailure(hookName, failureRate) {
    this.injections.hooks.set(hookName, failureRate);
  }

  /**
   * Inject tool failures
   *
   * @param {string} toolName - Tool to inject failures into ('*' for all)
   * @param {number} failureRate - Probability of failure (0.0 to 1.0)
   */
  async injectToolFailure(toolName, failureRate) {
    this.injections.tools.set(toolName, failureRate);
  }

  /**
   * Inject context exhaustion
   *
   * @returns {Promise<object>} Injection result
   */
  async injectContextExhaustion() {
    this.injections.contextExhausted = true;
    return {
      compressionUsed: true,
      checkpointCreated: true,
    };
  }

  /**
   * Inject memory pressure
   *
   * @param {number} percentUsed - Percentage of memory used (0-100)
   */
  async injectMemoryPressure(percentUsed) {
    this.injections.memoryPressure = percentUsed;

    // Simulate memory pressure effects
    if (percentUsed > 85) {
      global.gc?.(); // Trigger GC if available
    }
  }

  /**
   * Run chaos test scenario
   *
   * @param {string} scenarioName - Scenario name
   * @param {number} durationMs - Test duration in milliseconds
   * @returns {Promise<object>} Test result
   */
  async runChaosTest(scenarioName, durationMs) {
    const startTime = Date.now();
    const result = {
      scenarioName,
      duration: durationMs,
      totalAttempts: 0,
      failures: 0,
      recoveries: 0,
      retries: 0,
      auditTrail: [],
      recovered: false,
      crashed: false, // Added: explicit crashed state
      failureRate: 0,
      recoveryRate: 0,
      gcTriggered: this.injections.memoryPressure > 80, // Set immediately based on memory pressure
      compressionTriggered: false,
      truncationTriggered: false,
      maxConcurrency: 100,
      initialConcurrency: 100,
      checkpointCreated: false,
      checkpointValid: false,
      finalState: { consistent: true },
    };

    // Run scenario simulation
    while (Date.now() - startTime < durationMs) {
      result.totalAttempts++;

      // Simulate operation
      const operation = await this.simulateOperation(scenarioName);

      if (operation.failed) {
        result.failures++;
        result.auditTrail.push({
          type: 'failure',
          timestamp: Date.now(),
          valid: true,
        });

        // Attempt recovery
        const recovery = await this.attemptRecovery(operation);
        if (recovery.success) {
          result.recoveries++;
          result.retries += recovery.retries;
          result.auditTrail.push({
            type: 'recovery',
            timestamp: Date.now(),
            valid: true,
          });
        }
      } else {
        result.auditTrail.push({
          type: 'success',
          timestamp: Date.now(),
          valid: true,
        });
      }

      // Check for context exhaustion effects
      if (this.injections.contextExhausted) {
        result.compressionTriggered = true;
        result.checkpointCreated = true;
        result.checkpointValid = true;
      }

      // Check for memory pressure effects
      if (this.injections.memoryPressure > 85) {
        result.gcTriggered = true;
        result.maxConcurrency = Math.floor(result.initialConcurrency * 0.7); // Reduce by 30%
      }

      // Simulate small delay
      await this.sleep(10);
    }

    // Calculate final metrics
    result.failureRate = result.totalAttempts > 0 ? result.failures / result.totalAttempts : 0;
    result.recoveryRate = result.failures > 0 ? result.recoveries / result.failures : 1.0;
    // Consider recovered if: no failures OR high recovery rate
    result.recovered = result.failures === 0 || result.recoveryRate >= 0.9;

    this.testResults.push(result);
    return result;
  }

  /**
   * Simulate a single operation
   *
   * @param {string} scenarioName - Scenario name
   * @returns {Promise<object>} Operation result
   */
  async simulateOperation(scenarioName) {
    const operation = {
      name: scenarioName,
      failed: false,
      reason: null,
    };

    // Check hook failures
    for (const [hookName, failureRate] of this.injections.hooks) {
      if (hookName === '*' || scenarioName.includes(hookName)) {
        if (Math.random() < failureRate) {
          operation.failed = true;
          operation.reason = `hook-failure: ${hookName}`;
          return operation;
        }
      }
    }

    // Check tool failures
    for (const [toolName, failureRate] of this.injections.tools) {
      if (toolName === '*' || scenarioName.includes(toolName.toLowerCase())) {
        if (Math.random() < failureRate) {
          operation.failed = true;
          operation.reason = `tool-failure: ${toolName}`;
          return operation;
        }
      }
    }

    return operation;
  }

  /**
   * Attempt recovery from failure
   *
   * @param {object} operation - Failed operation
   * @returns {Promise<object>} Recovery result
   */
  async attemptRecovery(operation) {
    const recovery = {
      success: false,
      retries: 0,
    };

    // Retry up to 3 times
    for (let i = 0; i < 3; i++) {
      recovery.retries++;
      await this.sleep(100); // Backoff delay

      // 80% chance of recovery on retry
      if (Math.random() < 0.8) {
        recovery.success = true;
        this.recoveryAttempts.push({
          operation: operation.name,
          retries: recovery.retries,
          timestamp: Date.now(),
        });
        return recovery;
      }
    }

    return recovery;
  }

  /**
   * Validate recovery from chaos test
   *
   * @param {object} result - Test result
   * @returns {Promise<object>} Validation result
   */
  async validateRecovery(result) {
    return {
      passed: result.recovered && result.recoveryRate >= 0.9,
      recoveryRate: result.recoveryRate,
      issues: result.recovered ? [] : ['low-recovery-rate'],
    };
  }

  /**
   * Generate chaos engineering report
   *
   * @param {object} result - Test result
   * @returns {Promise<string>} Markdown report
   */
  async generateChaosReport(result) {
    const report = `# Chaos Engineering Report

## Scenario: ${result.scenarioName}

- **Duration**: ${result.duration}ms
- **Total Attempts**: ${result.totalAttempts}
- **Failures**: ${result.failures}
- **Recoveries**: ${result.recoveries}
- **Recovery Rate**: ${(result.recoveryRate * 100).toFixed(1)}%

## Failure Injection

- **Hook Failures**: ${
      Array.from(this.injections.hooks.entries())
        .map(([h, r]) => `${h} (${r * 100}%)`)
        .join(', ') || 'None'
    }
- **Tool Failures**: ${
      Array.from(this.injections.tools.entries())
        .map(([t, r]) => `${t} (${r * 100}%)`)
        .join(', ') || 'None'
    }
- **Memory Pressure**: ${this.injections.memoryPressure}%

## Recovery Metrics

- **Average Retries**: ${result.retries > 0 ? (result.retries / result.recoveries).toFixed(1) : 0}
- **Recovery Status**: ${result.recovered ? '✅ PASSED' : '❌ FAILED'}

## Audit Trail

- **Total Entries**: ${result.auditTrail.length}
- **Valid Entries**: ${result.auditTrail.filter(e => e.valid).length}

## Recommendations

${result.recoveryRate < 0.9 ? '⚠️ Recovery rate below 90% - investigate failure patterns' : '✅ Recovery rate acceptable'}
${result.auditTrail.some(e => !e.valid) ? '⚠️ Invalid audit entries detected' : '✅ Audit trail integrity maintained'}
`;

    return report;
  }

  /**
   * Sleep helper
   *
   * @param {number} ms - Milliseconds to sleep
   * @returns {Promise<void>}
   */
  sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

function syncSleep(ms) {
  if (typeof SharedArrayBuffer !== 'undefined' && typeof Atomics !== 'undefined') {
    try {
      const sharedBuffer = new SharedArrayBuffer(4);
      const int32 = new Int32Array(sharedBuffer);
      Atomics.wait(int32, 0, 0, ms);
      return;
    } catch (_e) {
      // Fall back to busy-wait
    }
  }
  const start = Date.now();
  while (Date.now() - start < ms) {
    // Busy wait - only used when Atomics.wait unavailable
  }
}

function isProcessAlive(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch (_err) {
    return false;
  }
}

function tryClaimStaleLock(lockFile) {
  const claimingFile = `${lockFile}.claiming.${process.pid}.${Date.now()}`;

  try {
    fs.renameSync(lockFile, claimingFile);
    try {
      const lockData = JSON.parse(fs.readFileSync(claimingFile, 'utf8'));
      if (lockData.pid && !isProcessAlive(lockData.pid)) {
        fs.unlinkSync(claimingFile);
        return true;
      }

      // Process still alive; restore lock if possible
      try {
        fs.renameSync(claimingFile, lockFile);
      } catch (_restoreErr) {
        try {
          fs.unlinkSync(claimingFile);
        } catch {
          // best effort cleanup
        }
      }
      return false;
    } catch (_readErr) {
      try {
        fs.unlinkSync(claimingFile);
      } catch {
        // best effort cleanup
      }
      return true;
    }
  } catch (_renameErr) {
    return false;
  }
}

function acquireLock(filePath) {
  const lockFile = filePath + LOCK_SUFFIX;
  const startTime = Date.now();

  while (Date.now() - startTime < MAX_LOCK_WAIT_MS) {
    try {
      fs.writeFileSync(lockFile, JSON.stringify({ pid: process.pid, time: Date.now() }), {
        flag: 'wx',
      });
      return true;
    } catch (e) {
      if (e.code === 'EEXIST') {
        if (tryClaimStaleLock(lockFile)) {
          continue;
        }
        syncSleep(LOCK_RETRY_MS);
        continue;
      }
      return false;
    }
  }

  return false;
}

function releaseLock(filePath) {
  const lockFile = filePath + LOCK_SUFFIX;
  try {
    fs.unlinkSync(lockFile);
  } catch {
    // ignore
  }
}

function getDefaultState() {
  const now = new Date().toISOString();
  const defaults = SCHEMAS['loop-state']?.defaults || {};
  return {
    ...defaults,
    sessionId: process.env.CLAUDE_SESSION_ID || `session-${Date.now()}`,
    createdAt: now,
    updatedAt: now,
  };
}

function ensureStateDir(filePath) {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function getState(stateFile = LOOP_STATE_FILE) {
  const defaults = getDefaultState();

  try {
    if (!fs.existsSync(stateFile)) {
      return defaults;
    }
    const content = fs.readFileSync(stateFile, 'utf8');
    const parsed = safeParseJSON(content, 'loop-state');
    const state = { ...defaults, ...parsed };
    if (!state.createdAt) state.createdAt = defaults.createdAt;
    if (!state.updatedAt) state.updatedAt = defaults.updatedAt;
    return state;
  } catch (_e) {
    return defaults;
  }
}

function saveState(state, stateFile = LOOP_STATE_FILE) {
  const lockAcquired = acquireLock(stateFile);
  try {
    ensureStateDir(stateFile);
    const updated = {
      ...state,
      updatedAt: new Date().toISOString(),
    };
    atomicWriteJSONSync(stateFile, updated);
  } finally {
    if (lockAcquired) {
      releaseLock(stateFile);
    }
  }
}

function resetState(stateFile = LOOP_STATE_FILE) {
  const state = getDefaultState();
  saveState(state, stateFile);
  return state;
}

function recordAction(action, stateFile = LOOP_STATE_FILE) {
  if (!action || typeof action !== 'string') return;

  const state = getState(stateFile);
  const history = Array.isArray(state.actionHistory) ? state.actionHistory : [];

  const existing = history.find(h => h && typeof h === 'object' && h.action === action);
  if (existing) {
    existing.count = typeof existing.count === 'number' ? existing.count + 1 : 1;
    existing.lastAt = new Date().toISOString();
  } else {
    history.push({ action, count: 1, lastAt: new Date().toISOString() });
  }

  state.actionHistory = history.slice(-50);
  saveState(state, stateFile);
}

function recordSpawn(agentType, stateFile = LOOP_STATE_FILE) {
  const state = getState(stateFile);
  state.spawnDepth = typeof state.spawnDepth === 'number' ? state.spawnDepth + 1 : 1;
  saveState(state, stateFile);

  if (agentType) {
    recordAction(`spawn:${agentType}`, stateFile);
  }
}

function decrementSpawnDepth(stateFile = LOOP_STATE_FILE) {
  const state = getState(stateFile);
  const current = typeof state.spawnDepth === 'number' ? state.spawnDepth : 0;
  state.spawnDepth = Math.max(0, current - 1);
  saveState(state, stateFile);
}

function recordEvolution(type, stateFile = LOOP_STATE_FILE) {
  if (!type || typeof type !== 'string') return;

  const state = getState(stateFile);
  state.evolutionCount = typeof state.evolutionCount === 'number' ? state.evolutionCount + 1 : 1;
  state.lastEvolutions =
    state.lastEvolutions && typeof state.lastEvolutions === 'object' ? state.lastEvolutions : {};
  state.lastEvolutions[type] = new Date().toISOString();
  saveState(state, stateFile);
  recordAction(`evolution:${type}`, stateFile);
}

function getInteractionValidator(interactionKey) {
  const validators = {
    'SPEC-001_SPEC-002': validateSpecInitGitNotes,
    'SPEC-001_SPEC-007': validateSpecInitMetadata,
    'SPEC-001_SPEC-009': validateSpecInitAdaptive,
    'SPEC-002_SPEC-010': validateGitNotesRevert,
    'SPEC-003_SPEC-004': validateCheckpointPhaseGate,
    'SPEC-005_SPEC-006': validateBrownfieldStyleguides,
    'SPEC-005_SPEC-009': validateBrownfieldAdaptive,
    'SPEC-007_SPEC-008': validateMetadataAnalytics,
  };

  return validators[interactionKey] || null;
}

function validateSpecInitGitNotes(testData) {
  const issues = [];
