class AdaptiveQuestioner {
  constructor(domain, memoryLoader = null) {
    this.domain = domain || 'general';
    this.memoryLoader = memoryLoader;
    this.questionPool = DOMAIN_QUESTIONS[this.domain] || DOMAIN_QUESTIONS.general;
  }

  /**
   * Get next question based on context and history
   * @param {Object} context - Accumulated context
   * @param {Array} history - Question/answer history
   * @returns {Object} - { question, followupAreas, alternatives }
   */
  async getNextQuestion(context, history) {
    // Filter out already-asked questions
    const askedQuestions = history.map(h => h.question.toLowerCase());
    const availableQuestions = this.questionPool.filter(
      q => !askedQuestions.some(asked => this._isSimilar(asked, q.question.toLowerCase()))
    );

    // Filter out questions already answered by context
    const contextKeys = Object.keys(context).map(k => k.toLowerCase());
    const relevantQuestions = availableQuestions.filter(q => {
      const questionTopics = this._extractTopics(q.question);
      return !questionTopics.some(topic => contextKeys.some(key => key.includes(topic)));
    });

    // Prioritize questions based on context gaps
    // If context indicates a feature exists but related feature doesn't, prioritize the related
    const contextGaps = this._identifyContextGaps(context);

    // Prioritize by question priority AND context gaps
    const priorityOrder = { CRITICAL: 3, HIGH: 2, MEDIUM: 1 };
    const sorted = relevantQuestions.sort((a, b) => {
      // Context gap bonus (prioritize questions that fill gaps)
      const aGapBonus = contextGaps.some(gap => a.question.toLowerCase().includes(gap)) ? 2 : 0;
      const bGapBonus = contextGaps.some(gap => b.question.toLowerCase().includes(gap)) ? 2 : 0;

      const aScore = (priorityOrder[a.priority] || 0) + aGapBonus;
      const bScore = (priorityOrder[b.priority] || 0) + bGapBonus;

      return bScore - aScore;
    });

    const nextQuestion = sorted[0] || this.questionPool[0];

    // Generate alternatives
    const alternatives = this._generateAlternatives(nextQuestion.question);

    return {
      question: nextQuestion.question,
      followupAreas: nextQuestion.followups || [],
      alternatives,
    };
  }

  /**
   * Identify context gaps (features that should be asked about)
   */
  _identifyContextGaps(context) {
    const gaps = [];

    // If hasAuth is true but hasRBAC is false, ask about RBAC
    if (context.hasAuth === true && context.hasRBAC === false) {
      gaps.push('role');
      gaps.push('permission');
      gaps.push('rbac');
    }

    // If hasDatabase is true but hasBackup is false, ask about backup
    if (context.hasDatabase === true && context.hasBackup === false) {
      gaps.push('backup');
    }

    // If hasAPI is true but hasRateLimit is false, ask about rate limiting
    if (context.hasAPI === true && context.hasRateLimit === false) {
      gaps.push('rate');
      gaps.push('limit');
    }

    return gaps;
  }

  /**
   * Detect optimal stopping point
   * @param {Array} history - Question/answer history
   * @param {Object} context - Accumulated context
   * @returns {Object} - { shouldStop, readiness, missingAreas }
   */
  async detectOptimalStop(history, context) {
    if (history.length === 0) {
      return {
        shouldStop: false,
        readiness: 0,
        missingAreas: this.questionPool.map(q => q.question),
      };
    }

    // Calculate scores
    const expectedFields = this.questionPool
      .map(q => this._extractTopics(q.question)[0])
      .filter(f => f !== undefined); // Filter out undefined values

    const answers = history.map(h => ({
      answer: h.answer,
      question: h.question,
      quality: this._calculateAnswerQuality(h.answer),
    }));

    // Calculate completeness based on actual answer coverage vs expected topics
    // Use flexible matching - if history covers similar topics to expected fields
    const answeredTopics = new Set();
    history.forEach(h => {
      const topics = this._extractTopics(h.question);
      topics.forEach(t => answeredTopics.add(t));
      // Also extract topics from answers (sometimes answers mention related topics)
      const answerTopics = this._extractTopics(h.answer);
      answerTopics.forEach(t => answeredTopics.add(t));
    });

    // Match answered topics to expected fields
    const expectedMatched = expectedFields.filter(
      f =>
        f &&
        (answeredTopics.has(f) ||
          Array.from(answeredTopics).some(at => at && (at.includes(f) || f.includes(at))))
    );

    const completenessScore =
      expectedFields.length > 0
        ? Math.round((expectedMatched.length / expectedFields.length) * 100)
        : 100;

    // Load domain patterns for quality scoring
    const domainPatterns = await loadDomainPatterns(this.domain);
    const qualityScore = scoreQuality(answers, domainPatterns);
    const consistencyScore = scoreConsistency(answers, context);

    const readiness = computeOverallReadiness({
      completeness: completenessScore,
      quality: qualityScore,
      consistency: consistencyScore,
    });

    // Identify missing areas (check for CRITICAL priority questions)
    const criticalQuestions = this.questionPool.filter(q => q.priority === 'CRITICAL');
    const missingCritical = criticalQuestions.filter(q => {
      const topics = this._extractTopics(q.question);
      return !topics.some(
        t =>
          answeredTopics.has(t) ||
          Array.from(answeredTopics).some(at => at.includes(t) || t.includes(at))
      );
    });

    const missingAreas = missingCritical.map(q => q.question);

    // Stopping criteria:
    // 1. Readiness >= 80 AND no missing critical areas
    // 2. OR history.length >= 5 AND quality score >= 70 AND completeness >= 60
    // 3. OR history.length >= 10 (very long history - always stop)
    // 4. Never stop if quality score < 50 (low-quality answers)
    let shouldStop = false;

    if (qualityScore >= 50) {
      shouldStop =
        (readiness >= 80 && missingCritical.length === 0) ||
        (history.length >= 5 && qualityScore >= 70 && completenessScore >= 60) ||
        history.length >= 10;
    }

    return { shouldStop, readiness, missingAreas };
  }

  /**
   * Check if two questions are similar
   */
  _isSimilar(q1, q2) {
    const topics1 = this._extractTopics(q1);
    const topics2 = this._extractTopics(q2);
    return topics1.some(t1 => topics2.some(t2 => t1.includes(t2) || t2.includes(t1)));
  }

  /**
   * Extract topics from question
   */
  _extractTopics(question) {
    const keywords = [
      'auth',
      'authentication',
      'method',
      'token',
      'expiry',
      'password',
      'database',
      'db',
      'api',
      'endpoint',
      'cache',
      'performance',
      'test',
      'security',
      'encrypt',
      'role',
      'permission',
      'migration',
      'schema',
      'index',
      'backup',
      'rate',
      'limit',
      'version',
      'jwt',
      'oauth',
    ];

    const words = question.toLowerCase().split(/\s+/);
    return words.filter(w => keywords.includes(w) || keywords.some(k => w.includes(k)));
  }

  /**
   * Generate alternative phrasings
   */
  _generateAlternatives(question) {
    const alternatives = [
      question.replace('What ', 'Which '),
      question.replace('?', ' do you prefer?'),
      question.replace('will you', 'should the system'),
    ];
    return alternatives.filter(a => a !== question).slice(0, 2);
  }

  /**
   * Calculate answer quality (0-1 scale)
   */
  _calculateAnswerQuality(answer) {
    if (!answer || answer.trim().length === 0) return 0;

    // Quality based on length and detail
    const length = answer.length;
    if (length < 10) return 0.3;
    if (length < 30) return 0.5;
    if (length < 60) return 0.7;
    return 0.9;
  }

function sleep(ms) {
  const start = Date.now();
  while (Date.now() - start < ms) {
    // Busy wait
  }
}

function atomicWriteJSONSync(filePath, data) {
  const content = JSON.stringify(data, null, 2) + '\n';
  atomicWriteSync(filePath, content, 'utf8');
}

function restoreFromBackup(filePath, backupPath = null) {
  const backup = backupPath || `${filePath}.bak`;

  if (!fs.existsSync(backup)) {
    if (process.env.DEBUG_ATOMIC_WRITE) {
      console.error(`[atomic-write] No backup found: ${backup}`);
    }
    return false;
  }

  try {
    const content = fs.readFileSync(backup);
    atomicWriteSync(filePath, content);

    if (process.env.DEBUG_ATOMIC_WRITE) {
      console.error(`[atomic-write] Restored from: ${backup}`);
    }

    return true;
  } catch (e) {
    if (process.env.DEBUG_ATOMIC_WRITE) {
      console.error(`[atomic-write] Restore failed: ${e.message}`);
    }
    return false;
  }
}

class BottleneckAnalyzer {
  constructor(profilerMetrics) {
    this.metrics = profilerMetrics || {};
  }

  /**
   * Find functions taking more than threshold% of total time
   * @param {number} threshold - Percentage threshold (default 10%)
   * @returns {Array} Bottleneck functions sorted by impact
   */
  findBottlenecks(threshold = 10) {
    const entries = Object.entries(this.metrics);
    if (entries.length === 0) {
      return [];
    }

    // Calculate total execution time
    const totalTime = entries.reduce((sum, [, metrics]) => {
      return sum + (metrics.executionTime || 0);
    }, 0);

    if (totalTime === 0) {
      return [];
    }

    // Find functions exceeding threshold
    const bottlenecks = [];
    for (const [name, metrics] of entries) {
      const percentage = (metrics.executionTime / totalTime) * 100;
      if (percentage >= threshold) {
        bottlenecks.push({
          name,
          executionTime: metrics.executionTime,
          percentage: parseFloat(percentage.toFixed(2)),
          callCount: metrics.callCount || 1,
          memoryUsed: metrics.memoryUsed || 0,
        });
      }
    }

    // Sort by execution time (descending)
    bottlenecks.sort((a, b) => b.executionTime - a.executionTime);

    return bottlenecks;
  }

  /**
   * Analyze memory-heavy operations sorted by size
   * @returns {Array} Memory-heavy operations
   */
  analyzeMemory() {
    const entries = Object.entries(this.metrics);
    const memoryHeavy = [];

    for (const [name, metrics] of entries) {
      if (metrics.memoryUsed > 0) {
        memoryHeavy.push({
          name,
          memoryUsed: metrics.memoryUsed,
          executionTime: metrics.executionTime || 0,
        });
      }
    }

    // Sort by memory usage (descending)
    memoryHeavy.sort((a, b) => b.memoryUsed - a.memoryUsed);

    return memoryHeavy;
  }

  /**
   * Analyze slow query functions
   * @returns {Array} Slow query functions sorted by time
   */
  analyzeQueries() {
    const entries = Object.entries(this.metrics);
    const slowQueries = [];

    for (const [name, metrics] of entries) {
      // Identify query-related functions by name patterns
      if (
        name.toLowerCase().includes('query') ||
        name.toLowerCase().includes('find') ||
        name.toLowerCase().includes('search') ||
        name.toLowerCase().includes('fetch')
      ) {
        slowQueries.push({
          name,
          executionTime: metrics.executionTime || 0,
          callCount: metrics.callCount || 1,
        });
      }
    }

    // Sort by execution time (descending)
    slowQueries.sort((a, b) => b.executionTime - a.executionTime);

    return slowQueries;
  }

  /**
   * Analyze checkpointing overhead
   * @returns {Object} Checkpoint overhead analysis
   */
  analyzeCheckpointing() {
    let totalTime = 0;
    let saveTime = 0;
    let loadTime = 0;

    for (const [name, metrics] of Object.entries(this.metrics)) {
      if (name.toLowerCase().includes('checkpoint')) {
        totalTime += metrics.executionTime || 0;

        if (name.toLowerCase().includes('save')) {
          saveTime += metrics.executionTime || 0;
        } else if (name.toLowerCase().includes('load')) {
          loadTime += metrics.executionTime || 0;
        }
      }
    }

    return {
      totalTime,
      saveTime,
      loadTime,
      percentage: 0, // Would need total app time to calculate
    };
  }

  /**
   * Detect memory growth pattern from samples
   * @param {Array} samples - Array of { timestamp, memoryUsed } objects
   * @returns {Object} Memory growth analysis
   */
  getMemoryGrowthPattern(samples) {
    if (!samples || samples.length < 2) {
      return {
        trend: 'unknown',
        growthRate: 0,
      };
    }

    // Calculate linear regression to determine trend
    const n = samples.length;
    let sumX = 0;
    let sumY = 0;
    let sumXY = 0;
    let sumX2 = 0;

    for (let i = 0; i < n; i++) {
      const x = i;
      const y = samples[i].memoryUsed;
      sumX += x;
      sumY += y;
      sumXY += x * y;
      sumX2 += x * x;
    }

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    const growthRate = slope / (sumY / n); // Normalized growth rate

    let trend;
    if (Math.abs(growthRate) < 0.05) {
      trend = 'stable';
    } else if (growthRate > 0) {
      trend = 'increasing';
    } else {
      trend = 'decreasing';
    }

    return {
      trend,
      growthRate,
      sampleCount: n,
    };
  }

  /**
   * Suggest optimizations for a bottleneck
   * @param {Object} bottleneck - Bottleneck object
   * @returns {Array<string>} Optimization suggestions
   */
  suggestOptimizations(bottleneck) {
    const suggestions = [];

    // Suggest caching for repeated operations
    if (bottleneck.callCount && bottleneck.callCount > 10) {
      suggestions.push('Add caching to reduce repeated computations');
    }

    // Suggest async for I/O operations
    if (bottleneck.type === 'io' || bottleneck.name.toLowerCase().includes('save')) {
      suggestions.push('Use async/await to avoid blocking operations');
    }

    // Suggest batching for multiple calls
    if (bottleneck.callCount && bottleneck.callCount > 20) {
      suggestions.push('Batch operations to reduce overhead');
    }

    // Suggest parallel processing
    if (bottleneck.parallelizable || bottleneck.executionTime > 500) {
      suggestions.push('Use parallel processing for independent operations');
    }

    // Suggest indexing for queries
    if (
      bottleneck.name.toLowerCase().includes('query') ||
      bottleneck.name.toLowerCase().includes('search')
    ) {
      suggestions.push('Add indexing to speed up queries');
    }

    // Generic suggestion for high execution time
    if (bottleneck.executionTime > 1000) {
      suggestions.push('Profile this function in detail to identify specific bottlenecks');
    }

    return suggestions;
  }

function splitSentencesWithOffsets(text) {
  const input = String(text || '');
  const trimmed = input.trim();
  if (!trimmed) return [];
  const matches = input.matchAll(/[^.!?]+[.!?]+|[^.!?]+$/g);
  const sentences = [];
  for (const match of matches) {
    if (!match[0]) continue;
    const content = match[0].trim();
    if (!content) continue;
    const startIndex = match.index ?? 0;
    sentences.push({ content, startIndex, endIndex: startIndex + match[0].length });
  }
  return sentences;
}

function estimateTokens(text) {
  return Math.max(1, Math.ceil(String(text || '').length / 4));
}

class AgentHealthTracker {
  /**
   * Create a new AgentHealthTracker
   *
   * @param {Object} options - Configuration options
   * @param {string} [options.registryPath] - Path to agent registry JSON file
   * @param {number} [options.failureThreshold] - Number of failures before isolation
   * @param {number} [options.recoveryWindow] - Time in ms before recovery attempt
   */
  constructor(options = {}) {
    this.registryPath =
      options.registryPath || path.join(PROJECT_ROOT, '.claude/context/agent-registry.json');
    this.failureThreshold = options.failureThreshold || FAILURE_THRESHOLD;
    this.recoveryWindow = options.recoveryWindow || RECOVERY_WINDOW_MS;
  }

  /**
   * Load registry from file
   *
   * @returns {Object} The agent registry
   * @throws {Error} If file doesn't exist or can't be parsed
   */
  loadRegistry() {
    if (!fs.existsSync(this.registryPath)) {
      throw new Error(`Registry not found: ${this.registryPath}`);
    }
    const content = fs.readFileSync(this.registryPath, 'utf-8');
    return JSON.parse(content);
  }

  /**
   * Save registry to file atomically
   *
   * @param {Object} registry - The registry to save
   */
  saveRegistry(registry) {
    atomicWriteJSONSync(this.registryPath, registry);
  }

  /**
   * Record successful spawn/task completion
   *
   * @param {string} agentId - The agent ID
   * @param {number|null} [executionMs] - Execution time in milliseconds
   * @returns {boolean} True if recorded, false if agent not found
   */
  recordSuccess(agentId, executionMs = null) {
    const registry = this.loadRegistry();
    const agent = registry.agents[agentId];

    if (!agent) {
      console.warn(`[agent-health] Agent ${agentId} not found in registry`);
      return false;
    }

    // Update counters
    agent.health.successCount++;
    agent.health.consecutiveFailures = 0;
    agent.health.lastSuccessAt = new Date().toISOString();
    agent.health.lastUpdate = new Date().toISOString();

    // Update execution time (rolling average)
    if (executionMs !== null) {
      const total = agent.health.successCount + agent.health.failureCount;
      const currentAvg = agent.health.averageExecutionMs || 0;
      // Calculate new average (weighted)
      if (total === 1) {
        agent.health.averageExecutionMs = executionMs;
      } else {
        agent.health.averageExecutionMs = (currentAvg * (total - 1) + executionMs) / total;
      }
    }

    // Update success rate
    this.updateSuccessRate(agent);

    // Check for recovery from degraded (if success rate >= 0.9)
    if (agent.health.status === 'degraded' && agent.health.successRate >= RECOVERY_THRESHOLD) {
      agent.health.status = 'healthy';
      agent.health.isolatedAt = null;
      agent.health.isolationReason = null;
    }

    // Update health arrays
    this.updateHealthArrays(registry);
    this.saveRegistry(registry);

    return true;
  }

  /**
   * Record spawn/task failure
   *
   * @param {string} agentId - The agent ID
   * @param {string} [reason] - Failure reason
   * @returns {boolean} True if recorded, false if agent not found
   */
  recordFailure(agentId, reason = 'Unknown failure') {
    const registry = this.loadRegistry();
    const agent = registry.agents[agentId];

    if (!agent) {
      console.warn(`[agent-health] Agent ${agentId} not found in registry`);
      return false;
    }

    // Update counters
    agent.health.failureCount++;
    agent.health.consecutiveFailures++;
    agent.health.lastFailureAt = new Date().toISOString();
    agent.health.lastUpdate = new Date().toISOString();

    // Update success rate
    this.updateSuccessRate(agent);

    // Check for isolation (3 consecutive failures) - takes priority
    if (agent.health.consecutiveFailures >= this.failureThreshold) {
      agent.health.status = 'unavailable';
      agent.health.isolatedAt = new Date().toISOString();
      agent.health.isolationReason = `${this.failureThreshold} consecutive failures: ${reason}`;
    }
    // Check for degradation (success rate < 0.7)
    // Only applies when there's enough history (MIN_HISTORY_FOR_DEGRADATION operations)
    // This prevents brand new agents from being degraded after just 1-2 failures
    else {
      const totalOperations = agent.health.successCount + agent.health.failureCount;
      if (
        totalOperations >= MIN_HISTORY_FOR_DEGRADATION &&
        agent.health.successRate < DEGRADED_THRESHOLD
      ) {
        agent.health.status = 'degraded';
      }
    }

    // Update health arrays
    this.updateHealthArrays(registry);
    this.saveRegistry(registry);

    return true;
  }

  /**
   * Attempt recovery for isolated agents
   *
   * @param {string} agentId - The agent ID
   * @returns {{ success: boolean, reason: string }} Recovery result
   */
  attemptRecovery(agentId) {
    const registry = this.loadRegistry();
    const agent = registry.agents[agentId];

    if (!agent) {
      return { success: false, reason: 'Agent not found' };
    }

    if (agent.health.status !== 'unavailable') {
      return { success: false, reason: 'Agent not isolated' };
    }

    // Check recovery window
    const isolatedAt = new Date(agent.health.isolatedAt);
    const now = new Date();
    const timeSinceIsolation = now - isolatedAt;

    if (timeSinceIsolation < this.recoveryWindow) {
      const remainingMs = this.recoveryWindow - timeSinceIsolation;
      const remainingSecs = Math.ceil(remainingMs / 1000);
      return {
        success: false,
        reason: `Recovery cooldown active (${remainingSecs}s remaining)`,
      };
    }

    // Reset for recovery attempt
    agent.health.consecutiveFailures = 0;
    agent.health.status = 'degraded';
    agent.health.lastUpdate = new Date().toISOString();

    // Keep isolation info for audit trail (don't clear isolatedAt/isolationReason)

    // Update health arrays
    this.updateHealthArrays(registry);
    this.saveRegistry(registry);

    return { success: true, reason: 'Recovery attempted, status set to degraded' };
  }

  /**
   * Get health report for all agents
   *
   * @returns {Object} Health report with summary and agent lists
   */
  getHealthReport() {
    const registry = this.loadRegistry();

    return {
      summary: {
        totalAgents: registry.metadata.totalAgents,
        healthy: registry.health.healthy.length,
        degraded: registry.health.degraded.length,
        unavailable: registry.health.unavailable.length,
        lastCheck: new Date().toISOString(),
      },
      healthy: registry.health.healthy,
      degraded: registry.health.degraded.map(id => ({
        id,
        successRate: registry.agents[id]?.health.successRate,
        consecutiveFailures: registry.agents[id]?.health.consecutiveFailures,
      })),
      unavailable: registry.health.unavailable.map(id => ({
        id,
        isolatedAt: registry.agents[id]?.health.isolatedAt,
        reason: registry.agents[id]?.health.isolationReason,
      })),
    };
  }

  /**
   * Reset agent health to default
   *
   * @param {string} agentId - The agent ID
   * @returns {boolean} True if reset, false if agent not found
   */
  resetHealth(agentId) {
    const registry = this.loadRegistry();
    const agent = registry.agents[agentId];

    if (!agent) {
      return false;
    }

    agent.health = {
      status: 'healthy',
      consecutiveFailures: 0,
      successCount: 0,
      failureCount: 0,
      successRate: 1.0,
      averageExecutionMs: null,
      lastUpdate: new Date().toISOString(),
      isolatedAt: null,
      isolationReason: null,
      lastSuccessAt: null,
      lastFailureAt: null,
    };

    // Update health arrays
    this.updateHealthArrays(registry);
    this.saveRegistry(registry);

    return true;
  }

  /**
   * Update success rate calculation
   *
   * @param {Object} agent - The agent object
   */
  updateSuccessRate(agent) {
    const total = agent.health.successCount + agent.health.failureCount;
    if (total === 0) {
      agent.health.successRate = 1.0;
    } else {
      agent.health.successRate = agent.health.successCount / total;
    }
  }

  /**
   * Update health arrays in registry
   *
   * @param {Object} registry - The registry object
   */
  updateHealthArrays(registry) {
    registry.health.healthy = [];
    registry.health.degraded = [];
    registry.health.unavailable = [];

    for (const [agentId, agent] of Object.entries(registry.agents)) {
      switch (agent.health.status) {
        case 'healthy':
          registry.health.healthy.push(agentId);
          break;
        case 'degraded':
          registry.health.degraded.push(agentId);
          break;
        case 'unavailable':
          registry.health.unavailable.push(agentId);
          break;
      }
    }

    // Update metadata
    registry.metadata.healthyAgents = registry.health.healthy.length;
    registry.metadata.degradedAgents = registry.health.degraded.length;
    registry.metadata.unavailableAgents = registry.health.unavailable.length;
    registry.metadata.lastHealthCheck = new Date().toISOString();
  }

function resetInstance() {
  trackerInstance = null;
