function normalizeModelName(model) {
  if (!model) return 'sonnet';

  const modelLower = model.toLowerCase();

  if (modelLower.includes('haiku')) return 'haiku';
  if (modelLower.includes('sonnet')) return 'sonnet';
  if (modelLower.includes('opus')) return 'opus';

  // Return original if it's already a valid short form
  if (['haiku', 'sonnet', 'opus'].includes(modelLower)) {
    return modelLower;
  }

  // Default fallback
  return 'sonnet';
}

function parseAgentFrontmatter(content) {
  const frontmatterMatch = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!frontmatterMatch) return null;

  try {
    if (yaml) {
      return yaml.load(frontmatterMatch[1]);
    }
    // Fallback: simple YAML parsing for key: value pairs
    return parseSimpleYaml(frontmatterMatch[1]);
  } catch (_error) {
    // If the YAML parser rejects the frontmatter, fall back to the simple parser.
    // This keeps registry generation resilient to slightly-nonstandard YAML.
    try {
      const parsed = parseSimpleYaml(frontmatterMatch[1]);
      if (!parsed || !parsed.name || !parsed.description) return null;
      return parsed;
    } catch (_fallbackError) {
      // Don't throw, just return null for invalid frontmatter
      return null;
    }
  }
}

function parseSimpleYaml(yamlContent) {
  const result = {};
  const lines = yamlContent.split('\n');
  let currentKey = null;
  let inArray = false;
  let arrayValues = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Array context (supports both dash arrays and flow arrays split across lines)
    if (inArray && currentKey) {
      // Flow array delimiters
      if (trimmed === '[') continue;
      if (trimmed === ']') {
        result[currentKey] = arrayValues;
        arrayValues = [];
        inArray = false;
        currentKey = null;
        continue;
      }

      // Dash array item
      if (trimmed.startsWith('- ')) {
        const raw = trimmed.slice(2).trim();
        const withoutComment = raw.replace(/\s+#.*$/, '').trim();
        if (withoutComment) arrayValues.push(parseYamlValue(withoutComment));
        continue;
      }

      const colonIndex = trimmed.indexOf(':');
      if (colonIndex <= 0) {
        // Flow array item (e.g. "Read," or "'some string',")
        const raw = trimmed.replace(/,\s*$/, '').trim();
        const withoutComment = raw.replace(/\s+#.*$/, '').trim();
        if (!withoutComment) continue;

        // Allow a one-line inline array inside an array context:
        // tools:
        //   [Read, Write]
        if (withoutComment.startsWith('[') && withoutComment.endsWith(']')) {
          const arrayContent = withoutComment.slice(1, -1);
          arrayContent
            .split(',')
            .map(s => s.trim())
            .filter(Boolean)
            .forEach(v => arrayValues.push(parseYamlValue(v)));
          continue;
        }

        arrayValues.push(parseYamlValue(withoutComment));
        continue;
      }

      // New key encountered: finish previous array and continue parsing the key line below
      result[currentKey] = arrayValues;
      arrayValues = [];
      inArray = false;
      currentKey = null;
    }

    // Key: value
    const colonIndex = trimmed.indexOf(':');
    if (colonIndex > 0) {
      const key = trimmed.slice(0, colonIndex).trim();
      const value = trimmed.slice(colonIndex + 1).trim();

      // Handle inline array [a, b, c]
      if (value.startsWith('[') && value.endsWith(']')) {
        const arrayContent = value.slice(1, -1);
        result[key] = arrayContent
          .split(',')
          .map(s => s.trim())
          .filter(Boolean);
        inArray = false;
        currentKey = null;
        continue;
      }

      if (value === '' || value === '[') {
        // Start of array or nested object
        currentKey = key;
        inArray = true;
        arrayValues = [];
      } else {
        // Simple value
        result[key] = parseYamlValue(value);
        currentKey = null;
      }
    }
  }

  // Handle trailing array
  if (inArray && currentKey) {
    result[currentKey] = arrayValues;
  }

  return result;
}

function parseYamlValue(value) {
  if (value === 'true') return true;
  if (value === 'false') return false;
  if (value === 'null' || value === '~') return null;
  if (/^-?\d+$/.test(value)) return parseInt(value, 10);
  if (/^-?\d+\.\d+$/.test(value)) return parseFloat(value);
  // Remove quotes
  if (
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"))
  ) {
    return value.slice(1, -1);
  }
  return value;
}

function extractTriggerPhrases(agentDef, agentId) {
  const phrases = [];

  // From agent name (split by hyphens, filter short parts)
  const namePhrases = agentId.split('-').filter(p => p.length > 2);
  phrases.push(...namePhrases);

  // From description
  if (agentDef.description) {
    // Extract key action words
    const actionWords =
      agentDef.description.match(
        /\b(implement|review|test|debug|design|analyze|fix|build|create|deploy|optimize|refactor|validate|audit|plan|coordinate|orchestrate)\w*/gi
      ) || [];
    phrases.push(...actionWords.map(w => w.toLowerCase()));
  }

  // From skills
  if (agentDef.skills && Array.isArray(agentDef.skills)) {
    phrases.push(...agentDef.skills.filter(s => s.length > 2));
  }

  // Dedupe and return
  return [...new Set(phrases)];
}

function extractExamplesAndTags(agentDef, triggerPhrases, skills) {
  const examples = Array.isArray(agentDef.examples)
    ? agentDef.examples
    : Array.isArray(agentDef.capability_examples)
      ? agentDef.capability_examples
      : [];
  const tagsFromFrontmatter = Array.isArray(agentDef.tags) ? agentDef.tags : [];
  const tagsFromPhrases = (triggerPhrases || [])
    .flatMap(phrase => phrase.toLowerCase().split(/\s+/))
    .filter(word => word.length > 2);
  const tags = [...new Set([...tagsFromFrontmatter, ...tagsFromPhrases, ...(skills || [])])];
  return { examples, tags };
}

function inferDomain(agentDef, agentId, category) {
  // Check skills first
  if (agentDef.skills && Array.isArray(agentDef.skills)) {
    for (const skill of agentDef.skills) {
      const skillLower = skill.toLowerCase();
      const domain = DOMAIN_MAPPING[skillLower];
      if (domain) return domain;
    }
  }

  // Check agent ID keywords
  const idLower = agentId.toLowerCase();
  for (const [keyword, domain] of Object.entries(DOMAIN_MAPPING)) {
    if (idLower.includes(keyword)) return domain;
  }

  // Fallback by category
  const categoryDomains = {
    core: 'code',
    specialized: 'code',
    domain: 'code',
    orchestrator: 'orchestration',
  };

  return categoryDomains[category] || 'code';
}

function loadAgentSkillMatrixAndSkillIndex() {
  let matrix = { agents: {} };
  let skillIndex = { skills: {} };
  try {
    if (fs.existsSync(AGENT_SKILL_MATRIX_PATH)) {
      matrix = JSON.parse(fs.readFileSync(AGENT_SKILL_MATRIX_PATH, 'utf8'));
    }
  } catch (_error) {
    // ignore
  }
  try {
    if (fs.existsSync(SKILL_INDEX_PATH)) {
      skillIndex = JSON.parse(fs.readFileSync(SKILL_INDEX_PATH, 'utf8'));
    }
  } catch (_error) {
    // ignore
  }
  return { matrix, skillIndex };
}

function getRequiredToolsUnionForAgent(agentId, matrix, skillIndex) {
  const skills = new Set();
  const agents = matrix.agents || {};
  for (const categoryAgents of Object.values(agents)) {
    if (typeof categoryAgents !== 'object') continue;
    const config = categoryAgents[agentId];
    if (!config) continue;
    const primary = Array.isArray(config.primary) ? config.primary : [];
    const secondary = Array.isArray(config.secondary) ? config.secondary : [];
    const always = Array.isArray(config.always) ? config.always : [];
    const contextual =
      config.contextual && typeof config.contextual === 'object'
        ? Object.values(config.contextual).flat()
        : [];
    [...primary, ...secondary, ...always, ...contextual].forEach(s => skills.add(s));
  }
  const tools = new Set();
  const indexSkills = skillIndex.skills || {};
  for (const skillName of skills) {
    const skill = indexSkills[skillName];
    if (skill && Array.isArray(skill.requiredTools)) {
      skill.requiredTools.forEach(t => tools.add(t));
    }
  }
  return [...tools];
}

function generateCapabilityCard(agentDef, agentId, category, filePath, toolsUnionFromSkills = []) {
  const domain = inferDomain(agentDef, agentId, category);
  const triggerPhrases = extractTriggerPhrases(agentDef, agentId);

  // Get tools list from agent .md
  let tools = ['Read', 'Write', 'Edit', 'Bash'];
  if (agentDef.tools) {
    if (Array.isArray(agentDef.tools)) {
      tools = agentDef.tools;
    } else if (typeof agentDef.tools === 'string') {
      tools = agentDef.tools
        .trim()
        .replace(/^\[/, '')
        .replace(/\]$/, '')
        .split(',')
        .map(t => t.trim())
        .filter(Boolean);
    }
  }
  // Merge with union of tools required by this agent's skills so registry has full set
  if (toolsUnionFromSkills.length > 0) {
    const merged = new Set([...tools, ...toolsUnionFromSkills]);
    tools = [...merged];
  }

  // Get skills list
  const skills = agentDef.skills && Array.isArray(agentDef.skills) ? agentDef.skills : [];
  const { examples, tags } = extractExamplesAndTags(agentDef, triggerPhrases, skills);

  // Build display name
  let displayName = agentDef.name;
  if (!displayName) {
    displayName = agentId
      .split('-')
      .map(w => w.charAt(0).toUpperCase() + w.slice(1))
      .join(' ');
  }

  // Primary capability name (clean up agent ID)
  const capabilityName = agentId.replace(/-pro$/, '').replace(/-expert$/, '');

  // Truncate description to 200 chars for schema compliance
  let description = agentDef.description || `${displayName} capability`;
  if (description.length > 200) {
    description = description.slice(0, 197) + '...';
  }

  // Build capabilities from skills and description
  const capabilities = [
    {
      name: capabilityName,
      domain: domain,
      description: description,
      triggerPhrases: triggerPhrases.slice(0, 10),
      requiredTools: tools.slice(0, 18),
      skills: skills.slice(0, 10),
      examples: examples.slice(0, 10),
      tags: tags.slice(0, 15),
    },
  ];

  // Normalize file path to relative format
  let relativePath = filePath;
  if (path.isAbsolute(filePath)) {
    relativePath = path.relative(PROJECT_ROOT, filePath);
  }
  relativePath = relativePath.replace(/\\/g, '/');
  if (!relativePath.startsWith('.')) {
    relativePath = './' + relativePath;
  }
  // Normalize to expected format
  relativePath = relativePath.replace('./', '.claude/');
  if (!relativePath.startsWith('.claude/')) {
    relativePath = '.claude/' + relativePath.replace(/^\.\//, '');
  }

  return {
    id: agentId,
    displayName: displayName,
    category: category,
    filePath: relativePath,
    capabilities: capabilities,
    constraints: {
      maxConcurrentTasks: 5,
      preferredModel: normalizeModelName(agentDef.model),
    },
    health: {
      status: 'healthy',
      consecutiveFailures: 0,
      successCount: 0,
      failureCount: 0,
      successRate: 1.0,
      lastUpdate: new Date().toISOString(),
      isolatedAt: null,
      isolationReason: null,
    },
    metadata: {
      version: agentDef.version || '1.0.0',
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    },
  };
}

class AgentRegistryGenerator {
  constructor() {
    this.agents = new Map();
    this.registry = {
      version: '1.0.0',
      generatedAt: null,
      metadata: {},
      agents: {},
      index: {
        byCapability: {},
        byDomain: {},
        byCategory: {},
      },
      health: {
        healthy: [],
        degraded: [],
        unavailable: [],
      },
    };
  }

  /**
   * Scan all agent directories
   * @param {string} agentsDir - Path to agents directory
   * @returns {Promise<Map>} Map of agent ID to agent info
   */
  async scanAgents(agentsDir) {
    const categories = ['core', 'specialized', 'domain', 'orchestrators'];
    const agents = new Map();

    for (const category of categories) {
      const categoryDir = path.join(agentsDir, category);

      if (!fs.existsSync(categoryDir)) continue;

      const files = fs.readdirSync(categoryDir).filter(f => f.endsWith('.md'));

      for (const file of files) {
        // Skip README files
        if (file.toLowerCase() === 'readme.md') continue;

        const filePath = path.join(categoryDir, file);
        const content = fs.readFileSync(filePath, 'utf-8');
        const agentDef = parseAgentFrontmatter(content);

        if (!agentDef) {
          // Skip files without valid frontmatter
          continue;
        }

        const agentId = file.replace('.md', '');
        // Normalize category (orchestrators -> orchestrator)
        const normalizedCategory = category === 'orchestrators' ? 'orchestrator' : category;

        agents.set(agentId, {
          definition: agentDef,
          category: normalizedCategory,
          filePath: filePath,
        });
      }
    }

    return agents;
  }

  /**
   * Build indices for fast lookup
   */
  buildIndices() {
    for (const [agentId, card] of Object.entries(this.registry.agents)) {
      // Index by category
      if (!this.registry.index.byCategory[card.category]) {
        this.registry.index.byCategory[card.category] = [];
      }
      if (!this.registry.index.byCategory[card.category].includes(agentId)) {
        this.registry.index.byCategory[card.category].push(agentId);
      }

      // Index by capabilities
      for (const capability of card.capabilities) {
        if (!this.registry.index.byCapability[capability.name]) {
          this.registry.index.byCapability[capability.name] = [];
        }
        if (!this.registry.index.byCapability[capability.name].includes(agentId)) {
          this.registry.index.byCapability[capability.name].push(agentId);
        }

        // Index by domain
        if (!this.registry.index.byDomain[capability.domain]) {
          this.registry.index.byDomain[capability.domain] = [];
        }
        if (!this.registry.index.byDomain[capability.domain].includes(agentId)) {
          this.registry.index.byDomain[capability.domain].push(agentId);
        }
      }
    }
  }

  /**
   * Update health summary arrays
   */
  updateHealthSummary() {
    this.registry.health.healthy = [];
    this.registry.health.degraded = [];
    this.registry.health.unavailable = [];

    for (const [agentId, card] of Object.entries(this.registry.agents)) {
      switch (card.health.status) {
        case 'healthy':
          this.registry.health.healthy.push(agentId);
          break;
        case 'degraded':
          this.registry.health.degraded.push(agentId);
          break;
        case 'unavailable':
          this.registry.health.unavailable.push(agentId);
          break;
      }
    }
  }

  /**
   * Generate full registry
   * @param {string} agentsDir - Path to agents directory
   * @returns {Promise<Object>} Generated registry
   */
  async generate(agentsDir) {
    const agents = await this.scanAgents(agentsDir);
    const { matrix, skillIndex } = loadAgentSkillMatrixAndSkillIndex();

    for (const [agentId, agentInfo] of agents) {
      let toolsUnionFromSkills = getRequiredToolsUnionForAgent(agentId, matrix, skillIndex);
      if (!Array.isArray(toolsUnionFromSkills) || toolsUnionFromSkills.length === 0) {
        toolsUnionFromSkills = getDefaultTools(agentId);
      }
      const card = generateCapabilityCard(
        agentInfo.definition,
        agentId,
        agentInfo.category,
        agentInfo.filePath,
        toolsUnionFromSkills
      );
      this.registry.agents[agentId] = card;
    }

    this.buildIndices();
    this.updateHealthSummary();

    this.registry.generatedAt = new Date().toISOString();
    this.registry.metadata = {
      totalAgents: Object.keys(this.registry.agents).length,
      healthyAgents: this.registry.health.healthy.length,
      degradedAgents: this.registry.health.degraded.length,
      unavailableAgents: this.registry.health.unavailable.length,
      lastHealthCheck: new Date().toISOString(),
      lastFullScan: new Date().toISOString(),
    };

    return this.registry;
  }

  /**
   * Validate registry against schema
   * @param {Object} registry - Registry to validate
   * @returns {Object} Validation result
   */
  validate(registry) {
    const schemaPath = path.join(PROJECT_ROOT, '.claude/schemas/agent-capability-card.schema.json');

    if (!fs.existsSync(schemaPath)) {
      return { valid: true, errors: [], message: 'Schema file not found, skipping validation' };
    }

    if (!Ajv || !addFormats) {
      return { valid: true, errors: [], message: 'AJV not available, skipping validation' };
    }

    const schema = JSON.parse(fs.readFileSync(schemaPath, 'utf-8'));
    const ajv = new Ajv({ allErrors: true, strict: false });
    addFormats(ajv);

    const validate = ajv.compile(schema);
    const errors = [];

    for (const [agentId, card] of Object.entries(registry.agents)) {
      if (!validate(card)) {
        errors.push({
          agentId,
          errors: validate.errors,
        });
      }
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }

  /**
   * Save registry to file
   * @param {Object} registry - Registry to save
   * @param {string} outputPath - Output file path
   */
  saveRegistry(registry, outputPath) {
    const dir = path.dirname(outputPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    fs.writeFileSync(outputPath, JSON.stringify(registry, null, 2));
    console.log(`Registry saved to ${outputPath}`);
  }

async function main() {
  const generator = new AgentRegistryGenerator();
  const agentsDir = path.join(PROJECT_ROOT, '.claude/agents');
  const outputPath = path.join(PROJECT_ROOT, '.claude/context/agent-registry.json');

  console.log('Scanning agents...');
  const registry = await generator.generate(agentsDir);

  console.log(`Found ${registry.metadata.totalAgents} agents`);

  const validation = generator.validate(registry);
  if (!validation.valid) {
    console.error('Validation errors:', JSON.stringify(validation.errors, null, 2));
    process.exit(1);
  }

  generator.saveRegistry(registry, outputPath);
  console.log('Registry generation complete');
}

function normalizeAgentPath(filePath) {
  if (!filePath) return null;
  let normalized = filePath;
  if (path.isAbsolute(normalized)) {
    normalized = path.relative(PROJECT_ROOT, normalized);
  }
  normalized = normalized.replace(/\\/g, '/');
  if (!normalized.startsWith('.claude/')) {
    normalized = '.claude/' + normalized.replace(/^\.\//, '');
  }
  return normalized;
}

function scanAgentsFromFilesystem(agentsDir) {
  const categories = ['core', 'specialized', 'domain', 'orchestrators'];
  const agents = new Map();

  for (const category of categories) {
    const categoryDir = path.join(agentsDir, category);
    if (!fs.existsSync(categoryDir)) continue;

    const files = fs.readdirSync(categoryDir).filter(f => f.endsWith('.md'));
    for (const file of files) {
      if (file.toLowerCase() === 'readme.md') continue;

      const filePath = path.join(categoryDir, file);
      const content = fs.readFileSync(filePath, 'utf-8');
      const agentDef = parseAgentFrontmatter(content);
      if (!agentDef) continue;

      const agentId = file.replace('.md', '');
      agents.set(agentId, {
        filePath: normalizeAgentPath(filePath),
      });
    }
  }

  return agents;
}

class AvailableAgentsQuery {
  /**
   * Create an AvailableAgentsQuery instance
   * @param {Object} options - Configuration options
   * @param {string} options.registryPath - Path to agent registry JSON
   * @param {number} options.cacheTTL - Cache TTL in milliseconds (default: 2 minutes)
   * @param {number} options.cacheMaxSize - Maximum cache entries (default: 50)
   */
  constructor(options = {}) {
    this.registryPath = options.registryPath || DEFAULT_REGISTRY_PATH;
    this.agentsDir = options.agentsDir || DEFAULT_AGENTS_DIR;
    this.registry = null;
    this.cache = new Map();
    this.cacheTimeouts = new Map();
    this.CACHE_TTL = options.cacheTTL || 2 * 60 * 1000; // 2 minutes
    this.CACHE_MAX_SIZE = options.cacheMaxSize || 50;
    this.CONSISTENCY_CHECK_INTERVAL = options.consistencyCheckIntervalMs || 5 * 60 * 1000; // 5 minutes
    this.enableConsistencyCheck =
      options.enableConsistencyCheck ?? this.registryPath === DEFAULT_REGISTRY_PATH;
    this._lastConsistencyCheckAt = 0;
  }

  /**
   * Load registry from file (lazy loading + caching)
   * @returns {Object} The agent registry
   * @throws {Error} If registry cannot be loaded
   */
  getRegistry() {
    if (this.registry) return this.registry;

    try {
      const content = fs.readFileSync(this.registryPath, 'utf-8');
      this.registry = JSON.parse(content);
      this.checkRegistryConsistency();
      return this.registry;
    } catch (error) {
      throw new Error(`Failed to load agent registry: ${error.message}`);
    }
  }

  checkRegistryConsistency() {
    if (!this.enableConsistencyCheck) return;
    if (process.env.REGISTRY_CONSISTENCY_CHECK === 'off') return;

    const now = Date.now();
    if (now - this._lastConsistencyCheckAt < this.CONSISTENCY_CHECK_INTERVAL) {
      return;
    }
    this._lastConsistencyCheckAt = now;

    try {
      const registryAgents = this.registry?.agents || {};
      const registryIds = Object.keys(registryAgents);
      const registryIdSet = new Set(registryIds);
      const fileAgents = scanAgentsFromFilesystem(this.agentsDir);

      const missingOnDisk = [];
      const pathMismatch = [];
      for (const agentId of registryIds) {
        const entry = registryAgents[agentId];
        const fileInfo = fileAgents.get(agentId);
        if (!fileInfo) {
          missingOnDisk.push(agentId);
          continue;
        }
        const registryPath = normalizeAgentPath(entry?.filePath);
        if (registryPath && registryPath !== fileInfo.filePath) {
          pathMismatch.push({ agentId, registryPath, filePath: fileInfo.filePath });
        }
      }

      const missingInRegistry = [];
      for (const agentId of fileAgents.keys()) {
        if (!registryIdSet.has(agentId)) {
          missingInRegistry.push(agentId);
        }
      }

      if (
        missingOnDisk.length === 0 &&
        missingInRegistry.length === 0 &&
        pathMismatch.length === 0
      ) {
        return;
      }

      const summary = [
        missingOnDisk.length > 0 ? `missing on disk: ${missingOnDisk.length}` : null,
        missingInRegistry.length > 0 ? `missing in registry: ${missingInRegistry.length}` : null,
        pathMismatch.length > 0 ? `path mismatches: ${pathMismatch.length}` : null,
      ]
        .filter(Boolean)
        .join(', ');

      const message = [
        '[registry] Agent registry drift detected:',
        summary,
        'Run: npm run gen:agent-registry',
      ].join(' ');

      if (process.env.REGISTRY_CONSISTENCY_GATE === 'block') {
        throw new Error(message);
      }

      console.warn(message);
    } catch (error) {
      if (process.env.REGISTRY_CONSISTENCY_GATE === 'block') {
        throw error;
      }
      console.warn('[registry] Consistency check failed (non-blocking):', error.message);
    }
  }

  /**
   * Main query function - find agents by criteria
   *
   * @param {Object} options - Query options
   * @param {string} options.capability - Filter by capability (e.g., 'code-review')
   * @param {string} options.domain - Filter by domain (e.g., 'code', 'testing')
   * @param {string} options.category - Filter by category (e.g., 'core', 'specialized')
   * @param {boolean} options.excludeFailed - Exclude unavailable agents (default: true)
   * @param {number} options.minSuccessRate - Minimum success rate 0-1 (default: 0.7)
   * @param {number} options.limit - Maximum results 1-50 (default: 10)
   * @returns {Object} Query result with matching agents
   */
  query(options = {}) {
    // Handle undefined/null options
    if (options === undefined || options === null) {
      options = {};
    }

    // 1. Validate options
    const validationError = this.validateOptions(options);
    if (validationError) {
      return this.buildErrorResponse(validationError);
    }

    // 2. Check cache
    const cacheKey = this.getCacheKey(options);
    const cached = this.getFromCache(cacheKey);
    if (cached) {
      return cached;
    }

    // 3. Load registry
    let registry;
    try {
      registry = this.getRegistry();
    } catch (error) {
      return this.buildErrorResponse(error.message);
    }

    let agents = [];

    // 4. Filter by capability (using index for O(1) lookup)
    if (options.capability) {
      const capAgentIds = registry.index?.byCapability?.[options.capability] || [];
      agents = capAgentIds.map(id => registry.agents[id]).filter(Boolean);
    }
    // 5. Filter by domain (using index)
    else if (options.domain) {
      const domainAgentIds = registry.index?.byDomain?.[options.domain] || [];
      agents = domainAgentIds.map(id => registry.agents[id]).filter(Boolean);
    }
    // 6. Filter by category (using index)
    else if (options.category) {
      const categoryAgentIds = registry.index?.byCategory?.[options.category] || [];
      agents = categoryAgentIds.map(id => registry.agents[id]).filter(Boolean);
    }
    // 7. Default: all agents
    else {
      agents = Object.values(registry.agents || {});
    }

    // 8. Filter by health status
    const excludeFailed = options.excludeFailed !== false; // default true
    if (excludeFailed) {
      agents = agents.filter(a => a.health?.status !== 'unavailable');
    }

    // 9. Filter by minimum success rate
    const minRate = options.minSuccessRate ?? 0.7;
    agents = agents.filter(a => (a.health?.successRate ?? 1.0) >= minRate);

    // 10. Sort by success rate DESC (best first), then by execution time
    agents.sort((a, b) => {
      const rateA = a.health?.successRate ?? 1.0;
      const rateB = b.health?.successRate ?? 1.0;
      if (rateB !== rateA) {
        return rateB - rateA;
      }
      // Secondary sort: prefer faster agents
      const timeA = a.health?.averageExecutionMs ?? Infinity;
      const timeB = b.health?.averageExecutionMs ?? Infinity;
      return timeA - timeB;
    });

    // 11. Apply limit
    const limit = Math.min(options.limit || 10, 50);
    agents = agents.slice(0, limit);

    // 12. Build and cache response
    const response = {
      success: true,
      agents: agents,
      count: agents.length,
      query: options,
    };

    this.setCache(cacheKey, response);
    return response;
  }

  /**
   * Get a single agent by ID
   * @param {string} agentId - The agent ID
   * @returns {Object|null} The agent or null if not found
   */
  getAgent(agentId) {
    try {
      const registry = this.getRegistry();
      return registry.agents?.[agentId] || null;
    } catch {
      return null;
    }
  }

  /**
   * Check if an agent is available (optionally for a specific capability)
   * @param {string} agentId - The agent ID
   * @param {string} capability - Optional capability to check
   * @returns {boolean} True if agent is available
   */
  isAvailable(agentId, capability = null) {
    const agent = this.getAgent(agentId);
    if (!agent) return false;
    if (agent.health?.status === 'unavailable') return false;

    if (capability) {
      return agent.capabilities?.some(c => c.name === capability) ?? false;
    }

    return true;
  }

  /**
   * Get the best agent for a capability
   * @param {string} capability - The capability to find
   * @returns {Object|null} The best agent or null
   */
  getBestAgent(capability) {
    const result = this.query({
      capability,
      excludeFailed: true,
      minSuccessRate: 0.7,
      limit: 1,
    });

    return result.success && result.count > 0 ? result.agents[0] : null;
  }

  /**
   * Get available filter options
   * @returns {Object} Filter metadata (capabilities, domains, categories)
   */
  getAvailableFilters() {
    try {
      const registry = this.getRegistry();

      return {
        capabilities: Object.keys(registry.index?.byCapability || {}),
        domains: Object.keys(registry.index?.byDomain || {}),
        categories: Object.keys(registry.index?.byCategory || {}),
        totalAgents: registry.metadata?.totalAgents || Object.keys(registry.agents || {}).length,
        healthyAgents: registry.metadata?.healthyAgents || registry.health?.healthy?.length || 0,
      };
    } catch {
      return {
        capabilities: [],
        domains: [],
        categories: [],
        totalAgents: 0,
        healthyAgents: 0,
      };
    }
  }

  /**
   * Get available capabilities
   * @returns {string[]} List of available capabilities
   */
  getAvailableCapabilities() {
    const filters = this.getAvailableFilters();
    return filters.capabilities;
  }

  /**
   * Get available domains
   * @returns {string[]} List of available domains
   */
  getAvailableDomains() {
    const filters = this.getAvailableFilters();
    return filters.domains;
  }

  /**
   * Validate query options
   * @param {Object} options - Query options to validate
   * @returns {string|null} Error message or null if valid
   */
  validateOptions(options) {
    if (typeof options !== 'object' || options === null) {
      return 'Options must be an object';
    }

    if (options.limit !== undefined) {
      if (!Number.isInteger(options.limit) || options.limit < 1 || options.limit > 50) {
        return 'limit must be an integer between 1 and 50';
      }
    }

    if (options.minSuccessRate !== undefined) {
      if (
        typeof options.minSuccessRate !== 'number' ||
        options.minSuccessRate < 0 ||
        options.minSuccessRate > 1
      ) {
        return 'minSuccessRate must be a number between 0 and 1';
      }
    }

    return null;
  }

  /**
   * Build error response
   * @param {string} error - Error message
   * @returns {Object} Error response object
   */
  buildErrorResponse(error) {
    return {
      success: false,
      error: error,
      agents: [],
      count: 0,
    };
  }

  /**
   * Build response when no agents match
   * @param {Object} options - Original query options
   * @returns {Object} No-match response with suggestions
   */
  buildNoMatchResponse(options) {
    const filters = this.getAvailableFilters();

    return {
      success: false,
      agents: [],
      count: 0,
      error: `No agents found matching: ${this.describeQuery(options)}`,
      suggestions: {
        message: 'Try domain filtering instead',
        alternatives: [{ domain: filters.domains[0] || 'code' }, { category: 'core' }],
      },
    };
  }

  /**
   * Generate cache key from query options
   * @param {Object} options - Query options
   * @returns {string} Cache key
   */
  getCacheKey(options) {
    return JSON.stringify(options, Object.keys(options || {}).sort());
  }

  /**
   * Get value from cache if valid
   * @param {string} key - Cache key
   * @returns {Object|null} Cached value or null
   */
  getFromCache(key) {
    if (this.cache.has(key)) {
      const timeout = this.cacheTimeouts.get(key);
      if (timeout && Date.now() > timeout) {
        this.cache.delete(key);
        this.cacheTimeouts.delete(key);
        return null;
      }
      return this.cache.get(key);
    }
    return null;
  }

  /**
   * Store value in cache
   * @param {string} key - Cache key
   * @param {Object} value - Value to cache
   */
  setCache(key, value) {
    // Implement LRU: remove oldest if at max size
    if (this.cache.size >= this.CACHE_MAX_SIZE) {
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
      this.cacheTimeouts.delete(firstKey);
    }

    this.cache.set(key, value);
    this.cacheTimeouts.set(key, Date.now() + this.CACHE_TTL);
  }

  /**
   * Clear cache (useful for testing and registry updates)
   */
  clearCache() {
    this.cache.clear();
    this.cacheTimeouts.clear();
    this.registry = null;
  }

  /**
   * Helper: describe query in human-readable form
   * @param {Object} options - Query options
   * @returns {string} Human-readable description
   */
  describeQuery(options) {
    const parts = [];
    if (options.capability) parts.push(`capability='${options.capability}'`);
    if (options.domain) parts.push(`domain='${options.domain}'`);
    if (options.category) parts.push(`category='${options.category}'`);
    if (options.minSuccessRate) parts.push(`minSuccessRate=${options.minSuccessRate}`);
    return parts.join(' AND ') || 'all agents';
  }

