function loadConfig(projectRoot) {
  try {
    const env = process.env.AGENT_STUDIO_ENV;
    const baseDir = path.join(projectRoot, '.claude');
    const stagingPath = path.join(baseDir, 'config.staging.yaml');
    const defaultPath = path.join(baseDir, 'config.yaml');
    const configPath = env === 'staging' && fs.existsSync(stagingPath) ? stagingPath : defaultPath;
    if (!fs.existsSync(configPath)) {
      return null;
    }
    const content = fs.readFileSync(configPath, 'utf8');
    return yaml.load(content);
  } catch (_e) {
    return null;
  }
}

function getModelFromConfig(agentType, projectRoot) {
  const config = loadConfig(projectRoot);
  if (!config || !config.agents || !config.agents[agentType]) {
    return null;
  }
  return config.agents[agentType].model || null;
}

function getAgentConfig(agentType, projectRoot) {
  const config = loadConfig(projectRoot);
  if (!config || !config.agents || !config.agents[agentType]) {
    return null;
  }
  return config.agents[agentType];
}

function getModelFromFrontmatter(agentType, projectRoot) {
  try {
    // Search all agent categories
    for (const category of AGENT_CATEGORIES) {
      const agentPath = path.join(projectRoot, '.claude', 'agents', category, `${agentType}.md`);

      if (fs.existsSync(agentPath)) {
        const content = fs.readFileSync(agentPath, 'utf8');

        // Extract YAML frontmatter
        const frontmatterMatch = content.match(/^---\s*\n([\s\S]*?)\n---/);
        if (frontmatterMatch) {
          const frontmatter = frontmatterMatch[1];

          // Extract model field
          const modelMatch = frontmatter.match(/^model:\s*(\S+)/m);
          if (modelMatch) {
            return modelMatch[1];
          }
        }
      }
    }

    return null;
  } catch (_e) {
    return null;
  }
}

function normalizeModel(model) {
  // Handle null/undefined/empty
  if (!model || typeof model !== 'string' || model.trim() === '') {
    return MODEL_ALIASES['sonnet']; // Default to sonnet
  }

  const trimmed = model.trim();

  // If it's a shorthand, convert to full ID
  if (MODEL_ALIASES[trimmed] && !trimmed.startsWith('claude-')) {
    return MODEL_ALIASES[trimmed];
  }

  // If it's already a full ID or unknown, return as-is
  return trimmed;
}

function getShorthand(model) {
  if (!model) return 'sonnet';

  const trimmed = model.trim();

  // If it's a full ID, convert to shorthand
  if (trimmed.startsWith('claude-') && MODEL_ALIASES[trimmed]) {
    return MODEL_ALIASES[trimmed];
  }

  // If it's already a shorthand, return as-is
  if (['opus', 'sonnet', 'haiku'].includes(trimmed)) {
    return trimmed;
  }

  return 'sonnet'; // Default
}

function resolveAgentModel(agentType, projectRoot = process.cwd()) {
  // Validate input
  if (!agentType || typeof agentType !== 'string') {
    return {
      model: MODEL_ALIASES['sonnet'],
      shorthand: 'sonnet',
      source: 'complexity-default',
      raw: null,
    };
  }

  const normalizedAgent = agentType.trim().toLowerCase();

  // Step 1: Try config.yaml
  const configModel = getModelFromConfig(normalizedAgent, projectRoot);
  if (configModel) {
    return {
      model: normalizeModel(configModel),
      shorthand: getShorthand(configModel),
      source: 'config.yaml',
      raw: configModel,
    };
  }

  // Step 2: Try agent frontmatter
  const frontmatterModel = getModelFromFrontmatter(normalizedAgent, projectRoot);
  if (frontmatterModel) {
    return {
      model: normalizeModel(frontmatterModel),
      shorthand: getShorthand(frontmatterModel),
      source: 'frontmatter',
      raw: frontmatterModel,
    };
  }

  // Step 3: Use complexity-based default
  const complexityDefault = COMPLEXITY_DEFAULTS[normalizedAgent] || COMPLEXITY_DEFAULTS['default'];
  return {
    model: normalizeModel(complexityDefault),
    shorthand: complexityDefault,
    source: 'complexity-default',
    raw: null,
  };
}

function commandExists(cmd) {
  if (!/^[a-zA-Z0-9_.-]+$/.test(String(cmd))) {
    return false;
  }

  try {
    const isWindows = process.platform === 'win32';
    const result = spawnSync(isWindows ? 'where' : 'which', [cmd], { stdio: 'pipe' });
    return result.status === 0;
  } catch (_err) {
    return false;
  }
}

async function assess(projectPath) {
  const result = {
    type: 'greenfield',
    scores: {
      structure: 0,
      tests: 0,
      docs: 0,
      patterns: 0,
    },
    recommendations: [],
    suggested_workflows: [],
    suggested_agents: [],
  };

  if (!fs.existsSync(projectPath)) {
    return result;
  }

  // Score structure
  result.scores.structure = await scoreStructure(projectPath);

  // Score tests
  result.scores.tests = await scoreTests(projectPath);

  // Score documentation
  result.scores.docs = await scoreDocs(projectPath);

  // Score architecture patterns
  result.scores.patterns = await scorePatterns(projectPath);

  // Calculate overall maturity
  const avgScore =
    (result.scores.structure + result.scores.tests + result.scores.docs + result.scores.patterns) /
    4;

  // Classify project
  if (avgScore >= 0.8) {
    result.type = 'legacy';
  } else if (avgScore >= 0.3) {
    result.type = 'brownfield';
  } else {
    result.type = 'greenfield';
  }

  // Generate recommendations
  result.recommendations = generateRecommendations(result.scores);

  // Suggest workflows
  result.suggested_workflows = suggestWorkflows(result.type, result.scores);

  // Suggest agents based on tech stack
  result.suggested_agents = await suggestAgents(projectPath);

  return result;
}

async function scoreStructure(projectPath) {
  let score = 0;

  const expectedDirs = [
    'src',
    'lib',
    'tests',
    'test',
    '__tests__',
    'docs',
    'doc',
    'config',
    'scripts',
    'build',
    'dist',
  ];

  const files = fs.readdirSync(projectPath);
  const dirCount = expectedDirs.filter(dir => files.includes(dir)).length;

  // Base score on directory organization
  if (dirCount >= 5) {
    score = 0.9;
  } else if (dirCount >= 3) {
    score = 0.6;
  } else if (dirCount >= 1) {
    score = 0.3;
  } else {
    score = 0.1;
  }

  // Bonus for GitHub workflows (CI/CD maturity)
  const githubWorkflowsPath = path.join(projectPath, '.github/workflows');
  if (fs.existsSync(githubWorkflowsPath)) {
    score = Math.min(score + 0.1, 1.0);
  }

  return score;
}

async function scoreTests(projectPath) {
  let score = 0;

  const testDirs = ['tests', 'test', '__tests__', 'spec'];
  let testFileCount = 0;

  for (const testDir of testDirs) {
    const testPath = path.join(projectPath, testDir);
    if (fs.existsSync(testPath)) {
      testFileCount += countFilesRecursive(testPath, /\.(test|spec)\.(js|ts|jsx|tsx|py)$/);
    }
  }

  // Score based on test file count
  if (testFileCount >= 20) {
    score = 0.9;
  } else if (testFileCount >= 10) {
    score = 0.7;
  } else if (testFileCount >= 5) {
    score = 0.5;
  } else if (testFileCount >= 1) {
    score = 0.3;
  } else {
    score = 0;
  }

  return score;
}

async function scoreDocs(projectPath) {
  let score = 0;

  const docFiles = [
    'README.md',
    'CONTRIBUTING.md',
    'CHANGELOG.md',
    'LICENSE',
    'CODE_OF_CONDUCT.md',
    'SECURITY.md',
  ];

  const files = fs.readdirSync(projectPath);
  const docCount = docFiles.filter(doc => files.includes(doc)).length;

  // Check README quality
  const readmePath = path.join(projectPath, 'README.md');
  if (fs.existsSync(readmePath)) {
    const readmeContent = fs.readFileSync(readmePath, 'utf8');
    const hasInstallation = readmeContent.toLowerCase().includes('install');
    const hasUsage = readmeContent.toLowerCase().includes('usage');
    const hasAPI = readmeContent.toLowerCase().includes('api');

    if (hasInstallation && hasUsage && hasAPI) {
      score += 0.3;
    } else if (hasInstallation || hasUsage) {
      score += 0.2;
    }
  }

  // Score based on doc file count
  if (docCount >= 4) {
    score += 0.6;
  } else if (docCount >= 2) {
    score += 0.4;
  } else if (docCount >= 1) {
    score += 0.2;
  }

  return Math.min(score, 1.0);
}

async function scorePatterns(projectPath) {
  let score = 0;

  const configFiles = [
    'tsconfig.json',
    '.eslintrc.js',
    '.eslintrc.json',
    '.prettierrc',
    '.editorconfig',
    'jest.config.js',
    'webpack.config.js',
    'vite.config.js',
    'rollup.config.js',
  ];

  const files = fs.readdirSync(projectPath);
  const configCount = configFiles.filter(config => files.includes(config)).length;

  // Score based on config file count
  if (configCount >= 5) {
    score = 0.9;
  } else if (configCount >= 3) {
    score = 0.6;
  } else if (configCount >= 1) {
    score = 0.3;
  } else {
    score = 0.1;
  }

  return score;
}

function generateRecommendations(scores) {
  const recommendations = [];

  if (scores.tests < 0.5) {
    recommendations.push('Increase test coverage to 80%+');
    recommendations.push('Add unit tests for core functionality');
  }

  if (scores.docs < 0.5) {
    recommendations.push('Add comprehensive README with installation and usage');
    recommendations.push('Create API documentation');
    recommendations.push('Add CONTRIBUTING.md for contributors');
  }

  if (scores.structure < 0.5) {
    recommendations.push('Organize code into src/ and tests/ directories');
    recommendations.push('Separate concerns (components, utils, services)');
  }

  if (scores.patterns < 0.5) {
    recommendations.push('Add linting configuration (.eslintrc)');
    recommendations.push('Add code formatting (.prettierrc)');
    recommendations.push('Consider adding TypeScript for type safety');
  }

  return recommendations;
}

function suggestWorkflows(type, scores) {
  const workflows = [];

  // Always suggest project-onboarding for brownfield/legacy
  if (type === 'brownfield' || type === 'legacy') {
    workflows.push('project-onboarding');
  }

  // Suggest TDD if low test coverage
  if (scores.tests < 0.5) {
    workflows.push('tdd');
    workflows.push('qa-workflow');
  }

  // Suggest context-driven-development for brownfield/legacy
  if (type === 'brownfield' || type === 'legacy') {
    workflows.push('context-driven-development');
  }

  return workflows;
}

async function suggestAgents(projectPath) {
  const agents = [];

  // Read package.json for TypeScript
  const packageJsonPath = path.join(projectPath, 'package.json');
  if (fs.existsSync(packageJsonPath)) {
    try {
      const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
      const allDeps = { ...pkg.dependencies, ...pkg.devDependencies };

      if (allDeps['typescript']) {
        agents.push('typescript-pro');
      }

      if (allDeps['react']) {
        agents.push('frontend-pro');
      }

      if (allDeps['next']) {
        agents.push('nextjs-pro');
      }

      if (allDeps['vue']) {
        agents.push('frontend-pro');
      }

      if (allDeps['express'] || allDeps['fastify']) {
        agents.push('nodejs-pro');
      }
    } catch (_err) {
      // Invalid JSON
    }
  }

  // Check for Python
  if (
    fs.existsSync(path.join(projectPath, 'pyproject.toml')) ||
    fs.existsSync(path.join(projectPath, 'requirements.txt'))
  ) {
    agents.push('python-pro');
  }

  // Check for Go
  if (fs.existsSync(path.join(projectPath, 'go.mod'))) {
    agents.push('golang-pro');
  }

  // Always suggest QA for brownfield projects with low test coverage
  agents.push('qa');

  return agents;
}

function countFilesRecursive(dir, pattern) {
  let count = 0;

  if (!fs.existsSync(dir)) {
    return count;
  }

  const files = fs.readdirSync(dir);

  for (const file of files) {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    if (stat.isDirectory()) {
      count += countFilesRecursive(filePath, pattern);
    } else if (pattern.test(file)) {
      count++;
    }
  }

  return count;
}

function getProjectRoot() {
  // We're in .claude/lib/utils, so walk up 3 levels to get to project root
  // __dirname = PROJECT_ROOT/.claude/lib/utils
  // path.dirname(__dirname) = PROJECT_ROOT/.claude/lib
  // path.dirname(path.dirname(__dirname)) = PROJECT_ROOT/.claude
  // path.dirname(path.dirname(path.dirname(__dirname))) = PROJECT_ROOT

  const projectRoot = path.dirname(path.dirname(path.dirname(__dirname)));

  // Verify .claude directory exists
  const claudeDir = path.join(projectRoot, '.claude');
  if (!fs.existsSync(claudeDir)) {
    throw new Error(`Could not find .claude directory in ${projectRoot}`);
  }

  return projectRoot;
}

function loadConfig(useCache = true) {
  if (useCache && cachedConfig) {
    return cachedConfig;
  }

  const env = getEnvironment();
  const projectRoot = getProjectRoot();

  // Determine config file path
  let configFile;
  let configPath;

  if (env === 'staging') {
    configFile = 'config.staging.yaml';
    configPath = path.join(projectRoot, '.claude', configFile);

    // Fall back to default if staging config doesn't exist
    if (!fs.existsSync(configPath)) {
      console.warn(
        `[config-loader] Staging config not found at ${configPath}, using default config.yaml`
      );
      configFile = 'config.yaml';
      configPath = path.join(projectRoot, '.claude', configFile);
    }
  } else {
    // Development and production use default config.yaml
    configFile = 'config.yaml';
    configPath = path.join(projectRoot, '.claude', configFile);
  }

  // Load and parse config
  try {
    const configContent = fs.readFileSync(configPath, 'utf8');
    const config = yaml.load(configContent);

    // Add metadata
    config._meta = {
      environment: env,
      configFile: configFile,
      configPath: configPath,
      loadedAt: new Date().toISOString(),
    };

    cachedConfig = config;
    return config;
  } catch (error) {
    throw new Error(`Failed to load config from ${configPath}: ${error.message}`);
  }
}

function clearCache() {
  cachedConfig = null;
}

function getEnvironmentPath(relativePath) {
  const env = getEnvironment();
  const projectRoot = getProjectRoot();

  if (env === 'staging') {
    // Staging: .claude/staging/<relativePath>
    return path.join(projectRoot, '.claude', 'staging', relativePath);
  }

  // Development/Production: .claude/<relativePath>
  return path.join(projectRoot, '.claude', relativePath);
}

function checkCompressionNeeded(context) {
  const {
    tokenBudgetStatus = { percentUsed: 0, status: 'OK' },
    lastReadSize = 0,
    lastFetchSize = 0,
    operationCount = 0,
    largeOperationPattern = false,
  } = context;

  // Trigger 1: Budget threshold (CRITICAL)
  if (tokenBudgetStatus.percentUsed >= 90) {
    return {
      needed: true,
      reason: `Budget > 90% (${tokenBudgetStatus.percentUsed.toFixed(1)}%)`,
      urgency: 'high',
    };
  }

  // Trigger 2: Single large Read
  if (lastReadSize >= READ_SIZE_THRESHOLD) {
    const sizeKB = Math.floor(lastReadSize / 1000);
    return {
      needed: true,
      reason: `Read > 10KB (${sizeKB}KB)`,
      urgency: 'medium',
    };
  }

  // Trigger 3: Single large Fetch
  if (lastFetchSize >= FETCH_SIZE_THRESHOLD) {
    const sizeKB = Math.floor(lastFetchSize / 1000);
    return {
      needed: true,
      reason: `Fetch > 5KB (${sizeKB}KB)`,
      urgency: 'medium',
    };
  }

  // Update operation counter (passed from context or internal)
  operationCounter = operationCount;

  // Trigger 4: Periodic (every 10 operations)
  if (operationCounter >= PERIODIC_INTERVAL) {
    return {
      needed: true,
      reason: `Periodic compression (${operationCounter} ops)`,
      urgency: 'low',
    };
  }

  // Trigger 5: Urgent pattern (3+ large ops in last 5)
  if (largeOperationPattern) {
    return {
      needed: true,
      reason: '3+ large operations detected',
      urgency: 'high',
    };
  }

  return {
    needed: false,
    reason: 'No compression triggers met',
    urgency: 'low',
  };
}

async function triggerCompression(options) {
  const { reason, urgency, _simulateFailure = false } = options;

  try {
    // Simulate failure if test flag is set
    if (_simulateFailure) {
      throw new Error('Simulated compression failure');
    }

    // In Phase 2, we don't actually invoke the skill
    // We just simulate success and log the event
    const bytesFreed = Math.floor(Math.random() * 50000) + 10000; // Simulate 10-60 KB freed

    // Log compression event
    const logEntry = {
      timestamp: new Date().toISOString(),
      reason,
      urgency,
      bytesFreed,
      success: true,
    };

    // Ensure directory exists
    const logDir = path.dirname(COMPRESSION_STATS_PATH);
    if (!fs.existsSync(logDir)) {
      fs.mkdirSync(logDir, { recursive: true });
    }

    // Append to JSONL file
    fs.appendFileSync(COMPRESSION_STATS_PATH, JSON.stringify(logEntry) + '\n', 'utf8');

    // Phase 3 (optional): write a reminder file for Router/agents to act on
    if (AUTO_COMPRESSION_PHASE_3) {
      try {
        if (!fs.existsSync(RUNTIME_DIR)) {
          fs.mkdirSync(RUNTIME_DIR, { recursive: true });
        }
        fs.writeFileSync(COMPRESSION_REMINDER_PATH, 'compression_needed\n', 'utf8');
        fs.writeFileSync(
          COMPRESSION_REMINDER_JSON_PATH,
          JSON.stringify(
            {
              reason,
              urgency,
              timestamp: new Date().toISOString(),
            },
            null,
            2
          ),
          'utf8'
        );
      } catch (_err) {
        // Best-effort; reminder is advisory only
      }
    }

    return {
      success: true,
      message: `Compression triggered: ${reason} (${bytesFreed} bytes freed)`,
      bytesFreed,
    };
  } catch (error) {
    // Error handling - don't retry in Phase 2
    return {
      success: false,
      message: `Compression failed: ${error.message}`,
      bytesFreed: 0,
    };
  }
}

function getCompressionStats() {
  // Check if stats file exists
  if (!fs.existsSync(COMPRESSION_STATS_PATH)) {
    return {
      totalCompressions: 0,
      totalBytesSaved: 0,
      averageReduction: '0%',
      lastCompressionTime: 'Never',
    };
  }

  try {
    // Read JSONL file
    const logContent = fs.readFileSync(COMPRESSION_STATS_PATH, 'utf8');
    const lines = logContent
      .trim()
      .split('\n')
      .filter(line => line.length > 0);

    if (lines.length === 0) {
      return {
        totalCompressions: 0,
        totalBytesSaved: 0,
        averageReduction: '0%',
        lastCompressionTime: 'Never',
      };
    }

    // Parse entries
    const entries = lines
      .map(line => {
        try {
          return JSON.parse(line);
        } catch (_e) {
          return null;
        }
      })
      .filter(entry => entry !== null && entry.success);

    const totalCompressions = entries.length;
    const totalBytesSaved = entries.reduce((sum, entry) => sum + (entry.bytesFreed || 0), 0);
    const averageReduction =
      totalCompressions > 0
        ? Math.floor((totalBytesSaved / totalCompressions / 1000) * 100) / 100 + '%'
        : '0%';
    const lastEntry = entries[entries.length - 1];
    const lastCompressionTime = lastEntry ? lastEntry.timestamp : 'Never';

    return {
      totalCompressions,
      totalBytesSaved,
      averageReduction,
      lastCompressionTime,
    };
  } catch (_error) {
    // Return zeros on error
    return {
      totalCompressions: 0,
      totalBytesSaved: 0,
      averageReduction: '0%',
      lastCompressionTime: 'Never',
    };
  }
}

function resetCompressionCounters() {
  operationCounter = 0;
}

function getProjectRoot() {
  return process.env.PROJECT_ROOT || process.cwd();
}

function escapeCSV(value) {
  if (typeof value !== 'string') {
    return value;
  }

  // Formula characters that trigger Excel/Sheets execution
  const dangerousStarts = ['=', '+', '-', '@', '\t', '\r', '\n'];

  for (const char of dangerousStarts) {
    if (value.startsWith(char)) {
      // Prefix with single quote to prevent formula execution
      return "'" + value;
    }
  }

  // Handle commas and quotes in CSV
  if (value.includes(',') || value.includes('"') || value.includes('\n')) {
    return `"${value.replace(/"/g, '""')}"`;
  }

  return value;
}

function parseFrontmatter(content) {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) {
    return {};
  }

  const yaml = match[1];
  const result = {};

  // Simple YAML parser (handles basic key: value and key: [array])
  const lines = yaml.split('\n');
  for (const line of lines) {
    const keyValue = line.match(/^([^:]+):\s*(.+)$/);
    if (keyValue) {
      const key = keyValue[1].trim();
      let value = keyValue[2].trim();

      // Handle arrays [item1, item2]
      if (value.startsWith('[') && value.endsWith(']')) {
        value = value
          .slice(1, -1)
          .split(',')
          .map(v => v.trim());
      }

      result[key] = value;
    }
  }

  return result;
}

function extractUseCases(description) {
  const useCases = [];

  // Common use case keywords
  const keywords = [
    'testing',
    'quality',
    'development',
    'security',
    'planning',
    'review',
    'documentation',
    'deployment',
    'monitoring',
    'debugging',
    'refactoring',
    'architecture',
    'design',
    'performance',
    'optimization',
  ];

  const lowerDesc = description.toLowerCase();
  for (const keyword of keywords) {
    if (lowerDesc.includes(keyword)) {
      useCases.push(keyword);
    }
  }

  return useCases.slice(0, 5); // Limit to 5 use cases
}

function inferComplexity(content, frontmatter) {
  if (frontmatter.complexity) {
    return frontmatter.complexity.toUpperCase();
  }

  // Infer from content length and structure
  const lines = content.split('\n').length;
  const headings = (content.match(/^#+\s/gm) || []).length;

  if (lines < 100 || headings < 5) {
    return 'LOW';
  } else if (lines < 300 || headings < 15) {
    return 'MEDIUM';
  } else if (lines < 1000) {
    return 'HIGH';
  } else {
    return 'EPIC';
  }
}

function scanDirectory(dir, domain) {
  const artifacts = [];
  const projectRoot = getProjectRoot();

  if (!fs.existsSync(dir)) {
    return artifacts;
  }

  function scanRecursive(currentDir) {
    const entries = fs.readdirSync(currentDir);

    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory()) {
        scanRecursive(fullPath);
      } else if (entry === 'SKILL.md' || entry.endsWith('.md')) {
        try {
          const content = fs.readFileSync(fullPath, 'utf-8');
          const frontmatter = parseFrontmatter(content);

          // Extract name from frontmatter or directory name
          const name = frontmatter.name || path.basename(path.dirname(fullPath));

          // Get relative path from project root
          const relativePath = path.relative(projectRoot, fullPath).replace(/\\/g, '/');

          // Extract description
          const description =
            frontmatter.description ||
            content
              .split('\n')
              .find(line => line.trim() && !line.startsWith('#') && !line.startsWith('---'))
              ?.trim() ||
            'No description available';

          // Extract metadata
          const tools = Array.isArray(frontmatter.tools) ? frontmatter.tools : [];
          const deprecated = frontmatter.deprecated === true || frontmatter.deprecated === 'true';
          const alias = frontmatter.alias || frontmatter.superseded_by || '';
          const useCases = frontmatter.use_cases || extractUseCases(description);
          const complexity = inferComplexity(content, frontmatter);

          artifacts.push({
            name: escapeCSV(name),
            path: escapeCSV(relativePath),
            description: escapeCSV(description.substring(0, 200)),
            domain,
            complexity,
            use_cases: escapeCSV(Array.isArray(useCases) ? useCases.join(',') : useCases),
            tools: escapeCSV(tools.join(',')),
            deprecated: deprecated ? 'true' : 'false',
            alias: escapeCSV(alias),
            usage_count: '0',
            last_used: '',
          });
        } catch (error) {
          console.warn(`[kb-index] Skipping ${fullPath}: ${error.message}`);
        }
      }
    }
  }

  scanRecursive(dir);
  return artifacts;
}

function buildKnowledgeBaseIndex() {
  const projectRoot = getProjectRoot();
  const outputPath = path.join(
    projectRoot,
    '.claude',
    'context',
    'artifacts',
    'knowledge-base-index.csv'
  );
  const tmpPath = outputPath + '.tmp';

  // Ensure output directory exists
  const outputDir = path.dirname(outputPath);
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Scan directories
  const skills = scanDirectory(path.join(projectRoot, '.claude', 'skills'), 'skill');
  const agents = scanDirectory(path.join(projectRoot, '.claude', 'agents'), 'agent');
  const workflows = scanDirectory(path.join(projectRoot, '.claude', 'workflows'), 'workflow');

  const allArtifacts = [...skills, ...agents, ...workflows];

  // Generate CSV content
  const headers = [
    'name',
    'path',
    'description',
    'domain',
    'complexity',
    'use_cases',
    'tools',
    'deprecated',
    'alias',
    'usage_count',
    'last_used',
  ];
  const csvLines = [headers.join(',')];

  for (const artifact of allArtifacts) {
    const row = headers.map(header => artifact[header] || '');
    csvLines.push(row.join(','));
  }

  const csvContent = csvLines.join('\n') + '\n';

  // Atomic write: write to .tmp then rename
  fs.writeFileSync(tmpPath, csvContent, 'utf-8');
  fs.renameSync(tmpPath, outputPath);

  console.log(`[kb-index] Knowledge base index built: ${allArtifacts.length} artifacts indexed`);

  return {
    success: true,
    artifactsIndexed: allArtifacts.length,
    outputPath,
  };
}

function maskString(text) {
  if (typeof text !== 'string') {
    return text;
  }

  let masked = text;

  for (const { pattern, replacement } of MASKING_PATTERNS) {
    masked = masked.replace(pattern, replacement);
  }

  return masked;
}

function sanitizeForLogging(obj, depth = 0) {
  // Prevent infinite recursion
  if (depth > 10) {
    return '[NESTED_OBJECT_TRUNCATED]';
  }

  // Handle null and undefined
  if (obj === null || obj === undefined) {
    return obj;
  }

  // Handle primitives
  if (typeof obj === 'string') {
    return maskString(obj);
  }

  if (typeof obj !== 'object') {
    return obj;
  }

  // Handle arrays
  if (Array.isArray(obj)) {
    return obj.map(item => sanitizeForLogging(item, depth + 1));
  }

  // Handle objects
  const sanitized = {};

  for (const [key, value] of Object.entries(obj)) {
    // Check if field is forbidden
    if (isForbidden(key)) {
      sanitized[key] = '[REDACTED]';
      continue;
    }

    // Recursively sanitize values
    if (typeof value === 'string') {
      sanitized[key] = maskString(value);
    } else if (value === null || value === undefined) {
      sanitized[key] = value;
    } else if (Array.isArray(value)) {
      sanitized[key] = value.map(item => sanitizeForLogging(item, depth + 1));
    } else if (typeof value === 'object') {
      sanitized[key] = sanitizeForLogging(value, depth + 1);
    } else {
      sanitized[key] = value;
    }
  }

  return sanitized;
}

function maskEmail(email) {
  if (typeof email !== 'string') {
    return email;
  }

  const emailRegex = /^([^@]+)@([^.]+)\.(.+)$/;
  const match = email.match(emailRegex);

  if (!match) {
    return email;
  }

  const [, local, domain, tld] = match;

  // Mask local part (keep first char)
  const maskedLocal = local.length > 1 ? local[0] + '***' : local + '***';

  // Mask domain (keep first char)
  const maskedDomain = domain.length > 1 ? domain[0] + '***' : domain + '***';

  return `${maskedLocal}@${maskedDomain}.${tld}`;
}

function maskPath(filePath) {
  if (typeof filePath !== 'string') {
    return filePath;
  }

  let masked = filePath;

  // Get PROJECT_ROOT
  const projectRoot = process.cwd();

  // Replace PROJECT_ROOT with relative path
  if (masked.startsWith(projectRoot)) {
    masked = masked.slice(projectRoot.length);
    if (masked.startsWith(path.sep)) {
      masked = masked.slice(1);
    }
    if (!masked.startsWith('.')) {
      masked = './' + masked.replace(/\\/g, '/');
    }
  }

  // Mask home directory (Unix)
  const homeDir = process.env.HOME || process.env.USERPROFILE || '';
  if (homeDir && masked.includes(homeDir)) {
    masked = masked.replace(homeDir, '[HOME]');
  }

  // Mask username in paths (Unix: /home/username, /Users/username)
  const unixUserMatch = masked.match(/\/(home|Users)\/([^/]+)/);
  if (unixUserMatch) {
    masked = masked.replace(
      `/${unixUserMatch[1]}/${unixUserMatch[2]}`,
      `/${unixUserMatch[1]}/[USER]`
    );
  }

  // Mask username in paths (Windows: C:\Users\username)
  const windowsUserMatch = masked.match(/[A-Z]:\\Users\\([^\\]+)/i);
  if (windowsUserMatch) {
    masked = masked.replace(/([A-Z]:\\Users\\)[^\\]+/i, '$1[USER]');
  }

  return masked;
}

function maskStackTrace(stack) {
  if (typeof stack !== 'string') {
    return [];
  }

  const lines = stack.split('\n');
  const frames = [];

  for (const line of lines) {
    // Skip the error message line (first line usually)
    if (!line.trim().startsWith('at ')) {
      continue;
    }

    // Extract and clean frame
    let frame = line.trim();

    // Remove function arguments (content in parentheses before file path)
    // Pattern: "at functionName(arg1, arg2) (/path/file.js:10:5)"
    // Should become: "at functionName (/path/file.js:10:5)"
    frame = frame.replace(/\([^)]*\)\s*\(/, ' (');

    // Mask file paths in the frame
    frame = maskPath(frame);

    // Mask any sensitive data that might be in the frame
    frame = maskString(frame);

    frames.push(frame);

    // Limit to 3 frames
    if (frames.length >= 3) {
      break;
    }
  }

  return frames;
}

function isForbidden(fieldName) {
  if (typeof fieldName !== 'string') {
    return false;
  }

  return FORBIDDEN_FIELD_PATTERNS.some(pattern => pattern.test(fieldName));
}

function getSensitivity(fieldName) {
  if (typeof fieldName !== 'string') {
    return 'public';
  }

  if (FORBIDDEN_FIELD_PATTERNS.some(pattern => pattern.test(fieldName))) {
    return 'forbidden';
  }

  if (SENSITIVE_FIELD_PATTERNS.some(pattern => pattern.test(fieldName))) {
    return 'sensitive';
  }

  if (INTERNAL_FIELD_PATTERNS.some(pattern => pattern.test(fieldName))) {
    return 'internal';
  }

  return 'public';
}

function getEnvironment() {
  const agentEnv = process.env.AGENT_STUDIO_ENV;
  const nodeEnv = process.env.NODE_ENV;

  // Priority: AGENT_STUDIO_ENV > NODE_ENV > default
  if (agentEnv) {
    const normalized = agentEnv.toLowerCase();
    if (['development', 'staging', 'production'].includes(normalized)) {
      return normalized;
    }
    console.warn(`[environment] Invalid AGENT_STUDIO_ENV="${agentEnv}", defaulting to development`);
  }

  if (nodeEnv) {
    return nodeEnv === 'production' ? 'production' : 'development';
  }

  return 'development'; // Default
}

function isStaging() {
  return getEnvironment() === 'staging';
}

function isProduction() {
  return getEnvironment() === 'production';
}

function isDevelopment() {
  return getEnvironment() === 'development';
}

function getThreshold(metric, productionValue) {
  const env = getEnvironment();

  // Staging: 2x more lenient than production
  if (env === 'staging') {
    return productionValue * 2;
  }

  // Development: No thresholds enforced
  if (env === 'development') {
    return Infinity;
  }

  // Production: Use strict threshold
  return productionValue;
}

function ensureDirForFile(filePath) {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function trimJsonlFile(filePath, maxLines) {
  if (!maxLines || !Number.isFinite(maxLines) || maxLines <= 0) return;
  if (!fs.existsSync(filePath)) return;

  const content = fs.readFileSync(filePath, 'utf8');
  const lines = content.split('\n').filter(Boolean);
  if (lines.length <= maxLines) return;

  const trimmed = lines.slice(-maxLines).join('\n') + '\n';
  fs.writeFileSync(filePath, trimmed, 'utf8');
}

function normalizeScope(scope) {
  const normalized = String(scope || '')
    .trim()
    .toLowerCase();
  return SCOPES.has(normalized) ? normalized : 'soft';
}

function removeTarget(target, dryRun) {
  const targetPath = target.path;
  if (!fs.existsSync(targetPath)) return false;
  if (dryRun) return true;
  if (target.type === 'dir') {
    fs.rmSync(targetPath, { recursive: true, force: true });
  } else {
    fs.rmSync(targetPath, { force: true });
  }
  return true;
}

function calculateCost(model, inputTokens, outputTokens) {
  // Validate inputs
  if (!model || typeof model !== 'string') {
    throw new Error('Model must be a non-empty string');
  }

  if (typeof inputTokens !== 'number' || inputTokens < 0) {
    throw new Error('inputTokens must be a non-negative number');
  }

  if (typeof outputTokens !== 'number' || outputTokens < 0) {
    throw new Error('outputTokens must be a non-negative number');
  }

  // Get pricing for model (default to sonnet if not found)
  const pricing = PRICING[model] || PRICING['sonnet'];

  // Calculate costs
  const inputCost = (inputTokens / 1000) * pricing.input;
  const outputCost = (outputTokens / 1000) * pricing.output;

  return inputCost + outputCost;
}

function getPricing(model) {
  return PRICING[model] || PRICING['sonnet'];
}

function modelToTier(model) {
  if (!model) return 'sonnet';
  const m = model.toLowerCase();
  if (m.includes('haiku')) return 'haiku';
  if (m.includes('opus')) return 'opus';
  return 'sonnet';
}

function getAvailableModels() {
  return Object.keys(PRICING);
}

function formatCost(cost) {
  return `$${cost.toFixed(4)}`;
}

function formatTokens(tokens) {
  return tokens.toLocaleString();
}

function aggregateCosts(calls) {
  const breakdown = {
    haiku: { cost: 0, calls: 0, tokens: 0 },
    sonnet: { cost: 0, calls: 0, tokens: 0 },
    opus: { cost: 0, calls: 0, tokens: 0 },
    total: { cost: 0, calls: 0, tokens: 0 },
  };

  for (const call of calls) {
    const tier = modelToTier(call.model);
    const cost = calculateCost(call.model, call.inputTokens, call.outputTokens);
    const tokens = call.inputTokens + call.outputTokens;

    breakdown[tier].cost += cost;
    breakdown[tier].calls += 1;
    breakdown[tier].tokens += tokens;

    breakdown.total.cost += cost;
    breakdown.total.calls += 1;
    breakdown.total.tokens += tokens;
  }

  return breakdown;
}

class ContextAccumulator {
  constructor() {
    this.answers = [];
  }

  /**
   * Add answer with metadata
   * @param {string} question
   * @param {string} answer
   * @param {Object} metadata
   */
  addAnswer(question, answer, metadata = {}) {
    const relevance = this._calculateRelevance(answer);
    const quality = this._calculateQuality(answer);

    this.answers.push({
      question,
      answer,
      timestamp: new Date().toISOString(),
      relevance,
      quality,
      ...metadata,
    });
  }

  /**
   * Get accumulated context
   * @returns {Object} - { answers, completeness }
   */
  getContext() {
    const completeness = this._calculateCompleteness();
    return {
      answers: this.answers,
      completeness,
    };
  }

  /**
   * Detect conflicts in answers
   * @returns {Array<string>} - Array of conflict descriptions
   */
  detectConflicts() {
    const conflicts = [];

    // Group answers by topic
    const topics = {};
    this.answers.forEach(a => {
      const topicWords = this._extractTopics(a.question);
      topicWords.forEach(topic => {
        if (!topics[topic]) topics[topic] = [];
        topics[topic].push(a);
      });
    });

    // Check for conflicting answers on same topic
    Object.keys(topics).forEach(topic => {
      const topicAnswers = topics[topic];
      if (topicAnswers.length > 1) {
        const uniqueAnswers = new Set(topicAnswers.map(a => a.answer.toLowerCase()));
        if (uniqueAnswers.size > 1) {
          conflicts.push(
            `Conflicting answers about ${topic}: ${Array.from(uniqueAnswers).join(' vs ')}`
          );
        }
      }
    });

    return conflicts;
  }

  /**
   * Suggest skipping a question if context already answers it
   * @param {string} question
   * @param {Object} context
   * @returns {boolean}
   */
  suggestSkip(question, _context) {
    const questionTopics = this._extractTopics(question);
    const answeredTopics = this.answers.map(a => this._extractTopics(a.question)).flat();

    // Skip if question topics already answered
    return questionTopics.some(qt => answeredTopics.some(at => at.includes(qt) || qt.includes(at)));
  }

  /**
   * Build human-readable summary
   * @returns {string}
   */
  buildSummary() {
    if (this.answers.length === 0) return 'No answers collected yet.';

    const lines = this.answers.map(a => {
      return `- ${a.question} → ${a.answer}`;
    });

    return lines.join('\n');
  }

  /**
   * Calculate relevance score (0-1)
   */
  _calculateRelevance(answer) {
    // More detailed answers have higher relevance
    const length = answer.length;
    if (length < 10) return 0.3;
    if (length < 30) return 0.5;
    if (length < 60) return 0.7;
    return 0.9;
  }

  /**
   * Calculate quality score (0-1)
   */
  _calculateQuality(answer) {
    if (!answer || answer.trim().length === 0) return 0;

    // Quality based on length and detail
    const length = answer.length;
    if (length < 10) return 0.3;
    if (length < 30) return 0.5;
    if (length < 60) return 0.7;
    return 0.9;
  }

  /**
   * Calculate completeness (0-1)
   */
  _calculateCompleteness() {
    const count = this.answers.length;
    if (count === 0) return 0;
    if (count < 3) return 0.3;
    if (count < 5) return 0.6;
    if (count < 7) return 0.8;
    return 1.0;
  }

  /**
   * Extract topics from question
   */
  _extractTopics(question) {
    const keywords = [
      'auth',
      'authentication',
      'token',
      'password',
      'database',
      'db',
      'api',
      'endpoint',
      'cache',
      'performance',
      'test',
      'security',
      'encrypt',
      'role',
      'permission',
      'migration',
      'schema',
      'index',
      'backup',
      'rate',
      'limit',
      'version',
      'mysql',
      'postgresql',
      'postgres',
    ];

    const words = question.toLowerCase().split(/\s+/);
    const matches = words.filter(w => keywords.includes(w) || keywords.some(k => w.includes(k)));

    // Also extract from question text (e.g., "Database?" -> ["database"])
    const questionWords = question.toLowerCase().match(/\b(\w+)\b/g) || [];
    keywords.forEach(kw => {
      if (questionWords.some(qw => qw.includes(kw) || kw.includes(qw))) {
        matches.push(kw);
      }
    });

    return [...new Set(matches)]; // Deduplicate
  }

function sanitizeObject(parsed, filterByAllowedKeys = false) {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return null;
  }

  // Create clean object without prototype
  const clean = Object.create(null);

  for (const key of Object.keys(parsed)) {
    // Skip dangerous keys (SEC-007)
    if (DANGEROUS_KEYS.includes(key)) {
      continue;
    }

    // Skip unknown keys at top level when filtering is enabled
    if (filterByAllowedKeys && !ALLOWED_HOOK_INPUT_KEYS.includes(key)) {
      continue;
    }

    const value = parsed[key];

    // Deep copy nested objects (don't filter nested objects by allowed keys)
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      clean[key] = sanitizeObject(value, false) || {};
    } else if (Array.isArray(value)) {
      clean[key] = [...value];
    } else {
      clean[key] = value;
    }
  }

  return Object.assign({}, clean);
}

function parseHookInputSync() {
  if (!process.argv[2]) {
    return null;
  }

  try {
    const parsed = JSON.parse(process.argv[2]);
    return sanitizeObject(parsed);
  } catch (_e) {
    return null;
  }
}

const endListener = () => {
  if (!hasData || !input.trim()) {
    cleanup();
    resolveOnce(allowEmpty ? null : undefined);
    return;
  }

  try {
    const parsed = JSON.parse(input);
    cleanup();
    resolveOnce(sanitizeObject(parsed));
  } catch (_e) {
    // Invalid JSON
    cleanup();
    resolveOnce(allowEmpty ? null : undefined);
  }
};

const errorListener = () => {
  cleanup();
  resolveOnce(allowEmpty ? null : undefined);
};

const cleanup = () => {
  process.stdin.removeListener('data', dataListener);
  process.stdin.removeListener('end', endListener);
  process.stdin.removeListener('error', errorListener);
};

function validateHookInput(jsonString) {
  if (!jsonString || typeof jsonString !== 'string') {
    return null;
  }

  const trimmed = jsonString.trim();
  if (!trimmed) {
    return null;
  }

  try {
    const parsed = JSON.parse(trimmed);

    // Arrays are not valid hook input
    if (Array.isArray(parsed)) {
      return null;
    }

    // Filter by allowed keys at top level for security
    return sanitizeObject(parsed, true);
  } catch (_e) {
    return null;
  }
}

