  };

  if (!fs.existsSync(configDir)) {
    fs.mkdirSync(configDir, { recursive: true });
  }
  fs.writeFileSync(configPath, JSON.stringify(config, null, 2), 'utf8');
  return config;
}

function getSelectionPrompt() {
  const available = getAvailablePackageManagers();
  const current = getPackageManager();

  let message = '[PackageManager] Available package managers:\n';
  for (const pmName of available) {
    const indicator = pmName === current.name ? ' (current)' : '';
    message += `  - ${pmName}${indicator}\n`;
  }
  message += '\nTo set your preferred package manager:\n';
  message += '  - Global: Set CLAUDE_PACKAGE_MANAGER environment variable\n';
  message += '  - Or add to ~/.claude/package-manager.json: {"packageManager": "pnpm"}\n';
  message += '  - Or add to package.json: {"packageManager": "pnpm@8"}\n';
  return message;
}

function extractTaskId(note) {
  if (!note) return null;

  // Try JSON format first (git-notes-audit hook output)
  try {
    const parsed = JSON.parse(note);
    if (parsed.taskId) {
      return String(parsed.taskId).replace(/^#/, '');
    }
  } catch (_err) {
    // Not JSON, continue with regex
  }

  // Try regex patterns: TASK-#6, [TASK-#7], TASK-#8:
  const match = note.match(/TASK-#(\d+)/i);
  if (match) {
    return match[1];
  }

  return null;
}

async function getCommits(repoPath, range) {
  try {
    // Get commit hashes, messages, dates, and authors
    // Exclude notes refs to avoid including git notes metadata commits
    const log = execSync(
      `git log --format="%H|||%s|||%ai|||%an" ${range} --not --glob=refs/notes/*`,
      {
        cwd: repoPath,
        encoding: 'utf8',
      }
    ).trim();

    if (!log) return [];

    const commits = log.split('\n').map(line => {
      const [hash, message, date, author] = line.split('|||');
      return {
        hash,
        message,
        date,
        author,
        note: null,
        metadata: {},
        cherryPicked: message.includes('cherry picked from commit'),
      };
    });

    // Get git notes for each commit
    for (const commit of commits) {
      try {
        const note = execSync(`git notes show ${commit.hash}`, {
          cwd: repoPath,
          encoding: 'utf8',
        }).trim();
        commit.note = note;

        // Try to parse JSON metadata
        try {
          const parsed = JSON.parse(note);
          commit.metadata = parsed.metadata || {};
        } catch (_err) {
          // Not JSON, no metadata
        }
      } catch (_err) {
        // No note for this commit
      }
    }

    return commits;
  } catch (_err) {
    // Invalid range or no commits
    return [];
  }
}

async function groupByTask(repoPath, range) {
  const commits = await getCommits(repoPath, range);
  const groups = {};

  for (const commit of commits) {
    const taskId = extractTaskId(commit.note);

    const key = taskId || 'unknown';
    if (!groups[key]) {
      groups[key] = [];
    }

    groups[key].push(commit);
  }

  return groups;
}

async function revertTask(repoPath, taskId) {
  const commits = await getCommits(repoPath, '--all');
  const taskCommits = commits
    .filter(c => extractTaskId(c.note) === taskId)
    .sort((a, b) => new Date(b.date) - new Date(a.date)); // Newest first

  if (taskCommits.length === 0) {
    return {
      success: false,
      conflicts: false,
      message: `No commits found for Task #${taskId}`,
    };
  }

  try {
    for (const commit of taskCommits) {
      execSync(`git revert --no-edit ${commit.hash}`, { cwd: repoPath, stdio: 'pipe' });

      // Add git note to revert commit
      const latestHash = execSync('git rev-parse HEAD', { cwd: repoPath, encoding: 'utf8' }).trim();
      execSync(`git notes add -m "REVERTED-TASK-#${taskId}" ${latestHash}`, { cwd: repoPath });

      // Mark original commit as reverted
      const originalNote = commit.note || '';
      const updatedNote = `${originalNote}\n[REVERTED]`;
      execSync(`git notes add -f -m "${updatedNote}" ${commit.hash}`, { cwd: repoPath });
    }

    return {
      success: true,
      conflicts: false,
      message: `Successfully reverted ${taskCommits.length} commit(s) for Task #${taskId}`,
    };
  } catch (err) {
    // Check if it's a merge conflict
    if (err.message.includes('CONFLICT') || err.message.includes('conflict')) {
      return {
        success: false,
        conflicts: true,
        message: 'Revert failed: merge conflict detected. Resolve manually and continue.',
      };
    }

    return {
      success: false,
      conflicts: false,
      message: `Revert failed: ${err.message}`,
    };
  }
}

async function findTaskByName(repoPath, name) {
  const commits = await getCommits(repoPath, '--all');
  const matchingTasks = new Set();

  for (const commit of commits) {
    if (commit.note && commit.note.includes(name)) {
      const taskId = extractTaskId(commit.note);
      if (taskId && taskId !== 'unknown') {
        matchingTasks.add(taskId);
      }
    }
  }

  return Array.from(matchingTasks);
}

async function loadDomainPatterns(domain) {
  // Check cache first
  if (patternCache[domain]) {
    return patternCache[domain];
  }

  const learningsPath = path.join(PROJECT_ROOT, '.claude/context/memory/learnings.md');

  if (!fs.existsSync(learningsPath)) {
    patternCache[domain] = [];
    return [];
  }

  const content = fs.readFileSync(learningsPath, 'utf-8');

  // Extract patterns related to domain
  const patterns = [];
  const domainKeywords = {
    authentication: ['auth', 'jwt', 'bcrypt', 'oauth', 'token', 'password', 'login', 'session'],
    database: ['postgres', 'mysql', 'migration', 'schema', 'index', 'database', 'sql'],
    'api-design': ['rest', 'graphql', 'api', 'endpoint', 'route', 'versioning'],
    testing: ['tdd', 'jest', 'pytest', 'unittest', 'test', 'coverage', 'red-green-refactor'],
    performance: ['cache', 'cdn', 'performance', 'optimization', 'latency', 'throughput'],
    security: ['encrypt', 'owasp', 'vulnerability', 'security', 'threat', 'xss', 'sql injection'],
    architecture: ['adr', 'decision', 'architecture', 'pattern', 'design'],
  };

  const keywords = domainKeywords[domain] || [];
  const lines = content.split('\n');

  lines.forEach(line => {
    const lower = line.toLowerCase();
    if (keywords.some(kw => lower.includes(kw))) {
      patterns.push(line.trim());
    }
  });

  // Cache the result
  patternCache[domain] = patterns;

  return patterns;
}

async function suggestQuestionVariants(baseQuestion, domain) {
  const patterns = await loadDomainPatterns(domain);

  const variants = [
    baseQuestion,
    baseQuestion.replace('What ', 'Which '),
    baseQuestion.replace('?', ' do you prefer?'),
  ];

  // Add pattern-based variants
  if (domain === 'database' && patterns.some(p => p.toLowerCase().includes('migration'))) {
    variants.push('How will you handle database migrations?');
    variants.push('What database migration strategy?');
  }

  if (domain === 'authentication' && patterns.some(p => p.toLowerCase().includes('jwt'))) {
    variants.push('Will you use JWT tokens?');
  }

  return [...new Set(variants)]; // Deduplicate
}

async function findSimilarPastTasks(keywords) {
  const learningsPath = path.join(PROJECT_ROOT, '.claude/context/memory/learnings.md');

  if (!fs.existsSync(learningsPath)) {
    return [];
  }

  const content = fs.readFileSync(learningsPath, 'utf-8');
  const lines = content.split('\n');

  const similar = [];
  lines.forEach(line => {
    const lower = line.toLowerCase();
    const matchCount = keywords.filter(kw => lower.includes(kw.toLowerCase())).length;
    if (matchCount >= 2) {
      similar.push(line.trim());
    }
  });

  return similar;
}

async function scoreAnswerQuality(answer, domainPatterns) {
  if (!answer || answer.trim().length === 0) return 0;

  const answerLower = answer.toLowerCase();
  let score = 0;

  // Base score from length
  const length = answer.length;
  if (length < 10) score = 20;
  else if (length < 30) score = 40;
  else if (length < 60) score = 60;
  else score = 70;

  // Bonus for pattern matches
  const matches = domainPatterns.filter(pattern => {
    const keywords = pattern.toLowerCase().split(/\s+/);
    return keywords.some(kw => answerLower.includes(kw));
  });

  const bonus = Math.min(30, matches.length * 10);
  score += bonus;

  return Math.min(100, score);
}

function getConfigFromEnv() {
  return {
    warningThreshold:
      parseFloat(process.env.HEAP_WARNING_THRESHOLD || DEFAULTS.warningThreshold * 100) / 100,
    criticalThreshold:
      parseFloat(process.env.HEAP_CRITICAL_THRESHOLD || DEFAULTS.criticalThreshold * 100) / 100,
    shutdownThreshold:
      parseFloat(process.env.HEAP_SHUTDOWN_THRESHOLD || DEFAULTS.shutdownThreshold * 100) / 100,
    interval: parseInt(process.env.MEMORY_MONITOR_INTERVAL_MS || DEFAULTS.interval, 10),
    maxHistorySize: parseInt(process.env.MEMORY_HISTORY_SIZE || DEFAULTS.maxHistorySize, 10),
  };
}

 * MemoryMonitor class for heap usage monitoring
 *
 * @class MemoryMonitor
 * @example
 * const monitor = new MemoryMonitor();
 * monitor.on('warning', (data) => console.warn('Memory warning:', data));
 * monitor.start();
 */
class MemoryMonitor {
  /**
   * Create a MemoryMonitor instance
   *
   * @param {Object} config - Configuration options
   * @param {number} [config.warningThreshold=0.70] - Warning threshold (0-1)
   * @param {number} [config.criticalThreshold=0.85] - Critical threshold (0-1)
   * @param {number} [config.shutdownThreshold=0.95] - Shutdown threshold (0-1)
   * @param {number} [config.interval=5000] - Check interval in ms
   * @param {number} [config.maxHistorySize=100] - Max history entries to retain
   */
  constructor(config = {}) {
    const envConfig = getConfigFromEnv();

    this.warningThreshold = config.warningThreshold ?? envConfig.warningThreshold;
    this.criticalThreshold = config.criticalThreshold ?? envConfig.criticalThreshold;
    this.shutdownThreshold = config.shutdownThreshold ?? envConfig.shutdownThreshold;
    this.interval = config.interval ?? envConfig.interval;
    this.maxHistorySize = config.maxHistorySize ?? envConfig.maxHistorySize;

    // Internal state
    this.listeners = [];
    this.memoryHistory = [];
    this.monitor = null;
    this.isRunning = false;
    this.lastLevel = null;

    // Validate thresholds
    this._validateThresholds();
  }

  /**
   * Validate threshold configuration
   * @private
   */
  _validateThresholds() {
    if (this.warningThreshold >= this.criticalThreshold) {
      throw new Error('warningThreshold must be less than criticalThreshold');
    }
    if (this.criticalThreshold >= this.shutdownThreshold) {
      throw new Error('criticalThreshold must be less than shutdownThreshold');
    }
    if (this.warningThreshold < 0 || this.shutdownThreshold > 1) {
      throw new Error('Thresholds must be between 0 and 1');
    }
  }

  /**
   * Start the memory monitor
   * @returns {MemoryMonitor} this (for chaining)
   */
  start() {
    if (this.isRunning) {
      return this;
    }

    this.isRunning = true;
    this.monitor = setInterval(() => this.checkHeap(), this.interval);

    // Run an immediate check
    this.checkHeap();

    return this;
  }

  /**
   * Stop the memory monitor
   * @returns {MemoryMonitor} this (for chaining)
   */
  stop() {
    if (this.monitor) {
      clearInterval(this.monitor);
      this.monitor = null;
    }
    this.isRunning = false;
    return this;
  }

  /**
   * Check current heap usage and emit events if thresholds crossed
   * @returns {Object} Current memory entry
   */
  checkHeap() {
    const mem = process.memoryUsage();

    // Calculate heap percentage
    // Note: heapTotal is the current allocated heap, not the max
    // For max heap, we need to use v8.getHeapStatistics() which provides heap_size_limit
    let heapLimit;
    try {
      const v8 = require('v8');
      const heapStats = v8.getHeapStatistics();
      heapLimit = heapStats.heap_size_limit;
    } catch (_err) {
      // Fallback: estimate based on heapTotal with a safety margin
      // This is less accurate but works in environments without v8 module
      heapLimit = mem.heapTotal * 2;
    }

    const heapPercent = mem.heapUsed / heapLimit;

    const entry = {
      timestamp: Date.now(),
      heapUsed: mem.heapUsed,
      heapTotal: mem.heapTotal,
      heapLimit: heapLimit,
      heapPercent: heapPercent,
      external: mem.external,
      rss: mem.rss,
    };

    // Add to history with bounded size
    this.memoryHistory.push(entry);
    if (this.memoryHistory.length > this.maxHistorySize) {
      this.memoryHistory.shift();
    }

    // Always emit check event
    this.emit('check', entry);

    // Determine threshold level and emit appropriate event
    let level = null;
    if (heapPercent >= this.shutdownThreshold) {
      level = 'SHUTDOWN';
      this.emit('critical', {
        level: 'SHUTDOWN',
        percent: heapPercent,
        heapUsedMB: mem.heapUsed / 1024 / 1024,
        heapLimitMB: heapLimit / 1024 / 1024,
        message: `Heap usage at ${(heapPercent * 100).toFixed(1)}% - SHUTDOWN threshold exceeded`,
        entry,
      });
    } else if (heapPercent >= this.criticalThreshold) {
      level = 'CRITICAL';
      this.emit('critical', {
        level: 'CRITICAL',
        percent: heapPercent,
        heapUsedMB: mem.heapUsed / 1024 / 1024,
        heapLimitMB: heapLimit / 1024 / 1024,
        message: `Heap usage at ${(heapPercent * 100).toFixed(1)}% - CRITICAL threshold exceeded`,
        entry,
      });
    } else if (heapPercent >= this.warningThreshold) {
      level = 'WARNING';
      this.emit('warning', {
        level: 'WARNING',
        percent: heapPercent,
        heapUsedMB: mem.heapUsed / 1024 / 1024,
        heapLimitMB: heapLimit / 1024 / 1024,
        message: `Heap usage at ${(heapPercent * 100).toFixed(1)}% - WARNING threshold exceeded`,
        entry,
      });
    }

    // Emit recovery event if we dropped below a threshold
    if (this.lastLevel && !level) {
      this.emit('recovery', {
        previousLevel: this.lastLevel,
        percent: heapPercent,
        heapUsedMB: mem.heapUsed / 1024 / 1024,
        message: `Heap usage recovered to ${(heapPercent * 100).toFixed(1)}%`,
        entry,
      });
    }

    this.lastLevel = level;
    return entry;
  }

  /**
   * Register an event listener
   *
   * @param {string} event - Event name ('check', 'warning', 'critical', 'recovery')
   * @param {Function} callback - Callback function
   * @returns {MemoryMonitor} this (for chaining)
   */
  on(event, callback) {
    this.listeners.push({ event, callback });
    return this;
  }

  /**
   * Remove an event listener
   *
   * @param {string} event - Event name
   * @param {Function} callback - Callback function to remove
   * @returns {MemoryMonitor} this (for chaining)
   */
  off(event, callback) {
    this.listeners = this.listeners.filter(l => !(l.event === event && l.callback === callback));
    return this;
  }

  /**
   * Emit an event to all registered listeners
   *
   * @param {string} event - Event name
   * @param {any} data - Event data
   */
  emit(event, data) {
    this.listeners
      .filter(l => l.event === event)
      .forEach(l => {
        try {
          l.callback(data);
        } catch (err) {
          console.error(`[MemoryMonitor] Error in ${event} listener:`, err.message);
        }
      });
  }

  /**
   * Get memory statistics from history
   *
   * @returns {Object|null} Statistics object or null if no history
   */
  getStats() {
    if (this.memoryHistory.length === 0) {
      return null;
    }

    const current = this.memoryHistory[this.memoryHistory.length - 1];
    const percentages = this.memoryHistory.map(e => e.heapPercent);

    const min = Math.min(...percentages);
    const max = Math.max(...percentages);
    const avg = percentages.reduce((s, p) => s + p, 0) / percentages.length;

    // Calculate trend (positive = increasing, negative = decreasing)
    let trend = 0;
    if (this.memoryHistory.length >= 2) {
      const recent = percentages.slice(-10);
      if (recent.length >= 2) {
        trend = (recent[recent.length - 1] - recent[0]) / recent.length;
      }
    }

    return {
      current: {
        percent: current.heapPercent,
        heapUsedMB: current.heapUsed / 1024 / 1024,
        heapLimitMB: current.heapLimit / 1024 / 1024,
        timestamp: current.timestamp,
      },
      min,
      max,
      avg,
      trend,
      historySize: this.memoryHistory.length,
      level: this.lastLevel,
    };
  }

  /**
   * Check if spawning agents should be paused due to memory pressure
   *
   * @returns {Object} { shouldPause: boolean, reason: string|null, stats: Object|null }
   */
  shouldPauseSpawning() {
    const stats = this.getStats();

    if (!stats) {
      return { shouldPause: false, reason: null, stats: null };
    }

    if (stats.current.percent >= this.criticalThreshold) {
      return {
        shouldPause: true,
        reason: `Heap usage at ${(stats.current.percent * 100).toFixed(1)}% exceeds critical threshold (${this.criticalThreshold * 100}%)`,
        stats,
      };
    }

    // Also pause if trend is strongly increasing and we're above warning
    if (stats.current.percent >= this.warningThreshold && stats.trend > 0.01) {
      return {
        shouldPause: true,
        reason: `Heap usage at ${(stats.current.percent * 100).toFixed(1)}% with increasing trend`,
        stats,
      };
    }

    return { shouldPause: false, reason: null, stats };
  }

  /**
   * Attempt to trigger garbage collection (if exposed)
   * Note: Requires --expose-gc flag to be effective
   *
   * @returns {boolean} True if GC was triggered
   */
  triggerGC() {
    if (typeof global.gc === 'function') {
      global.gc();
      return true;
    }
    return false;
  }

  /**
   * Get current memory status as a formatted string
   *
   * @returns {string} Status string
   */
  getStatusString() {
    const stats = this.getStats();
    if (!stats) {
      return 'No memory data available';
    }

    const { current, min, max, avg, trend, level } = stats;
    const trendStr = trend > 0 ? `+${(trend * 100).toFixed(2)}%` : `${(trend * 100).toFixed(2)}%`;

    return [
      `Heap: ${current.heapUsedMB.toFixed(1)}MB / ${current.heapLimitMB.toFixed(1)}MB (${(current.percent * 100).toFixed(1)}%)`,
      `Range: ${(min * 100).toFixed(1)}% - ${(max * 100).toFixed(1)}%`,
      `Avg: ${(avg * 100).toFixed(1)}%`,
      `Trend: ${trendStr}`,
      level ? `Status: ${level}` : 'Status: OK',
    ].join(' | ');
  }

  /**
   * Clear history and reset state
   * @returns {MemoryMonitor} this (for chaining)
   */
  reset() {
    this.memoryHistory = [];
    this.lastLevel = null;
    return this;
  }

function resetGlobalMonitor() {
  if (globalMonitor) {
    globalMonitor.stop();
    globalMonitor = null;
  }
}

class PerformanceProfiler {
  constructor(specsPath) {
    this.specsPath = specsPath;
    this.metrics = new Map();
    this.sessions = new Map();
    this.callCounts = new Map();
  }

  /**
   * Instrument a function to track performance metrics
   * @param {string} name - Function identifier
   * @param {Function} fn - Function to instrument
   * @returns {Function} Instrumented function
   */
  instrumentFunction(name, fn) {
    const self = this;

    // Return a wrapper that works for both sync and async functions
    return function instrumentedWrapper(...args) {
      const startTime = performance.now();
      const startMemory = process.memoryUsage().heapUsed;

      let result;
      let error;

      try {
        result = fn(...args);

        // Check if result is a Promise
        if (result && typeof result.then === 'function') {
          // For async functions, track metrics after promise resolves
          return result.then(
            value => {
              self._recordMetrics(name, startTime, startMemory, value, null);
              return value;
            },
            err => {
              self._recordMetrics(name, startTime, startMemory, null, err);
              throw err;
            }
          );
        }
      } catch (err) {
        error = err;
      }

      // For sync functions, record metrics immediately
      self._recordMetrics(name, startTime, startMemory, result, error);

      if (error) {
        throw error;
      }

      return result;
    };
  }

  /**
   * Record metrics for a function call
   * @private
   */
  _recordMetrics(name, startTime, startMemory, result, _error) {
    const endTime = performance.now();
    const endMemory = process.memoryUsage().heapUsed;

    const executionTime = endTime - startTime;
    const memoryUsed = Math.max(0, endMemory - startMemory);

    // Track tokens if result contains token info
    let tokensUsed = 0;
    if (result && typeof result === 'object' && 'tokens' in result) {
      tokensUsed = result.tokens;
    }

    // Track cache hits if result contains cache info
    let cacheHits = 0;
    if (result && typeof result === 'object' && 'cacheHit' in result) {
      cacheHits = result.cacheHit ? 1 : 0;
    }

    // Update call count
    const currentCount = this.callCounts.get(name) || 0;
    this.callCounts.set(name, currentCount + 1);

    // Store metrics
    const existingMetrics = this.metrics.get(name);
    if (existingMetrics) {
      // Aggregate metrics for multiple runs
      this.metrics.set(name, {
        executionTime: existingMetrics.executionTime + executionTime,
        memoryUsed: existingMetrics.memoryUsed + memoryUsed,
        tokensUsed: existingMetrics.tokensUsed + tokensUsed,
        cacheHits: existingMetrics.cacheHits + cacheHits,
        callCount: this.callCounts.get(name),
      });
    } else {
      this.metrics.set(name, {
        executionTime,
        memoryUsed,
        tokensUsed,
        cacheHits,
        callCount: 1,
      });
    }
  }

  /**
   * Start a profiling session with a label
   * @param {string} label - Session identifier
   */
  startProfiling(label) {
    this.sessions.set(label, {
      startTime: performance.now(),
      startMemory: process.memoryUsage().heapUsed,
    });
  }

  /**
   * Stop a profiling session and store metrics
   * @param {string} label - Session identifier
   */
  stopProfiling(label) {
    const session = this.sessions.get(label);
    if (!session) {
      return;
    }

    const endTime = performance.now();
    const endMemory = process.memoryUsage().heapUsed;

    const executionTime = endTime - session.startTime;
    const memoryUsed = Math.max(0, endMemory - session.startMemory);

    this.metrics.set(label, {
      executionTime,
      memoryUsed,
      tokensUsed: 0,
      cacheHits: 0,
      callCount: 1,
    });

    this.sessions.delete(label);
  }

  /**
   * Get metrics for a specific label
   * @param {string} label - Metric identifier
   * @returns {Object|null} Metrics object or null if not found
   */
  getMetrics(label) {
    return this.metrics.get(label) || null;
  }

  /**
   * Profile all SPEC modules (SPEC-001 through SPEC-012)
   * @returns {Promise<Array>} Array of profiling results
   */
  async profileAllSpecs() {
    const results = [];

    // Find all SPEC modules in the specs path
    const specDirs = ['workflow', 'memory', 'testing', 'utils'];

    for (const dir of specDirs) {
      const dirPath = path.join(this.specsPath, dir);
      if (!fs.existsSync(dirPath)) {
        continue;
      }

      const files = fs.readdirSync(dirPath);
      for (const file of files) {
        if (file.endsWith('.cjs') || file.endsWith('.js')) {
          const modulePath = path.join(dirPath, file);
          const moduleName = path.basename(file, path.extname(file));

          try {
            const startTime = performance.now();
            const startMemory = process.memoryUsage().heapUsed;

            // Require the module to profile its load time
            require(modulePath);

            const endTime = performance.now();
            const endMemory = process.memoryUsage().heapUsed;

            results.push({
              module: moduleName,
              path: modulePath,
              loadTime: endTime - startTime,
              memoryUsed: Math.max(0, endMemory - startMemory),
            });
          } catch (_error) {
            // Skip modules that can't be loaded
          }
        }
      }
    }

    return results;
  }

  /**
   * Generate flame graph data in JSON format
   * @returns {Object} Flame graph data
   */
  generateFlameGraph() {
    const root = {
      name: 'root',
      value: 0,
      children: [],
    };

    // Build hierarchical structure from metrics
    const totalTime = Array.from(this.metrics.values()).reduce(
      (sum, m) => sum + m.executionTime,
      0
    );

    for (const [name, metrics] of this.metrics.entries()) {
      root.children.push({
        name,
        value: metrics.executionTime,
        percentage: totalTime > 0 ? (metrics.executionTime / totalTime) * 100 : 0,
      });
    }

    root.value = totalTime;

    return root;
  }

  /**
   * Generate performance heatmap per function
   * @returns {Object} Heatmap data
   */
  generateHeatmap() {
    const heatmap = {
      functions: [],
      minTime: Infinity,
      maxTime: -Infinity,
    };

    for (const [name, metrics] of this.metrics.entries()) {
      heatmap.functions.push({
        name,
        executionTime: metrics.executionTime,
        memoryUsed: metrics.memoryUsed,
        callCount: metrics.callCount || 1,
      });

      heatmap.minTime = Math.min(heatmap.minTime, metrics.executionTime);
      heatmap.maxTime = Math.max(heatmap.maxTime, metrics.executionTime);
    }

    // Sort by execution time (descending)
    heatmap.functions.sort((a, b) => b.executionTime - a.executionTime);

    return heatmap;
  }

  // ==========================================================================
  // Phase 5: Enhanced Profiling Methods
  // ==========================================================================

  /**
   * Record a metric directly (for external profiling)
   * @param {string} operation - Operation name
   * @param {Object} data - Metric data (duration, memoryUsed, frequency, category, timestamp)
   */
  record(operation, data) {
    const existing = this.metrics.get(operation);
    const records = existing?.records || [];
    records.push({
      ...data,
      timestamp: data.timestamp || Date.now(),
    });

    this.metrics.set(operation, {
      operation,
      executionTime: (existing?.executionTime || 0) + (data.duration || 0),
      memoryUsed: (existing?.memoryUsed || 0) + (data.memoryUsed || 0),
      tokensUsed: (existing?.tokensUsed || 0) + (data.tokensUsed || 0),
      cacheHits: (existing?.cacheHits || 0) + (data.cacheHits || 0),
      callCount: (existing?.callCount || 0) + 1,
      frequency: data.frequency || (existing?.callCount || 0) + 1,
      category: data.category || existing?.category,
      records,
    });
  }

  /**
   * Identify bottlenecks based on threshold
   * @param {number} threshold - Minimum duration to be considered bottleneck
   * @returns {Array} Array of bottleneck operations
   */
  identifyBottlenecks(threshold = 1000) {
    const bottlenecks = [];

    for (const [operation, metrics] of this.metrics.entries()) {
      const avgDuration =
        metrics.callCount > 0 ? metrics.executionTime / metrics.callCount : metrics.executionTime;

      if (avgDuration >= threshold) {
        const totalImpact = avgDuration * (metrics.frequency || metrics.callCount || 1);
        const suggestions = this._generateSuggestions(operation, metrics);

        bottlenecks.push({
          operation,
          avgDuration,
          totalImpact,
          frequency: metrics.frequency || metrics.callCount || 1,
          category: metrics.category,
          suggestions,
        });
      }
    }

    // Sort by total impact descending
    bottlenecks.sort((a, b) => b.totalImpact - a.totalImpact);

    return bottlenecks;
  }

  _generateSuggestions(operation, metrics) {
    const suggestions = [];

    if (
      metrics.category === 'io' ||
      operation.toLowerCase().includes('read') ||
      operation.toLowerCase().includes('write')
    ) {
      suggestions.push('Consider batching I/O operations');
      suggestions.push('Implement caching for repeated reads');
    }

    if (
      metrics.category === 'search' ||
      operation.toLowerCase().includes('grep') ||
      operation.toLowerCase().includes('search')
    ) {
      suggestions.push('Use indexed search for large datasets');
      suggestions.push('Cache search results when possible');
    }

    if (metrics.frequency > 10) {
      suggestions.push('High frequency operation - consider parallelization');
    }

    if (suggestions.length === 0) {
      suggestions.push('Review for optimization opportunities');
    }

    return suggestions;
  }

  /**
   * Get latency statistics for an operation
   * @param {string} operation - Operation name
   * @returns {Object} Latency stats (p50, p95, p99, mean, min, max)
   */
  getLatencyStats(operation) {
    const metrics = this.metrics.get(operation);
    if (!metrics || !metrics.records || metrics.records.length === 0) {
      return { p50: 0, p95: 0, p99: 0, mean: 0, min: 0, max: 0 };
    }

    const durations = metrics.records
      .map(r => r.duration)
      .filter(d => d !== undefined)
      .sort((a, b) => a - b);

    if (durations.length === 0) {
      return { p50: 0, p95: 0, p99: 0, mean: 0, min: 0, max: 0 };
    }

    const mean = durations.reduce((sum, d) => sum + d, 0) / durations.length;
    const p50Index = Math.floor(durations.length * 0.5);
    const p95Index = Math.floor(durations.length * 0.95);
    const p99Index = Math.floor(durations.length * 0.99);

    return {
      p50: durations[p50Index] || durations[durations.length - 1],
      p95: durations[p95Index] || durations[durations.length - 1],
      p99: durations[p99Index] || durations[durations.length - 1],
      mean,
      min: durations[0],
      max: durations[durations.length - 1],
    };
  }

  /**
   * Get memory statistics for all operations
   * @returns {Object} Memory stats by operation
   */
  getMemoryStats() {
    const stats = {};

    for (const [operation, metrics] of this.metrics.entries()) {
      if (metrics.memoryUsed > 0 || (metrics.records && metrics.records.some(r => r.memoryUsed))) {
        stats[operation] = {
          totalMemory: metrics.memoryUsed,
          avgMemory: metrics.callCount > 0 ? metrics.memoryUsed / metrics.callCount : 0,
          records: metrics.records?.filter(r => r.memoryUsed !== undefined) || [],
        };
      }
    }

    return stats;
  }

  /**
   * Detect memory usage trend for an operation
   * @param {string} operation - Operation name
   * @returns {Object} Trend analysis {direction, slope}
   */
  detectMemoryTrend(operation) {
    const metrics = this.metrics.get(operation);
    if (!metrics || !metrics.records || metrics.records.length < 2) {
      return { direction: 'stable', slope: 0 };
    }

    const records = metrics.records
      .filter(r => r.memoryUsed !== undefined)
      .sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

    if (records.length < 2) {
      return { direction: 'stable', slope: 0 };
    }

    // Simple linear regression
    const n = records.length;
    const xMean = (n - 1) / 2;
    const yMean = records.reduce((sum, r) => sum + r.memoryUsed, 0) / n;

    let numerator = 0;
    let denominator = 0;
    for (let i = 0; i < n; i++) {
      numerator += (i - xMean) * (records[i].memoryUsed - yMean);
      denominator += (i - xMean) * (i - xMean);
    }

    const slope = denominator !== 0 ? numerator / denominator : 0;

    let direction = 'stable';
    if (slope > yMean * 0.1) direction = 'increasing';
    else if (slope < -yMean * 0.1) direction = 'decreasing';

    return { direction, slope };
  }

  /**
   * Get average memory for an operation
   * @param {string} operation - Operation name
   * @returns {number} Average memory used
   */
  getAverageMemory(operation) {
    const metrics = this.metrics.get(operation);
    if (!metrics || !metrics.records || metrics.records.length === 0) {
      return 0;
    }

    const memoryRecords = metrics.records.filter(r => r.memoryUsed !== undefined);
    if (memoryRecords.length === 0) return 0;

    return memoryRecords.reduce((sum, r) => sum + r.memoryUsed, 0) / memoryRecords.length;
  }

  /**
   * Generate optimization recommendations
   * @returns {Array} Array of recommendations
   */
  generateRecommendations() {
    const recommendations = [];

    for (const [operation, metrics] of this.metrics.entries()) {
      const avgDuration =
        metrics.callCount > 0 ? metrics.executionTime / metrics.callCount : metrics.executionTime;

      const totalImpact = avgDuration * (metrics.frequency || metrics.callCount || 1);

      if (totalImpact > 0) {
        // Estimate potential savings (assume 30% improvement possible)
        const estimatedSavings = totalImpact * 0.3;

        recommendations.push({
          operation,
          avgDuration,
          totalImpact,
          frequency: metrics.frequency || metrics.callCount || 1,
          estimatedSavings,
          suggestions: this._generateSuggestions(operation, metrics),
        });
      }
    }

    // Sort by total impact descending
    recommendations.sort((a, b) => b.totalImpact - a.totalImpact);

    return recommendations;
  }

  /**
   * Clear all metrics
   */
  clear() {
    this.metrics.clear();
    this.sessions.clear();
    this.callCounts.clear();
  }

function bashPath(windowsPath) {
  if (!windowsPath) return windowsPath;
  // Input validation
  if (typeof windowsPath !== 'string') {
    return windowsPath;
  }
  // SEC-REMEDIATION-002: Sanitize null bytes (command injection prevention)
  // Null bytes can truncate paths or bypass validation
  const sanitized = windowsPath.replace(/\0/g, '');
  // Warn on shell metacharacters that could be dangerous
  const shellMetachars = /[$`!]/;
  if (shellMetachars.test(sanitized) && process.env.PLATFORM_DEBUG === 'true') {
    console.error(
      JSON.stringify({
        type: 'security_warning',
        message: 'Path contains shell metacharacters',
        path: sanitized.substring(0, 100), // Truncate for logging
      })
    );
  }
  // Convert all backslashes to forward slashes
  return sanitized.replace(/\\/g, '/');
}

function shellQuote(filepath) {
  if (!filepath) return filepath;

  // First normalize to forward slashes for Bash compatibility
  const normalized = bashPath(filepath);

  if (isWindows) {
    // Windows: Use double quotes, escape existing double quotes
    return `"${normalized.replace(/"/g, '""')}"`;
  }
  // Unix: Use single quotes, escape existing single quotes
  return `'${normalized.replace(/'/g, "'\\''")}'`;
}

function bashSafePath(filepath) {
  return shellQuote(bashPath(filepath));
}

function normalizePath(filepath) {
  if (!filepath) return filepath;
  return filepath.replace(/[/\\]/g, path.sep);
}

function isWindowsAbsolutePath(filepath) {
  if (!filepath) return false;
  // Match drive letter followed by : and separator
  return /^[A-Za-z]:[/\\]/.test(filepath);
}

function isUnixAbsolutePath(filepath) {
  if (!filepath) return false;
  return filepath.startsWith('/');
}

function isAbsolutePath(filepath) {
  return isWindowsAbsolutePath(filepath) || isUnixAbsolutePath(filepath);
}

function getLineEnding() {
  return isWindows ? '\r\n' : '\n';
}

function normalizeLineEndings(text) {
  if (!text) return text;
  return text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function scoreCompleteness(answers, expectedFields) {
  if (expectedFields.length === 0) return 100;

  const answeredFields = answers.filter(a => a.answer && a.answer.trim().length > 0).length;
  const coverage = answeredFields / expectedFields.length;

  return Math.round(coverage * 100);
}

function scoreQuality(answers, domainPatterns) {
  if (answers.length === 0) return 0;

  // Average quality from answers
  const avgQuality = answers.reduce((sum, a) => sum + (a.quality || 0), 0) / answers.length;

  // Base score from quality (0-1 scale to 0-100)
  let score = avgQuality * 100;

  // Bonus for pattern matches
  if (domainPatterns && domainPatterns.length > 0) {
    const matches = answers.filter(a => {
      const lower = a.answer.toLowerCase();
      return domainPatterns.some(pattern => {
        const keywords = pattern.toLowerCase().split(/\s+/);
        return keywords.some(kw => lower.includes(kw));
      });
    });
    const bonus = (matches.length / answers.length) * 10;
    score += bonus;
  }

  return Math.min(100, Math.round(score));
}

function scoreConsistency(answers, context) {
  if (answers.length === 0) return 100;

  let conflicts = 0;
  const topics = {};

  // Group answers by topic
  answers.forEach(a => {
    const topicWords = extractTopics(a.question || a.answer);
    topicWords.forEach(topic => {
      if (!topics[topic]) topics[topic] = [];
      topics[topic].push(a.answer);
    });
  });

  // Check for conflicting answers (different non-trivial answers to same topic)
  Object.keys(topics).forEach(topic => {
    const topicAnswers = topics[topic];
    if (topicAnswers.length > 1) {
      const normalized = topicAnswers.map(a => a.trim().toLowerCase());
      const uniqueAnswers = new Set(normalized);

      // Only count as conflict if answers are substantially different
      if (uniqueAnswers.size > 1) {
        // Check if they're contradictory (e.g., "PostgreSQL" vs "MySQL")
        const answerList = Array.from(uniqueAnswers);
        let hasContradiction = false;

        for (let i = 0; i < answerList.length; i++) {
          for (let j = i + 1; j < answerList.length; j++) {
            // Check if answers don't overlap at all (likely conflicting)
            const words1 = answerList[i].split(/\s+/);
            const words2 = answerList[j].split(/\s+/);
            const overlap = words1.filter(w => words2.includes(w));

            if (overlap.length === 0 && words1.length > 0 && words2.length > 0) {
              hasContradiction = true;
              break;
            }
          }
          if (hasContradiction) break;
        }

        if (hasContradiction) conflicts++;
      }
    }
  });

  // Check consistency with context
  Object.keys(context).forEach(key => {
    const contextValue = String(context[key]).toLowerCase();
    answers.forEach(a => {
      const answerValue = String(a.answer).toLowerCase();
      if (answerValue.includes(key.toLowerCase())) {
        if (!answerValue.includes(contextValue)) {
          conflicts++;
        }
      }
    });
  });

  const consistency = Math.max(0, 100 - conflicts * 25); // Higher penalty per conflict
  return Math.round(consistency);
}

function computeOverallReadiness(scores) {
  const { completeness, quality, consistency } = scores;

  // Weighted average: completeness (60%), quality (25%), consistency (15%)
  // Completeness is weighted highest as it's most critical
  const weighted = completeness * 0.6 + quality * 0.25 + consistency * 0.15;

  return Math.round(weighted);
}

function isTransientError(error) {
  // Check for permanent error types first
  if (PERMANENT_ERROR_TYPES.has(error.constructor.name)) {
    return false;
  }

  // Check for transient error codes
  if (error.code && TRANSIENT_ERROR_CODES.has(error.code)) {
    return true;
  }

  // Default: treat as permanent (conservative)
  // This prevents infinite retries on unknown errors
  return false;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function invalidateCache(filePath) {
  cache.delete(filePath);
}

function clearAllCache() {
  cache.clear();
}

function estimateTokens(content) {
  const chars = content.length;
  const tokens = Math.floor(chars * CHAR_TO_TOKEN_RATIO);

  return {
    tokens,
    chars,
    estimate: `~${tokens} tokens (${chars} chars × ${CHAR_TO_TOKEN_RATIO})`,
  };
}

function trackAgentUsage(agentId, usage) {
  const { inputTokens = 0, outputTokens = 0, toolResults = '' } = usage;

  // Estimate tool result tokens
  const toolTokensEstimate = estimateTokens(toolResults).tokens;

  // Calculate total tokens for this usage
  const usageTokens = inputTokens + outputTokens + toolTokensEstimate;

  // Get or initialize agent usage
  if (!agentUsageMap.has(agentId)) {
    agentUsageMap.set(agentId, {
      totalTokens: 0,
      budget: DEFAULT_BUDGET,
    });
  }

  const agentData = agentUsageMap.get(agentId);

  // Update cumulative total
  agentData.totalTokens += usageTokens;

  // Calculate budget stats
  const budgetRemaining = agentData.budget - agentData.totalTokens;
  const percentUsed = (agentData.totalTokens / agentData.budget) * 100;

  // Determine status (tracking only - no blocking)
  let status = 'OK';
  if (percentUsed >= 90) {
    status = 'CRITICAL';
  } else if (percentUsed >= 80) {
    status = 'WARNING';
  }

  return {
    agentId,
    totalTokens: agentData.totalTokens,
    budget: agentData.budget,
    budgetRemaining,
    percentUsed,
    status,
  };
}

function checkBudgetStatus(agentId) {
  if (!agentUsageMap.has(agentId)) {
    return {
      used: 0,
      budget: DEFAULT_BUDGET,
      remaining: DEFAULT_BUDGET,
      percentUsed: 0,
      status: 'OK',
    };
  }

  const agentData = agentUsageMap.get(agentId);
  const remaining = agentData.budget - agentData.totalTokens;
  const percentUsed = (agentData.totalTokens / agentData.budget) * 100;

  let status = 'OK';
  if (percentUsed >= 90) {
    status = 'CRITICAL';
  } else if (percentUsed >= 80) {
    status = 'WARNING';
  }

  return {
    used: agentData.totalTokens,
    budget: agentData.budget,
    remaining,
    percentUsed,
    status,
  };
}

function logTokenEvent(eventType, data) {
  const { agentId, tokens, reason } = data;

  const event = {
    timestamp: new Date().toISOString(),
    eventType,
    agentId,
    tokens,
    reason,
  };

  // Ensure directory exists
  const logDir = path.dirname(TOKEN_LOG_PATH);
  if (!fs.existsSync(logDir)) {
    fs.mkdirSync(logDir, { recursive: true });
  }

  // Append to JSONL file (one JSON object per line)
  fs.appendFileSync(TOKEN_LOG_PATH, JSON.stringify(event) + '\n', 'utf8');
}

function queryByPhase(phaseId, tracksData) {
  if (!Array.isArray(tracksData)) {
    throw new TypeError('tracksData must be an array');
  }

  const tasks = tracksData.filter(track => track.phaseState === phaseId);

  // Compute aggregate metrics
  const estimatedDays = tasks.filter(t => t.estimatedEffort?.days).map(t => t.estimatedEffort.days);
  const actualDays = tasks.filter(t => t.actualEffort?.days).map(t => t.actualEffort.days);

  const avgEstimatedDays =
    estimatedDays.length > 0
      ? estimatedDays.reduce((sum, d) => sum + d, 0) / estimatedDays.length
      : 0;

  const avgActualDays =
    actualDays.length > 0 ? actualDays.reduce((sum, d) => sum + d, 0) / actualDays.length : 0;

  return {
    phase: phaseId,
    tasks,
    metrics: {
      totalTasks: tasks.length,
      avgEstimatedDays,
      avgActualDays,
    },
  };
}

function queryByAgent(agentId, tracksData) {
  if (!Array.isArray(tracksData)) {
    throw new TypeError('tracksData must be an array');
  }

  const tasks = tracksData.filter(track => track.assignee === agentId);

  // Compute completion metrics
  const completedTasks = tasks.filter(t => t.status === 'completed').length;
  const inProgressTasks = tasks.filter(t => t.status === 'in_progress').length;
  const completionRate = tasks.length > 0 ? (completedTasks / tasks.length) * 100 : 0;

  // Compute effort accuracy (estimated vs actual)
  const tasksWithEffort = tasks.filter(t => t.estimatedEffort?.days && t.actualEffort?.days);

  const avgEstimatedDays =
    tasksWithEffort.length > 0
      ? tasksWithEffort.reduce((sum, t) => sum + t.estimatedEffort.days, 0) / tasksWithEffort.length
      : 0;

  const avgActualDays =
    tasksWithEffort.length > 0
      ? tasksWithEffort.reduce((sum, t) => sum + t.actualEffort.days, 0) / tasksWithEffort.length
      : 0;

  // Estimate accuracy: how close actual is to estimated (100% = perfect)
  const estimateAccuracy =
    avgEstimatedDays > 0
      ? 100 - (Math.abs(avgActualDays - avgEstimatedDays) / avgEstimatedDays) * 100
      : 0;

  return {
    agent: agentId,
    tasks,
    metrics: {
      completedTasks,
      inProgressTasks,
      completionRate,
      avgEstimatedDays,
      avgActualDays,
      estimateAccuracy,
    },
  };
}

function queryByStatus(status, tracksData) {
  if (!Array.isArray(tracksData)) {
    throw new TypeError('tracksData must be an array');
  }

  const tasks = tracksData.filter(track => track.status === status);

  // Sort by updated_at (most recent first)
  tasks.sort((a, b) => {
    if (!a.updated_at) return 1;
    if (!b.updated_at) return -1;
    return new Date(b.updated_at) - new Date(a.updated_at);
  });

  // Compute timeline metrics (created -> updated duration)
  const durations = tasks
    .filter(t => t.created_at && t.updated_at)
    .map(t => {
      try {
        const created = new Date(t.created_at);
        const updated = new Date(t.updated_at);
        return (updated - created) / (1000 * 60 * 60 * 24); // Convert to days
      } catch (_err) {
        return null;
      }
    })
    .filter(d => d !== null);

  const avgDurationDays =
    durations.length > 0 ? durations.reduce((sum, d) => sum + d, 0) / durations.length : 0;

  // Group by type
  const byType = {};
  tasks.forEach(t => {
    byType[t.type] = (byType[t.type] || 0) + 1;
  });

  return {
    status,
    tasks,
    metrics: {
      totalTasks: tasks.length,
      avgDurationDays,
      byType,
    },
  };
}

function computeProjectMetrics(tracksData) {
  if (!Array.isArray(tracksData)) {
    throw new TypeError('tracksData must be an array');
  }

  const totalTasks = tracksData.length;
  const completedTasks = tracksData.filter(t => t.status === 'completed').length;
  const completionPercentage = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;

  // Effort metrics
  const totalEstimatedDays = tracksData
    .filter(t => t.estimatedEffort?.days)
    .reduce((sum, t) => sum + t.estimatedEffort.days, 0);

  const totalActualDays = tracksData
    .filter(t => t.actualEffort?.days)
    .reduce((sum, t) => sum + t.actualEffort.days, 0);

  // Average effort multiplier (actual / estimated)
  const tasksWithEffort = tracksData.filter(
    t => t.estimatedEffort?.days && t.actualEffort?.days && t.estimatedEffort.days > 0
  );

  const avgEffortMultiplier =
    tasksWithEffort.length > 0
      ? tasksWithEffort.reduce((sum, t) => sum + t.actualEffort.days / t.estimatedEffort.days, 0) /
        tasksWithEffort.length
      : null;

  // Phases completed
  const phasesCompleted = {};
  tracksData.forEach(t => {
    if (t.phaseState) {
      phasesCompleted[t.phaseState] = (phasesCompleted[t.phaseState] || 0) + 1;
    }
  });

  // By priority
  const byPriority = {};
  tracksData.forEach(t => {
    if (t.priority) {
      byPriority[t.priority] = (byPriority[t.priority] || 0) + 1;
    }
  });

  return {
    totalTasks,
    completedTasks,
    completionPercentage,
    totalEstimatedDays,
    totalActualDays,
    avgEffortMultiplier,
    phasesCompleted,
    byPriority,
  };
}

function generateReport(tracksData) {
  if (!Array.isArray(tracksData)) {
    throw new TypeError('tracksData must be an array');
  }

  if (tracksData.length === 0) {
    return '# Track Analytics Report\n\nNo tracks found.\n';
  }

  const metrics = computeProjectMetrics(tracksData);
  const timestamp = new Date().toISOString();

  let report = `# Track Analytics Report\n\n`;
  report += `**Generated:** ${timestamp}\n\n`;

  // Project Metrics
  report += `## Project Metrics\n\n`;
  report += `- **Total Tasks:** ${metrics.totalTasks}\n`;
  report += `- **Completed:** ${metrics.completedTasks}\n`;
  report += `- **Completion Percentage:** ${metrics.completionPercentage.toFixed(1)}%\n`;
  report += `- **Total Estimated:** ${metrics.totalEstimatedDays} days\n`;
  report += `- **Total Actual:** ${metrics.totalActualDays} days\n`;
  if (metrics.avgEffortMultiplier !== null) {
    report += `- **Avg Effort Multiplier:** ${metrics.avgEffortMultiplier.toFixed(2)}x\n`;
  }
  report += `\n`;

  // Phase Breakdown
  report += `## Phase Breakdown\n\n`;
  if (Object.keys(metrics.phasesCompleted).length > 0) {
    Object.entries(metrics.phasesCompleted)
      .sort((a, b) => b[1] - a[1])
      .forEach(([phase, count]) => {
        report += `- **${phase}:** ${count} tasks\n`;
      });
  } else {
    report += `No phase data available.\n`;
  }
  report += `\n`;

  // Priority Breakdown
  report += `## Priority Breakdown\n\n`;
  if (Object.keys(metrics.byPriority).length > 0) {
    Object.entries(metrics.byPriority)
      .sort((a, b) => b[1] - a[1])
      .forEach(([priority, count]) => {
        report += `- **${priority}:** ${count} tasks\n`;
      });
  } else {
    report += `No priority data available.\n`;
  }
  report += `\n`;

  // Agent Metrics
  const agents = [...new Set(tracksData.filter(t => t.assignee).map(t => t.assignee))];
  if (agents.length > 0) {
    report += `## Agent Metrics\n\n`;
    agents.forEach(agent => {
      const agentData = queryByAgent(agent, tracksData);
      report += `### ${agent}\n\n`;
      report += `- Completed: ${agentData.metrics.completedTasks}\n`;
      report += `- In Progress: ${agentData.metrics.inProgressTasks}\n`;
      report += `- Completion Rate: ${agentData.metrics.completionRate.toFixed(1)}%\n`;
      if (agentData.metrics.avgEstimatedDays > 0) {
        report += `- Avg Estimated: ${agentData.metrics.avgEstimatedDays.toFixed(1)} days\n`;
        report += `- Avg Actual: ${agentData.metrics.avgActualDays.toFixed(1)} days\n`;
        report += `- Estimate Accuracy: ${agentData.metrics.estimateAccuracy.toFixed(1)}%\n`;
      }
      report += `\n`;
    });
  }

  // Insights (auto-generated)
  report += `## Insights\n\n`;
  const insights = [];

  // Insight: Faster than estimated
  if (metrics.avgEffortMultiplier !== null && metrics.avgEffortMultiplier < 1) {
    const percentage = ((1 - metrics.avgEffortMultiplier) * 100).toFixed(1);
    insights.push(
      `- Implementation is ${percentage}% faster than estimated on average (under budget)`
    );
  }

  // Insight: Slower than estimated
  if (metrics.avgEffortMultiplier !== null && metrics.avgEffortMultiplier > 1.2) {
    const percentage = ((metrics.avgEffortMultiplier - 1) * 100).toFixed(1);
    insights.push(
      `- Implementation is ${percentage}% slower than estimated (estimates may need adjustment)`
    );
  }

  // Insight: Critical items
  if (metrics.byPriority.critical > 0) {
    insights.push(`- ${metrics.byPriority.critical} critical priority items require attention`);
  }

  // Insight: Completion rate
  if (metrics.completionPercentage < 50) {
    insights.push(
      `- Project is ${metrics.completionPercentage.toFixed(1)}% complete (early stage)`
    );
  } else if (metrics.completionPercentage >= 80) {
    insights.push(
      `- Project is ${metrics.completionPercentage.toFixed(1)}% complete (nearing completion)`
    );
  }

  if (insights.length > 0) {
    insights.forEach(insight => {
      report += `${insight}\n`;
    });
  } else {
    report += `No insights generated.\n`;
  }
  report += `\n`;

  // Task Lists by Status
  const statuses = [
    { key: 'completed', label: 'Completed' },
    { key: 'in_progress', label: 'In Progress' },
    { key: 'review', label: 'Review' },
    { key: 'new', label: 'New' },
  ];

  statuses.forEach(({ key, label }) => {
    const statusData = queryByStatus(key, tracksData);
    if (statusData.tasks.length > 0) {
      report += `### ${label} Tasks\n\n`;
      statusData.tasks.slice(0, 10).forEach(task => {
        report += `- **${task.trackId}**: ${task.description || 'No description'}\n`;
      });
      if (statusData.tasks.length > 10) {
        report += `- ... and ${statusData.tasks.length - 10} more\n`;
      }
      report += `\n`;
    }
  });

  return report;
}

class PatternLibrary {
  constructor(config = {}) {
    this.config = {
      persistence: config.persistence !== false,
      storagePath:
        config.storagePath || path.join(process.cwd(), '.claude', 'lib', 'ml', 'patterns.json'),
      ...config,
    };

    this.patterns = new Map();
    this.nextId = 1;

    // Load from disk if persistence enabled
    if (this.config.persistence) {
      this._loadFromDisk();
    }
  }

  /**
   * Generate unique ID for a pattern
   * @returns {string} Unique ID
   */
  _generateId() {
    const id = `pattern-${this.nextId}`;
    this.nextId++;
    return id;
  }

  /**
   * Store a new pattern
   * @param {Object} pattern - Pattern to store
   * @returns {string} Pattern ID
   */
  store(pattern) {
    const id = this._generateId();
    const storedPattern = {
      ...pattern,
      id,
      metadata: {
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        usageCount: 0,
        successCount: 0,
        failureCount: 0,
        successRate: 1.0,
      },
    };

    this.patterns.set(id, storedPattern);

    if (this.config.persistence) {
      this._saveToDisk();
    }

    return id;
  }

  /**
   * Get pattern by ID
   * @param {string} id - Pattern ID
   * @returns {Object|null} Pattern or null
   */
  get(id) {
    return this.patterns.get(id) || null;
  }

  /**
   * Find patterns by type
   * @param {string} type - Pattern type
   * @returns {Array} Matching patterns
   */
  findByType(type) {
    return Array.from(this.patterns.values()).filter(p => p.type === type);
  }

  /**
   * Search patterns by name (partial match)
   * @param {string} query - Search query
   * @returns {Array} Matching patterns
   */
  search(query) {
    const lowerQuery = query.toLowerCase();
    return Array.from(this.patterns.values()).filter(
      p => p.name && p.name.toLowerCase().includes(lowerQuery)
    );
  }

  /**
   * Record usage of a pattern
   * @param {string} id - Pattern ID
   */
  recordUsage(id) {
    const pattern = this.patterns.get(id);
    if (pattern) {
      pattern.metadata.usageCount++;
      pattern.metadata.updatedAt = new Date().toISOString();

      if (this.config.persistence) {
        this._saveToDisk();
      }
    }
  }

  /**
   * Record outcome (success/failure) for a pattern
   * @param {string} id - Pattern ID
   * @param {boolean} success - Whether usage was successful
   */
  recordOutcome(id, success) {
    const pattern = this.patterns.get(id);
    if (pattern) {
      if (success) {
        pattern.metadata.successCount++;
      } else {
        pattern.metadata.failureCount++;
      }

      const total = pattern.metadata.successCount + pattern.metadata.failureCount;
      pattern.metadata.successRate = total > 0 ? pattern.metadata.successCount / total : 1.0;
      pattern.metadata.updatedAt = new Date().toISOString();

      if (this.config.persistence) {
        this._saveToDisk();
      }
    }
  }

  /**
   * Calculate reusability score for a pattern
   * @param {string} id - Pattern ID
   * @returns {number} Reusability score (0-1)
   */
  getReusabilityScore(id) {
    const pattern = this.patterns.get(id);
    if (!pattern) return 0;

    const metadata = pattern.metadata;

    // Score components:
    // 1. Usage frequency (normalized, max contribution: 0.4)
    const maxUsage = this._getMaxUsage();
    const usageScore = maxUsage > 0 ? (metadata.usageCount / maxUsage) * 0.4 : 0;

    // 2. Success rate (max contribution: 0.4)
    const successScore = metadata.successRate * 0.4;

    // 3. Recency (patterns used recently score higher, max: 0.2)
    const daysSinceUpdate = this._daysSince(metadata.updatedAt);
    const recencyScore = Math.max(0, (30 - daysSinceUpdate) / 30) * 0.2;

    return Math.min(1, usageScore + successScore + recencyScore);
  }

  _getMaxUsage() {
    let max = 0;
    for (const pattern of this.patterns.values()) {
      if (pattern.metadata.usageCount > max) {
        max = pattern.metadata.usageCount;
      }
    }
    return max;
  }

  _daysSince(dateStr) {
    const date = new Date(dateStr);
    const now = new Date();
    const diff = now - date;
    return diff / (1000 * 60 * 60 * 24);
  }

  /**
   * Rank patterns by reusability
   * @returns {Array} Patterns sorted by reusability score
   */
  rankByReusability() {
    const ranked = Array.from(this.patterns.values())
      .map(p => ({
        ...p,
        reusabilityScore: this.getReusabilityScore(p.id),
      }))
      .sort((a, b) => b.reusabilityScore - a.reusabilityScore);

    return ranked;
  }

  /**
   * Get library statistics
   * @returns {Object} Statistics
   */
  getStats() {
    const patterns = Array.from(this.patterns.values());
    const stats = {
      totalPatterns: patterns.length,
      byType: {},
      totalUsage: 0,
      avgSuccessRate: 0,
    };

    for (const pattern of patterns) {
      // Count by type
      const type = pattern.type || 'unknown';
      stats.byType[type] = (stats.byType[type] || 0) + 1;

      // Sum usage
      stats.totalUsage += pattern.metadata.usageCount;

      // Sum success rate
      stats.avgSuccessRate += pattern.metadata.successRate;
    }

    // Calculate average success rate
    if (patterns.length > 0) {
      stats.avgSuccessRate /= patterns.length;
    }

    return stats;
  }

  /**
   * Delete a pattern
   * @param {string} id - Pattern ID
   * @returns {boolean} Whether deletion was successful
   */
  delete(id) {
    const deleted = this.patterns.delete(id);

    if (deleted && this.config.persistence) {
      this._saveToDisk();
    }

    return deleted;
  }

  /**
   * Update a pattern
   * @param {string} id - Pattern ID
   * @param {Object} updates - Fields to update
   * @returns {Object|null} Updated pattern or null
   */
  update(id, updates) {
    const pattern = this.patterns.get(id);
    if (!pattern) return null;

    // Merge updates (but preserve metadata)
    const updated = {
      ...pattern,
      ...updates,
      id: pattern.id, // Preserve ID
      metadata: {
        ...pattern.metadata,
        updatedAt: new Date().toISOString(),
      },
    };

    this.patterns.set(id, updated);

    if (this.config.persistence) {
      this._saveToDisk();
    }

    return updated;
  }

  /**
   * Export library to JSON
   * @returns {string} JSON string
   */
  export() {
    const data = {
      patterns: Array.from(this.patterns.values()),
      exportedAt: new Date().toISOString(),
      version: '1.0',
    };
    return JSON.stringify(data, null, 2);
  }

  /**
   * Import patterns from JSON
   * @param {string} json - JSON string
   * @param {Object} options - Options (merge: boolean)
   */
  import(json, options = {}) {
    const data = JSON.parse(json);

    if (!options.merge) {
      this.patterns.clear();
    }

    for (const pattern of data.patterns || []) {
      // Generate new ID to avoid conflicts
      const newId = this._generateId();
      this.patterns.set(newId, {
        ...pattern,
        id: newId,
      });
    }

    if (this.config.persistence) {
      this._saveToDisk();
    }
  }

  /**
   * Load patterns from disk
   * @private
   */
  _loadFromDisk() {
    try {
      if (fs.existsSync(this.config.storagePath)) {
        const data = fs.readFileSync(this.config.storagePath, 'utf8');
        const parsed = JSON.parse(data);

        for (const pattern of parsed.patterns || []) {
          this.patterns.set(pattern.id, pattern);
          // Update nextId to avoid conflicts
          const numId = parseInt(pattern.id.replace('pattern-', ''), 10);
          if (!isNaN(numId) && numId >= this.nextId) {
            this.nextId = numId + 1;
          }
        }
      }
    } catch (_err) {
      // Silently ignore - will start with empty library
    }
  }

  /**
   * Save patterns to disk
   * @private
   */
  _saveToDisk() {
    try {
      const dir = path.dirname(this.config.storagePath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }

      const data = {
        patterns: Array.from(this.patterns.values()),
        savedAt: new Date().toISOString(),
        version: '1.0',
      };

      fs.writeFileSync(this.config.storagePath, JSON.stringify(data, null, 2), 'utf8');
    } catch (_err) {
      // Silently ignore write errors
    }
  }

  /**
   * Clear all patterns
   */
  clear() {
    this.patterns.clear();
    this.nextId = 1;

    if (this.config.persistence) {
      this._saveToDisk();
    }
  }

