function optimizationPriority(bottleneck, targetTime) {
  const currentTime = bottleneck.executionTime;
  const percentage = bottleneck.percentage || 0;
  const complexity = bottleneck.complexity || 'medium';

  // Calculate impact (time savings)
  let impact;
  if (percentage >= 20) {
    impact = 'high';
  } else if (percentage >= 10) {
    impact = 'medium';
  } else {
    impact = 'low';
  }

  // Estimate effort based on complexity
  let effort;
  let effortDays;

  if (complexity === 'high') {
    effort = 'high';
    effortDays = 3;
  } else if (complexity === 'medium') {
    effort = 'medium';
    effortDays = 1;
  } else {
    effort = 'low';
    effortDays = 0.25;
  }

  // Calculate impact/effort score (higher is better)
  const impactScore = {
    high: 3,
    medium: 2,
    low: 1,
  }[impact];

  const effortScore = {
    high: 1,
    medium: 2,
    low: 3,
  }[effort];

  const score = impactScore * effortScore;

  return {
    impact,
    effort,
    effortDays,
    score,
    timeSavings: Math.max(0, currentTime - targetTime),
    percentageSavings: percentage,
  };
}

function getProjectRoot() {
  return process.env.PROJECT_ROOT || process.cwd();
}

function validatePathSafety(filePath) {
  // Null/undefined check
  if (!filePath || typeof filePath !== 'string') {
    return { valid: false, reason: 'SEC-PATH-001: Path is null or not a string' };
  }

  // Normalize path
  const normalizedPath = path.normalize(filePath);

  // Check for path traversal patterns
  const dangerousPatterns = [
    /\.\.\//, // Unix path traversal
    /\.\.\\/, // Windows path traversal
    /^~\//, // Home directory reference
    /^\/(?!\.)/, // Absolute Unix path (allow ./ prefix)
    /^[A-Z]:\\/i, // Absolute Windows path
    /\$\{.*\}/, // Template injection
    /%[0-9a-f]{2}/i, // URL encoding in path
    /\0/, // Null byte injection
  ];

  for (const pattern of dangerousPatterns) {
    if (pattern.test(filePath)) {
      return { valid: false, reason: `SEC-PATH-002: Dangerous path pattern detected: ${pattern}` };
    }
  }

  // Verify within project root
  const projectRoot = getProjectRoot();
  const resolvedPath = path.resolve(projectRoot, normalizedPath);

  if (!resolvedPath.startsWith(projectRoot)) {
    return { valid: false, reason: 'SEC-PATH-003: Path resolves outside project root' };
  }

  return { valid: true, reason: 'Path validation passed' };
}

function validatePathContext(filePath, contextName) {
  // First, validate basic path safety
  const safetyCheck = validatePathSafety(filePath);
  if (!safetyCheck.valid) {
    return safetyCheck;
  }

  // Get context allowlist
  const context = PATH_CONTEXTS[contextName];
  if (!context) {
    return { valid: false, reason: `SEC-PATH-004: Unknown path context: ${contextName}` };
  }

  // Normalize path for comparison
  const normalizedPath = path.normalize(filePath).replace(/\\/g, '/');

  // Check against allowed prefixes
  const isAllowed = context.allowedPrefixes.some(
    prefix => normalizedPath.startsWith(prefix) || normalizedPath.startsWith('./' + prefix)
  );

  if (!isAllowed) {
    return {
      valid: false,
      reason: `SEC-PATH-005: Path not in allowed prefixes for ${contextName}. Allowed: ${context.allowedPrefixes.join(', ')}`,
    };
  }

  return { valid: true, reason: `Path valid for context: ${context.description}` };
}

function validateSidecarOwnership(filePath, agentName) {
  const sidecarCheck = validatePathContext(filePath, 'SIDECAR');
  if (!sidecarCheck.valid) {
    return sidecarCheck;
  }

  // Extract agent name from path
  const normalizedPath = path.normalize(filePath).replace(/\\/g, '/');
  const match = normalizedPath.match(/\.claude\/memory\/agents\/([^/]+)/);

  if (!match) {
    return { valid: false, reason: 'SEC-PATH-006: Could not extract agent name from sidecar path' };
  }

  const pathAgentName = match[1];

  if (pathAgentName !== agentName) {
    return {
      valid: false,
      reason: `SEC-PATH-007: Sidecar path agent "${pathAgentName}" does not match current agent "${agentName}"`,
    };
  }

  return { valid: true, reason: 'Sidecar ownership validated' };
}

function findProjectRoot(startDir = __dirname) {
  let dir = startDir;

  // Walk up the directory tree
  while (dir !== path.parse(dir).root) {
    const claudeMdPath = path.join(dir, '.claude', 'CLAUDE.md');
    if (fs.existsSync(claudeMdPath)) {
      return dir;
    }
    dir = path.dirname(dir);
  }

  // Check the root as well
  const rootClaudeMdPath = path.join(dir, '.claude', 'CLAUDE.md');
  if (fs.existsSync(rootClaudeMdPath)) {
    return dir;
  }

  // Fallback to startDir if not found (allows graceful degradation)
  return startDir;
}

function resolveProjectRoot() {
  // Fast path: this file lives under `<project>/.claude/lib/utils/` in this repo.
  // Prefer that deterministic location when the marker exists.
  try {
    const candidate = path.resolve(__dirname, '..', '..', '..');
    const marker = path.join(candidate, '.claude', 'CLAUDE.md');
    if (fs.existsSync(marker)) return candidate;
  } catch {
    // ignore
  }

  // Prefer explicit override when provided by the runtime (many hooks/tools already set this)
  if (process.env.CLAUDE_PROJECT_DIR && typeof process.env.CLAUDE_PROJECT_DIR === 'string') {
    const candidate = process.env.CLAUDE_PROJECT_DIR;
    try {
      const marker = path.join(candidate, '.claude', 'CLAUDE.md');
      if (fs.existsSync(marker)) return candidate;
    } catch {
      // ignore invalid override
    }
  }

  // Prefer current working directory when it looks like the project root.
  // This keeps tests and CLI runs stable even if this file is vendored/shared elsewhere.
  try {
    const cwdMarker = path.join(process.cwd(), '.claude', 'CLAUDE.md');
    if (fs.existsSync(cwdMarker)) return process.cwd();
  } catch {
    // ignore
  }

  // Fallback: find project root relative to this file's location
  return findProjectRoot(__dirname);
}

function validatePathWithinProject(filePath, projectRoot = PROJECT_ROOT) {
  // Reject null/undefined/empty paths (fail-closed)
  if (!filePath || typeof filePath !== 'string') {
    return { safe: false, reason: 'Path is null, undefined, or not a string' };
  }

  if (filePath.trim() === '') {
    return { safe: false, reason: 'Path is empty' };
  }

  // Check for traversal patterns BEFORE resolution
  // This catches encoded attacks before they're decoded
  for (const pattern of PATH_TRAVERSAL_PATTERNS) {
    if (pattern.test(filePath)) {
      return { safe: false, reason: 'Path contains traversal sequence or invalid characters' };
    }
  }

  // Normalize path separators (Windows/Unix compatibility)
  const normalizedInput = filePath.replace(/\\/g, '/');

  // Resolve to absolute path
  const resolvedPath = path.resolve(projectRoot, normalizedInput);
  const normalizedRoot = path.resolve(projectRoot);

  // Ensure resolved path is within project root
  // Use startsWith with separator to prevent prefix attacks
  // e.g., /project-root vs /project-root-evil
  // Windows paths are typically case-insensitive; compare accordingly to avoid false negatives.
  const isWin = process.platform === 'win32';
  const pathWithSep = (resolvedPath + path.sep).replace(/\\/g, '/');
  const rootWithSep = (normalizedRoot + path.sep).replace(/\\/g, '/');
  const pathCmp = isWin ? pathWithSep.toLowerCase() : pathWithSep;
  const rootCmp = isWin ? rootWithSep.toLowerCase() : rootWithSep;
  const resolvedCmp = isWin ? resolvedPath.toLowerCase() : resolvedPath;
  const rootExactCmp = isWin ? normalizedRoot.toLowerCase() : normalizedRoot;

  if (!pathCmp.startsWith(rootCmp) && resolvedCmp !== rootExactCmp) {
    return {
      safe: false,
      reason: 'Path resolves outside project root',
      resolvedPath,
    };
  }

  return { safe: true, resolvedPath };
}

function sanitizePath(filePath, projectRoot = PROJECT_ROOT) {
  const result = validatePathWithinProject(filePath, projectRoot);
  if (!result.safe) {
    throw new Error(`Path validation failed: ${result.reason} (path: ${filePath})`);
  }
  return result.resolvedPath;
}

function generateProfilingReport(metrics, bottlenecks, targets, baseline = null) {
  const sections = [];

  // 1. Executive Summary
  sections.push('# Performance Profiling Report');
  sections.push('');
  sections.push(`Generated: ${new Date().toISOString()}`);
  sections.push('');
  sections.push('## Executive Summary');
  sections.push('');

  if (bottlenecks.length > 0) {
    sections.push('### Top Bottlenecks');
    sections.push('');
    bottlenecks.slice(0, 5).forEach((bottleneck, index) => {
      sections.push(
        `${index + 1}. **${bottleneck.name}** - ${bottleneck.executionTime.toFixed(2)}ms (${bottleneck.percentage}% of total)`
      );
    });
    sections.push('');
  }

  // Recommendations
  sections.push('### Recommendations');
  sections.push('');
  if (bottlenecks.length > 0) {
    const topBottleneck = bottlenecks[0];
    if (topBottleneck.suggestions && topBottleneck.suggestions.length > 0) {
      topBottleneck.suggestions.forEach(suggestion => {
        sections.push(`- ${suggestion}`);
      });
    } else {
      sections.push(
        `- Optimize ${topBottleneck.name} (${topBottleneck.percentage}% of total time)`
      );
    }
  }
  sections.push('');

  // 2. Per-SPEC Performance Breakdown
  if (Object.keys(metrics).length > 0) {
    sections.push('## Per-Component Breakdown');
    sections.push('');
    sections.push('| Component | Execution Time | Memory Used | Call Count |');
    sections.push('|-----------|----------------|-------------|------------|');

    const entries = Object.entries(metrics);
    entries.forEach(([name, data]) => {
      const execTime = (data.executionTime || 0).toFixed(2);
      const memory = data.memoryUsed ? `${(data.memoryUsed / 1024 / 1024).toFixed(2)} MB` : 'N/A';
      const callCount = data.callCount || 1;
      sections.push(`| ${name} | ${execTime}ms | ${memory} | ${callCount} |`);
    });
    sections.push('');
  }

  // 3. Bottleneck Analysis
  if (bottlenecks.length > 0) {
    sections.push('## Bottleneck Analysis');
    sections.push('');

    bottlenecks.forEach(bottleneck => {
      sections.push(`### ${bottleneck.name}`);
      sections.push('');
      sections.push(`- **Execution Time**: ${bottleneck.executionTime.toFixed(2)}ms`);
      sections.push(`- **Percentage of Total**: ${bottleneck.percentage}%`);
      if (bottleneck.callCount) {
        sections.push(`- **Call Count**: ${bottleneck.callCount}`);
      }
      if (bottleneck.memoryUsed) {
        sections.push(`- **Memory Used**: ${(bottleneck.memoryUsed / 1024 / 1024).toFixed(2)} MB`);
      }
      sections.push('');

      if (bottleneck.suggestions && bottleneck.suggestions.length > 0) {
        sections.push('**Optimization Strategies:**');
        sections.push('');
        bottleneck.suggestions.forEach(suggestion => {
          sections.push(`- ${suggestion}`);
        });
        sections.push('');
      }
    });
  }

  // 4. Tier-Based Recommendations
  sections.push('## Tier-Based Recommendations');
  sections.push('');

  if (targets.tier1 && targets.tier1.length > 0) {
    sections.push('### Tier 1: Critical Path (Highest Priority)');
    sections.push('');
    targets.tier1.forEach(target => {
      sections.push(`- **${target.component}**: Target ${target.targetTime}${target.unit}`);
      sections.push(`  - ${target.rationale}`);
    });
    sections.push('');
  }

  if (targets.tier2 && targets.tier2.length > 0) {
    sections.push('### Tier 2: Important (Medium Priority)');
    sections.push('');
    targets.tier2.forEach(target => {
      sections.push(`- **${target.component}**: Target ${target.targetTime}${target.unit}`);
      if (target.rationale) {
        sections.push(`  - ${target.rationale}`);
      }
    });
    sections.push('');
  }

  if (targets.tier3 && targets.tier3.length > 0) {
    sections.push('### Tier 3: Nice-to-Have (Low Priority)');
    sections.push('');
    targets.tier3.forEach(target => {
      sections.push(`- **${target.component}**: Target ${target.targetTime}${target.unit}`);
      if (target.rationale) {
        sections.push(`  - ${target.rationale}`);
      }
    });
    sections.push('');
  }

  // 5. Historical Comparison (if baseline available)
  if (baseline) {
    sections.push('## Historical Comparison');
    sections.push('');
    sections.push('Comparing current metrics against baseline:');
    sections.push('');

    const improvements = [];
    const regressions = [];

    for (const [name, current] of Object.entries(metrics)) {
      if (baseline[name]) {
        const baseTime = baseline[name].executionTime;
        const currentTime = current.executionTime;
        const diff = currentTime - baseTime;
        const percentChange = ((diff / baseTime) * 100).toFixed(1);

        if (diff < 0) {
          improvements.push(`- ${name}: ${Math.abs(percentChange)}% faster`);
        } else if (diff > 0) {
          regressions.push(`- ${name}: ${percentChange}% slower`);
        }
      }
    }

    if (improvements.length > 0) {
      sections.push('**Improvements:**');
      sections.push('');
      improvements.forEach(item => sections.push(item));
      sections.push('');
    }

    if (regressions.length > 0) {
      sections.push('**Regressions:**');
      sections.push('');
      regressions.forEach(item => sections.push(item));
      sections.push('');
    }
  }

  // 6. Estimated Savings
  sections.push('## Estimated Savings');
  sections.push('');

  if (bottlenecks.length > 0) {
    bottlenecks.forEach(bottleneck => {
      if (bottleneck.targetTime !== undefined) {
        const savings = bottleneck.executionTime - bottleneck.targetTime;
        const callCount = bottleneck.callCount || 1;
        const totalSavings = savings * callCount;

        if (savings > 0) {
          sections.push(
            `- **${bottleneck.name}**: ${savings.toFixed(2)}ms per call × ${callCount} calls = ${totalSavings.toFixed(2)}ms total (${bottleneck.percentage}% improvement)`
          );
        }
      }

      if (bottleneck.targetMemory !== undefined && bottleneck.memoryUsed) {
        const memorySavings = bottleneck.memoryUsed - bottleneck.targetMemory;
        if (memorySavings > 0) {
          sections.push(
            `- **${bottleneck.name}**: ${(memorySavings / 1024 / 1024).toFixed(2)} MB memory reduction`
          );
        }
      }
    });
    sections.push('');
  }

  return sections.join('\n');
}

function safeParseJSON(content, schemaName) {
  // If no schema, do simple parse with fallback
  if (!schemaName || !SCHEMAS[schemaName]) {
    try {
      return JSON.parse(content);
    } catch (_e) {
      return {};
    }
  }

  const schema = SCHEMAS[schemaName];

  // Try to parse JSON
  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (_e) {
    // Return defaults on parse error
    return { ...schema.defaults };
  }

  // Create validated object starting with defaults
  // Use Object.create(null) to create object without prototype
  const validated = Object.create(null);

  // Copy defaults first
  for (const key of Object.keys(schema.defaults)) {
    validated[key] = schema.defaults[key];
  }

  // Only copy known properties from parsed data
  // This strips unknown/malicious properties like __proto__, constructor, etc.
  if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
    for (const key of Object.keys(schema.defaults)) {
      if (Object.prototype.hasOwnProperty.call(parsed, key)) {
        // SEC-AUDIT-006 FIX: Deep copy for all nested objects to prevent reference issues
        // Use JSON.parse(JSON.stringify()) for complete deep copy
        const value = parsed[key];
        if (value === null || value === undefined) {
          validated[key] = value;
        } else if (Array.isArray(value)) {
          // Deep copy arrays with all nested content
          try {
            validated[key] = JSON.parse(JSON.stringify(value));
          } catch (_e) {
            // If deep copy fails, use default
            validated[key] = schema.defaults[key];
          }
        } else if (typeof value === 'object') {
          // Deep copy nested objects
          try {
            validated[key] = JSON.parse(JSON.stringify(value));
          } catch (_e) {
            // If deep copy fails, use default
            validated[key] = schema.defaults[key];
          }
        } else {
          // Primitives can be assigned directly
          validated[key] = value;
        }
      }
    }
  }

  // Convert back to regular object for compatibility
  return Object.assign({}, validated);
}

function safeReadJSON(filePath, schemaName) {
  // Check if file exists
  if (!fs.existsSync(filePath)) {
    // Return defaults if schema exists, empty object otherwise
    if (schemaName && SCHEMAS[schemaName]) {
      return { ...SCHEMAS[schemaName].defaults };
    }
    return {};
  }

  // Try to read file
  let content;
  try {
    content = fs.readFileSync(filePath, 'utf-8');
  } catch (_e) {
    // Return defaults on read error
    if (schemaName && SCHEMAS[schemaName]) {
      return { ...SCHEMAS[schemaName].defaults };
    }
    return {};
  }

  // Empty file returns defaults
  if (!content || content.trim() === '') {
    if (schemaName && SCHEMAS[schemaName]) {
      return { ...SCHEMAS[schemaName].defaults };
    }
    return {};
  }

  // Parse with schema validation
  return safeParseJSON(content, schemaName);
}

async function detect(projectPath) {
  const result = {
    languages: [],
    frameworks: [],
    package_managers: [],
    build_tools: [],
    testing: [],
    ci_cd: [],
    confidence: 0,
  };

  if (!fs.existsSync(projectPath)) {
    return result;
  }

  const signals = {
    packageJson: 0,
    pyprojectToml: 0,
    requirementsTxt: 0,
    goMod: 0,
    cargoToml: 0,
    tsconfigJson: 0,
    githubActions: 0,
  };

  // Check package.json (Node.js/TypeScript)
  const packageJsonPath = path.join(projectPath, 'package.json');
  if (fs.existsSync(packageJsonPath)) {
    signals.packageJson = 1;
    try {
      const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
      const allDeps = {
        ...pkg.dependencies,
        ...pkg.devDependencies,
      };

      // Detect TypeScript
      if (allDeps['typescript']) {
        result.languages.push('typescript');
      } else {
        result.languages.push('javascript');
      }

      result.package_managers.push('npm');

      // Detect frameworks
      for (const [framework, patterns] of Object.entries(FRAMEWORK_PATTERNS)) {
        if (patterns.some(p => allDeps[p])) {
          result.frameworks.push(framework);
        }
      }

      // Detect testing frameworks
      for (const [testFramework, patterns] of Object.entries(TEST_PATTERNS)) {
        if (patterns.some(p => allDeps[p])) {
          result.testing.push(testFramework);
        }
      }
    } catch (_err) {
      // Invalid JSON - continue
    }
  }

  // Check pyproject.toml (Python with Poetry)
  const pyprojectPath = path.join(projectPath, 'pyproject.toml');
  if (fs.existsSync(pyprojectPath)) {
    signals.pyprojectToml = 1;
    result.languages.push('python');
    result.package_managers.push('poetry');

    const content = fs.readFileSync(pyprojectPath, 'utf8');

    // Detect frameworks from pyproject.toml
    if (content.includes('fastapi')) result.frameworks.push('fastapi');
    if (content.includes('django')) result.frameworks.push('django');
    if (content.includes('flask')) result.frameworks.push('flask');

    // Detect testing
    if (content.includes('pytest')) result.testing.push('pytest');
  }

  // Check requirements.txt (Python with pip)
  const requirementsPath = path.join(projectPath, 'requirements.txt');
  if (fs.existsSync(requirementsPath)) {
    signals.requirementsTxt = 1;
    if (!result.languages.includes('python')) {
      result.languages.push('python');
    }
    result.package_managers.push('pip');

    const content = fs.readFileSync(requirementsPath, 'utf8');

    // Detect frameworks
    if (content.includes('django')) result.frameworks.push('django');
    if (content.includes('fastapi')) result.frameworks.push('fastapi');
    if (content.includes('flask')) result.frameworks.push('flask');

    // Detect testing
    if (content.includes('pytest')) result.testing.push('pytest');
  }

  // Check go.mod (Go)
  const goModPath = path.join(projectPath, 'go.mod');
  if (fs.existsSync(goModPath)) {
    signals.goMod = 1;
    result.languages.push('go');
    result.package_managers.push('go-modules');

    const content = fs.readFileSync(goModPath, 'utf8');

    // Detect frameworks
    if (content.includes('github.com/gin-gonic/gin')) result.frameworks.push('gin');
    if (content.includes('github.com/labstack/echo')) result.frameworks.push('echo');
  }

  // Check tsconfig.json (TypeScript without package.json)
  const tsconfigPath = path.join(projectPath, 'tsconfig.json');
  if (fs.existsSync(tsconfigPath) && !result.languages.includes('typescript')) {
    signals.tsconfigJson = 1;
    result.languages.push('typescript');
  }

  // Check GitHub Actions
  const githubWorkflowsPath = path.join(projectPath, '.github/workflows');
  if (fs.existsSync(githubWorkflowsPath)) {
    const workflows = fs
      .readdirSync(githubWorkflowsPath)
      .filter(f => f.endsWith('.yml') || f.endsWith('.yaml'));
    if (workflows.length > 0) {
      signals.githubActions = 1;
      result.ci_cd.push('github-actions');
    }
  }

  // Calculate confidence score
  const totalSignals = Object.values(signals).reduce((sum, val) => sum + val, 0);
  const maxSignals = Object.keys(signals).length;

  // Base confidence on signal strength
  if (signals.packageJson || signals.pyprojectToml || signals.goMod) {
    // Strong signal (package manager file)
    result.confidence = 0.9 + (totalSignals / maxSignals) * 0.1;
  } else if (totalSignals > 0) {
    // Medium signal (config files only)
    result.confidence = 0.5 + (totalSignals / maxSignals) * 0.3;
  } else {
    result.confidence = 0;
  }

  // Deduplicate arrays
  result.languages = [...new Set(result.languages)];
  result.frameworks = [...new Set(result.frameworks)];
  result.testing = [...new Set(result.testing)];

  return result;
}

async function detectLanguage(projectPath) {
  const result = await detect(projectPath);
  return result.languages[0] || null;
}

class AdapterRegistry {
  constructor() {
    this.adapters = new Map();
    this.factories = new Map();
  }

  /**
   * Register an adapter instance
   * @param {string} system - System name
   * @param {string} version - System version
   * @param {Object} adapter - Adapter instance
   */
  register(system, version, adapter) {
    const key = this._makeKey(system, version);
    this.adapters.set(key, adapter);
  }

  /**
   * Register a factory function for lazy loading
   * @param {string} system - System name
   * @param {string} version - System version
   * @param {Function} factory - Factory function
   */
  registerFactory(system, version, factory) {
    const key = this._makeKey(system, version);
    this.factories.set(key, factory);
  }

  /**
   * Get adapter by system and version
   * @param {string} system - System name
   * @param {string} version - System version
   * @param {Object} options - Options
   * @param {boolean} options.fallbackToCompatible - Fallback to compatible version
   * @returns {Object|null} Adapter instance or null
   */
  get(system, version, options = {}) {
    const key = this._makeKey(system, version);

    // Try exact match
    if (this.adapters.has(key)) {
      return this.adapters.get(key);
    }

    // Try fallback to compatible version
    if (options.fallbackToCompatible) {
      const compatible = this._findCompatibleAdapter(system, version);
      if (compatible) {
        return compatible;
      }
    }

    return null;
  }

  /**
   * Load adapter (from factory if needed)
   * @param {string} system - System name
   * @param {string} version - System version
   * @returns {Promise<Object>} Adapter instance
   */
  async load(system, version) {
    const key = this._makeKey(system, version);

    // Check if already loaded
    if (this.adapters.has(key)) {
      return this.adapters.get(key);
    }

    // Load from factory
    if (this.factories.has(key)) {
      const factory = this.factories.get(key);
      const adapter = factory();
      this.adapters.set(key, adapter);
      return adapter;
    }

    throw new Error(`Adapter not found: ${system}@${version}`);
  }

  /**
   * Deregister an adapter
   * @param {string} system - System name
   * @param {string} version - System version
   */
  deregister(system, version) {
    const key = this._makeKey(system, version);
    this.adapters.delete(key);
    this.factories.delete(key);
  }

  /**
   * Find compatible adapter (same major version)
   * @private
   */
  _findCompatibleAdapter(system, version) {
    const requestedMajor = this._parseMajor(version);

    for (const [key, adapter] of this.adapters.entries()) {
      const [sys, ver] = key.split('@');
      if (sys === system) {
        const major = this._parseMajor(ver);
        if (major === requestedMajor) {
          return adapter;
        }
      }
    }

    return null;
  }

  /**
   * Parse major version from semver
   * @private
   */
  _parseMajor(version) {
    const match = version.match(/^(\d+)\./);
    return match ? parseInt(match[1], 10) : 0;
  }

  /**
   * Make registry key
   * @private
   */
  _makeKey(system, version) {
    return `${system}@${version}`;
  }

class ConditionalExecutor {
  async when(condition, thenBranch, elseBranch = null, context = null, options = {}) {
    const { evaluator = 'javascript' } = options;

    let conditionResult;

    if (typeof condition === 'function') {
      conditionResult = await condition(context);
    } else if (typeof condition === 'string') {
      conditionResult = this._evaluateExpression(condition, evaluator, context);
    } else {
      conditionResult = condition;
    }

    if (conditionResult) {
      return await thenBranch(context);
    } else if (elseBranch) {
      return await elseBranch(context);
    }
    return null;
  }

  _evaluateExpression(expression, evaluator, context) {
    if (evaluator === 'javascript') {
      return this._evaluateJavaScript(expression, context);
    } else if (evaluator === 'jsonpath') {
      return this._evaluateJsonPath(expression, context);
    } else if (evaluator === 'simple') {
      return this._evaluateSimple(expression, context);
    }
    throw new Error(`Unknown evaluator: ${evaluator}`);
  }

  _evaluateJavaScript(expression, context) {
    // Sandbox evaluation for security
    try {
      const ctx = context || {};
      // Inject context as 'ctx' variable for safer evaluation
      const keys = ['ctx', ...Object.keys(ctx)];
      const values = [ctx, ...Object.values(ctx)];
      // eslint-disable-next-line no-new-func -- Intentional dynamic evaluation for expression support
      const fn = new Function(...keys, `return ${expression}`);
      return fn(...values);
    } catch (error) {
      throw new Error(`Cannot read property on undefined: ${error.message}`);
    }
  }

  _evaluateJsonPath(expression, context) {
    // Simple JSONPath support ($.path.to.property)
    if (!expression.startsWith('$.')) {
      return false;
    }

    const path = expression.slice(2).split('.');
    let value = context;

    for (const key of path) {
      if (value == null) {
        return false;
      }
      value = value[key];
    }

    return !!value;
  }

  _evaluateSimple(expression, context) {
    // Simple comparison: "count > 10" style
    const match = expression.match(/^(\w+)\s*(>|<|>=|<=|===|==|!=)\s*(.+)$/);
    if (!match) {
      return false;
    }

    const [, left, operator, right] = match;
    const leftValue = context[left];
    let rightValue = right;

    // Parse right value
    if (right === 'true') rightValue = true;
    else if (right === 'false') rightValue = false;
    else if (!isNaN(right)) rightValue = Number(right);

    switch (operator) {
      case '>':
        return leftValue > rightValue;
      case '<':
        return leftValue < rightValue;
      case '>=':
        return leftValue >= rightValue;
      case '<=':
        return leftValue <= rightValue;
      case '===':
        return leftValue === rightValue;
      case '==':
        // eslint-disable-next-line eqeqeq -- Intentional loose equality for simple evaluator
        return leftValue == rightValue;
      case '!=':
        // eslint-disable-next-line eqeqeq -- Intentional loose inequality for simple evaluator
        return leftValue != rightValue;
      default:
        return false;
    }
  }

  async switch(value, cases, defaultCase = null) {
    const caseFunction = cases[value];

    if (caseFunction) {
      return await caseFunction();
    } else if (defaultCase) {
      return await defaultCase();
    }

    return null;
  }

  async chain(conditions, defaultBranch, context = null) {
    for (const { condition, branch } of conditions) {
      let result;

      if (typeof condition === 'function') {
        result = await condition(context);
      } else {
        result = condition;
      }

      if (result) {
        return await branch(context);
      }
    }

    return await defaultBranch(context);
  }

class CrossWorkflowTrigger {
  /**
   * Create a new CrossWorkflowTrigger
   *
   * @param {Object} workflowEngine - Workflow engine instance
   * @param {Object} options - Configuration options
   * @param {number} options.maxChainDepth - Max trigger chain depth
   * @param {number} options.defaultTimeout - Default timeout for sync triggers
   */
  constructor(workflowEngine, options = {}) {
    this.engine = workflowEngine;
    this.options = {
      maxChainDepth: options.maxChainDepth || MAX_CHAIN_DEPTH,
      defaultTimeout: options.defaultTimeout || DEFAULT_TIMEOUT,
    };

    // Trigger history
    this.history = [];

    // Registered trigger handlers
    this.handlers = new Map();

    // Active trigger chain (for circular detection)
    this._activeChain = [];

    // Pending async triggers
    this._pendingTriggers = new Map();
  }

  /**
   * Trigger a workflow from another workflow
   *
   * @param {string} fromWorkflow - Source workflow ID
   * @param {string} toWorkflow - Target workflow ID
   * @param {Object} context - Context to pass to target workflow
   * @param {Object} options - Trigger options
   * @param {boolean} options.sync - If true, wait for result (default: true)
   * @param {number} options.timeout - Timeout for sync triggers
   * @returns {Promise<Object>} Result or pending status
   */
  async trigger(fromWorkflow, toWorkflow, context = {}, options = {}) {
    const { sync = true, timeout = this.options.defaultTimeout } = options;

    // Check for circular triggers
    if (this.detectCircularTrigger(this._activeChain, toWorkflow)) {
      throw new Error(
        `Circular trigger detected: ${[...this._activeChain, toWorkflow].join(' -> ')}`
      );
    }

    // Check chain depth
    if (this._activeChain.length >= this.options.maxChainDepth) {
      throw new Error(`Trigger chain depth exceeded (max: ${this.options.maxChainDepth})`);
    }

    // Create trigger record
    const triggerId = this._generateTriggerId();
    const triggerRecord = {
      id: triggerId,
      fromWorkflow,
      toWorkflow,
      context,
      timestamp: Date.now(),
      sync,
      status: 'pending',
    };

    // Add to history
    this.history.push(triggerRecord);

    if (sync) {
      // Synchronous trigger - wait for result
      return this._executeSyncTrigger(triggerRecord, timeout);
    } else {
      // Asynchronous trigger - fire and forget
      return this._executeAsyncTrigger(triggerRecord);
    }
  }

  /**
   * Trigger multiple workflows in parallel
   *
   * @param {string} fromWorkflow - Source workflow ID
   * @param {Array<{workflowId: string, context: Object}>} targets - Target workflows
   * @param {Object} context - Shared context (merged with individual contexts)
   * @returns {Promise<Array<{workflowId: string, status: string, result?: Object, error?: string}>>}
   */
  async triggerMultiple(fromWorkflow, targets, sharedContext = {}) {
    const promises = targets.map(async target => {
      const mergedContext = { ...sharedContext, ...target.context };

      try {
        const result = await this.trigger(fromWorkflow, target.workflowId, mergedContext, {
          sync: true,
        });
        return {
          workflowId: target.workflowId,
          status: 'success',
          result,
        };
      } catch (e) {
        return {
          workflowId: target.workflowId,
          status: 'error',
          error: e.message,
        };
      }
    });

    return Promise.all(promises);
  }

  /**
   * Register a handler for workflow triggers
   *
   * @param {string} workflowId - Workflow ID to handle
   * @param {Function} handler - Handler function (context) => result
   */
  registerTriggerHandler(workflowId, handler) {
    if (typeof handler !== 'function') {
      throw new Error('Handler must be a function');
    }
    this.handlers.set(workflowId, handler);
  }

  /**
   * Get trigger history, optionally filtered by workflow
   *
   * @param {string} [workflowId] - Filter by source workflow ID
   * @returns {Array} Trigger history
   */
  getTriggerHistory(workflowId = null) {
    if (workflowId) {
      return this.history.filter(h => h.fromWorkflow === workflowId);
    }
    return [...this.history];
  }

  /**
   * Detect if adding a workflow would create a circular trigger
   *
   * @param {string[]} chain - Current trigger chain
   * @param {string} nextWorkflow - Workflow to add
   * @returns {boolean} True if circular
   */
  detectCircularTrigger(chain, nextWorkflow) {
    return chain.includes(nextWorkflow);
  }

  /**
   * Execute a synchronous trigger
   * @private
   */
  async _executeSyncTrigger(triggerRecord, timeout) {
    const { toWorkflow, context } = triggerRecord;

    // Add to active chain
    this._activeChain.push(toWorkflow);

    try {
      // Create timeout promise
      const timeoutPromise = new Promise((_, reject) => {
        setTimeout(() => reject(new Error(`Trigger timeout after ${timeout}ms`)), timeout);
      });

      // Execute workflow
      const executionPromise = this._executeWorkflow(toWorkflow, context);

      // Race between execution and timeout
      const result = await Promise.race([executionPromise, timeoutPromise]);

      // Update record
      triggerRecord.status = 'completed';
      triggerRecord.result = result;

      return result;
    } catch (e) {
      triggerRecord.status = 'error';
      triggerRecord.error = e.message;
      throw e;
    } finally {
      // Remove from active chain
      const index = this._activeChain.indexOf(toWorkflow);
      if (index !== -1) {
        this._activeChain.splice(index, 1);
      }
    }
  }

  /**
   * Execute an asynchronous trigger (fire-and-forget)
   * @private
   */
  async _executeAsyncTrigger(triggerRecord) {
    const { id, toWorkflow, context } = triggerRecord;

    // Store pending trigger
    this._pendingTriggers.set(id, triggerRecord);

    // Execute in background
    this._executeWorkflow(toWorkflow, context)
      .then(result => {
        triggerRecord.status = 'completed';
        triggerRecord.result = result;
      })
      .catch(e => {
        triggerRecord.status = 'error';
        triggerRecord.error = e.message;
      })
      .finally(() => {
        this._pendingTriggers.delete(id);
      });

    // Return immediately with pending status
    return {
      triggerId: id,
      status: 'pending',
      fromWorkflow: triggerRecord.fromWorkflow,
      toWorkflow: triggerRecord.toWorkflow,
    };
  }

  /**
   * Execute a workflow through the engine
   * @private
   */
  async _executeWorkflow(workflowId, context) {
    if (this.engine && typeof this.engine.executeWorkflow === 'function') {
      return this.engine.executeWorkflow(workflowId, context);
    }

    // Fallback: check for registered handler
    if (this.handlers.has(workflowId)) {
      const handler = this.handlers.get(workflowId);
      return handler(context);
    }

    throw new Error(`Workflow not found: ${workflowId}`);
  }

  /**
   * Invoke a registered handler
   * @private
   */
  _invokeHandler(workflowId, context) {
    if (!this.handlers.has(workflowId)) {
      throw new Error(`Handler not found: ${workflowId}`);
    }
    return this.handlers.get(workflowId)(context);
  }

  /**
   * Generate a unique trigger ID
   * @private
   */
  _generateTriggerId() {
    return `trigger-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;
  }

  /**
   * Get pending triggers
   *
   * @returns {Array} Pending trigger records
   */
  getPendingTriggers() {
    return Array.from(this._pendingTriggers.values());
  }

  /**
   * Check if a trigger is still pending
   *
   * @param {string} triggerId - Trigger ID
   * @returns {boolean}
   */
  isPending(triggerId) {
    return this._pendingTriggers.has(triggerId);
  }

  /**
   * Clear trigger history
   */
  clearHistory() {
    this.history = [];
  }

function createCheckpointId() {
  const timestamp = Date.now();
  const random = Math.random().toString(36).substring(2, 8);
  return `chk-${timestamp}-${random}`;
}

function compressState(state) {
  const json = JSON.stringify(state);
  const buffer = Buffer.from(json, 'utf-8');
  return zlib.gzipSync(buffer);
}

function decompressState(compressed) {
  const buffer = zlib.gunzipSync(compressed);
  const json = buffer.toString('utf-8');
  return JSON.parse(json);
}

class MemoryStorage {
  constructor() {
    this.data = new Map();
  }

  async save(id, checkpoint) {
    this.data.set(id, checkpoint);
  }

  async load(id) {
    return this.data.get(id) || null;
  }

  async delete(id) {
    this.data.delete(id);
  }

  async list() {
    return Array.from(this.data.values());
  }

class FileStorage {
  constructor(checkpointDir) {
    this.checkpointDir = checkpointDir;
  }

  /**
   * Ensure checkpoint directory exists
   */
  ensureDir() {
    if (!fs.existsSync(this.checkpointDir)) {
      fs.mkdirSync(this.checkpointDir, { recursive: true });
    }
  }

  /**
   * Get file path for a checkpoint ID
   */
  getFilePath(id) {
    return path.join(this.checkpointDir, `${id}.json.gz`);
  }

  async save(id, checkpoint) {
    this.ensureDir();
    const filePath = this.getFilePath(id);
    const compressed = compressState(checkpoint);
    await fs.promises.writeFile(filePath, compressed);
  }

  async load(id) {
    const filePath = this.getFilePath(id);
    if (!fs.existsSync(filePath)) {
      return null;
    }
    const compressed = await fs.promises.readFile(filePath);
    return decompressState(compressed);
  }

  async delete(id) {
    const filePath = this.getFilePath(id);
    if (fs.existsSync(filePath)) {
      await fs.promises.unlink(filePath);
    }
  }

  async list() {
    this.ensureDir();
    const files = await fs.promises.readdir(this.checkpointDir);
    const checkpoints = [];

    for (const file of files) {
      if (file.endsWith('.json.gz')) {
        const id = file.replace('.json.gz', '');
        try {
          const checkpoint = await this.load(id);
          if (checkpoint) {
            checkpoints.push(checkpoint);
          }
        } catch (_e) {
          // Skip corrupted files
          console.warn(`[checkpoint-manager] Skipping corrupted checkpoint: ${file}`);
        }
      }
    }

    return checkpoints;
  }

class CheckpointManager {
  /**
   * Create a new CheckpointManager
   *
   * @param {Object} options - Configuration options
   * @param {string} options.checkpointDir - Directory for file storage
   * @param {string} options.storage - Storage type: 'file' or 'memory'
   * @param {number} options.maxAge - Max age for checkpoints in ms (default: 7 days)
   * @param {number} options.maxCount - Max checkpoints per workflow (default: 10)
   */
  constructor(options = {}) {
    this.options = {
      checkpointDir: options.checkpointDir || DEFAULT_CHECKPOINT_DIR,
      storage: options.storage || 'file',
      maxAge: options.maxAge || DEFAULT_MAX_AGE,
      maxCount: options.maxCount || DEFAULT_MAX_COUNT,
    };

    // Initialize storage backend
    if (this.options.storage === 'memory') {
      this.storage = new MemoryStorage();
    } else {
      this.storage = new FileStorage(this.options.checkpointDir);
    }
  }

  /**
   * Save a checkpoint
   *
   * @param {string} workflowId - Workflow identifier
   * @param {Object} state - Workflow state to save
   * @returns {string} Checkpoint ID
   */
  async save(workflowId, state) {
    const id = createCheckpointId();
    const checkpoint = {
      id,
      workflowName: workflowId,
      workflowVersion: state.workflowVersion || '1.0.0',
      createdAt: new Date().toISOString(),
      phase: state.phase,
      stepIndex: state.stepIndex,
      context: state.context || {},
      stepResults: state.stepResults || {},
      metadata: state.metadata || {},
    };

    await this.storage.save(id, checkpoint);
    return id;
  }

  /**
   * Load a specific checkpoint
   *
   * @param {string} checkpointId - Checkpoint ID to load
   * @returns {Object} Checkpoint data
   * @throws {Error} If checkpoint not found
   */
  async load(checkpointId) {
    const checkpoint = await this.storage.load(checkpointId);
    if (!checkpoint) {
      throw new Error(`Checkpoint not found: ${checkpointId}`);
    }
    return checkpoint;
  }

  /**
   * Load the most recent checkpoint for a workflow
   *
   * @param {string} workflowId - Workflow identifier
   * @returns {Object|null} Latest checkpoint or null if none exist
   */
  async loadLatest(workflowId) {
    const checkpoints = await this.list(workflowId);
    if (checkpoints.length === 0) {
      return null;
    }
    return checkpoints[0]; // Already sorted newest first
  }

  /**
   * List all checkpoints for a workflow
   *
   * @param {string} workflowId - Workflow identifier
   * @returns {Array} List of checkpoints sorted by creation time (newest first)
   */
  async list(workflowId) {
    const allCheckpoints = await this.storage.list();
    const filtered = allCheckpoints.filter(c => c.workflowName === workflowId);

    // Sort by creation time, newest first
    filtered.sort((a, b) => {
      const timeA = new Date(a.createdAt).getTime();
      const timeB = new Date(b.createdAt).getTime();
      return timeB - timeA;
    });

    return filtered;
  }

  /**
   * Delete a specific checkpoint
   *
   * @param {string} checkpointId - Checkpoint ID to delete
   */
  async delete(checkpointId) {
    await this.storage.delete(checkpointId);
  }

  /**
   * Cleanup old checkpoints
   *
   * @param {number} maxAge - Max age in ms (default: from options)
   * @param {number} maxCount - Max count per workflow (default: from options)
   * @returns {Object} Cleanup results
   */
  async cleanup(maxAge = this.options.maxAge, maxCount = this.options.maxCount) {
    const results = {
      deletedByAge: 0,
      deletedByCount: 0,
    };

    const now = Date.now();
    const allCheckpoints = await this.storage.list();

    // Delete by age
    for (const checkpoint of allCheckpoints) {
      const createdAt = new Date(checkpoint.createdAt).getTime();
      if (now - createdAt > maxAge) {
        await this.storage.delete(checkpoint.id);
        results.deletedByAge++;
      }
    }

    // Group by workflow and delete oldest exceeding maxCount
    const byWorkflow = new Map();
    const remainingCheckpoints = await this.storage.list();

    for (const checkpoint of remainingCheckpoints) {
      const wfId = checkpoint.workflowName;
      if (!byWorkflow.has(wfId)) {
        byWorkflow.set(wfId, []);
      }
      byWorkflow.get(wfId).push(checkpoint);
    }

    for (const [, checkpoints] of byWorkflow) {
      // Sort newest first
      checkpoints.sort((a, b) => {
        const timeA = new Date(a.createdAt).getTime();
        const timeB = new Date(b.createdAt).getTime();
        return timeB - timeA;
      });

      // Delete oldest exceeding count
      if (checkpoints.length > maxCount) {
        const toDelete = checkpoints.slice(maxCount);
        for (const checkpoint of toDelete) {
          await this.storage.delete(checkpoint.id);
          results.deletedByCount++;
        }
      }
    }

    return results;
  }

  /**
   * Check if a checkpoint can be resumed
   *
   * @param {string} checkpointId - Checkpoint ID to check
   * @returns {boolean} True if checkpoint exists and is valid
   */
  async canResume(checkpointId) {
    try {
      const checkpoint = await this.storage.load(checkpointId);
      return checkpoint !== null && checkpoint.phase !== undefined;
    } catch (_e) {
      return false;
    }
  }

  /**
   * Get the resume point from a checkpoint
   *
   * @param {Object} checkpoint - Checkpoint object
   * @returns {Object} Resume point with phase and stepIndex
   */
  getResumePoint(checkpoint) {
    return {
      phase: checkpoint.phase,
      stepIndex: checkpoint.stepIndex,
    };
  }

function getStepNumber(workflowId, stepId) {
  const match = stepId.match(/(\d+)/);
  if (match) {
    return parseInt(match[1], 10);
  }
  const currentCount = workflowStepCounters.get(workflowId) || 0;
  const nextCount = currentCount + 1;
  workflowStepCounters.set(workflowId, nextCount);

  // Memory safety: enforce max size with LRU eviction
  if (workflowStepCounters.size > MAX_WORKFLOW_COUNTERS) {
    // Evict oldest entry (first key in Map, since Map preserves insertion order)
    const firstKey = workflowStepCounters.keys().next().value;
    workflowStepCounters.delete(firstKey);
    console.warn(
      `[CheckpointManager] Evicted workflow counter for ${firstKey} (size: ${workflowStepCounters.size})`
    );
  }

  return nextCount;
}

function getNextStepId(stepId) {
  const match = stepId.match(/^(.*?)(\d+)$/);
  if (match) {
    const prefix = match[1];
    const number = parseInt(match[2], 10);
    return `${prefix}${number + 1}`;
  }
  return 'next-step';
}

function generateChecksum(data) {
  const crypto = require('crypto');
  return crypto.createHash('sha256').update(JSON.stringify(data)).digest('hex');
}

async function save(arg1, arg2, arg3, arg4) {
  let workflowId, stepId, state, checkpointDir;

  // Handle object-style call: save({ workflowId, stepId, state }, checkpointDir)
  if (typeof arg1 === 'object' && arg1 !== null && arg1.workflowId) {
    workflowId = arg1.workflowId;
    stepId = arg1.stepId;
    state = arg1.state;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  } else {
    // Handle positional call: save(workflowId, stepId, state, checkpointDir)
    workflowId = arg1;
    stepId = arg2;
    state = arg3;
    checkpointDir = arg4 || SPEC003_CHECKPOINT_DIR;
  }

  await fs.promises.mkdir(checkpointDir, { recursive: true });

  const timestamp = new Date().toISOString();
  const stepNumber = getStepNumber(workflowId, stepId);

  const checkpoint = {
    workflowId,
    stepId,
    stepNumber,
    state,
    timestamp,
    checksum: generateChecksum(state),
  };

  const checkpointPath = path.join(checkpointDir, `${workflowId}.json`);
  await fs.promises.writeFile(checkpointPath, JSON.stringify(checkpoint, null, 2), 'utf8');
}

async function load(arg1, arg2) {
  let workflowId, checkpointDir;
  if (typeof arg1 === 'object' && arg1 !== null && arg1.workflowId) {
    workflowId = arg1.workflowId;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  } else {
    workflowId = arg1;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  }
  const checkpointPath = path.join(checkpointDir, `${workflowId}.json`);

  try {
    const content = await fs.promises.readFile(checkpointPath, 'utf8');
    return JSON.parse(content);
  } catch (err) {
    if (err.code === 'ENOENT') {
      return null;
    }
    throw err;
  }
}

async function exists(arg1, arg2) {
  let workflowId, checkpointDir;
  if (typeof arg1 === 'object' && arg1 !== null && arg1.workflowId) {
    workflowId = arg1.workflowId;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  } else {
    workflowId = arg1;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  }
  const checkpointPath = path.join(checkpointDir, `${workflowId}.json`);

  try {
    await fs.promises.access(checkpointPath);
    return true;
  } catch (_err) {
    return false;
  }
}

async function verify(arg1, arg2) {
  let workflowId, checkpointDir;
  if (typeof arg1 === 'object' && arg1 !== null && arg1.workflowId) {
    workflowId = arg1.workflowId;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  } else {
    workflowId = arg1;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  }
  const checkpoint = await load(workflowId, checkpointDir);

  if (!checkpoint) {
    return false;
  }

  const expectedChecksum = generateChecksum(checkpoint.state);
  return checkpoint.checksum === expectedChecksum;
}

async function clear(arg1, arg2) {
  let workflowId, checkpointDir;
  if (typeof arg1 === 'object' && arg1 !== null && arg1.workflowId) {
    workflowId = arg1.workflowId;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  } else {
    workflowId = arg1;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  }
  const checkpointPath = path.join(checkpointDir, `${workflowId}.json`);

  try {
    await fs.promises.unlink(checkpointPath);
    workflowStepCounters.delete(workflowId);
  } catch (err) {
    if (err.code !== 'ENOENT') {
      throw err;
    }
  }
}

async function recover(arg1, arg2) {
  let workflowId, checkpointDir;
  if (typeof arg1 === 'object' && arg1 !== null && arg1.workflowId) {
    workflowId = arg1.workflowId;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  } else {
    workflowId = arg1;
    checkpointDir = arg2 || SPEC003_CHECKPOINT_DIR;
  }
  const checkpoint = await load(workflowId, checkpointDir);

  if (!checkpoint) {
    return null;
  }

  const isValid = await verify(workflowId, checkpointDir);

  if (!isValid) {
    throw new Error(`Checkpoint for workflow ${workflowId} is corrupted. Cannot recover.`);
  }

  const nextStep = getNextStepId(checkpoint.stepId);

  return {
    workflowId: checkpoint.workflowId,
    stepId: checkpoint.stepId,
    stepNumber: checkpoint.stepNumber,
    state: checkpoint.state,
    timestamp: checkpoint.timestamp,
    nextStep,
    recovered: true,
  };
}

class DeploymentManager {
  constructor() {
    this.deployments = new Map(); // workflowId -> deploymentState
    this.mockHealth = new Map(); // workflowId -> { blue, green } health status
    this.rollbackHistory = new Map(); // workflowId -> rollback[] array
  }

  /**
   * Deploy new version alongside current (blue-green)
   * @param {string} workflowId - Workflow identifier
   * @param {string} newVersion - Green version
   * @param {object} options - Deployment options
   */
  async deploy(workflowId, newVersion, options = {}) {
    const {
      startPercentage = 0,
      autoMigrate = false,
      monitorHealth = false,
      healthCheckInterval = 5000,
      autoRollback = false,
      states = [],
    } = options;

    // Get current active version (blue)
    const blueVersion = this.deployments.has(workflowId)
      ? this.deployments.get(workflowId).blue.version
      : '1.0.0';

    // Set up deployment state
    this.deployments.set(workflowId, {
      blue: { version: blueVersion },
      green: { version: newVersion },
      greenPercentage: startPercentage,
      autoRollback,
    });

    // Auto-migrate states if requested
    if (autoMigrate && states.length > 0) {
      for (const state of states) {
        state.workflowVersion = newVersion;
      }
    }

    // Start health monitoring if requested (autoRollback implies monitorHealth)
    if (autoRollback || monitorHealth) {
      this._startHealthMonitoring(workflowId, healthCheckInterval);
    }
  }

  /**
   * Get deployment state
   * @param {string} workflowId - Workflow identifier
   * @returns {object} Deployment state
   */
  getDeploymentState(workflowId) {
    return this.deployments.get(workflowId);
  }

  /**
   * Select version for request (based on traffic percentage)
   * @param {string} workflowId - Workflow identifier
   * @returns {object} Selected version { version }
   */
  selectVersion(workflowId) {
    const deployment = this.deployments.get(workflowId);
    if (!deployment) {
      return { version: '1.0.0' }; // Default
    }

    // Random selection based on percentage
    const random = Math.random() * 100;
    if (random < deployment.greenPercentage) {
      return deployment.green;
    } else {
      return deployment.blue;
    }
  }

  /**
   * Set traffic routing percentage
   * @param {string} workflowId - Workflow identifier
   * @param {object} options - { greenPercentage }
   */
  async setTraffic(workflowId, options) {
    const { greenPercentage } = options;

    if (greenPercentage < 0 || greenPercentage > 100) {
      throw new Error('Invalid percentage: must be 0-100');
    }

    // Create deployment if it doesn't exist
    if (!this.deployments.has(workflowId)) {
      this.deployments.set(workflowId, {
        blue: { version: '1.0.0' },
        green: { version: '2.0.0' },
        greenPercentage: 0,
      });
    }

    const deployment = this.deployments.get(workflowId);
    deployment.greenPercentage = greenPercentage;
  }

  /**
   * Ramp up traffic to green version
   * @param {string} workflowId - Workflow identifier
   * @param {number} targetPercentage - Target percentage
   */
  async rampUp(workflowId, targetPercentage) {
    // Check health before ramping up
    const health = await this.checkHealth(workflowId, 'green');
    if (!health.healthy) {
      throw new Error('Unhealthy metrics: cannot ramp up');
    }

    await this.setTraffic(workflowId, { greenPercentage: targetPercentage });
  }

  /**
   * Ramp down traffic from green version
   * @param {string} workflowId - Workflow identifier
   * @param {number} targetPercentage - Target percentage
   */
  async rampDown(workflowId, targetPercentage) {
    await this.setTraffic(workflowId, { greenPercentage: targetPercentage });
  }

  /**
   * Instant rollback to blue version
   * @param {string} workflowId - Workflow identifier
   * @param {object} options - { reason }
   */
  async rollback(workflowId, options = {}) {
    const { reason = 'Manual rollback' } = options;

    const deployment = this.deployments.get(workflowId);
    if (!deployment) return;

    // Record rollback
    const rollback = {
      fromVersion: deployment.green.version,
      toVersion: deployment.blue.version,
      reason,
      timestamp: new Date().toISOString(),
    };

    if (!this.rollbackHistory.has(workflowId)) {
      this.rollbackHistory.set(workflowId, []);
    }
    this.rollbackHistory.get(workflowId).push(rollback);

    // Set traffic to 0%
    deployment.greenPercentage = 0;
  }

  /**
   * Get rollback history
   * @param {string} workflowId - Workflow identifier
   * @returns {object[]} Rollback history
   */
  getRollbackHistory(workflowId) {
    return this.rollbackHistory.get(workflowId) || [];
  }

  /**
   * Check health of version
   * @param {string} workflowId - Workflow identifier
   * @param {string} color - 'blue' or 'green'
   * @returns {object} Health status
   */
  async checkHealth(workflowId, color) {
    const deployment = this.deployments.get(workflowId);
    if (!deployment) {
      return { version: '1.0.0', healthy: true, metrics: {} };
    }

    const version = deployment[color].version;

    // Check mock health (for testing)
    if (this.mockHealth.has(workflowId)) {
      const mock = this.mockHealth.get(workflowId)[color];
      if (mock) {
        return { version, ...mock };
      }
    }

    // Default: healthy
    return { version, healthy: true, metrics: {} };
  }

  /**
   * Set mock health (for testing)
   * @param {string} workflowId - Workflow identifier
   * @param {string} color - 'blue' or 'green'
   * @param {object} health - Health status
   */
  setMockHealth(workflowId, color, health) {
    if (!this.mockHealth.has(workflowId)) {
      this.mockHealth.set(workflowId, {});
    }
    this.mockHealth.get(workflowId)[color] = health;
  }

  /**
   * Start health monitoring (auto-rollback on failure)
   * @param {string} workflowId - Workflow identifier
   * @param {number} interval - Check interval (ms)
   */
  _startHealthMonitoring(workflowId, interval) {
    const checkHealth = async () => {
      const deployment = this.deployments.get(workflowId);
      if (!deployment || !deployment.autoRollback) {
        return; // Stop monitoring
      }

      const health = await this.checkHealth(workflowId, 'green');
      if (!health.healthy && deployment.greenPercentage > 0) {
        await this.rollback(workflowId, { reason: 'Auto-rollback: unhealthy metrics' });
        return; // Stop after rollback
      }

      // Schedule next check
      setTimeout(checkHealth, interval);
    };

    setTimeout(checkHealth, interval);
  }

  /**
   * Switch active version pointer
   * @param {string} workflowId - Workflow identifier
   */
  async switchActive(workflowId) {
    const deployment = this.deployments.get(workflowId);
    if (deployment) {
      // Swap blue and green
      const temp = deployment.blue;
      deployment.blue = deployment.green;
      deployment.green = temp;
      deployment.greenPercentage = 0; // Reset
    }
  }

  /**
   * Get active version
   * @param {string} workflowId - Workflow identifier
   * @returns {object} Active version
   */
  getActive(workflowId) {
    const deployment = this.deployments.get(workflowId);
    return deployment ? deployment.blue : { version: '1.0.0' };
  }

  /**
   * Retire old version (remove from deployment)
   * @param {string} workflowId - Workflow identifier
   * @param {string} version - Version to retire
   */
  async retire(workflowId, version) {
    const deployment = this.deployments.get(workflowId);
    if (!deployment) return;

    // Remove from blue or green
    if (deployment.blue.version === version) {
      // If retiring blue (current active), set to null or keep green as sole version
      deployment.blue = { version: deployment.green.version };
    } else if (deployment.green.version === version) {
      // If retiring green, remove it
      deployment.green = { version: deployment.blue.version };
    }
  }

  /**
   * List versions (simplified)
   * @param {string} workflowId - Workflow identifier
   * @returns {string[]} Version list
   */
  listVersions(workflowId) {
    const deployment = this.deployments.get(workflowId);
    if (!deployment) return [];

    const versions = [deployment.blue.version];
    if (deployment.green && deployment.green.version !== deployment.blue.version) {
      versions.push(deployment.green.version);
    }
    return versions;
  }

  /**
   * Deploy canary (10% traffic)
   * @param {string} workflowId - Workflow identifier
   * @param {string} newVersion - Canary version
   * @param {object} options - Deployment options
   */
  async deployCanary(workflowId, newVersion, options = {}) {
    const {
      canaryPercentage = 10,
      autoRollbackOnFailure = false,
      healthCheckInterval = 100,
    } = options;

    await this.deploy(workflowId, newVersion, {
      startPercentage: canaryPercentage,
      autoRollback: autoRollbackOnFailure,
      monitorHealth: autoRollbackOnFailure,
      healthCheckInterval,
    });
  }

  /**
   * Check canary health
   * @param {string} workflowId - Workflow identifier
   * @returns {boolean} True if healthy
   */
  async checkCanaryHealth(workflowId) {
    const health = await this.checkHealth(workflowId, 'green');
    return health.healthy && (health.successRate || 1.0) >= 0.99;
  }

  /**
   * Promote canary to full deployment
   * @param {string} workflowId - Workflow identifier
   */
  async promoteCanary(workflowId) {
    await this.setTraffic(workflowId, { greenPercentage: 100 });
  }

class CycleDetector {
  /**
   * Detect cycles in workflow dependencies
   * @param {Object} workflow - The workflow to check
   * @param {Map} registry - Map of all workflows by name
   * @param {Set} visited - Already validated workflows (optimization)
   * @param {Object} options - { maxDepth: 10 }
   */
  async detectCycles(workflow, registry, visited = new Set(), options = {}) {
    const maxDepth = options.maxDepth ?? MAX_DEPTH;
    const stack = new Set();
    const allVisited = new Set(visited);

    await this._dfs(workflow.name || workflow.id, registry, stack, allVisited, [], maxDepth);
  }

  /**
   * Depth-first search to detect cycles
   */
  async _dfs(name, registry, stack, visited, path, maxDepth) {
    if (path.length >= maxDepth) {
      throw new Error(
        `Workflow composition depth exceeded ${maxDepth}: ${[...path, name].join(' -> ')}`
      );
    }

    if (!registry.has(name)) {
      throw new Error(`Workflow '${name}' not found in registry`);
    }

    if (visited.has(name)) {
      return;
    }

    if (stack.has(name)) {
      const cyclePath = [...path, name].join(' -> ');
      throw new Error(`Circular dependency detected: ${cyclePath}`);
    }

    stack.add(name);
    path.push(name);

    const workflow = registry.get(name);
    const dependencies = this._extractDependencies(workflow);

    for (const depName of dependencies) {
      await this._dfs(depName, registry, stack, visited, [...path], maxDepth);
    }

    stack.delete(name);
    visited.add(name);
  }

  /**
   * Extract all workflow dependencies from a workflow
   */
  _extractDependencies(workflow) {
    const deps = new Set();

    // Handle extends
    if (workflow.extends) {
      const extendsArray = Array.isArray(workflow.extends) ? workflow.extends : [workflow.extends];
      extendsArray.forEach(e => deps.add(e));
    }

    // Handle includes
    if (workflow.includes) {
      const includesArray = Array.isArray(workflow.includes)
        ? workflow.includes
        : [workflow.includes];
      includesArray.forEach(i => deps.add(i));
    }

    // Handle includes in phases
    if (workflow.phases && Array.isArray(workflow.phases)) {
      for (const phase of workflow.phases) {
        if (phase.include) {
          deps.add(phase.include);
        }
      }
    }

    // Handle compose
    if (workflow.compose && workflow.compose.workflows) {
      const workflowsArray = Array.isArray(workflow.compose.workflows)
        ? workflow.compose.workflows
        : [workflow.compose.workflows];
      workflowsArray.forEach(w => {
        const name = typeof w === 'string' ? w : w.workflow;
        if (name) deps.add(name);
      });
    }

    return Array.from(deps);
  }

async function orchestrate(projectPath) {
  const startTime = Date.now();

  // Step 1: Detect tech stack
  console.log('[BROWNFIELD] Detecting tech stack...');
  const techStack = await techStackDetector.detect(projectPath);

  // Step 2: Assess maturity
  console.log('[BROWNFIELD] Assessing project maturity...');
  const assessment = await brownfieldAssessor.assess(projectPath);

  // Step 3: Select agents
  console.log('[BROWNFIELD] Selecting appropriate agents...');
  const suggestedAgents = assessment.suggested_agents;

  // Step 4: Configure phase-completion-guard based on maturity
  console.log('[BROWNFIELD] Configuring workflow parameters...');
  const configuration = configureWorkflow(assessment);

  // Step 5: Generate onboarding report
  const elapsedTime = Math.round((Date.now() - startTime) / 1000);
  const estimatedSetupTime = estimateSetupTime(assessment);

  const onboardingReport = {
    tech_stack: techStack,
    project_type: assessment.type,
    maturity_scores: assessment.scores,
    suggested_agents: suggestedAgents,
    suggested_workflows: assessment.suggested_workflows,
    recommendations: assessment.recommendations,
    configuration: configuration,
    estimated_setup_time: estimatedSetupTime,
    detection_time: `${elapsedTime} seconds`,
    next_steps: generateNextSteps(assessment, techStack),
  };

  console.log(`[BROWNFIELD] Onboarding configured in ${elapsedTime}s`);
  console.log(`[BROWNFIELD] Estimated setup time: ${estimatedSetupTime}`);

  return onboardingReport;
}

function configureWorkflow(assessment) {
  const config = {
    phase_completion_guard: 'warn', // default
    test_coverage_threshold: 0.8,
    documentation_required: true,
    code_review_required: true,
  };

  // Adjust based on project type
  if (assessment.type === 'greenfield') {
    config.phase_completion_guard = 'warn'; // Lenient for new projects
    config.test_coverage_threshold = 0.6; // Lower threshold
  } else if (assessment.type === 'brownfield') {
    config.phase_completion_guard = 'block'; // Enforce quality gates
    config.test_coverage_threshold = 0.8; // Standard threshold
  } else if (assessment.type === 'legacy') {
    config.phase_completion_guard = 'block'; // Strict for legacy
    config.test_coverage_threshold = 0.7; // Realistic for legacy
    config.refactoring_recommended = true;
  }

  return config;
}

function estimateSetupTime(assessment) {
  if (assessment.type === 'greenfield') {
    return '15-20 minutes';
  } else if (assessment.type === 'brownfield') {
    return '20-30 minutes';
  } else {
    return '30-45 minutes'; // legacy
  }
}

