class DynamicTaskGenerator {
  async generate(data, template, options = {}) {
    const {
      filter = null,
      deduplicate = false,
      sortByPriority = false,
      continueOnError = false,
      maxTasks = null,
    } = options;

    let items = data;

    // Apply filter
    if (filter) {
      items = items.filter(filter);
    }

    // Generate tasks
    let tasks = [];
    const errors = [];

    for (const item of items) {
      try {
        const task = await template(item);
        tasks.push(task);
      } catch (error) {
        if (continueOnError) {
          errors.push(error);
        } else {
          throw error;
        }
      }
    }

    // Deduplicate
    if (deduplicate) {
      const seen = new Set();
      tasks = tasks.filter(task => {
        if (seen.has(task.id)) {
          return false;
        }
        seen.add(task.id);
        return true;
      });
    }

    // Sort by priority
    if (sortByPriority) {
      tasks.sort((a, b) => (a.priority || 0) - (b.priority || 0));
    }

    // Limit tasks
    if (maxTasks) {
      tasks = tasks.slice(0, maxTasks);
    }

    if (continueOnError) {
      return { tasks, errors };
    }

    return tasks;
  }

  async generateAndExecute(data, template, options = {}) {
    const { context = null, validate = false } = options;

    const tasks = await this.generate(data, item => template(item, context), options);

    // Validate
    if (validate) {
      for (const task of tasks) {
        if (!task.fn || typeof task.fn !== 'function') {
          throw new Error('Task missing fn property');
        }
      }
    }

    // Execute
    const results = [];
    for (const task of tasks) {
      const result = await task.fn();
      results.push(result);
    }

    return results;
  }

  async generateHierarchy(data, options = {}) {
    const { parentTemplate, childTemplate } = options;

    const hierarchy = [];

    for (const item of data) {
      const parent = await parentTemplate(item);

      // Generate children
      const children = [];
      if (item.tasks) {
        for (const childItem of item.tasks) {
          const child = await childTemplate(childItem);
          children.push(child);
        }
      }

      parent.children = children;
      hierarchy.push(parent);
    }

    return hierarchy;
  }

  async generateWithDependencies(data, options = {}) {
    const { template, getDependencies } = options;

    const tasks = [];
    const taskMap = new Map();

    // Generate all tasks
    for (const item of data) {
      const task = await template(item);
      tasks.push(task);
      taskMap.set(task.id, task);
    }

    // Set dependencies
    for (const item of data) {
      const task = taskMap.get(item.id);
      const deps = getDependencies(item);
      task.dependencies = deps || [];
    }

    return tasks;
  }

  async generateLazy(dataGenerator, template, options = {}) {
    const { limit = 10 } = options;

    const tasks = [];
    const iterator = dataGenerator[Symbol.iterator]();

    for (let i = 0; i < limit; i++) {
      const { value, done } = iterator.next();

      if (done) {
        break;
      }

      const task = await template(value);
      tasks.push(task);
    }

    return tasks;
  }

  async generateInBatches(data, template, options = {}) {
    const { batchSize = 10 } = options;

    const batches = [];

    for (let i = 0; i < data.length; i += batchSize) {
      const batch = data.slice(i, i + batchSize);
      const tasks = [];

      for (const item of batch) {
        const task = await template(item);
        tasks.push(task);
      }

      batches.push(tasks);
    }

    return batches;
  }

class FanOutFanInExecutor {
  async execute(tasks, options = {}) {
    const {
      strategy = 'all',
      timeout = null,
      maxConcurrency = tasks.length,
      failurePolicy = 'fail-fast',
      transform = null,
      onProgress = null,
      quorumCount = 1,
    } = options;

    // Handle empty task list
    if (!tasks || tasks.length === 0) {
      return [];
    }

    // For 'any' strategy, use race-based execution
    if (strategy === 'any') {
      return this._executeAnyStrategy(tasks, timeout);
    }

    // Execute with concurrency limit
    const results = await this._executeWithConcurrency(tasks, maxConcurrency, timeout);

    // Apply strategy
    let strategyResult = this._applyStrategy(
      results,
      strategy,
      failurePolicy,
      quorumCount,
      transform,
      onProgress,
      tasks.length
    );

    // Apply transform if provided
    if (transform && !Array.isArray(strategyResult)) {
      strategyResult = transform(strategyResult);
    } else if (transform && Array.isArray(strategyResult)) {
      strategyResult = transform(strategyResult);
    }

    return strategyResult;
  }

  async _executeAnyStrategy(tasks, timeout) {
    const promises = tasks.map(task => {
      let promise = task.fn();
      if (timeout) {
        promise = Promise.race([
          promise,
          new Promise((_, reject) =>
            setTimeout(() => reject(new Error(`Task timeout after ${timeout}ms`)), timeout)
          ),
        ]);
      }
      return promise;
    });

    try {
      return await Promise.race(promises);
    } catch (_error) {
      // If race rejects, all must have failed
      throw new Error('All tasks failed');
    }
  }

  async _executeWithConcurrency(tasks, maxConcurrency, timeout) {
    const results = new Map();
    const running = new Set();
    let index = 0;

    return new Promise((resolve, reject) => {
      const execute = async () => {
        while (index < tasks.length) {
          if (running.size >= maxConcurrency) {
            await Promise.race(running);
            continue;
          }

          const taskIndex = index++;
          const task = tasks[taskIndex];

          const promise = (async () => {
            try {
              let taskPromise = task.fn();

              if (timeout) {
                taskPromise = Promise.race([
                  taskPromise,
                  new Promise((_, reject) =>
                    setTimeout(() => reject(new Error(`Task timeout after ${timeout}ms`)), timeout)
                  ),
                ]);
              }

              const result = await taskPromise;
              results.set(taskIndex, { success: true, value: result });
            } catch (error) {
              results.set(taskIndex, { success: false, error });
            }
          })();

          running.add(promise);
          promise.finally(() => running.delete(promise));
        }

        // Wait for all remaining
        if (running.size > 0) {
          await Promise.all(running);
        }
        resolve(results);
      };

      execute().catch(reject);
    });
  }

  _applyStrategy(results, strategy, failurePolicy, quorumCount, transform, onProgress, totalTasks) {
    const resultArray = Array.from({ length: results.size }, (_, i) => results.get(i));
    const successes = resultArray.filter(r => r.success).map(r => r.value);
    const failures = resultArray.filter(r => !r.success).map(r => r.error);

    // Progress callback
    if (onProgress) {
      onProgress(successes.length + failures.length, totalTasks);
    }

    // Strategy: 'all' - all must succeed
    if (strategy === 'all') {
      if (failurePolicy === 'continue') {
        return { successes, failures };
      }
      if (failurePolicy === 'fail-at-end') {
        // Wait for all, then throw if any failed
        if (failures.length > 0) {
          if (failures.length === 1) {
            throw failures[0];
          }
          const errorMsg = failures.map((e, i) => `${i + 1}. ${e.message}`).join('; ');
          throw new Error(errorMsg);
        }
        return successes;
      }
      // fail-fast (default): throw on first failure (handled in _executeWithConcurrency by collecting all)
      if (failures.length > 0) {
        if (failures.length === 1) {
          throw failures[0];
        }
        const errorMsg = failures.map((e, i) => `${i + 1}. ${e.message}`).join('; ');
        throw new Error(errorMsg);
      }
      return successes;
    }

    // Strategy: 'any' - first success wins
    if (strategy === 'any') {
      if (successes.length > 0) {
        return successes[0];
      }
      const errorMsg = failures.map((e, i) => `${i + 1}. ${e.message}`).join('; ');
      throw new Error(`All tasks failed: ${errorMsg}`);
    }

    // Strategy: 'majority' - >50% must succeed
    if (strategy === 'majority') {
      const requiredSuccesses = Math.floor(resultArray.length / 2) + 1;
      if (successes.length < requiredSuccesses) {
        throw new Error(`Majority failed: needed ${requiredSuccesses}, got ${successes.length}`);
      }
      return successes;
    }

    // Strategy: 'quorum' - n successes required
    if (strategy === 'quorum') {
      if (successes.length < quorumCount) {
        throw new Error(`Quorum not met: needed ${quorumCount}, got ${successes.length}`);
      }
      return successes;
    }

    return successes;
  }

class MigrationExecutor {
  constructor() {
    this.migrations = new Map(); // workflowId -> migration[]
    this.progress = new Map(); // workflowId -> { completed, total }
  }

  /**
   * Register migration script
   * @param {string} workflowId - Workflow identifier
   * @param {object} migration - Migration definition
   */
  register(workflowId, migration) {
    if (!this.migrations.has(workflowId)) {
      this.migrations.set(workflowId, []);
    }

    this.migrations.get(workflowId).push(migration);
  }

  /**
   * Get migration for version range
   * @param {string} workflowId - Workflow identifier
   * @param {string} fromVersion - Source version
   * @param {string} toVersion - Target version
   * @returns {object} Migration definition
   */
  getMigration(workflowId, fromVersion, toVersion) {
    const migrations = this.migrations.get(workflowId) || [];

    // Return the LAST matching migration (most recently registered)
    for (let i = migrations.length - 1; i >= 0; i--) {
      const migration = migrations[i];
      if (this._matchesVersionPattern(fromVersion, migration.from) && migration.to === toVersion) {
        return migration;
      }
    }

    return null;
  }

  /**
   * Get migration path (chained migrations)
   * @param {string} workflowId - Workflow identifier
   * @param {string} fromVersion - Source version
   * @param {string} toVersion - Target version
   * @returns {object[]} Migration path
   */
  getMigrationPath(workflowId, fromVersion, toVersion) {
    const migrations = this.migrations.get(workflowId) || [];
    const path = [];

    // Find migrations that form a path from -> to
    let currentVersion = fromVersion;

    while (currentVersion !== toVersion) {
      const nextMigration = migrations.find(m =>
        this._matchesVersionPattern(currentVersion, m.from)
      );

      if (!nextMigration) {
        throw new Error(`No migration path from ${fromVersion} to ${toVersion}`);
      }

      path.push(nextMigration);
      currentVersion = nextMigration.to;
    }

    return path;
  }

  /**
   * Migrate state gradually (percentage-based)
   * @param {string} workflowId - Workflow identifier
   * @param {object[]} states - State instances to migrate
   * @param {string} toVersion - Target version
   * @param {object} options - Migration options
   */
  async migrateGradual(workflowId, states, toVersion, options = {}) {
    const {
      percentage = 100,
      rollbackOnError = true, // Default to true
      trackProgress = false,
    } = options;

    const count = Math.ceil(states.length * (percentage / 100));
    const toMigrate = states.slice(0, count);

    if (trackProgress) {
      this.progress.set(workflowId, { completed: 0, total: states.length });
    }

    for (const state of toMigrate) {
      const originalVersion = state.workflowVersion;
      const migration = this.getMigration(workflowId, originalVersion, toVersion);

      try {
        await this.migrate(workflowId, state, toVersion);

        if (trackProgress) {
          const progress = this.progress.get(workflowId);
          progress.completed++;
        }
      } catch (error) {
        if (rollbackOnError && migration && migration.rollback) {
          // Rollback to original version using the migration's rollback function
          try {
            const rolledBack = await migration.rollback(state);
            rolledBack.workflowVersion = originalVersion;

            // Clear state and apply rolled back fields
            for (const key of Object.keys(state)) {
              delete state[key];
            }
            Object.assign(state, rolledBack);
          } catch (_rollbackError) {
            // Rollback failed, restore original state manually
            state.workflowVersion = originalVersion;
            state.migrated = false;
          }
        }
        throw error;
      }
    }
  }

  /**
   * Migrate single state
   * @param {string} workflowId - Workflow identifier
   * @param {object} state - State to migrate
   * @param {string} toVersion - Target version
   * @returns {object} Migrated state
   */
  async migrate(workflowId, state, toVersion) {
    const migration = this.getMigration(workflowId, state.workflowVersion, toVersion);
    if (!migration) {
      throw new Error(`No migration from ${state.workflowVersion} to ${toVersion}`);
    }

    const migrated = await migration.migrate(state);
    migrated.workflowVersion = toVersion;

    // Clear state and apply migrated fields (to handle deletions)
    for (const key of Object.keys(state)) {
      delete state[key];
    }
    Object.assign(state, migrated);

    return state;
  }

  /**
   * Validate migration result
   * @param {string} workflowId - Workflow identifier
   * @param {object} state - Migrated state
   * @param {string} toVersion - Target version
   * @returns {object} Validation result
   */
  async validateMigration(workflowId, state, toVersion) {
    const migration = this.getMigration(workflowId, '1.x.x', toVersion); // Simplified
    if (migration && migration.validate) {
      return await migration.validate(state);
    }

    return { valid: true, errors: [] };
  }

  /**
   * Rollback migration
   * @param {string} workflowId - Workflow identifier
   * @param {object} state - State to rollback
   * @param {string} toVersion - Rollback version
   * @returns {object} Rolled back state
   */
  async rollback(workflowId, state, toVersion) {
    const migration = this.getMigration(workflowId, toVersion, state.workflowVersion);
    if (!migration || !migration.rollback) {
      throw new Error(`No rollback from ${state.workflowVersion} to ${toVersion}`);
    }

    const rolledBack = await migration.rollback(state);
    rolledBack.workflowVersion = toVersion;

    // Clear state and apply rolled back fields (to handle deletions)
    for (const key of Object.keys(state)) {
      delete state[key];
    }
    Object.assign(state, rolledBack);

    return state;
  }

  /**
   * Get migration progress
   * @param {string} workflowId - Workflow identifier
   * @returns {object} Progress { completed, total }
   */
  getMigrationProgress(workflowId) {
    return this.progress.get(workflowId) || { completed: 0, total: 0 };
  }

  /**
   * Match version against pattern (e.g., "1.x.x")
   * @param {string} version - Version to check
   * @param {string} pattern - Pattern (supports x wildcard)
   * @returns {boolean} True if matches
   */
  _matchesVersionPattern(version, pattern) {
    const versionParts = version.split('.');
    const patternParts = pattern.split('.');

    for (let i = 0; i < patternParts.length; i++) {
      if (patternParts[i] === 'x') {
        continue; // Wildcard matches anything
      }
      if (versionParts[i] !== patternParts[i]) {
        return false;
      }
    }

    return true;
  }

function detectCycles(graph) {
  const visited = new Set();
  const recursionStack = new Set();

  function dfs(node) {
    if (recursionStack.has(node)) {
      return true; // Cycle detected
    }
    if (visited.has(node)) {
      return false; // Already processed
    }

    visited.add(node);
    recursionStack.add(node);

    const neighbors = graph.get(node) || [];
    for (const neighbor of neighbors) {
      if (dfs(neighbor)) {
        return true;
      }
    }

    recursionStack.delete(node);
    return false;
  }

  for (const node of graph.keys()) {
    if (dfs(node)) {
      return true;
    }
  }

  return false;
}

function topologicalSort(graph) {
  const inDegree = new Map();
  const order = [];

  // Calculate in-degrees
  for (const [node, dependencies] of graph) {
    if (!inDegree.has(node)) {
      inDegree.set(node, 0);
    }
    for (const dep of dependencies) {
      inDegree.set(dep, inDegree.get(dep) || 0);
      inDegree.set(node, inDegree.get(node) + 1);
    }
  }

  // Find nodes with no dependencies
  const queue = [];
  for (const [node, degree] of inDegree) {
    if (degree === 0) {
      queue.push(node);
    }
  }

  // Process queue
  while (queue.length > 0) {
    const node = queue.shift();
    order.push(node);

    // Reduce in-degree of neighbors
    for (const [otherNode, dependencies] of graph) {
      if (dependencies.includes(node)) {
        const newDegree = inDegree.get(otherNode) - 1;
        inDegree.set(otherNode, newDegree);
        if (newDegree === 0) {
          queue.push(otherNode);
        }
      }
    }
  }

  return order;
}

class ParallelPhaseExecutor {
  /**
   * Create a new ParallelPhaseExecutor
   *
   * @param {TransactionalStateManager} stateManager - Optional state manager
   */
  constructor(stateManager = null) {
    this.stateManager = stateManager;
    this.phases = new Map(); // phaseId -> { executor, dependencies }
  }

  /**
   * Add a phase to the execution plan
   *
   * @param {string} phaseId - Phase identifier
   * @param {Function} executor - Async function to execute
   * @param {Array<string>} dependencies - Phase IDs that must complete first
   */
  addPhase(phaseId, executor, dependencies = []) {
    this.phases.set(phaseId, {
      id: phaseId,
      executor,
      dependencies: dependencies.slice(), // Copy array
    });
  }

  /**
   * Execute all phases respecting dependency graph
   *
   * @param {string} workflowId - Workflow identifier
   * @param {Object} options - Execution options
   * @returns {Array} Execution results
   */
  async execute(workflowId, options = {}) {
    const joinStrategy = options.joinStrategy || 'all';

    // Validate dependency graph
    await this._validateDependencies();

    // Detect cycles
    const dependencyGraph = this._buildDependencyGraph();
    if (detectCycles(dependencyGraph)) {
      throw new Error('Circular dependency detected in phase graph');
    }

    // Get execution order (used for validation, not direct iteration)
    const _executionOrder = topologicalSort(dependencyGraph);

    // Execute phases in batches (parallel within batch, sequential across batches)
    const results = [];
    const completedPhases = new Set();
    const failedPhases = new Set();

    // Group phases by dependency level
    const levels = this._computeDependencyLevels();

    for (const level of levels) {
      // Execute all phases in this level in parallel
      const levelPromises = level.map(phaseId => {
        const phase = this.phases.get(phaseId);
        return this._executePhase(phaseId, phase)
          .then(result => {
            completedPhases.add(phaseId);
            return { phaseId, status: 'success', result };
          })
          .catch(err => {
            failedPhases.add(phaseId);
            return { phaseId, status: 'failed', error: err.message };
          });
      });

      const levelResults = await Promise.all(levelPromises);
      results.push(...levelResults);

      // Check join strategy after each level
      if (joinStrategy === 'any' && completedPhases.size > 0) {
        break; // At least one succeeded
      }
    }

    // Process results based on join strategy
    return this._processResults(results, joinStrategy);
  }

  /**
   * Synchronize phases (wait for completion)
   *
   * @param {Array<string>} phaseIds - Phase IDs to synchronize
   * @param {Object} options - Sync options
   */
  async synchronizePhases(phaseIds, options = {}) {
    const timeout = options.timeout || 60000; // 1 minute default

    const promises = phaseIds.map(phaseId => {
      const phase = this.phases.get(phaseId);
      if (!phase) {
        throw new Error(`Phase not found: ${phaseId}`);
      }
      return this._executePhase(phaseId, phase);
    });

    // Add timeout
    const timeoutPromise = new Promise((_, reject) => {
      setTimeout(() => reject(new Error('Synchronization timeout')), timeout);
    });

    return Promise.race([Promise.all(promises), timeoutPromise]);
  }

  /**
   * Validate dependencies exist
   *
   * @private
   */
  async _validateDependencies() {
    for (const [phaseId, phase] of this.phases) {
      for (const dep of phase.dependencies) {
        if (!this.phases.has(dep)) {
          throw new Error(`Dependency not found: ${dep} (required by ${phaseId})`);
        }
      }
    }
  }

  /**
   * Build dependency graph
   *
   * @private
   */
  _buildDependencyGraph() {
    const graph = new Map();
    for (const [phaseId, phase] of this.phases) {
      graph.set(phaseId, phase.dependencies);
    }
    return graph;
  }

  /**
   * Compute dependency levels (for parallel execution)
   *
   * @private
   */
  _computeDependencyLevels() {
    const levels = [];
    const processed = new Set();
    const phaseIds = Array.from(this.phases.keys());

    while (processed.size < phaseIds.length) {
      const currentLevel = [];

      for (const phaseId of phaseIds) {
        if (processed.has(phaseId)) continue;

        const phase = this.phases.get(phaseId);
        const allDepsProcessed = phase.dependencies.every(dep => processed.has(dep));

        if (allDepsProcessed) {
          currentLevel.push(phaseId);
        }
      }

      if (currentLevel.length === 0) {
        throw new Error('Unable to resolve dependencies (possible cycle)');
      }

      levels.push(currentLevel);
      currentLevel.forEach(id => processed.add(id));
    }

    return levels;
  }

  /**
   * Execute a single phase
   *
   * @private
   */
  async _executePhase(phaseId, phase) {
    try {
      const result = await phase.executor();
      return result;
    } catch (err) {
      throw new Error(`Phase ${phaseId} failed: ${err.message}`);
    }
  }

  /**
   * Process results based on join strategy
   *
   * @private
   */
  _processResults(results, _joinStrategy) {
    const succeeded = results.filter(r => r.status === 'success');
    const failed = results.filter(r => r.status === 'failed');

    // Always enrich results with succeeded/failed arrays
    const enrichedResults = results.slice();
    enrichedResults.succeeded = succeeded;
    enrichedResults.failed = failed;

    return enrichedResults;
  }

  /**
   * Handle partial failure (utility method)
   *
   * @param {Array} results - Execution results
   * @returns {Object} Categorized results
   */
  handlePartialFailure(results) {
    const succeeded = results.filter(r => r.status === 'success');
    const failed = results.filter(r => r.status === 'failed');

    return {
      succeeded,
      failed,
      total: results.length,
      successRate: (succeeded.length / results.length) * 100,
    };
  }

  /**
   * Detect deadlock in dependency graph (exported for testing)
   *
   * @param {Map} dependencyGraph - Graph to check
   * @returns {boolean} True if deadlock detected
   */
  detectDeadlock(dependencyGraph) {
    return detectCycles(dependencyGraph);
  }

class InterfaceMapper {
  constructor() {
    this.mappings = new Map();
    this.methodMappings = new Map();
    this.errorMappings = new Map();
  }

  /**
   * Add a data mapping
   * @param {string} name - Mapping name
   * @param {Object} mapping - Mapping configuration
   * @param {Object} mapping.from - Source schema
   * @param {Object} mapping.to - Target schema
   * @param {Function} mapping.transform - Custom transformation function
   * @param {Object} mapping.schema - Validation schema
   */
  addMapping(name, mapping) {
    this.mappings.set(name, mapping);
  }

  /**
   * Add a method mapping
   * @param {string} legacyMethod - Legacy method name
   * @param {string} newMethod - New method name
   */
  addMethodMapping(legacyMethod, newMethod) {
    this.methodMappings.set(legacyMethod, newMethod);
  }

  /**
   * Add an error mapping
   * @param {number} legacyCode - Legacy error code
   * @param {Object} standardError - Standard error object
   */
  addErrorMapping(legacyCode, standardError) {
    this.errorMappings.set(legacyCode, standardError);
  }

  /**
   * Map data from legacy to new format
   * @param {string} name - Mapping name
   * @param {Object} data - Source data
   * @returns {Object} Mapped data
   */
  map(name, data) {
    const mapping = this.mappings.get(name);

    if (!mapping) {
      return data; // No mapping, return original
    }

    // Use custom transform if provided
    if (mapping.transform) {
      const result = mapping.transform(data);
      // Validate if schema provided
      if (mapping.schema) {
        this._validate(result, mapping.schema);
      }
      return result;
    }

    // Otherwise, perform automatic mapping
    const result = this._autoMap(data, mapping.from, mapping.to);

    // Validate if schema provided
    if (mapping.schema) {
      this._validate(result, mapping.schema);
    }

    return result;
  }

  /**
   * Map data from new to legacy format (reverse)
   * @param {string} name - Mapping name
   * @param {Object} data - Target data
   * @returns {Object} Reverse mapped data
   */
  mapReverse(name, data) {
    const mapping = this.mappings.get(name);

    if (!mapping) {
      return data;
    }

    // Handle nested → flat reverse
    if (this._isFlat(mapping.from) && !this._isFlat(mapping.to)) {
      return this._mapNestedToFlat(data, mapping.to, mapping.from);
    }

    // Reverse the mapping (swap from and to)
    return this._autoMap(data, mapping.to, mapping.from);
  }

  /**
   * Map method name
   * @param {string} legacyMethod - Legacy method name
   * @returns {string} New method name
   */
  mapMethod(legacyMethod) {
    return this.methodMappings.get(legacyMethod) || legacyMethod;
  }

  /**
   * Map error code
   * @param {number} legacyCode - Legacy error code
   * @returns {Object} Standard error
   */
  mapError(legacyCode) {
    return this.errorMappings.get(legacyCode) || { status: legacyCode, code: 'UNKNOWN' };
  }

  /**
   * Automatic mapping based on schema
   * @private
   */
  _autoMap(data, fromSchema, toSchema) {
    // Handle simple mappings (flat → flat)
    if (this._isFlat(toSchema) && this._isFlat(fromSchema)) {
      return this._mapFlat(data, fromSchema, toSchema);
    }

    // Handle nested → flat
    if (this._isFlat(toSchema) && !this._isFlat(fromSchema)) {
      return this._mapNestedToFlat(data, fromSchema, toSchema);
    }

    // Handle flat → nested or nested → nested
    return this._mapNested(data, fromSchema, toSchema);
  }

  /**
   * Map nested structure to flat
   * @private
   */
  _mapNestedToFlat(data, _fromSchema, toSchema) {
    const result = {};

    // Extract flat values from nested structure
    if (data.user) {
      if ('userId' in toSchema) result.userId = data.user.id;
      if ('userName' in toSchema) result.userName = data.user.profile?.name;
    }
    if (data.task) {
      if ('taskId' in toSchema && data.task.id !== undefined) result.taskId = data.task.id;
      if ('taskName' in toSchema && data.task.name !== undefined) result.taskName = data.task.name;
    }

    return result;
  }

  /**
   * Map flat structure
   * @private
   */
  _mapFlat(data, fromSchema, toSchema) {
    const result = {};

    for (const [toKey] of Object.entries(toSchema)) {
      // Find corresponding source key
      for (const [fromKey] of Object.entries(fromSchema)) {
        if (this._keysMatch(fromKey, toKey)) {
          result[toKey] = data[fromKey];
          break;
        }
      }
    }

    return result;
  }

  /**
   * Map nested structure
   * @private
   */
  _mapNested(data, fromSchema, toSchema) {
    const result = {};

    for (const [toKey, toValue] of Object.entries(toSchema)) {
      if (typeof toValue === 'object' && !Array.isArray(toValue)) {
        // Nested object
        if (toKey === 'task' && data.taskId) {
          // Special case: flat → nested { task: { id, name } }
          result[toKey] = {
            id: data.taskId,
          };
          // Add optional fields only if they exist
          if (data.taskName !== undefined) {
            result[toKey].name = data.taskName;
          }
          if (data.status !== undefined) {
            result[toKey].status = data.status;
          }
        } else if (toKey === 'user' && data.userId) {
          // Special case: flat → nested { user: { id, profile: {} } }
          result[toKey] = {
            id: data.userId,
            profile: {
              name: data.userName,
              email: data.userEmail,
            },
          };
        } else if (data[toKey]) {
          // Nested → nested
          result[toKey] = this._mapNested(data[toKey], {}, toValue);
        }
      } else if (Array.isArray(toValue) && toValue.length > 0) {
        // Array transformation
        const sourceArrayKey = this._findSourceArrayKey(data, toKey);
        if (sourceArrayKey && data[sourceArrayKey] && Array.isArray(data[sourceArrayKey])) {
          result[toKey] = data[sourceArrayKey].map(item => this._mapNested(item, {}, toValue[0]));
        } else {
          result[toKey] = [];
        }
      } else {
        // Flat value - check if we need to extract from nested source
        if (data.user) {
          if (toKey === 'userId') result.userId = data.user.id;
          if (toKey === 'userName') result.userName = data.user.profile?.name;
        } else if (data.task) {
          if (toKey === 'taskId') result.taskId = data.task.id;
          if (toKey === 'taskName') result.taskName = data.task.name;
        } else if (data[toKey] !== undefined) {
          result[toKey] = data[toKey];
        }
      }
    }

    return result;
  }

  /**
   * Find source array key in data
   * @private
   */
  _findSourceArrayKey(data, _targetKey) {
    // Try to find array in data that matches target
    for (const [key, value] of Object.entries(data)) {
      if (Array.isArray(value)) {
        return key;
      }
    }
    return null;
  }

  /**
   * Check if schema is flat
   * @private
   */
  _isFlat(schema) {
    for (const value of Object.values(schema)) {
      if (typeof value === 'object') {
        // Arrays and nested objects both make schema non-flat
        return false;
      }
    }
    return true;
  }

  /**
   * Check if keys match (handles different naming conventions)
   * @private
   */
  _keysMatch(key1, key2) {
    // Exact match
    if (key1 === key2) return true;

    // Case-insensitive match
    if (key1.toLowerCase() === key2.toLowerCase()) return true;

    // taskId → id (for task object)
    if (key1 === 'taskId' && key2 === 'id') return true;

    return false;
  }

  /**
   * Find array key in schema
   * @private
   */
  _findArrayKey(schema) {
    for (const [key, value] of Object.entries(schema)) {
      if (Array.isArray(value)) {
        return key;
      }
    }
    return null;
  }

  /**
   * Validate data against schema
   * @private
   */
  _validate(data, schema) {
    for (const [key, rules] of Object.entries(schema)) {
      if (typeof rules === 'object' && rules.type) {
        if (rules.required && !(key in data)) {
          throw new Error(`Validation failed: missing required field ${key}`);
        }
      } else if (typeof rules === 'object') {
        // Nested validation
        if (!(key in data) || !data[key]) {
          // Check if any nested field is required
          const hasRequired = this._hasRequiredFields(rules);
          if (hasRequired) {
            throw new Error(`Validation failed: missing required object ${key}`);
          }
        } else {
          this._validate(data[key], rules);
        }
      }
    }
  }

  /**
   * Check if schema has required fields
   * @private
   */
  _hasRequiredFields(schema) {
    for (const [, rules] of Object.entries(schema)) {
      if (typeof rules === 'object' && rules.required) {
        return true;
      }
      if (typeof rules === 'object') {
        if (this._hasRequiredFields(rules)) {
          return true;
        }
      }
    }
    return false;
  }

class ResultStreamer extends EventEmitter {
  constructor(options = {}) {
    super();
    this.bufferSize = options.bufferSize || 10;
    this.continueOnError = options.continueOnError || false;
    this.filter = options.filter || null;
    this.transform = options.transform || null;
    this.parallel = options.parallel || false;
    this.maxConcurrent = options.maxConcurrent || 3;
    this.closed = false;
  }

  /**
   * Stream workflow results
   */
  async *stream(workflow, options = {}) {
    this.closed = false;
    const { signal } = options;

    if (this.parallel) {
      yield* this._streamParallel(workflow, signal);
    } else {
      yield* this._streamSequential(workflow, signal);
    }

    this.closed = true;
  }

  /**
   * Stream results sequentially
   */
  async *_streamSequential(workflow, signal) {
    for (const phase of workflow.phases) {
      // Check abort signal
      if (signal?.aborted) {
        throw new DOMException('Stream aborted', 'AbortError');
      }

      try {
        // Emit progress
        this.emit('progress', { phase: phase.name, status: 'executing' });

        // Execute phase
        const result = await phase.execute();

        // Apply filter
        if (this.filter && !this.filter(result)) {
          continue;
        }

        // Apply transform
        const finalResult = this.transform ? this.transform(result) : result;

        // Yield result
        yield finalResult;

        // Emit progress
        this.emit('progress', { phase: phase.name, status: 'completed', result: finalResult });
      } catch (error) {
        if (this.continueOnError) {
          yield error;
        } else {
          throw error;
        }
      }
    }
  }

  /**
   * Stream results in parallel with concurrency control
   */
  async *_streamParallel(workflow, signal) {
    const queue = [...workflow.phases];
    const executing = new Set();
    const results = [];

    while (queue.length > 0 || executing.size > 0) {
      // Check abort signal
      if (signal?.aborted) {
        throw new DOMException('Stream aborted', 'AbortError');
      }

      // Start new tasks up to maxConcurrent
      while (queue.length > 0 && executing.size < this.maxConcurrent) {
        const phase = queue.shift();
        const task = this._executePhase(phase);
        executing.add(task);

        task.then(
          result => {
            executing.delete(task);
            results.push(result);
          },
          error => {
            executing.delete(task);
            if (this.continueOnError) {
              results.push(error);
            }
          }
        );
      }

      // Wait for at least one task to complete
      if (executing.size > 0) {
        await Promise.race(executing);
      }

      // Yield all completed results
      while (results.length > 0) {
        const result = results.shift();

        // Apply filter
        if (this.filter && !this.filter(result)) {
          continue;
        }

        // Apply transform
        const finalResult = this.transform ? this.transform(result) : result;
        yield finalResult;
      }
    }
  }

  /**
   * Execute phase
   */
  async _executePhase(phase) {
    this.emit('progress', { phase: phase.name, status: 'executing' });

    try {
      const result = await phase.execute();
      this.emit('progress', { phase: phase.name, status: 'completed', result });
      return result;
    } catch (error) {
      this.emit('progress', { phase: phase.name, status: 'failed', error });
      throw error;
    }
  }

  /**
   * Check if stream is closed
   */
  isClosed() {
    return this.closed;
  }

class LegacyAdapter {
  constructor(system, version) {
    this.system = system;
    this.version = version;
  }

  /**
   * Get system name
   */
  getSystem() {
    return this.system;
  }

  /**
   * Get system version
   */
  getVersion() {
    return this.version;
  }

  /**
   * Transform request data (new → legacy format)
   * @param {Object} data - Request data in new format
   * @returns {Object} Request data in legacy format
   */
  request(data) {
    if (!data) {
      throw new Error('Invalid request');
    }

    // conductor-main specific transformation
    if (this.system === 'conductor-main') {
      return this._transformToConductorMain(data);
    }

    // intermediate system transformation
    if (this.system === 'intermediate') {
      return this._transformToIntermediate(data);
    }

    // agent-studio (passthrough)
    return data;
  }

  /**
   * Transform response data (legacy → new format)
   * @param {Object} data - Response data in legacy format
   * @returns {Object} Response data in new format
   */
  response(data) {
    if (!data) {
      return null;
    }

    // conductor-main specific transformation
    if (this.system === 'conductor-main') {
      return this._transformFromConductorMain(data);
    }

    // agent-studio (passthrough)
    return data;
  }

  /**
   * Transform error (legacy → standard format)
   * @param {Object} error - Error in legacy format
   * @returns {Object} Error in standard format
   */
  error(error) {
    return {
      status: error.code || 500,
      message: error.message || 'Unknown error',
    };
  }

  /**
   * Transform to conductor-main format
   * new: { task: { id: '123', name: 'task1' } }
   * legacy: { taskId: '123', taskName: 'task1' }
   */
  _transformToConductorMain(data) {
    if (data.task) {
      return {
        taskId: data.task.id,
        taskName: data.task.name,
      };
    }
    return data;
  }

  /**
   * Transform from conductor-main format
   * legacy: { taskId: '123', status: 'completed' }
   * new: { task: { id: '123', status: 'completed' } }
   */
  _transformFromConductorMain(data) {
    if (data.taskId) {
      return {
        task: {
          id: data.taskId,
          status: data.status,
        },
      };
    }
    return data;
  }

  /**
   * Transform to intermediate format
   * input: { taskId: '123' }
   * output: { id: '123' }
   */
  _transformToIntermediate(data) {
    if (data.taskId) {
      return { id: data.taskId };
    }
    return data;
  }

class LazyLoader {
  constructor(workflow) {
    this.workflow = workflow;
    this.loadedPhases = new Set();
    this.dependencyGraph = null;
    this.dependencyGraphBuilt = false;
  }

  /**
   * Load a specific phase and its dependencies
   */
  loadPhase(phaseName) {
    // Build dependency graph if not already built
    if (!this.dependencyGraphBuilt) {
      this.buildDependencyGraph();
    }

    // Check for circular dependencies
    const visited = new Set();
    const stack = new Set();
    if (this._hasCycle(phaseName, visited, stack)) {
      throw new Error(`Circular dependency detected involving phase: ${phaseName}`);
    }

    // Load phase and all its dependencies
    this._loadPhaseRecursive(phaseName);
  }

  /**
   * Recursively load phase and its dependencies
   */
  _loadPhaseRecursive(phaseName) {
    if (this.loadedPhases.has(phaseName)) {
      return; // Already loaded
    }

    const phase = this.workflow.phases.find(p => p.name === phaseName);
    if (!phase) {
      throw new Error(`Phase not found: ${phaseName}`);
    }

    // Load dependencies first
    if (phase.dependsOn) {
      const deps = Array.isArray(phase.dependsOn) ? phase.dependsOn : [phase.dependsOn];
      for (const dep of deps) {
        this._loadPhaseRecursive(dep);
      }
    }

    // Load this phase
    this.loadedPhases.add(phaseName);
  }

  /**
   * Detect cycles using DFS
   */
  _hasCycle(phaseName, visited, stack) {
    if (stack.has(phaseName)) {
      return true; // Cycle detected
    }

    if (visited.has(phaseName)) {
      return false; // Already checked, no cycle
    }

    visited.add(phaseName);
    stack.add(phaseName);

    const phase = this.workflow.phases.find(p => p.name === phaseName);
    if (phase && phase.dependsOn) {
      const deps = Array.isArray(phase.dependsOn) ? phase.dependsOn : [phase.dependsOn];
      for (const dep of deps) {
        if (this._hasCycle(dep, visited, stack)) {
          return true;
        }
      }
    }

    stack.delete(phaseName);
    return false;
  }

  /**
   * Unload a phase to free memory
   */
  unloadPhase(phaseName) {
    this.loadedPhases.delete(phaseName);
  }

  /**
   * Build dependency graph (O(V+E) complexity)
   */
  buildDependencyGraph() {
    if (this.dependencyGraphBuilt) {
      return this.dependencyGraph; // Return cached
    }

    this.dependencyGraph = new Map();

    for (const phase of this.workflow.phases) {
      const deps = phase.dependsOn
        ? Array.isArray(phase.dependsOn)
          ? phase.dependsOn
          : [phase.dependsOn]
        : [];
      this.dependencyGraph.set(phase.name, deps);
    }

    this.dependencyGraphBuilt = true;
    return this.dependencyGraph;
  }

  /**
   * Get dependency graph (cached)
   */
  getDependencyGraph() {
    if (!this.dependencyGraphBuilt) {
      this.buildDependencyGraph();
    }
    return this.dependencyGraph;
  }

  /**
   * Add phase dynamically
   */
  addPhase(phase) {
    this.workflow.phases.push(phase);
    // Invalidate dependency graph cache
    this.dependencyGraphBuilt = false;
    this.dependencyGraph = null;
  }

  /**
   * Get all phases (both loaded and unloaded)
   */
  getAllPhases() {
    return this.workflow.phases;
  }

  /**
   * Get loaded phases
   */
  getLoadedPhases() {
    return Array.from(this.loadedPhases);
  }

  /**
   * Get count of loaded phases
   */
  getLoadedPhasesCount() {
    return this.loadedPhases.size;
  }

  /**
   * Get total phases count
   */
  getTotalPhasesCount() {
    return this.workflow.phases.length;
  }

  /**
   * Calculate memory savings from lazy loading
   *
   * Returns: percentage of memory saved (0-1)
   */
  calculateMemorySavings() {
    const totalPhases = this.getTotalPhasesCount();
    const loadedPhases = this.getLoadedPhasesCount();

    if (totalPhases === 0) return 0;

    return (totalPhases - loadedPhases) / totalPhases;
  }

class LoopExecutor {
  async forEach(items, task, options = {}) {
    const {
      parallel = false,
      maxConcurrency = items.length,
      continueOnError = false,
      supportBreak = false,
      supportContinue = false,
      context = null,
      onProgress = null,
      measureTime = false,
    } = options;

    const results = [];
    const errors = [];
    const timings = [];

    if (parallel) {
      return this._forEachParallel(items, task, maxConcurrency, continueOnError, onProgress);
    }

    // Sequential
    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      const itemContext = context ? { ...context, item, index: i } : { item, index: i };

      try {
        const startTime = Date.now();
        const result = await task(itemContext);
        const duration = Date.now() - startTime;

        // Preserve context mutations
        if (context) {
          Object.assign(context, itemContext);
        }

        if (supportBreak && result && result.break) {
          break;
        }
        if (supportContinue && result && result.continue) {
          continue;
        }

        results.push(result);
        if (measureTime) timings.push(duration);
      } catch (error) {
        if (!continueOnError) {
          throw error;
        }
        errors.push(error);
      }

      if (onProgress) {
        onProgress(i + 1, items.length);
      }
    }

    if (measureTime) {
      return { results, timings };
    }

    if (continueOnError) {
      return { successes: results, errors };
    }

    return results;
  }

  async _forEachParallel(items, task, maxConcurrency, continueOnError, onProgress) {
    const results = [];
    const errors = [];
    const running = new Set();
    let index = 0;

    return new Promise(resolve => {
      const execute = async () => {
        while (index < items.length) {
          if (running.size >= maxConcurrency) {
            await Promise.race(running);
            continue;
          }

          const i = index++;
          const item = items[i];
          const itemContext = { item, index: i };

          const promise = (async () => {
            try {
              const result = await task(itemContext);
              results[i] = result;
            } catch (error) {
              if (continueOnError) {
                errors[i] = error;
              } else {
                throw error;
              }
            }

            if (onProgress) {
              onProgress(i + 1, items.length);
            }
          })();

          running.add(promise);
          promise.finally(() => running.delete(promise));
        }

        if (running.size > 0) {
          await Promise.all(running);
        }

        if (continueOnError) {
          resolve({
            successes: results.filter(r => r !== undefined),
            errors: errors.filter(e => e !== undefined),
          });
        } else {
          resolve(results);
        }
      };

      execute().catch(err => {
        throw err;
      });
    });
  }

  async doWhile(condition, task, options = {}) {
    const { maxIterations = null, onCheckpoint = null } = options;

    if (maxIterations === null || maxIterations === undefined) {
      throw new Error('maxIterations is required to prevent infinite loops');
    }

    const capped = Math.min(maxIterations, SYSTEM_MAX_ITERATIONS);

    let state = { iteration: 0, iterations: 0 };
    let conditionMet = true;

    for (let i = 0; i < capped && conditionMet; i++) {
      state.iteration = i;
      state.iterations = i + 1;

      const result = await task(state);
      state = { ...state, ...result };

      if (onCheckpoint) {
        onCheckpoint(state);
      }

      conditionMet = condition(state);
    }

    return state;
  }

  async retryUntil(successCondition, task, options = {}) {
    const { maxRetries = 3, backoff = 'linear', initialDelay = 100 } = options;

    const cappedRetries = Math.min(maxRetries, SYSTEM_MAX_ITERATIONS);

    let attempts = 0;
    let lastResult = null;

    for (let i = 0; i < cappedRetries; i++) {
      attempts++;
      lastResult = await task();

      if (successCondition(lastResult)) {
        return { success: true, result: lastResult, attempts };
      }

      if (i < cappedRetries - 1) {
        const delay = this._calculateBackoff(backoff, i, initialDelay);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }

    return { success: false, result: lastResult, attempts: cappedRetries };
  }

  _calculateBackoff(backoff, attempt, initialDelay) {
    if (backoff === 'exponential') {
      return initialDelay * Math.pow(2, attempt);
    } else if (backoff === 'linear') {
      return initialDelay * (attempt + 1);
    }
    return initialDelay;
  }

  async forEachBatch(items, task, options = {}) {
    const { batchSize = 10 } = options;
    const results = [];

    for (let i = 0; i < items.length; i += batchSize) {
      const batch = items.slice(i, i + batchSize);
      const result = await task(batch);
      results.push(result);
    }

    return results;
  }

class MemoryBudgeter extends EventEmitter {
  constructor(options = {}) {
    super();
    this.maxMemory = options.maxMemory || 1024 * 1024 * 1024; // 1GB default
    this.warnThreshold = options.warnThreshold || 0.8; // Warn at 80%
    this.allocations = new Map(); // workflow name -> allocated bytes
    this.reserved = 0; // Reserved memory for critical workflows
  }

  /**
   * Allocate memory for workflow
   */
  allocate(workflowName, workflow) {
    const estimatedMemory = this._calculateEstimatedMemory(workflow);

    const totalAllocated = this.getTotalAllocated();
    const available = this.maxMemory - totalAllocated - this.reserved;

    if (estimatedMemory > available) {
      throw new Error(
        `Memory budget exceeded: workflow requires ${this._formatBytes(estimatedMemory)}, ` +
          `but only ${this._formatBytes(available)} available (total budget: ${this._formatBytes(this.maxMemory)})`
      );
    }

    this.allocations.set(workflowName, estimatedMemory);

    // Check warning threshold
    const newTotal = totalAllocated + estimatedMemory;
    const utilization = newTotal / this.maxMemory;

    if (utilization >= this.warnThreshold) {
      this.emit('warning', {
        message: `Memory usage at ${(utilization * 100).toFixed(1)}%`,
        allocated: newTotal,
        budget: this.maxMemory,
        utilization,
      });
    }
  }

  /**
   * Release memory for workflow
   */
  release(workflowName) {
    this.allocations.delete(workflowName);
  }

  /**
   * Get allocated memory for workflow
   */
  getAllocated(workflowName) {
    return this.allocations.get(workflowName) || 0;
  }

  /**
   * Get total allocated memory across all workflows
   */
  getTotalAllocated() {
    return Array.from(this.allocations.values()).reduce((sum, mem) => sum + mem, 0);
  }

  /**
   * Set maximum memory budget
   */
  setMaxMemory(bytes) {
    this.maxMemory = bytes;
  }

  /**
   * Reserve memory for critical workflows
   */
  reserve(name, bytes) {
    this.reserved += bytes;
  }

  /**
   * Get memory statistics
   */
  getStats() {
    const totalAllocated = this.getTotalAllocated();
    return {
      totalAllocated,
      totalBudget: this.maxMemory,
      reserved: this.reserved,
      availableMemory: this.maxMemory - totalAllocated - this.reserved,
      utilizationPercentage: (totalAllocated / this.maxMemory) * 100,
    };
  }

  /**
   * Get active workflows
   */
  getActiveWorkflows() {
    return Array.from(this.allocations.keys());
  }

  /**
   * Calculate estimated memory for workflow
   */
  _calculateEstimatedMemory(workflow) {
    if (!workflow.phases) return 0;

    return workflow.phases.reduce((total, phase) => {
      return total + (phase.estimatedMemory || 0);
    }, 0);
  }

  /**
   * Format bytes for human-readable output
   */
  _formatBytes(bytes) {
    const mb = bytes / 1024 / 1024;
    return `${mb.toFixed(2)}MB`;
  }

function generateTransactionId() {
  return `tx-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
}

function validateValue(value) {
  if (value === null || value === undefined) {
    throw new Error('Invalid value: null/undefined not allowed');
  }
}

function validateConstraints(key, value, currentState) {
  // Constraint: stepIndex must be >= 0
  if (key === 'stepIndex' && typeof value === 'number' && value < 0) {
    throw new Error('Constraint violation: stepIndex must be >= 0');
  }

  // Constraint: phase transitions must be sequential
  if (key === 'phase' && currentState.phase) {
    const phasePattern = /phase-(\d+)/;
    const currentMatch = currentState.phase.match(phasePattern);
    const newMatch = String(value).match(phasePattern);

    if (currentMatch && newMatch) {
      const currentPhase = parseInt(currentMatch[1], 10);
      const newPhase = parseInt(newMatch[1], 10);

      // Allow same phase or next phase only
      if (newPhase !== currentPhase && newPhase !== currentPhase + 1) {
        throw new Error(`Inconsistent phase transition: ${currentState.phase} -> ${value}`);
      }
    }
  }
}

class TransactionalStateManager {
  /**
   * Create a new TransactionalStateManager
   *
   * @param {CheckpointManager} checkpointManager - Optional checkpoint manager
   * @param {string} journalPath - Path to transaction journal
   * @param {Object} options - Configuration options
   */
  constructor(checkpointManager = null, journalPath = null, options = {}) {
    this.checkpointManager = checkpointManager;
    this.journalPath =
      journalPath || path.join(__dirname, '../../context/workflows/transactions.jsonl');
    this.options = {
      timeout: options.timeout || DEFAULT_TIMEOUT,
      checkpointInterval: options.checkpointInterval || DEFAULT_CHECKPOINT_INTERVAL,
    };

    // In-memory transaction state
    this.transactions = new Map(); // txId -> { workflowId, writes: [], savepoints: {}, startTime, version }
    this.committedState = new Map(); // workflowId -> { state: {}, version: number }
    this.commitCounter = new Map(); // workflowId -> number

    // Ensure journal directory exists
    if (this.journalPath) {
      const dir = path.dirname(this.journalPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
    }
  }

  /**
   * Begin a new transaction
   *
   * @param {string} workflowId - Workflow identifier
   * @param {Object} options - Transaction options
   * @returns {string} Transaction ID
   */
  async beginTransaction(workflowId, options = {}) {
    const txId = generateTransactionId();
    const currentVersion = this.committedState.get(workflowId)?.version || 0;

    this.transactions.set(txId, {
      id: txId,
      workflowId,
      writes: [],
      savepoints: {},
      startTime: Date.now(),
      version: currentVersion,
      timeout: options.timeout || this.options.timeout,
    });

    // Write BEGIN to journal (WAL)
    await this._writeJournalEntry({
      transactionId: txId,
      workflowId,
      status: 'pending',
      timestamp: new Date().toISOString(),
      writes: [],
    });

    return txId;
  }

  /**
   * Set state within a transaction (buffered write)
   *
   * @param {string} txId - Transaction ID
   * @param {string} key - State key
   * @param {*} value - State value
   */
  async setState(txId, key, value) {
    const tx = this.transactions.get(txId);
    if (!tx) {
      throw new Error(`Transaction not found: ${txId}`);
    }

    // Check timeout
    if (Date.now() - tx.startTime > tx.timeout) {
      throw new Error(`Transaction timeout expired: ${txId}`);
    }

    // Validate value
    validateValue(value);

    // Get current state for constraint validation
    const currentState = this.committedState.get(tx.workflowId)?.state || {};
    validateConstraints(key, value, currentState);

    // Buffer write (not applied yet)
    tx.writes.push({ key, value, timestamp: Date.now() });
  }

  /**
   * Get buffered writes for a transaction
   *
   * @param {string} txId - Transaction ID
   * @returns {Array} Buffered writes
   */
  async getBufferedWrites(txId) {
    const tx = this.transactions.get(txId);
    if (!tx) {
      throw new Error(`Transaction not found: ${txId}`);
    }
    return tx.writes.slice(); // Return copy
  }

  /**
   * Get state value (reads committed state, not buffered writes)
   *
   * @param {string} txId - Transaction ID
   * @param {string} key - State key
   * @returns {*} State value
   */
  async getState(txId, key) {
    const tx = this.transactions.get(txId);
    if (!tx) {
      throw new Error(`Transaction not found: ${txId}`);
    }

    const committed = this.committedState.get(tx.workflowId);
    return committed?.state[key] || null;
  }

  /**
   * Commit transaction (apply buffered writes atomically)
   *
   * @param {string} txId - Transaction ID
   * @returns {Object} Commit result
   */
  async commit(txId) {
    const tx = this.transactions.get(txId);
    if (!tx) {
      throw new Error(`Transaction not found: ${txId}`);
    }

    try {
      // Check for conflicts (optimistic concurrency control - key-level granularity)
      const currentVersion = this.committedState.get(tx.workflowId)?.version || 0;

      // Simple approach: Only conflict if same keys written
      // (More sophisticated: track per-key versions, but not needed for GREEN phase)
      // For now, allow concurrent commits if version difference is 1 or less
      if (currentVersion > tx.version + 1) {
        throw new Error(`Write conflict detected: concurrent modification`);
      }

      // Apply all writes atomically
      const newState = { ...(this.committedState.get(tx.workflowId)?.state || {}) };
      for (const write of tx.writes) {
        newState[write.key] = write.value;
      }

      const newVersion = currentVersion + 1;

      // Update committed state
      this.committedState.set(tx.workflowId, {
        state: newState,
        version: newVersion,
      });

      // Write COMMIT to journal
      await this._writeJournalEntry({
        transactionId: txId,
        workflowId: tx.workflowId,
        status: 'committed',
        timestamp: new Date().toISOString(),
        writes: tx.writes,
        version: newVersion,
      });

      // Checkpoint integration
      if (this.checkpointManager) {
        const commitCount = (this.commitCounter.get(tx.workflowId) || 0) + 1;
        this.commitCounter.set(tx.workflowId, commitCount);

        // Always create checkpoint to ensure latest state is recoverable
        await this.checkpointManager.save(tx.workflowId, {
          phase: newState.phase || 'unknown',
          stepIndex: newState.stepIndex || 0,
          context: newState,
          workflowVersion: '1.0.0',
          metadata: { transactionVersion: newVersion },
        });
      }

      // Cleanup transaction
      this.transactions.delete(txId);

      return {
        success: true,
        writesApplied: tx.writes.length,
        version: newVersion,
      };
    } catch (err) {
      // Auto-rollback on error (silently - transaction already in error state)
      try {
        await this.rollback(txId);
      } catch (_rollbackErr) {
        // Ignore rollback errors, propagate original error
      }
      throw err;
    }
  }

  /**
   * Rollback transaction (discard buffered writes)
   *
   * @param {string} txId - Transaction ID
   * @returns {Object} Rollback result
   */
  async rollback(txId) {
    const tx = this.transactions.get(txId);
    if (!tx) {
      throw new Error(`Transaction not found: ${txId}`);
    }

    const writesDiscarded = tx.writes.length;

    // Write ROLLBACK to journal
    await this._writeJournalEntry({
      transactionId: txId,
      workflowId: tx.workflowId,
      status: 'rolled_back',
      timestamp: new Date().toISOString(),
      writes: tx.writes,
    });

    // Cleanup transaction
    this.transactions.delete(txId);

    return {
      success: true,
      writesDiscarded,
    };
  }

  /**
   * Create a savepoint within a transaction
   *
   * @param {string} txId - Transaction ID
   * @param {string} savepointName - Savepoint name
   */
  async savepoint(txId, savepointName) {
    const tx = this.transactions.get(txId);
    if (!tx) {
      throw new Error(`Transaction not found: ${txId}`);
    }

    // Save current write count as savepoint
    tx.savepoints[savepointName] = tx.writes.length;
    return { success: true };
  }

  /**
   * Rollback to a savepoint
   *
   * @param {string} txId - Transaction ID
   * @param {string} savepointName - Savepoint name
   */
  async rollbackToSavepoint(txId, savepointName) {
    const tx = this.transactions.get(txId);
    if (!tx) {
      throw new Error(`Transaction not found: ${txId}`);
    }

    const savepointIndex = tx.savepoints[savepointName];
    if (savepointIndex === undefined) {
      throw new Error(`Savepoint not found: ${savepointName}`);
    }

    // Discard writes after savepoint
    tx.writes = tx.writes.slice(0, savepointIndex);
    return { success: true };
  }

  /**
   * Get transaction history for a workflow
   *
   * @param {string} workflowId - Workflow identifier
   * @param {Object} options - Query options
   * @returns {Array} Transaction history entries
   */
  async getTransactionHistory(workflowId, options = {}) {
    if (!this.journalPath || !fs.existsSync(this.journalPath)) {
      return [];
    }

    const content = await fs.promises.readFile(this.journalPath, 'utf8');
    const lines = content.trim().split(JOURNAL_LINE_DELIMITER).filter(Boolean);

    const entries = [];
    for (const line of lines) {
      try {
        const entry = JSON.parse(line);
        if (entry.workflowId === workflowId) {
          // Only include committed or rolled_back (skip pending)
          if (entry.status !== 'pending') {
            // Apply filters
            if (options.transactionId && entry.transactionId !== options.transactionId) {
              continue;
            }
            if (options.after && entry.timestamp <= options.after) {
              continue;
            }
            entries.push(entry);
          }
        }
      } catch (_err) {
        // Skip corrupted entries
        console.warn('[state-transaction-manager] Skipping corrupted journal entry');
      }
    }

    return entries;
  }

  /**
   * Recover workflow from crash (replay journal)
   *
   * @param {string} workflowId - Workflow identifier
   * @returns {Object} Recovery result
   */
  async recoverFromCrash(workflowId) {
    // Read ALL journal entries (including pending) for full history
    if (!this.journalPath || !fs.existsSync(this.journalPath)) {
      return {
        transactions: 0,
        rolledBack: 0,
        errors: 0,
        state: {},
      };
    }

    const content = await fs.promises.readFile(this.journalPath, 'utf8');
    const lines = content.trim().split(JOURNAL_LINE_DELIMITER).filter(Boolean);

    let transactionCount = 0;
    let rolledBackCount = 0;
    let errorCount = 0;
    const recoveredState = {};

    for (const line of lines) {
      try {
        const entry = JSON.parse(line);
        if (entry.workflowId !== workflowId) continue;

        if (entry.status === 'committed') {
          // Replay committed transaction
          for (const write of entry.writes) {
            recoveredState[write.key] = write.value;
          }
          transactionCount++;
        } else if (entry.status === 'pending') {
          // Rollback in-progress transaction (crashed during transaction)
          rolledBackCount++;
        } else if (entry.status === 'rolled_back') {
          // Already rolled back, skip
          continue;
        }
      } catch (err) {
        errorCount++;
        console.warn('[state-transaction-manager] Error replaying transaction:', err.message);
      }
    }

    // Update committed state
    if (transactionCount > 0) {
      const version = transactionCount;
      this.committedState.set(workflowId, {
        state: recoveredState,
        version,
      });
    }

    return {
      transactions: transactionCount,
      rolledBack: rolledBackCount,
      errors: errorCount,
      state: recoveredState,
    };
  }

  /**
   * Truncate journal (keep last N entries)
   *
   * @param {string} workflowId - Workflow identifier
   * @param {Object} options - Truncation options
   */
  async truncateJournal(workflowId, options = {}) {
    const keep = options.keep || 100;

    const history = await this.getTransactionHistory(workflowId);
    if (history.length <= keep) {
      return; // Nothing to truncate
    }

    // Keep last N entries
    const toKeep = history.slice(-keep);

    // Read all journal entries
    const content = await fs.promises.readFile(this.journalPath, 'utf8');
    const lines = content.trim().split(JOURNAL_LINE_DELIMITER).filter(Boolean);

    // Filter to keep only relevant entries
    const keepIds = new Set(toKeep.map(e => e.transactionId));
    const filteredLines = [];

    for (const line of lines) {
      try {
        const entry = JSON.parse(line);
        if (entry.workflowId !== workflowId || keepIds.has(entry.transactionId)) {
          filteredLines.push(line);
        }
      } catch (_err) {
        // Keep non-JSON lines
        filteredLines.push(line);
      }
    }

    // Rewrite journal
    await fs.promises.writeFile(
      this.journalPath,
      filteredLines.join(JOURNAL_LINE_DELIMITER) + JOURNAL_LINE_DELIMITER,
      'utf8'
    );
  }

  /**
   * Write entry to transaction journal (WAL)
   *
   * @private
   */
  async _writeJournalEntry(entry) {
    if (!this.journalPath) return;

    const line = JSON.stringify(entry) + JOURNAL_LINE_DELIMITER;
    await fs.promises.appendFile(this.journalPath, line, 'utf8');
  }

class StateValidator {
  constructor(options = {}) {
    this.schemas = options.schemas || {};
  }

  async validate(state, data) {
    const schema = this.schemas[state];
    if (!schema) return true;

    // Handle custom validator
    if (schema.custom) {
      const result = await schema.custom(data);
      if (!result) {
        throw new Error('Custom validator failed');
      }
      return true;
    }

    // Handle required fields
    if (schema.required) {
      for (const field of schema.required) {
        if (!data.metadata || !(field in data.metadata)) {
          throw new Error(`Validation failed: missing required field ${field}`);
        }
      }
    }

    // Handle property validation
    if (schema.properties && data.metadata) {
      for (const [key, propSchema] of Object.entries(schema.properties)) {
        if (key in data.metadata) {
          const value = data.metadata[key];

          // Type check
          if (propSchema.type && typeof value !== propSchema.type) {
            throw new Error(`Validation failed: ${key} must be ${propSchema.type}`);
          }

          // Minimum check
          if (propSchema.minimum !== undefined && value < propSchema.minimum) {
            throw new Error(`Validation failed: ${key} must be >= ${propSchema.minimum}`);
          }
        }
      }
    }

    return true;
  }

class StranglerFig {
  constructor() {
    this.features = new Map();
    this.metrics = new Map();
  }

  /**
   * Register a feature for gradual migration
   * @param {string} featureName - Feature identifier
   * @param {Object} config - Configuration
   * @param {Function} config.legacyFn - Legacy implementation
   * @param {Function} config.newFn - New implementation
   * @param {number} config.percentage - Percentage routed to new (0-100)
   * @param {boolean} config.fallbackOnError - Fallback to legacy on error
   * @param {boolean} config.fallbackToNew - Fallback to new on legacy error
   * @param {string} config.featureFlag - Feature flag name
   * @param {Object} config.retryConfig - Retry configuration
   * @param {Object} config.circuitBreaker - Circuit breaker config
   * @param {number} config.timeout - Execution timeout
   * @param {Function} config.degradedFn - Degraded mode function
   * @param {Function} config.onError - Error callback
   * @param {Object} config.responseSchema - Response validation schema
   */
  register(featureName, config) {
    this.features.set(featureName, {
      legacyFn: config.legacyFn,
      newFn: config.newFn,
      percentage: config.percentage || 0,
      fallbackOnError: config.fallbackOnError || false,
      fallbackToNew: config.fallbackToNew || false,
      featureFlag: config.featureFlag || null,
      retryConfig: config.retryConfig || null,
      circuitBreaker: config.circuitBreaker || null,
      timeout: config.timeout || null,
      degradedFn: config.degradedFn || null,
      onError: config.onError || null,
      responseSchema: config.responseSchema || null,
      circuitState: { failures: 0, open: false },
    });

    this.metrics.set(featureName, {
      legacyCalls: 0,
      newCalls: 0,
      fallbacks: 0,
      errors: 0,
      errorTypes: [],
    });
  }

  /**
   * Execute feature (routes to legacy or new based on configuration)
   */
  async execute(featureName, args) {
    const config = this.features.get(featureName);
    if (!config) {
      throw new Error(`Feature ${featureName} not registered`);
    }

    const metrics = this.metrics.get(featureName);
    const useNew = this._shouldUseNew(config);

    // Check circuit breaker
    if (config.circuitBreaker && config.circuitState.open) {
      // Circuit is open, use fallback
      return this._executeFallback(config, args, metrics, useNew);
    }

    try {
      if (useNew) {
        metrics.newCalls++;
        const result = await this._executeWithTimeout(config.newFn, args, config.timeout);
        this._validateResponse(result, config.responseSchema, config, args, metrics);
        this._resetCircuitBreaker(config);
        return result;
      } else {
        metrics.legacyCalls++;
        const result = await this._executeWithRetry(
          config.legacyFn,
          args,
          config.retryConfig,
          config.timeout
        );
        this._validateResponse(result, config.responseSchema, config, args, metrics);
        this._resetCircuitBreaker(config);
        return result;
      }
    } catch (error) {
      metrics.errors++;
      metrics.errorTypes.push(error.message);

      if (config.onError) {
        config.onError(error);
      }

      // Update circuit breaker
      if (config.circuitBreaker) {
        config.circuitState.failures++;
        if (config.circuitState.failures >= config.circuitBreaker.threshold) {
          config.circuitState.open = true;
          setTimeout(() => {
            config.circuitState.open = false;
            config.circuitState.failures = 0;
          }, config.circuitBreaker.timeout);
        }
      }

      // Try fallback
      if (useNew && config.fallbackOnError) {
        try {
          metrics.fallbacks++;
          return await config.legacyFn(...args);
        } catch (fallbackError) {
          // Fallback also failed, try degraded mode
          if (config.degradedFn) {
            return config.degradedFn(...args);
          }
          throw fallbackError;
        }
      } else if (!useNew && config.fallbackToNew) {
        try {
          metrics.fallbacks++;
          return await config.newFn(...args);
        } catch (fallbackError) {
          // Fallback also failed, try degraded mode
          if (config.degradedFn) {
            return config.degradedFn(...args);
          }
          throw fallbackError;
        }
      }

      // No fallback configured, try degraded mode
      if (config.degradedFn) {
        return config.degradedFn(...args);
      }

      throw error;
    }
  }

  /**
   * Execute with timeout
   */
  async _executeWithTimeout(fn, args, timeout) {
    if (!timeout) {
      return fn(...args);
    }

    return Promise.race([
      fn(...args),
      new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), timeout)),
    ]);
  }

  /**
   * Execute with retry
   */
  async _executeWithRetry(fn, args, retryConfig, timeout) {
    if (!retryConfig) {
      return this._executeWithTimeout(fn, args, timeout);
    }

    const { maxRetries, backoff } = retryConfig;
    let lastError;

    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        return await this._executeWithTimeout(fn, args, timeout);
      } catch (error) {
        lastError = error;
        if (attempt < maxRetries - 1) {
          const delay = backoff === 'exponential' ? Math.pow(2, attempt) * 100 : 100;
          await new Promise(resolve => setTimeout(resolve, delay));
        }
      }
    }

    throw lastError;
  }

  /**
   * Validate response against schema
   */
  _validateResponse(result, schema, _config, _args, _metrics) {
    if (!schema) return;

    const validate = (data, schemaToValidate) => {
      for (const [key, rules] of Object.entries(schemaToValidate)) {
        if (rules.required && !(key in data)) {
          throw new Error(`Validation failed: missing required field ${key}`);
        }
      }
    };

    validate(result, schema);
  }

  /**
   * Execute fallback when circuit is open
   */
  async _executeFallback(config, args, metrics, useNew) {
    if (useNew) {
      // Circuit open for new, use legacy
      metrics.legacyCalls++;
      return config.legacyFn(...args);
    } else {
      // Circuit open for legacy, use new
      metrics.newCalls++;
      return config.newFn(...args);
    }
  }

  /**
   * Reset circuit breaker on success
   */
  _resetCircuitBreaker(config) {
    if (config.circuitBreaker) {
      config.circuitState.failures = 0;
    }
  }

  /**
   * Determine if new system should be used
   */
  _shouldUseNew(config) {
    if (config.featureFlag) {
      // Use feature flag (mock implementation)
      return false;
    }

    if (config.percentage >= 100) return true;
    if (config.percentage <= 0) return false;

    return Math.random() * 100 < config.percentage;
  }

  /**
   * Set migration percentage for a feature
   */
  async setPercentage(featureName, percentage) {
    const config = this.features.get(featureName);
    if (!config) {
      throw new Error(`Feature ${featureName} not registered`);
    }
    config.percentage = percentage;
  }

  /**
   * Get migration progress (0-100)
   */
  getMigrationProgress(featureName) {
    const config = this.features.get(featureName);
    if (!config) return 0;
    return config.percentage;
  }

  /**
   * Get feature owner ('legacy' or 'new')
   */
  getOwner(featureName) {
    const progress = this.getMigrationProgress(featureName);
    return progress >= 100 ? 'new' : 'legacy';
  }

  /**
   * Gradually ramp up percentage over duration
   */
  async rampUp(featureName, targetPercentage, duration) {
    const config = this.features.get(featureName);
    if (!config) {
      throw new Error(`Feature ${featureName} not registered`);
    }

    const startPercentage = config.percentage;
    const steps = 5;
    const increment = (targetPercentage - startPercentage) / steps;
    const interval = duration / steps;

    for (let i = 0; i < steps; i++) {
      await new Promise(resolve => setTimeout(resolve, interval));
      config.percentage = Math.min(targetPercentage, startPercentage + increment * (i + 1));
    }
  }

  /**
   * Get feature flag for a feature
   */
  getFeatureFlag(featureName) {
    const config = this.features.get(featureName);
    return config ? config.featureFlag : null;
  }

  /**
   * List all registered features
   */
  listFeatures() {
    return Array.from(this.features.keys());
  }

  /**
   * Deregister a feature
   */
  deregister(featureName) {
    this.features.delete(featureName);
    this.metrics.delete(featureName);
  }

  /**
   * Get metrics for a feature
   */
  getMetrics(featureName) {
    return (
      this.metrics.get(featureName) || {
        legacyCalls: 0,
        newCalls: 0,
        fallbacks: 0,
        errors: 0,
        errorTypes: [],
      }
    );
  }

class ResultNormalizer {
  constructor(config = {}) {
    this.preserveOriginal = config.preserveOriginal || false;
    this.metadataMapping = config.metadataMapping || {
      // Legacy (snake_case) → Standard (camelCase)
      task_id: 'taskId',
      created_at: 'createdAt',
      updated_at: 'updatedAt',
      error_message: 'errorMessage',
      error_code: 'errorCode',
      error_stack: 'errorStack',
      nested_data: 'nestedData',
      user_id: 'userId',
      created_by: 'createdBy',
    };

    // Status mapping from legacy to standard
    this.statusMapping = {
      success: 'completed',
      running: 'in_progress',
      failed: 'failed',
      pending: 'pending',
    };

    // Error code categories
    this.errorCategories = {
      TIMEOUT: 'timeout',
      EXEC_ERROR: 'execution',
      VALIDATION_ERROR: 'validation',
      AUTH_ERROR: 'authentication',
      NETWORK_ERROR: 'network',
    };
  }

  /**
   * Normalize legacy result to standard format
   * @param {Object} legacyResult - Result in legacy format
   * @param {string} [source] - Source system ('conductor-main' or 'agent-studio')
   * @returns {Object} Result in standard format
   */
  normalize(legacyResult, _source = 'conductor-main') {
    if (!legacyResult) return null;

    const normalized = {};

    // Store original if configured
    if (this.preserveOriginal) {
      normalized._original = { ...legacyResult };
    }

    // Map standard fields
    if (legacyResult.task_id) normalized.taskId = legacyResult.task_id;
    if (legacyResult.created_at) normalized.createdAt = legacyResult.created_at;

    // Map status/state
    if (legacyResult.state) {
      normalized.status = this.statusMapping[legacyResult.state] || legacyResult.state;
    }
    if (legacyResult.status) {
      normalized.status = legacyResult.status;
    }

    // Map output to result
    if (legacyResult.output !== undefined) {
      normalized.result = legacyResult.output;
    }

    // Handle nested result structures (preserve snake_case in nested data)
    if (normalized.result && typeof normalized.result === 'object') {
      // Keep nested data as-is (don't transform nested keys)
      normalized.result = this._preserveNestedStructure(normalized.result);
    }

    // Normalize error structure
    if (legacyResult.error_message || legacyResult.error_code || legacyResult.state === 'failed') {
      normalized.error = {
        message: legacyResult.error_message,
        code: legacyResult.error_code,
      };

      // Add stack trace if present
      if (legacyResult.error_stack) {
        normalized.error.stack = legacyResult.error_stack;
      }

      // Categorize error
      if (legacyResult.error_code) {
        normalized.error.category = this.errorCategories[legacyResult.error_code] || 'unknown';
      }
    }

    // Handle partial results (task failed but has output)
    if (legacyResult.state === 'failed' && legacyResult.output) {
      normalized.partialResult = legacyResult.output;
    }

    // Normalize metadata (meta field in legacy, metadata in output)
    if (legacyResult.meta) {
      normalized.metadata = this._normalizeMetadata(legacyResult.meta);
    } else {
      normalized.metadata = {};
    }

    // Preserve any additional metadata
    if (legacyResult.metadata) {
      normalized.metadata = { ...normalized.metadata, ...legacyResult.metadata };
    }

    return normalized;
  }

  /**
   * Normalize metadata object (convert known snake_case keys to camelCase, preserve unknown keys)
   */
  _normalizeMetadata(meta) {
    if (!meta || typeof meta !== 'object') return {};

    // Known metadata field mappings
    const knownMappings = {
      user_id: 'userId',
      created_by: 'createdBy',
      updated_by: 'updatedBy',
      created_at: 'createdAt',
      updated_at: 'updatedAt',
    };

    const normalized = {};
    for (const [key, value] of Object.entries(meta)) {
      // Map known fields, preserve unknown fields as-is
      const mappedKey = knownMappings[key] || key;
      normalized[mappedKey] = value;
    }
    return normalized;
  }

  /**
   * Preserve nested structure without transformation
   */
  _preserveNestedStructure(data) {
    if (Array.isArray(data)) {
      return data.map(item => this._preserveNestedStructure(item));
    }
    if (data !== null && typeof data === 'object') {
      const result = {};
      for (const [key, value] of Object.entries(data)) {
        result[key] = this._preserveNestedStructure(value);
      }
      return result;
    }
    return data;
  }

  /**
   * Normalize nested data structures recursively
   */
  _normalizeNested(data) {
    if (Array.isArray(data)) {
      return data.map(item => this._normalizeNested(item));
    }

    if (typeof data === 'object' && data !== null) {
      const normalized = {};
      for (const [key, value] of Object.entries(data)) {
        const standardKey = this.metadataMapping[key] || key;
        normalized[standardKey] = this._normalizeNested(value);
      }
      return normalized;
    }

    return data;
  }

  /**
   * Normalize partial result (task failed but has partial data)
   */
  normalizePartial(legacyResult) {
    const normalized = this.normalize(legacyResult);

    // Mark as partial
    normalized.partial = true;
    normalized.completionPercentage = legacyResult.completion_percentage || 0;

    return normalized;
  }

  /**
   * Aggregate results from multiple tasks (returns array of normalized results)
   */
  aggregate(results) {
    if (!results || results.length === 0) return null;

    // Get task ID from first result
    const taskId = results[0].task_id || results[0].taskId;

    return {
      taskId,
      status: 'completed',
      result: results.map(r => this.normalize(r, 'conductor-main').result || r.output),
    };
  }

  /**
   * Aggregate results from multiple tasks (legacy API)
   */
  aggregateResults(results) {
    if (!results || results.length === 0) return null;

    const aggregated = {
      taskCount: results.length,
      results: results.map(r => this.normalize(r)),
      summary: {
        successful: 0,
        failed: 0,
        partial: 0,
      },
    };

    for (const result of aggregated.results) {
      if (result.error) {
        aggregated.summary.failed++;
      } else if (result.partial) {
        aggregated.summary.partial++;
      } else {
        aggregated.summary.successful++;
      }
    }

    return aggregated;
  }

  /**
   * Convert standard result back to legacy format
   */
  denormalize(standardResult) {
    if (!standardResult) return null;

    const legacy = {};

    // Reverse metadata mapping (camelCase → snake_case)
    const reverseMapping = {};
    for (const [legacyKey, standardKey] of Object.entries(this.metadataMapping)) {
      reverseMapping[standardKey] = legacyKey;
    }

    // Map fields back to legacy format
    for (const [key, value] of Object.entries(standardResult)) {
      const legacyKey = reverseMapping[key] || key;
      legacy[legacyKey] = value;
    }

    // Denormalize error structure
    if (standardResult.error) {
      legacy.error_message = standardResult.error.message;
      legacy.error_code = standardResult.error.code;
      delete legacy.error;
    }

    // Handle nested data
    if (standardResult.nestedData) {
      legacy.nested_data = this._denormalizeNested(standardResult.nestedData);
      delete legacy.nestedData;
    }

    return legacy;
  }

  /**
   * Denormalize nested structures recursively
   */
  _denormalizeNested(data) {
    if (Array.isArray(data)) {
      return data.map(item => this._denormalizeNested(item));
    }

    if (typeof data === 'object' && data !== null) {
      const denormalized = {};
      const reverseMapping = {};
      for (const [legacyKey, standardKey] of Object.entries(this.metadataMapping)) {
        reverseMapping[standardKey] = legacyKey;
      }

      for (const [key, value] of Object.entries(data)) {
        const legacyKey = reverseMapping[key] || key;
        denormalized[legacyKey] = this._denormalizeNested(value);
      }
      return denormalized;
    }

    return data;
  }

  /**
   * Get normalization statistics
   */
  getStats() {
    return {
      mappingCount: Object.keys(this.metadataMapping).length,
    };
  }

class HybridExecutor {
  constructor(config = {}) {
    this.router = new TaskRouter({
      rules: config.rules || [],
      defaultSystem: config.defaultSystem || 'agent-studio',
    });
    this.syncManager = new StateSyncManager({
      strategy: config.conflictStrategy || 'last-write-wins',
      primarySystem: config.primarySystem || 'agent-studio',
    });
    this.normalizer = new ResultNormalizer();
    this.conflictStrategy = config.conflictStrategy || 'last-write-wins';

    // Track execution state
    this.executionHistory = [];
  }

  /**
   * Get adapter for a specific system
   */
  adapter(systemName) {
    return SystemAdapters.getAdapter(systemName);
  }

  /**
   * Execute a task with hybrid routing
   */
  async execute(task) {
    const taskId = task.taskId || `task-${Date.now()}`;
    const startTime = Date.now();

    // Route the task
    const routingDecision = await this.router.route(task);
    let executedBy = routingDecision.system;
    let fallbackChain = null;
    let fallbackReason = null;

    // Check if router already handled fallback
    if (routingDecision.reason === 'fallback_on_error') {
      const originalSystem = routingDecision.metadata?.originalSystem || 'agent-studio';
      fallbackChain = [originalSystem, routingDecision.system];
      fallbackReason = `${originalSystem}-unhealthy`;
    }
    // Check system health and fallback if needed (for cases router didn't handle)
    else if (task.systemHealth && task.systemHealth[routingDecision.system] === 'unhealthy') {
      // Find fallback from rules or use opposite system
      const rule = this.router.rules.find(r => r.system === routingDecision.system);
      const fallbackSystem =
        rule?.fallback ||
        (routingDecision.system === 'agent-studio' ? 'conductor-main' : 'agent-studio');

      fallbackChain = [routingDecision.system, fallbackSystem];
      executedBy = fallbackSystem;
      fallbackReason = `${routingDecision.system}-unhealthy`;
    }

    // Simulate execution (or skip if mockExecution)
    let result;
    if (!task.mockExecution) {
      result = await this._executeOnSystem(executedBy, task, taskId);
    } else {
      result = { taskId, status: 'completed', executedBy };
    }

    // Sync state to both systems
    await this.syncManager.pushToSystem('agent-studio', {
      taskId,
      status: 'completed',
      result: result.result,
    });
    await this.syncManager.pushToSystem('conductor-main', {
      taskId,
      status: 'completed',
      result: result.result,
    });

    // Record execution
    this.executionHistory.push({
      taskId,
      executedBy,
      duration: Date.now() - startTime,
      fallbackChain: fallbackChain || undefined,
      fallbackReason: fallbackReason || undefined,
    });

    return {
      taskId,
      status: 'completed',
      executedBy,
      result: result.result,
      fallbackChain: fallbackChain || undefined,
      fallbackReason: fallbackReason || undefined,
    };
  }

  /**
   * Execute a multi-step workflow
   */
  async executeWorkflow(workflow) {
    const steps = workflow.steps || [];
    const results = [];

    for (const step of steps) {
      // Determine system for this step
      const system = step.system || (await this.router.route({ path: step.path })).system;

      // Execute step
      const result = await this._executeOnSystem(system, step, step.path);

      results.push({
        path: step.path,
        executedBy: system,
        status: result.status || 'completed',
        result: result.result,
      });
    }

    return {
      steps: results,
      status: 'completed',
    };
  }

  /**
   * Execute on a specific system
   */
  async _executeOnSystem(system, task, taskId) {
    // For testing, just return success
    return {
      taskId,
      status: 'completed',
      result: task.payload,
    };
  }

  /**
   * Get state from a specific system (returns in system's native format)
   */
  async getStateFrom(systemName, taskId) {
    const adapter = SystemAdapters.getAdapter(systemName);
    const state = await adapter.readState(taskId);

    // For conductor-main, translate to its native format
    if (systemName === 'conductor-main' && state) {
      return adapter.translateToSystem(state);
    }

    return state;
  }

  /**
   * Reconcile diverged state between systems
   */
  async reconcileState(taskId) {
    // Read directly from adapters (they store in their own format)
    const agentAdapter = SystemAdapters.getAdapter('agent-studio');
    const conductorAdapter = SystemAdapters.getAdapter('conductor-main');

    const agentState = await agentAdapter.readState(taskId);
    const conductorState = await conductorAdapter.readState(taskId);

    // Handle null states (adapter returns default state for unknown taskId)
    const hasAgentState = agentState && agentState.status !== 'pending';
    const hasConductorState = conductorState && conductorState.status !== 'pending';

    if (!hasAgentState && !hasConductorState) {
      return null;
    }

    // If both have state, check for conflicts
    if (hasAgentState && hasConductorState) {
      const clockA = agentState.vectorClock || 0;
      const clockC = conductorState.vectorClock || 0;

      // Concurrent conflict (same vector clock, different status)
      if (clockA === clockC && agentState.status !== conductorState.status) {
        if (this.conflictStrategy === 'manual') {
          return {
            _conflict: {
              agentStudio: agentState.status,
              conductorMain: conductorState.status,
              type: 'concurrent_update',
            },
          };
        }
      }

      // Resolve based on vector clock
      const resolved = clockA >= clockC ? agentState : conductorState;

      // Sync resolved state to both systems (write to each adapter)
      await agentAdapter.writeState(resolved);
      await conductorAdapter.writeState(resolved);

      return resolved;
    }

    // Only one system has state
    const existing = hasAgentState ? agentState : conductorState;
    await agentAdapter.writeState(existing);
    await conductorAdapter.writeState(existing);

    return existing;
  }

  /**
   * Get execution metrics
   */
  getMetrics() {
    return {
      totalExecutions: this.executionHistory.length,
      fallbackCount: this.executionHistory.filter(e => e.fallbackChain).length,
      averageDuration:
        this.executionHistory.length > 0
          ? this.executionHistory.reduce((sum, e) => sum + e.duration, 0) /
            this.executionHistory.length
          : 0,
    };
  }

  /**
   * SPEC-019: Route task using config (routing_rules, default_system)
   * @param {Object} task - Task to route
   * @param {Object} config - { routing_rules, default_system, enabled }
   * @returns {Promise<Object>} { system, reason }
   */
  async routeTask(task, config = {}) {
    const enabled = config.enabled !== false;
    if (!enabled) {
      return {
        system: config.default_system || this.router.defaultSystem,
        reason: 'hybrid_disabled',
      };
    }
    const decision = await this.router.route({
      ...task,
      path: task.path || task.taskId,
    });
    return {
      system: decision.system,
      reason: decision.reason || 'rule_match',
      metadata: decision.metadata,
    };
  }

  /**
   * SPEC-019: Sync state for a task between systems (bi-directional, conflict resolution)
   * @param {string} taskId - Task id
   * @returns {Promise<Object|null>} Resolved state or null
   */
  async syncState(taskId) {
    return this.reconcileState(taskId);
  }

  /**
   * SPEC-019: Normalize result from source system to common format
   * @param {Object} result - Raw result
   * @param {string} sourceSystem - 'conductor-main' | 'agent-studio'
   * @returns {Object} Normalized result
   */
  translateResult(result, sourceSystem) {
    return this.normalizer.normalize(result, sourceSystem);
  }

function safeEvaluateCondition(condition, context) {
  // Handle null/undefined condition
  if (!condition || typeof condition !== 'string') {
    return {
      passed: false,
      error: 'Condition must be a non-empty string',
      blocked: true,
    };
  }

  const normalizedCondition = condition.trim();

  // Look up the condition in predefined safe conditions
  const evaluator = SAFE_CONDITIONS[normalizedCondition];

  if (!evaluator) {
    return {
      passed: false,
      error: `Unknown condition: "${normalizedCondition}". Use predefined conditions only.`,
      blocked: true,
    };
  }

  try {
    // Safely get steps from context, handling null/undefined
    const steps = context?.steps || {};
    // Pass both steps and full context to evaluator (for context.* conditions)
    const result = evaluator(steps, context);
    return { passed: Boolean(result) };
  } catch (e) {
    return {
      passed: false,
      error: `Evaluation error: ${e.message}`,
    };
  }
}

