  }

  const result = spawnSync(process.execPath, [GENERATOR_PATH], {
    cwd: PROJECT_ROOT,
    stdio: 'inherit',
    env: { ...process.env },
  });

  return result.status !== undefined ? result.status : result.signal ? 1 : 0;
