function getCandidateFiles() {
  const override = process.env.CONSOLE_LOG_CHECK_FILES;
  if (override) {
    return override
      .split(',')
      .map(item => item.trim())
      .filter(Boolean);
  }

  try {
    execSync('git rev-parse --git-dir', { cwd: PROJECT_ROOT, stdio: 'pipe' });
  } catch (_err) {
    return [];
  }

  try {
    const output = execSync('git diff --name-only HEAD', {
      cwd: PROJECT_ROOT,
      encoding: 'utf8',
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    return output
      .split('\n')
      .map(line => line.trim())
      .filter(line => line.length > 0);
  } catch (_err) {
    return [];
  }
}

function filterScriptFiles(files) {
  return files.filter(file => /\.(ts|tsx|js|jsx)$/.test(file));
}

function resolveFilePath(file) {
  if (path.isAbsolute(file)) return file;
  return path.join(PROJECT_ROOT, file);
}

function scanForConsoleLogs(files) {
  let hasConsole = false;

  for (const file of files) {
    const filePath = resolveFilePath(file);
    if (!fs.existsSync(filePath)) continue;
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      if (content.includes('console.log')) {
        console.error(`[Hook] WARNING: console.log found in ${file}`);
        hasConsole = true;
      }
    } catch (_err) {
      // ignore unreadable files
    }
  }

  if (hasConsole) {
    console.error('[Hook] Remove console.log statements before committing');
  }
}

function main() {
  const files = filterScriptFiles(getCandidateFiles());
  scanForConsoleLogs(files);
  process.exit(0);
}

class WorkflowVersioner {
  constructor() {
    this.registry = new Map(); // workflowId -> Map(version -> metadata)
    this.activeVersions = new Map(); // workflowId -> activeVersion
  }

  /**
   * Parse semantic version string to components
   * @param {string} versionString - Version string (e.g., "2.1.3")
   * @returns {object} Parsed version { major, minor, patch, string }
   */
  parseVersion(versionString) {
    const parts = versionString.split('.');
    return {
      major: parseInt(parts[0], 10),
      minor: parseInt(parts[1], 10),
      patch: parseInt(parts[2], 10),
      string: versionString,
    };
  }

  /**
   * Compare two versions
   * @param {string} v1 - First version
   * @param {string} v2 - Second version
   * @returns {number} -1 if v1 < v2, 0 if equal, 1 if v1 > v2
   */
  compareVersions(v1, v2) {
    const parsed1 = this.parseVersion(v1);
    const parsed2 = this.parseVersion(v2);

    if (parsed1.major !== parsed2.major) {
      return parsed1.major < parsed2.major ? -1 : 1;
    }
    if (parsed1.minor !== parsed2.minor) {
      return parsed1.minor < parsed2.minor ? -1 : 1;
    }
    if (parsed1.patch !== parsed2.patch) {
      return parsed1.patch < parsed2.patch ? -1 : 1;
    }
    return 0;
  }

  /**
   * Check if version satisfies constraint (semver range)
   * @param {string} version - Version to check
   * @param {string} constraint - Constraint (e.g., ">=2.0.0", "^2.0.0")
   * @returns {boolean} True if satisfies
   */
  satisfies(version, constraint) {
    const parsed = this.parseVersion(version);

    // Handle >= constraint
    if (constraint.startsWith('>=')) {
      const minVersion = constraint.substring(2);
      return this.compareVersions(version, minVersion) >= 0;
    }

    // Handle ^ constraint (caret: compatible with same major version)
    if (constraint.startsWith('^')) {
      const baseVersion = constraint.substring(1);
      const baseParsed = this.parseVersion(baseVersion);

      // Same major version
      if (parsed.major !== baseParsed.major) {
        return false;
      }

      // Greater or equal minor/patch
      return this.compareVersions(version, baseVersion) >= 0;
    }

    // Exact match
    return version === constraint;
  }

  /**
   * Detect if upgrade is a breaking change (major version increment)
   * @param {string} fromVersion - Old version
   * @param {string} toVersion - New version
   * @returns {boolean} True if breaking change
   */
  isBreakingChange(fromVersion, toVersion) {
    const from = this.parseVersion(fromVersion);
    const to = this.parseVersion(toVersion);

    return to.major > from.major;
  }

  /**
   * Register workflow version with metadata
   * @param {string} workflowId - Workflow identifier
   * @param {string} version - Version string
   * @param {object} metadata - Version metadata
   */
  async register(workflowId, version, metadata) {
    if (!this.registry.has(workflowId)) {
      this.registry.set(workflowId, new Map());
    }

    const versions = this.registry.get(workflowId);
    versions.set(version, {
      version,
      ...metadata,
    });
  }

  /**
   * Get version metadata
   * @param {string} workflowId - Workflow identifier
   * @param {string} version - Version string
   * @returns {object} Version metadata
   */
  get(workflowId, version) {
    const versions = this.registry.get(workflowId);
    return versions ? versions.get(version) : null;
  }

  /**
   * List all versions for workflow (sorted)
   * @param {string} workflowId - Workflow identifier
   * @returns {string[]} Sorted version strings
   */
  listVersions(workflowId) {
    const versions = this.registry.get(workflowId);
    if (!versions) return [];

    return Array.from(versions.keys()).sort((a, b) => this.compareVersions(a, b));
  }

  /**
   * Get latest version for workflow
   * @param {string} workflowId - Workflow identifier
   * @returns {object} Latest version metadata
   */
  getLatest(workflowId) {
    const versions = this.listVersions(workflowId);
    if (versions.length === 0) return null;

    const latestVersion = versions[versions.length - 1];
    return this.get(workflowId, latestVersion);
  }

  /**
   * Set active version (for blue-green deployment)
   * @param {string} workflowId - Workflow identifier
   * @param {string} version - Version to set as active
   */
  async setActive(workflowId, version) {
    this.activeVersions.set(workflowId, version);
  }

  /**
   * Get active version (defaults to latest)
   * @param {string} workflowId - Workflow identifier
   * @returns {object} Active version metadata
   */
  getActive(workflowId) {
    const activeVersion = this.activeVersions.get(workflowId);
    if (activeVersion) {
      return this.get(workflowId, activeVersion);
    }

    // Default to latest
    return this.getLatest(workflowId);
  }

  /**
   * Check backward compatibility
   * @param {string} workflowId - Workflow identifier
   * @param {string} oldVersion - Old version
   * @param {string} newVersion - New version
   * @returns {boolean} True if backward compatible
   */
  isBackwardCompatible(workflowId, oldVersion, newVersion) {
    const newMeta = this.get(workflowId, newVersion);
    if (!newMeta || !newMeta.minCompatibleVersion) {
      // No constraint means no compatibility guarantee
      return false;
    }

    return this.compareVersions(oldVersion, newMeta.minCompatibleVersion) >= 0;
  }

  /**
   * Check if state can be migrated from old version
   * @param {object} state - Workflow state
   * @param {string} toVersion - Target version
   * @returns {boolean} True if migration possible
   */
  canMigrate(state, toVersion) {
    // Extract workflow ID from state or use default
    const workflowId = state.workflowId || 'feature-dev'; // TODO: Better extraction

    return this.isBackwardCompatible(workflowId, state.workflowVersion, toVersion);
  }

  /**
   * Calculate upgrade path (list of required migrations)
   * @param {string} workflowId - Workflow identifier
   * @param {string} fromVersion - Starting version
   * @param {string} toVersion - Target version
   * @returns {object[]} Migration steps
   */
  getUpgradePath(workflowId, fromVersion, toVersion) {
    // Check if downgrade
    if (this.compareVersions(fromVersion, toVersion) > 0) {
      throw new Error('Downgrade not supported without rollback migration');
    }

    const path = [];
    const versions = this.listVersions(workflowId);

    // Find versions between from and to
    for (const version of versions) {
      if (
        this.compareVersions(version, fromVersion) > 0 &&
        this.compareVersions(version, toVersion) <= 0
      ) {
        const meta = this.get(workflowId, version);
        if (meta.migrations) {
          path.push(...meta.migrations);
        }
      }
    }

    return path;
  }

class WorkflowValidator {
  /**
   * Validate complete workflow structure
   * @param {string|object} workflowOrPath - Workflow object or path to YAML file
   * @param {object} options - Validation options
   *   - maxNestingDepth: Maximum allowed nesting depth (default: 10)
   *   - returnErrors: If true, return {valid, errors} instead of throwing (default: false)
   * @returns {object|void} - Returns {valid, errors} if returnErrors=true, otherwise throws on error
   */
  async validate(workflowOrPath, options = {}) {
    const { maxNestingDepth = 10, returnErrors = false } = options;

    // Handle file path input
    let workflow = workflowOrPath;
    if (typeof workflowOrPath === 'string') {
      try {
        const content = fs.readFileSync(workflowOrPath, 'utf8');
        workflow = yaml.parse(content);
      } catch (err) {
        if (returnErrors) {
          return { valid: false, errors: [`Failed to read workflow file: ${err.message}`] };
        }
        throw err;
      }
    }

    if (returnErrors) {
      // Collect validation errors instead of throwing
      const errors = [];

      try {
        this._validateStructure(workflow);
      } catch (err) {
        errors.push(err.message);
      }

      try {
        this._validatePhases(workflow, maxNestingDepth);
      } catch (err) {
        errors.push(err.message);
      }

      try {
        this._validateVariables(workflow);
      } catch (err) {
        errors.push(err.message);
      }

      // Also validate step schema
      const stepResult = this.validateStepSchema(workflow);
      if (!stepResult.valid) {
        errors.push(...stepResult.errors);
      }

      // Workflow requirements (if not abstract and has phases)
      if (!workflow.abstract && workflow.phases) {
        if (Array.isArray(workflow.phases) && workflow.phases.length === 0) {
          errors.push('Workflow must have at least one phase');
        }

        if (Array.isArray(workflow.phases)) {
          for (const phase of workflow.phases) {
            if (!phase.subphases && (!phase.tasks || phase.tasks.length === 0)) {
              errors.push(`Phase '${phase.name}' must have at least one task`);
            }
          }
        }
      }

      return { valid: errors.length === 0, errors };
    }

    // Original throwing behavior (default)
    this._validateStructure(workflow);
    this._validatePhases(workflow, maxNestingDepth);
    this._validateVariables(workflow);

    // Workflow requirements
    if (!workflow.abstract) {
      if (!workflow.phases || workflow.phases.length === 0) {
        throw new Error('Workflow must have at least one phase');
      }

      for (const phase of workflow.phases) {
        if (!phase.subphases && (!phase.tasks || phase.tasks.length === 0)) {
          throw new Error(`Phase '${phase.name}' must have at least one task`);
        }
      }
    }
  }

  /**
   * Validate workflow structure
   */
  _validateStructure(workflow) {
    if (!workflow.name) {
      throw new Error("Workflow must have a name (missing 'name' field)");
    }

    if (!Array.isArray(workflow.phases) && !workflow.abstract) {
      throw new Error('Workflow must have a phases array (or be marked abstract)');
    }
  }

  /**
   * Validate phases
   */
  _validatePhases(workflow, maxNestingDepth = 10) {
    if (!workflow.phases) return;

    for (const phase of workflow.phases) {
      // All phases must have a name (includes are handled at composition time)
      if (!phase.name) {
        throw new Error('Phase is missing a name field');
      }

      // Validate subphase nesting depth (phase is at level 1, its subphases at level 2, etc.)
      if (phase.subphases) {
        this._validateNestingDepth(phase.subphases, 2, maxNestingDepth);
      }
    }
  }

  /**
   * Validate nesting depth
   */
  _validateNestingDepth(phases, currentDepth, maxDepth) {
    if (currentDepth > maxDepth) {
      throw new Error(`Nesting depth exceeded: maximum ${maxDepth} levels allowed`);
    }

    for (const phase of phases) {
      if (phase.subphases) {
        this._validateNestingDepth(phase.subphases, currentDepth + 1, maxDepth);
      }
    }
  }

  /**
   * Validate variables are defined
   */
  _validateVariables(workflow) {
    if (!workflow.phases) return;

    const variables = workflow.variables || {};
    const definedVars = new Set(Object.keys(variables));

    for (const phase of workflow.phases) {
      if (!phase.tasks) continue;

      for (const task of phase.tasks) {
        const matches = task.match(/{{(\w+)}}/g) || [];
        for (const match of matches) {
          const varName = match.replace(/[{}]/g, '');
          if (!definedVars.has(varName)) {
            throw new Error(
              `Phase '${phase.name}': undefined variable '{{${varName}}}' in task '${task}'`
            );
          }
        }
      }
    }
  }

  /**
   * Validate dependencies are satisfied
   */
  async validateDependencies(workflow) {
    if (!workflow.phases) return;

    const phaseNames = new Set();
    for (const phase of workflow.phases) {
      if (phase.name) {
        phaseNames.add(phase.name);
      }
    }

    // Check phase dependencies
    for (const phase of workflow.phases) {
      if (phase.dependsOn) {
        const deps = Array.isArray(phase.dependsOn) ? phase.dependsOn : [phase.dependsOn];
        for (const dep of deps) {
          if (!phaseNames.has(dep)) {
            throw new Error(`Phase '${phase.name}' dependency not found: '${dep}'`);
          }
        }
      }
    }

    // Check for circular phase dependencies
    this._validateNoCyclicDependencies(workflow.phases);
  }

  /**
   * Check for cycles in phase dependencies
   */
  _validateNoCyclicDependencies(phases) {
    const phaseMap = new Map();
    for (const phase of phases) {
      phaseMap.set(phase.name, phase);
    }

    const visited = new Set();
    const stack = new Set();

    for (const phase of phases) {
      if (!visited.has(phase.name)) {
        this._checkPhaseCycle(phase.name, phaseMap, visited, stack);
      }
    }
  }

  /**
   * DFS to check for cycles in phase dependencies
   */
  _checkPhaseCycle(phaseName, phaseMap, visited, stack) {
    if (stack.has(phaseName)) {
      throw new Error(`Circular dependency detected in phase: ${phaseName}`);
    }

    if (visited.has(phaseName)) {
      return;
    }

    stack.add(phaseName);
    const phase = phaseMap.get(phaseName);

    if (phase && phase.dependsOn) {
      const deps = Array.isArray(phase.dependsOn) ? phase.dependsOn : [phase.dependsOn];
      for (const dep of deps) {
        this._checkPhaseCycle(dep, phaseMap, visited, stack);
      }
    }

    stack.delete(phaseName);
    visited.add(phaseName);
  }

  /**
   * Validate workflow is executable (not abstract)
   */
  async validateForExecution(workflow) {
    if (workflow.abstract) {
      throw new Error(
        'Abstract workflows cannot be executed directly. Create a concrete child workflow.'
      );
    }
  }

  /**
   * Validate step schema in workflow
   * Checks that all steps have required fields: id, and either handler or action
   */
  validateStepSchema(workflow) {
    const errors = [];

    if (!workflow.phases) {
      return { valid: true, errors: [] };
    }

    // Iterate through all phases
    for (const [phaseName, phase] of Object.entries(workflow.phases)) {
      if (!phase.steps) continue;

      // Validate each step
      for (let i = 0; i < phase.steps.length; i++) {
        const step = phase.steps[i];
        const stepNum = i + 1; // Use 1-indexed step numbers for human-readable errors

        // Check for required 'id' field
        if (!step.id) {
          errors.push(`Phase '${phaseName}', Step ${stepNum}: missing 'id' field`);
        }

        // Check for either 'handler' or 'action' field
        if (!step.handler && !step.action) {
          errors.push(`Phase '${phaseName}', Step ${stepNum}: missing 'handler' or 'action' field`);
        }
      }
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }

function setGlobalPackageManager(pmName) {
  const homeDir = os.homedir();
  const configDir = path.join(homeDir, '.claude');
  const configPath = path.join(configDir, 'package-manager.json');

  if (!fs.existsSync(configDir)) {
    fs.mkdirSync(configDir, { recursive: true });
  }

  const config = {
    packageManager: pmName,
    setAt: new Date().toISOString(),
  };

  fs.writeFileSync(configPath, JSON.stringify(config, null, 2), 'utf8');
  console.log(`✓ Set global package manager to ${pmName}`);
  console.log(`  Config saved to: ${configPath}`);
}

function main() {
  const args = process.argv.slice(2);

  if (args.length === 0 || args[0] === '--help' || args[0] === '-h') {
    printHelp();
    process.exit(0);
  }

  if (args[0] === '--detect') {
    const pm = getPackageManager();
    console.log('\nPackage Manager Detection:');
    console.log(`  Current: ${pm.name} (${pm.source})`);
    console.log(`  Install: ${pm.config.installCmd}`);
    console.log(`  Run: ${pm.config.runCmd}`);
    console.log(`  Exec: ${pm.config.execCmd}`);
    console.log('\n' + getSelectionPrompt());
    process.exit(0);
  }

  if (args[0] === '--list') {
    const available = getAvailablePackageManagers();
    console.log('\nAvailable Package Managers:');
    available.forEach(pm => console.log(`  - ${pm}`));
    process.exit(0);
  }

  if (args[0] === '--global' && args[1]) {
    const pmName = args[1];
    if (!VALID_PMS.has(pmName)) {
      console.error(`Error: Invalid package manager: ${pmName}`);
      console.error('Valid options: npm, pnpm, yarn, bun');
      process.exit(1);
    }
    setGlobalPackageManager(pmName);
    process.exit(0);
  }

  if (args[0] === '--project' && args[1]) {
    const pmName = args[1];
    if (!VALID_PMS.has(pmName)) {
      console.error(`Error: Invalid package manager: ${pmName}`);
      console.error('Valid options: npm, pnpm, yarn, bun');
      process.exit(1);
    }
    setProjectPackageManager(pmName);
    console.log(`✓ Set project package manager to ${pmName}`);
    process.exit(0);
  }

  console.error('Error: Invalid command. Use --help for usage.');
  process.exit(1);
}

function findProjectRoot() {
  let dir = __dirname;
  while (dir !== path.parse(dir).root) {
    if (fs.existsSync(path.join(dir, '.claude', 'CLAUDE.md'))) {
      return dir;
    }
    dir = path.dirname(dir);
  }
  return process.cwd();
}

function clearCreatorActive() {
  try {
    if (!fs.existsSync(STATE_FILE)) {
      // State file doesn't exist - nothing to clear
      console.log(`[${CREATOR_NAME.toUpperCase()}] No state file found - nothing to clear`);
      return true;
    }

    // Read existing state
    let state = {};
    try {
      state = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
    } catch (_e) {
      // If file is corrupted, start fresh
      state = {};
    }

    // Clear this creator's active state
    if (state[CREATOR_NAME]) {
      state[CREATOR_NAME].active = false;
      state[CREATOR_NAME].clearedAt = new Date().toISOString();
      state[CREATOR_NAME].clearReason = result.success ? 'completed' : 'failed';
    }

    // Write updated state
    fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));
    console.log(`[${CREATOR_NAME.toUpperCase()}] State cleared in: ${STATE_FILE}`);
    return true;
  } catch (err) {
    console.error(`[${CREATOR_NAME.toUpperCase()}] Failed to clear state:`, err.message);
    return false;
  }
}

function processResult(executionResult) {
  // CRIT-002 FIX: Always clear active state, regardless of success/failure
  const stateCleared = clearCreatorActive();

  if (!stateCleared) {
    return {
      success: false,
      message: 'Failed to clear creator state',
    };
  }

  // Log completion status
  if (executionResult.success) {
    console.log(
      `[${CREATOR_NAME.toUpperCase()}] Agent created successfully: ${executionResult.artifactName || 'unknown'}`
    );
  } else {
    console.warn(
      `[${CREATOR_NAME.toUpperCase()}] Agent creation failed: ${executionResult.error || 'unknown error'}`
    );
  }

  return { success: true };
}

function isEnabled() {
  const flag = String(process.env.STRATEGIC_COMPACT_ENABLED || '').toLowerCase();
  return flag === 'true' || flag === '1' || flag === 'yes';
}

function getCounterFile() {
  if (process.env.COMPACT_COUNTER_FILE) {
    return process.env.COMPACT_COUNTER_FILE;
  }
  const sessionId = process.env.CLAUDE_SESSION_ID || String(process.ppid || 'default');
  return path.join(os.tmpdir(), `claude-tool-count-${sessionId}`);
}

function readCount(filePath) {
  try {
    if (!fs.existsSync(filePath)) return 0;
    const raw = fs.readFileSync(filePath, 'utf8').trim();
    const parsed = Number.parseInt(raw, 10);
    return Number.isFinite(parsed) ? parsed : 0;
  } catch (_err) {
    return 0;
  }
}

function writeCount(filePath, count) {
  try {
    fs.writeFileSync(filePath, String(count), 'utf8');
  } catch (err) {
    debugLog('suggest-compact', 'Failed to write counter file', err);
  }
}

function maybeSuggestCompact() {
  if (!isEnabled()) return null;

  const threshold = Number.parseInt(process.env.COMPACT_THRESHOLD || `${DEFAULT_THRESHOLD}`, 10);
  const interval = Number.parseInt(
    process.env.COMPACT_REMINDER_INTERVAL || `${DEFAULT_INTERVAL}`,
    10
  );
  const counterFile = getCounterFile();

  const current = readCount(counterFile);
  const next = current + 1;
  writeCount(counterFile, next);

  if (next === threshold) {
    return `[StrategicCompact] ${threshold} tool calls reached - consider /compact if transitioning phases`;
  }

  if (next > threshold && interval > 0 && next % interval === 0) {
    return `[StrategicCompact] ${next} tool calls - good checkpoint for /compact if context is stale`;
  }

  return null;
}

function handleHookInput(input) {
  if (!input) return;
  const toolName = getToolName(input);
  if (toolName !== 'Edit' && toolName !== 'Write' && toolName !== 'NotebookEdit') return;

  const message = maybeSuggestCompact();
  if (message) {
    console.error(message);
  }
}

