}

export function detectFromPackageJson(packageJson) {
  const frameworks = [];
  const allDeps = {
    ...packageJson.dependencies,
    ...packageJson.devDependencies,
  };

  for (const [depName, depVersion] of Object.entries(allDeps || {})) {
    if (FRAMEWORK_RULES[depName]) {
      const rule = FRAMEWORK_RULES[depName];
      frameworks.push({
        name: rule.name,
        version: cleanVersion(depVersion),
        category: rule.category,
        confidence: 1.0,
        source: 'package.json',
        ecosystem: rule.ecosystem,
      });
    }
  }

  return frameworks;
}

export function detectFromRequirementsTxt(content) {
  const frameworks = [];
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Parse package name (handle version specifiers)
    const match = trimmed.match(/^([a-zA-Z0-9_-]+)/);
    if (!match) continue;

    const packageName = match[1].toLowerCase();
    if (PYTHON_FRAMEWORKS[packageName]) {
      const rule = PYTHON_FRAMEWORKS[packageName];

      // Try to extract version
      const versionMatch = trimmed.match(/==([0-9.]+)/);
      const version = versionMatch ? versionMatch[1] : undefined;

      frameworks.push({
        name: rule.name,
        version,
        category: rule.category,
        confidence: 0.9,
        source: 'requirements.txt',
        ecosystem: rule.ecosystem,
      });
    }
  }

  return frameworks;
}

export function detectFromPyprojectToml(content) {
  const frameworks = [];

  // Simple regex-based parsing for dependencies section
  const depMatch = content.match(/\[project\.dependencies\]([\s\S]*?)(?:\[|$)/);
  if (!depMatch) return frameworks;

  const depsSection = depMatch[1];
  const lines = depsSection.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Parse package from line like: "fastapi>=0.100.0"
    const match = trimmed.match(/"([a-zA-Z0-9_-]+)/);
    if (!match) continue;

    const packageName = match[1].toLowerCase();
    if (PYTHON_FRAMEWORKS[packageName]) {
      const rule = PYTHON_FRAMEWORKS[packageName];
      frameworks.push({
        name: rule.name,
        category: rule.category,
        confidence: 0.9,
        source: 'pyproject.toml',
        ecosystem: rule.ecosystem,
      });
    }
  }

  return frameworks;
}

function cleanVersion(version) {
  return version.replace(/^[^\d]*/, '').replace(/[^\d.].*$/, '');
}

export function deduplicateFrameworks(frameworks) {
  const seen = new Map();

  for (const fw of frameworks) {
    const existing = seen.get(fw.name);
    if (!existing || fw.confidence > existing.confidence) {
      seen.set(fw.name, fw);
    }
  }

  return Array.from(seen.values());
}

export function detectFrameworks(manifests) {
  let frameworks = [];

  // Detect from package.json
  if (manifests['package.json']) {
    const pkgFrameworks = detectFromPackageJson(manifests['package.json']);
    frameworks.push(...pkgFrameworks);
  }

  // Detect from requirements.txt
  if (manifests['requirements.txt']) {
    const pyFrameworks = detectFromRequirementsTxt(manifests['requirements.txt']);
    frameworks.push(...pyFrameworks);
  }

  // Detect from pyproject.toml
  if (manifests['pyproject.toml']) {
    const pyprojectFrameworks = detectFromPyprojectToml(manifests['pyproject.toml']);
    frameworks.push(...pyprojectFrameworks);
  }

  // Deduplicate
  frameworks = deduplicateFrameworks(frameworks);

  return frameworks;
}

async function validateProjectRoot(projectRoot) {
  try {
    const stat = await fs.stat(projectRoot);
    if (!stat.isDirectory()) {
      throw new Error(`Path is not a directory: ${projectRoot}`);
    }
  } catch (error) {
    throw new Error(`Invalid project root: ${error.message}`);
  }
}

async function detectManifests(projectRoot) {
  const manifests = {};

  const manifestFiles = [
    'package.json',
    'requirements.txt',
    'pyproject.toml',
    'go.mod',
    'Cargo.toml',
    'pom.xml',
    'build.gradle',
    'composer.json',
  ];

  for (const file of manifestFiles) {
    const filePath = path.join(projectRoot, file);
    try {
      const exists = await fs
        .access(filePath)
        .then(() => true)
        .catch(() => false);
      if (exists) {
        const content = await fs.readFile(filePath, 'utf-8');
        if (file.endsWith('.json') || file.endsWith('.toml')) {
          try {
            manifests[file] = file.endsWith('.json') ? JSON.parse(content) : content;
          } catch {
            manifests[file] = content; // Keep as string if parse fails
          }
        } else {
          manifests[file] = content;
        }
      }
    } catch (_error) {
      // Skip files that can't be read
    }
  }

  return manifests;
}

async function detectProjectType(projectRoot, manifests) {
  // Check for monorepo indicators
  if (
    manifests['package.json']?.workspaces ||
    (await fileExists(projectRoot, 'pnpm-workspace.yaml')) ||
    (await fileExists(projectRoot, 'lerna.json'))
  ) {
    return 'monorepo';
  }

  // Check for mobile indicators
  if (
    (await directoryExists(projectRoot, 'android')) &&
    (await directoryExists(projectRoot, 'ios'))
  ) {
    return 'mobile';
  }

  // Check for microservices (multiple service directories)
  const rootDirs = await fs.readdir(projectRoot);
  const serviceDirs = rootDirs.filter(
    dir => dir.includes('service') || dir.includes('microservice')
  );
  if (serviceDirs.length >= 3) {
    return 'microservices';
  }

  // Check for serverless indicators
  if (
    (await fileExists(projectRoot, 'serverless.yml')) ||
    (await fileExists(projectRoot, 'serverless.yaml'))
  ) {
    return 'serverless';
  }

  // Check package.json for type indicators
  if (manifests['package.json']) {
    const pkg = manifests['package.json'];

    // CLI project
    if (pkg.bin) {
      return 'cli';
    }

    // Library project
    if (pkg.main && !pkg.scripts?.start && !pkg.scripts?.dev) {
      return 'library';
    }

    const deps = { ...pkg.dependencies, ...pkg.devDependencies };
    const hasReact = 'react' in deps;
    const hasNext = 'next' in deps;
    const hasExpress = 'express' in deps;
    const hasFastify = 'fastify' in deps;

    // Fullstack
    if ((hasNext || hasReact) && (hasExpress || hasFastify)) {
      return 'fullstack';
    }

    // Next.js is fullstack by default
    if (hasNext) {
      return 'fullstack';
    }

    // Frontend
    if (hasReact || 'vue' in deps || '@angular/core' in deps) {
      return 'frontend';
    }

    // Backend
    if (hasExpress || hasFastify || 'koa' in deps) {
      return 'backend';
    }
  }

  // Check Python manifests
  if (manifests['requirements.txt'] || manifests['pyproject.toml']) {
    const content = manifests['requirements.txt'] || manifests['pyproject.toml'];
    if (content.includes('fastapi') || content.includes('django') || content.includes('flask')) {
      return 'backend';
    }
  }

  return 'unknown';
}

