      const tsconfigPath = path.join(projectRoot, 'tsconfig.json');
      const tsconfig = JSON.parse(await fs.readFile(tsconfigPath, 'utf-8'));
      quality.type_safety.strict_mode = tsconfig.compilerOptions?.strict === true;
