  const args = process.argv.slice(2);
  const fix = args.includes('--fix');
  const strict = args.includes('--strict');
  const verbose = args.includes('--verbose');

  console.log('🔍 Scanning for orphaned skills...\n');

  // Find all skills
  const skillPaths = await glob('.claude/skills/*/SKILL.md');
  const skills = skillPaths.map(p => path.basename(path.dirname(p)));

  // Find all agents and their assigned skills
  const agentPaths = await glob('.claude/agents/**/*.md');
  const assignedSkills = new Set();
  const agentSkillMap = {};

  for (const agentPath of agentPaths) {
    try {
      const content = fs.readFileSync(agentPath, 'utf-8');
      const frontmatter = parseFrontmatter(content);
      if (frontmatter) {
        const agentName = frontmatter.name || path.basename(agentPath, '.md');
        const agentSkills = frontmatter.skills || [];

        agentSkillMap[agentName] = agentSkills;
        agentSkills.forEach(s => assignedSkills.add(s));
      }
    } catch (_e) {
      // Skip files that can't be parsed
    }
  }

  // Find orphans
  const orphans = skills.filter(s => !assignedSkills.has(s));

  // Categorize orphans
  const critical = [];
  const suggested = {};

  for (const orphan of orphans) {
    let foundMatch = false;
    for (const [pattern, agents] of Object.entries(AGENT_SKILL_MATRIX)) {
      if (new RegExp(pattern, 'i').test(orphan)) {
        suggested[orphan] = agents;
        foundMatch = true;
        break;
      }
    }
    if (!foundMatch) {
      critical.push(orphan);
    }
  }

  // Report
  console.log('📊 Summary');
  console.log('─'.repeat(50));
  console.log(`Total skills:     ${skills.length}`);
  console.log(`Assigned skills:  ${assignedSkills.size}`);
  console.log(`Orphaned skills:  ${orphans.length}`);
  console.log('');

  if (orphans.length === 0) {
    console.log('✅ All skills are assigned to at least one agent!');
    process.exit(0);
  }

  console.log('⚠️  Orphaned Skills');
  console.log('─'.repeat(50));

  // Skills with suggestions
  if (Object.keys(suggested).length > 0) {
    console.log('\n📋 Skills with suggested assignments:\n');
    for (const [skill, agents] of Object.entries(suggested)) {
      console.log(`  ${skill}`);
      console.log(`    → Suggested: ${agents.join(', ')}`);

      if (fix) {
        console.log(`    Fix: Add to ${agents[0]}.md skills array`);
      }
    }
  }

  // Skills without suggestions
  if (critical.length > 0) {
    console.log('\n❓ Skills with no automatic suggestion:\n');
    for (const skill of critical) {
      console.log(`  ${skill}`);
      console.log(`    → Review manually and assign to appropriate agent`);
    }
  }

  // Verbose: show agent assignments
  if (verbose) {
    console.log('\n📋 Current Agent Assignments:\n');
    for (const [agent, skills] of Object.entries(agentSkillMap)) {
      if (skills.length > 0) {
        console.log(`  ${agent}: ${skills.length} skills`);
      }
    }
  }

  // Fix mode: generate commands
  if (fix) {
    console.log('\n🔧 Fix Commands:\n');
    for (const [skill, agents] of Object.entries(suggested)) {
      console.log(`# Assign ${skill} to ${agents[0]}`);
      console.log(
        `node .claude/skills/skill-creator/scripts/create.cjs --assign "${skill}" --agent "${agents[0]}"`
      );
      console.log('');
    }
  }

  // Exit code
  if (strict && orphans.length > 0) {
    console.log('\n❌ Strict mode: Exiting with error due to orphaned skills');
    process.exit(1);
  }

  process.exit(0);
}

function parseArgs(args) {
  const parsed = {
    query: null,
    path: null,
    limit: DEFAULT_LIMIT,
    type: 'hybrid', // hybrid, keyword, symbol, semantic, path
    extensions: null,
    format: 'json',
    threshold: 0.3, // minimum relevance score
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--query' && args[i + 1]) {
      parsed.query = args[++i];
    } else if (arg === '--path' && args[i + 1]) {
      parsed.path = args[++i];
    } else if (arg === '--limit' && args[i + 1]) {
      parsed.limit = parseInt(args[++i], 10);
    } else if (arg === '--type' && args[i + 1]) {
      parsed.type = args[++i];
    } else if (arg === '--extensions' && args[i + 1]) {
      parsed.extensions = args[++i]
        .split(',')
        .map(e => (e.trim().startsWith('.') ? e.trim() : `.${e.trim()}`));
    } else if (arg === '--format' && args[i + 1]) {
      parsed.format = args[++i];
    } else if (arg === '--threshold' && args[i + 1]) {
      parsed.threshold = parseFloat(args[++i]);
    }
  }

  return parsed;
}

function expandQuerySemantics(query) {
  const expansions = {
    auth: ['authentication', 'authorize', 'login', 'signin', 'session', 'token', 'jwt', 'oauth'],
    authentication: ['auth', 'login', 'signin', 'credential', 'password', 'token'],
    user: ['account', 'profile', 'member', 'customer'],
    error: ['exception', 'failure', 'fault', 'bug', 'issue'],
    handle: ['process', 'manage', 'deal', 'catch'],
    database: ['db', 'storage', 'repository', 'model', 'schema'],
    api: ['endpoint', 'route', 'handler', 'controller', 'service'],
    test: ['spec', 'unittest', 'integration', 'e2e'],
    component: ['widget', 'element', 'module', 'part'],
    function: ['method', 'procedure', 'routine', 'fn'],
    class: ['type', 'interface', 'struct', 'object'],
    config: ['configuration', 'settings', 'options', 'setup'],
  };

  const keywords = extractKeywords(query);
  const expanded = new Set(keywords);

  keywords.forEach(keyword => {
    if (expansions[keyword]) {
      expansions[keyword].forEach(term => expanded.add(term));
    }
  });

  return Array.from(expanded);
}

async function scanDirectory(dirPath, extensions) {
  const files = [];

  async function scan(currentPath) {
    try {
      const entries = await readdir(currentPath, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = join(currentPath, entry.name);

        if (entry.isDirectory()) {
          // Skip excluded directories
          if (EXCLUDE_DIRS.includes(entry.name)) continue;
          await scan(fullPath);
        } else if (entry.isFile()) {
          const ext = extname(entry.name);
          if (extensions.includes(ext)) {
            try {
              const content = await readFile(fullPath, 'utf-8');
              const stats = await stat(fullPath);
              files.push({
                path: fullPath,
                relativePath: relative(PROJECT_ROOT, fullPath),
                content,
                lineCount: content.split('\n').length,
                extension: ext,
                size: stats.size,
              });
            } catch (error) {
              // Skip files that can't be read
              console.error(`Warning: Failed to read ${fullPath}: ${error.message}`);
            }
          }
        }
      }
    } catch (error) {
      // Skip directories that can't be accessed
      console.error(`Warning: Failed to scan ${currentPath}: ${error.message}`);
    }
  }

  await scan(dirPath);
  return files;
}

function extractSymbols(file) {
  const symbols = [];
  const lines = file.content.split('\n');

  lines.forEach((line, idx) => {
    const trimmed = line.trim();

    // Function declarations
    const funcMatch = trimmed.match(/(?:export\s+)?(?:async\s+)?function\s+(\w+)/);
    if (funcMatch) {
      symbols.push({
        name: funcMatch[1],
        type: 'function',
        line: idx + 1,
        signature: trimmed,
      });
    }

    // Arrow functions
    const arrowMatch = trimmed.match(
      /(?:export\s+)?(?:const|let|var)\s+(\w+)\s*=\s*(?:async\s+)?\([^)]*\)\s*=>/
    );
    if (arrowMatch) {
      symbols.push({
        name: arrowMatch[1],
        type: 'function',
        line: idx + 1,
        signature: trimmed,
      });
    }

    // Class declarations
    const classMatch = trimmed.match(/(?:export\s+)?(?:abstract\s+)?class\s+(\w+)/);
    if (classMatch) {
      symbols.push({
        name: classMatch[1],
        type: 'class',
        line: idx + 1,
        signature: trimmed,
      });
    }

    // Interface/Type declarations (TypeScript)
    const interfaceMatch = trimmed.match(/(?:export\s+)?interface\s+(\w+)/);
    if (interfaceMatch) {
      symbols.push({
        name: interfaceMatch[1],
        type: 'interface',
        line: idx + 1,
        signature: trimmed,
      });
    }

    const typeMatch = trimmed.match(/(?:export\s+)?type\s+(\w+)/);
    if (typeMatch) {
      symbols.push({
        name: typeMatch[1],
        type: 'type',
        line: idx + 1,
        signature: trimmed,
      });
    }

    // Python class/function
    if (file.extension === '.py') {
      const pyClassMatch = trimmed.match(/class\s+(\w+)/);
      if (pyClassMatch) {
        symbols.push({
          name: pyClassMatch[1],
          type: 'class',
          line: idx + 1,
          signature: trimmed,
        });
      }

      const pyFuncMatch = trimmed.match(/def\s+(\w+)/);
      if (pyFuncMatch) {
        symbols.push({
          name: pyFuncMatch[1],
          type: 'function',
          line: idx + 1,
          signature: trimmed,
        });
      }
    }
  });

  return symbols;
}

function keywordSearch(files, keywords) {
  const results = [];

  files.forEach(file => {
    const lines = file.content.split('\n');
    const lowerContent = file.content.toLowerCase();

    // Calculate keyword matches
    let matchCount = 0;
    keywords.forEach(keyword => {
      const regex = new RegExp(`\\b${keyword}\\b`, 'gi');
      const matches = lowerContent.match(regex);
      if (matches) matchCount += matches.length;
    });

    if (matchCount === 0) return;

    // Find specific line matches
    lines.forEach((line, idx) => {
      const lowerLine = line.toLowerCase();
      let lineMatchCount = 0;

      keywords.forEach(keyword => {
        if (lowerLine.includes(keyword)) lineMatchCount++;
      });

      if (lineMatchCount > 0) {
        // Get context (3 lines before and after)
        const contextStart = Math.max(0, idx - 3);
        const contextEnd = Math.min(lines.length, idx + 4);
        const context = lines.slice(contextStart, contextEnd).join('\n');

        // Calculate relevance based on keyword density
        const relevance = Math.min(1.0, lineMatchCount / keywords.length + matchCount / 100);

        results.push({
          file: file.relativePath,
          line: idx + 1,
          column: line.indexOf(keywords[0]) + 1,
          match_type: 'keyword',
          relevance_score: relevance,
          context,
          snippet: line.trim(),
          keywords_matched: keywords.filter(k => lowerLine.includes(k)),
        });
      }
    });
  });

  return results;
}

function symbolSearch(files, query) {
  const results = [];
  const queryLower = query.toLowerCase();
  const keywords = extractKeywords(query);

  files.forEach(file => {
    const symbols = extractSymbols(file);

    symbols.forEach(symbol => {
      const nameLower = symbol.name.toLowerCase();
      let matchScore = 0;

      // Exact match
      if (nameLower === queryLower) {
        matchScore = 1.0;
      }
      // Contains query
      else if (nameLower.includes(queryLower)) {
        matchScore = 0.8;
      }
      // Keyword match
      else {
        const matched = keywords.filter(k => nameLower.includes(k));
        if (matched.length > 0) {
          matchScore = 0.5 + (matched.length / keywords.length) * 0.3;
        }
      }

      if (matchScore > 0) {
        // Get context around symbol
        const lines = file.content.split('\n');
        const contextStart = Math.max(0, symbol.line - 4);
        const contextEnd = Math.min(lines.length, symbol.line + 10);
        const context = lines.slice(contextStart, contextEnd).join('\n');

        results.push({
          file: file.relativePath,
          line: symbol.line,
          column: 1,
          match_type: 'symbol',
          relevance_score: matchScore,
          context,
          snippet: symbol.signature,
          symbol: {
            name: symbol.name,
            type: symbol.type,
            signature: symbol.signature,
          },
        });
      }
    });
  });

  return results;
}

function semanticSearch(files, query) {
  const expandedTerms = expandQuerySemantics(query);
  return keywordSearch(files, expandedTerms);
}

function pathSearch(files, query) {
  const results = [];
  const queryLower = query.toLowerCase();
  const keywords = extractKeywords(query);

  files.forEach(file => {
    const pathLower = file.relativePath.toLowerCase();
    let matchScore = 0;

    // Direct path match
    if (pathLower.includes(queryLower)) {
      matchScore = 0.9;
    }
    // Keyword in path
    else {
      const matched = keywords.filter(k => pathLower.includes(k));
      if (matched.length > 0) {
        matchScore = 0.6 + (matched.length / keywords.length) * 0.3;
      }
    }

    if (matchScore > 0) {
      results.push({
        file: file.relativePath,
        line: 1,
        column: 1,
        match_type: 'path',
        relevance_score: matchScore,
        context: file.content.split('\n').slice(0, 10).join('\n'), // First 10 lines
        snippet: `File path: ${file.relativePath}`,
      });
    }
  });

  return results;
}

function hybridSearch(files, query, keywords) {
  const keywordResults = keywordSearch(files, keywords);
  const symbolResults = symbolSearch(files, query);
  const semanticResults = semanticSearch(files, query);
  const pathResults = pathSearch(files, query);

  // Merge results (deduplicate by file+line)
  const merged = new Map();

  [...keywordResults, ...symbolResults, ...semanticResults, ...pathResults].forEach(result => {
    const key = `${result.file}:${result.line}`;

    if (!merged.has(key)) {
      merged.set(key, result);
    } else {
      // Keep higher relevance score
      const existing = merged.get(key);
      if (result.relevance_score > existing.relevance_score) {
        merged.set(key, result);
      }
    }
  });

  return Array.from(merged.values());
}

function executeSearch(files, query, type) {
  const keywords = extractKeywords(query);
  const startTime = Date.now();

  let results = [];
  let strategiesUsed = [];

  switch (type) {
    case 'keyword':
      results = keywordSearch(files, keywords);
      strategiesUsed = ['keyword'];
      break;
    case 'symbol':
      results = symbolSearch(files, query);
      strategiesUsed = ['symbol'];
      break;
    case 'semantic':
      results = semanticSearch(files, query);
      strategiesUsed = ['semantic'];
      break;
    case 'path':
      results = pathSearch(files, query);
      strategiesUsed = ['path'];
      break;
    case 'hybrid':
    default:
      results = hybridSearch(files, query, keywords);
      strategiesUsed = ['keyword', 'symbol', 'semantic', 'path'];
      break;
  }

  const duration = Date.now() - startTime;

  return { results, strategiesUsed, duration };
}

function rankResults(results, limit, threshold) {
  // Sort by relevance (descending)
  const sorted = results.sort((a, b) => b.relevance_score - a.relevance_score);

  // Filter by threshold
  const filtered = sorted.filter(r => r.relevance_score >= threshold);

  // Limit results
  return filtered.slice(0, limit);
}

function calculateSummary(results, _files) {
  const topFiles = [...new Set(results.map(r => r.file))].slice(0, 5);

  const symbolTypes = new Set();
  results.forEach(r => {
    if (r.symbol) {
      symbolTypes.add(r.symbol.type);
    }
  });

  const matchTypes = new Map();
  results.forEach(r => {
    matchTypes.set(r.match_type, (matchTypes.get(r.match_type) || 0) + 1);
  });

  return {
    top_files: topFiles,
    symbol_types_found: Array.from(symbolTypes),
    match_type_distribution: Object.fromEntries(matchTypes),
    recommendations: generateRecommendations(results),
  };
}

function generateRecommendations(results) {
  const recommendations = [];

  if (results.length === 0) {
    recommendations.push('No results found. Try broadening your search query.');
  } else if (results.length < 3) {
    recommendations.push('Few results found. Consider using semantic search or hybrid mode.');
  }

  const symbolMatches = results.filter(r => r.match_type === 'symbol').length;
  if (symbolMatches > results.length * 0.7) {
    recommendations.push('Most matches are symbols. Consider reviewing symbol definitions.');
  }

  const avgScore = results.reduce((sum, r) => sum + r.relevance_score, 0) / results.length;
  if (avgScore < 0.5) {
    recommendations.push(
      'Low average relevance. Try refining your query with more specific terms.'
    );
  }

  return recommendations;
}

async function validateOutput(output, schemaPath) {
  try {
    const schemaContent = await readFile(join(PROJECT_ROOT, schemaPath), 'utf-8');
    const schema = JSON.parse(schemaContent);

    // Basic validation - check required fields
    const requiredFields = schema.required || [];
    for (const field of requiredFields) {
      if (!(field in output)) {
        console.error(`Missing required field: ${field}`);
        return false;
      }
    }
    return true;
  } catch (err) {
    console.error('Schema validation failed:', err.message);
    return false;
  }
}

function formatOutput(query, files, searchResults, args) {
  const { results, _strategiesUsed, duration } = searchResults;
  const rankedResults = rankResults(results, args.limit, args.threshold);
  const _summary = calculateSummary(rankedResults, files);

  return {
    skill_name: 'repo-rag',
    query,
    query_type: args.type,
    results_count: rankedResults.length,
    files_searched: files.map(f => f.relativePath).slice(0, 100), // Limit to first 100 files
    semantic_matches: rankedResults.map(r => ({
      file: r.file,
      line_start: r.line,
      line_end: r.line,
      relevance_score: Math.round(r.relevance_score * 100) / 100,
      snippet: r.snippet,
      match_type: r.match_type,
      context: r.context,
    })),
    search_metadata: {
      total_files_scanned: files.length,
      total_lines_analyzed: files.reduce((sum, f) => sum + f.lineCount, 0),
      search_duration_ms: duration,
    },
    filters_applied: {
      file_extensions: args.extensions || DEFAULT_EXTENSIONS,
      directories: args.path ? [args.path] : [],
    },
    timestamp: new Date().toISOString(),
  };
}

function formatMarkdown(output) {
  const lines = [];

  lines.push('# Repo RAG Search Results\n');
  lines.push(`**Query**: ${output.input.query}`);
  lines.push(`**Strategy**: ${output.search.strategies_used.join(', ')}`);
  lines.push(`**Files Scanned**: ${output.search.files_scanned}`);
  lines.push(`**Matches Found**: ${output.search.matches_found}`);
  lines.push(`**Duration**: ${output.execution.duration_ms}ms\n`);

  if (output.results.length === 0) {
    lines.push('*No results found.*\n');
  } else {
    lines.push('## Results\n');

    output.results.forEach((result, idx) => {
      lines.push(`### ${idx + 1}. ${result.file}:${result.line}`);
      lines.push(`- **Type**: ${result.match_type}`);
      lines.push(`- **Relevance**: ${(result.relevance_score * 100).toFixed(0)}%`);

      if (result.symbol) {
        lines.push(`- **Symbol**: ${result.symbol.type} \`${result.symbol.name}\``);
      }

      lines.push('\n```');
      lines.push(result.snippet);
      lines.push('```\n');
    });
  }

  if (output.summary.recommendations.length > 0) {
    lines.push('## Recommendations\n');
    output.summary.recommendations.forEach(rec => {
      lines.push(`- ${rec}`);
    });
    lines.push('');
  }

  return lines.join('\n');
}

async function main() {
  const args = parseArgs(process.argv.slice(2));

  if (!args.query) {
    showHelp();
    process.exit(1);
  }

  try {
    const searchPath = args.path ? join(PROJECT_ROOT, args.path) : PROJECT_ROOT;
    const extensions = args.extensions || DEFAULT_EXTENSIONS;

    // Scan directory for files
    const files = await scanDirectory(searchPath, extensions);

    if (files.length === 0) {
      console.error('No files found to search');
      process.exit(1);
    }

    // Execute search
    const searchResults = executeSearch(files, args.query, args.type);

    // Format output
    const output = formatOutput(args.query, files, searchResults, args);

    // Validate output
    const schemaPath = '.claude/schemas/skill-repo-rag-output.schema.json';
    const isValid = await validateOutput(output, schemaPath);

    if (!isValid) {
      console.error('Warning: Output does not conform to schema');
    }

    // Output result
    if (args.format === 'markdown') {
      console.log(formatMarkdown(output));
    } else {
      console.log(JSON.stringify(output, null, 2));
    }
  } catch (error) {
    console.error(`Error: ${error.message}`);
    console.error(error.stack);
    process.exit(1);
  }
}

export function parsePackageJson(packageJson) {
  const dependencies = {
    production: {},
    development: {},
    peer: {},
    optional: {},
  };

  if (packageJson.dependencies) {
    dependencies.production = packageJson.dependencies;
  }

  if (packageJson.devDependencies) {
    dependencies.development = packageJson.devDependencies;
  }

  if (packageJson.peerDependencies) {
    dependencies.peer = packageJson.peerDependencies;
  }

  if (packageJson.optionalDependencies) {
    dependencies.optional = packageJson.optionalDependencies;
  }

  return {
    type: 'nodejs',
    manager: detectPackageManager(packageJson),
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

function detectPackageManager(packageJson) {
  if (packageJson.packageManager) {
    if (packageJson.packageManager.startsWith('pnpm')) return 'pnpm';
    if (packageJson.packageManager.startsWith('yarn')) return 'yarn';
    if (packageJson.packageManager.startsWith('npm')) return 'npm';
  }

  // Default to npm if not specified
  return 'npm';
}

export function parseRequirementsTxt(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Parse package name and version
    const match = trimmed.match(/^([a-zA-Z0-9_-]+)([>=<~!]*)([0-9.]*)/);
    if (!match) continue;

    const [, packageName, operator, version] = match;

    // Development dependencies typically have "dev" in the name or are test-related
    const isDev =
      packageName.toLowerCase().includes('test') ||
      packageName.toLowerCase().includes('dev') ||
      packageName.toLowerCase().includes('pytest') ||
      packageName.toLowerCase().includes('coverage');

    const versionSpec = operator && version ? `${operator}${version}` : '*';

    if (isDev) {
      dependencies.development[packageName] = versionSpec;
    } else {
      dependencies.production[packageName] = versionSpec;
    }
  }

  return {
    type: 'python',
    manager: 'pip',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

export function parsePyprojectToml(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  // Parse [project.dependencies]
  const prodMatch = content.match(/\[project\.dependencies\]([\s\S]*?)(?:\[|$)/);
  if (prodMatch) {
    const deps = parseTOMLDependencies(prodMatch[1]);
    dependencies.production = deps;
  }

  // Parse [project.optional-dependencies.dev] or similar
  const devMatch = content.match(
    /\[project\.optional-dependencies\.(?:dev|test)\]([\s\S]*?)(?:\[|$)/
  );
  if (devMatch) {
    const deps = parseTOMLDependencies(devMatch[1]);
    dependencies.development = deps;
  }

  return {
    type: 'python',
    manager: 'poetry',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

function parseTOMLDependencies(content) {
  const deps = {};
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Parse line like: "fastapi>=0.100.0" or "fastapi = ">=0.100.0""
    const match = trimmed.match(/"([a-zA-Z0-9_-]+)\s*([>=<~!]*)\s*([0-9.]*)/);
    if (match) {
      const [, packageName, operator, version] = match;
      const versionSpec = operator && version ? `${operator}${version}` : '*';
      deps[packageName] = versionSpec;
    }
  }

  return deps;
}

export function parseGoMod(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  const lines = content.split('\n');
  let inRequire = false;

  for (const line of lines) {
    const trimmed = line.trim();

    if (trimmed.startsWith('require (')) {
      inRequire = true;
      continue;
    }

    if (inRequire && trimmed === ')') {
      inRequire = false;
      continue;
    }

    if (inRequire || trimmed.startsWith('require ')) {
      // Parse line like: "github.com/pkg/errors v0.9.1"
      const match = trimmed.match(/([a-zA-Z0-9._/-]+)\s+v([0-9.]+)/);
      if (match) {
        const [, packageName, version] = match;
        dependencies.production[packageName] = `v${version}`;
      }
    }
  }

  return {
    type: 'go',
    manager: 'go',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: 0,
  };
}

export function parseCargoToml(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  // Parse [dependencies]
  const prodMatch = content.match(/\[dependencies\]([\s\S]*?)(?:\[|$)/);
  if (prodMatch) {
    const deps = parseTOMLDependencies(prodMatch[1]);
    dependencies.production = deps;
  }

  // Parse [dev-dependencies]
  const devMatch = content.match(/\[dev-dependencies\]([\s\S]*?)(?:\[|$)/);
  if (devMatch) {
    const deps = parseTOMLDependencies(devMatch[1]);
    dependencies.development = deps;
  }

  return {
    type: 'rust',
    manager: 'cargo',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

export function parsePomXml(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  // Simple regex parsing for <dependency> blocks
  const depMatches = content.matchAll(/<dependency>([\s\S]*?)<\/dependency>/g);

  for (const match of depMatches) {
    const depBlock = match[1];

    const groupIdMatch = depBlock.match(/<groupId>(.*?)<\/groupId>/);
    const artifactIdMatch = depBlock.match(/<artifactId>(.*?)<\/artifactId>/);
    const versionMatch = depBlock.match(/<version>(.*?)<\/version>/);
    const scopeMatch = depBlock.match(/<scope>(.*?)<\/scope>/);

    if (groupIdMatch && artifactIdMatch) {
      const packageName = `${groupIdMatch[1]}:${artifactIdMatch[1]}`;
      const version = versionMatch ? versionMatch[1] : '*';
      const scope = scopeMatch ? scopeMatch[1] : 'compile';

      if (scope === 'test') {
        dependencies.development[packageName] = version;
      } else {
        dependencies.production[packageName] = version;
      }
    }
  }

  return {
    type: 'java',
    manager: 'maven',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

export function parseBuildGradle(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  // Parse implementation, api, compileOnly, testImplementation, etc.
  const depLines = content.match(
    /\s+(implementation|api|compileOnly|testImplementation|androidTestImplementation)\s+['"]([^'"]+)['"]/g
  );

  if (depLines) {
    for (const line of depLines) {
      const match = line.match(
        /(implementation|api|compileOnly|testImplementation|androidTestImplementation)\s+['"]([^'"]+)['"]/
      );
      if (match) {
        const [, scope, dependency] = match;
        const isTest = scope.toLowerCase().includes('test');

        if (isTest) {
          dependencies.development[dependency] = '*';
        } else {
          dependencies.production[dependency] = '*';
        }
      }
    }
  }

  return {
    type: 'java',
    manager: 'gradle',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

export function analyzeDependencies(manifests) {
  const results = [];

  // Node.js
  if (manifests['package.json']) {
    const parsed = parsePackageJson(manifests['package.json']);
    results.push(parsed);
  }

  // Python
  if (manifests['requirements.txt']) {
    const parsed = parseRequirementsTxt(manifests['requirements.txt']);
    results.push(parsed);
  }

  if (manifests['pyproject.toml']) {
    const parsed = parsePyprojectToml(manifests['pyproject.toml']);
    results.push(parsed);
  }

  // Go
  if (manifests['go.mod']) {
    const parsed = parseGoMod(manifests['go.mod']);
    results.push(parsed);
  }

  // Rust
  if (manifests['Cargo.toml']) {
    const parsed = parseCargoToml(manifests['Cargo.toml']);
    results.push(parsed);
  }

  // Java
  if (manifests['pom.xml']) {
    const parsed = parsePomXml(manifests['pom.xml']);
    results.push(parsed);
  }

  if (manifests['build.gradle']) {
    const parsed = parseBuildGradle(manifests['build.gradle']);
    results.push(parsed);
  }

  // Aggregate results
  return aggregateDependencies(results);
}

function aggregateDependencies(results) {
  if (results.length === 0) {
    return {
      production: 0,
      development: 0,
    };
  }

  // If single package manager, return its counts
  if (results.length === 1) {
    return {
      production: results[0].totalProduction,
      development: results[0].totalDevelopment,
    };
  }

  // Multiple package managers (e.g., monorepo)
  let totalProduction = 0;
  let totalDevelopment = 0;

  for (const result of results) {
    totalProduction += result.totalProduction;
    totalDevelopment += result.totalDevelopment;
  }

  return {
    production: totalProduction,
    development: totalDevelopment,
  };
}

function parseArgs() {
  const args = process.argv.slice(2);
  const parsed = {
    input: '',
    output: '',
    dryRun: false,
  };

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--input' && args[i + 1]) {
      parsed.input = args[++i];
    } else if (args[i] === '--output' && args[i + 1]) {
      parsed.output = args[++i];
    } else if (args[i] === '--dry-run') {
      parsed.dryRun = true;
    }
  }
  return parsed;
}

function migrateState(legacyState) {
  const newState = {
    workflowId: legacyState.project_name || 'migrated-workflow',
    status: 'active',
    currentPhase: legacyState.current_step || 'unknown',
    phases: {},
    context: {
      migratedAt: new Date().toISOString(),
      legacyData: legacyState.metadata || {},
    },
    history: [],
  };

  // simplistic mapping of phases
  // assuming legacy has a simple list of phases or inferred from context
  // If legacy doesn't list all phases, we create a generic structure

  if (legacyState.phases && Array.isArray(legacyState.phases)) {
    legacyState.phases.forEach(p => {
      newState.phases[p.name] = {
        name: p.name,
        status: p.status || 'pending',
        tasks: [],
      };
    });
  } else {
    // Fallback: Create phases based on completed_phases
    if (legacyState.completed_phases) {
      legacyState.completed_phases.forEach(p => {
        newState.phases[p] = { name: p, status: 'completed', tasks: [] };
      });
    }

    // Add current phase
    if (legacyState.current_step && !newState.phases[legacyState.current_step]) {
      newState.phases[legacyState.current_step] = {
        name: legacyState.current_step,
        status: 'active',
        tasks: [],
      };
    }
  }

  return newState;
}

function main() {
  const { input, output, dryRun } = parseArgs();

  if (!input) {
    console.error('Error: --input <path> is required');
    process.exit(1);
  }

  try {
    const raw = fs.readFileSync(input, 'utf8');
    const legacy = JSON.parse(raw);
    const migrated = migrateState(legacy);

    if (dryRun) {
      console.log(JSON.stringify(migrated, null, 2));
    } else {
      if (output) {
        fs.mkdirSync(path.dirname(output), { recursive: true });
        fs.writeFileSync(output, JSON.stringify(migrated, null, 2));
        console.log(`Successfully migrated state to ${output}`);
      } else {
        console.log(JSON.stringify(migrated, null, 2));
      }
    }
  } catch (err) {
    console.error('Migration failed:', err.message);
    process.exit(1);
  }
}

function parseArgs() {
  const args = process.argv.slice(2);
  const opts = {};

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const nextArg = args[i + 1];

      if (nextArg && !nextArg.startsWith('--')) {
        opts[key] = nextArg;
        i++;
      } else {
        opts[key] = true;
      }
    }
  }

  return opts;
}

function loadLog() {
  if (!fs.existsSync(COST_LOG)) {
    console.error(`Error: Cost log not found at ${COST_LOG}`);
    process.exit(1);
  }

  const content = fs.readFileSync(COST_LOG, 'utf-8').trim();
  if (!content) {
    console.log('Cost log is empty');
    return [];
  }

  const entries = [];
  for (const line of content.split('\n')) {
    if (line.trim()) {
      try {
        entries.push(JSON.parse(line));
      } catch (e) {
        console.warn(`Warning: Failed to parse line: ${e.message}`);
      }
    }
  }

  return entries;
}

function loadSummary() {
  if (!fs.existsSync(COST_SUMMARY)) {
    return { allTime: { cost: 0, tokens: 0, sessions: 0 }, lastSession: null };
  }

  try {
    return JSON.parse(fs.readFileSync(COST_SUMMARY, 'utf-8'));
  } catch {
    return { allTime: { cost: 0, tokens: 0, sessions: 0 }, lastSession: null };
  }
}

function verifyIntegrity(entries) {
  if (entries.length === 0) {
    console.log('Log is empty - no integrity check needed');
    return true;
  }

  let previousHash = '0';
  let valid = true;

  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];

    // Check previous hash matches
    if (entry._prevHash !== previousHash) {
      console.error(`ERROR: Hash chain broken at entry ${i + 1}`);
      console.error(`  Expected prevHash: ${previousHash}`);
      console.error(`  Got prevHash: ${entry._prevHash}`);
      valid = false;
      break;
    }

    previousHash = entry._hash;
  }

  if (valid) {
    console.log('✓ Log integrity verified - all hashes are valid');
  }

  return valid;
}

function reportToday(entries) {
  const today = new Date().toISOString().split('T')[0];

  const todayEntries = entries.filter(e => e.timestamp.startsWith(today));

  console.log(`\nCost Report (Today: ${today})`);
  console.log('='.repeat(50));

  if (todayEntries.length === 0) {
    console.log('No entries found for today');
    return;
  }

  const summary = aggregateEntries(todayEntries);
  displaySummary(summary);
}

function reportDays(entries, days) {
  const daysMs = days * 24 * 60 * 60 * 1000;
  const cutoff = new Date(Date.now() - daysMs);

  const filteredEntries = entries.filter(e => new Date(e.timestamp) >= cutoff);

  console.log(`\nCost Report (Last ${days} Days)`);
  console.log('='.repeat(50));

  if (filteredEntries.length === 0) {
    console.log('No entries found');
    return;
  }

  const summary = aggregateEntries(filteredEntries);
  displaySummary(summary);
}

function reportByModel(entries) {
  console.log('\nCost Report (By Model)');
  console.log('='.repeat(50));

  const byModel = {};
  for (const entry of entries) {
    if (!byModel[entry.tier]) {
      byModel[entry.tier] = { calls: 0, tokens: 0, cost: 0 };
    }
    byModel[entry.tier].calls++;
    byModel[entry.tier].tokens += entry.inputTokens + entry.outputTokens;
    byModel[entry.tier].cost += parseFloat(entry.cost);
  }

  // Sort by cost descending
  const sorted = Object.entries(byModel).sort((a, b) => b[1].cost - a[1].cost);

  console.log('\n| Tier   | Calls | Tokens | Cost     | % of Total |');
  console.log('|--------|-------|--------|----------|------------|');

  const totalCost = sorted.reduce((sum, [, data]) => sum + data.cost, 0);

  for (const [tier, data] of sorted) {
    const percentage = ((data.cost / totalCost) * 100).toFixed(1);
    console.log(
      `| ${tier.padEnd(6)} | ${String(data.calls).padStart(5)} | ${String(data.tokens).padStart(6)} | $${data.cost.toFixed(4).padStart(7)} | ${percentage.padStart(8)}% |`
    );
  }

  console.log('|--------|-------|--------|----------|------------|');
  console.log(
    `| TOTAL  | ${String(entries.length).padStart(5)} | ${String(entries.reduce((sum, e) => sum + e.inputTokens + e.outputTokens, 0)).padStart(6)} | $${totalCost.toFixed(4).padStart(7)} | ${(100).toFixed(1).padStart(8)}% |`
  );
}

function reportSession(entries, sessionId) {
  const sessionEntries = entries.filter(e => e.sessionId === sessionId);

  console.log(`\nCost Report (Session: ${sessionId})`);
  console.log('='.repeat(50));

  if (sessionEntries.length === 0) {
    console.log('Session not found');
    return;
  }

  const summary = aggregateEntries(sessionEntries);
  displaySummary(summary);
}

function aggregateEntries(entries) {
  const summary = {
    byTier: {
      haiku: { calls: 0, tokens: 0, cost: 0 },
      sonnet: { calls: 0, tokens: 0, cost: 0 },
      opus: { calls: 0, tokens: 0, cost: 0 },
    },
    total: { calls: 0, tokens: 0, cost: 0 },
  };

  for (const entry of entries) {
    const tier = entry.tier;
    const tokens = entry.inputTokens + entry.outputTokens;
    const cost = parseFloat(entry.cost);

    summary.byTier[tier].calls++;
    summary.byTier[tier].tokens += tokens;
    summary.byTier[tier].cost += cost;

    summary.total.calls++;
    summary.total.tokens += tokens;
    summary.total.cost += cost;
  }

  return summary;
}

function displaySummary(summary) {
  console.log('\n| Tier   | Calls | Tokens  | Cost     |');
  console.log('|--------|-------|---------|----------|');

  const { byTier, total } = summary;

  for (const [tier, data] of Object.entries(byTier)) {
    if (data.calls > 0) {
      console.log(
        `| ${tier.padEnd(6)} | ${String(data.calls).padStart(5)} | ${String(data.tokens).padStart(7)} | $${data.cost.toFixed(4).padStart(7)} |`
      );
    }
  }

  console.log('|--------|-------|---------|----------|');
  console.log(
    `| TOTAL  | ${String(total.calls).padStart(5)} | ${String(total.tokens).padStart(7)} | $${total.cost.toFixed(4).padStart(7)} |`
  );
}

function main() {
  const opts = parseArgs();

  // Check for verify command first
  if (opts.verify) {
    const entries = loadLog();
    const valid = verifyIntegrity(entries);
    process.exit(valid ? 0 : 1);
  }

  const entries = loadLog();

  if (opts.today) {
    reportToday(entries);
  } else if (opts.days) {
    reportDays(entries, parseInt(opts.days, 10));
  } else if (opts['by-model']) {
    reportByModel(entries);
  } else if (opts.session) {
    reportSession(entries, opts.session);
  } else {
    // Default: all-time summary
    console.log('\nAll-Time Cost Summary');
    console.log('='.repeat(50));

    if (entries.length === 0) {
      console.log('No cost entries found');
      return;
    }

    const summary = loadSummary();
    console.log(`\nTotal Sessions: ${summary.allTime.sessions}`);
    console.log(`Total Cost: $${summary.allTime.cost.toFixed(2)}`);
    console.log(`Total Tokens: ${summary.allTime.tokens.toLocaleString()}`);

    if (summary.lastSession) {
      console.log(`\nLast Session: ${summary.lastSession.timestamp}`);
      console.log(`  Cost: $${summary.lastSession.cost.toFixed(4)}`);
      console.log(`  Tokens: ${summary.lastSession.tokens.toLocaleString()}`);
    }
  }
}

function parseArgs(args) {
  const result = { _: [] };
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const next = args[i + 1];
      if (next && !next.startsWith('--')) {
        result[key] = next;
        i += 1;
      } else {
        result[key] = true;
      }
    } else {
      result._.push(arg);
    }
  }
  return result;
}

function printUsage() {
  process.stdout.write(
    ['Usage:', '  document-query.cjs --document <path_or_url> [--query "question"]'].join('\n') +
      '\n'
  );
}

function isUrl(value) {
  return /^https?:\/\//i.test(value);
}

async function loadDocument(doc) {
  if (isUrl(doc)) {
    if (typeof fetch !== 'function') {
      throw new Error('fetch is not available in this runtime');
    }
    const res = await fetch(doc);
    if (!res.ok) {
      throw new Error(`Failed to fetch ${doc}: ${res.status}`);
    }
    return await res.text();
  }
  const resolved = path.isAbsolute(doc) ? doc : path.join(PROJECT_ROOT, doc);
  return fs.readFileSync(resolved, 'utf8');
}

function scoreParagraphs(text, query) {
  const q = String(query || '')
    .toLowerCase()
    .trim();
  if (!q) return [];
  const terms = q.split(/\s+/).filter(Boolean);
  const paragraphs = text.split(/\n{2,}/);
  const scored = paragraphs.map(p => {
    const lower = p.toLowerCase();
    let score = 0;
    for (const term of terms) {
      if (!term) continue;
      const matches = lower.split(term).length - 1;
      if (matches > 0) score += matches;
    }
    return { paragraph: p.trim(), score };
  });
  return scored.filter(item => item.score > 0).sort((a, b) => b.score - a.score);
}

async function run() {
  const args = parseArgs(process.argv.slice(2));
  const documentPath = args.document || args._[0];
  if (!documentPath || args.help) {
    printUsage();
    process.exit(documentPath ? 0 : 1);
  }
  const query = args.query || args._[1] || '';

  try {
    const text = await loadDocument(documentPath);
    if (!query) {
      process.stdout.write(text + '\n');
      process.exit(0);
    }
    const scored = scoreParagraphs(text, query);
    if (scored.length === 0) {
      process.stdout.write('No matching sections found.\n');
      process.exit(0);
    }
    const top = scored.slice(0, 3);
    process.stdout.write(
      top.map(item => `---\nScore: ${item.score}\n${item.paragraph}\n`).join('\n') + '\n'
    );
    process.exit(0);
  } catch (err) {
    process.stderr.write(`${err.message}\n`);
    process.exit(1);
  }
}

function findProjectRoot() {
  let dir = __dirname;
  while (dir !== path.parse(dir).root) {
    if (fs.existsSync(path.join(dir, '.claude'))) {
      return dir;
    }
    dir = path.dirname(dir);
  }
  return process.cwd();
}

function log(color, msg) {
  console.log(`${colors[color]}${msg}${colors.reset}`);
}

function checkDir(relPath) {
  const fullPath = path.join(PROJECT_ROOT, relPath);
  if (fs.existsSync(fullPath)) {
    if (VERBOSE) log('green', `  ✓ ${relPath}`);
    results.passed++;
    return true;
  }

  if (FIX_MODE) {
    fs.mkdirSync(fullPath, { recursive: true });
    fs.writeFileSync(path.join(fullPath, '.gitkeep'), `# ${path.basename(relPath)} directory\n`);
    log('yellow', `  ✓ ${relPath} (created)`);
    results.fixed++;
    return true;
  }

  log('red', `  ✗ ${relPath} (missing)`);
  results.errors++;
  return false;
}

function checkFile(relPath) {
  const fullPath = path.join(PROJECT_ROOT, relPath);
  if (fs.existsSync(fullPath)) {
    if (VERBOSE) log('green', `  ✓ ${relPath}`);
    results.passed++;
    return true;
  }

  log('red', `  ✗ ${relPath} (missing)`);
  results.errors++;
  return false;
}

function parseFrontmatter(content) {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return null;

  const yaml = match[1];
  const result = {};
  const lines = yaml.split('\n');

  for (const line of lines) {
    if (line.match(/^[a-z_]+:/i)) {
      const colonIndex = line.indexOf(':');
      const key = line.slice(0, colonIndex).trim();
      const value = line.slice(colonIndex + 1).trim();
      result[key] = value;
    }
  }

  return result;
}

function validateAgents() {
  console.log('\n📋 Validating Agents...');

  const agentsDir = path.join(CLAUDE_DIR, 'agents');
  if (!fs.existsSync(agentsDir)) {
    log('red', '  ✗ Agents directory not found');
    results.errors++;
    return;
  }

  let agentCount = 0;
  let validCount = 0;

  function scanAgents(dir) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        scanAgents(fullPath);
      } else if (entry.name.endsWith('.md')) {
        agentCount++;
        try {
          const content = fs.readFileSync(fullPath, 'utf-8');
          const fm = parseFrontmatter(content);
          if (fm && fm.name) {
            validCount++;
            if (VERBOSE) log('green', `  ✓ ${entry.name}`);
          } else {
            log('yellow', `  ⚠ ${entry.name} (missing frontmatter)`);
            results.warnings++;
          }
        } catch (_e) {
          log('red', `  ✗ ${entry.name} (read error)`);
          results.errors++;
        }
      }
    }
  }

  scanAgents(agentsDir);
  log('dim', `  Found ${agentCount} agents, ${validCount} valid`);
  results.passed += validCount;
}

function validateSkills() {
  console.log('\n🔧 Validating Skills...');

  const skillsDir = path.join(CLAUDE_DIR, 'skills');
  if (!fs.existsSync(skillsDir)) {
    log('red', '  ✗ Skills directory not found');
    results.errors++;
    return;
  }

  const skills = fs
    .readdirSync(skillsDir, { withFileTypes: true })
    .filter(e => e.isDirectory())
    .map(e => e.name);

  let validCount = 0;
  let scaffoldCount = 0;

  for (const skill of skills) {
    const skillPath = path.join(skillsDir, skill, 'SKILL.md');
    if (!fs.existsSync(skillPath)) {
      if (VERBOSE) log('yellow', `  ⚠ ${skill} (no SKILL.md)`);
      results.warnings++;
      continue;
    }

    try {
      const content = fs.readFileSync(skillPath, 'utf-8');
      const fm = parseFrontmatter(content);
      if (fm && fm.name) {
        validCount++;

        // Check if main.cjs is scaffold (use constant so grep for "TODO" does not flag this file)
        const SCAFFOLD_MARKER = 'TODO' + ': Implement skill logic here';
        const mainPath = path.join(skillsDir, skill, 'scripts', 'main.cjs');
        if (fs.existsSync(mainPath)) {
          const mainContent = fs.readFileSync(mainPath, 'utf-8');
          if (mainContent.includes(SCAFFOLD_MARKER)) {
            scaffoldCount++;
          }
        }
      }
    } catch (_e) {
      log('red', `  ✗ ${skill} (error reading)`);
      results.errors++;
    }
  }

  log('dim', `  Found ${skills.length} skills, ${validCount} valid, ${scaffoldCount} scaffolds`);
  results.passed += validCount;
  if (scaffoldCount > 0) {
    log(
      'yellow',
      `  ⚠ ${scaffoldCount} skills are implemented as scaffolds (main.cjs contains scaffold marker).`
    );
  }
}

function validateHooks() {
  console.log('\n🪝 Validating Hooks...');

  const settingsPath = path.join(CLAUDE_DIR, 'settings.json');
  if (!fs.existsSync(settingsPath)) {
    log('red', '  ✗ settings.json not found');
    results.errors++;
    return;
  }

  try {
    const settings = JSON.parse(fs.readFileSync(settingsPath, 'utf-8'));
    const hooks = settings.hooks || {};

    for (const [event, handlers] of Object.entries(hooks)) {
      for (const handler of handlers) {
        for (const hook of handler.hooks || []) {
          if (hook.command) {
            // Extract script path from command
            const match = hook.command.match(/node\s+([^\s]+)/);
            if (match) {
              const scriptPath = path.join(PROJECT_ROOT, match[1]);
              if (fs.existsSync(scriptPath)) {
                if (VERBOSE) log('green', `  ✓ ${event}: ${match[1]}`);
                results.passed++;
              } else {
                log('red', `  ✗ ${event}: ${match[1]} (script not found)`);
                results.errors++;
              }
            }
          }
        }
      }
    }
  } catch (e) {
    log('red', `  ✗ Error parsing settings.json: ${e.message}`);
    results.errors++;
  }
}

function validateMcp() {
  console.log('\n🔌 Validating MCP Configuration...');

  const mcpPath = path.join(CLAUDE_DIR, '.mcp.json');
