function generateTaskId(entry) {
  const timestamp = entry.timestamp || new Date().toISOString();
  const date = new Date(timestamp);
  const agentType = (entry.agent_type || 'unknown').toLowerCase();
  const sessionPart = (entry.session_id || '').slice(0, 8);

  // Format: spawn-YYYYMMDD-HHMMSS-agent-sessionId
  const dateStr = date.toISOString().replace(/[-:]/g, '').slice(0, 15); // YYYYMMDDTHHMMSS
  return `spawn-${dateStr}-${agentType}-${sessionPart}`;
}

function fixSpawnLog(dryRun = false) {
  if (!fs.existsSync(SPAWN_LOG_PATH)) {
    console.log('spawn-log.jsonl not found, nothing to fix');
    return { fixed: 0, total: 0 };
  }

  const content = fs.readFileSync(SPAWN_LOG_PATH, 'utf8');
  const lines = content.split('\n').filter(Boolean);

  if (lines.length === 0) {
    console.log('spawn-log.jsonl is empty, nothing to fix');
    return { fixed: 0, total: 0 };
  }

  const entries = lines
    .map(line => {
      try {
        return JSON.parse(line);
      } catch (_err) {
        console.error(`Failed to parse line: ${line.slice(0, 80)}...`);
        return null;
      }
    })
    .filter(Boolean);

  // Pair spawn_start and spawn_end events
  const pairs = [];
  const unpaired = [];

  for (let i = 0; i < entries.length; i++) {
    const entry = entries[i];

    if (entry.event === 'spawn_start') {
      // Look for matching spawn_end
      const matchingEnd = entries
        .slice(i + 1)
        .find(
          e =>
            e.event === 'spawn_end' &&
            e.session_id === entry.session_id &&
            (!e.task_id || e.task_id === entry.task_id)
        );

      if (matchingEnd) {
        pairs.push({ start: entry, end: matchingEnd });
      } else {
        unpaired.push(entry);
      }
    } else if (entry.event !== 'spawn_end') {
      // memory_load_failed, etc.
      unpaired.push(entry);
    }
  }

  // Generate task IDs for entries with null task_id
  let fixed = 0;
  const fixedEntries = [];
  const seen = new Set();

  for (const { start, end } of pairs) {
    if (start.task_id === null || end.task_id === null) {
      const generatedId = generateTaskId(start);
      start.task_id = generatedId;
      end.task_id = generatedId;
      fixed += 2;
      console.log(`  Fixed pair: ${generatedId} (${start.agent_type || 'unknown'})`);
    }
    fixedEntries.push(start);
    seen.add(start);
    fixedEntries.push(end);
    seen.add(end);
  }

  // Add unpaired entries (already processed or non-spawn events)
  for (const entry of entries) {
    if (!seen.has(entry)) {
      if (entry.task_id === null) {
        const generatedId = generateTaskId(entry);
        entry.task_id = generatedId;
        fixed++;
        console.log(`  Fixed unpaired: ${generatedId} (${entry.event})`);
      }
      fixedEntries.push(entry);
    }
  }

  if (dryRun) {
    console.log(`\n[DRY RUN] Would fix ${fixed} entries out of ${entries.length} total`);
    return { fixed, total: entries.length };
  }

  // Backup original file
  const backupPath = `${SPAWN_LOG_PATH}.backup-${Date.now()}`;
  fs.copyFileSync(SPAWN_LOG_PATH, backupPath);
  console.log(`\nCreated backup: ${backupPath}`);

  // Write fixed entries
  const newContent = fixedEntries.map(e => JSON.stringify(e)).join('\n') + '\n';
  fs.writeFileSync(SPAWN_LOG_PATH, newContent, 'utf8');

  console.log(`\nFixed ${fixed} entries out of ${entries.length} total`);
  console.log(`Wrote ${fixedEntries.length} entries to spawn-log.jsonl`);

  return { fixed, total: entries.length };
}

function parseEslintOutput() {
  try {
    const output = execSync('pnpm lint 2>&1 || true', {
      encoding: 'utf-8',
      cwd: PROJECT_ROOT,
      maxBuffer: 50 * 1024 * 1024,
    });

    const fixes = [];
    const lines = output.split('\n');
    let currentFile = null;

    for (const line of lines) {
      // Match file paths (Windows format: C:\path\file.js)
      const fileMatch = line.match(/^([A-Z]:\\[^\s]+\.(cjs|mjs|js))$/i);
      if (fileMatch) {
        currentFile = fileMatch[1];
        continue;
      }

      if (!currentFile) continue;

      // Match unused variable: "'varName' is assigned a value but never used"
      const assignedMatch = line.match(
        /^\s*(\d+):(\d+)\s+(?:error|warning)\s+'([^']+)' is assigned a value but never used/
      );
      if (assignedMatch) {
        fixes.push({
          file: currentFile,
          line: parseInt(assignedMatch[1], 10),
          column: parseInt(assignedMatch[2], 10),
          varName: assignedMatch[3],
          type: 'assigned',
        });
        continue;
      }

      // Match unused function parameter: "'paramName' is defined but never used"
      const definedMatch = line.match(
        /^\s*(\d+):(\d+)\s+(?:error|warning)\s+'([^']+)' is defined but never used/
      );
      if (definedMatch) {
        fixes.push({
          file: currentFile,
          line: parseInt(definedMatch[1], 10),
          column: parseInt(definedMatch[2], 10),
          varName: definedMatch[3],
          type: 'defined',
        });
        continue;
      }
    }

    return fixes;
  } catch (err) {
    console.error('Error parsing ESLint output:', err.message);
    return [];
  }
}

function fixUnusedVar(content, lineNum, column, varName) {
  const lines = content.split('\n');
  const lineIdx = lineNum - 1;

  if (lineIdx >= lines.length) return { content, fixed: false };

  const line = lines[lineIdx];

  // Check if already has _ prefix
  if (varName.startsWith('_')) {
    return { content, fixed: false };
  }

  // Skip variables that shouldn't be prefixed
  if (SKIP_PREFIX.includes(varName)) {
    return { content, fixed: false, skipped: true };
  }

  // Only prefix known safe variables to avoid breaking code
  if (!SAFE_TO_PREFIX.includes(varName)) {
    return { content, fixed: false, skipped: true };
  }

  // Create regex to find and replace the variable name at the right position
  // We need to be careful to only replace the declaration, not uses
  const colIdx = column - 1;

  // Verify the variable name is at the expected position
  if (line.slice(colIdx, colIdx + varName.length) !== varName) {
    // Try to find nearby
    const nearbyIdx = line.indexOf(varName, Math.max(0, colIdx - 5));
    if (nearbyIdx === -1 || nearbyIdx > colIdx + 5) {
      return { content, fixed: false };
    }

    // Check it's a word boundary
    const before = line[nearbyIdx - 1] || '';
    const after = line[nearbyIdx + varName.length] || '';
    if (/\w/.test(before) || /\w/.test(after)) {
      return { content, fixed: false };
    }

    // Replace at the found position
    const newLine =
      line.slice(0, nearbyIdx) + '_' + varName + line.slice(nearbyIdx + varName.length);
    lines[lineIdx] = newLine;
    return { content: lines.join('\n'), fixed: true };
  }

  // Check word boundaries
  const before = line[colIdx - 1] || '';
  const _after = line[colIdx + varName.length] || '';
  if (/\w/.test(before)) {
    return { content, fixed: false };
  }

  // Replace at the exact position
  const newLine = line.slice(0, colIdx) + '_' + varName + line.slice(colIdx + varName.length);
  lines[lineIdx] = newLine;

  return { content: lines.join('\n'), fixed: true };
}

function processFixes(fixes) {
  // Group fixes by file
  const fileGroups = new Map();
  for (const fix of fixes) {
    if (!fileGroups.has(fix.file)) {
      fileGroups.set(fix.file, []);
    }
    fileGroups.get(fix.file).push(fix);
  }

  // Process each file
  for (const [filePath, fileFixes] of fileGroups) {
    try {
      let content = fs.readFileSync(filePath, 'utf-8');
      let fileModified = false;

      // Sort fixes by line number and column (descending) to avoid position shifts
      fileFixes.sort((a, b) => {
        if (b.line !== a.line) return b.line - a.line;
        return b.column - a.column;
      });

      for (const fix of fileFixes) {
        const result = fixUnusedVar(content, fix.line, fix.column, fix.varName);

        if (result.fixed) {
          content = result.content;
          fileModified = true;

          if (fix.type === 'assigned') {
            stats.varsFixed++;
          } else {
            stats.argsFixed++;
          }
        } else if (result.skipped) {
          stats.skipped.push(
            `${path.relative(PROJECT_ROOT, filePath)}:${fix.line} - ${fix.varName}`
          );
        }
      }

      if (fileModified) {
        if (!DRY_RUN) {
          fs.writeFileSync(filePath, content);
        }
        stats.filesProcessed++;
        const relativePath = path.relative(PROJECT_ROOT, filePath);
        console.log(`  ${DRY_RUN ? '[DRY]' : '[FIX]'} ${relativePath}`);
      }
    } catch (err) {
      stats.errors.push({ file: filePath, error: err.message });
    }
  }
}

