function chunkByHeaders(content, _filePath) {
  const lines = content.split('\n');
  const chunks = [];
  let currentSection = null;
  let currentContent = [];
  let startLine = 1;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNumber = i + 1;

    // Detect section headers (## Header or ### Header)
    if (line.match(/^##\s+(.+)$/)) {
      // Save previous section if exists
      if (currentSection) {
        chunks.push({
          section: currentSection,
          content: currentContent.join('\n').trim(),
          line: startLine,
        });
      }

      // Start new section
      currentSection = line.replace(/^##\s+/, '').trim();
      currentContent = [];
      startLine = lineNumber;
    } else {
      // Add content to current section
      if (currentSection) {
        currentContent.push(line);
      }
    }
  }

  // Save last section
  if (currentSection && currentContent.length > 0) {
    chunks.push({
      section: currentSection,
      content: currentContent.join('\n').trim(),
      line: startLine,
    });
  }

  return chunks;
}

function loadJsonEntries(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  let parsed = [];
  try {
    parsed = JSON.parse(raw);
  } catch (_e) {
    return [];
  }
  if (!Array.isArray(parsed)) return [];
  return parsed
    .map(entry => {
      if (typeof entry === 'string') {
        return { text: entry, content: null, timestamp: null };
      }
      if (entry && typeof entry === 'object') {
        return {
          text: entry.text || entry.title || entry.name || '',
          content: entry.content || null,
          timestamp: entry.timestamp || null,
        };
      }
      return null;
    })
    .filter(entry => entry && entry.text);
}

function extractMetadata(filePath, section, line) {
  const basename = path.basename(filePath, '.md');
  const today = new Date().toISOString().split('T')[0];

  // Determine type from file name
  let type = 'unknown';
  if (basename.includes('learning')) {
    type = 'learning';
  } else if (basename.includes('decision')) {
    type = 'decision';
  } else if (basename.includes('issue')) {
    type = 'issue';
  }

  return {
    filePath: basename + '.md',
    section,
    line,
    type,
    timestamp: today,
  };
}

function extractJsonMetadata(filePath) {
  const basename = path.basename(filePath, '.json');
  return {
    filePath: basename + '.json',
    section: basename,
    line: null,
    type: basename === 'patterns' ? 'pattern' : basename === 'gotchas' ? 'issue' : 'memory',
    timestamp: new Date().toISOString().split('T')[0],
  };
}

function findMemoryFiles(sourceDir) {
  const files = [];

  // Main memory files
  const mainFiles = ['learnings.md', 'decisions.md', 'issues.md', 'patterns.json', 'gotchas.json'];
  for (const file of mainFiles) {
    const fullPath = path.join(sourceDir, file);
    if (fs.existsSync(fullPath)) {
      files.push(fullPath);
    }
  }

  // Archived files
  const archiveDir = path.join(sourceDir, 'archive');
  if (fs.existsSync(archiveDir)) {
    const yearMonths = fs.readdirSync(archiveDir);
    for (const yearMonth of yearMonths) {
      const yearMonthPath = path.join(archiveDir, yearMonth);
      if (fs.statSync(yearMonthPath).isDirectory()) {
        const archivedFiles = fs.readdirSync(yearMonthPath);
        for (const file of archivedFiles) {
          if (file.endsWith('.md')) {
            files.push(path.join(yearMonthPath, file));
          }
        }
      }
    }
  }

  return files;
}

async function processFile(filePath, options, vectorStore) {
  const ext = path.extname(filePath).toLowerCase();
  const isJson = ext === '.json';
  const chunks = isJson
    ? loadJsonEntries(filePath)
    : chunkByHeaders(fs.readFileSync(filePath, 'utf8'), filePath);

  if (options.dryRun) {
    console.log(
      `  [DRY RUN] Would process ${chunks.length} chunks from ${path.basename(filePath)}`
    );
    return chunks.length;
  }

  // Generate embeddings for each chunk and upsert into LanceDB
  const docs = chunks.map((chunk, index) => {
    const metadata = isJson
      ? extractJsonMetadata(filePath)
      : extractMetadata(filePath, chunk.section, chunk.line);
    const documentId = isJson
      ? `${metadata.filePath}-${index + 1}`
      : `${metadata.filePath}-${chunk.line}`;
    const documentText = isJson
      ? `${chunk.text}${chunk.content ? `\n\n${chunk.content}` : ''}`
      : `${chunk.section}\n\n${chunk.content}`;
    const docMeta = {
      ...metadata,
      source: metadata.filePath,
    };
    return { id: documentId, text: documentText, metadata: docMeta };
  });

  await vectorStore.upsertDocuments(docs);

  console.log(`  Processed ${chunks.length} chunks from ${path.basename(filePath)}`);
  return chunks.length;
}

async function reindexIfNeeded(vectorStore, options) {
  if (!options?.reindex) return false;
  if (!vectorStore || typeof vectorStore.dropTable !== 'function') {
    throw new Error('LanceDB table drop is unavailable');
  }
  await vectorStore.dropTable();
  return true;
}

async function main() {
  const args = process.argv.slice(2);
  const options = {
    sourceDir: '.claude/context/memory',
    batchSize: 100,
    dryRun: false,
    file: null,
    reindex: false,
  };

  // Parse arguments
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--source' && i + 1 < args.length) {
      options.sourceDir = args[i + 1];
      i++;
    } else if (args[i] === '--batch-size' && i + 1 < args.length) {
      options.batchSize = parseInt(args[i + 1], 10);
      i++;
    } else if (args[i] === '--dry-run') {
      options.dryRun = true;
    } else if (args[i] === '--reindex') {
      options.reindex = true;
    } else if (args[i] === '--file' && i + 1 < args.length) {
      options.file = args[i + 1];
      i++;
    }
  }

  // Resolve source directory
  const PROJECT_ROOT = path.resolve(__dirname, '../../..');
  const sourceDir = path.resolve(PROJECT_ROOT, options.sourceDir);

  console.log('Embedding Generator');
  console.log('==================');
  console.log(`Source directory: ${sourceDir}`);
  console.log(`Batch size: ${options.batchSize}`);
  console.log(`Mode: ${options.dryRun ? 'DRY RUN' : 'EXECUTE'}`);
  if (options.reindex) {
    console.log('Reindex: enabled (existing table will be dropped)');
  }
  console.log('');

  // Find files
  let files = [];
  if (options.file) {
    const filePath = path.isAbsolute(options.file)
      ? options.file
      : path.resolve(PROJECT_ROOT, options.file);
    files = [filePath];
  } else {
    files = findMemoryFiles(sourceDir);
  }
  console.log(`Found ${files.length} memory files to process`);
  console.log('');

  if (options.dryRun) {
    // Dry run - just show what would be processed
    for (const file of files) {
      await processFile(file, options, null);
    }
    console.log('');
    console.log('[DRY RUN] No embeddings were actually generated');
    return;
  }

  // Initialize vector store
  console.log('Initializing LanceDB...');
  const vectorStore = new MemoryVectorStore({
    persistDirectory: path.join(PROJECT_ROOT, '.claude/data/lancedb'),
    collectionName: process.env.LANCEDB_TABLE || 'agent_memory',
  });

  // Check if available
  const available = await vectorStore.isAvailable();
  if (!available) {
    console.error('ERROR: LanceDB is not available');
    process.exit(1);
  }

  console.log('LanceDB initialized successfully');
  if (options.reindex) {
    console.log(`Dropping table: ${vectorStore.config.collectionName}`);
    await reindexIfNeeded(vectorStore, options);
  }
  console.log('');

  // Process files
  let totalChunks = 0;
  for (const file of files) {
    const ext = path.extname(file).toLowerCase();
    if (!['.md', '.json'].includes(ext)) {
      console.log(`  Skipping unsupported file: ${path.basename(file)}`);
      continue;
    }
    try {
      totalChunks += await processFile(file, options, vectorStore);
    } catch (error) {
      if (String(error?.message || '').includes('embedding dimension mismatch')) {
        console.error('ERROR: Embedding dimension mismatch detected.');
        console.error('Run with --reindex to rebuild the LanceDB table.');
      }
      throw error;
    }
  }

  console.log('');
  console.log('✅ Embedding generation complete');
  console.log(`   Total chunks processed: ${totalChunks}`);
  console.log(`   Files processed: ${files.length}`);
  console.log(`   Estimated cost: $0.01 (one-time)`);
}

function loadAgentSkillMatrix() {
  const skillToAgents = {};
  const agentToSkills = {};

  try {
    if (!fs.existsSync(AGENT_SKILL_MATRIX_PATH)) {
      return { skillToAgents, agentToSkills };
    }
    const raw = fs.readFileSync(AGENT_SKILL_MATRIX_PATH, 'utf8');
    const matrix = JSON.parse(raw);
    const agents = matrix.agents || {};

    for (const [_category, categoryAgents] of Object.entries(agents)) {
      if (typeof categoryAgents !== 'object') continue;
      for (const [agentId, config] of Object.entries(categoryAgents)) {
        if (typeof config !== 'object') continue;
        const primary = Array.isArray(config.primary) ? config.primary : [];
        const secondary = Array.isArray(config.secondary) ? config.secondary : [];
        const always = Array.isArray(config.always) ? config.always : [];
        const contextual =
          config.contextual && typeof config.contextual === 'object'
            ? Object.values(config.contextual).flat()
            : [];
        const allSkills = [...new Set([...primary, ...always, ...secondary, ...contextual])];
        agentToSkills[agentId] = allSkills;

        for (const skillName of primary) {
          if (!skillToAgents[skillName])
            skillToAgents[skillName] = { agentPrimary: [], agentSupporting: [] };
          if (!skillToAgents[skillName].agentPrimary.includes(agentId)) {
            skillToAgents[skillName].agentPrimary.push(agentId);
          }
        }
        for (const skillName of always) {
          if (!skillToAgents[skillName])
            skillToAgents[skillName] = { agentPrimary: [], agentSupporting: [] };
          if (!skillToAgents[skillName].agentPrimary.includes(agentId)) {
            skillToAgents[skillName].agentPrimary.push(agentId);
          }
        }
        for (const skillName of secondary) {
          if (!skillToAgents[skillName])
            skillToAgents[skillName] = { agentPrimary: [], agentSupporting: [] };
          if (!skillToAgents[skillName].agentSupporting.includes(agentId)) {
            skillToAgents[skillName].agentSupporting.push(agentId);
          }
        }
        for (const skillName of contextual) {
          if (!skillToAgents[skillName])
            skillToAgents[skillName] = { agentPrimary: [], agentSupporting: [] };
          if (!skillToAgents[skillName].agentSupporting.includes(agentId)) {
            skillToAgents[skillName].agentSupporting.push(agentId);
          }
        }
      }
    }
  } catch (err) {
    console.warn(`Warning: Could not load agent-skill-matrix: ${err.message}`);
  }

  return { skillToAgents, agentToSkills };
}

function parseSkillCatalog() {
  const skills = [];

  try {
    if (fs.existsSync(CATALOG_PATH)) {
      const content = fs.readFileSync(CATALOG_PATH, 'utf8');

      // Extract skill names from table rows
      const skillPattern = /\| `([^`]+)` \|/g;
      let match;

      while ((match = skillPattern.exec(content)) !== null) {
        const skillName = match[1].replace(/~~/g, ''); // Remove strikethrough
        if (!skillName.startsWith('~~')) {
          skills.push(skillName);
        }
      }
    }
  } catch (err) {
    console.warn(`Warning: Could not parse skill catalog: ${err.message}`);
  }

  return [...new Set(skills)]; // Remove duplicates
}

function scanSkillFiles() {
  const skills = {};

  try {
    if (!fs.existsSync(SKILLS_DIR)) {
      return skills;
    }

    const entries = fs.readdirSync(SKILLS_DIR, { withFileTypes: true });

    for (const entry of entries) {
      if (entry.isDirectory()) {
        const skillPath = path.join(SKILLS_DIR, entry.name, 'SKILL.md');

        if (fs.existsSync(skillPath)) {
          const content = fs.readFileSync(skillPath, 'utf8');

          // Extract frontmatter if exists
          const frontmatterMatch = content.match(/^---\n([\s\S]*?)\n---/);

          skills[entry.name] = {
            name: entry.name,
            hasSkillFile: true,
            hasFrontmatter: !!frontmatterMatch,
          };
        }
      }
    }
  } catch (err) {
    console.warn(`Warning: Could not scan skill files: ${err.message}`);
  }

  return skills;
}

function scanSkillFilesRecursively(baseDir, relativePath = '') {
  const skills = {};
  const currentDir = relativePath ? path.join(baseDir, relativePath) : baseDir;

  try {
    if (!fs.existsSync(currentDir)) {
      return skills;
    }

    const entries = fs.readdirSync(currentDir, { withFileTypes: true });

    for (const entry of entries) {
      if (entry.isDirectory()) {
        // Build the relative path for this entry
        const entryRelativePath = relativePath ? `${relativePath}/${entry.name}` : entry.name;

        const skillPath = path.join(currentDir, entry.name, 'SKILL.md');

        if (fs.existsSync(skillPath)) {
          const content = fs.readFileSync(skillPath, 'utf8');

          // Extract frontmatter if exists
          const frontmatterMatch = content.match(/^---\n([\s\S]*?)\n---/);

          // Use forward slashes for consistent keys (cross-platform)
          const skillKey = entryRelativePath.replace(/\\/g, '/');

          skills[skillKey] = {
            name: skillKey,
            hasSkillFile: true,
            hasFrontmatter: !!frontmatterMatch,
          };
        }

        // Recursively scan subdirectories
        const nestedSkills = scanSkillFilesRecursively(baseDir, entryRelativePath);
        Object.assign(skills, nestedSkills);
      }
    }
  } catch (err) {
    console.warn(`Warning: Could not scan skill files in ${currentDir}: ${err.message}`);
  }

  return skills;
}

function validateIndex(indexPath) {
  const errors = [];
  const warnings = [];

  try {
    const index = JSON.parse(fs.readFileSync(indexPath, 'utf8'));

    // Check version
    if (!index.version) {
      errors.push('Missing version field');
    }

    // Check skills count
    const skillCount = Object.keys(index.skills || {}).length;
    if (skillCount < 100) {
      warnings.push(`Expected 400+ skills, found ${skillCount}`);
    }

    // Check domains
    const domainCount = Object.keys(index.index?.byDomain || {}).length;
    if (domainCount < 10) {
      warnings.push(`Expected 20+ domains, found ${domainCount}`);
    }

    // Check each skill has required fields
    for (const [name, skill] of Object.entries(index.skills || {})) {
      if (!skill.requiredTools || skill.requiredTools.length === 0) {
        warnings.push(`Skill ${name} has no required tools`);
      }
    }

    return { valid: errors.length === 0, errors, warnings };
  } catch (err) {
    return { valid: false, errors: [`Failed to parse index: ${err.message}`], warnings };
  }
}

