  if (!validation.valid) {
    console.log('\nWarning: Generated index has validation issues:');
    validation.errors.forEach(e => console.log(`  - ${e}`));
  }
}

function readJson(filePath) {
  if (!fs.existsSync(filePath)) return null;
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    return { __error: err.message };
  }
}

function resolveSources() {
  const contextFile = readJson(CURRENT_CONTEXT_PATH);
  const modesFile = readJson(CURRENT_MODES_PATH);

  let contextName = null;
  let contextSource = 'default';
  let modeNames = [];
  let modeSource = 'default';

  if (contextFile && !contextFile.__error && typeof contextFile.context === 'string') {
    const trimmed = contextFile.context.trim();
    if (trimmed) {
      contextName = trimmed;
      contextSource = 'file:current-context';
    }
  }

  if (contextFile && !contextFile.__error && Array.isArray(contextFile.modes)) {
    modeNames = contextFile.modes.map(mode => String(mode).trim()).filter(Boolean);
    if (modeNames.length > 0) {
      modeSource = 'file:current-context';
    }
  }

  if (modeNames.length === 0 && modesFile && !modesFile.__error && Array.isArray(modesFile.modes)) {
    modeNames = modesFile.modes.map(mode => String(mode).trim()).filter(Boolean);
    if (modeNames.length > 0) {
      modeSource = 'file:current-modes';
    }
  }

  if (!contextName) {
    const envContext = process.env.AGENT_STUDIO_CONTEXT;
    if (envContext && envContext.trim()) {
      contextName = envContext.trim();
      contextSource = 'env';
    }
  }

  if (modeNames.length === 0) {
    const envModes = process.env.AGENT_STUDIO_MODES;
    if (envModes && envModes.trim()) {
      modeNames = envModes
        .split(',')
        .map(mode => mode.trim())
        .filter(Boolean);
      if (modeNames.length > 0) {
        modeSource = 'env';
      }
    }
  }

  return {
    contextName,
    contextSource,
    modeNames,
    modeSource,
    contextFile,
    modesFile,
  };
}

function getCoreToolNames() {
  const manifest = getManifest();
  const core = manifest.tools && manifest.tools.core ? manifest.tools.core : [];
  return core.map(tool => tool.name);
}

function getCommits(range) {
  try {
    const output = execSync(`git log --pretty=format:%H%x09%s ${range}`, { encoding: 'utf-8' });

    if (!output.trim()) {
      return [];
    }

    return output
      .trim()
      .split('\n')
      .map(line => {
        const [hash, ...messageParts] = line.split('\t');
        return { hash: hash.trim(), message: messageParts.join('\t') };
      });
  } catch (error) {
    console.error(`Error getting commits: ${error.message}`);
    return [];
  }
}

function getNotes(commitHash) {
  try {
    return execSync(`git notes show ${commitHash}`, { encoding: 'utf-8' });
  } catch (_error) {
    return null; // No note for this commit
  }
}

function verify(range) {
  const commits = getCommits(range);
  const results = [];

  for (const commit of commits) {
    const notes = getNotes(commit.hash);

    if (!notes) {
      results.push({
        hash: commit.hash.substring(0, 7),
        message: commit.message,
        notes: null,
        verified: false,
        status: 'MISSING',
        timestamp: null,
      });
      continue;
    }

    const verification = gitNotesAudit.verifyNote(notes, commit.hash);

    results.push({
      hash: commit.hash.substring(0, 7),
      message: commit.message,
      notes: notes,
      verified: verification.verified,
      status: verification.verified ? 'VERIFIED' : 'TAMPERED',
      timestamp: verification.timestamp || null,
      taskId: verification.taskId || null,
      agentName: verification.agentName || null,
      error: verification.error || null,
    });
  }

  return results;
}

function generateReport(results, range) {
  const total = results.length;
  const withNotes = results.filter(r => r.notes !== null).length;
  const verified = results.filter(r => r.verified).length;
  const missing = results.filter(r => r.status === 'MISSING').length;
  const tampered = results.filter(r => r.status === 'TAMPERED').length;

  let report = `# Git Notes Audit Trail Report

**Generated**: ${new Date().toISOString()}
**Commit Range**: ${range || 'All commits'}

## Summary

- **Total Commits**: ${total}
- **With Notes**: ${withNotes} (${((withNotes / total) * 100).toFixed(1)}%)
- **Verified**: ${verified} ✓
- **Missing**: ${missing} ${missing > 0 ? '⚠' : ''}
- **Tampered**: ${tampered} ${tampered > 0 ? '🚨' : ''}

`;

  if (missing > 0) {
    report += `## ⚠ Missing Audit Notes (${missing})\n\n`;
    report += `| Commit | Message |\n`;
    report += `|--------|----------|\n`;
    results
      .filter(r => r.status === 'MISSING')
      .forEach(r => {
        report += `| ${r.hash} | ${r.message} |\n`;
      });
    report += `\n`;
  }

  if (tampered > 0) {
    report += `## 🚨 Tampered Notes (${tampered})\n\n`;
    report += `| Commit | Message | Error |\n`;
    report += `|--------|---------|-------|\n`;
    results
      .filter(r => r.status === 'TAMPERED')
      .forEach(r => {
        report += `| ${r.hash} | ${r.message} | ${r.error} |\n`;
      });
    report += `\n`;
  }

  report += `## Verified Commits (${verified})\n\n`;
  report += `| Commit | Task ID | Agent | Timestamp | Message |\n`;
  report += `|--------|---------|-------|-----------|----------|\n`;
  results
    .filter(r => r.verified)
    .forEach(r => {
      report += `| ${r.hash} | ${r.taskId} | ${r.agentName} | ${r.timestamp} | ${r.message} |\n`;
    });

  return report;
}

function printSummary(results) {
  const total = results.length;
  const verified = results.filter(r => r.verified).length;
  const missing = results.filter(r => r.status === 'MISSING').length;
  const tampered = results.filter(r => r.status === 'TAMPERED').length;

  console.log('\n=== Git Notes Audit Trail ===\n');
  console.log(`Total Commits: ${total}`);
  console.log(`Verified: ${verified} ✓`);
  console.log(`Missing: ${missing} ${missing > 0 ? '⚠' : ''}`);
  console.log(`Tampered: ${tampered} ${tampered > 0 ? '🚨' : ''}`);
  console.log('');

  if (missing > 0) {
    console.log('⚠ Commits missing audit notes:');
    results
      .filter(r => r.status === 'MISSING')
      .forEach(r => {
        console.log(`  ${r.hash} - ${r.message}`);
      });
    console.log('');
  }

  if (tampered > 0) {
    console.log('🚨 Commits with tampered notes:');
    results
      .filter(r => r.status === 'TAMPERED')
      .forEach(r => {
        console.log(`  ${r.hash} - ${r.message}`);
        console.log(`    Error: ${r.error}`);
      });
    console.log('');
  }

  console.log('Verified commits:');
  results
    .filter(r => r.verified)
    .forEach(r => {
      console.log(`  ${r.hash} [${r.taskId}] ${r.agentName} - ${r.message}`);
    });
  console.log('');
}

function main() {
  const args = process.argv.slice(2);

  // Show help
  if (args.includes('--help') || args.includes('-h')) {
    console.log(`
Git Notes Verification Tool

Usage:
  node git-notes-verify.cjs <commit_range>
  node git-notes-verify.cjs main..HEAD
  node git-notes-verify.cjs HEAD~5..HEAD
  node git-notes-verify.cjs --all
  node git-notes-verify.cjs --report=audit-report.md

Options:
  --all             Verify all commits in repository
  --report=FILE     Generate markdown report and save to file
  --help, -h        Show this help message

Examples:
  # Verify last 10 commits
  node git-notes-verify.cjs HEAD~10..HEAD

  # Verify commits between main and current branch
  node git-notes-verify.cjs main..HEAD

  # Generate audit report
  node git-notes-verify.cjs main..HEAD --report=audit-2026-01-29.md

  # Verify all commits
  node git-notes-verify.cjs --all
    `);
    process.exit(0);
  }

  // Parse arguments
  let range = '';
  let reportFile = null;

  for (const arg of args) {
    if (arg.startsWith('--report=')) {
      reportFile = arg.split('=')[1];
    } else if (arg === '--all') {
      range = ''; // Empty range means all commits
    } else if (!arg.startsWith('--')) {
      range = arg;
    }
  }

  // Default to last 10 commits if no range specified
  if (!range && !args.includes('--all')) {
    range = 'HEAD~10..HEAD';
  }

  // Verify commits
  const results = verify(range);

  if (results.length === 0) {
    console.log('No commits found in range:', range || 'all commits');
    process.exit(0);
  }

  // Generate report if requested
  if (reportFile) {
    const report = generateReport(results, range);
    fs.writeFileSync(reportFile, report, 'utf-8');
    console.log(`\nReport generated: ${reportFile}`);
  }

  // Print summary
  printSummary(results);

  // Exit with error code if any issues found
  const issues = results.filter(r => !r.verified).length;
  process.exit(issues > 0 ? 1 : 0);
}

