    }

    if (result.warnings.length > 0) {
      console.log('\nWarnings:');
      result.warnings.forEach(w => console.log(`  - ${w}`));
    }

    if (result.valid) {
      console.log('\nManifest is valid!');
      process.exit(0);
    } else {
      console.log('\nManifest validation failed.');
      process.exit(1);
    }
  }

  // Generate manifest
  const manifest = generateManifest({ verbose });

  if (dryRun) {
