function findProjectRoot(startDir) {
  let dir = startDir || __dirname;
  while (dir !== path.parse(dir).root) {
    // Check if parent directory has .claude and contains CLAUDE.md
    if (fs.existsSync(path.join(dir, '.claude', 'CLAUDE.md'))) {
      return dir;
    }
    // Also check if we're inside .claude and can go up
    if (path.basename(dir) === '.claude' || dir.includes('.claude')) {
      const parent = path.dirname(dir);
      if (fs.existsSync(path.join(parent, '.claude', 'CLAUDE.md'))) {
        return parent;
      }
    }
    dir = path.dirname(dir);
  }
  return process.cwd();
}

function scanAgentFiles(projectRoot) {
  const agentsDir = path.join(projectRoot, '.claude', 'agents');
  const results = [];

  if (!fs.existsSync(agentsDir)) {
    return results;
  }

  function scan(dir, relativeBase) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      const relativePath = path.posix.join(relativeBase, entry.name);

      if (entry.isDirectory()) {
        scan(fullPath, relativePath);
      } else if (entry.name.endsWith('.md')) {
        results.push(relativePath);
      }
    }
  }

  scan(agentsDir, '.claude/agents');
  return results;
}

function validateRouting(tableEntries, agentFiles, projectRoot) {
  const results = {
    ok: [],
    missing: [],
    notInTable: [],
    mismatch: [],
  };

  // Normalize paths for comparison (handle Windows backslashes)
  const normalizedFiles = new Set(agentFiles.map(f => f.replace(/\\/g, '/')));

  // Track which files are accounted for
  const accountedFiles = new Set();

  // Check each table entry
  for (const entry of tableEntries) {
    const normalizedPath = entry.file.replace(/\\/g, '/');
    const fullPath = path.join(projectRoot, normalizedPath);

    if (fs.existsSync(fullPath)) {
      // File exists - mark as OK
      results.ok.push({
        agent: entry.agent,
        file: entry.file,
        requestType: entry.requestType,
      });
      accountedFiles.add(normalizedPath);
    } else {
      // File doesn't exist - mark as MISSING
      results.missing.push({
        agent: entry.agent,
        file: entry.file,
        requestType: entry.requestType,
      });
    }
  }

  // Find files not in the routing table
  for (const file of normalizedFiles) {
    if (!accountedFiles.has(file)) {
      results.notInTable.push({ file });
    }
  }

  return results;
}

function formatOutput(results, verbose = false) {
  const lines = [];

  lines.push('=== Agent Routing Validation ===');
  lines.push('');
  lines.push('Checking CLAUDE.md Section 3 against .claude/agents/...');
  lines.push('');

  // Show OK entries (if verbose or few)
  if (verbose || results.ok.length <= 5) {
    for (const entry of results.ok) {
      lines.push(`\u2713 ${entry.agent}: ${entry.file} [OK]`);
    }
  } else {
    lines.push(`\u2713 ${results.ok.length} agents validated [OK]`);
  }

  // Show missing entries
  for (const entry of results.missing) {
    lines.push(`\u2717 ${entry.agent}: ${entry.file} [MISSING]`);
  }

  // Show not-in-table entries
  for (const entry of results.notInTable) {
    lines.push(`? ${path.basename(entry.file, '.md')}: ${entry.file} [NOT IN TABLE]`);
  }

  // Summary
  lines.push('');
  lines.push('Summary:');
  lines.push(`- OK: ${results.ok.length}`);
  lines.push(`- Missing: ${results.missing.length}`);
  lines.push(`- Not in table: ${results.notInTable.length}`);
  lines.push(`- Mismatch: ${results.mismatch.length}`);
  lines.push('');

  const hasIssues =
    results.missing.length > 0 || results.notInTable.length > 0 || results.mismatch.length > 0;
  if (hasIssues) {
    lines.push('Overall: FAIL (discrepancies found)');
  } else {
    lines.push('Overall: PASS');
  }

  return lines.join('\n');
}

function main() {
  const args = process.argv.slice(2);
  const verbose = args.includes('--verbose') || args.includes('-v');

  const projectRoot = findProjectRoot(__dirname);
  const claudeMdPath = path.join(projectRoot, '.claude', 'CLAUDE.md');

  // Read CLAUDE.md
  if (!fs.existsSync(claudeMdPath)) {
    console.error('Error: CLAUDE.md not found at', claudeMdPath);
    process.exit(1);
  }

  const content = fs.readFileSync(claudeMdPath, 'utf-8');

  // Parse routing table
  const tableEntries = parseRoutingTable(content);

  if (tableEntries.length === 0) {
    console.error('Error: No routing table found in CLAUDE.md Section 3');
    process.exit(1);
  }

  // Scan agent files
  const agentFiles = scanAgentFiles(projectRoot);

  // Validate
  const results = validateRouting(tableEntries, agentFiles, projectRoot);

  // Output
  console.log(formatOutput(results, verbose));

  // Exit code
  const hasIssues =
    results.missing.length > 0 || results.notInTable.length > 0 || results.mismatch.length > 0;
  process.exit(hasIssues ? 1 : 0);
}

function findAgentFiles() {
  const agents = [];

  function scanDir(dir) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        scanDir(fullPath);
      } else if (entry.name.endsWith('.md') && entry.name !== 'README.md') {
        agents.push(fullPath);
      }
    }
  }

  scanDir(AGENTS_DIR);
  return agents;
}

function validateAllAgents() {
  const agentFiles = findAgentFiles();
  const results = [];

  console.log(`\n🔍 Validating ${agentFiles.length} agent files...\n`);

  for (const filePath of agentFiles) {
    const content = fs.readFileSync(filePath, 'utf8');
    const relPath = path.relative(PROJECT_ROOT, filePath);

    const result = validator._test.validateAgentTools(filePath, content);

    results.push({
      filePath: relPath,
      agentName: result.metadata?.agentName || path.basename(filePath, '.md'),
      category: result.metadata?.category || 'unknown',
      toolCount: result.metadata?.toolCount || 0,
      mcpToolCount: result.metadata?.mcpToolCount || 0,
      valid: result.valid,
      errors: result.errors,
      warnings: result.warnings,
    });

    // Print status
    const status = result.valid ? '✅' : '❌';
    const name = path.basename(filePath, '.md');
    console.log(`${status} ${name.padEnd(30)} (${result.metadata?.toolCount || 0} tools)`);

    if (!result.valid) {
      result.errors.forEach(err => {
        console.log(`   ❌ ${err}`);
      });
    }

    if (result.warnings.length > 0) {
      result.warnings.forEach(warn => {
        console.log(`   ⚠️  ${warn}`);
      });
    }
  }

  return results;
}

function generateReport(results) {
  const timestamp = new Date().toISOString();
  const validCount = results.filter(r => r.valid).length;
  const invalidCount = results.length - validCount;
  const warningCount = results.reduce((sum, r) => sum + r.warnings.length, 0);

  const report = [
    '# Agent Tools Validation Report',
    '',
    `**Generated:** ${timestamp}`,
    `**Total Agents:** ${results.length}`,
    `**Valid:** ${validCount} ✅`,
    `**Invalid:** ${invalidCount} ❌`,
    `**Warnings:** ${warningCount} ⚠️`,
    '',
    '---',
    '',
    '## Summary by Category',
    '',
    '| Category | Agents | Valid | Invalid | Warnings |',
    '|----------|--------|-------|---------|----------|',
  ];

  // Group by category
  const byCategory = {};
  for (const result of results) {
    const cat = result.category || 'unknown';
    if (!byCategory[cat]) {
      byCategory[cat] = { total: 0, valid: 0, invalid: 0, warnings: 0 };
    }
    byCategory[cat].total++;
    if (result.valid) byCategory[cat].valid++;
    else byCategory[cat].invalid++;
    byCategory[cat].warnings += result.warnings.length;
  }

  for (const [category, stats] of Object.entries(byCategory)) {
    report.push(
      `| ${category} | ${stats.total} | ${stats.valid} | ${stats.invalid} | ${stats.warnings} |`
    );
  }

  report.push('', '---', '', '## Validation Results', '');

  // Invalid agents
  const invalid = results.filter(r => !r.valid);
  if (invalid.length > 0) {
    report.push('### ❌ Invalid Agents', '');

    for (const result of invalid) {
      report.push(`#### ${result.agentName} (${result.category})`);
      report.push('');
      report.push(`**File:** \`${result.filePath}\``);
      report.push(`**Tools:** ${result.toolCount} (${result.mcpToolCount} MCP)`);
      report.push('');
      report.push('**Errors:**');
      result.errors.forEach(err => {
        report.push(`- ❌ ${err}`);
      });

      if (result.warnings.length > 0) {
        report.push('');
        report.push('**Warnings:**');
        result.warnings.forEach(warn => {
          report.push(`- ⚠️  ${warn}`);
        });
      }

      report.push('');
    }
  }

  // Agents with warnings
  const withWarnings = results.filter(r => r.valid && r.warnings.length > 0);
  if (withWarnings.length > 0) {
    report.push('### ⚠️  Agents with Warnings', '');

    for (const result of withWarnings) {
      report.push(`#### ${result.agentName} (${result.category})`);
      report.push('');
      report.push(`**File:** \`${result.filePath}\``);
      report.push(`**Tools:** ${result.toolCount} (${result.mcpToolCount} MCP)`);
      report.push('');
      report.push('**Warnings:**');
      result.warnings.forEach(warn => {
        report.push(`- ⚠️  ${warn}`);
      });
      report.push('');
    }
  }

  // Valid agents
  const valid = results.filter(r => r.valid && r.warnings.length === 0);
  if (valid.length > 0) {
    report.push('### ✅ Valid Agents', '');
    report.push('| Agent | Category | Tools | MCP Tools |');
    report.push('|-------|----------|-------|-----------|');

    for (const result of valid) {
      report.push(
        `| ${result.agentName} | ${result.category} | ${result.toolCount} | ${result.mcpToolCount} |`
      );
    }

    report.push('');
  }

  report.push('---', '', '## Recommendations', '');

  if (invalidCount > 0) {
    report.push('### Critical Issues', '');
    report.push('1. Fix invalid tool references in agent frontmatter');
    report.push('2. Ensure category-specific requirements are met');
    report.push('3. Check agent-specific rules (orchestrators, reviewers, etc.)');
    report.push('');
  }

  if (warningCount > 0) {
    report.push('### Warnings', '');
    report.push('1. MCP tools require server configuration in `.claude/settings.json`');
    report.push('2. Consider using `Skill()` fallback for sequential-thinking');
    report.push('3. Review MCP tool usage vs availability');
    report.push('');
  }

  report.push('---', '', '## Next Steps', '');
  report.push(
    '1. Run `node .claude/tools/cli/validate-agent-tools.js --fix` to auto-fix common issues'
  );
  report.push('2. Set `AGENT_TOOLS_VALIDATOR=block` to enforce validation in hooks');
  report.push('3. Add validation to CI/CD pipeline');
  report.push('');

  return report.join('\n');
}

