function getFilesToScan(args) {
  // Check for --staged flag (git staged files)
  if (args.includes('--staged')) {
    try {
      const output = execSync('git diff --cached --name-only --diff-filter=ACMR', {
        encoding: 'utf8',
      });
      return output.trim().split('\n').filter(Boolean);
    } catch (err) {
      console.error('Error getting staged files:', err.message);
      return [];
    }
  }

  // Check for --all flag (all tracked files)
  if (args.includes('--all')) {
    try {
      const output = execSync('git ls-files', { encoding: 'utf8' });
      return output.trim().split('\n').filter(Boolean);
    } catch (err) {
      console.error('Error getting tracked files:', err.message);
      return [];
    }
  }

  // Specific files provided
  const files = args.filter(arg => !arg.startsWith('--'));
  if (files.length > 0) {
    return files;
  }

  // Default: scan current directory
  return walkDirectory('.');
}

function walkDirectory(dir) {
  const files = [];

  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        // Skip excluded directories
        if (CONFIG.skipDirs.includes(entry.name)) {
          continue;
        }
        files.push(...walkDirectory(fullPath));
      } else if (entry.isFile()) {
        files.push(fullPath);
      }
    }
  } catch (_err) {
    // Skip directories we can't read
  }

  return files;
}

function normalizePathForMatch(filePath) {
  return filePath.split(path.sep).join('/');
}

function shouldScanFile(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  const normalized = normalizePathForMatch(filePath);

  // Check extension
  if (!CONFIG.scanExtensions.includes(ext) && !filePath.includes('.env')) {
    return false;
  }

  // Skip .md files under docs/plans/skills (examples and documentation only)
  if (ext === '.md' && CONFIG.skipMdPaths) {
    if (CONFIG.skipMdPaths.some(prefix => normalized.includes(prefix))) {
      return false;
    }
  }

  // Check file size
  try {
    const stats = fs.statSync(filePath);
    if (stats.size > CONFIG.maxFileSize) {
      return false;
    }
  } catch (_err) {
    return false;
  }

  return true;
}

function shouldSkipScanning(filePath, content) {
  // Skip if file has security-lint-ignore directive
  if (
    content.startsWith('// security-lint-ignore') ||
    content.startsWith('/* security-lint-ignore') ||
    content.startsWith('# security-lint-ignore')
  ) {
    return true;
  }

  const fileName = path.basename(filePath);

  // Skip security-lint.cjs itself (contains security patterns as rule definitions)
  if (fileName === 'security-lint.cjs' && content.includes('SECURITY_RULES')) {
    return true;
  }

  // Skip test files that are testing security patterns
  // These files intentionally contain security issues as test data
  if (
    fileName.includes('.test.') &&
    (content.includes('security-lint') || content.includes('SECURITY_RULES'))
  ) {
    return true;
  }

  return false;
}

function scanFile(filePath) {
  const findings = [];

  // Read file content
  let content;
  try {
    content = fs.readFileSync(filePath, 'utf8');
  } catch (_err) {
    return findings;
  }

  // Check if file should be skipped
  if (shouldSkipScanning(filePath, content)) {
    return findings;
  }

  // Check each rule
  for (const rule of SECURITY_RULES) {
    // Create fresh regex to reset lastIndex
    const pattern = new RegExp(rule.pattern.source, rule.pattern.flags);

    let match;
    while ((match = pattern.exec(content)) !== null) {
      // Find line number
      const upToMatch = content.substring(0, match.index);
      const lineNumber = upToMatch.split('\n').length;

      findings.push({
        ruleId: rule.id,
        ruleName: rule.name,
        severity: rule.severity,
        description: rule.description,
        fix: rule.fix,
        file: filePath,
        line: lineNumber,
        column: match.index - upToMatch.lastIndexOf('\n'),
        match: match[0].substring(0, 50) + (match[0].length > 50 ? '...' : ''),
      });

      // Prevent infinite loops for non-global patterns
      if (!pattern.global) break;
    }
  }

  return findings;
}

function formatFindings(findings) {
  if (findings.length === 0) {
    return '\n\x1b[32m[PASS] No security issues found\x1b[0m\n';
  }

  // Group by file
  const byFile = {};
  for (const f of findings) {
    if (!byFile[f.file]) byFile[f.file] = [];
    byFile[f.file].push(f);
  }

  // Count by severity
  const counts = { critical: 0, high: 0, medium: 0, low: 0 };
  for (const f of findings) {
    counts[f.severity]++;
  }

  let output = '\n\x1b[31m[FAIL] Security issues detected\x1b[0m\n\n';

  // Summary
  output += '\x1b[1mSummary:\x1b[0m\n';
  if (counts.critical > 0) output += `  \x1b[31m* Critical: ${counts.critical}\x1b[0m\n`;
  if (counts.high > 0) output += `  \x1b[33m* High: ${counts.high}\x1b[0m\n`;
  if (counts.medium > 0) output += `  \x1b[34m* Medium: ${counts.medium}\x1b[0m\n`;
  if (counts.low > 0) output += `  \x1b[90m* Low: ${counts.low}\x1b[0m\n`;
  output += '\n';

  // Details by file
  for (const [file, fileFindings] of Object.entries(byFile)) {
    output += `\x1b[1m${file}\x1b[0m\n`;

    for (const f of fileFindings) {
      const severityColor = {
        critical: '\x1b[31m',
        high: '\x1b[33m',
        medium: '\x1b[34m',
        low: '\x1b[90m',
      }[f.severity];

      output += `  ${severityColor}${f.line}:${f.column}\x1b[0m  ${f.ruleId} ${f.description}\n`;
      output += `           \x1b[90mMatch: ${f.match}\x1b[0m\n`;
      output += `           \x1b[36mFix: ${f.fix}\x1b[0m\n`;
    }
    output += '\n';
  }

  return output;
}

function formatJson(findings) {
  return JSON.stringify(
    {
      success: findings.length === 0,
      totalFindings: findings.length,
      findings,
      scannedAt: new Date().toISOString(),
    },
    null,
    2
  );
}

function main() {
  const args = process.argv.slice(2);

  // Help
  if (args.includes('--help') || args.includes('-h')) {
    console.log(`
Security Lint - Pre-commit security scanner

Usage:
  security-lint.cjs [options] [files...]

Options:
  --staged    Scan git staged files
  --all       Scan all git tracked files
  --json      Output results as JSON
  --help, -h  Show this help

Examples:
  security-lint.cjs --staged           # Pre-commit hook
  security-lint.cjs src/auth.js        # Scan specific file
  security-lint.cjs --all --json       # Full scan with JSON output
`);
    process.exit(0);
  }

  // Get files to scan
  const files = getFilesToScan(args);
  const filesToScan = files.filter(shouldScanFile);

  if (filesToScan.length === 0) {
    console.log('No files to scan');
    process.exit(0);
  }

  // Scan all files
  let allFindings = [];
  for (const file of filesToScan) {
    const findings = scanFile(file);
    allFindings.push(...findings);
  }

  // Exclude known false positives (path + ruleId) from blocking and report
  if (CONFIG.skipFindings && CONFIG.skipFindings.length > 0) {
    allFindings = allFindings.filter(f => {
      const normalized = normalizePathForMatch(f.file);
      const skip = CONFIG.skipFindings.some(
        s => normalized.includes(s.pathSubstring) && f.ruleId === s.ruleId
      );
      return !skip;
    });
  }

  // Output results
  if (args.includes('--json')) {
    console.log(formatJson(allFindings));
  } else {
    console.log(formatFindings(allFindings));
    console.log(`Scanned ${filesToScan.length} file(s)`);
  }

  // Exit with appropriate code
  const hasCriticalOrHigh = allFindings.some(
    f => f.severity === 'critical' || f.severity === 'high'
  );
  process.exit(hasCriticalOrHigh ? 1 : 0);
}

async function executeHook(hookPath, input) {
  const fullPath = path.join(HOOKS_DIR, hookPath);

  return new Promise(resolve => {
    const startTime = process.hrtime.bigint();

    const child = spawn('node', [fullPath], {
      cwd: PROJECT_ROOT,
      env: {
        ...process.env,
        // Disable enforcement for profiling (we just want latency)
        ROUTER_WRITE_GUARD: 'off',
        PLANNER_FIRST_ENFORCEMENT: 'off',
        SECURITY_REVIEW_ENFORCEMENT: 'off',
        ROUTER_SELF_CHECK: 'off',
        ROUTER_BASH_GUARD: 'off',
        FILE_PLACEMENT_GUARD: 'off',
        TDD_CHECK_ENFORCEMENT: 'off',
        // Prevent actual blocking
        HOOK_FAIL_OPEN: 'true',
      },
      stdio: ['pipe', 'pipe', 'pipe'],
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', data => {
      stdout += data.toString();
    });

    child.stderr.on('data', data => {
      stderr += data.toString();
    });

    // Write input to stdin
    child.stdin.write(JSON.stringify(input));
    child.stdin.end();

    child.on('close', exitCode => {
      const endTime = process.hrtime.bigint();
      const latencyMs = Number(endTime - startTime) / 1_000_000; // Convert to ms

      resolve({
        latencyMs,
        exitCode: exitCode || 0,
        stdout,
        stderr,
      });
    });

    child.on('error', err => {
      const endTime = process.hrtime.bigint();
      const latencyMs = Number(endTime - startTime) / 1_000_000;

      resolve({
        latencyMs,
        exitCode: -1,
        stdout: '',
        stderr: err.message,
      });
    });

    // Timeout after 5 seconds
    setTimeout(() => {
      child.kill();
      const endTime = process.hrtime.bigint();
      const latencyMs = Number(endTime - startTime) / 1_000_000;

      resolve({
        latencyMs,
        exitCode: -2,
        stdout,
        stderr: 'Timeout after 5000ms',
      });
    }, 5000);
  });
}

function calculatePercentiles(latencies) {
  if (latencies.length === 0) {
    return { p50: 0, p90: 0, p95: 0, p99: 0, min: 0, max: 0, mean: 0 };
  }

  const sorted = [...latencies].sort((a, b) => a - b);
  const n = sorted.length;

  const percentile = p => {
    const index = Math.ceil((p / 100) * n) - 1;
    return sorted[Math.max(0, Math.min(index, n - 1))];
  };

  const sum = sorted.reduce((a, b) => a + b, 0);

  return {
    p50: percentile(50),
    p90: percentile(90),
    p95: percentile(95),
    p99: percentile(99),
    min: sorted[0],
    max: sorted[n - 1],
    mean: sum / n,
  };
}

async function profileHook(hookConfig, iterations, warm = true) {
  const latencies = [];
  const warmupIterations = warm ? Math.min(5, iterations) : 0;

  // Warmup iterations (not counted)
  for (let i = 0; i < warmupIterations; i++) {
    await executeHook(hookConfig.path, hookConfig.input);
  }

  // Actual profiling iterations
  for (let i = 0; i < iterations; i++) {
    const result = await executeHook(hookConfig.path, hookConfig.input);
    if (result.exitCode !== -2) {
      // Exclude timeouts
      latencies.push(result.latencyMs);
    }
  }

  const stats = calculatePercentiles(latencies);

  return {
    name: hookConfig.name,
    path: hookConfig.path,
    trigger: hookConfig.trigger,
    iterations: latencies.length,
    ...stats,
  };
}

function generateMarkdownReport(results) {
