function parseArgs(args) {
  const result = { _: [] };
  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i];
    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const next = args[i + 1];
      if (next && !next.startsWith('--')) {
        result[key] = next;
        i += 1;
      } else {
        result[key] = true;
      }
    } else {
      result._.push(arg);
    }
  }
  return result;
}

function printUsage() {
  process.stdout.write(
    [
      'Usage:',
      '  schedule-task.cjs add --name "Daily" --type once --run-at "2026-02-03T12:00:00Z" --payload "{\\"command\\":\\"node .claude/lib/memory/memory-scheduler.cjs daily\\"}"',
      '  schedule-task.cjs add "Daily" once "2026-02-03T12:00:00Z" "{\\"command\\":\\"node .claude/lib/memory/memory-scheduler.cjs daily\\"}"',
      '  schedule-task.cjs list',
      '  schedule-task.cjs remove <id>',
    ].join('\n') + '\n'
  );
}

function parsePayload(payloadArg) {
  if (!payloadArg) return {};
  try {
    return JSON.parse(payloadArg);
  } catch (_e) {
    return { command: payloadArg };
  }
}

function run() {
  const args = parseArgs(process.argv.slice(2));
  const cmd = args._[0];

  if (!cmd || cmd === 'help' || args.help) {
    printUsage();
    process.exit(0);
  }

  if (cmd === 'list') {
    const tasks = listTasks();
    process.stdout.write(JSON.stringify({ tasks }, null, 2) + '\n');
    process.exit(0);
  }

  if (cmd === 'remove') {
    const id = args._[1];
    if (!id) {
      process.stderr.write('Missing id for remove.\n');
      process.exit(1);
    }
    const removed = removeTask(id);
    process.stdout.write(removed ? `Removed ${id}\n` : `Not found: ${id}\n`);
    process.exit(removed ? 0 : 1);
  }

  if (cmd === 'add') {
    const name = args.name || args._[1];
    const type = args.type || args._[2] || 'once';
    const runAt = args['run-at'] || args.runAt || args._[3] || null;
    const payloadArg = args.payload || args._[4] || null;
    if (!name) {
      process.stderr.write('Missing name for add.\n');
      process.exit(1);
    }
    const payload = parsePayload(payloadArg);
    const id = addTask({
      name,
      type,
      nextRunAt: runAt,
      cronExpr: args.cron || null,
      payload,
    });
    process.stdout.write(`Added task ${id}\n`);
    process.exit(0);
  }

  process.stderr.write(`Unknown command: ${cmd}\n`);
  printUsage();
  process.exit(1);
}

async function loadToolDefinitions() {
  const mcpConfigPath = join(__dirname, '..', '.mcp.json');

  try {
    const config = JSON.parse(await readFile(mcpConfigPath, 'utf-8'));
    const tools = [];

    // Extract tools from MCP servers
    if (config.mcpServers) {
      for (const [serverName, serverConfig] of Object.entries(config.mcpServers)) {
        // In practice, would load actual tool definitions from MCP server
        // For now, return server names as tool categories
        tools.push({
          server: serverName,
          name: serverName,
          description: serverConfig.description || `Tools from ${serverName} server`,
          deferred: serverConfig.deferLoading || false,
          alwaysLoad: serverConfig.alwaysLoadTools || [],
        });
      }
    }

    return tools;
  } catch (_error) {
    // Config file doesn't exist or is invalid
    return [];
  }
}

function searchTools(tools, query, limit = 5) {
  const queryLower = query.toLowerCase();
  const queryWords = queryLower.split(/\s+/);

  // Score tools based on query match
  const scored = tools.map(tool => {
    const toolText = `${tool.name} ${tool.description}`.toLowerCase();
    let score = 0;

    // Exact match
    if (toolText.includes(queryLower)) {
      score += 10;
    }

    // Word matches
    for (const word of queryWords) {
      if (toolText.includes(word)) {
        score += 2;
      }
    }

    // Description relevance
    if (tool.description && tool.description.toLowerCase().includes(queryLower)) {
      score += 5;
    }

    return { ...tool, score };
  });

  // Sort by score and return top results
  return scored
    .filter(t => t.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}

export async function searchToolDefinitions(query, limit = 5) {
  const tools = await loadToolDefinitions();
  const results = searchTools(tools, query, limit);

  return {
    query,
    results,
    total_tools: tools.length,
    matches: results.length,
  };
}

