function getArtifactType(artifactPath) {
  const normalizedPath = artifactPath.replace(/\\/g, '/');

  if (normalizedPath.includes('/agents/')) return 'agent';
  if (normalizedPath.includes('/skills/')) return 'skill';
  if (normalizedPath.includes('/workflows/')) return 'workflow';
  if (normalizedPath.includes('/hooks/')) return 'hook';
  if (normalizedPath.includes('/schemas/')) return 'schema';
  if (normalizedPath.includes('/templates/')) return 'template';

  return 'unknown';
}

function getArtifactName(artifactPath) {
  const normalizedPath = artifactPath.replace(/\\/g, '/');
  const parts = normalizedPath.split('/');
  const filename = parts[parts.length - 1];

  // Remove extension
  return filename.replace(/\.(md|cjs|mjs|json)$/, '');
}

function readFileSafe(filePath) {
  try {
    return fs.readFileSync(filePath, 'utf-8');
  } catch (_err) {
    return null;
  }
}

function checkClaudeMdRouting(artifactPath, artifactType, artifactName) {
  if (!['agent', 'workflow'].includes(artifactType)) {
    return { applicable: false, passed: true, message: 'Not applicable for this artifact type' };
  }

  const claudeMd = readFileSafe(CLAUDE_MD);
  if (!claudeMd) {
    return { applicable: true, passed: false, message: 'Could not read CLAUDE.md' };
  }

  // Check if artifact name appears in routing table area
  const hasEntry = claudeMd.toLowerCase().includes(artifactName.toLowerCase());

  if (hasEntry) {
    return { applicable: true, passed: true, message: `Found "${artifactName}" in CLAUDE.md` };
  }

  return {
    applicable: true,
    passed: false,
    message: `No routing entry found for "${artifactName}" in CLAUDE.md`,
  };
}

function checkSkillCatalog(artifactPath, artifactType, artifactName) {
  if (artifactType !== 'skill') {
    return { applicable: false, passed: true, message: 'Not applicable for this artifact type' };
  }

  const catalog = readFileSafe(SKILL_CATALOG);
  if (!catalog) {
    return { applicable: true, passed: false, message: 'Could not read skill-catalog.md' };
  }

  const hasEntry = catalog.toLowerCase().includes(artifactName.toLowerCase());

  if (hasEntry) {
    return { applicable: true, passed: true, message: `Found "${artifactName}" in skill catalog` };
  }

  return {
    applicable: true,
    passed: false,
    message: `No catalog entry found for "${artifactName}" in skill-catalog.md`,
  };
}

function checkRoutingTable(artifactPath, artifactType, artifactName) {
  if (artifactType !== 'agent') {
    return { applicable: false, passed: true, message: 'Not applicable for this artifact type' };
  }

  const table = readFileSafe(ROUTING_TABLE);
  if (!table) {
    return { applicable: true, passed: false, message: 'Could not read routing-table.cjs' };
  }

  const hasEntry = table.toLowerCase().includes(artifactName.toLowerCase());

  if (hasEntry) {
    return {
      applicable: true,
      passed: true,
      message: `Found "${artifactName}" in routing-table.cjs`,
    };
  }

  return {
    applicable: true,
    passed: false,
    message: `No keywords/mapping found for "${artifactName}" in routing-table.cjs`,
  };
}

function checkAgentAssignment(artifactPath, artifactType, artifactName) {
  if (!['skill', 'workflow'].includes(artifactType)) {
    return { applicable: false, passed: true, message: 'Not applicable for this artifact type' };
  }

  // Search all agent files for reference to this artifact
  function searchDir(dir) {
    try {
      const items = fs.readdirSync(dir);
      for (const item of items) {
        const itemPath = path.join(dir, item);
        const stat = fs.statSync(itemPath);

        if (stat.isDirectory()) {
          const found = searchDir(itemPath);
          if (found) return found;
        } else if (item.endsWith('.md')) {
          const content = readFileSafe(itemPath);
          if (content && content.toLowerCase().includes(artifactName.toLowerCase())) {
            return itemPath;
          }
        }
      }
    } catch (_err) {
      // Ignore errors
    }
    return null;
  }

  const foundIn = searchDir(AGENTS_DIR);

  if (foundIn) {
    const relativePath = path.relative(PROJECT_ROOT, foundIn);
    return { applicable: true, passed: true, message: `Assigned to agent: ${relativePath}` };
  }

  return {
    applicable: true,
    passed: false,
    message: `No agent references "${artifactName}"`,
  };
}

function checkMemoryFiles(artifactPath, artifactType, artifactName) {
  const learnings = readFileSafe(LEARNINGS_MD) || '';
  const decisions = readFileSafe(DECISIONS_MD) || '';

  const inLearnings = learnings.toLowerCase().includes(artifactName.toLowerCase());
  const inDecisions = decisions.toLowerCase().includes(artifactName.toLowerCase());

  if (inLearnings || inDecisions) {
    const locations = [];
    if (inLearnings) locations.push('learnings.md');
    if (inDecisions) locations.push('decisions.md');
    return { applicable: true, passed: true, message: `Found in: ${locations.join(', ')}` };
  }

  return {
    applicable: true,
    passed: false,
    message: `No memory file mentions "${artifactName}"`,
  };
}

function checkSchemaValidation(artifactPath, artifactType, _artifactName) {
  const content = readFileSafe(artifactPath);
  if (!content) {
    return { applicable: true, passed: false, message: 'Could not read artifact file' };
  }

  // Basic structure checks based on type
  if (artifactType === 'agent' || artifactType === 'workflow') {
    // Check for YAML frontmatter
    if (!content.startsWith('---') && !content.includes('# ')) {
      return { applicable: true, passed: false, message: 'Missing frontmatter or header' };
    }
  }

  if (artifactType === 'skill') {
    // Check for skill structure
    if (!content.includes('## ') && !content.includes('# ')) {
      return { applicable: true, passed: false, message: 'Missing skill structure' };
    }
  }

  if (artifactType === 'hook') {
    // Check for function export
    if (!content.includes('module.exports') && !content.includes('export ')) {
      return { applicable: true, passed: false, message: 'Missing module export' };
    }
  }

  return { applicable: true, passed: true, message: 'Basic structure validated' };
}

function checkTestsExist(artifactPath, artifactType, _artifactName) {
  // Only applicable for hooks and tools
  if (!['hook', 'tool'].includes(artifactType) && !artifactPath.includes('/tools/')) {
    return { applicable: false, passed: true, message: 'Not applicable for this artifact type' };
  }

  // Look for test file
  const dir = path.dirname(artifactPath);
  const baseName = path.basename(artifactPath, path.extname(artifactPath));
  const testPatterns = [
    `${baseName}.test.cjs`,
    `${baseName}.test.mjs`,
    `${baseName}.test.js`,
    `${baseName}.spec.cjs`,
    `${baseName}.spec.mjs`,
    `${baseName}.spec.js`,
  ];

  for (const pattern of testPatterns) {
    const testPath = path.join(dir, pattern);
    if (fs.existsSync(testPath)) {
      return { applicable: true, passed: true, message: `Test file found: ${pattern}` };
    }
  }

  return {
    applicable: true,
    passed: false,
    message: 'No test file found',
  };
}

function checkDocumentationComplete(artifactPath, _artifactType, _artifactName) {
  const content = readFileSafe(artifactPath);
  if (!content) {
    return { applicable: true, passed: false, message: 'Could not read artifact file' };
  }

  const foundPlaceholders = [];
  for (const placeholder of PLACEHOLDER_STRINGS) {
    if (content.toLowerCase().includes(placeholder.toLowerCase())) {
      foundPlaceholders.push(placeholder);
    }
  }

  if (foundPlaceholders.length > 0) {
    return {
      applicable: true,
      passed: false,
      message: `Found placeholders: ${foundPlaceholders.join(', ')}`,
    };
  }

  return { applicable: true, passed: true, message: 'No placeholder text found' };
}

function checkEvolutionState(artifactPath, artifactType, artifactName) {
  const stateContent = readFileSafe(EVOLUTION_STATE);
  if (!stateContent) {
    return { applicable: true, passed: false, message: 'Could not read evolution-state.json' };
  }

  const hasEntry = stateContent.toLowerCase().includes(artifactName.toLowerCase());

  if (hasEntry) {
    return { applicable: true, passed: true, message: `Found in evolution-state.json` };
  }

  return {
    applicable: true,
    passed: false,
    message: `No evolution state entry for "${artifactName}"`,
  };
}

function checkRouterDiscoverability(artifactPath, artifactType, artifactName) {
  if (!['agent', 'skill'].includes(artifactType)) {
    return { applicable: false, passed: true, message: 'Not applicable for this artifact type' };
  }

  // For agents: need CLAUDE.md + routing-table
  // For skills: need catalog + agent assignment

  if (artifactType === 'agent') {
    const claudeCheck = checkClaudeMdRouting(artifactPath, artifactType, artifactName);
    const routerCheck = checkRoutingTable(artifactPath, artifactType, artifactName);

    if (claudeCheck.passed && routerCheck.passed) {
      return { applicable: true, passed: true, message: 'Agent is discoverable by Router' };
    }

    return {
      applicable: true,
      passed: false,
      message: 'Agent may not be discoverable - check CLAUDE.md and routing-table',
    };
  }

  if (artifactType === 'skill') {
    const catalogCheck = checkSkillCatalog(artifactPath, artifactType, artifactName);
    const assignmentCheck = checkAgentAssignment(artifactPath, artifactType, artifactName);

    if (catalogCheck.passed && assignmentCheck.passed) {
      return { applicable: true, passed: true, message: 'Skill is discoverable by agents' };
    }

    return {
      applicable: true,
      passed: false,
      message: 'Skill may not be discoverable - check catalog and agent assignments',
    };
  }

  return { applicable: false, passed: true, message: 'Not applicable' };
}

function validateArtifact(artifactPath) {
  // Resolve to absolute path
  const absolutePath = path.isAbsolute(artifactPath)
    ? artifactPath
    : path.join(process.cwd(), artifactPath);

  // Check if artifact exists
  if (!fs.existsSync(absolutePath)) {
    console.error(`Error: Artifact not found: ${absolutePath}`);
    return { passed: false, exitCode: 2 };
  }

  const artifactType = getArtifactType(absolutePath);
  const artifactName = getArtifactName(absolutePath);

  console.log('\n===============================================');
  console.log(' POST-CREATION VALIDATION');
  console.log('===============================================');
  console.log(`Artifact: ${artifactPath}`);
  console.log(`Type: ${artifactType}`);
  console.log(`Name: ${artifactName}`);
  console.log('-----------------------------------------------\n');

  const checks = [
    { name: '1. CLAUDE.md Routing Entry', fn: checkClaudeMdRouting },
    { name: '2. Skill Catalog Entry', fn: checkSkillCatalog },
    { name: '3. Routing Table Keywords', fn: checkRoutingTable },
    { name: '4. Agent Assignment', fn: checkAgentAssignment },
    { name: '5. Memory File Updates', fn: checkMemoryFiles },
    { name: '6. Schema Validation', fn: checkSchemaValidation },
    { name: '7. Tests Exist', fn: checkTestsExist },
    { name: '8. Documentation Complete', fn: checkDocumentationComplete },
    { name: '9. Evolution State Updated', fn: checkEvolutionState },
    { name: '10. Router Discoverability', fn: checkRouterDiscoverability },
  ];

  let failedCount = 0;
  let passedCount = 0;
  let skippedCount = 0;

  for (const check of checks) {
    const result = check.fn(absolutePath, artifactType, artifactName);

    let status;
    if (!result.applicable) {
      status = 'SKIP';
      skippedCount++;
    } else if (result.passed) {
      status = 'PASS';
      passedCount++;
    } else {
      status = 'FAIL';
      failedCount++;
    }

    const statusStr = status === 'PASS' ? '[PASS]' : status === 'FAIL' ? '[FAIL]' : '[SKIP]';
    console.log(`${statusStr} ${check.name}`);
    console.log(`       ${result.message}\n`);
  }

  console.log('-----------------------------------------------');
  console.log(`Results: ${passedCount} passed, ${failedCount} failed, ${skippedCount} skipped`);
  console.log('===============================================\n');

  if (failedCount > 0) {
    console.log('VALIDATION FAILED - Fix the issues above before marking task complete.\n');
    return { passed: false, exitCode: 1 };
  }

  console.log('VALIDATION PASSED - Artifact is properly integrated.\n');
  return { passed: true, exitCode: 0 };
}

function getRecentArtifacts(hoursAgo = 24) {
  const stateContent = readFileSafe(EVOLUTION_STATE);
  if (!stateContent) return [];

  try {
    const state = JSON.parse(stateContent);
    const cutoff = Date.now() - hoursAgo * 60 * 60 * 1000;
    const recent = [];

    // Check currentEvolution
    if (state.currentEvolution?.artifacts) {
      for (const artifact of state.currentEvolution.artifacts) {
        if (artifact.path) {
          recent.push(path.join(PROJECT_ROOT, artifact.path));
        }
      }
    }

    // Check completed evolutions
    if (state.evolutions) {
      for (const evolution of state.evolutions) {
        const completedAt = new Date(evolution.completedAt).getTime();
        if (completedAt > cutoff && evolution.path) {
          recent.push(path.join(PROJECT_ROOT, evolution.path));
        }
      }
    }

    return recent;
  } catch (err) {
    console.error('Error parsing evolution state:', err.message);
    return [];
  }
}

function main() {
  const args = process.argv.slice(2);

  if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
    console.log(`
Usage: validate-integration.cjs <artifact-path>
       validate-integration.cjs --recent
       validate-integration.cjs --all

Options:
  <artifact-path>  Path to the artifact to validate
  --recent         Validate recently created artifacts (last 24 hours)
  --all            Validate all artifacts in evolution state
  --help, -h       Show this help message

Exit codes:
  0 = All checks passed
  1 = One or more checks failed
  2 = Invalid arguments or artifact not found
`);
    process.exit(0);
  }

  if (args.includes('--recent')) {
    const recent = getRecentArtifacts(24);
    if (recent.length === 0) {
      console.log('No recently created artifacts found.\n');
      process.exit(0);
    }

    console.log(`Found ${recent.length} recently created artifact(s).\n`);

    let anyFailed = false;
    for (const artifactPath of recent) {
      if (fs.existsSync(artifactPath)) {
        const result = validateArtifact(artifactPath);
        if (!result.passed) anyFailed = true;
      } else {
        console.log(`Skipping (not found): ${artifactPath}\n`);
      }
    }

    process.exit(anyFailed ? 1 : 0);
  }

  // Validate single artifact
  const result = validateArtifact(args[0]);
  process.exit(result.exitCode);
}

function getISOWeek(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const weekNo = Math.ceil(((d - yearStart) / MS_PER_DAY + 1) / 7);
  return { year: d.getUTCFullYear(), week: weekNo };
}

function getWeekString(date) {
  const { year, week } = getISOWeek(date);
  return `${year}-W${String(week).padStart(2, '0')}`;
}

function getWeekBounds(date) {
  const d = new Date(date);
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1); // Monday = start
  const start = new Date(d.setDate(diff));
  start.setHours(0, 0, 0, 0);
  const end = new Date(start);
  end.setDate(end.getDate() + 6);
  end.setHours(23, 59, 59, 999);
  return { start, end };
}

function readErrorLogs() {
  const errorsFile = path.join(ERROR_REPORTS_DIR, 'errors.jsonl');

  if (!fs.existsSync(errorsFile)) {
    return [];
  }

  try {
    const content = fs.readFileSync(errorsFile, 'utf8');
    if (!content.trim()) return [];

    const lines = content.split('\n').filter(line => line.trim());
    const errors = [];

    for (const line of lines) {
      try {
        errors.push(JSON.parse(line));
      } catch (_e) {
        // Skip malformed
      }
    }

    return errors;
  } catch (_err) {
    return [];
  }
}

function filterByWeek(errors, weekStart, weekEnd) {
  return errors.filter(e => {
    if (!e.timestamp) return false;
    const t = new Date(e.timestamp).getTime();
    return t >= weekStart.getTime() && t <= weekEnd.getTime();
  });
}

function rankAgents(errors) {
  const counts = {};
  const severityCounts = {};

  for (const error of errors) {
    const agent = error.context?.agentName || 'unknown';
    counts[agent] = (counts[agent] || 0) + 1;

    if (!severityCounts[agent]) {
      severityCounts[agent] = { CRITICAL: 0, HIGH: 0, MEDIUM: 0, LOW: 0 };
    }
    if (error.severity) {
      severityCounts[agent][error.severity] = (severityCounts[agent][error.severity] || 0) + 1;
    }
  }

  // Sort by error count (ascending = best first)
  return Object.entries(counts)
    .map(([agent, count]) => ({
      agent,
      errorCount: count,
      severities: severityCounts[agent],
      score: calculateAgentScore(count, severityCounts[agent]),
    }))
    .sort((a, b) => a.errorCount - b.errorCount);
}

function calculateAgentScore(count, severities) {
  let score = 100;
  score -= count * 2;
  score -= (severities.CRITICAL || 0) * 15;
  score -= (severities.HIGH || 0) * 8;
  score -= (severities.MEDIUM || 0) * 3;
  score -= (severities.LOW || 0) * 1;
  return Math.max(0, Math.min(100, score));
}

function analyzeHookReliability(errors) {
  const hookErrors = errors.filter(e => e.category === 'HOOK_FAILURE');
  const hookCounts = {};

  for (const error of hookErrors) {
    const hook = error.source?.location || 'unknown';
    hookCounts[hook] = (hookCounts[hook] || 0) + 1;
  }

  return Object.entries(hookCounts)
    .map(([hook, count]) => ({ hook, failures: count }))
    .sort((a, b) => b.failures - a.failures);
}

function analyzeToolReliability(errors) {
  const toolErrors = errors.filter(e => e.category === 'TOOL_FAILURE');
  const toolCounts = {};

  for (const error of toolErrors) {
    const tool = error.context?.toolName || 'unknown';
    toolCounts[tool] = (toolCounts[tool] || 0) + 1;
  }

  return Object.entries(toolCounts)
    .map(([tool, count]) => ({ tool, failures: count }))
    .sort((a, b) => b.failures - a.failures);
}

function calculateTrend(thisWeek, lastWeek) {
  if (lastWeek === 0) {
    return {
      direction: thisWeek > 0 ? 'up' : 'stable',
      percentage: thisWeek > 0 ? 100 : 0,
      text: thisWeek > 0 ? `+${thisWeek} new errors` : 'No errors',
    };
  }

  const diff = thisWeek - lastWeek;
  const percentage = Math.round((diff / lastWeek) * 100);

  return {
    direction: diff > 0 ? 'up' : diff < 0 ? 'down' : 'stable',
    percentage: Math.abs(percentage),
    text:
      diff > 0
        ? `+${percentage}% increase`
        : diff < 0
          ? `-${Math.abs(percentage)}% decrease`
          : 'No change',
  };
}

function generateWeeklyAnalysis(weekDate = new Date()) {
  const { start: weekStart, end: weekEnd } = getWeekBounds(weekDate);
  const weekStr = getWeekString(weekDate);

  // Previous week
  const prevWeekDate = new Date(weekStart);
  prevWeekDate.setDate(prevWeekDate.getDate() - 7);
  const { start: prevStart, end: prevEnd } = getWeekBounds(prevWeekDate);
  const prevWeekStr = getWeekString(prevWeekDate);

  // Read all errors
  const allErrors = readErrorLogs();

  // Filter by weeks
  const thisWeekErrors = filterByWeek(allErrors, weekStart, weekEnd);
  const lastWeekErrors = filterByWeek(allErrors, prevStart, prevEnd);

  // Calculate trend
  const trend = calculateTrend(thisWeekErrors.length, lastWeekErrors.length);

  // Detect patterns for this week
  const patterns = patternDetector.detectPatterns(thisWeekErrors);
  const recommendations = patternDetector.generateRecommendations(patterns);

  // Rankings and reliability
  const agentRanking = rankAgents(thisWeekErrors);
  const hookReliability = analyzeHookReliability(thisWeekErrors);
  const toolReliability = analyzeToolReliability(thisWeekErrors);

  // Critical issues
  const criticalErrors = thisWeekErrors.filter(e => e.severity === 'CRITICAL');

  return {
    week: weekStr,
    previousWeek: prevWeekStr,
    generatedAt: new Date().toISOString(),
    period: {
      start: weekStart.toISOString(),
      end: weekEnd.toISOString(),
    },
    summary: {
      totalErrors: thisWeekErrors.length,
      previousWeekErrors: lastWeekErrors.length,
      trend,
    },
    agentRanking,
    hookReliability,
    toolReliability,
    patterns,
    recommendations,
    criticalIssues: criticalErrors.map(e => ({
      errorId: e.errorId,
      message: e.message,
      timestamp: e.timestamp,
      agent: e.context?.agentName,
    })),
  };
}

function generateMarkdown(analysis) {
  const lines = [];

  lines.push(`# Weekly Error Analysis - ${analysis.week}`);
  lines.push('');
  lines.push(`Generated: ${analysis.generatedAt}`);
  lines.push(
    `Period: ${analysis.period.start.split('T')[0]} to ${analysis.period.end.split('T')[0]}`
  );
  lines.push('');

  // Summary with Trend
  lines.push('## Summary');
  lines.push('');
  const trendIcon =
    analysis.summary.trend.direction === 'up'
      ? '↑'
      : analysis.summary.trend.direction === 'down'
        ? '↓'
        : '→';
  lines.push(`| Metric | This Week | Last Week | Trend |`);
  lines.push(`|--------|-----------|-----------|-------|`);
  lines.push(
    `| Total Errors | ${analysis.summary.totalErrors} | ${analysis.summary.previousWeekErrors} | ${trendIcon} ${analysis.summary.trend.text} |`
  );
  lines.push('');

  // Critical Issues
  if (analysis.criticalIssues.length > 0) {
    lines.push('## Critical Issues Requiring Immediate Action');
    lines.push('');
    for (const issue of analysis.criticalIssues) {
      lines.push(`- **${issue.errorId}**: ${issue.message}`);
      if (issue.agent) lines.push(`  - Agent: ${issue.agent}`);
      lines.push(`  - Time: ${issue.timestamp}`);
    }
    lines.push('');
  }

  // Agent Performance Ranking
  lines.push('## Agent Performance Ranking');
  lines.push('');
  lines.push('| Rank | Agent | Errors | Score | Critical | High | Medium | Low |');
  lines.push('|------|-------|--------|-------|----------|------|--------|-----|');
  analysis.agentRanking.forEach((agent, index) => {
    const s = agent.severities;
    lines.push(
      `| ${index + 1} | ${agent.agent} | ${agent.errorCount} | ${agent.score}/100 | ${s.CRITICAL} | ${s.HIGH} | ${s.MEDIUM} | ${s.LOW} |`
    );
  });
  lines.push('');

  // Hook Reliability
  if (analysis.hookReliability.length > 0) {
    lines.push('## Hook Reliability Analysis');
    lines.push('');
    lines.push('| Hook | Failures |');
    lines.push('|------|----------|');
    for (const hook of analysis.hookReliability) {
      lines.push(`| ${hook.hook} | ${hook.failures} |`);
    }
    lines.push('');
  }

  // Tool Reliability
  if (analysis.toolReliability.length > 0) {
    lines.push('## Tool Reliability Analysis');
    lines.push('');
    lines.push('| Tool | Failures |');
    lines.push('|------|----------|');
    for (const tool of analysis.toolReliability) {
      lines.push(`| ${tool.tool} | ${tool.failures} |`);
    }
    lines.push('');
  }

  // Recommendations
  if (analysis.recommendations.length > 0) {
    lines.push('## Recommendations for Improvement');
    lines.push('');
    for (const rec of analysis.recommendations) {
      lines.push(`### [${rec.priority}] ${rec.issue}`);
      lines.push(`- **Suggestion**: ${rec.suggestion}`);
      lines.push('');
    }
  }

  // Pattern Details
  lines.push('## Pattern Analysis');
  lines.push('');
  const p = analysis.patterns;
  lines.push(`- Repeated Errors: ${p.repeatedErrors?.length || 0}`);
  lines.push(`- Error Cascades: ${p.cascades?.length || 0}`);
  lines.push(`- Agent Issues: ${p.agentIssues?.length || 0}`);
  lines.push(`- Hook Failures: ${p.hookFailures?.length || 0}`);
  lines.push(`- Tool Failures: ${p.toolFailures?.length || 0}`);
  lines.push(`- Severity Escalations: ${p.severityEscalations?.length || 0}`);
  lines.push('');

  return lines.join('\n');
}

function saveReport(markdown, week, outputPath) {
  const dir = outputPath ? path.dirname(outputPath) : ERROR_SUMMARIES_DIR;
  const filePath = outputPath || path.join(ERROR_SUMMARIES_DIR, `weekly-analysis-${week}.md`);

  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  fs.writeFileSync(filePath, markdown, 'utf8');
  return filePath;
}

function parseArgs() {
  const args = process.argv.slice(2);
  const result = { week: null, output: null };

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--week' && args[i + 1]) {
      result.week = args[i + 1];
      i++;
    } else if (args[i] === '--output' && args[i + 1]) {
      result.output = args[i + 1];
      i++;
    }
  }

  return result;
}

function parseWeekString(weekStr) {
  const match = weekStr.match(/^(\d{4})-W(\d{2})$/);
  if (!match) {
    throw new Error(`Invalid week format: ${weekStr}. Expected YYYY-WXX`);
  }

  const year = parseInt(match[1], 10);
  const week = parseInt(match[2], 10);

  // Find the first day of the year
  const jan1 = new Date(year, 0, 1);
  const jan1Day = jan1.getDay();

  // Find Monday of week 1
  const week1Monday = new Date(jan1);
  week1Monday.setDate(jan1.getDate() + (jan1Day <= 4 ? 1 - jan1Day : 8 - jan1Day));

  // Add weeks
  const targetDate = new Date(week1Monday);
  targetDate.setDate(week1Monday.getDate() + (week - 1) * 7);

  return targetDate;
}

async function main() {
  const args = parseArgs();

  let weekDate = new Date();
  if (args.week) {
    try {
      weekDate = parseWeekString(args.week);
    } catch (err) {
      console.error(`Error: ${err.message}`);
      process.exit(1);
    }
  }

  console.log(`Generating weekly error analysis for ${getWeekString(weekDate)}...`);

  const analysis = generateWeeklyAnalysis(weekDate);
  const markdown = generateMarkdown(analysis);
  const filePath = saveReport(markdown, analysis.week, args.output);

  console.log(`\nReport generated: ${filePath}`);
  console.log(`\nSummary:`);
  console.log(`  Total errors this week: ${analysis.summary.totalErrors}`);
  console.log(`  Previous week: ${analysis.summary.previousWeekErrors}`);
  console.log(`  Trend: ${analysis.summary.trend.text}`);
  console.log(`  Critical issues: ${analysis.criticalIssues.length}`);
  console.log(`  Recommendations: ${analysis.recommendations.length}`);

  if (analysis.criticalIssues.length > 0) {
    console.log(`\nCritical Issues:`);
    for (const issue of analysis.criticalIssues.slice(0, 3)) {
      console.log(`  - ${issue.errorId}: ${issue.message?.substring(0, 50)}...`);
    }
  }
}

