function listCommandFiles(dir) {
  if (!fs.existsSync(dir)) return [];
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...listCommandFiles(fullPath));
    } else if (entry.isFile() && entry.name.endsWith('.md')) {
      files.push(fullPath);
    }
  }
  return files;
}

function parseFrontmatter(content) {
  const lines = content.split(/\r?\n/);
  if (lines[0] !== '---') return null;
  let endIndex = -1;
  for (let i = 1; i < lines.length; i += 1) {
    if (lines[i] === '---') {
      endIndex = i;
      break;
    }
  }
  if (endIndex === -1) return null;
  const frontmatterLines = lines.slice(1, endIndex);
  const frontmatter = {};
  for (const line of frontmatterLines) {
    const match = line.match(/^([A-Za-z0-9_-]+)\s*:\s*(.*)$/);
    if (match) {
      frontmatter[match[1]] = match[2];
    }
  }
  return frontmatter;
}

function validateCommandFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  if (!content.trim()) {
    return [filePath + ': empty file'];
  }
  const frontmatter = parseFrontmatter(content);
  if (!frontmatter) {
    return [filePath + ': missing frontmatter (---)'];
  }
  if (!frontmatter.description || !String(frontmatter.description).trim()) {
    return [filePath + ': missing frontmatter description'];
  }
  return [];
}

function main() {
  const files = listCommandFiles(COMMANDS_DIR);
  if (files.length === 0) {
    console.error('No command markdown files found.');
    process.exit(1);
  }

  const errors = [];
  for (const filePath of files) {
    errors.push(...validateCommandFile(filePath));
  }

  if (errors.length > 0) {
    console.error('Command validation failed:');
    for (const error of errors) {
      console.error('- ' + error);
    }
    process.exit(1);
  }

  console.log('Command validation passed (' + files.length + ' files).');
}

async function loadAgentPermissions(agentName) {
  const configPath = join(__dirname, '../../config.yaml');
  const configContent = await readFile(configPath, 'utf8');
  const config = yaml.load(configContent);

  const agentConfig = config.agent_routing?.[agentName];
  const toolRestrictions = config.tool_restrictions?.[agentName];

  if (toolRestrictions) {
    return {
      allowed: toolRestrictions.allowed_tools || [],
      restricted: toolRestrictions.restricted_tools || [],
    };
  }

  // Default permissions based on agent complexity
  if (agentConfig) {
    if (agentConfig.complexity === 'high') {
      return {
        allowed: PermissionLevels.FULL_ACCESS,
        restricted: [],
      };
    } else if (agentConfig.complexity === 'medium') {
      return {
        allowed: PermissionLevels.READ_WRITE,
        restricted: ['Bash', 'Docker'],
      };
    } else {
      return {
        allowed: PermissionLevels.READ_ONLY,
        restricted: ['Write', 'Edit', 'Bash', 'Docker'],
      };
    }
  }

  // Default: read-only
  return {
    allowed: PermissionLevels.READ_ONLY,
    restricted: [],
  };
}

export async function checkPermission(agentName, toolName) {
  const permissions = await loadAgentPermissions(agentName);

  // Check restricted list first
  if (permissions.restricted.includes(toolName)) {
    return {
      allowed: false,
      reason: `Tool ${toolName} is restricted for agent ${agentName}`,
    };
  }

  // Check allowed list
  if (permissions.allowed.length > 0 && !permissions.allowed.includes(toolName)) {
    return {
      allowed: false,
      reason: `Tool ${toolName} is not in allowed list for agent ${agentName}`,
    };
  }

  return {
    allowed: true,
  };
}

