export async function updateSDKSession(sessionId, updates) {
  const session = await loadSDKSession(sessionId);

  if (!session) {
    throw new Error(`Session ${sessionId} not found`);
  }

  // Update session
  Object.assign(session, updates);
  session.updated_at = new Date().toISOString();

  // MEMORY SAFETY: Enforce limits on all arrays to prevent unbounded growth
  if (session.messages) {
    session.messages = enforceArrayLimit(session.messages, MAX_MESSAGES);
  }
  if (session.tool_calls) {
    session.tool_calls = enforceArrayLimit(session.tool_calls, MAX_TOOL_CALLS);
  }
  if (session.history) {
    session.history = enforceArrayLimit(session.history, MAX_HISTORY);
  }

  // Save updated session
  await writeFile(getSessionFilePath(sessionId), JSON.stringify(session, null, 2), 'utf8');

  return session;
}

