  const session = await loadSDKSession(sessionId);

  if (!session) {
    throw new Error(`Session ${sessionId} not found`);
  }

  if (!session.messages) {
    session.messages = [];
  }

  session.messages.push({
    ...message,
    timestamp: new Date().toISOString(),
  });

  // MEMORY SAFETY: Enforce limit on messages array
  session.messages = enforceArrayLimit(session.messages, MAX_MESSAGES);

  return await updateSDKSession(sessionId, { messages: session.messages });
}

export async function addSessionToolCall(sessionId, toolCall) {
  const session = await loadSDKSession(sessionId);

  if (!session) {
    throw new Error(`Session ${sessionId} not found`);
  }

  if (!session.tool_calls) {
    session.tool_calls = [];
  }

  session.tool_calls.push({
    ...toolCall,
    timestamp: new Date().toISOString(),
  });

  // MEMORY SAFETY: Enforce limit on tool_calls array
  session.tool_calls = enforceArrayLimit(session.tool_calls, MAX_TOOL_CALLS);

  return await updateSDKSession(sessionId, { tool_calls: session.tool_calls });
}

export async function updateSessionCost(sessionId, costUpdate) {
  const session = await loadSDKSession(sessionId);

  if (!session) {
    throw new Error(`Session ${sessionId} not found`);
  }

  session.cost = {
    total: (session.cost?.total || 0) + (costUpdate.total || 0),
    input_tokens: (session.cost?.input_tokens || 0) + (costUpdate.input_tokens || 0),
    output_tokens: (session.cost?.output_tokens || 0) + (costUpdate.output_tokens || 0),
    tool_calls: (session.cost?.tool_calls || 0) + (costUpdate.tool_calls || 1),
  };

  return await updateSDKSession(sessionId, { cost: session.cost });
}

export async function closeSDKSession(sessionId, reason = 'completed') {
  return await updateSDKSession(sessionId, {
    status: 'closed',
    closed_at: new Date().toISOString(),
    close_reason: reason,
  });
}

export async function getSessionModelInfo(sessionId) {
  const session = await loadSDKSession(sessionId);

  if (!session) {
    return null;
  }

  return {
    session_id: sessionId,
    role: session.role,
    model: session.model,
    temperature: session.temperature,
    router_enabled: session.settings?.router_enabled ?? false,
    auto_route_to_orchestrator: session.settings?.auto_route_to_orchestrator ?? false,
  };
}

function readInput() {
  const chunks = [];
  process.stdin.setEncoding('utf8');

  return new Promise(resolve => {
    process.stdin.on('data', chunk => chunks.push(chunk));
    process.stdin.on('end', () => {
      const input = chunks.join('');
      if (!input.trim()) {
        resolve(null);
        return;
      }

      try {
        resolve(JSON.parse(input));
      } catch (error) {
        resolve({ error: `Invalid JSON input: ${error.message}` });
      }
    });
  });
}

function extractTaskPrompt(toolInput) {
  // Handle null/undefined
  if (!toolInput) {
    return '';
  }

  // Task tool input structure varies, check common patterns
  if (typeof toolInput === 'string') {
    return toolInput;
  }

  if (toolInput.prompt) {
    return toolInput.prompt;
  }

  if (toolInput.task) {
    return toolInput.task;
  }

  if (toolInput.instruction) {
    return toolInput.instruction;
  }

  // Return stringified version if none of the above
  return JSON.stringify(toolInput);
}

function validateTaskTemplate(toolInput) {
  const prompt = extractTaskPrompt(toolInput);

  // Try to parse as JSON
  let taskData;
  try {
    taskData = typeof prompt === 'string' ? JSON.parse(prompt) : prompt;
  } catch (error) {
    return {
      valid: false,
      reason: 'Task prompt is not valid JSON',
      missingFields: REQUIRED_FIELDS,
      error: error.message,
    };
  }

  // Check for required fields
  const missingFields = REQUIRED_FIELDS.filter(field => !(field in taskData));

  if (missingFields.length > 0) {
    return {
      valid: false,
      reason: 'Missing required fields from agent-task.schema.json',
      missingFields,
    };
  }

  // Check nested required fields in context
  if (taskData.context) {
    const missingContextFields = REQUIRED_CONTEXT_FIELDS.filter(
      field => !(field in taskData.context)
    );

    if (missingContextFields.length > 0) {
      return {
        valid: false,
        reason: 'Missing required context fields',
        missingFields: missingContextFields.map(f => `context.${f}`),
      };
    }
  }

  // Check nested required fields in verification (v2.1.0+)
  if (taskData.verification) {
    const missingVerificationFields = REQUIRED_VERIFICATION_FIELDS.filter(
      field => !(field in taskData.verification)
    );

    if (missingVerificationFields.length > 0) {
      return {
        valid: false,
        reason: 'Missing required verification fields (v2.1.0+)',
        missingFields: missingVerificationFields.map(f => `verification.${f}`),
      };
    }
  }

  // Check for optimization fields (warning, not blocking)
  const missingOptimizations = OPTIMIZATION_FIELDS.filter(field => !(field in taskData));

  return {
    valid: true,
    missingOptimizations,
    hasOptimizations: missingOptimizations.length === 0,
  };
}

