async function main() {
  try {
    const input = await readInput();

    if (!input) {
      // No input, allow by default
      console.log(JSON.stringify({ decision: 'approve' }));
      return;
    }

    if (input.error) {
      // Input parsing error, allow (don't block on hook errors)
      console.log(JSON.stringify({ decision: 'approve' }));
      return;
    }

    const { tool_name, tool_input } = input;

    // Only validate Task tool calls
    if (tool_name !== 'Task') {
      console.log(JSON.stringify({ decision: 'approve' }));
      return;
    }

    // Validate task template
    const validationResult = validateTaskTemplate(tool_input);

    if (!validationResult.valid) {
      // Block invalid task calls
      const blockMessage = generateBlockMessage(validationResult);
      console.log(
        JSON.stringify({
          decision: 'block',
          reason: blockMessage,
          missing_fields: validationResult.missingFields || [],
          missing_optimizations: validationResult.missingOptimizations || [],
          has_optimizations: false,
          error: validationResult.error || null,
        })
      );
      return;
    }

    // Allow valid task calls
    console.log(
      JSON.stringify({
        decision: 'approve',
        missing_fields: [],
        missing_optimizations: validationResult.missingOptimizations || [],
        has_optimizations: validationResult.hasOptimizations === true,
      })
    );

    // Log warning if missing optimizations
    if (validationResult.missingOptimizations.length > 0) {
      console.error(
        `⚠️  Task template missing optimization fields: ${validationResult.missingOptimizations.join(', ')}`
      );
    }
  } catch (error) {
    // Never block on hook errors (fail-safe)
    console.error(`Hook error: ${error.message}`);
    console.log(JSON.stringify({ decision: 'approve' }));
  }
}

function isRootPath(filePath) {
  // Normalize path separators
  const normalized = filePath.replace(/\\/g, '/');
  // Check if path has no directory separators (except leading ./)
  const parts = normalized.split('/').filter(p => p);
  return parts.length === 1 || (parts.length === 2 && parts[0] === '.');
}

function getFilename(filePath) {
  return basename(filePath);
}

function suggestPath(filePath, reason) {
  const filename = getFilename(filePath);

  if (reason === 'root_violation') {
    // Suggest .claude/context/reports/ or .claude/context/tasks/ based on filename
    if (
      filename.includes('report') ||
      filename.includes('audit') ||
      filename.includes('analysis')
    ) {
      return `.claude/context/reports/${filename}`;
    } else if (filename.includes('task') || filename.includes('todo')) {
      return `.claude/context/tasks/${filename}`;
    } else {
      return `.claude/context/artifacts/${filename}`;
    }
  }

  if (reason === 'malformed_path') {
    // Try to reconstruct path
    // Common pattern: CdevprojectsLLM-RULES.claude... → .claude/...
    if (filePath.includes('.claude')) {
      const match = filePath.match(/\.claude[^\/]*\/(.+)/);
      if (match) {
        return `.claude/${match[1]}`;
      }
    }
    // Default suggestion
    return `.claude/context/artifacts/${filename}`;
  }

  return null;
}

function validateFilePath(filePath) {
  if (!filePath || typeof filePath !== 'string') {
    return { valid: true }; // Skip validation if no path
  }

  // Normalize path
  const normalized = filePath.replace(/\\/g, '/').trim();

  // Check malformed patterns
  for (const pattern of MALFORMED_PATTERNS) {
    if (pattern.test(normalized)) {
      return {
        valid: false,
        reason: 'malformed_path',
        message: `BLOCKED: Malformed file path detected. Path appears to have missing separators or corrupted Windows path format.`,
        suggested_path: suggestPath(normalized, 'malformed_path'),
      };
    }
  }

  // Check root directory violations
  if (isRootPath(normalized)) {
    const filename = getFilename(normalized);
    if (!rootAllowlist.includes(filename)) {
      return {
        valid: false,
        reason: 'root_violation',
        message: `BLOCKED: File "${filename}" not allowed in project root. Use appropriate .claude/ subdirectory. See .claude/rules/subagent-file-rules.md for correct locations.`,
        suggested_path: suggestPath(normalized, 'root_violation'),
      };
    }
  }

  // Check prohibited directories
  for (const prohibited of PROHIBITED_DIRS) {
    if (normalized.startsWith(prohibited) || normalized.includes(`/${prohibited}`)) {
      return {
        valid: false,
        reason: 'prohibited_directory',
        message: `BLOCKED: Cannot write to prohibited directory "${prohibited}". This location is reserved for build outputs or version control.`,
        suggested_path: `.claude/context/artifacts/${getFilename(normalized)}`,
      };
    }
  }

  return { valid: true };
}

function detectBashFileCreation(command) {
  if (!command || typeof command !== 'string') {
    return null;
  }

  // Patterns: echo "..." > file.md, cat <<EOF > file.md
  const patterns = [
    /echo\s+["'].*["']\s*>\s+[^\s&|;]+/,
    /cat\s+<<\s*\w+\s*>\s+[^\s&|;]+/,
    /printf\s+.*\s*>\s+[^\s&|;]+/,
  ];

  for (const pattern of patterns) {
    if (pattern.test(command)) {
      // Extract filename
      const match = command.match(/>\s+([^\s&|;]+)/);
      const filename = match ? match[1].trim() : 'file';
      return {
        detected: true,
        filename: filename,
        message: `BLOCKED: File creation via Bash redirects is blocked. Use Write tool instead.`,
      };
    }
  }

  return null;
}

async function main() {
  try {
    // Read JSON from stdin
    let input = '';
    for await (const chunk of process.stdin) {
      input += chunk.toString();
    }

    const data = JSON.parse(input);
    const toolName = data.tool_name || '';
    const toolInput = data.tool_input || {};

    // Skip validation for TodoWrite and Task tools
    if (toolName === 'TodoWrite' || toolName === 'Task') {
      console.log(JSON.stringify({ decision: 'approve' }));
      process.exit(0);
    }

    // Layer 2: Block Bash file creation
    if (toolName === 'Bash') {
      const command = toolInput.command || '';
      const bashFileCreation = detectBashFileCreation(command);

      if (bashFileCreation?.detected) {
        const response = {
          decision: 'block',
          reason: bashFileCreation.message,
          suggested_action: `Use Write tool to create ${bashFileCreation.filename} instead of Bash redirects.`,
        };
        console.log(JSON.stringify(response));
        process.exit(0);
      }
    }

    // Layer 1 & 3: Validate file paths for Write/Edit
    if (toolName === 'Write' || toolName === 'Edit') {
      const filePath = toolInput.file_path || toolInput.path || '';

      if (filePath) {
        const validation = validateFilePath(filePath);

        if (!validation.valid) {
          const response = {
            decision: 'block',
            reason: validation.message,
            suggested_path: validation.suggested_path,
          };
          console.log(JSON.stringify(response));
          process.exit(0);
        }
      }
    }

    // Allow by default
    console.log(JSON.stringify({ decision: 'approve' }));
    process.exit(0);
  } catch (error) {
    // On error, allow (fail open) but log warning
    console.error(
      JSON.stringify({
        decision: 'approve',
        warning: `Path validator error: ${error.message}`,
      })
    );
    process.exit(0);
  } finally {
    clearTimeout(timeout);
    // Clean up recursion guard
    delete process.env.CLAUDE_PATH_VALIDATOR_EXECUTING;
  }
}

function respond(obj) {
  try {
    process.stdout.write(JSON.stringify(obj));
  } catch {
    // ignore
  }
}

async function readStdinJson() {
  try {
    const chunks = [];
    for await (const c of process.stdin)
      chunks.push(Buffer.isBuffer(c) ? c : Buffer.from(String(c)));
    const text = Buffer.concat(chunks).toString('utf8').trim();
    if (!text) return null;
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function normalizeToolName(value) {
  if (typeof value === 'string') return value.trim();
  if (value == null) return '';
  return String(value).trim();
}

function isTaskToolName(value) {
  const lower = normalizeToolName(value).toLowerCase();
  return lower === 'task' || lower.startsWith('task(');
}

function safeFileId(input) {
  const raw = String(input ?? '');
  const hash = createHash('sha256').update(raw).digest('hex').slice(0, 10);
  const cleaned = raw.replace(/[^a-zA-Z0-9_-]+/g, '_').slice(0, 60);
  return `${cleaned || 'session'}-${hash}`;
}

function resolveTmpDir() {
  const raw =
    process.env.CLAUDE_HOOK_TMP_DIR ||
    process.env.CLAUDE_TMP_DIR ||
    process.env.CLAUDE_CONTEXT_TMP_DIR ||
    join(PROJECT_ROOT, '.claude', 'context', 'tmp');
  const s = String(raw || '').trim();
  if (!s) return join(PROJECT_ROOT, '.claude', 'context', 'tmp');
  return isAbsolute(s) ? s : resolve(PROJECT_ROOT, s);
}

function getTaskSpawnTarget(toolName, toolInput) {
  if (!isTaskToolName(toolName)) return null;
  const raw =
    toolInput?.subagent_type ??
    toolInput?.subagentType ??
    toolInput?.agent ??
    toolInput?.agent_name ??
    toolInput?.agentName ??
    toolInput?.subagent ??
    toolInput?.subagent_name ??
    toolInput?.subagentName ??
    null;
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim();
  return trimmed ? trimmed : null;
}

function readJson(path) {
  try {
    if (!existsSync(path)) return null;
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    return null;
  }
}

function getSelectedWorkflowFromState(state) {
  const decision =
    state?.routing?.decision && typeof state.routing.decision === 'object'
      ? state.routing.decision
      : null;
  const candidates = [
    decision?.selected_workflow,
    decision?.selectedWorkflow,
    decision?.workflow_selection,
    decision?.workflowSelection,
    state?.routing?.selected_workflow,
    state?.routing?.workflow_selection,
  ];
  for (const c of candidates) {
    if (typeof c === 'string' && c.trim()) return c.trim();
  }
  return '';
}

function isHeadlessWorkflowPath(workflowPath) {
  const s = String(workflowPath || '')
    .trim()
    .toLowerCase();
  if (!s) return false;
  return s.includes('-headless.yaml') || s.includes('-headless.yml');
}

async function main() {
  const hookInput = await readStdinJson();
  if (!hookInput || typeof hookInput !== 'object') {
    respond({ decision: 'approve' });
    return;
  }

  const toolName =
    hookInput.tool_name ?? hookInput.tool ?? hookInput.toolName ?? hookInput.name ?? '';
  const toolInput =
    hookInput.tool_input ?? hookInput.toolInput ?? hookInput.input ?? hookInput.params ?? {};
  if (!isTaskToolName(toolName)) {
    respond({ decision: 'approve' });
    return;
  }

  const tmpDir = resolveTmpDir();
  const sessionKey = String((await getSessionKeyForHook({ hookInput, tmpDir })) || '').trim();
  if (!sessionKey) {
    respond({ decision: 'approve' });
    return;
  }

  const statePath = join(tmpDir, 'routing-sessions', `${safeFileId(sessionKey)}.json`);
  const state = readJson(statePath);
  if (!state) {
    respond({ decision: 'approve' });
    return;
  }

  const routingCompleted = Boolean(state?.routing?.completed);
  if (!routingCompleted) {
    respond({ decision: 'approve' });
    return;
  }

  const selectedWorkflow = getSelectedWorkflowFromState(state);
  if (!isHeadlessWorkflowPath(selectedWorkflow)) {
    respond({ decision: 'approve' });
    return;
  }

  const spawnTarget = getTaskSpawnTarget(toolName, toolInput);
  if (!spawnTarget) {
    respond({ decision: 'approve' });
    return;
  }

  const handoffTarget =
    typeof state?.routing?.handoff_target === 'string' ? state.routing.handoff_target.trim() : '';
  const handoffCompleted = Boolean(state?.routing?.handoff_completed);

  if (!handoffCompleted && handoffTarget) {
    if (spawnTarget.toLowerCase() === handoffTarget.toLowerCase()) {
      respond({ decision: 'approve' });
      return;
    }

    respond({
      decision: 'deny',
      reason: `Headless workflow selected (${selectedWorkflow}). Routing requires handoff to "${handoffTarget}" first; do not spawn "${spawnTarget}".`,
    });
    return;
  }

  respond({
    decision: 'deny',
    reason: `Headless workflow selected (${selectedWorkflow}). Do not spawn subagents via Task after handoff; run the headless runner command instead (e.g. pnpm ship-readiness:headless:json).`,
  });
}

function safeRespond(obj) {
  if (responded) return;
  responded = true;
  try {
    process.stdout.write(JSON.stringify(obj));
  } catch {
    // ignore
  }
}

function approve() {
  safeRespond({ decision: 'approve' });
}

function block(reason) {
  safeRespond({ decision: 'block', reason });
}

const finalize = () => {
  if (resolved) return;
  resolved = true;
  resolve(Buffer.concat(chunks).toString('utf-8'));
};

function normalizeToolName(value) {
  if (typeof value === 'string') return value.trim();
  if (value == null) return '';
  return String(value).trim();
}

function normalizeAgentName(context) {
  const envActive =
    String(process.env.CLAUDE_AGENT_NAME || '').trim() ||
    String(process.env.CLAUDE_AGENT_ROLE || '').trim() ||
    String(process.env.CLAUDE_ACTIVE_AGENT || '').trim() ||
    String(process.env.CLAUDE_CURRENT_AGENT || '').trim() ||
    String(process.env.CLAUDE_AGENT || '').trim() ||
    String(process.env.CLAUDE_SUBAGENT_TYPE || '').trim();
  if (envActive) return envActive.toLowerCase();

  const fromContext =
    context?.agent_name ??
    context?.agentName ??
    context?.agent ??
    context?.agent_type ??
    context?.agentType ??
    context?.subagent_type ??
    context?.subagentType ??
    context?.role ??
    null;
  if (typeof fromContext === 'string' && fromContext.trim())
    return fromContext.trim().toLowerCase();
  return '';
}

function stableReason() {
  const id = createHash('sha256')
    .update('master-orchestrator-read-guard-v1')
    .digest('hex')
    .slice(0, 8);
  return [
    'MASTER-ORCHESTRATOR READ BLOCKED',
    'Master orchestrator must delegate analysis to subagents instead of reading files directly.',
    'Next: spawn `diagnostics-runner` (for diagnostics) or `analyst` (for file analysis).',
    `ref:${id}`,
  ].join('\n');
}

async function main() {
  const raw = await readStdinWithLimit().catch(() => '');
  if (!raw) return approve();

  let hookInput;
  try {
    hookInput = JSON.parse(raw);
  } catch {
    return approve();
  }

  const toolName = normalizeToolName(
    hookInput?.tool_name ?? hookInput?.tool ?? hookInput?.toolName ?? hookInput?.name
  ).toLowerCase();
  if (toolName !== 'read') return approve();

  const context = hookInput?.context ?? hookInput?.ctx ?? {};
  const agent = normalizeAgentName(context);
  if (agent !== 'master-orchestrator') return approve();

  const reason = stableReason();
  await logDenialIfBlocking({
    hookName: 'master-orchestrator-read-guard',
    hookInput,
    decision: 'block',
    reason,
  });
  return block(reason);
}

async function getManager() {
  if (!managerInstance) {
    managerInstance = createMemoryInjectionManager();
    await managerInstance.initialize();
  }

  return managerInstance;
}

async function main() {
  try {
    // Read input from stdin
    const input = await new Promise((resolve, reject) => {
      let data = '';

      process.stdin.on('data', chunk => {
        data += chunk;
      });

      process.stdin.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch (error) {
          reject(new Error(`Invalid JSON input: ${error.message}`));
        }
      });

      process.stdin.on('error', reject);

      // Timeout after 1 second
      setTimeout(() => {
        reject(new Error('stdin read timeout'));
      }, 1000);
    });

    const { tool_name: toolName, tool_input: toolInput, tool_result: toolResult, duration } = input;

    // Extract context
    const context = {
      sessionId: process.env.CLAUDE_SESSION_ID || 'default',
      toolName,
      toolParams: toolInput,
      duration,
    };

    // Get manager instance (lazy init)
    const manager = await getManager();

    // Capture tool result (async, non-blocking)
    // Use setImmediate to return immediately without waiting
    setImmediate(async () => {
      try {
        await manager.captureToolResult(context, toolResult);
      } catch (error) {
        console.error(`[Memory Capture] Background capture error: ${error.message}`);
      }
    });

    // Return immediately (don't block tool completion)
    const result = {
      captured: true,
      async: true,
    };

    process.stdout.write(JSON.stringify(result));
    process.exit(0);
  } catch (error) {
    // FAIL-SAFE: Never block tool completion
    console.error(`[Memory Capture] Error (non-blocking): ${error.message}`);

    const result = {
      captured: false,
      error: error.message,
    };

    process.stdout.write(JSON.stringify(result));
    process.exit(0);
  }
}

