async function main() {
  // Fast path: only Task calls can spawn router, so skip stdin parsing for other tools
  // if we have tool info in argv or env (reduces overhead for most calls)
  const envToolName = String(process.env.CLAUDE_TOOL_NAME || '')
    .trim()
    .toLowerCase();
  if (envToolName && envToolName !== 'task') {
    process.stdout.write(JSON.stringify({ decision: 'approve' }));
    return;
  }

  let hookInput = null;
  try {
    const raw = await readStdin();
    hookInput = raw ? JSON.parse(raw) : {};
  } catch {
    process.stdout.write(JSON.stringify({ decision: 'approve' }));
    return;
  }

  const toolName = hookInput.tool_name ?? hookInput.tool ?? '';
  const toolInput = hookInput.tool_input ?? hookInput.params ?? hookInput.input ?? {};

  const spawnTarget = getTaskSpawnTarget(toolName, toolInput);
  if (!spawnTarget || spawnTarget.toLowerCase() !== 'router') {
    process.stdout.write(JSON.stringify({ decision: 'approve' }));
    return;
  }

  try {
    const sessionKey = await getSessionKey(hookInput);
    const statePath = statePathForSessionKey(sessionKey);
    if (!existsSync(statePath)) {
      process.stdout.write(JSON.stringify({ decision: 'approve' }));
      return;
    }

    const state = JSON.parse(await readFile(statePath, 'utf-8'));
    const routingStarted = Boolean(state?.routing?.started_at);
    const routingCompleted = Boolean(state?.routing?.completed);
    if (!routingStarted && !routingCompleted) {
      process.stdout.write(JSON.stringify({ decision: 'approve' }));
      return;
    }

    // If routing is in-progress, block router re-runs to avoid loops/races.
    // CRITICAL: Check for stuck routing - if started too long ago, allow re-routing to recover.
    if (routingStarted && !routingCompleted) {
      const startedAtMs = parseDateMs(state?.routing?.started_at);
      const elapsedMs = startedAtMs != null ? Date.now() - startedAtMs : null;

      // If routing has been stuck for too long, allow re-routing to recover from deadlock
      if (elapsedMs != null && elapsedMs > STUCK_ROUTING_TIMEOUT_MS) {
        // Log recovery for debugging
        const recoveryInfo = `Routing stuck recovery: started ${Math.round(elapsedMs / 1000)}s ago, timeout ${Math.round(STUCK_ROUTING_TIMEOUT_MS / 1000)}s`;
        process.stderr.write(`[no-reroute-after-routing] ${recoveryInfo}\n`);
        process.stdout.write(JSON.stringify({ decision: 'approve' }));
        return;
      }

      const reason = [
        'ROUTER RE-RUN BLOCKED',
        'Routing is already in progress for this session.',
        'Do not spawn the router again; wait for routing to complete, then proceed.',
        elapsedMs != null
          ? `(Will auto-recover in ${Math.max(0, Math.round((STUCK_ROUTING_TIMEOUT_MS - elapsedMs) / 1000))}s if still stuck)`
          : '',
      ]
        .filter(Boolean)
        .join('\n');
      process.stdout.write(JSON.stringify({ decision: 'block', reason }));
      return;
    }

    // Routing completed: allow re-routing after a short cooldown window so the next user turn
    // can be classified. This keeps the "no reroute in the same request" invariant while
    // preventing multi-turn dead-ends.
    if (routingCompleted) {
      const completedAtMs =
        parseDateMs(state?.routing?.completed_at) ?? parseDateMs(state?.updated_at);

      // CRITICAL FIX: If cooldown has elapsed OR we can't determine when routing completed,
      // approve the router spawn to prevent multi-turn session deadlocks.
      // Previously, if completedAtMs was null, we'd fall through and block forever.
      if (completedAtMs == null || Date.now() - completedAtMs > REROUTE_COOLDOWN_MS) {
        process.stdout.write(JSON.stringify({ decision: 'approve' }));
        return;
      }

      // Within cooldown window - block to prevent loops in same request
      const reason = [
        'ROUTER RE-RUN BLOCKED (cooldown active)',
        'Routing just completed. Please wait a moment before re-routing.',
        `Cooldown: ${REROUTE_COOLDOWN_MS}ms`,
      ].join('\n');
      process.stdout.write(JSON.stringify({ decision: 'block', reason }));
      return;
    }

    // Note: If routingCompleted is true, we always return above (either approve or block).
    // All code paths are covered by the conditionals above.
  } catch {
    // Fail-open to avoid deadlocks on state parsing issues.
    process.stdout.write(JSON.stringify({ decision: 'approve' }));
  }
}

