}

function safeRespond(obj) {
  if (responded) return;
  responded = true;
  try {
    process.stdout.write(JSON.stringify(obj));
  } catch {
    // ignore
  }
}

function approve() {
  safeRespond({ decision: 'approve' });
}

function block(reason) {
  safeRespond({ decision: 'block', reason });
}

function normalizeToolName(value) {
  if (typeof value === 'string') return value.trim();
  if (value == null) return '';
  return String(value).trim();
}

async function readStdinJson() {
  const input = await new Promise(resolve => {
    const chunks = [];
    process.stdin.on('data', chunk => chunks.push(chunk));
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf-8')));
    process.stdin.on('error', () => resolve(''));
    setTimeout(() => resolve(chunks.length ? Buffer.concat(chunks).toString('utf-8') : ''), 250);
  });

  if (!input || !input.trim()) return null;
  try {
    return JSON.parse(input);
  } catch {
    return null;
  }
}

function getReadPath(toolInput) {
  const raw =
    toolInput?.path ??
    toolInput?.file_path ??
    toolInput?.filePath ??
    toolInput?.filename ??
    toolInput?.file ??
    null;
  return typeof raw === 'string' ? raw : null;
}

function resolveWorkspacePath(p) {
  const raw = String(p || '').trim();
  if (!raw) return null;
  if (isAbsolute(raw)) return raw;
  return resolve(PROJECT_ROOT, raw);
}

async function main() {
  const hookInput = await readStdinJson();
  const toolName = normalizeToolName(
    hookInput?.tool_name ?? hookInput?.tool ?? hookInput?.toolName ?? hookInput?.name
  );
  if (toolName.toLowerCase() !== 'read') {
    approve();
    return;
  }

  const toolInput =
    hookInput?.tool_input ?? hookInput?.toolInput ?? hookInput?.input ?? hookInput?.params ?? {};
  const path = getReadPath(toolInput);
  if (!path || !path.trim()) {
    approve();
    return;
  }

  const resolvedPath = resolveWorkspacePath(path);
  if (!resolvedPath) {
    approve();
    return;
  }

  let s;
  try {
    s = statSync(resolvedPath);
  } catch {
    approve();
    return;
  }

  if (s?.isDirectory?.()) {
    const reason = [
      'Read path guard: Read() cannot open directories.',
      `Requested path is a directory: ${path}`,
      resolvedPath !== path ? `Resolved path: ${resolvedPath}` : null,
      'Use `Glob`/`Search` (or delegate a subagent to use `Bash(dir/ls)`), then Read a specific file.',
    ]
      .filter(Boolean)
      .join('\n');
    await logDenialIfBlocking({
      hookName: 'read-path-guard',
      hookInput,
      decision: 'block',
      reason,
    });
    block(reason);
    return;
  }

  approve();
}

class VerificationResult {
  constructor() {
    this.verdict = 'PASS'; // PASS, CONCERNS, FAIL
    this.timestamp = new Date().toISOString();
    this.errors = [];
    this.warnings = [];
    this.deliverables_status = [];
    this.success_criteria_status = [];
    this.verification_steps = {
      step1_errors: { checked: false, found: [] },
      step2_warnings: { checked: false, found: [] },
      step3_deliverables: { checked: false, missing: [] },
      step4_criteria: { checked: false, unmet: [] },
      step5_verdict: { checked: false, agent_verdict: null },
    };
  }

  addError(message, severity = 'critical') {
    this.errors.push({ message, severity, timestamp: new Date().toISOString() });
    if (severity === 'critical') {
      this.verdict = 'FAIL';
    } else if (this.verdict === 'PASS') {
      this.verdict = 'CONCERNS';
    }
  }

  addWarning(message) {
    this.warnings.push({ message, timestamp: new Date().toISOString() });
    if (this.verdict === 'PASS') {
      this.verdict = 'CONCERNS';
    }
  }

  addDeliverableStatus(path, exists, validated, message = null) {
    this.deliverables_status.push({ path, exists, validated, message });
    if (!exists) {
      this.addError(`Deliverable not found: ${path}`, 'critical');
    } else if (!validated) {
      this.addWarning(`Deliverable empty or invalid: ${path}`);
    }
  }

  addCriteriaStatus(criterion, met, evidence = null) {
    this.success_criteria_status.push({ criterion, met, evidence });
    if (!met) {
      this.addError(`Success criterion not met: ${criterion}`, 'critical');
    }
  }

async function readStdin() {
  const chunks = [];
  for await (const chunk of stdin) {
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf-8');
}

function log(message) {
  stderr.write(`[post-delegation-verifier] ${message}\n`);
}

function extractTextFromResult(toolResult) {
  if (!toolResult) return '';

  // If string, return directly
  if (typeof toolResult === 'string') {
    return toolResult;
  }

  // If object with content field
  if (toolResult.content) {
    return typeof toolResult.content === 'string'
      ? toolResult.content
      : JSON.stringify(toolResult.content);
  }

  // If object with output field
  if (toolResult.output) {
    return typeof toolResult.output === 'string'
      ? toolResult.output
      : JSON.stringify(toolResult.output);
  }

  // If object with text field
  if (toolResult.text) {
    return toolResult.text;
  }

  // Fall back to JSON stringify
  return JSON.stringify(toolResult);
}

function checkForErrors(outputText, result) {
  result.verification_steps.step1_errors.checked = true;

  const errorKeywords = ['error', 'failed', 'exception', 'crash', 'fatal', 'failure'];
  const content = outputText.toLowerCase();
  const foundErrors = [];

  for (const keyword of errorKeywords) {
    const regex = new RegExp(`\\b${keyword}\\b`, 'gi');
    const matches = content.match(regex);
    if (matches && matches.length > 0) {
      foundErrors.push({ keyword, count: matches.length });
    }
  }

  result.verification_steps.step1_errors.found = foundErrors;

  if (foundErrors.length > 0) {
    foundErrors.forEach(({ keyword, count }) => {
      result.addError(`Found ${count} occurrence(s) of "${keyword}"`, 'critical');
    });
    log(`Step 1: Found errors - ${foundErrors.map(e => `${e.keyword}(${e.count})`).join(', ')}`);
  } else {
    log('Step 1: No errors found');
  }
}

function checkForWarnings(outputText, result) {
  result.verification_steps.step2_warnings.checked = true;

  const warningKeywords = ['warning', 'concern', 'issue', 'problem', 'caution'];
  const content = outputText.toLowerCase();
  const foundWarnings = [];

  for (const keyword of warningKeywords) {
    const regex = new RegExp(`\\b${keyword}\\b`, 'gi');
    const matches = content.match(regex);
    if (matches && matches.length > 0) {
      foundWarnings.push({ keyword, count: matches.length });
    }
  }

  result.verification_steps.step2_warnings.found = foundWarnings;

  if (foundWarnings.length > 0) {
    foundWarnings.forEach(({ keyword, count }) => {
      result.addWarning(`Found ${count} occurrence(s) of "${keyword}"`);
    });
    log(
      `Step 2: Found warnings - ${foundWarnings.map(w => `${w.keyword}(${w.count})`).join(', ')}`
    );
  } else {
    log('Step 2: No warnings found');
  }
}

function verifyDeliverablesExist(toolInput, result) {
  result.verification_steps.step3_deliverables.checked = true;

  // Extract deliverables from task template
  let deliverables = [];

  if (toolInput.deliverables) {
    deliverables = Array.isArray(toolInput.deliverables)
      ? toolInput.deliverables
      : [toolInput.deliverables];
  }

  if (deliverables.length === 0) {
    log('Step 3: No deliverables specified to verify');
    return;
  }

  let missingCount = 0;

  for (const deliverable of deliverables) {
    const path = typeof deliverable === 'string' ? deliverable : deliverable.path;
    if (!path) continue;

    const resolvedPath =
      path.startsWith('/') || path.match(/^[A-Z]:/) ? path : join(PROJECT_ROOT, path);
    const exists = existsSync(resolvedPath);

    let validated = false;
    if (exists) {
      try {
        const stats = statSync(resolvedPath);
        validated = stats.size > 0; // Basic validation: file is not empty
      } catch (error) {
        log(`Step 3: Error checking file ${path}: ${error.message}`);
      }
    }

    result.addDeliverableStatus(path, exists, validated);

    if (!exists) {
      result.verification_steps.step3_deliverables.missing.push(path);
      missingCount++;
    }
  }

  if (missingCount === 0) {
    log(`Step 3: All ${deliverables.length} deliverable(s) verified`);
  } else {
    log(`Step 3: ${missingCount} deliverable(s) missing`);
  }
}

function validateSuccessCriteria(toolInput, result) {
  result.verification_steps.step4_criteria.checked = true;

  // Extract success criteria from task template
  let criteria = [];

  if (toolInput.success_criteria) {
    criteria = Array.isArray(toolInput.success_criteria)
      ? toolInput.success_criteria
      : [toolInput.success_criteria];
  }

  if (criteria.length === 0) {
    log('Step 4: No success criteria specified to validate');
    return;
  }

  let unmetCount = 0;

  for (const criterion of criteria) {
    const name = typeof criterion === 'string' ? criterion : criterion.name || criterion.criterion;
    const met = typeof criterion === 'string' ? null : criterion.met;
    const evidence = typeof criterion === 'string' ? null : criterion.evidence;

    // If met is explicitly false, mark as unmet
    if (met === false) {
      result.addCriteriaStatus(name, false, evidence);
      result.verification_steps.step4_criteria.unmet.push(name);
      unmetCount++;
    } else {
      // Assume met if not explicitly false (criteria are from template, not results)
      result.addCriteriaStatus(name, true, evidence);
    }
  }

  if (unmetCount === 0) {
    log(`Step 4: All ${criteria.length} success criteria validated`);
  } else {
    log(`Step 4: ${unmetCount} success criteria not met`);
  }
}

function checkVerdict(outputText, result) {
  result.verification_steps.step5_verdict.checked = true;

  // Search for verdict in output text
  const verdictMatch = outputText.match(/verdict:\s*(PASS|CONCERNS|FAIL)/i);
  const agentVerdict = verdictMatch ? verdictMatch[1].toUpperCase() : null;

  result.verification_steps.step5_verdict.agent_verdict = agentVerdict;

  if (agentVerdict) {
    log(`Step 5: Agent verdict - ${agentVerdict}`);

    if (agentVerdict === 'FAIL') {
      result.verdict = 'FAIL';
      result.addError('Agent reported FAIL verdict', 'critical');
    } else if (agentVerdict === 'CONCERNS') {
      if (result.verdict === 'PASS') {
        result.verdict = 'CONCERNS';
      }
      result.addWarning('Agent reported CONCERNS verdict');
    }
  } else {
    log('Step 5: No explicit verdict found in agent output');
  }
}

function saveVerificationResult(result) {
  try {
    const outputDir = join(PROJECT_ROOT, '.claude/context/reports');
    if (!existsSync(outputDir)) {
      mkdirSync(outputDir, { recursive: true });
    }

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const outputPath = join(outputDir, `verification-result-${timestamp}.json`);

    writeFileSync(outputPath, JSON.stringify(result, null, 2));
    log(`Verification result saved to ${outputPath}`);
  } catch (error) {
    log(`Failed to save verification result: ${error.message}`);
  }
}

async function main() {
  try {
    // Read input from stdin
    const inputStr = await readStdin();

    if (!inputStr || inputStr.trim() === '') {
      log('No input received, exiting');
      process.stdout.write(
        JSON.stringify({
          decision: 'approve',
          hookSpecificOutput: { hookEventName: 'PostToolUse' },
        })
      );
      process.exit(0);
    }

    const input = JSON.parse(inputStr);
    const { tool_name: toolName, tool_input: toolInput, tool_result: toolResult } = input;

    // Only verify Task tool (agent delegations)
    if (toolName !== 'Task') {
      log(`Skipping verification for ${toolName} (only Task tool is verified)`);
      process.stdout.write(
        JSON.stringify({
          decision: 'approve',
          hookSpecificOutput: { hookEventName: 'PostToolUse' },
        })
      );
      process.exit(0);
    }

    log('Starting post-delegation verification...');

    const result = new VerificationResult();

    // Extract text from tool result
    const outputText = extractTextFromResult(toolResult);

    // Execute 5-step verification protocol
    checkForErrors(outputText, result);
    checkForWarnings(outputText, result);
    verifyDeliverablesExist(toolInput, result);
    validateSuccessCriteria(toolInput, result);
    checkVerdict(outputText, result);

    // Save verification result
    saveVerificationResult(result);

    // Log final verdict
    log(`Verification complete: ${result.verdict}`);
    if (result.errors.length > 0) {
      log(`  Errors: ${result.errors.length}`);
    }
    if (result.warnings.length > 0) {
      log(`  Warnings: ${result.warnings.length}`);
    }

    // Return verification result
    const hookResult = {
      verification_passed: result.verdict === 'PASS',
      verification_verdict: result.verdict,
      errors_count: result.errors.length,
      warnings_count: result.warnings.length,
      verification_details: result,
    };

    process.stdout.write(
      JSON.stringify({ decision: 'approve', hookSpecificOutput: { hookEventName: 'PostToolUse' } })
    );
    process.exit(0);
  } catch (error) {
    // FAIL-SAFE: Never block task completion
    log(`Error (non-blocking): ${error.message}`);

    const hookResult = {
      verification_passed: false,
      verification_verdict: 'ERROR',
      error: error.message,
    };

    process.stdout.write(
      JSON.stringify({ decision: 'approve', hookSpecificOutput: { hookEventName: 'PostToolUse' } })
    );
    process.exit(0);
  } finally {
    clearTimeout(timeout);
    delete process.env.CLAUDE_VERIFICATION_HOOK_EXECUTING;
  }
}

function matchesSlopPattern(filename) {
  return SLOP_PATTERNS.some(pattern => pattern.test(filename));
}

function isInRoot(filePath) {
  const normalized = filePath.replace(/\\/g, '/');
  const parts = normalized.split('/').filter(p => p && p !== '.');
  return parts.length === 1;
}

async function loadCleanupLog() {
  try {
    if (existsSync(CLEANUP_LOG)) {
      const content = await readFile(CLEANUP_LOG, 'utf-8');
      return JSON.parse(content);
    }
  } catch (error) {
    // Return empty log on error
  }
  return { cleaned_files: [], last_cleanup: null };
}

async function saveCleanupLog(log) {
  try {
    const logDir = dirname(CLEANUP_LOG);
    if (!existsSync(logDir)) {
      await mkdir(logDir, { recursive: true });
    }
    await writeFile(CLEANUP_LOG, JSON.stringify(log, null, 2), 'utf-8');
  } catch (error) {
    // Fail silently - logging is not critical
  }
}

async function cleanupFile(filePath) {
  try {
    const filename = basename(filePath);
    const projectRoot = resolve(__dirname, '../..');
    const fullPath = resolve(projectRoot, filePath);

    // Check if file exists
    if (!existsSync(fullPath)) {
      return null; // File doesn't exist, nothing to clean
    }

    let shouldClean = false;
    let reason = '';

    // Check SLOP patterns
    if (matchesSlopPattern(filename)) {
      shouldClean = true;
      reason = 'matches_slop_pattern';
    }

    // Check root directory violation
    if (isInRoot(filePath) && !ROOT_ALLOWLIST.includes(filename)) {
      shouldClean = true;
      reason = 'root_directory_violation';
    }

    if (shouldClean) {
      // Check if it's a directory or file
      const stats = lstatSync(fullPath);
      if (stats.isDirectory()) {
        await rm(fullPath, { recursive: true, force: true });
      } else {
        await unlink(fullPath);
      }
      return {
        file: filePath,
        reason: reason,
        cleaned_at: new Date().toISOString(),
      };
    }

    return null;
  } catch (error) {
    // Fail silently - don't block on cleanup errors
    return null;
  }
}

async function cleanupTmpclaudeFiles() {
  const projectRoot = resolve(__dirname, '../..');
  const cleaned = [];

  // Directories to skip during recursive search
  const skipDirs = new Set([
    'node_modules',
    '.git',
    '.claude/context/tmp', // Our own temp directory
    'dist',
    'build',
    '.next',
    '.nuxt',
    '.cache',
  ]);

  /**
   * Recursively search for tmpclaude files
   */
  async function searchDirectory(dirPath, relativePath = '') {
    try {
      const entries = await readdir(dirPath, { withFileTypes: true });

      for (const entry of entries) {
        const entryName = entry.name;
        const fullPath = join(dirPath, entryName);
        const relativeEntryPath = relativePath ? join(relativePath, entryName) : entryName;

        // Skip excluded directories
        if (entry.isDirectory() && skipDirs.has(entryName)) {
          continue;
        }

        // Check if this is a tmpclaude file/directory
        if (entryName.startsWith('tmpclaude-') && entryName.includes('-cwd')) {
          try {
            const stats = lstatSync(fullPath);
            if (stats.isDirectory()) {
              await rm(fullPath, { recursive: true, force: true });
            } else {
              await unlink(fullPath);
            }

            cleaned.push({
              file: relativeEntryPath,
              reason: 'tmpclaude_file',
              cleaned_at: new Date().toISOString(),
            });
          } catch (error) {
            // Fail silently for individual files - continue with others
          }
        } else if (entry.isDirectory()) {
          // Recursively search subdirectories
          await searchDirectory(fullPath, relativeEntryPath);
        }
      }
    } catch (error) {
      // Fail silently - continue with other directories
    }
  }

  try {
    await searchDirectory(projectRoot);
  } catch (error) {
    // Fail silently - cleanup is non-critical
  }

  return cleaned;
}

async function main() {
  try {
    // Read JSON from stdin
    let input = '';
    for await (const chunk of process.stdin) {
      input += chunk.toString();
    }

    const data = JSON.parse(input);
    const toolName = data.tool_name || '';
    const toolInput = data.tool_input || {};

    const cleanedItems = [];

    // Cleanup after Write operations
    if (toolName === 'Write') {
      const filePath = toolInput.file_path || toolInput.path || '';

      if (filePath) {
        const cleaned = await cleanupFile(filePath);
        if (cleaned) {
          cleanedItems.push(cleaned);
        }
      }
    }

    // Cleanup tmpclaude-* files after Bash commands
    if (toolName === 'Bash') {
      const tmpclaudeCleaned = await cleanupTmpclaudeFiles();
      if (tmpclaudeCleaned.length > 0) {
        cleanedItems.push(...tmpclaudeCleaned);
      }
      // Always log cleanup attempt for debugging
      console.error(
        JSON.stringify({
          action: 'cleanup_attempt',
          tool: toolName,
          cleaned_count: tmpclaudeCleaned.length,
        })
      );
    }

    // Log all cleaned items
    if (cleanedItems.length > 0) {
      const log = await loadCleanupLog();
      log.cleaned_files.push(...cleanedItems);
      log.last_cleanup = new Date().toISOString();
      await saveCleanupLog(log);

      // Output cleanup summary (non-blocking)
      for (const cleaned of cleanedItems) {
        console.error(
          JSON.stringify({
            action: 'cleaned',
            file: cleaned.file,
            reason: cleaned.reason,
            message: `Cleaned up ${cleaned.reason === 'tmpclaude_file' ? 'tmpclaude file' : 'SLOP file'}: ${cleaned.file} (${cleaned.reason})`,
          })
        );
      }
    }

    // Always allow (this is post-execution, non-blocking)
    process.exit(0);
  } catch (error) {
    // Log error to stderr for debugging (non-blocking)
    console.error(
      JSON.stringify({
        action: 'error',
        error: error.message,
        stack: error.stack,
      })
    );
    // Fail silently - cleanup is non-critical
    process.exit(0);
  }
}

function truthy(value) {
  const raw = String(value || '')
    .trim()
    .toLowerCase();
  return raw === '1' || raw === 'true' || raw === 'yes' || raw === 'on';
}

function readJson(path) {
  try {
    if (!existsSync(path)) return null;
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    return null;
  }
}

function isEnabled() {
  if (truthy(process.env.CLAUDE_READ_ONLY)) return true;
  const st = readJson(STATE_PATH);
  return Boolean(st?.enabled);
}

function toolNameOf(input) {
  const v = input?.tool_name ?? input?.tool ?? input?.toolName ?? input?.name ?? '';
  return typeof v === 'string' ? v.trim() : String(v ?? '').trim();
}

function toolInputOf(input) {
  return input?.tool_input ?? input?.toolInput ?? input?.input ?? input?.params ?? {};
}

function bashIsMutating(command) {
  const c = String(command || '');
  const s = c.toLowerCase();

  // Obvious file writes via shell redirection / tee
  if (/[^\S\r\n]>(>|&)?[^\S\r\n]?/.test(c) || /\btee\b/i.test(c)) return true;

  // Git operations: allow common read-only commands, but block staging/history mutations.
  if (/\bgit\b/.test(s)) {
    const mutatingGit =
      /\b(add|commit|push|tag|checkout|merge|rebase|reset|clean|apply|stash|cherry-pick)\b/.test(s);
    if (mutatingGit) return true;
    const readOnlyGit = /\b(status|log|diff|show|grep|blame|branch|remote|config|help)\b/.test(s);
    if (readOnlyGit) return false;
  }

  // Package installs/updates
  if (
    /\b(pnpm|npm|yarn)\b/.test(s) &&
    /\b(install|add|remove|update|upgrade|link|unlink)\b/.test(s)
  )
    return true;

  // File mutations (keep conservative)
  if (/\b(rm|del|erase|mv|move|cp|copy|mkdir|rmdir|touch|chmod|chown)\b/.test(s)) return true;

  // Formatting/lint fixers can rewrite files
  if (
    /\b(pnpm|npm)\b/.test(s) &&
    /\b(format|lint)\b/.test(s) &&
    !/\b(format:check|lint:check)\b/.test(s)
  )
    return true;

  return false;
}

async function main() {
  let raw = '';
  for await (const chunk of process.stdin) raw += chunk.toString();
  const input = raw ? JSON.parse(raw) : {};

  if (!isEnabled()) {
    process.stdout.write(JSON.stringify({ decision: 'approve' }));
    return;
  }

  const toolName = toolNameOf(input);
  const lower = toolName.toLowerCase();
  const toolInput = toolInputOf(input);

  if (lower === 'write' || lower === 'edit') {
    process.stdout.write(
      JSON.stringify({
        decision: 'block',
        reason:
          'READ-ONLY MODE: Write/Edit is disabled. Disable read-only via `node .claude/tools/read-only.mjs disable` (or unset CLAUDE_READ_ONLY) to proceed.',
      })
    );
    return;
  }

  if (lower === 'bash') {
    const cmd = toolInput?.command ?? toolInput?.cmd ?? '';
    if (bashIsMutating(cmd)) {
      process.stdout.write(
        JSON.stringify({
          decision: 'block',
          reason:
            'READ-ONLY MODE: This Bash command looks like it may modify the repo. Disable read-only via `node .claude/tools/read-only.mjs disable` (or unset CLAUDE_READ_ONLY) to proceed.',
        })
      );
      return;
    }
  }

  process.stdout.write(JSON.stringify({ decision: 'approve' }));
}

function safeRespond(obj) {
  if (responded) return;
  responded = true;
  try {
    process.stdout.write(JSON.stringify(obj));
  } catch {
    // Fail-open: do nothing.
  }
}

function isAllowedReadFile(filePath) {
  return ALLOWED_READ_PATTERNS.some(pattern => pattern.test(filePath));
}

function summarizeToolInput(tool, toolInput) {
  const summary = {};

  if (tool === 'Bash') {
    const command = String(toolInput?.command || '');
    summary.command = command.slice(0, MAX_TOOL_INPUT_CHARS);
    if (command.length > MAX_TOOL_INPUT_CHARS) summary.command_truncated = true;
    return summary;
  }

  if (tool === 'Read') {
    const filePath = String(toolInput?.file_path || '');
    summary.file_path = filePath.slice(0, MAX_TOOL_INPUT_CHARS);
    if (filePath.length > MAX_TOOL_INPUT_CHARS) summary.file_path_truncated = true;
    return summary;
  }

  if (tool === 'Write' || tool === 'Edit') {
    const filePath = String(toolInput?.file_path || toolInput?.path || '');
    summary.file_path = filePath.slice(0, MAX_TOOL_INPUT_CHARS);
    if (filePath.length > MAX_TOOL_INPUT_CHARS) summary.file_path_truncated = true;
    if (typeof toolInput?.content === 'string') summary.content_length = toolInput.content.length;
    if (typeof toolInput?.old_string === 'string')
      summary.old_string_length = toolInput.old_string.length;
    if (typeof toolInput?.new_string === 'string')
      summary.new_string_length = toolInput.new_string.length;
    return summary;
  }

  for (const [key, value] of Object.entries(toolInput || {})) {
    if (value == null) continue;
    if (typeof value === 'string') {
      summary[key] = value.slice(0, MAX_TOOL_INPUT_CHARS);
      if (value.length > MAX_TOOL_INPUT_CHARS) summary[`${key}_truncated`] = true;
    } else if (typeof value === 'number' || typeof value === 'boolean') {
      summary[key] = value;
    }
  }

  return summary;
}

async function loadSessionStateFromDisk() {
  try {
    if (!existsSync(SESSION_STATE_PATH)) return null;
    const content = await readFile(SESSION_STATE_PATH, 'utf-8');
    const parsed = JSON.parse(content);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

async function tryLoadSessionState() {
  const now = Date.now();
  if (sessionStateCache && now - sessionStateCacheAt < STATE_CACHE_TTL_MS) {
    return sessionStateCache;
  }

  const state = await loadSessionStateFromDisk();
  sessionStateCache = state;
  sessionStateCacheAt = now;
  return state;
}

async function readSessionDeltas() {
  try {
    if (!existsSync(SESSION_DELTA_PATH)) return [];
    const content = await readFile(SESSION_DELTA_PATH, 'utf-8');
    if (!content) return [];

    const deltas = [];
    for (const line of content.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed) continue;
      try {
        const parsed = JSON.parse(trimmed);
        if (parsed && typeof parsed === 'object') deltas.push(parsed);
      } catch {
        // ignore malformed line
      }
    }
    return deltas;
  } catch {
    return [];
  }
}

function applySessionDeltas(state, deltas) {
  if (!state || !deltas?.length) return state;

  for (const delta of deltas) {
    if (delta?.agent_role === 'orchestrator') state.agent_role = 'orchestrator';

    if (Number.isFinite(delta?.read_inc) && delta.read_inc !== 0) {
      state.read_count =
        (Number.isFinite(state.read_count) ? state.read_count : 0) + delta.read_inc;
    }

    if (typeof delta?.file_read === 'string' && delta.file_read) {
      state.files_read = Array.isArray(state.files_read) ? state.files_read : [];
      state.files_read.push(delta.file_read.slice(0, MAX_TOOL_INPUT_CHARS));
      if (state.files_read.length > MAX_FILES_READ)
        state.files_read = state.files_read.slice(-MAX_FILES_READ);
    }

    if (delta?.violation && typeof delta.violation === 'object') {
      state.violations = Array.isArray(state.violations) ? state.violations : [];
      state.violations.push(delta.violation);
      if (state.violations.length > MAX_VIOLATIONS)
        state.violations = state.violations.slice(-MAX_VIOLATIONS);
    }
  }

  return state;
}

async function tryLoadEffectiveSessionState() {
  const baseState = await tryLoadSessionState();
  if (!baseState) return null;

  const deltas = await readSessionDeltas();
  return applySessionDeltas(structuredClone(baseState), deltas);
}

function detectRoleFromEnv() {
  if (process.env.CLAUDE_AGENT_ROLE) {
    return process.env.CLAUDE_AGENT_ROLE === 'orchestrator' ? 'orchestrator' : 'subagent';
  }
  if (process.env.CLAUDE_AGENT_NAME) {
    const agentName = process.env.CLAUDE_AGENT_NAME.toLowerCase();
    return ['orchestrator', 'master-orchestrator'].includes(agentName)
      ? 'orchestrator'
      : 'subagent';
  }
  return null;
}

function detectRoleFromHookInput(hookInput) {
  try {
    const ctx = hookInput?.context ?? hookInput?.ctx ?? null;
    const raw =
      ctx?.agent_name ??
      ctx?.agentName ??
      ctx?.agent ??
      hookInput?.agent_name ??
      hookInput?.agentName ??
      hookInput?.agent ??
      null;
    if (typeof raw !== 'string') return null;
    const name = raw.trim().toLowerCase();
    if (!name) return null;
    return ['orchestrator', 'master-orchestrator'].includes(name) ? 'orchestrator' : null;
  } catch {
    return null;
  }
}

async function writeSessionState(state) {
  try {
    const dir = dirname(SESSION_STATE_PATH);
    await mkdir(dir, { recursive: true });
    const payload = JSON.stringify(state, null, 2);

    const maxRetries = 3;
    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        await writeFile(SESSION_STATE_PATH, payload, 'utf-8');
        return;
      } catch (error) {
        const isLast = attempt === maxRetries - 1;
        const retryable =
          error &&
          (error.code === 'EBUSY' ||
            error.code === 'EPERM' ||
            error.code === 'EACCES' ||
            error.code === 'EMFILE');
        if (!retryable || isLast) return;
        await new Promise(r => setTimeout(r, 50 * Math.pow(2, attempt)));
      }
    }
  } catch {
    // ignore (fail-open)
  }
}

async function appendSessionDelta(delta) {
  try {
    const dir = dirname(SESSION_DELTA_PATH);
    await mkdir(dir, { recursive: true });
    await appendFile(SESSION_DELTA_PATH, JSON.stringify(delta) + '\n', 'utf-8');

    if (sessionStateCache) {
      applySessionDeltas(sessionStateCache, [delta]);
      sessionStateCacheAt = Date.now();
      sessionStateCacheHasUncompactedUpdates = true;
    }
  } catch {
    // ignore (fail-open)
  }
}

async function acquireCompactLock() {
  const MAX_RETRIES = 3;
  const BASE_DELAY_MS = 50;

  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    try {
      await writeFile(SESSION_LOCK_PATH, String(process.pid), { encoding: 'utf-8', flag: 'wx' });
      return true;
    } catch (error) {
      // Only retry if file exists (EEXIST) - otherwise it's a permission or path issue
      if (error?.code !== 'EEXIST') {
        return false;
      }

      // Check if lock is stale and clean up atomically
      try {
        if (existsSync(SESSION_LOCK_PATH)) {
          const lockStat = await stat(SESSION_LOCK_PATH);
          const ageMs = Date.now() - lockStat.mtimeMs;
          if (ageMs > STATE_COMPACT_DEBOUNCE_MS * 3) {
            // Use rename to atomically move stale lock before deletion
            const stalePath = `${SESSION_LOCK_PATH}.stale-${Date.now()}`;
            try {
              await rename(SESSION_LOCK_PATH, stalePath);
              await unlink(stalePath).catch(() => {});
            } catch {
              // Another process may have already cleaned up - continue to retry
            }
          }
        }
      } catch {
        // ignore stat/cleanup errors
      }

      // Exponential backoff before retry
      if (attempt < MAX_RETRIES - 1) {
        await new Promise(r => setTimeout(r, BASE_DELAY_MS * Math.pow(2, attempt)));
      }
    }
  }
  return false;
}

async function releaseCompactLock() {
  try {
    if (existsSync(SESSION_LOCK_PATH)) await unlink(SESSION_LOCK_PATH);
  } catch {
    // ignore
  }
}

function addViolation(state, violation) {
  state.violations = Array.isArray(state.violations) ? state.violations : [];
  state.violations.push(violation);
  if (state.violations.length > MAX_VIOLATIONS) {
    state.violations = state.violations.slice(-MAX_VIOLATIONS);
  }
}

async function logViolation(violation) {
  try {
    const logDir = dirname(AUDIT_LOG_PATH);
    await mkdir(logDir, { recursive: true });
    await appendFile(AUDIT_LOG_PATH, JSON.stringify(violation) + '\n', 'utf-8');
  } catch {
    // ignore
  }
}

async function main() {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  const input = Buffer.concat(chunks).toString('utf-8');

  let hookInput;
  try {
    hookInput = JSON.parse(input);
  } catch {
    safeRespond({ decision: 'approve' });
    return;
  }

  const tool = hookInput.tool_name || hookInput.tool;
  const toolInput = hookInput.tool_input || {};

  // Exclusions to prevent recursion / self-interference
  if (tool === 'Task' || tool === 'TodoWrite') {
    safeRespond({ decision: 'approve' });
    return;
  }

  // Fast path: if tool isn't enforced, allow without touching state/logs
  if (!ENFORCEMENT_RULES[tool]) {
    safeRespond({ decision: 'approve' });
    return;
  }

  const envRole = detectRoleFromEnv();
  if (envRole === 'subagent') {
    safeRespond({ decision: 'approve' });
    return;
  }

  const hookRole = detectRoleFromHookInput(hookInput);
  const existingState = await tryLoadEffectiveSessionState();
  const role =
    envRole ??
    hookRole ??
    (existingState?.agent_role === 'orchestrator' ? 'orchestrator' : 'subagent');

  if (role !== 'orchestrator') {
    safeRespond({ decision: 'approve' });
    return;
  }

  const state = existingState || {
    session_id: `sess_${Date.now()}`,
    agent_role: 'orchestrator',
    read_count: 0,
    violations: [],
    files_read: [],
    created_at: new Date().toISOString(),
  };

  // Ensure session state exists on disk for subsequent hook invocations.
  if (!existsSync(SESSION_STATE_PATH)) {
    const nowMs = Date.now();
    state.last_compact_ms = nowMs;
    await writeSessionState(state);
    sessionStateCache = structuredClone(state);
    sessionStateCacheAt = nowMs;
    sessionStateCacheHasUncompactedUpdates = false;
  }

  state.agent_role = 'orchestrator';
  state.read_count = Number.isFinite(state.read_count) ? state.read_count : 0;
  state.violations = Array.isArray(state.violations) ? state.violations : [];
  state.files_read = Array.isArray(state.files_read) ? state.files_read : [];
  if (state.violations.length > MAX_VIOLATIONS)
    state.violations = state.violations.slice(-MAX_VIOLATIONS);
  if (state.files_read.length > MAX_FILES_READ)
    state.files_read = state.files_read.slice(-MAX_FILES_READ);

  const rule = ENFORCEMENT_RULES[tool];

  if (rule.action === 'BLOCK') {
    const violation = {
      session_id: state.session_id,
      tool,
      tool_input: summarizeToolInput(tool, toolInput),
      type: `${tool}_BLOCKED`,
      reason: rule.reason,
      delegate: rule.delegate,
      blocked: true,
      timestamp: new Date().toISOString(),
    };
    addViolation(state, violation);
    await appendSessionDelta({ agent_role: 'orchestrator', violation });
    await compactSessionStateIfNeeded({ force: true });
    await logViolation(violation);

    safeRespond({
      decision: 'block',
      reason: `
╔═══════════════════════════════════════════════════════════════════╗
║  ORCHESTRATOR VIOLATION - TOOL BLOCKED                            ║
╠═══════════════════════════════════════════════════════════════════╣
║  Tool: ${String(tool).padEnd(58)}║
║  Reason: ${String(rule.reason).substring(0, 55).padEnd(55)}║
║  Action: Spawn ${rule.delegate} subagent via Task tool${' '.repeat(Math.max(0, 35 - String(rule.delegate).length))}║
╚═══════════════════════════════════════════════════════════════════╝
      `.trim(),
    });
    return;
  }

  if (rule.action === 'CONDITIONAL') {
    const command = String(toolInput.command || '');
    const isBlocked = rule.blocked_patterns.some(pattern => pattern.test(command));
    if (!isBlocked) {
      safeRespond({ decision: 'approve' });
      return;
    }

    const violation = {
      session_id: state.session_id,
      tool,
      tool_input: summarizeToolInput(tool, toolInput),
      type: 'BASH_DANGEROUS_COMMAND',
      reason: rule.reason,
      delegate: rule.delegate,
      blocked: true,
      timestamp: new Date().toISOString(),
    };
    addViolation(state, violation);
    await appendSessionDelta({ agent_role: 'orchestrator', violation });
    await compactSessionStateIfNeeded({ force: true });
    await logViolation(violation);

    safeRespond({
      decision: 'block',
      reason: `
╔═══════════════════════════════════════════════════════════════════╗
║  ORCHESTRATOR VIOLATION - DANGEROUS COMMAND BLOCKED               ║
╠═══════════════════════════════════════════════════════════════════╣
║  Command: ${command.substring(0, 55).padEnd(55)}║
║  Reason: ${String(rule.reason).substring(0, 55).padEnd(55)}║
║  Action: Spawn ${rule.delegate} subagent via Task tool${' '.repeat(Math.max(0, 35 - String(rule.delegate).length))}║
╚═══════════════════════════════════════════════════════════════════╝
      `.trim(),
    });
    return;
  }

  if (rule.action === 'COUNT_LIMITED') {
    state.read_count += 1;

    const filePath = String(toolInput.file_path || '');
    if (filePath) {
      state.files_read.push(filePath.slice(0, MAX_TOOL_INPUT_CHARS));
      if (state.files_read.length > MAX_FILES_READ)
        state.files_read = state.files_read.slice(-MAX_FILES_READ);
    }

    if (state.read_count > rule.max_count) {
      if (isAllowedReadFile(filePath)) {
        await appendSessionDelta({
          agent_role: 'orchestrator',
          read_inc: 1,
          file_read: filePath || undefined,
        });
        await compactSessionStateIfNeeded();
        safeRespond({ decision: 'approve' });
        return;
      }

      const violation = {
        session_id: state.session_id,
        tool,
        tool_input: summarizeToolInput(tool, toolInput),
        type: 'READ_LIMIT_EXCEEDED',
        read_count: state.read_count,
        reason: `${rule.reason} (attempt #${state.read_count})`,
        delegate: rule.delegate,
        blocked: true,
        timestamp: new Date().toISOString(),
      };
      addViolation(state, violation);
      await appendSessionDelta({
        agent_role: 'orchestrator',
        read_inc: 1,
        file_read: filePath || undefined,
        violation,
      });
      await compactSessionStateIfNeeded({ force: true });
      await logViolation(violation);

      safeRespond({
        decision: 'block',
        reason: `
╔═══════════════════════════════════════════════════════════════════╗
║  ORCHESTRATOR VIOLATION - 2-FILE RULE EXCEEDED                    ║
╠═══════════════════════════════════════════════════════════════════╣
║  Tool: Read (attempt #${String(state.read_count).padEnd(45)}║
║  Reason: ${String(rule.reason).substring(0, 55).padEnd(55)}║
║  Action: Spawn ${rule.delegate} subagent via Task tool${' '.repeat(Math.max(0, 35 - String(rule.delegate).length))}║
╚═══════════════════════════════════════════════════════════════════╝
        `.trim(),
      });
      return;
    }

    await appendSessionDelta({
      agent_role: 'orchestrator',
      read_inc: 1,
      file_read: filePath || undefined,
    });
    await compactSessionStateIfNeeded();
    safeRespond({ decision: 'approve' });
    return;
  }

  safeRespond({ decision: 'approve' });
}

function safeRespond(obj) {
  if (responded) return;
  responded = true;
  try {
    process.stdout.write(JSON.stringify(obj));
  } catch {
    // ignore
  }
}

function approve(extra = undefined) {
  safeRespond(extra ? { decision: 'approve', ...extra } : { decision: 'approve' });
}

function block(reason) {
  safeRespond({ decision: 'block', reason });
}

function normalizeToolName(value) {
  if (typeof value === 'string') return value.trim();
  if (value == null) return '';
  return String(value).trim();
}

async function readStdinJson() {
  const input = await new Promise(resolve => {
    const chunks = [];
    process.stdin.on('data', chunk => chunks.push(chunk));
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf-8')));
    process.stdin.on('error', () => resolve(''));
    setTimeout(() => resolve(chunks.length ? Buffer.concat(chunks).toString('utf-8') : ''), 250);
  });

  if (!input || !input.trim()) return null;
  try {
    return JSON.parse(input);
  } catch {
    return null;
  }
}

function getReadPath(toolInput) {
  const raw =
    toolInput?.path ??
    toolInput?.file_path ??
    toolInput?.filePath ??
    toolInput?.filename ??
    toolInput?.file ??
    null;
  return typeof raw === 'string' ? raw : null;
}

function hasPaging(toolInput) {
  if (!toolInput || typeof toolInput !== 'object') return false;
  const keys = ['offset', 'limit', 'start', 'end', 'start_line', 'end_line', 'range'];
  return keys.some(k => toolInput[k] !== undefined && toolInput[k] !== null);
}

function isAgentEcosystemPath(path) {
  if (!path || typeof path !== 'string') return false;
  const normalized = path.replace(/\\/g, '/');
  // Allow `.claude/` reads (artifacts, runtime state, workflows, agents, schemas, config).
  // These files can legitimately be large and are foundational to the agent framework.
  return (
    normalized.startsWith('.claude/') ||
    normalized.includes('/.claude/') ||
    normalized.includes('/.claude\\') ||
    normalized.includes('\\.claude/')
  );
}

function getMaxBytes() {
  const raw = String(process.env.CLAUDE_READ_MAX_BYTES || '').trim();
  const parsed = raw ? Number(raw) : NaN;
  if (Number.isFinite(parsed) && parsed > 0) return parsed;
  // Default chosen to sit below typical ~25k token Read caps.
  return 110 * 1024;
}

async function main() {
  const hookInput = await readStdinJson();
  const toolName = normalizeToolName(
    hookInput?.tool_name ?? hookInput?.tool ?? hookInput?.toolName ?? hookInput?.name
  );
  if (toolName.toLowerCase() !== 'read') {
    approve();
    return;
  }

  const toolInput =
    hookInput?.tool_input ?? hookInput?.toolInput ?? hookInput?.input ?? hookInput?.params ?? {};

  const path = getReadPath(toolInput);
  if (!path || !path.trim()) {
    approve();
    return;
  }

  if (isAgentEcosystemPath(path)) {
    approve();
    return;
  }

  if (hasPaging(toolInput)) {
    approve();
    return;
  }

  let s;
  try {
    s = statSync(path);
  } catch {
    approve();
    return;
  }

  if (!s?.isFile?.()) {
    approve();
    return;
  }

  const maxBytes = getMaxBytes();
  if (typeof s.size === 'number' && s.size > maxBytes) {
    const reason = [
      'Read size guard: file is too large to Read without paging.',
      `Requested path: ${path}`,
      `Size: ${s.size} bytes (limit: ${maxBytes} bytes)`,
      'Fix: use Read with `offset` + `limit`, or use `Grep`/`Search` to narrow scope first.',
    ].join('\n');
    await logDenialIfBlocking({
      hookName: 'read-size-guard',
      hookInput,
      decision: 'block',
      reason,
    });
    block(reason);
    return;
  }

  approve();
}

function normalizeToolName(value) {
  if (typeof value === 'string') return value.trim();
  if (value == null) return '';
  return String(value).trim();
}

function toolNameOf(input) {
  const v = input?.tool_name ?? input?.tool ?? input?.toolName ?? input?.name ?? '';
  return typeof v === 'string' ? v.trim() : String(v ?? '').trim();
}

function toolInputOf(input) {
  return input?.tool_input ?? input?.toolInput ?? input?.input ?? input?.params ?? {};
}

function safeFileId(input) {
