async function loadState(path) {
  try {
    if (!existsSync(path)) return { active: 0, agents: [], agentStack: [] };
    const raw = await readFile(path, 'utf8');
    const obj = JSON.parse(raw);
    return {
      active: clampInt(obj?.active, 0, 200),
      pending: clampInt(obj?.pending, 0, 200),
      agents: Array.isArray(obj?.agents) ? obj.agents.map(String) : [],
      agentStack: Array.isArray(obj?.agentStack) ? obj.agentStack.map(String) : [],
      last_stopped_agent:
        typeof obj?.last_stopped_agent === 'string' ? obj.last_stopped_agent : null,
      updated_at: typeof obj?.updated_at === 'string' ? obj.updated_at : null,
    };
  } catch {
    return { active: 0, agents: [], agentStack: [] };
  }
}

async function saveState(path, state) {
  await mkdir(dirname(path), { recursive: true });
  const next = {
    active: clampInt(state.active, 0, 200),
    pending: clampInt(state.pending, 0, 200),
    agents: Array.isArray(state.agents) ? state.agents : [],
    agentStack: Array.isArray(state.agentStack) ? state.agentStack : [],
    last_stopped_agent:
      typeof state.last_stopped_agent === 'string' ? state.last_stopped_agent : null,
    updated_at: new Date().toISOString(),
  };
  await writeFile(path, JSON.stringify(next, null, 2), 'utf8');
}

async function main() {
  const mode = String(process.argv[2] || '')
    .trim()
    .toLowerCase();
  const hookInput = await readStdinJson();
  const sessionKey = String(
    (await getSessionKeyForHook({ hookInput, tmpDir: TMP_DIR })) || ''
  ).trim();
  if (!sessionKey) return;

  const statePath = join(ACTIVE_DIR, `${sessionKey}.json`);
  const state = await loadState(statePath);

  const hintedAgent =
    sanitizeAgentName(
      hookInput?.delegated_agent ??
        hookInput?.delegatedAgent ??
        hookInput?.subagent_type ??
        hookInput?.subagentType ??
        hookInput?.subagent ??
        hookInput?.agent ??
        null
    ) ?? 'unknown';

  if (mode === 'start' || mode === 'subagent-start' || mode === 'subagentstart') {
    // Move one pending Task spawn into active (best-effort) to avoid burst spawns.
    if (!Number.isFinite(state.pending)) state.pending = 0;
    if (state.pending > 0) state.pending = clampInt(state.pending - 1, 0, 200);

    state.active = clampInt(state.active + 1, 0, 200);
    state.agents = [...(state.agents || []), hintedAgent].slice(-200);
    // Push to agentStack for LIFO tracking (used to identify stopped agent)
    state.agentStack = [...(state.agentStack || []), hintedAgent].slice(-200);
    state.last_stopped_agent = null; // Clear on start
    await saveState(statePath, state);
  } else if (mode === 'stop' || mode === 'subagent-stop' || mode === 'subagentstop') {
    state.active = clampInt(state.active - 1, 0, 200);
    if (Array.isArray(state.agents) && state.agents.length)
      state.agents = state.agents.slice(0, -1);
    // Pop from agentStack to identify which agent stopped (LIFO order)
    // Claude Code doesn't pass agent name to SubagentStop, so we use the stack
    const stoppedAgent =
      Array.isArray(state.agentStack) && state.agentStack.length
        ? state.agentStack.pop()
        : 'unknown';
    state.last_stopped_agent = stoppedAgent;
    await saveState(statePath, state);
  }
}

