export function parsePackageJson(packageJson) {
  const dependencies = {
    production: {},
    development: {},
    peer: {},
    optional: {},
  };

  if (packageJson.dependencies) {
    dependencies.production = packageJson.dependencies;
  }

  if (packageJson.devDependencies) {
    dependencies.development = packageJson.devDependencies;
  }

  if (packageJson.peerDependencies) {
    dependencies.peer = packageJson.peerDependencies;
  }

  if (packageJson.optionalDependencies) {
    dependencies.optional = packageJson.optionalDependencies;
  }

  return {
    type: 'nodejs',
    manager: detectPackageManager(packageJson),
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

function detectPackageManager(packageJson) {
  if (packageJson.packageManager) {
    if (packageJson.packageManager.startsWith('pnpm')) return 'pnpm';
    if (packageJson.packageManager.startsWith('yarn')) return 'yarn';
    if (packageJson.packageManager.startsWith('npm')) return 'npm';
  }

  // Default to npm if not specified
  return 'npm';
}

export function parseRequirementsTxt(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Parse package name and version
    const match = trimmed.match(/^([a-zA-Z0-9_-]+)([>=<~!]*)([0-9.]*)/);
    if (!match) continue;

    const [, packageName, operator, version] = match;

    // Development dependencies typically have "dev" in the name or are test-related
    const isDev =
      packageName.toLowerCase().includes('test') ||
      packageName.toLowerCase().includes('dev') ||
      packageName.toLowerCase().includes('pytest') ||
      packageName.toLowerCase().includes('coverage');

    const versionSpec = operator && version ? `${operator}${version}` : '*';

    if (isDev) {
      dependencies.development[packageName] = versionSpec;
    } else {
      dependencies.production[packageName] = versionSpec;
    }
  }

  return {
    type: 'python',
    manager: 'pip',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

export function parsePyprojectToml(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  // Parse [project.dependencies]
  const prodMatch = content.match(/\[project\.dependencies\]([\s\S]*?)(?:\[|$)/);
  if (prodMatch) {
    const deps = parseTOMLDependencies(prodMatch[1]);
    dependencies.production = deps;
  }

  // Parse [project.optional-dependencies.dev] or similar
  const devMatch = content.match(
    /\[project\.optional-dependencies\.(?:dev|test)\]([\s\S]*?)(?:\[|$)/
  );
  if (devMatch) {
    const deps = parseTOMLDependencies(devMatch[1]);
    dependencies.development = deps;
  }

  return {
    type: 'python',
    manager: 'poetry',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

function parseTOMLDependencies(content) {
  const deps = {};
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Parse line like: "fastapi>=0.100.0" or "fastapi = ">=0.100.0""
    const match = trimmed.match(/"([a-zA-Z0-9_-]+)\s*([>=<~!]*)\s*([0-9.]*)/);
    if (match) {
      const [, packageName, operator, version] = match;
      const versionSpec = operator && version ? `${operator}${version}` : '*';
      deps[packageName] = versionSpec;
    }
  }

  return deps;
}

export function parseGoMod(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  const lines = content.split('\n');
  let inRequire = false;

  for (const line of lines) {
    const trimmed = line.trim();

    if (trimmed.startsWith('require (')) {
      inRequire = true;
      continue;
    }

    if (inRequire && trimmed === ')') {
      inRequire = false;
      continue;
    }

    if (inRequire || trimmed.startsWith('require ')) {
      // Parse line like: "github.com/pkg/errors v0.9.1"
      const match = trimmed.match(/([a-zA-Z0-9._/-]+)\s+v([0-9.]+)/);
      if (match) {
        const [, packageName, version] = match;
        dependencies.production[packageName] = `v${version}`;
      }
    }
  }

  return {
    type: 'go',
    manager: 'go',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: 0,
  };
}

export function parseCargoToml(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  // Parse [dependencies]
  const prodMatch = content.match(/\[dependencies\]([\s\S]*?)(?:\[|$)/);
  if (prodMatch) {
    const deps = parseTOMLDependencies(prodMatch[1]);
    dependencies.production = deps;
  }

  // Parse [dev-dependencies]
  const devMatch = content.match(/\[dev-dependencies\]([\s\S]*?)(?:\[|$)/);
  if (devMatch) {
    const deps = parseTOMLDependencies(devMatch[1]);
    dependencies.development = deps;
  }

  return {
    type: 'rust',
    manager: 'cargo',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

export function parsePomXml(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  // Simple regex parsing for <dependency> blocks
  const depMatches = content.matchAll(/<dependency>([\s\S]*?)<\/dependency>/g);

  for (const match of depMatches) {
    const depBlock = match[1];

    const groupIdMatch = depBlock.match(/<groupId>(.*?)<\/groupId>/);
    const artifactIdMatch = depBlock.match(/<artifactId>(.*?)<\/artifactId>/);
    const versionMatch = depBlock.match(/<version>(.*?)<\/version>/);
    const scopeMatch = depBlock.match(/<scope>(.*?)<\/scope>/);

    if (groupIdMatch && artifactIdMatch) {
      const packageName = `${groupIdMatch[1]}:${artifactIdMatch[1]}`;
      const version = versionMatch ? versionMatch[1] : '*';
      const scope = scopeMatch ? scopeMatch[1] : 'compile';

      if (scope === 'test') {
        dependencies.development[packageName] = version;
      } else {
        dependencies.production[packageName] = version;
      }
    }
  }

  return {
    type: 'java',
    manager: 'maven',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

export function parseBuildGradle(content) {
  const dependencies = {
    production: {},
    development: {},
  };

  // Parse implementation, api, compileOnly, testImplementation, etc.
  const depLines = content.match(
    /\s+(implementation|api|compileOnly|testImplementation|androidTestImplementation)\s+['"]([^'"]+)['"]/g
  );

  if (depLines) {
    for (const line of depLines) {
      const match = line.match(
        /(implementation|api|compileOnly|testImplementation|androidTestImplementation)\s+['"]([^'"]+)['"]/
      );
      if (match) {
        const [, scope, dependency] = match;
        const isTest = scope.toLowerCase().includes('test');

        if (isTest) {
          dependencies.development[dependency] = '*';
        } else {
          dependencies.production[dependency] = '*';
        }
      }
    }
  }

  return {
    type: 'java',
    manager: 'gradle',
    dependencies,
    totalProduction: Object.keys(dependencies.production).length,
    totalDevelopment: Object.keys(dependencies.development).length,
  };
}

export function analyzeDependencies(manifests) {
  const results = [];

  // Node.js
  if (manifests['package.json']) {
    const parsed = parsePackageJson(manifests['package.json']);
    results.push(parsed);
  }

  // Python
  if (manifests['requirements.txt']) {
    const parsed = parseRequirementsTxt(manifests['requirements.txt']);
    results.push(parsed);
  }

  if (manifests['pyproject.toml']) {
    const parsed = parsePyprojectToml(manifests['pyproject.toml']);
    results.push(parsed);
  }

  // Go
  if (manifests['go.mod']) {
    const parsed = parseGoMod(manifests['go.mod']);
    results.push(parsed);
  }

  // Rust
  if (manifests['Cargo.toml']) {
    const parsed = parseCargoToml(manifests['Cargo.toml']);
    results.push(parsed);
  }

  // Java
  if (manifests['pom.xml']) {
    const parsed = parsePomXml(manifests['pom.xml']);
    results.push(parsed);
  }

  if (manifests['build.gradle']) {
    const parsed = parseBuildGradle(manifests['build.gradle']);
    results.push(parsed);
  }

  // Aggregate results
  return aggregateDependencies(results);
}

function aggregateDependencies(results) {
  if (results.length === 0) {
    return {
      production: 0,
      development: 0,
    };
  }

  // If single package manager, return its counts
  if (results.length === 1) {
    return {
      production: results[0].totalProduction,
      development: results[0].totalDevelopment,
    };
  }

  // Multiple package managers (e.g., monorepo)
  let totalProduction = 0;
  let totalDevelopment = 0;

  for (const result of results) {
    totalProduction += result.totalProduction;
    totalDevelopment += result.totalDevelopment;
  }

  return {
    production: totalProduction,
    development: totalDevelopment,
  };
}

async function validateProjectRoot(projectRoot) {
  try {
    const stat = await fs.stat(projectRoot);
    if (!stat.isDirectory()) {
      throw new Error(`Path is not a directory: ${projectRoot}`);
    }
  } catch (error) {
    throw new Error(`Invalid project root: ${error.message}`);
  }
}

async function detectManifests(projectRoot) {
  const manifests = {};

  const manifestFiles = [
    'package.json',
    'requirements.txt',
    'pyproject.toml',
    'go.mod',
    'Cargo.toml',
    'pom.xml',
    'build.gradle',
    'composer.json',
  ];

  for (const file of manifestFiles) {
    const filePath = path.join(projectRoot, file);
    try {
      const exists = await fs
        .access(filePath)
        .then(() => true)
        .catch(() => false);
      if (exists) {
        const content = await fs.readFile(filePath, 'utf-8');
        if (file.endsWith('.json') || file.endsWith('.toml')) {
          try {
            manifests[file] = file.endsWith('.json') ? JSON.parse(content) : content;
          } catch {
            manifests[file] = content; // Keep as string if parse fails
          }
        } else {
          manifests[file] = content;
        }
      }
    } catch (error) {
      // Skip files that can't be read
    }
  }

  return manifests;
}

async function detectProjectType(projectRoot, manifests) {
  // Check for monorepo indicators
  if (
    manifests['package.json']?.workspaces ||
    (await fileExists(projectRoot, 'pnpm-workspace.yaml')) ||
    (await fileExists(projectRoot, 'lerna.json'))
  ) {
    return 'monorepo';
  }

  // Check for mobile indicators
  if (
    (await directoryExists(projectRoot, 'android')) &&
    (await directoryExists(projectRoot, 'ios'))
  ) {
    return 'mobile';
  }

  // Check for microservices (multiple service directories)
  const rootDirs = await fs.readdir(projectRoot);
  const serviceDirs = rootDirs.filter(
    dir => dir.includes('service') || dir.includes('microservice')
  );
  if (serviceDirs.length >= 3) {
    return 'microservices';
  }

  // Check for serverless indicators
  if (
    (await fileExists(projectRoot, 'serverless.yml')) ||
    (await fileExists(projectRoot, 'serverless.yaml'))
  ) {
    return 'serverless';
  }

  // Check package.json for type indicators
  if (manifests['package.json']) {
    const pkg = manifests['package.json'];

    // CLI project
    if (pkg.bin) {
      return 'cli';
    }

    // Library project
    if (pkg.main && !pkg.scripts?.start && !pkg.scripts?.dev) {
      return 'library';
    }

    const deps = { ...pkg.dependencies, ...pkg.devDependencies };
    const hasReact = 'react' in deps;
    const hasNext = 'next' in deps;
    const hasExpress = 'express' in deps;
    const hasFastify = 'fastify' in deps;

    // Fullstack
    if ((hasNext || hasReact) && (hasExpress || hasFastify)) {
      return 'fullstack';
    }

    // Next.js is fullstack by default
    if (hasNext) {
      return 'fullstack';
    }

    // Frontend
    if (hasReact || 'vue' in deps || '@angular/core' in deps) {
      return 'frontend';
    }

    // Backend
    if (hasExpress || hasFastify || 'koa' in deps) {
      return 'backend';
    }
  }

  // Check Python manifests
  if (manifests['requirements.txt'] || manifests['pyproject.toml']) {
    const content = manifests['requirements.txt'] || manifests['pyproject.toml'];
    if (content.includes('fastapi') || content.includes('django') || content.includes('flask')) {
      return 'backend';
    }
  }

  return 'unknown';
}

async function detectFrameworks(manifests) {
  const frameworks = [];

  if (manifests['package.json']) {
    const pkg = manifests['package.json'];
    const allDeps = { ...pkg.dependencies, ...pkg.devDependencies };

    const frameworkMap = {
      // Frameworks
      next: { category: 'framework', name: 'nextjs' },
      react: { category: 'framework', name: 'react' },
      vue: { category: 'framework', name: 'vue' },
      '@angular/core': { category: 'framework', name: 'angular' },
      svelte: { category: 'framework', name: 'svelte' },
      express: { category: 'framework', name: 'express' },
      fastify: { category: 'framework', name: 'fastify' },

      // UI Libraries
      '@mui/material': { category: 'ui-library', name: 'material-ui' },
      antd: { category: 'ui-library', name: 'ant-design' },
      '@chakra-ui/react': { category: 'ui-library', name: 'chakra-ui' },

      // State Management
      redux: { category: 'state-management', name: 'redux' },
      zustand: { category: 'state-management', name: 'zustand' },
      jotai: { category: 'state-management', name: 'jotai' },

      // Testing
      jest: { category: 'testing', name: 'jest' },
      vitest: { category: 'testing', name: 'vitest' },
      cypress: { category: 'testing', name: 'cypress' },
      '@playwright/test': { category: 'testing', name: 'playwright' },

      // Build Tools
      vite: { category: 'build-tool', name: 'vite' },
      webpack: { category: 'build-tool', name: 'webpack' },
      esbuild: { category: 'build-tool', name: 'esbuild' },

      // Database/ORM
      prisma: { category: 'orm', name: 'prisma' },
      typeorm: { category: 'orm', name: 'typeorm' },
      mongoose: { category: 'orm', name: 'mongoose' },

      // Auth
      'next-auth': { category: 'auth', name: 'nextauth' },
      '@clerk/nextjs': { category: 'auth', name: 'clerk' },
    };

    for (const [depName, depVersion] of Object.entries(allDeps)) {
      if (frameworkMap[depName]) {
        const fw = frameworkMap[depName];
        frameworks.push({
          name: fw.name,
          version: depVersion.replace(/^\^|~/, ''),
          category: fw.category,
          confidence: 1.0,
          source: 'package.json',
        });
      }
    }
  }

  // Python frameworks
  if (manifests['requirements.txt']) {
    const content = manifests['requirements.txt'];
    const pythonFrameworks = {
      fastapi: 'framework',
      django: 'framework',
      flask: 'framework',
      pytest: 'testing',
      sqlalchemy: 'orm',
    };

    for (const [name, category] of Object.entries(pythonFrameworks)) {
      if (content.includes(name)) {
        frameworks.push({
          name,
          category,
          confidence: 0.9,
          source: 'requirements.txt',
        });
      }
    }
  }

  return frameworks;
}

async function generateFileStats(projectRoot) {
  const stats = {
    total_files: 0,
    total_lines: 0,
    languages: {},
    file_types: {},
    directories: 0,
    avg_file_size_lines: 0,
    largest_files: [],
    files_skipped: 0,
  };

  // Use glob to find all files, excluding common build/dep directories
  const pattern = '**/*';
  const files = await glob(pattern, {
    cwd: projectRoot,
    ignore: EXCLUDE_DIRS.map(dir => `**/${dir}/**`),
    nodir: true,
    dot: true,
  });

  const fileSizes = [];

  for (const file of files) {
    const fullPath = path.join(projectRoot, file);
    const ext = path.extname(file);

    // Count file types
    stats.file_types[ext] = (stats.file_types[ext] || 0) + 1;

    // Skip binary files and very large files
    if (
      ![
        '.md',
        '.txt',
        '.json',
        '.yaml',
        '.yml',
        '.js',
        '.ts',
        '.jsx',
        '.tsx',
        '.py',
        '.go',
        '.rs',
        '.java',
      ].includes(ext)
    ) {
      stats.files_skipped++;
      continue;
    }

    try {
      const content = await fs.readFile(fullPath, 'utf-8');
      const lines = content.split('\n').length;

      stats.total_files++;
      stats.total_lines += lines;

      // Track by language
      const language = LANGUAGE_MAP[ext] || 'Other';
      stats.languages[language] = (stats.languages[language] || 0) + lines;

      // Track file sizes
      fileSizes.push({ path: file, lines });
    } catch (error) {
      stats.files_skipped++;
    }
  }

  // Sort and get largest files
  fileSizes.sort((a, b) => b.lines - a.lines);
  stats.largest_files = fileSizes.slice(0, 10);

  // Calculate average
  if (stats.total_files > 0) {
    stats.avg_file_size_lines = Math.round(stats.total_lines / stats.total_files);
  }

  // Count directories
  const dirs = await glob('**/', {
    cwd: projectRoot,
    ignore: EXCLUDE_DIRS.map(dir => `**/${dir}/**`),
  });
  stats.directories = dirs.length;

  return stats;
}

async function analyzeStructure(projectRoot) {
  const rootDirs = await fs.readdir(projectRoot, { withFileTypes: true });
  const directories = rootDirs.filter(
    dirent => dirent.isDirectory() && !EXCLUDE_DIRS.includes(dirent.name)
  );

  const structure = {
    root_directories: [],
    entry_points: [],
    architecture_pattern: 'unknown',
    module_system: 'unknown',
  };

  // Classify root directories
  const purposeMap = {
    src: 'source',
    app: 'source',
    lib: 'source',
    test: 'tests',
    tests: 'tests',
    __tests__: 'tests',
    cypress: 'tests',
    config: 'config',
    '.config': 'config',
    docs: 'docs',
    documentation: 'docs',
    dist: 'build',
    build: 'build',
    out: 'build',
    scripts: 'scripts',
    bin: 'scripts',
    assets: 'assets',
    static: 'assets',
    public: 'public',
  };

  for (const dir of directories) {
    const purpose = purposeMap[dir.name.toLowerCase()] || 'unknown';

    // Count files in directory
    const filesInDir = await glob('**/*', {
      cwd: path.join(projectRoot, dir.name),
      nodir: true,
    });

    structure.root_directories.push({
      name: dir.name,
      purpose,
      file_count: filesInDir.length,
    });
  }

  // Detect entry points
  const entryPointCandidates = [
    { path: 'src/index.ts', type: 'main' },
    { path: 'src/index.js', type: 'main' },
    { path: 'app/page.tsx', type: 'app' },
    { path: 'src/app.ts', type: 'app' },
    { path: 'src/server.ts', type: 'server' },
    { path: 'main.py', type: 'main' },
    { path: 'app.py', type: 'app' },
  ];

  for (const candidate of entryPointCandidates) {
    if (await fileExists(projectRoot, candidate.path)) {
      structure.entry_points.push(candidate);
    }
  }

  // Detect architecture pattern
  const hasMVC = directories.some(d =>
    ['models', 'views', 'controllers'].includes(d.name.toLowerCase())
  );
  const hasLayered = directories.some(d =>
    ['presentation', 'business', 'data'].includes(d.name.toLowerCase())
  );
  const hasFeatures = directories.some(d => d.name === 'features' || d.name === 'modules');

  if (hasMVC) {
    structure.architecture_pattern = 'mvc';
  } else if (hasLayered) {
    structure.architecture_pattern = 'layered';
  } else if (hasFeatures) {
    structure.architecture_pattern = 'modular';
  } else if (structure.root_directories.length <= 3) {
    structure.architecture_pattern = 'flat';
  } else {
    structure.architecture_pattern = 'monolith';
  }

  // Detect module system (check package.json)
  try {
    const pkgPath = path.join(projectRoot, 'package.json');
    const pkg = JSON.parse(await fs.readFile(pkgPath, 'utf-8'));
    structure.module_system = pkg.type === 'module' ? 'esm' : 'commonjs';
  } catch {
    structure.module_system = 'unknown';
  }

  return structure;
}

async function analyzeDependencies(manifests) {
  const dependencies = {
    production: 0,
    development: 0,
  };

  if (manifests['package.json']) {
    const pkg = manifests['package.json'];
    dependencies.production = Object.keys(pkg.dependencies || {}).length;
    dependencies.development = Object.keys(pkg.devDependencies || {}).length;
  }

  return dependencies;
}

async function analyzeCodeQuality(projectRoot, manifests) {
  const quality = {
    linting: {
      configured: false,
      tool: null,
    },
    formatting: {
      configured: false,
      tool: null,
    },
    testing: {
      framework: null,
      test_files: 0,
      coverage_configured: false,
    },
    type_safety: {
      typescript: false,
      strict_mode: false,
    },
  };

  // Check for linting
  if (
    (await fileExists(projectRoot, '.eslintrc.json')) ||
    (await fileExists(projectRoot, 'eslint.config.js'))
  ) {
    quality.linting.configured = true;
    quality.linting.tool = 'eslint';
  }

  // Check for formatting
  if (
    (await fileExists(projectRoot, '.prettierrc')) ||
    (await fileExists(projectRoot, 'prettier.config.js'))
  ) {
    quality.formatting.configured = true;
    quality.formatting.tool = 'prettier';
  }

  // Check for testing
  if (manifests['package.json']) {
    const pkg = manifests['package.json'];
    const deps = { ...pkg.dependencies, ...pkg.devDependencies };

    if ('jest' in deps) quality.testing.framework = 'jest';
    if ('vitest' in deps) quality.testing.framework = 'vitest';
    if ('cypress' in deps) quality.testing.framework = 'cypress';
    if ('@playwright/test' in deps) quality.testing.framework = 'playwright';
  }

  // Count test files
  const testFiles = await glob('**/*.{test,spec}.{ts,tsx,js,jsx}', {
    cwd: projectRoot,
    ignore: EXCLUDE_DIRS.map(dir => `**/${dir}/**`),
  });
  quality.testing.test_files = testFiles.length;

  // Check for TypeScript
  if (await fileExists(projectRoot, 'tsconfig.json')) {
    quality.type_safety.typescript = true;
    try {
      const tsconfigPath = path.join(projectRoot, 'tsconfig.json');
      const tsconfig = JSON.parse(await fs.readFile(tsconfigPath, 'utf-8'));
      quality.type_safety.strict_mode = tsconfig.compilerOptions?.strict === true;
    } catch {
      // Ignore parse errors
    }
  }

  return quality;
}

async function detectPatterns(projectRoot, stats) {
  const patterns = [];

  // Large files (anti-pattern)
  const largeFiles = stats.largest_files.filter(f => f.lines > 1000);
  if (largeFiles.length > 0) {
    patterns.push({
      pattern: 'large-files',
      type: 'anti-pattern',
      description: `${largeFiles.length} files exceed 1000 lines (violates micro-service principle)`,
      locations: largeFiles.map(f => f.path),
      recommendation: 'Refactor large files into smaller, focused modules (< 1000 lines)',
    });
  }

  return patterns;
}

function calculateTechDebt(stats, dependencies, codeQuality, patterns) {
  const indicators = [];
  let score = 0;

  // Large files penalty
  const largeFiles = stats.largest_files.filter(f => f.lines > 1000);
  if (largeFiles.length > 0) {
    score += Math.min(largeFiles.length * 5, 30);
    indicators.push({
      category: 'complexity',
      severity: largeFiles.length > 5 ? 'high' : 'medium',
      description: `${largeFiles.length} files exceed 1000 lines`,
      remediation_effort: largeFiles.length > 10 ? 'major' : 'moderate',
    });
  }

  // Missing tests penalty
  if (codeQuality.testing.test_files === 0) {
    score += 20;
    indicators.push({
      category: 'missing-tests',
      severity: 'high',
      description: 'No test files found',
      remediation_effort: 'major',
    });
  }

  // No linting penalty
  if (!codeQuality.linting.configured) {
    score += 10;
    indicators.push({
      category: 'documentation',
      severity: 'medium',
      description: 'No linting configuration found',
      remediation_effort: 'minor',
    });
  }

  // No TypeScript strict mode
  if (codeQuality.type_safety.typescript && !codeQuality.type_safety.strict_mode) {
    score += 5;
    indicators.push({
      category: 'documentation',
      severity: 'low',
      description: 'TypeScript strict mode not enabled',
      remediation_effort: 'minor',
    });
  }

  return {
    score: Math.min(score, 100),
    indicators,
  };
}

function generateRecommendations(projectType, techDebt, codeQuality) {
  const recommendations = [];

  // Large files recommendation
  const complexityIssues = techDebt.indicators.filter(i => i.category === 'complexity');
  if (complexityIssues.length > 0) {
    recommendations.push({
      priority: 'P1',
      category: 'maintainability',
      title: 'Refactor large files',
      description:
        'Break down files exceeding 1000 lines into smaller, focused modules following micro-service principles',
      effort: 'moderate',
      impact: 'high',
    });
  }

  // Missing tests recommendation
  if (codeQuality.testing.test_files === 0) {
    recommendations.push({
      priority: 'P0',
      category: 'testing',
      title: 'Add test coverage',
      description:
        'Implement unit and integration tests to ensure code quality and prevent regressions',
      effort: 'major',
      impact: 'critical',
    });
  }

  // No linting recommendation
  if (!codeQuality.linting.configured) {
    recommendations.push({
      priority: 'P2',
      category: 'maintainability',
      title: 'Configure code linting',
      description: 'Set up ESLint or similar linting tool to enforce coding standards',
      effort: 'trivial',
      impact: 'medium',
    });
  }

  return recommendations;
}

