function getRipgrepBinary() {
  const plat = platform();
  const architecture = arch();

  let binPath;
  switch (plat) {
    case 'win32':
      binPath = join(BIN_DIR, 'win32-x64', 'rg.exe');
      break;
    case 'darwin':
      binPath = architecture === 'arm64'
        ? join(BIN_DIR, 'darwin-arm64', 'rg')
        : join(BIN_DIR, 'darwin-x64', 'rg');
      break;
    case 'linux':
      binPath = architecture === 'arm64'
        ? join(BIN_DIR, 'linux-arm64', 'rg')
        : join(BIN_DIR, 'linux-x64', 'rg');
      break;
    default:
      throw new Error(`Unsupported platform: ${plat}`);
  }

  if (!existsSync(binPath)) {
    throw new Error(`Ripgrep binary not found at: ${binPath}`);
  }

  return binPath;
}

async function runRipgrep(args) {
  const rgBinary = getRipgrepBinary();
  const env = { ...process.env, RIPGREP_CONFIG_PATH: CONFIG_PATH };

  return new Promise((resolve, reject) => {
    const proc = spawn(rgBinary, args, {
      env,
      stdio: ['inherit', 'pipe', 'pipe'],
      cwd: PROJECT_ROOT,
      windowsHide: true,
    });

    proc.stdout.on('data', (data) => process.stdout.write(data));
    proc.stderr.on('data', (data) => process.stderr.write(data));

    proc.on('close', (code) => {
      if (code === 0 || code === 1) resolve(code);
      else reject(new Error(`ripgrep exited with code ${code}`));
    });

    proc.on('error', reject);
  });
}

async function main() {
  const args = process.argv.slice(2);

  if (args.length < 2 || args.includes('--help') || args.includes('-h')) {
    showHelp();
    process.exit(0);
  }

  const [preset, pattern, ...rest] = args;
  let rgArgs = ['-n']; // Always show line numbers
  let searchPath = '.';

  // Parse preset
  switch (preset.toLowerCase()) {
    case 'js':
      rgArgs.push('--type', 'js');
      if (rest[0] && !rest[0].startsWith('-')) searchPath = rest.shift();
      break;

    case 'ts':
      rgArgs.push('--type', 'ts');
      if (rest[0] && !rest[0].startsWith('-')) searchPath = rest.shift();
      break;

    case 'mjs':
      rgArgs.push('--glob', '*.mjs');
      if (rest[0] && !rest[0].startsWith('-')) searchPath = rest.shift();
      break;

    case 'hooks':
      rgArgs.push('--type', 'js');
      searchPath = '.claude/hooks/';
      break;

    case 'skills':
      rgArgs.push('--type', 'js', '--type', 'md');
      searchPath = '.claude/skills/';
      break;

    case 'tools':
      rgArgs.push('--type', 'js');
      searchPath = '.claude/tools/';
      break;

    case 'agents':
      rgArgs.push('--type', 'md');
      searchPath = '.claude/agents/';
      break;

    case 'all':
      if (rest[0] && !rest[0].startsWith('-')) searchPath = rest.shift();
      break;

    default:
      console.error(`Unknown preset: ${preset}`);
      console.error('Run with --help for available presets');
      process.exit(1);
  }

  // Add pattern and path
  rgArgs.push(pattern, searchPath, ...rest);

  try {
    await runRipgrep(rgArgs);
  } catch (error) {
    console.error(`Error: ${error.message}`);
    process.exit(2);
  }
}

