async function loadCache() {
  try {
    if (existsSync(CACHE_FILE)) {
      const cacheData = await readFile(CACHE_FILE, 'utf8');
      const cache = JSON.parse(cacheData);
      skillCache.clear();
      skillMetadataCache.clear();

      for (const [key, value] of Object.entries(cache.skills || {})) {
        skillCache.set(key, value);
      }
      for (const [key, value] of Object.entries(cache.metadata || {})) {
        skillMetadataCache.set(key, value);
      }
    }
  } catch (error) {
    // Cache load failed, continue without cache
  }
}

async function saveCache() {
  // Mark save as pending
  saveCachePending = true;

  // Debounce: only save after 100ms of inactivity
  if (saveCacheTimer) {
    clearTimeout(saveCacheTimer);
  }

  saveCacheTimer = setTimeout(async () => {
    if (!saveCachePending) return;
    saveCachePending = false;

    try {
      await mkdir(CACHE_DIR, { recursive: true });
      const cacheData = {
        skills: Object.fromEntries(skillCache),
        metadata: Object.fromEntries(skillMetadataCache),
        timestamp: new Date().toISOString(),
      };
      await writeFile(CACHE_FILE, JSON.stringify(cacheData, null, 2), 'utf8');
    } catch (error) {
      // Cache save failed, continue without persistence
    }
  }, 100);
}

export async function loadSkillMetadata(skillName) {
  // Check cache first
  if (skillMetadataCache.has(skillName)) {
    return skillMetadataCache.get(skillName);
  }

  const skillPath = join(__dirname, `../${skillName}/SKILL.md`);

  try {
    const rawContent = await readFile(skillPath, 'utf8');
    // Normalize line endings (handle Windows CRLF and Unix LF)
    const content = rawContent.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    const frontmatterMatch = content.match(/^---\n([\s\S]*?)\n---/);

    if (frontmatterMatch) {
      const frontmatterText = frontmatterMatch[1];

      // Parse YAML frontmatter using js-yaml
      const frontmatter = yaml.load(frontmatterText);

      // Extract context:fork field (handle colon in key name)
      const metadata = {
        name: frontmatter.name,
        description: frontmatter.description,
        contextFork: frontmatter['context:fork'] ?? false,
        model: frontmatter.model,
        allowedTools: frontmatter['allowed-tools'] || [],
        version: frontmatter.version,
        executable: frontmatter.executable,
        testSuite: frontmatter.test_suite,
        bestPractices: frontmatter.best_practices,
        errorHandling: frontmatter.error_handling,
        streaming: frontmatter.streaming,
        templates: frontmatter.templates,
      };

      skillMetadataCache.set(skillName, metadata);
      await saveCache();
      return metadata;
    }

    return {};
  } catch (error) {
    return {};
  }
}

export async function loadSkillInstructions(skillName, useCache = true) {
  // Check cache first
  if (useCache && skillCache.has(skillName)) {
    return skillCache.get(skillName);
  }

  const skillPath = join(__dirname, `../${skillName}/SKILL.md`);

  try {
    const rawContent = await readFile(skillPath, 'utf8');
    // Normalize line endings (handle Windows CRLF and Unix LF)
    const content = rawContent.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    // Extract content after YAML frontmatter
    const frontmatterEnd = content.indexOf('---', 3);
    const instructions =
      frontmatterEnd !== -1 ? content.substring(frontmatterEnd + 3).trim() : content;

    // Cache the instructions
    if (useCache) {
      skillCache.set(skillName, instructions);
      await saveCache();
    }

    return instructions;
  } catch (error) {
    throw new Error(`Failed to load skill instructions for ${skillName}: ${error.message}`);
  }
}

