  } catch (e) {
    console.error(`[ERROR] Error creating directory: ${e.message}`);
    return null;
  }

  // Create SKILL.md
  const skillTitle = titleCase(skillName);
  const skillContent = SKILL_TEMPLATE.replace(/{skill_name}/g, skillName).replace(
    /{skill_title}/g,
    skillTitle
  );

  const skillMdPath = path.join(skillDir, "SKILL.md");
  try {
    fs.writeFileSync(skillMdPath, skillContent);
    console.log("[OK] Created SKILL.md");
  } catch (e) {
    console.error(`[ERROR] Error creating SKILL.md: ${e.message}`);
    return null;
  }

  // Create resource directories
  if (resources.length > 0) {
    try {
      createResourceDirs(skillDir, skillName, resources, includeExamples);
    } catch (e) {
      console.error(`[ERROR] Error creating resources: ${e.message}`);
      return null;
    }
  }

  // Print next steps
  console.log(`\n[OK] Skill '${skillName}' initialized at ${skillDir}`);
  console.log("\nNext steps:");
  console.log("1. Edit SKILL.md - complete TODO items and update description");
  if (resources.length > 0) {
    if (includeExamples) {
      console.log("2. Customize or delete example files in resource directories");
    } else {
      console.log("2. Add resources to scripts/, references/, assets/ as needed");
    }
  } else {
    console.log("2. Create resource directories only if needed");
  }
  console.log("3. Run validate.cjs to verify after editing");

  return skillDir;
}

function runTest(skillPath) {
  const testScript = path.join(__dirname, "test.cjs");

  console.log(`\n[TEST] Validating skill structure...`);

  const result = spawnSync("node", [testScript, skillPath], {
    stdio: "inherit",
    shell: true,
    timeout: 30000,
  });

  if (result.status === 0) {
    return { passed: true };
  } else {
    return { passed: false, exitCode: result.status };
  }
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  if (args.help) usage(0);
  if (!args.skillName) {
    console.error("[ERROR] Skill name is required");
    usage(1);
  }

  // Normalize skill name
  const rawName = args.skillName;
  const skillName = normalizeSkillName(rawName);

  if (!skillName) {
    console.error("[ERROR] Skill name must include at least one letter or digit");
    process.exit(1);
  }

  if (skillName.length > MAX_SKILL_NAME_LENGTH) {
    console.error(
      `[ERROR] Skill name '${skillName}' is too long (${skillName.length} chars). Max: ${MAX_SKILL_NAME_LENGTH}`
    );
    process.exit(1);
  }

  if (skillName !== rawName) {
    console.log(`Note: Normalized skill name from '${rawName}' to '${skillName}'`);
  }

  // Validate resources
  const invalidResources = args.resources.filter((r) => !ALLOWED_RESOURCES.has(r));
  if (invalidResources.length > 0) {
    console.error(
      `[ERROR] Unknown resource type(s): ${invalidResources.join(", ")}`
    );
    console.error(`   Allowed: ${[...ALLOWED_RESOURCES].join(", ")}`);
    process.exit(1);
  }

  if (args.examples && args.resources.length === 0) {
    console.error("[ERROR] --examples requires --resources to be set");
    process.exit(1);
  }

  // Dedupe resources
  const resources = [...new Set(args.resources)];

  console.log(`Initializing skill: ${skillName}`);
  console.log(`   Location: ${args.path}`);
  if (resources.length > 0) {
    console.log(`   Resources: ${resources.join(", ")}`);
    if (args.examples) console.log("   Examples: enabled");
  } else {
    console.log("   Resources: none (create as needed)");
  }
  console.log();

  const skillDir = createSkill(skillName, args.path, resources, args.examples);

  if (!skillDir) {
    process.exit(1);
  }

  // Run validation tests automatically unless --no-test
  if (args.test) {
    const testResult = runTest(skillDir);
    if (!testResult.passed) {
      console.log(`\n[NOTE] Validation shows warnings - this is expected for new skills.`);
      console.log(`       Complete the TODO items in SKILL.md to fix them.`);
    }
  }

  process.exit(0);
}

function parseArgs(argv) {
  const args = {
    repo: null,
    url: null,
    paths: [],
    ref: DEFAULT_REF,
    dest: DEFAULT_DEST,
    name: null,
    help: false,
  };

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === "--repo") args.repo = argv[++i];
    else if (token === "--url") args.url = argv[++i];
    else if (token === "--path") args.paths.push(argv[++i]);
    else if (token === "--ref") args.ref = argv[++i];
    else if (token === "--dest") args.dest = argv[++i];
    else if (token === "--name") args.name = argv[++i];
    else if (token === "--help" || token === "-h") args.help = true;
  }

  return args;
}

function parseGitHubUrl(url, defaultRef) {
  const parsed = new URL(url);
  if (parsed.hostname !== "github.com") {
    throw new Error("Only GitHub URLs are supported");
  }

  const parts = parsed.pathname.split("/").filter(Boolean);
  if (parts.length < 2) {
    throw new Error("Invalid GitHub URL");
  }

  const owner = parts[0];
  const repo = parts[1];
  let ref = defaultRef;
  let subpath = "";

  if (parts.length > 2) {
    if (parts[2] === "tree" || parts[2] === "blob") {
      if (parts.length < 4) {
        throw new Error("GitHub URL missing ref or path");
      }
      ref = parts[3];
      subpath = parts.slice(4).join("/");
    } else {
      subpath = parts.slice(2).join("/");
    }
  }

  return { owner, repo, ref, subpath: subpath || null };
}

async function downloadFile(url) {
  return httpsGet(url);
}

async function fetchGitHubContents(owner, repo, path, ref) {
  const apiUrl = `https://api.github.com/repos/${owner}/${repo}/contents/${path}?ref=${ref}`;
  const data = await httpsGet(apiUrl, { Accept: "application/vnd.github.v3+json" });
  return JSON.parse(data.toString());
}

async function downloadDirectory(owner, repo, dirPath, ref, destDir) {
  const contents = await fetchGitHubContents(owner, repo, dirPath, ref);

  if (!Array.isArray(contents)) {
    throw new Error(`Path is not a directory: ${dirPath}`);
  }

  fs.mkdirSync(destDir, { recursive: true });

  for (const item of contents) {
    const itemDest = path.join(destDir, item.name);

    if (item.type === "file") {
      console.log(`  Downloading: ${item.path}`);
      const content = await downloadFile(item.download_url);
      fs.writeFileSync(itemDest, content);
    } else if (item.type === "dir") {
      await downloadDirectory(owner, repo, item.path, ref, itemDest);
    }
  }
}

function gitSparseCheckout(owner, repo, ref, paths, destDir) {
  const repoUrl = `https://github.com/${owner}/${repo}.git`;
  const repoDir = path.join(destDir, "repo");

  try {
    // Clone with sparse checkout
    execSync(
      `git clone --filter=blob:none --depth 1 --sparse --single-branch --branch ${ref} ${repoUrl} ${repoDir}`,
      { stdio: "pipe" }
    );
  } catch (e) {
    // Try without branch (might be a tag or commit)
    execSync(
      `git clone --filter=blob:none --depth 1 --sparse --single-branch ${repoUrl} ${repoDir}`,
      { stdio: "pipe" }
    );
  }

  // Set sparse checkout paths
  execSync(`git -C ${repoDir} sparse-checkout set ${paths.join(" ")}`, {
    stdio: "pipe",
  });

  // Checkout specific ref
  execSync(`git -C ${repoDir} checkout ${ref}`, { stdio: "pipe" });

  return repoDir;
}

function validateSkillDir(skillPath) {
  if (!fs.existsSync(skillPath)) {
    throw new Error(`Skill path not found: ${skillPath}`);
  }

  const skillMd = path.join(skillPath, "SKILL.md");
  if (!fs.existsSync(skillMd)) {
    throw new Error("SKILL.md not found in skill directory");
  }
}

function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });

  const entries = fs.readdirSync(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);

    if (entry.isDirectory()) {
      copyDir(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

function rmrf(dir) {
  if (fs.existsSync(dir)) {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

async function installSkill(source, skillPath, destRoot, overrideName) {
  const skillName = overrideName || path.basename(skillPath);

  // Validate skill name
  if (!skillName || skillName === "." || skillName === "..") {
    throw new Error("Invalid skill name");
  }

  const destDir = path.join(destRoot, skillName);

  // Check destination doesn't exist
  if (fs.existsSync(destDir)) {
    throw new Error(`Destination already exists: ${destDir}`);
  }

  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "skill-install-"));

  try {
    console.log(`Installing ${skillName} from ${source.owner}/${source.repo}...`);

    let repoRoot;
    let useGit = false;

    // Try direct download first
    try {
      const skillDestTmp = path.join(tmpDir, skillName);
      await downloadDirectory(
        source.owner,
        source.repo,
        skillPath,
        source.ref,
        skillDestTmp
      );
      repoRoot = tmpDir;
    } catch (e) {
      // Fall back to git sparse checkout
      if (
        e.message.includes("HTTP 401") ||
        e.message.includes("HTTP 403") ||
        e.message.includes("HTTP 404")
      ) {
        console.log("  Download failed, trying git sparse checkout...");
        useGit = true;
        repoRoot = gitSparseCheckout(
          source.owner,
          source.repo,
          source.ref,
          [skillPath],
          tmpDir
        );
      } else {
        throw e;
      }
    }

    // Validate and copy
    const srcPath = useGit
      ? path.join(repoRoot, skillPath)
      : path.join(repoRoot, skillName);

    validateSkillDir(srcPath);

    // Create destination directory
    fs.mkdirSync(path.dirname(destDir), { recursive: true });
    copyDir(srcPath, destDir);

    console.log(`[OK] Installed ${skillName} to ${destDir}`);
    return { name: skillName, path: destDir };
  } finally {
    rmrf(tmpDir);
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2));

  if (args.help) usage(0);

  // Resolve source
  let source;
  let paths = args.paths;

  if (args.url) {
    const parsed = parseGitHubUrl(args.url, args.ref);
    source = { owner: parsed.owner, repo: parsed.repo, ref: parsed.ref };
    if (parsed.subpath && paths.length === 0) {
      paths = [parsed.subpath];
    }
  } else if (args.repo) {
    const parts = args.repo.split("/").filter(Boolean);
    if (parts.length !== 2) {
      console.error("[ERROR] --repo must be in owner/repo format");
      process.exit(1);
    }
    source = { owner: parts[0], repo: parts[1], ref: args.ref };
  } else {
    console.error("[ERROR] Provide --repo or --url");
    usage(1);
  }

  if (paths.length === 0) {
    console.error("[ERROR] Missing --path");
    process.exit(1);
  }

  if (args.name && paths.length > 1) {
    console.error("[ERROR] --name can only be used with a single --path");
    process.exit(1);
  }

  // Validate paths
  for (const p of paths) {
    if (path.isAbsolute(p) || p.startsWith("..")) {
      console.error(`[ERROR] Path must be relative: ${p}`);
      process.exit(1);
    }
  }

  // Install each skill
  const installed = [];
  try {
    for (const skillPath of paths) {
      const name = paths.length === 1 ? args.name : null;
      const result = await installSkill(source, skillPath, args.dest, name);
      installed.push(result);
    }

    console.log("\n[OK] Installation complete");
    if (installed.length > 1) {
      console.log("Installed skills:");
      installed.forEach((s) => console.log(`  - ${s.name}`));
    }
    console.log("\nRestart Claude Code to pick up new skills.");
  } catch (e) {
    console.error(`[ERROR] ${e.message}`);
    process.exit(1);
  }
}

function parseArgs(argv) {
  const args = {
    path: DEFAULT_SKILLS_PATH,
    repo: null,
    repoPath: "skills/",
    ref: DEFAULT_REF,
    format: "text",
    help: false,
  };

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token === "--path") args.path = argv[++i];
    else if (token === "--repo") args.repo = argv[++i];
    else if (token === "--repo-path") args.repoPath = argv[++i];
    else if (token === "--ref") args.ref = argv[++i];
    else if (token === "--format") args.format = argv[++i];
    else if (token === "--help" || token === "-h") args.help = true;
  }

  return args;
}

function getInstalledSkills(skillsPath) {
  const skills = [];
  const resolvedPath = path.resolve(skillsPath);

  if (!fs.existsSync(resolvedPath)) {
    return skills;
  }

  const entries = fs.readdirSync(resolvedPath, { withFileTypes: true });

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;

    const skillDir = path.join(resolvedPath, entry.name);
    const skillMd = path.join(skillDir, "SKILL.md");

    if (fs.existsSync(skillMd)) {
      const content = fs.readFileSync(skillMd, "utf8");

      // Extract name and description from frontmatter
      let name = entry.name;
      let description = "";

      // Normalize line endings to handle both LF and CRLF
      const normalizedContent = content.replace(/\r\n/g, '\n');
      const frontmatterMatch = normalizedContent.match(/^---\n([\s\S]*?)\n---/);
      if (frontmatterMatch) {
        const nameMatch = frontmatterMatch[1].match(/^name:\s*(.+)$/m);
        const descMatch = frontmatterMatch[1].match(/^description:\s*(.+)$/m);
        if (nameMatch) name = nameMatch[1].trim();
        if (descMatch) description = descMatch[1].trim();
      }

      // Truncate description
      if (description.length > 80) {
        description = description.slice(0, 77) + "...";
      }

      skills.push({
        name,
        folder: entry.name,
        path: skillDir,
        description,
        installed: true,
      });
    }
  }

  return skills.sort((a, b) => a.name.localeCompare(b.name));
}

async function getRepoSkills(repo, repoPath, ref) {
  const [owner, repoName] = repo.split("/");
  const apiUrl = `https://api.github.com/repos/${owner}/${repoName}/contents/${repoPath}?ref=${ref}`;

  try {
    const data = await httpsGet(apiUrl);
    const contents = JSON.parse(data.toString());

    if (!Array.isArray(contents)) {
      throw new Error("Path is not a directory");
    }

    const skills = [];
    for (const item of contents) {
      if (item.type === "dir") {
        skills.push({
          name: item.name,
          path: item.path,
          url: `https://github.com/${repo}/tree/${ref}/${item.path}`,
          installed: false,
        });
      }
    }

    return skills.sort((a, b) => a.name.localeCompare(b.name));
  } catch (e) {
    if (e.message.includes("HTTP 404")) {
      throw new Error(`Path not found: https://github.com/${repo}/tree/${ref}/${repoPath}`);
    }
    throw e;
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2));

  if (args.help) usage(0);

  try {
    let skills;
    let source;

    if (args.repo) {
      // List from GitHub repo
      source = `${args.repo}/${args.repoPath}`;
      const repoSkills = await getRepoSkills(args.repo, args.repoPath, args.ref);

      // Check which are already installed
      const installed = new Set(
        getInstalledSkills(args.path).map((s) => s.name)
      );

      skills = repoSkills.map((s) => ({
        ...s,
        installed: installed.has(s.name),
      }));
    } else {
      // List installed skills
      source = path.resolve(args.path);
      skills = getInstalledSkills(args.path);
    }

    if (args.format === "json") {
      console.log(JSON.stringify(skills, null, 2));
    } else {
      if (args.repo) {
        console.log(`Skills from ${source}:\n`);
      } else {
        console.log(`Installed skills in ${source}:\n`);
      }

      if (skills.length === 0) {
        console.log("  (none)");
      } else {
        for (let i = 0; i < skills.length; i++) {
          const s = skills[i];
          const suffix = s.installed && args.repo ? " (installed)" : "";
          const desc = s.description ? ` - ${s.description}` : "";
          console.log(`  ${i + 1}. ${s.name}${suffix}${desc}`);
        }
      }

      if (args.repo) {
        console.log(
          "\nTo install: node install.cjs --repo " +
            args.repo +
            " --path " +
            args.repoPath +
            "<skill-name>"
        );
      }
    }
  } catch (e) {
    console.error(`[ERROR] ${e.message}`);
    process.exit(1);
  }
}

function detectPlatform(dirPath) {
  const files = fs.readdirSync(dirPath);

  const claudeScore = CLAUDE_INDICATORS.filter(f =>
    files.includes(f) || fs.existsSync(path.join(dirPath, f))
  ).length;

  const geminiScore = GEMINI_INDICATORS.filter(f =>
    files.includes(f) || fs.existsSync(path.join(dirPath, f))
  ).length;

  if (claudeScore > 0 && geminiScore > 0) {
    return { platform: 'universal', claudeScore, geminiScore };
  } else if (claudeScore > geminiScore) {
    return { platform: 'claude', claudeScore, geminiScore };
  } else if (geminiScore > claudeScore) {
    return { platform: 'gemini', claudeScore, geminiScore };
  }

  return { platform: 'unknown', claudeScore, geminiScore };
}

function parseSkillMd(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const frontmatterMatch = content.match(/^---\n([\s\S]*?)\n---/);

  if (!frontmatterMatch) {
    throw new Error('No YAML frontmatter found in SKILL.md');
  }

  const frontmatter = yaml.load(frontmatterMatch[1]);
  const body = content.slice(frontmatterMatch[0].length).trim();

  return { frontmatter, body, raw: content };
}

function parseGeminiExtension(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  return JSON.parse(content);
}

function allowlistToDenylist(allowedTools) {
  if (!allowedTools || allowedTools.length === 0) {
    return []; // No restrictions = no exclusions
  }
  return ALL_TOOLS.filter(tool => !allowedTools.includes(tool));
}

function denylistToAllowlist(excludeTools) {
  if (!excludeTools || excludeTools.length === 0) {
    return []; // No exclusions = all allowed (empty means no restriction)
  }
  return ALL_TOOLS.filter(tool => !excludeTools.includes(tool));
}

function claudeToGemini(sourcePath, outputPath) {
  const skillPath = path.join(sourcePath, 'SKILL.md');
  if (!fs.existsSync(skillPath)) {
    throw new Error(`SKILL.md not found in ${sourcePath}`);
  }

  const { frontmatter, body } = parseSkillMd(skillPath);

  // Create gemini-extension.json
  const geminiExtension = {
    name: frontmatter.name || path.basename(sourcePath),
    version: frontmatter.version || '1.0.0',
    description: frontmatter.description || '',
    contextFilename: 'GEMINI.md'
  };

  // Convert allowed-tools to excludeTools
  if (frontmatter['allowed-tools']) {
    const excludeTools = allowlistToDenylist(frontmatter['allowed-tools']);
    if (excludeTools.length > 0) {
      geminiExtension.excludeTools = excludeTools;
    }
  }

  // Handle MCP servers if present
  const mcpConfigPath = path.join(sourcePath, 'config.json');
  if (fs.existsSync(mcpConfigPath)) {
    const mcpConfig = JSON.parse(fs.readFileSync(mcpConfigPath, 'utf8'));
    geminiExtension.mcpServers = {
      [mcpConfig.skill_name || frontmatter.name]: {
        command: mcpConfig.command,
        args: mcpConfig.args?.map(arg =>
          arg.replace(/\$\{skillPath\}/g, '${extensionPath}')
        ) || []
      }
    };

    // Convert env vars to settings
    if (mcpConfig.env) {
      geminiExtension.settings = {};
      for (const [key, value] of Object.entries(mcpConfig.env)) {
        geminiExtension.settings[key] = {
          description: `Environment variable: ${key}`,
          required: false,
          secret: key.toLowerCase().includes('key') ||
                  key.toLowerCase().includes('token') ||
                  key.toLowerCase().includes('secret')
        };
      }
    }
  }

  // Ensure output directory exists
  fs.mkdirSync(outputPath, { recursive: true });

  // Write gemini-extension.json
  fs.writeFileSync(
    path.join(outputPath, 'gemini-extension.json'),
    JSON.stringify(geminiExtension, null, 2)
  );

  // Create GEMINI.md from SKILL.md body
  const geminiMd = `# ${frontmatter.name || path.basename(sourcePath)}\n\n${frontmatter.description || ''}\n\n${body}`;
  fs.writeFileSync(path.join(outputPath, 'GEMINI.md'), geminiMd);

  // Copy shared resources
  const sharedPath = path.join(sourcePath, 'shared');
  if (fs.existsSync(sharedPath)) {
    copyDir(sharedPath, path.join(outputPath, 'shared'));
  }

  // Copy scripts as servers
  const scriptsPath = path.join(sourcePath, 'scripts');
  if (fs.existsSync(scriptsPath)) {
    copyDir(scriptsPath, path.join(outputPath, 'servers'));
  }

  return {
    success: true,
    files: ['gemini-extension.json', 'GEMINI.md'],
    target: 'gemini'
  };
}

function geminiToClaude(sourcePath, outputPath) {
  const extensionPath = path.join(sourcePath, 'gemini-extension.json');
  if (!fs.existsSync(extensionPath)) {
    throw new Error(`gemini-extension.json not found in ${sourcePath}`);
  }

  const extension = parseGeminiExtension(extensionPath);

  // Build SKILL.md frontmatter
  const frontmatter = {
    name: extension.name,
    description: extension.description || ''
  };

  // Convert excludeTools to allowed-tools
  if (extension.excludeTools && extension.excludeTools.length > 0) {
    frontmatter['allowed-tools'] = denylistToAllowlist(extension.excludeTools);
  }

  if (extension.version) {
    frontmatter.version = extension.version;
  }

  // Read GEMINI.md for body content
  let body = '';
  const geminiMdPath = path.join(sourcePath, extension.contextFilename || 'GEMINI.md');
  if (fs.existsSync(geminiMdPath)) {
    body = fs.readFileSync(geminiMdPath, 'utf8');
    // Remove the first heading if it matches the name
    body = body.replace(new RegExp(`^#\\s*${extension.name}\\s*\n+`, 'i'), '');
    // Remove description if it's duplicated at the start
    if (extension.description) {
      body = body.replace(new RegExp(`^${escapeRegex(extension.description)}\\s*\n+`, 'i'), '');
    }
  }

  // Ensure output directory exists
  fs.mkdirSync(outputPath, { recursive: true });

  // Write SKILL.md
  const skillMd = `---\n${yaml.dump(frontmatter)}---\n\n# ${extension.name}\n\n${body}`;
  fs.writeFileSync(path.join(outputPath, 'SKILL.md'), skillMd);

  // Create config.json from MCP servers
  if (extension.mcpServers) {
    const serverName = Object.keys(extension.mcpServers)[0];
    const serverConfig = extension.mcpServers[serverName];

    const config = {
      skill_name: extension.name,
      command: serverConfig.command,
      args: serverConfig.args?.map(arg =>
        arg.replace(/\$\{extensionPath\}/g, '${skillPath}')
      ) || [],
      description: extension.description,
      source: `Converted from Gemini extension`
    };

    // Convert settings to env
    if (extension.settings) {
      config.env = {};
      for (const key of Object.keys(extension.settings)) {
        config.env[key] = `\${${key}}`;
      }
    }

    fs.writeFileSync(
      path.join(outputPath, 'config.json'),
      JSON.stringify(config, null, 2)
    );
  }

  // Copy shared resources
  const sharedPath = path.join(sourcePath, 'shared');
  if (fs.existsSync(sharedPath)) {
    copyDir(sharedPath, path.join(outputPath, 'shared'));
  }

  // Copy servers as scripts
  const serversPath = path.join(sourcePath, 'servers');
  if (fs.existsSync(serversPath)) {
    copyDir(serversPath, path.join(outputPath, 'scripts'));
  }

  return {
    success: true,
    files: ['SKILL.md', 'config.json'],
    target: 'claude'
  };
}

function makeUniversal(sourcePath, outputPath) {
  const detection = detectPlatform(sourcePath);

  if (detection.platform === 'universal') {
    console.log('Skill is already universal (has both SKILL.md and gemini-extension.json)');
    return { success: true, alreadyUniversal: true };
  }

  // Copy source to output first
  if (sourcePath !== outputPath) {
    copyDir(sourcePath, outputPath);
  }

  // Add missing platform files
  if (detection.platform === 'claude') {
    // Add Gemini files
    const result = claudeToGemini(sourcePath, outputPath);

    // Also keep the original Claude files
    const skillPath = path.join(sourcePath, 'SKILL.md');
    if (fs.existsSync(skillPath) && sourcePath !== outputPath) {
      fs.copyFileSync(skillPath, path.join(outputPath, 'SKILL.md'));
    }

    return { ...result, universal: true };
  } else if (detection.platform === 'gemini') {
    // Add Claude files
    const result = geminiToClaude(sourcePath, outputPath);

    // Also keep the original Gemini files
    const extensionPath = path.join(sourcePath, 'gemini-extension.json');
    if (fs.existsSync(extensionPath) && sourcePath !== outputPath) {
      fs.copyFileSync(extensionPath, path.join(outputPath, 'gemini-extension.json'));
    }
    const geminiMdPath = path.join(sourcePath, 'GEMINI.md');
    if (fs.existsSync(geminiMdPath) && sourcePath !== outputPath) {
      fs.copyFileSync(geminiMdPath, path.join(outputPath, 'GEMINI.md'));
    }

    return { ...result, universal: true };
  }

  throw new Error(`Cannot determine platform type for ${sourcePath}`);
}

function analyze(dirPath) {
  const detection = detectPlatform(dirPath);
  const result = {
    path: dirPath,
    platform: detection.platform,
    scores: {
      claude: detection.claudeScore,
      gemini: detection.geminiScore
    },
    files: {
      claude: [],
      gemini: [],
      shared: []
    },
    metadata: {}
  };

  // Check for specific files
  const files = fs.readdirSync(dirPath);

  if (files.includes('SKILL.md')) {
    result.files.claude.push('SKILL.md');
    try {
      const { frontmatter } = parseSkillMd(path.join(dirPath, 'SKILL.md'));
      result.metadata.claude = frontmatter;
    } catch (e) {
      result.metadata.claudeError = e.message;
    }
  }

  if (files.includes('gemini-extension.json')) {
    result.files.gemini.push('gemini-extension.json');
    try {
      result.metadata.gemini = parseGeminiExtension(path.join(dirPath, 'gemini-extension.json'));
    } catch (e) {
      result.metadata.geminiError = e.message;
    }
  }

  if (files.includes('GEMINI.md')) result.files.gemini.push('GEMINI.md');
  if (files.includes('config.json')) result.files.claude.push('config.json');
  if (files.includes('executor.py')) result.files.claude.push('executor.py');
  if (files.includes('shared')) result.files.shared.push('shared/');
  if (files.includes('scripts')) result.files.claude.push('scripts/');
  if (files.includes('servers')) result.files.gemini.push('servers/');
  if (files.includes('commands')) result.files.gemini.push('commands/');

  // Conversion recommendations
  result.recommendations = [];

  if (detection.platform === 'claude') {
    result.recommendations.push('Can convert to Gemini with: node port.cjs <path> --to gemini');
    result.recommendations.push('Can make universal with: node port.cjs <path> --universal');
  } else if (detection.platform === 'gemini') {
    result.recommendations.push('Can convert to Claude with: node port.cjs <path> --to claude');
    result.recommendations.push('Can make universal with: node port.cjs <path> --universal');
  } else if (detection.platform === 'universal') {
    result.recommendations.push('Already supports both platforms');
  } else {
    result.recommendations.push('Cannot determine platform. Ensure SKILL.md or gemini-extension.json exists.');
  }

  return result;
}

function copyDir(src, dest) {
  fs.mkdirSync(dest, { recursive: true });
  const entries = fs.readdirSync(src, { withFileTypes: true });

  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);

    if (entry.isDirectory()) {
      copyDir(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

function escapeRegex(string) {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

