export async function expireStale(maxAgeHours = 72) {
  try {
    const now = Date.now();
    const maxAgeMs = maxAgeHours * 60 * 60 * 1000;

    // Get pending and deferred suggestions
    const pending = await getByStatus(['pending', 'deferred']);

    let expiredCount = 0;

    for (const entry of pending) {
      const createdAt = new Date(entry.created_at).getTime();
      const age = now - createdAt;

      if (age > maxAgeMs) {
        await updateStatus(entry.suggestion_id, 'expired');
        expiredCount++;
      }
    }

    if (expiredCount > 0) {
      console.log(`✓ Expired ${expiredCount} stale suggestions`);
    }

    return expiredCount;
  } catch (error) {
    console.error('Failed to expire stale suggestions:', error.message);
    return 0;
  }
}

function parseArgs(args) {
  const parsed = {
    source: null,
    framework: null,
    output: null,
    coverage: 80,
    help: false,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--help') {
      parsed.help = true;
    } else if (arg === '--source' && args[i + 1]) {
      parsed.source = args[++i];
    } else if (arg === '--framework' && args[i + 1]) {
      parsed.framework = args[++i];
    } else if (arg === '--output' && args[i + 1]) {
      parsed.output = args[++i];
    } else if (arg === '--coverage' && args[i + 1]) {
      parsed.coverage = parseInt(args[++i]);
    }
  }

  return parsed;
}

