export function parseHookOutput(rawResult, hookType) {
  if (!rawResult.stdout) {
    return {
      success: false,
      error: 'No stdout output from hook',
    };
  }

  try {
    const parsed = JSON.parse(rawResult.stdout);

    if (hookType === 'pretooluse') {
      return {
        success: true,
        type: 'pretooluse',
        decision: parsed.decision === 'allow' ? 'approve' : parsed.decision || 'approve',
        reason: parsed.reason || '',
        suggestion: parsed.suggestion || '',
        metadata: parsed.metadata || {},
      };
    } else if (hookType === 'posttooluse') {
      return {
        success: true,
        type: 'posttooluse',
        verification_verdict: parsed.verification_verdict || 'UNKNOWN',
        verification_passed: parsed.verification_passed || false,
        errors: parsed.errors || [],
        warnings: parsed.warnings || [],
        verification_steps: parsed.verification_steps || {},
      };
    }

    return {
      success: true,
      type: 'unknown',
      data: parsed,
    };
  } catch (error) {
    // Fallback to text parsing
    return {
      success: false,
      error: 'Failed to parse JSON output',
      raw_output: rawResult.stdout,
      parse_error: error.message,
    };
  }
}

function normalizeDecision(decision) {
  const raw = String(decision || '')
    .trim()
    .toLowerCase();
  if (!raw) return 'approve';
  if (raw === 'approve' || raw === 'allow') return 'approve';
  if (raw === 'block' || raw === 'deny') return 'block';
  return raw;
}

function isPlainObject(value) {
  return value != null && typeof value === 'object' && !Array.isArray(value);
}

function matchesSubset(actual, expected) {
  if (expected === undefined) return true;

  if (Array.isArray(expected)) {
    if (!Array.isArray(actual)) return false;
    if (expected.length !== actual.length) return false;
    for (let i = 0; i < expected.length; i++) {
      if (!matchesSubset(actual[i], expected[i])) return false;
    }
    return true;
  }

  if (isPlainObject(expected)) {
    if (!isPlainObject(actual)) return false;
    for (const [key, value] of Object.entries(expected)) {
      if (!matchesSubset(actual[key], value)) return false;
    }
    return true;
  }

  return actual === expected;
}

