export class EntityA2AConverter {
  /**
   * @param {object} options - Configuration options
   */
  constructor(options = {}) {
    this.schema = options.schema || ENTITY_DATA_PART_SCHEMA;
    this.version = options.version || '1.0.0';
  }

  /**
   * Convert entities to A2A DataPart
   *
   * @param {Array} entities - Entity objects
   * @returns {Promise<object>} A2A DataPart
   */
  async toA2ADataPart(entities) {
    const startTime = Date.now();

    if (!Array.isArray(entities)) {
      throw new Error('Entities must be an array');
    }

    // Convert entities to A2A format
    const a2aEntities = entities.map(entity => this.convertEntityToA2AFormat(entity));

    // Build DataPart
    const dataPart = {
      data: {
        entities: a2aEntities,
        version: this.version,
        timestamp: new Date().toISOString(),
      },
    };

    // Validate schema
    const validation = this.validateEntityDataPart(dataPart);
    if (!validation.valid) {
      throw new Error(`Entity DataPart validation failed: ${validation.errors.join(', ')}`);
    }

    const duration = Date.now() - startTime;

    console.log(
      `[Entity-A2A Converter] Converted ${entities.length} entities to DataPart in ${duration}ms`
    );

    return dataPart;
  }

  /**
   * Convert A2A DataPart to entities
   *
   * @param {object} dataPart - A2A DataPart
   * @returns {Promise<Array>} Entity objects
   */
  async fromA2ADataPart(dataPart) {
    const startTime = Date.now();

    if (!dataPart || !dataPart.data) {
      throw new Error('Invalid DataPart: data object required');
    }

    // Validate schema
    const validation = this.validateEntityDataPart(dataPart);
    if (!validation.valid) {
      throw new Error(`Entity DataPart validation failed: ${validation.errors.join(', ')}`);
    }

    // Extract entities
    const entities = (dataPart.data.entities || []).map(a2aEntity =>
      this.convertA2AFormatToEntity(a2aEntity)
    );

    const duration = Date.now() - startTime;

    console.log(
      `[Entity-A2A Converter] Converted DataPart to ${entities.length} entities in ${duration}ms`
    );

    return entities;
  }

  /**
   * Convert entity object to A2A format
   *
   * @param {object} entity - Legacy entity object
   * @returns {object} A2A entity format
   */
  convertEntityToA2AFormat(entity) {
    return {
      entityId: entity.entityId || entity.id || randomUUID(),
      entityType: entity.entityType || entity.type || 'unknown',
      name: entity.name || entity.value || '',
      attributes: this.convertAttributes(entity.attributes || {}),
      relationships: this.convertRelationships(entity.relationships || []),
      mentions: entity.mentions || entity.occurrence_count || 1,
      metadata: {
        confidence: entity.confidence || 1.0,
        context: entity.context || null,
        firstSeen: entity.first_seen || entity.created_at,
        lastSeen: entity.last_seen || entity.updated_at,
        isActive: entity.is_active !== undefined ? entity.is_active : true,
      },
    };
  }

  /**
   * Convert A2A format to entity object
   *
   * @param {object} a2aEntity - A2A entity format
   * @returns {object} Legacy entity object
   */
  convertA2AFormatToEntity(a2aEntity) {
    return {
      id: a2aEntity.entityId,
      type: a2aEntity.entityType,
      value: a2aEntity.name,
      attributes: this.convertA2AAttributes(a2aEntity.attributes || {}),
      relationships: this.convertA2ARelationships(a2aEntity.relationships || []),
      occurrence_count: a2aEntity.mentions || 1,
      confidence: a2aEntity.metadata?.confidence || 1.0,
      context: a2aEntity.metadata?.context || null,
      first_seen: a2aEntity.metadata?.firstSeen,
      last_seen: a2aEntity.metadata?.lastSeen,
      is_active: a2aEntity.metadata?.isActive !== undefined ? a2aEntity.metadata.isActive : true,
    };
  }

  /**
   * Convert entity attributes to A2A format
   *
   * @param {object} attributes - Legacy attributes
   * @returns {object} A2A attributes
   */
  convertAttributes(attributes) {
    // Attributes are already key-value pairs
    // Just ensure they're serializable
    const converted = {};

    for (const [key, value] of Object.entries(attributes)) {
      if (typeof value === 'object' && value !== null) {
        converted[key] = JSON.stringify(value);
      } else {
        converted[key] = String(value);
      }
    }

    return converted;
  }

  /**
   * Convert A2A attributes to legacy format
   *
   * @param {object} a2aAttributes - A2A attributes
   * @returns {object} Legacy attributes
   */
  convertA2AAttributes(a2aAttributes) {
    const converted = {};

    for (const [key, value] of Object.entries(a2aAttributes)) {
      try {
        // Try to parse JSON strings
        converted[key] = JSON.parse(value);
      } catch {
        // Keep as string if not JSON
        converted[key] = value;
      }
    }

    return converted;
  }

  /**
   * Convert entity relationships to A2A format
   *
   * @param {Array} relationships - Legacy relationships
   * @returns {Array} A2A relationships
   */
  convertRelationships(relationships) {
    return relationships.map(rel => ({
      relatedEntityId: rel.entity_id_2 || rel.relatedEntityId,
      relationshipType: rel.relationship_type || rel.relationshipType,
      strength: rel.strength || 1.0,
      context: rel.context || null,
    }));
  }

  /**
   * Convert A2A relationships to legacy format
   *
   * @param {Array} a2aRelationships - A2A relationships
   * @returns {Array} Legacy relationships
   */
  convertA2ARelationships(a2aRelationships) {
    return a2aRelationships.map(rel => ({
      entity_id_2: rel.relatedEntityId,
      relationship_type: rel.relationshipType,
      strength: rel.strength || 1.0,
      context: rel.context || null,
    }));
  }

  /**
   * Validate entity DataPart against schema
   *
   * @param {object} dataPart - A2A DataPart
   * @returns {object} Validation result { valid: boolean, errors: string[] }
   */
  validateEntityDataPart(dataPart) {
    const errors = [];

    if (!dataPart) {
      return { valid: false, errors: ['DataPart is null or undefined'] };
    }

    if (!dataPart.data) {
      errors.push('Missing required field: data');
      return { valid: false, errors }; // Early return to prevent accessing undefined
    }

    if (!dataPart.data.entities) {
      errors.push('Missing required field: data.entities');
    } else if (!Array.isArray(dataPart.data.entities)) {
      errors.push('data.entities must be an array');
    } else {
      // Validate each entity
      dataPart.data.entities.forEach((entity, index) => {
        if (!entity.entityId) {
          errors.push(`Entity ${index}: missing entityId`);
        }
        if (!entity.entityType) {
          errors.push(`Entity ${index}: missing entityType`);
        }
        if (!entity.name) {
          errors.push(`Entity ${index}: missing name`);
        }
      });
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Merge entity DataParts
   *
   * Combines multiple DataParts into a single DataPart, deduplicating entities
   *
   * @param {Array} dataParts - Array of A2A DataParts
   * @returns {Promise<object>} Merged DataPart
   */
  async mergeDataParts(dataParts) {
    const startTime = Date.now();

    if (!Array.isArray(dataParts)) {
      throw new Error('dataParts must be an array');
    }

    const entityMap = new Map();

    // Merge entities by ID
    for (const dataPart of dataParts) {
      if (!dataPart.data || !dataPart.data.entities) {
        continue;
      }

      for (const entity of dataPart.data.entities) {
        const existingEntity = entityMap.get(entity.entityId);

        if (existingEntity) {
          // Merge mentions
          existingEntity.mentions += entity.mentions || 1;

          // Merge attributes
          existingEntity.attributes = {
            ...existingEntity.attributes,
            ...entity.attributes,
          };

          // Merge relationships
          const relIds = new Set(existingEntity.relationships.map(r => r.relatedEntityId));
          for (const rel of entity.relationships || []) {
            if (!relIds.has(rel.relatedEntityId)) {
              existingEntity.relationships.push(rel);
              relIds.add(rel.relatedEntityId);
            }
          }
        } else {
          entityMap.set(entity.entityId, { ...entity });
        }
      }
    }

    // Build merged DataPart
    const mergedDataPart = {
      data: {
        entities: Array.from(entityMap.values()),
        version: this.version,
        timestamp: new Date().toISOString(),
      },
    };

    const duration = Date.now() - startTime;

    console.log(
      `[Entity-A2A Converter] Merged ${dataParts.length} DataParts into ${mergedDataPart.data.entities.length} entities in ${duration}ms`
    );

    return mergedDataPart;
  }

export class ExternalAgentDiscovery {
  /**
   * @param {object} options - Configuration options
   */
  constructor(options = {}) {
    this.featureFlags = options.featureFlags || {
      external_federation: process.env.EXTERNAL_FEDERATION === 'true' || false,
    };
    this.timeout = options.timeout || DEFAULT_TIMEOUT_MS;
    this.cache = cache;
  }

  /**
   * Discover external agent by fetching AgentCard
   *
   * @param {string} url - External agent base URL
   * @param {object} options - Discovery options
   * @returns {Promise<object>} AgentCard
   */
  async discoverAgent(url, options = {}) {
    const startTime = Date.now();

    const enabled =
      this.featureFlags.isEnabled?.('external_federation') ?? this.featureFlags.external_federation;
    if (!enabled) {
      throw new Error('external_federation feature flag is disabled');
    }

    // Normalize URL
    const normalizedUrl = this.normalizeUrl(url);

    // Check cache first
    const cached = this.getCachedAgentCard(normalizedUrl);
    if (cached && !options.forceRefresh) {
      const duration = Date.now() - startTime;
      console.log(`[External Discovery] Cache hit for ${normalizedUrl} (${duration}ms)`);
      return cached;
    }

    // Fetch AgentCard from external agent
    const agentCardUrl = this.buildAgentCardUrl(normalizedUrl);

    try {
      const response = await this.fetchWithTimeout(agentCardUrl, options.timeout || this.timeout);

      if (!response.ok) {
        throw new Error(
          `Failed to fetch AgentCard: HTTP ${response.status} ${response.statusText}`
        );
      }

      const contentType = response.headers.get('content-type');
      if (!contentType || !contentType.includes('application/json')) {
        throw new Error(`Invalid content type: expected application/json, got ${contentType}`);
      }

      const data = await response.json();

      // Extract AgentCard from response
      const agentCard = data.agents ? data.agents[0] : data;

      // Validate AgentCard
      const validation = this.validateExternalAgentCard(agentCard);
      if (!validation.valid) {
        throw new Error(`Invalid AgentCard: ${validation.errors.join(', ')}`);
      }

      // Add discovery metadata
      agentCard._discovery = {
        source_url: normalizedUrl,
        discovered_at: new Date().toISOString(),
        discovery_time_ms: Date.now() - startTime,
      };

      // Cache AgentCard
      this.cacheAgentCard(normalizedUrl, agentCard);

      const duration = Date.now() - startTime;
      console.log(
        `[External Discovery] Discovered agent ${agentCard.name} from ${normalizedUrl} (${duration}ms)`
      );

      return agentCard;
    } catch (error) {
      console.error(`[External Discovery] Failed to discover ${normalizedUrl}:`, error);
      throw new Error(`External agent discovery failed: ${error.message}`);
    }
  }

  /**
   * Get cached AgentCard
   *
   * @param {string} url - External agent URL
   * @returns {object|null} Cached AgentCard or null
   */
  getCachedAgentCard(url) {
    const normalizedUrl = this.normalizeUrl(url);
    const cached = this.cache.get(normalizedUrl);

    if (!cached) {
      return null;
    }

    const age = Date.now() - cached.timestamp;
    if (age >= CACHE_TTL_MS) {
      // Cache expired
      this.cache.delete(normalizedUrl);
      return null;
    }

    return cached.agentCard;
  }

  /**
   * Cache AgentCard
   *
   * @param {string} url - External agent URL
   * @param {object} agentCard - AgentCard to cache
   */
  cacheAgentCard(url, agentCard) {
    const normalizedUrl = this.normalizeUrl(url);

    this.cache.set(normalizedUrl, {
      agentCard,
      timestamp: Date.now(),
    });
  }

  /**
   * Validate external AgentCard structure
   *
   * @param {object} agentCard - AgentCard to validate
   * @returns {object} Validation result
   */
  validateExternalAgentCard(agentCard) {
    const errors = [];

    if (!agentCard) {
      return { valid: false, errors: ['AgentCard is null or undefined'] };
    }

    // Required fields per A2A v0.3.0
    const required = [
      'protocol_version',
      'name',
      'description',
      'version',
      'supported_interfaces',
      'capabilities',
      'default_input_modes',
      'default_output_modes',
      'skills',
    ];

    for (const field of required) {
      if (agentCard[field] === undefined || agentCard[field] === null) {
        errors.push(`Missing required field: ${field}`);
      }
    }

    // Validate array fields
    if (agentCard.supported_interfaces && !Array.isArray(agentCard.supported_interfaces)) {
      errors.push('supported_interfaces must be an array');
    }

    if (agentCard.skills && !Array.isArray(agentCard.skills)) {
      errors.push('skills must be an array');
    }

    // Validate capabilities
    if (agentCard.capabilities && typeof agentCard.capabilities !== 'object') {
      errors.push('capabilities must be an object');
    }

    // Validate protocol version
    if (agentCard.protocol_version && !agentCard.protocol_version.startsWith('0.3')) {
      errors.push(`Unsupported protocol version: ${agentCard.protocol_version} (expected 0.3.x)`);
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * List all discovered external agents
   *
   * @param {object} filters - Filter options
   * @returns {Array} External AgentCards
   */
  listExternalAgents(filters = {}) {
    const agents = Array.from(this.cache.values())
      .map(entry => entry.agentCard)
      .filter(card => {
        // Filter by capability
        if (filters.capability && !card.capabilities[filters.capability]) {
          return false;
        }

        // Filter by skill
        if (filters.skill) {
          const hasSkill = card.skills.some(
            s => s.name === filters.skill || s.id === filters.skill
          );
          if (!hasSkill) return false;
        }

        return true;
      });

    // Apply limit
    if (filters.limit) {
      return agents.slice(0, filters.limit);
    }

    return agents;
  }

  /**
   * Clear discovery cache
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get cache statistics
   *
   * @returns {object} Cache stats
   */
  getCacheStats() {
    const now = Date.now();
    const entries = Array.from(this.cache.entries());

    return {
      size: this.cache.size,
      entries: entries.map(([url, entry]) => ({
        url,
        agent_name: entry.agentCard.name,
        age_ms: now - entry.timestamp,
        expired: now - entry.timestamp >= CACHE_TTL_MS,
      })),
      ttl_ms: CACHE_TTL_MS,
    };
  }

  /**
   * Normalize URL for consistency
   *
   * @param {string} url - URL to normalize
   * @returns {string} Normalized URL
   */
  normalizeUrl(url) {
    // Remove trailing slash
    return url.replace(/\/$/, '');
  }

  /**
   * Build AgentCard endpoint URL
   *
   * @param {string} baseUrl - Agent base URL
   * @returns {string} AgentCard endpoint URL
   */
  buildAgentCardUrl(baseUrl) {
    return `${baseUrl}/.well-known/agent-card.json`;
  }

  /**
   * Fetch with timeout
   *
   * @param {string} url - URL to fetch
   * @param {number} timeout - Timeout in ms
   * @returns {Promise<Response>} Fetch response
   */
  async fetchWithTimeout(url, timeout) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url, {
        signal: controller.signal,
        headers: {
          Accept: 'application/json',
          'User-Agent': 'LLM-Rules-A2A/1.0',
        },
      });
      return response;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  /**
   * Discover multiple agents in parallel
   *
   * @param {Array<string>} urls - Agent URLs
   * @param {object} options - Discovery options
   * @returns {Promise<Array>} Discovered AgentCards
   */
  async discoverMultipleAgents(urls, options = {}) {
    const startTime = Date.now();

    const results = await Promise.allSettled(urls.map(url => this.discoverAgent(url, options)));

    const discovered = [];
    const failed = [];

    results.forEach((result, idx) => {
      if (result.status === 'fulfilled') {
        discovered.push(result.value);
      } else {
        failed.push({
          url: urls[idx],
          error: result.reason.message,
        });
      }
    });

    const duration = Date.now() - startTime;

    console.log(
      `[External Discovery] Discovered ${discovered.length}/${urls.length} agents in ${duration}ms`
    );

    if (failed.length > 0) {
      console.warn('[External Discovery] Failed discoveries:', failed);
    }

    return { discovered, failed, duration };
  }

  /**
   * Check if agent supports capability
   *
   * @param {string} url - Agent URL
   * @param {string} capability - Capability name
   * @returns {Promise<boolean>} True if supported
   */
  async supportsCapability(url, capability) {
    const agentCard = await this.discoverAgent(url);
    return agentCard.capabilities[capability] === true;
  }

export function resetInstance() {
  instance = null;
  cache.clear();
}

function setupFetchMock() {
  fetchMock = {
    calls: [],
    responses: new Map(),
  };

  global.fetch = async (url, options) => {
    fetchMock.calls.push({ url, options });

    const response = fetchMock.responses.get(url);
    if (!response) {
      throw new Error(`No mock response for ${url}`);
    }

    return response;
  };
}

function teardownFetchMock() {
  global.fetch = originalFetch;
  fetchMock = null;
}

export class FederationManager {
  /**
   * @param {object} options - Configuration options
   */
  constructor(options = {}) {
    this.featureFlags = options.featureFlags || {
      external_federation: process.env.EXTERNAL_FEDERATION === 'true' || false,
    };

    // Get component instances
    this.discovery = options.discovery || getExternalAgentDiscovery(options);
    this.pushHandler = options.pushHandler || getPushNotificationHandler(options);
    this.streamingHandler = options.streamingHandler || getStreamingHandler(options);

    // Federated task tracking
    this.federatedTasks = new Map();
  }

  /**
   * Check if federation is enabled
   *
   * @returns {boolean} True if enabled
   */
  isFederationEnabled() {
    const enabled =
      this.featureFlags.isEnabled?.('external_federation') ?? this.featureFlags.external_federation;
    return enabled === true;
  }

  /**
   * Execute task on external agent
   *
   * @param {string} agentUrl - External agent URL
   * @param {object} message - A2A Message
   * @param {object} options - Execution options
   * @returns {Promise<object>} Task result
   */
  async executeExternalTask(agentUrl, message, options = {}) {
    const startTime = Date.now();

    if (!this.isFederationEnabled()) {
      throw new Error('external_federation feature flag is disabled');
    }

    // Step 1: Discover external agent
    console.log(`[Federation] Discovering agent at ${agentUrl}`);
    const agentCard = await this.discovery.discoverAgent(agentUrl, options);

    // Step 2: Validate agent capabilities
    if (!agentCard.supported_interfaces.includes('a2a')) {
      throw new Error(`Agent at ${agentUrl} does not support A2A interface`);
    }

    // Step 3: Send message to external agent
    console.log(`[Federation] Sending message to ${agentCard.name}`);
    const task = await this.sendMessageToExternalAgent(agentUrl, agentCard, message, options);

    // Step 4: Set up streaming if supported
    if (agentCard.capabilities.streaming && options.streaming !== false) {
      console.log(`[Federation] Setting up streaming for task ${task.id}`);
      await this.setupStreamingForTask(agentUrl, task, options);
    }

    // Step 5: Set up push notifications if supported
    if (agentCard.capabilities.push_notifications && options.callbackUrl) {
      console.log(`[Federation] Configuring push notifications for task ${task.id}`);
      await this.setupPushNotificationsForTask(agentUrl, task, options.callbackUrl, options);
    }

    // Track federated task
    this.federatedTasks.set(task.id, {
      task_id: task.id,
      agent_url: agentUrl,
      agent_name: agentCard.name,
      started_at: new Date().toISOString(),
      status: task.state,
      capabilities_used: {
        streaming: agentCard.capabilities.streaming && options.streaming !== false,
        push_notifications: agentCard.capabilities.push_notifications && !!options.callbackUrl,
      },
    });

    const duration = Date.now() - startTime;

    console.log(`[Federation] Task ${task.id} initiated on ${agentCard.name} (${duration}ms)`);

    return task;
  }

  /**
   * Send message to external agent
   *
   * @param {string} agentUrl - External agent URL
   * @param {object} agentCard - AgentCard
   * @param {object} message - A2A Message
   * @param {object} options - Send options
   * @returns {Promise<object>} Task
   */
  async sendMessageToExternalAgent(agentUrl, agentCard, message, options = {}) {
    // Build SendMessage request
    const request = {
      message,
      session_id: options.sessionId || `session-${randomUUID()}`,
    };

    if (options.taskId) {
      request.task_id = options.taskId;
    }

    try {
      // Send to external agent's SendMessage endpoint
      const endpoint = agentCard.url || agentUrl;
      const response = await fetch(`${endpoint}/sendMessage`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        body: JSON.stringify(request),
      });

      if (!response.ok) {
        throw new Error(`External agent returned HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      // Validate task response
      if (!data.task || !data.task.id) {
        throw new Error('Invalid task response from external agent');
      }

      return data.task;
    } catch (error) {
      console.error(`[Federation] Failed to send message to ${agentUrl}:`, error);
      throw new Error(`External task execution failed: ${error.message}`);
    }
  }

  /**
   * Set up streaming for external task
   *
   * @param {string} agentUrl - External agent URL
   * @param {object} task - Task object
   * @param {object} options - Streaming options
   * @returns {Promise<object>} Stream context
   */
  async setupStreamingForTask(agentUrl, task, options = {}) {
    // Create message for streaming
    const streamMessage = {
      messageId: `msg-${randomUUID()}`,
      taskId: task.id,
      role: Role.USER,
      parts: [{ text: 'Stream task updates' }],
    };

    // Start streaming
    const stream = this.streamingHandler.startStreamingMessage(
      streamMessage,
      event => {
        // Handle streaming events
        if (options.onStreamEvent) {
          options.onStreamEvent(event);
        }

        // Update federated task status
        if (event.type === 'task_status_update' && event.task) {
          const federatedTask = this.federatedTasks.get(task.id);
          if (federatedTask) {
            federatedTask.status = event.task.state;
            federatedTask.last_update_at = new Date().toISOString();
          }
        }
      },
      options
    );

    return stream;
  }

  /**
   * Set up push notifications for external task
   *
   * @param {string} agentUrl - External agent URL
   * @param {object} task - Task object
   * @param {string} callbackUrl - Webhook callback URL
   * @param {object} options - Notification options
   * @returns {object} Push notification config
   */
  async setupPushNotificationsForTask(agentUrl, task, callbackUrl, options = {}) {
    // Configure push notification
    const config = this.pushHandler.configurePushNotification(task.id, callbackUrl, options);

    // Send subscription request to external agent
    try {
      const endpoint = agentUrl;
      const response = await fetch(`${endpoint}/subscribeToTask`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          task_id: task.id,
          callback_url: callbackUrl,
          events: config.events,
        }),
      });

      if (!response.ok) {
        console.warn(
          `[Federation] Failed to subscribe to task ${task.id} at ${agentUrl}: HTTP ${response.status}`
        );
      }
    } catch (error) {
      console.warn(`[Federation] Failed to subscribe to task ${task.id}:`, error);
    }

    return config;
  }

  /**
   * Get list of federated agents
   *
   * @param {object} filters - Filter options
   * @returns {Array} AgentCards
   */
  getFederatedAgents(filters = {}) {
    return this.discovery.listExternalAgents(filters);
  }

  /**
   * Get federated task status
   *
   * @param {string} taskId - Task ID
   * @returns {object|null} Federated task info
   */
  getFederatedTask(taskId) {
    return this.federatedTasks.get(taskId) || null;
  }

  /**
   * List all federated tasks
   *
   * @param {object} filters - Filter options
   * @returns {Array} Federated tasks
   */
  listFederatedTasks(filters = {}) {
    let tasks = Array.from(this.federatedTasks.values());

    // Filter by agent URL
    if (filters.agent_url) {
      tasks = tasks.filter(t => t.agent_url === filters.agent_url);
    }

    // Filter by status
    if (filters.status) {
      tasks = tasks.filter(t => t.status === filters.status);
    }

    // Apply limit
    if (filters.limit) {
      tasks = tasks.slice(0, filters.limit);
    }

    return tasks;
  }

  /**
   * Get federation statistics
   *
   * @returns {object} Federation stats
   */
  getFederationStats() {
    const tasks = Array.from(this.federatedTasks.values());
    const agents = this.discovery.listExternalAgents();

    return {
      total_external_agents: agents.length,
      total_federated_tasks: tasks.length,
      streaming_enabled: tasks.filter(t => t.capabilities_used.streaming).length,
      push_notifications_enabled: tasks.filter(t => t.capabilities_used.push_notifications).length,
      discovery_cache_size: this.discovery.cache.size,
      active_streams: this.streamingHandler.activeStreams.size,
    };
  }

  /**
   * Discover and execute task on best matching agent
   *
   * @param {Array<string>} agentUrls - Candidate agent URLs
   * @param {object} message - A2A Message
   * @param {object} criteria - Selection criteria
   * @param {object} options - Execution options
   * @returns {Promise<object>} Task result
   */
  async executeOnBestAgent(agentUrls, message, criteria = {}, options = {}) {
    const startTime = Date.now();

    // Discover all agents in parallel
    const discoveryResult = await this.discovery.discoverMultipleAgents(agentUrls, options);

    if (discoveryResult.discovered.length === 0) {
      throw new Error('No agents discovered successfully');
    }

    // Score agents based on criteria
    const scoredAgents = discoveryResult.discovered.map(agentCard => {
      let score = 0;

      // Score based on capabilities
      if (criteria.streaming && agentCard.capabilities.streaming) {
        score += 10;
      }

      if (criteria.push_notifications && agentCard.capabilities.push_notifications) {
        score += 10;
      }

      // Score based on skills
      if (criteria.required_skills) {
        const matchingSkills = agentCard.skills.filter(skill =>
          criteria.required_skills.includes(skill.name)
        );
        score += matchingSkills.length * 5;
      }

      return { agentCard, score };
    });

    // Sort by score
    scoredAgents.sort((a, b) => b.score - a.score);

    const bestAgent = scoredAgents[0].agentCard;

    console.log(`[Federation] Selected ${bestAgent.name} (score: ${scoredAgents[0].score})`);

    // Execute task on best agent
    const task = await this.executeExternalTask(bestAgent._discovery.source_url, message, options);

    const duration = Date.now() - startTime;

    console.log(`[Federation] Task execution with agent selection completed (${duration}ms)`);

    return {
      task,
      selected_agent: bestAgent,
      candidates: scoredAgents.length,
      selection_time_ms: duration,
    };
  }

  /**
   * Clear federation state (for testing)
   */
  clearFederation() {
    this.federatedTasks.clear();
    this.discovery.clearCache();
    this.pushHandler.clearPushNotifications();
    this.streamingHandler.clearStreams();
  }

export function resetInstance() {
  if (instance) {
    instance.clearFederation();
  }
  instance = null;
}

function setupFetchMock() {
  fetchMock = {
    calls: [],
    responses: new Map(),
  };

  global.fetch = async (url, options) => {
    fetchMock.calls.push({ url, options });

    const response = fetchMock.responses.get(url);
    if (!response) {
      // Default response
      return {
        ok: true,
        status: 200,
        headers: new Map([['content-type', 'application/json']]),
        json: async () => ({}),
      };
    }

    return response;
  };
}

function teardownFetchMock() {
  global.fetch = originalFetch;
  fetchMock = null;
}

export class MemoryA2ABridge {
  /**
   * @param {object} options - Configuration options
   */
  constructor(options = {}) {
    this.memoryHandoffService = options.memoryHandoffService;
    this.entityConverter = options.entityConverter;
    this.featureFlags = options.featureFlags || FEATURE_FLAGS;
  }

  /**
   * Convert legacy memory handoff to A2A Artifact
   *
   * @param {object} handoff - Legacy memory handoff object
   * @returns {Promise<object>} A2A Artifact
   */
  async toA2AArtifact(handoff) {
    const startTime = Date.now();

    if (!this.featureFlags.memory_a2a_bridge) {
      throw new Error('memory_a2a_bridge feature flag is disabled');
    }

    // Validate input
    if (!handoff || !handoff.memories) {
      throw new Error('Invalid handoff: memories required');
    }

    // Convert memories to TextPart
    const memoryParts = await this.convertMemoriesToParts(handoff.memories);

    // Convert entities to DataPart (if present)
    const entityParts =
      handoff.entities && handoff.entities.length > 0
        ? [await this.convertEntitiesToDataPart(handoff.entities)]
        : [];

    // Build A2A Artifact
    const artifact = {
      artifactId: handoff.handoffId || `artifact-handoff-${randomUUID()}`,
      name: 'memory-handoff',
      parts: [...memoryParts, ...entityParts],
      metadata: {
        relevanceScore: handoff.relevanceScore || 0,
        tokenBudget: handoff.tokenBudget || 0,
        sourceAgentId: handoff.sourceAgentId,
        targetAgentId: handoff.targetAgentId,
        conversionDuration: Date.now() - startTime,
        format: 'a2a',
        version: '1.0.0',
      },
    };

    console.log(
      `[Memory-A2A Bridge] Converted handoff to A2A Artifact in ${Date.now() - startTime}ms`
    );

    return artifact;
  }

  /**
   * Convert A2A Artifact to legacy memory handoff
   *
   * @param {object} artifact - A2A Artifact
   * @returns {Promise<object>} Legacy memory handoff
   */
  async fromA2AArtifact(artifact) {
    const startTime = Date.now();

    if (!this.featureFlags.memory_a2a_bridge) {
      throw new Error('memory_a2a_bridge feature flag is disabled');
    }

    // Validate input
    if (!artifact || !artifact.parts || !Array.isArray(artifact.parts)) {
      throw new Error('Invalid artifact: parts array required');
    }

    // Extract TextParts → memories
    const memories = await this.convertPartsToMemories(artifact.parts.filter(p => p.text));

    // Extract DataParts → entities
    const entities = await this.convertDataPartToEntities(
      artifact.parts.find(p => p.data && p.data.entities)
    );

    // Build legacy handoff
    const handoff = {
      handoffId: artifact.artifactId,
      memories,
      entities: entities || [],
      relevanceScore: artifact.metadata?.relevanceScore || 0,
      tokenBudget: artifact.metadata?.tokenBudget || 0,
      sourceAgentId: artifact.metadata?.sourceAgentId,
      targetAgentId: artifact.metadata?.targetAgentId,
      metadata: {
        conversionDuration: Date.now() - startTime,
        originalFormat: artifact.metadata?.format || 'a2a',
      },
    };

    console.log(
      `[Memory-A2A Bridge] Converted A2A Artifact to legacy handoff in ${Date.now() - startTime}ms`
    );

    return handoff;
  }

  /**
   * Convert memories to A2A TextParts
   *
   * @param {Array} memories - Memory objects
   * @returns {Promise<Array>} A2A TextParts
   */
  async convertMemoriesToParts(memories) {
    const startTime = Date.now();

    if (!Array.isArray(memories)) {
      throw new Error('Memories must be an array');
    }

    // Group memories by tier for better organization
    const textContent = memories
      .map(memory => {
        const roleLabel = memory.role || 'unknown';
        const timestamp = memory.timestamp ? new Date(memory.timestamp).toISOString() : 'unknown';
        const tier = memory.tier || 'conversation';
        const relevance = memory.relevanceScore
          ? `relevance: ${memory.relevanceScore.toFixed(2)}`
          : '';

        return `[${roleLabel}] [${tier}] [${timestamp}] ${relevance}\n${memory.content}`;
      })
      .join('\n\n---\n\n');

    const duration = Date.now() - startTime;

    console.log(
      `[Memory-A2A Bridge] Converted ${memories.length} memories to TextPart in ${duration}ms`
    );

    return [
      {
        text: textContent,
      },
    ];
  }

  /**
   * Convert entities to A2A DataPart
   *
   * @param {Array} entities - Entity objects
   * @returns {Promise<object>} A2A DataPart
   */
  async convertEntitiesToDataPart(entities) {
    const startTime = Date.now();

    if (!Array.isArray(entities)) {
      throw new Error('Entities must be an array');
    }

    // Use EntityA2AConverter if available
    if (this.entityConverter) {
      return await this.entityConverter.toA2ADataPart(entities);
    }

    // Fallback: basic conversion
    const dataPart = {
      data: {
        entities: entities.map(entity => ({
          entityId: entity.entityId || entity.id,
          entityType: entity.entityType || entity.type,
          name: entity.name || entity.value,
          attributes: entity.attributes || {},
          relationships: entity.relationships || [],
          mentions: entity.mentions || entity.occurrence_count || 1,
        })),
      },
    };

    const duration = Date.now() - startTime;

    console.log(
      `[Memory-A2A Bridge] Converted ${entities.length} entities to DataPart in ${duration}ms`
    );

    return dataPart;
  }

  /**
   * Convert A2A TextParts to memories
   *
   * @param {Array} parts - A2A TextParts
   * @returns {Promise<Array>} Memory objects
   */
  async convertPartsToMemories(parts) {
    const startTime = Date.now();

    if (!Array.isArray(parts)) {
      throw new Error('Parts must be an array');
    }

    const memories = [];

    for (const part of parts) {
      if (!part.text) {
        continue;
      }

      // Parse structured text back into memory objects
      const sections = part.text.split('\n\n---\n\n');

      for (const section of sections) {
        const match = section.match(
          /^\[([^\]]+)\] \[([^\]]+)\] \[([^\]]+)\] ?(relevance: ([0-9.]+))?\n(.+)$/s
        );

        if (match) {
          const [, role, tier, timestamp, , relevanceScore, content] = match;

          memories.push({
            role,
            tier,
            timestamp,
            relevanceScore: relevanceScore ? parseFloat(relevanceScore) : undefined,
            content: content.trim(),
          });
        } else {
          // Fallback: treat as plain text memory
          memories.push({
            role: 'unknown',
            tier: 'conversation',
            timestamp: new Date().toISOString(),
            content: section.trim(),
          });
        }
      }
    }

    const duration = Date.now() - startTime;

    console.log(
      `[Memory-A2A Bridge] Converted ${parts.length} TextParts to ${memories.length} memories in ${duration}ms`
    );

    return memories;
  }

  /**
   * Convert A2A DataPart to entities
   *
   * @param {object} dataPart - A2A DataPart
   * @returns {Promise<Array>} Entity objects
   */
  async convertDataPartToEntities(dataPart) {
    const startTime = Date.now();

    if (!dataPart || !dataPart.data) {
      return [];
    }

    // Use EntityA2AConverter if available
    if (this.entityConverter) {
      return await this.entityConverter.fromA2ADataPart(dataPart);
    }

    // Fallback: basic conversion
    const entities = (dataPart.data.entities || []).map(entity => ({
      id: entity.entityId,
      type: entity.entityType,
      value: entity.name,
      attributes: entity.attributes || {},
      relationships: entity.relationships || [],
      occurrence_count: entity.mentions || 1,
    }));

    const duration = Date.now() - startTime;

    console.log(
      `[Memory-A2A Bridge] Converted DataPart to ${entities.length} entities in ${duration}ms`
    );

    return entities;
  }

  /**
   * Prepare handoff in A2A format
   *
   * Wrapper around memoryHandoffService.prepareHandoff that converts to A2A
   *
   * @param {object} params - Handoff parameters
   * @returns {Promise<object>} A2A Artifact
   */
  async prepareA2AHandoff(params) {
    if (!this.memoryHandoffService) {
      throw new Error('memoryHandoffService not configured');
    }

    if (!this.featureFlags.memory_a2a_bridge) {
      throw new Error('memory_a2a_bridge feature flag is disabled');
    }

    // Prepare handoff using existing service
    const handoff = await this.memoryHandoffService.prepareHandoff(params);

    // Convert to A2A format
    const artifact = await this.toA2AArtifact({
      handoffId: handoff.handoffId,
      memories: handoff.context?.memories || [],
      entities: handoff.context?.entities || [],
      relevanceScore: handoff.metadata?.relevanceScore,
      tokenBudget: handoff.metadata?.tokenBudget,
      sourceAgentId: params.sourceAgentId,
      targetAgentId: params.targetAgentId,
    });

    return artifact;
  }

  /**
   * Apply A2A handoff context
   *
   * Converts A2A Artifact to legacy format and applies via memoryHandoffService
   *
   * @param {object} artifact - A2A Artifact
   * @returns {Promise<object>} Applied handoff result
   */
  async applyA2AHandoff(artifact) {
    if (!this.memoryHandoffService) {
      throw new Error('memoryHandoffService not configured');
    }

    if (!this.featureFlags.memory_a2a_bridge) {
      throw new Error('memory_a2a_bridge feature flag is disabled');
    }

    // Convert from A2A format
    const handoff = await this.fromA2AArtifact(artifact);

    // Apply handoff using existing service
    const result = await this.memoryHandoffService.applyHandoffContext(handoff.handoffId);

    return {
      ...result,
      handoff,
    };
  }

export class A2AMessageWrapper {
  /**
   * @param {object} options - Configuration options
   */
  constructor(options = {}) {
    this.featureFlags = options.featureFlags || FEATURE_FLAGS;
  }

  /**
   * Convert internal prompt to A2A Message
   *
   * @param {string|object} prompt - Internal prompt (string or object)
   * @param {object} options - Conversion options
   * @returns {object} A2A Message
   */
  toA2AMessage(prompt, options = {}) {
    const startTime = Date.now();

    if (!this.featureFlags.a2a_message_wrapper) {
      throw new Error('a2a_message_wrapper feature flag is disabled');
    }

    // Determine role
    const role = options.role || Role.USER;

    // Convert prompt to parts
    let parts;
    if (typeof prompt === 'string') {
      parts = [this.convertTextToPart(prompt)];
    } else if (typeof prompt === 'object' && prompt.parts) {
      // Already has parts
      parts = prompt.parts;
    } else if (typeof prompt === 'object') {
      // Convert object to data part
      parts = [{ data: prompt }];
    } else {
      throw new Error('Invalid prompt: must be string or object');
    }

    // Build A2A Message
    const message = {
      messageId: options.messageId || `msg-${randomUUID()}`,
      role,
      parts,
      metadata: options.metadata || {},
    };

    // Add optional fields
    if (options.contextId) {
      message.contextId = options.contextId;
    }
    if (options.taskId) {
      message.taskId = options.taskId;
    }

    const duration = Date.now() - startTime;

    console.log(`[Message Wrapper] Converted prompt to A2A Message in ${duration}ms`);

    return message;
  }

  /**
   * Extract prompt from A2A Message
   *
   * @param {object} message - A2A Message
   * @returns {object} Internal prompt format
   */
  fromA2AMessage(message) {
    const startTime = Date.now();

    if (!this.featureFlags.a2a_message_wrapper) {
      throw new Error('a2a_message_wrapper feature flag is disabled');
    }

    // Validate message
    if (!message || !message.parts || !Array.isArray(message.parts)) {
      throw new Error('Invalid A2A Message: parts array required');
    }

    // Extract text content from parts
    const textContent = this.convertPartsToText(message.parts);

    // Extract data from parts
    const dataParts = message.parts.filter(p => p.data);

    // Extract files from parts
    const fileParts = message.parts.filter(p => p.file);

    // Build internal format
    const prompt = {
      messageId: message.messageId,
      contextId: message.contextId,
      taskId: message.taskId,
      role: message.role === Role.USER ? 'user' : 'agent',
      content: textContent,
      data: dataParts.length > 0 ? dataParts.map(p => p.data) : undefined,
      files: fileParts.length > 0 ? fileParts.map(p => p.file) : undefined,
      metadata: message.metadata || {},
    };

    const duration = Date.now() - startTime;

    console.log(`[Message Wrapper] Extracted prompt from A2A Message in ${duration}ms`);

    return prompt;
  }

  /**
   * Convert text to A2A TextPart
   *
   * @param {string} text - Text content
   * @returns {object} A2A TextPart
   */
  convertTextToPart(text) {
    if (typeof text !== 'string') {
      throw new Error('Text must be a string');
    }

    return { text };
  }

  /**
   * Convert A2A Parts to text
   *
   * @param {Array} parts - A2A Parts
   * @returns {string} Combined text content
   */
  convertPartsToText(parts) {
    if (!Array.isArray(parts)) {
      throw new Error('Parts must be an array');
    }

    return parts
      .filter(p => p.text)
      .map(p => p.text)
      .join('\n\n');
  }

  /**
   * Convert file to A2A FilePart
   *
   * @param {object} file - File object
   * @returns {object} A2A FilePart
   */
  convertFileToPart(file) {
    if (!file || !file.name) {
      throw new Error('File must have a name');
    }

    const filePart = {
      file: {
        name: file.name,
        mime_type: file.mimeType || file.mime_type || 'application/octet-stream',
      },
    };

    // Add URI or bytes
    if (file.uri) {
      filePart.file.uri = file.uri;
    } else if (file.bytes) {
      filePart.file.bytes = file.bytes;
    }

    return filePart;
  }

  /**
   * Convert data to A2A DataPart
   *
   * @param {object} data - JSON data
   * @returns {object} A2A DataPart
   */
  convertDataToPart(data) {
    if (typeof data !== 'object' || data === null) {
      throw new Error('Data must be an object');
    }

    return { data };
  }

  /**
   * Validate A2A Message structure
   *
   * @param {object} message - A2A Message
   * @returns {object} Validation result
   */
  validateMessage(message) {
    const errors = [];

    // Check required fields
    if (!message) {
      return { valid: false, errors: ['Message is null or undefined'] };
    }

    if (!message.role) {
      errors.push('Missing required field: role');
    } else if (!Object.values(Role).includes(message.role)) {
      errors.push(`Invalid role: ${message.role}`);
    }

    if (!message.parts) {
      errors.push('Missing required field: parts');
    } else if (!Array.isArray(message.parts)) {
      errors.push('parts must be an array');
    } else if (message.parts.length === 0) {
      errors.push('parts must have at least one element');
    } else {
      // Validate each part
      for (let i = 0; i < message.parts.length; i++) {
        const part = message.parts[i];
        const hasText = 'text' in part;
        const hasFile = 'file' in part;
        const hasData = 'data' in part;

        if (!hasText && !hasFile && !hasData) {
          errors.push(`Part ${i} must have text, file, or data`);
        }
      }
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Create multi-part message
   *
   * @param {Array} parts - Array of parts (text/file/data)
   * @param {object} options - Message options
   * @returns {object} A2A Message
   */
  createMultiPartMessage(parts, options = {}) {
    if (!Array.isArray(parts)) {
      throw new Error('Parts must be an array');
    }

    // Convert parts to A2A format
    const a2aParts = parts.map(part => {
      if (typeof part === 'string') {
        return this.convertTextToPart(part);
      } else if (part.file) {
        return this.convertFileToPart(part);
      } else if (part.data || typeof part === 'object') {
        return this.convertDataToPart(part.data || part);
      } else {
        throw new Error('Invalid part type');
      }
    });

    return this.toA2AMessage({ parts: a2aParts }, options);
  }

export class PushNotificationHandler {
  /**
   * @param {object} options - Configuration options
   */
  constructor(options = {}) {
    this.featureFlags = options.featureFlags || {
      push_notifications: process.env.PUSH_NOTIFICATIONS === 'true' || false,
    };
    this.webhookSecret = options.webhookSecret || DEFAULT_WEBHOOK_SECRET;
    this.pushConfigs = pushConfigs;
    this.deliveryLog = deliveryLog;
  }

  /**
   * Configure push notification for task
   *
   * @param {string} taskId - Task ID
   * @param {string} callbackUrl - Webhook callback URL
   * @param {object} options - Configuration options
   * @returns {object} Push notification configuration
   */
  configurePushNotification(taskId, callbackUrl, options = {}) {
    const enabled =
      this.featureFlags.isEnabled?.('push_notifications') ?? this.featureFlags.push_notifications;
    if (!enabled) {
      throw new Error('push_notifications feature flag is disabled');
    }

    if (!taskId) {
      throw new Error('taskId is required');
    }

    if (!callbackUrl) {
      throw new Error('callbackUrl is required');
    }

    // Validate callback URL
    try {
      new URL(callbackUrl);
    } catch (error) {
      throw new Error(`Invalid callbackUrl: ${error.message}`);
    }

    // Create configuration
    const config = {
      task_id: taskId,
      callback_url: callbackUrl,
      secret: options.secret || this.webhookSecret,
      events: options.events || ['task_status_update', 'task_artifact_update'],
      created_at: new Date().toISOString(),
      delivery_count: 0,
      last_delivery_at: null,
    };

    // Store configuration
    this.pushConfigs.set(taskId, config);

    console.log(`[Push Notifications] Configured for task ${taskId} → ${callbackUrl}`);

    return config;
  }

  /**
   * Handle incoming push notification webhook
   *
   * @param {object} webhook - Webhook payload
   * @param {object} options - Handler options
   * @returns {object} Handler result
   */
  handlePushNotification(webhook, options = {}) {
    const startTime = Date.now();

    const enabled =
      this.featureFlags.isEnabled?.('push_notifications') ?? this.featureFlags.push_notifications;
    if (!enabled) {
      throw new Error('push_notifications feature flag is disabled');
    }

    // Validate webhook structure
    const validation = this.validateWebhookPayload(webhook);
    if (!validation.valid) {
      throw new Error(`Invalid webhook payload: ${validation.errors.join(', ')}`);
    }

    // Validate signature if provided
    if (options.signature) {
      const signatureValid = this.validateWebhookSignature(
        webhook,
        options.signature,
        options.secret
      );

      if (!signatureValid) {
        throw new Error('Invalid webhook signature');
      }
    }

    // Process webhook
    const result = {
      webhook_id: webhook.webhook_id || `webhook-${randomUUID()}`,
      task_id: webhook.task_id,
      event_type: webhook.event_type,
      received_at: new Date().toISOString(),
      processing_time_ms: 0,
    };

    // Execute webhook handlers (placeholder for now)
    // In production, this would trigger callbacks, update state, etc.

    result.processing_time_ms = Date.now() - startTime;

    console.log(
      `[Push Notifications] Handled ${webhook.event_type} for task ${webhook.task_id} (${result.processing_time_ms}ms)`
    );

    return result;
  }

  /**
   * Validate webhook signature using HMAC-SHA256
   *
   * @param {object} webhook - Webhook payload
   * @param {string} signature - Provided signature
   * @param {string} secret - Webhook secret
   * @returns {boolean} True if valid
   */
  validateWebhookSignature(webhook, signature, secret = null) {
    // Validate signature parameter
    if (!signature || typeof signature !== 'string') {
      return false;
    }

    const webhookSecret = secret || this.webhookSecret;

    // Validate webhook secret is configured
    if (!webhookSecret) {
      throw new Error(
        'Webhook secret not configured - set WEBHOOK_SECRET env var or pass secret option'
      );
    }

    // Compute expected signature
    const payload = JSON.stringify(webhook);
    const expectedSignature = crypto
      .createHmac('sha256', webhookSecret)
      .update(payload)
      .digest('hex');

    // Check signature lengths match before timingSafeEqual (prevents throw on mismatch)
    if (signature.length !== expectedSignature.length) {
      return false;
    }

    // Constant-time comparison to prevent timing attacks
    try {
      return crypto.timingSafeEqual(
        Buffer.from(signature, 'utf-8'),
        Buffer.from(expectedSignature, 'utf-8')
      );
    } catch {
      return false;
    }
  }

  /**
   * Generate webhook signature
   *
   * @param {object} webhook - Webhook payload
   * @param {string} secret - Webhook secret
   * @returns {string} HMAC-SHA256 signature
   */
  generateWebhookSignature(webhook, secret = null) {
    const webhookSecret = secret || this.webhookSecret;
    const payload = JSON.stringify(webhook);

    return crypto.createHmac('sha256', webhookSecret).update(payload).digest('hex');
  }

  /**
   * Send push notification to callback URL
   *
   * @param {string} taskId - Task ID
   * @param {object} event - Event data
   * @returns {Promise<object>} Delivery result
   */
  async sendPushNotification(taskId, event) {
    const startTime = Date.now();

    const config = this.pushConfigs.get(taskId);
    if (!config) {
      throw new Error(`No push notification configured for task ${taskId}`);
    }

    // Filter by event type
    if (config.events && !config.events.includes(event.event_type)) {
      console.log(
        `[Push Notifications] Event ${event.event_type} not in configured events for task ${taskId}`
      );
      return { skipped: true, reason: 'event_type_filtered' };
    }

    // Build webhook payload
    const webhook = {
      webhook_id: `webhook-${randomUUID()}`,
      task_id: taskId,
      event_type: event.event_type,
      timestamp: new Date().toISOString(),
      data: event.data || {},
    };

    // Generate signature
    const signature = this.generateWebhookSignature(webhook, config.secret);

    try {
      // Send POST request to callback URL
      const response = await fetch(config.callback_url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Webhook-Signature': signature,
          'X-Webhook-Id': webhook.webhook_id,
        },
        body: JSON.stringify(webhook),
      });

      const duration = Date.now() - startTime;

      const deliveryResult = {
        webhook_id: webhook.webhook_id,
        task_id: taskId,
        callback_url: config.callback_url,
        status: response.ok ? 'success' : 'failed',
        http_status: response.status,
        duration_ms: duration,
        delivered_at: new Date().toISOString(),
      };

      // Update config
      config.delivery_count++;
      config.last_delivery_at = deliveryResult.delivered_at;

      // Log delivery
      this.logDelivery(deliveryResult);

      console.log(
        `[Push Notifications] Delivered ${event.event_type} to ${config.callback_url} (${duration}ms, HTTP ${response.status})`
      );

      return deliveryResult;
    } catch (error) {
      const duration = Date.now() - startTime;

      const deliveryResult = {
        webhook_id: webhook.webhook_id,
        task_id: taskId,
        callback_url: config.callback_url,
        status: 'error',
        error: error.message,
        duration_ms: duration,
        delivered_at: new Date().toISOString(),
      };

      // Log delivery error
      this.logDelivery(deliveryResult);

      console.error(`[Push Notifications] Failed to deliver to ${config.callback_url}:`, error);

      throw new Error(`Push notification delivery failed: ${error.message}`);
    }
  }

  /**
   * Validate webhook payload structure
   *
   * @param {object} webhook - Webhook payload
   * @returns {object} Validation result
   */
  validateWebhookPayload(webhook) {
    const errors = [];

    if (!webhook) {
      return { valid: false, errors: ['Webhook is null or undefined'] };
    }

    // Required fields
    if (!webhook.task_id) {
      errors.push('Missing required field: task_id');
    }

    if (!webhook.event_type) {
      errors.push('Missing required field: event_type');
    }

    if (!webhook.timestamp) {
      errors.push('Missing required field: timestamp');
    }

    return { valid: errors.length === 0, errors };
  }

  /**
   * Log webhook delivery attempt
   *
   * @param {object} deliveryResult - Delivery result
   */
  logDelivery(deliveryResult) {
    this.deliveryLog.push(deliveryResult);

    // Trim log if too large
    if (this.deliveryLog.length > MAX_LOG_SIZE) {
      this.deliveryLog.shift();
    }
  }

  /**
   * Get delivery log for task
   *
   * @param {string} taskId - Task ID
   * @returns {Array} Delivery log entries
   */
  getDeliveryLog(taskId) {
    return this.deliveryLog.filter(entry => entry.task_id === taskId);
  }

  /**
   * Get delivery statistics
   *
   * @param {string} taskId - Task ID (optional)
   * @returns {object} Delivery stats
   */
  getDeliveryStats(taskId = null) {
    let entries = this.deliveryLog;

    if (taskId) {
      entries = entries.filter(e => e.task_id === taskId);
    }

    const total = entries.length;
    const successful = entries.filter(e => e.status === 'success').length;
    const failed = entries.filter(e => e.status === 'failed').length;
    const errors = entries.filter(e => e.status === 'error').length;

    return {
      total,
      successful,
      failed,
      errors,
      success_rate: total > 0 ? successful / total : 0,
    };
  }

  /**
   * Remove push notification configuration
   *
   * @param {string} taskId - Task ID
   * @returns {boolean} True if removed
   */
  removePushNotification(taskId) {
    return this.pushConfigs.delete(taskId);
  }

  /**
   * List all configured push notifications
   *
   * @returns {Array} Push notification configs
   */
  listPushNotifications() {
    return Array.from(this.pushConfigs.values());
  }

  /**
   * Clear all push notification configurations
   */
  clearPushNotifications() {
    this.pushConfigs.clear();
  }

  /**
   * Clear delivery log
   */
  clearDeliveryLog() {
    this.deliveryLog.length = 0;
  }

export function resetInstance() {
  instance = null;
  pushConfigs.clear();
  deliveryLog.length = 0;
}

function setupFetchMock() {
