}

export class StreamingHandler {
  /**
   * @param {object} options - Configuration options
   */
  constructor(options = {}) {
    this.featureFlags = options.featureFlags || {
      streaming_support: process.env.STREAMING_SUPPORT === 'true' || false,
    };
    this.activeStreams = activeStreams;
    this.heartbeatInterval = options.heartbeatInterval || HEARTBEAT_INTERVAL_MS;
    this.maxStreamDuration = options.maxStreamDuration || MAX_STREAM_DURATION_MS;
  }

  /**
   * Start streaming message
   *
   * @param {object} message - A2A Message to stream
   * @param {function} onUpdate - Update callback
   * @param {object} options - Streaming options
   * @returns {object} Stream context
   */
  startStreamingMessage(message, onUpdate, options = {}) {
    const startTime = Date.now();

    const enabled =
      this.featureFlags.isEnabled?.('streaming_support') ?? this.featureFlags.streaming_support;
    if (!enabled) {
      throw new Error('streaming_support feature flag is disabled');
    }

    if (!message) {
      throw new Error('message is required');
    }

    if (typeof onUpdate !== 'function') {
      throw new Error('onUpdate must be a function');
    }

    // Generate stream ID
    const streamId = options.streamId || `stream-${randomUUID()}`;

    // Create event emitter for stream
    const emitter = new EventEmitter();

    // Create stream context
    const streamContext = {
      stream_id: streamId,
      message_id: message.messageId,
      task_id: message.taskId,
      started_at: new Date().toISOString(),
      event_count: 0,
      last_event_at: null,
      status: 'active',
      emitter,
      onUpdate,
    };

    // Store stream
    this.activeStreams.set(streamId, streamContext);

    // Set up event listener
    emitter.on('event', event => {
      streamContext.event_count++;
      streamContext.last_event_at = new Date().toISOString();

      // Call update callback
      onUpdate(event);
    });

    // Set up heartbeat
    const heartbeatTimer = setInterval(() => {
      if (streamContext.status === 'active') {
        this.sendStreamUpdate(streamId, {
          type: StreamEventType.HEARTBEAT,
          timestamp: new Date().toISOString(),
        });
      }
    }, this.heartbeatInterval);

    streamContext.heartbeatTimer = heartbeatTimer;

    // Set up automatic timeout
    const timeoutTimer = setTimeout(() => {
      console.log(`[Streaming] Stream ${streamId} timed out after ${this.maxStreamDuration}ms`);
      this.closeStream(streamId, 'timeout');
    }, this.maxStreamDuration);

    streamContext.timeoutTimer = timeoutTimer;

    const duration = Date.now() - startTime;

    console.log(
      `[Streaming] Started stream ${streamId} for message ${message.messageId} (${duration}ms)`
    );

    return streamContext;
  }

  /**
   * Send stream update event
   *
   * @param {string} streamId - Stream ID
   * @param {object} event - Event data
   * @returns {boolean} True if sent
   */
  sendStreamUpdate(streamId, event) {
    const stream = this.activeStreams.get(streamId);

    if (!stream) {
      console.warn(`[Streaming] Stream ${streamId} not found`);
      return false;
    }

    if (stream.status !== 'active') {
      console.warn(`[Streaming] Stream ${streamId} is not active (${stream.status})`);
      return false;
    }

    // Validate event
    if (!event.type) {
      throw new Error('Event type is required');
    }

    // Add timestamp if not present
    if (!event.timestamp) {
      event.timestamp = new Date().toISOString();
    }

    // Add stream metadata
    event.stream_id = streamId;
    event.event_id = `event-${randomUUID()}`;

    // Emit event
    stream.emitter.emit('event', event);

    // console.log(`[Streaming] Sent ${event.type} to stream ${streamId}`);

    return true;
  }

  /**
   * Close stream
   *
   * @param {string} streamId - Stream ID
   * @param {string} reason - Close reason
   * @returns {boolean} True if closed
   */
  closeStream(streamId, reason = 'complete') {
    const stream = this.activeStreams.get(streamId);

    if (!stream) {
      console.warn(`[Streaming] Stream ${streamId} not found`);
      return false;
    }

    // Send completion event
    this.sendStreamUpdate(streamId, {
      type: StreamEventType.COMPLETE,
      reason,
      timestamp: new Date().toISOString(),
    });

    // Update status
    stream.status = 'closed';
    stream.closed_at = new Date().toISOString();

    // Clear timers
    if (stream.heartbeatTimer) {
      clearInterval(stream.heartbeatTimer);
    }

    if (stream.timeoutTimer) {
      clearTimeout(stream.timeoutTimer);
    }

    // Remove all listeners
    stream.emitter.removeAllListeners();

    // Remove from active streams
    this.activeStreams.delete(streamId);

    console.log(`[Streaming] Closed stream ${streamId} (reason: ${reason})`);

    return true;
  }

  /**
   * Get stream context
   *
   * @param {string} streamId - Stream ID
   * @returns {object|null} Stream context
   */
  getStream(streamId) {
    return this.activeStreams.get(streamId) || null;
  }

  /**
   * List active streams
   *
   * @param {object} filters - Filter options
   * @returns {Array} Active streams
   */
  listActiveStreams(filters = {}) {
    let streams = Array.from(this.activeStreams.values()).filter(s => s.status === 'active');

    // Filter by task ID
    if (filters.task_id) {
      streams = streams.filter(s => s.task_id === filters.task_id);
    }

    // Apply limit
    if (filters.limit) {
      streams = streams.slice(0, filters.limit);
    }

    return streams;
  }

  /**
   * Get stream statistics
   *
   * @param {string} streamId - Stream ID (optional)
   * @returns {object} Stream stats
   */
  getStreamStats(streamId = null) {
    if (streamId) {
      const stream = this.activeStreams.get(streamId);
      if (!stream) {
        throw new Error(`Stream not found: ${streamId}`);
      }

      const now = Date.now();
      const startTime = new Date(stream.started_at).getTime();
      const duration = now - startTime;

      return {
        stream_id: streamId,
        status: stream.status,
        event_count: stream.event_count,
        duration_ms: duration,
        started_at: stream.started_at,
        last_event_at: stream.last_event_at,
        closed_at: stream.closed_at,
      };
    }

    // Global stats
    const allStreams = Array.from(this.activeStreams.values());
    const activeCount = allStreams.filter(s => s.status === 'active').length;
    const totalEvents = allStreams.reduce((sum, s) => sum + s.event_count, 0);

    return {
      total_streams: this.activeStreams.size,
      active_streams: activeCount,
      total_events: totalEvents,
      average_events_per_stream:
        this.activeStreams.size > 0 ? totalEvents / this.activeStreams.size : 0,
    };
  }

  /**
   * Send task status update event
   *
   * @param {string} streamId - Stream ID
   * @param {object} task - Task object
   * @returns {boolean} True if sent
   */
  sendTaskStatusUpdate(streamId, task) {
    return this.sendStreamUpdate(streamId, {
      type: StreamEventType.TASK_STATUS_UPDATE,
      task: {
        id: task.id,
        state: task.state,
        updated_at: task.updated_at,
      },
    });
  }

  /**
   * Send task artifact update event
   *
   * @param {string} streamId - Stream ID
   * @param {object} task - Task object
   * @param {object} artifact - Artifact object
   * @returns {boolean} True if sent
   */
  sendTaskArtifactUpdate(streamId, task, artifact) {
    return this.sendStreamUpdate(streamId, {
      type: StreamEventType.TASK_ARTIFACT_UPDATE,
      task: {
        id: task.id,
        artifacts: task.artifacts,
      },
      artifact,
    });
  }

  /**
   * Send task message event
   *
   * @param {string} streamId - Stream ID
   * @param {object} message - A2A Message
   * @returns {boolean} True if sent
   */
  sendTaskMessage(streamId, message) {
    return this.sendStreamUpdate(streamId, {
      type: StreamEventType.TASK_MESSAGE,
      message,
    });
  }

  /**
   * Send error event
   *
   * @param {string} streamId - Stream ID
   * @param {object} error - Error object
   * @returns {boolean} True if sent
   */
  sendError(streamId, error) {
    return this.sendStreamUpdate(streamId, {
      type: StreamEventType.ERROR,
      error: {
        message: error.message,
        code: error.code,
        details: error.details,
      },
    });
  }

  /**
   * Clear all streams (for testing)
   */
  clearStreams() {
    // Close all active streams
    for (const streamId of this.activeStreams.keys()) {
      this.closeStream(streamId, 'clear');
    }

    this.activeStreams.clear();
  }

export function resetInstance() {
  if (instance) {
    instance.clearStreams();
  }
  instance = null;
  activeStreams.clear();
}

export class TaskStateManager {
  /**
   * @param {object} options - Configuration options
   */
  constructor(options = {}) {
    this.tasks = new Map(); // In-memory task storage
    this.stateHistory = new Map(); // Task state history
    this.featureFlags = options.featureFlags || FEATURE_FLAGS;
  }

  /**
   * Create a new task
   *
   * @param {object} message - A2A Message
   * @param {object} options - Task options
   * @returns {object} Created task
   */
  createTask(message, options = {}) {
    const startTime = Date.now();

    if (!this.featureFlags.task_state_manager) {
      throw new Error('task_state_manager feature flag is disabled');
    }

    // Generate task ID
    const taskId = options.taskId || `task-${randomUUID()}`;

    // Get session ID
    const sessionId = options.sessionId || message.contextId || `session-${randomUUID()}`;

    // Create task object
    const task = {
      id: taskId,
      session_id: sessionId,
      state: TaskState.SUBMITTED,
      messages: [message],
      artifacts: [],
      metadata: options.metadata || {},
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };

    // Store task
    this.tasks.set(taskId, task);

    // Initialize state history
    this.stateHistory.set(taskId, [
      {
        from_state: null,
        to_state: TaskState.SUBMITTED,
        reason: 'Task created',
        timestamp: task.created_at,
      },
    ]);

    const duration = Date.now() - startTime;

    console.log(`[Task State Manager] Created task ${taskId} in ${duration}ms`);

    return task;
  }

  /**
   * Transition task to new state
   *
   * @param {string} taskId - Task ID
   * @param {string} newState - New state
   * @param {string} reason - Reason for transition
   * @returns {object} Updated task
   */
  transitionState(taskId, newState, reason = '') {
    const startTime = Date.now();

    if (!this.featureFlags.task_state_manager) {
      throw new Error('task_state_manager feature flag is disabled');
    }

    // Get task
    const task = this.tasks.get(taskId);
    if (!task) {
      throw new Error(`Task not found: ${taskId}`);
    }

    // Get current state
    const currentState = task.state;

    // Validate transition
    if (!this.validateTransition(currentState, newState)) {
      throw new Error(
        `Invalid transition: ${currentState} → ${newState}. ` +
          `Valid transitions from ${currentState}: ${VALID_TRANSITIONS[currentState]?.join(', ') || 'none (terminal state)'}`
      );
    }

    // Update task state
    task.state = newState;
    task.updated_at = new Date().toISOString();

    // Add to state history
    const history = this.stateHistory.get(taskId) || [];
    history.push({
      from_state: currentState,
      to_state: newState,
      reason,
      timestamp: task.updated_at,
    });
    this.stateHistory.set(taskId, history);

    // Mark completion time for terminal states
    if (this.isTerminalState(newState)) {
      task.completed_at = task.updated_at;
    }

    const duration = Date.now() - startTime;

    console.log(
      `[Task State Manager] Transitioned ${taskId} from ${currentState} to ${newState} in ${duration}ms`
    );

    return task;
  }

  /**
   * Validate state transition
   *
   * @param {string} fromState - Current state
   * @param {string} toState - Target state
   * @returns {boolean} True if valid
   */
  validateTransition(fromState, toState) {
    // Check if transition is allowed
    const validTransitions = VALID_TRANSITIONS[fromState];

    if (!validTransitions) {
      return false; // Unknown state
    }

    return validTransitions.includes(toState);
  }

  /**
   * Check if state is terminal
   *
   * @param {string} state - Task state
   * @returns {boolean} True if terminal
   */
  isTerminalState(state) {
    return TERMINAL_STATES.includes(state);
  }

  /**
   * Get task by ID
   *
   * @param {string} taskId - Task ID
   * @returns {object|null} Task or null if not found
   */
  getTask(taskId) {
    return this.tasks.get(taskId) || null;
  }

  /**
   * Get state history for task
   *
   * @param {string} taskId - Task ID
   * @returns {Array} State history
   */
  getStateHistory(taskId) {
    return this.stateHistory.get(taskId) || [];
  }

  /**
   * Add message to task
   *
   * @param {string} taskId - Task ID
   * @param {object} message - A2A Message
   * @returns {object} Updated task
   */
  addMessage(taskId, message) {
    const task = this.tasks.get(taskId);
    if (!task) {
      throw new Error(`Task not found: ${taskId}`);
    }

    task.messages.push(message);
    task.updated_at = new Date().toISOString();

    return task;
  }

  /**
   * Add artifact to task
   *
   * @param {string} taskId - Task ID
   * @param {object} artifact - Task artifact
   * @returns {object} Updated task
   */
  addArtifact(taskId, artifact) {
    const task = this.tasks.get(taskId);
    if (!task) {
      throw new Error(`Task not found: ${taskId}`);
    }

    task.artifacts.push(artifact);
    task.updated_at = new Date().toISOString();

    return task;
  }

  /**
   * Update task metadata
   *
   * @param {string} taskId - Task ID
   * @param {object} metadata - Metadata to merge
   * @returns {object} Updated task
   */
  updateMetadata(taskId, metadata) {
    const task = this.tasks.get(taskId);
    if (!task) {
      throw new Error(`Task not found: ${taskId}`);
    }

    task.metadata = { ...task.metadata, ...metadata };
    task.updated_at = new Date().toISOString();

    return task;
  }

  /**
   * List tasks by session
   *
   * @param {string} sessionId - Session ID
   * @param {object} filters - Filter options
   * @returns {Array} Tasks
   */
  listTasks(sessionId, filters = {}) {
    let tasks = Array.from(this.tasks.values()).filter(t => t.session_id === sessionId);

    // Apply state filter
    if (filters.state) {
      tasks = tasks.filter(t => t.state === filters.state);
    }

    // Apply limit
    if (filters.limit) {
      tasks = tasks.slice(0, filters.limit);
    }

    return tasks;
  }

  /**
   * Cancel task
   *
   * @param {string} taskId - Task ID
   * @param {string} reason - Cancellation reason
   * @returns {object} Updated task
   */
  cancelTask(taskId, reason = 'Task cancelled') {
    return this.transitionState(taskId, TaskState.CANCELLED, reason);
  }

  /**
   * Get task status summary
   *
   * @param {string} taskId - Task ID
   * @returns {object} Status summary
   */
  getTaskStatus(taskId) {
    const task = this.getTask(taskId);
    if (!task) {
      throw new Error(`Task not found: ${taskId}`);
    }

    const history = this.getStateHistory(taskId);

    return {
      task_id: taskId,
      state: task.state,
      is_terminal: this.isTerminalState(task.state),
      created_at: task.created_at,
      updated_at: task.updated_at,
      completed_at: task.completed_at,
      message_count: task.messages.length,
      artifact_count: task.artifacts.length,
      state_changes: history.length,
    };
  }

  /**
   * Get all valid transitions from current state
   *
   * @param {string} taskId - Task ID
   * @returns {Array} Valid next states
   */
  getValidTransitions(taskId) {
    const task = this.getTask(taskId);
    if (!task) {
      throw new Error(`Task not found: ${taskId}`);
    }

    return VALID_TRANSITIONS[task.state] || [];
  }

  /**
   * Clear all tasks (for testing)
   */
  clear() {
    this.tasks.clear();
    this.stateHistory.clear();
  }

export function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

